const bot = new Bot(TOKEN)
installTgPostLogger(bot)

// ─── getUpdates heartbeat ─────────────────────────────────────────────────
// Tracks the last time getUpdates completed (success OR error). Used by
// the poll health check as a secondary stall signal: if getMe succeeds but
// getUpdates hasn't responded in a while, the grammy runner loop is frozen
// without the network being down (2026-06-30: clerk/klanker deaf for 2h
// after a single timeout — getMe stayed green so the getMe-only check
// never fired). Initialized to now so the first health-check interval
// doesn't false-positive before the runner makes its first poll.
let lastGetUpdatesHeartbeatMs = Date.now()
bot.api.config.use(async (prev, method, payload, signal) => {
  try {
    const result = await prev(method, payload, signal)
    if (method === 'getUpdates') lastGetUpdatesHeartbeatMs = Date.now()
    return result
  } catch (err) {
    if (method === 'getUpdates') lastGetUpdatesHeartbeatMs = Date.now()
    throw err
  }
})

const GRAMMY_VERSION: string = (() => {
  try {
    const raw = readFileSync(new URL('../../node_modules/grammy/package.json', import.meta.url), 'utf8')
    return (JSON.parse(raw) as { version: string }).version ?? 'unknown'
  } catch {
    return 'unknown'
  }
})()

// ─── sendChecklist / editMessageChecklist boot probes ─────────────────────
// grammY 1.x exposes new Telegram Bot API methods via bot.api.raw before the
// typed wrapper is generated. We probe for availability at boot so callers
// can detect degraded mode gracefully instead of throwing at call time.
const _rawSendChecklist = (bot.api.raw as unknown as Record<string, unknown>).sendChecklist
const _rawEditMessageChecklist = (bot.api.raw as unknown as Record<string, unknown>).editMessageChecklist

/** True when the connected Telegram Bot API supports native checklists. */
const CHECKLIST_API_AVAILABLE =
  typeof _rawSendChecklist === 'function' &&
  typeof _rawEditMessageChecklist === 'function'

if (!CHECKLIST_API_AVAILABLE) {
  process.stderr.write(
    `telegram gateway: sendChecklist / editMessageChecklist not available in this grammY/Bot API version (${GRAMMY_VERSION}) — checklist tools will error gracefully\n`,
  )
}

/**
 * Send a native Telegram checklist message.
 * Wraps bot.api.raw.sendChecklist with string→number coercion (chat_id) and
 * a 30-task cap enforced before the API call.
 */
async function rawSendChecklist(args: {
  chat_id: string
  title: string
  tasks: Array<{ text: string; done?: boolean }>
  message_thread_id?: number
  reply_to_message_id?: number
  protect_content?: boolean
}): Promise<{ message_id: number }> {
  if (!CHECKLIST_API_AVAILABLE) {
    throw new Error('sendChecklist is not available in this grammY/Telegram Bot API version')
  }
  const MAX_TASKS = 30
  if (args.tasks.length > MAX_TASKS) {
    throw new Error(`checklist exceeds ${MAX_TASKS}-task limit (got ${args.tasks.length})`)
  }
  const result = await (_rawSendChecklist as (p: Record<string, unknown>) => Promise<{ message_id: number }>)({
    chat_id: Number(args.chat_id),
    title: args.title,
    tasks: args.tasks.map(t => ({ text: t.text, ...(t.done != null ? { is_completed: t.done } : {}) })),
    ...(args.message_thread_id != null ? { message_thread_id: args.message_thread_id } : {}),
    ...(args.reply_to_message_id != null ? { reply_to_message_id: args.reply_to_message_id } : {}),
    ...(args.protect_content === true ? { protect_content: true } : {}),
  })
  return { message_id: result.message_id }
}

/**
 * Edit (patch) an existing Telegram checklist message.
 * Supports updating title, adding/removing tasks, and marking tasks done/undone.
 * Task objects with an `id` field target existing tasks; those without are added.
 */
async function rawEditMessageChecklist(args: {
  chat_id: string
  message_id: string
  title?: string
  tasks?: Array<{ id?: string; text?: string; done?: boolean }>
}): Promise<void> {
  if (!CHECKLIST_API_AVAILABLE) {
    throw new Error('editMessageChecklist is not available in this grammY/Telegram Bot API version')
  }
  await (_rawEditMessageChecklist as (p: Record<string, unknown>) => Promise<unknown>)({
    chat_id: Number(args.chat_id),
    message_id: Number(args.message_id),
    ...(args.title != null ? { title: args.title } : {}),
    ...(args.tasks != null
      ? {
          tasks: args.tasks.map(t => ({
            ...(t.id != null ? { id: Number(t.id) } : {}),
            ...(t.text != null ? { text: t.text } : {}),
            ...(t.done != null ? { is_completed: t.done } : {}),
          })),
        }
      : {}),
  })
}

const chatLock = createChatLock()
const lockedBot = chatLock.wrapBot({ api: bot.api as unknown as Record<string, unknown> }) as unknown as typeof bot
let botUsername = ''

// ─── Access control ───────────────────────────────────────────────────────

type PendingEntry = {
  senderId: string
  chatId: string
  createdAt: number
  expiresAt: number
  replies: number
}

type GroupPolicy = {
  requireMention: boolean
  allowFrom: string[]
}

type Access = {
  dmPolicy: 'pairing' | 'allowlist' | 'disabled'
  allowFrom: string[]
  groups: Record<string, GroupPolicy>
  pending: Record<string, PendingEntry>
  mentionPatterns?: string[]
  ackReaction?: string
  replyToMode?: 'off' | 'first' | 'all'
  textChunkLimit?: number
  chunkMode?: 'length' | 'newline'
  parseMode?: 'html' | 'markdownv2' | 'text'
  disableLinkPreview?: boolean
  coalescingGapMs?: number
  /** A2: max media attachments folded into one coalesced turn. Default 10
   *  (a full Telegram album / forwarded burst arrives as one turn). Set 1 to
   *  restore single-attachment behaviour. Projected from
   *  channels.telegram.coalesce.max_attachments by scaffold. */
  coalesceMaxAttachments?: number
  /** Problem B: when true (the default), a `!` interrupt that lands
   *  mid-tool-call is deferred until the in-flight tool finishes (bounded by
   *  interruptMaxWaitMs) before SIGINT + resume. Set false to fire
   *  synchronously. Projected from channels.telegram.interrupt.safe_boundary. */
  interruptSafeBoundary?: boolean
  /** Upper bound (ms) to wait for a safe boundary before firing a deferred
   *  interrupt anyway. Default 8000. Projected from
   *  channels.telegram.interrupt.max_wait_ms. */
  interruptMaxWaitMs?: number
  statusReactions?: boolean
  historyEnabled?: boolean
  historyRetentionDays?: number
  /** Per-agent sticker aliases for the `send_sticker` MCP tool (#576).
   *  Operator declares a name → file_id map under telegram.stickers
   *  in switchroom.yaml; reconcile writes the resolved map into
   *  access.json so the gateway has it without re-reading config. */
  stickers?: Record<string, string>
  /** Voice-in transcription config (#578 spike). When `enabled` is
   *  true and provider is 'openai', inbound voice/audio messages are
   *  downloaded and transcribed via Whisper, then surface as the
   *  user's inbound text. The provider API key is a `vault:` reference
   *  (`api_key`, default `vault:openai/api-key`) resolved through the
   *  vault broker at use-time — never read from a plaintext file. Off by
   *  default. */
  voice_in?: {
    enabled?: boolean
    provider?: 'openai'
    language?: string
    api_key?: string
  }
  /** Outbound spoken replies via TTS (PR-C2). When enabled, the agent's
   *  text reply is synthesized into an OGG/Opus voice note and sent
   *  alongside (or instead of) the text, per `reply_mode`. The 'kokoro'
   *  engine uses the local voice sidecar (POST /tts) and is only active
   *  when the host voice verdict is local (SWITCHROOM_VOICE_ENGINE ===
   *  'local'); 'openai' is an honest-exception cloud path gated on an
   *  `api_key` vault ref. Voice is best-effort and fully non-fatal — any
   *  TTS error falls back to the text reply. ONE voice note per response:
   *  the reply is speech-normalized (markdown/symbols stripped) and, for the
   *  kokoro sidecar, sent in a SINGLE /tts call that returns one concatenated
   *  file. Off by default. */
  voice_out?: {
    enabled?: boolean
    engine?: 'kokoro' | 'openai'
    voice?: string
    reply_mode?: 'voice+text' | 'voice-only' | 'on-demand'
    /** Kokoro-engine playback speed. Clamped to 0.5–2.0; defaults to 1.1
     *  when voice_out is enabled but speed is unset (the fleet default —
     *  slightly brisker than neutral). Ignored by the OpenAI path. */
    speed?: number
    /** OpenAI-engine only: per-voice-note chunk size (default 600) used to
     *  split a long reply across sequential notes, since OpenAI's TTS input
     *  has a hard cap. Ignored by the kokoro path, which sends the whole
     *  reply in one call (the sidecar owns length + concatenation). */
    max_chars?: number
    api_key?: string
  }
  /** Telegraph long-reply publishing (#579). When enabled, replies
   *  above `threshold` chars publish to Telegraph and the agent's
   *  reply becomes a single message linking to the Telegraph URL
   *  (rendered via Telegram's native Instant View). Off by default. */
  telegraph?: {
    enabled?: boolean
    threshold?: number
    short_name?: string
    author_name?: string
  }
}

function defaultAccess(): Access {
  return { dmPolicy: 'pairing', allowFrom: [], groups: {}, pending: {} }
}

// Rich-message wire cap (#2669): the rich path allows 32768 UTF-8 chars.
const MAX_CHUNK_LIMIT = RICH_MESSAGE_MAX_CHARS
const MAX_ATTACHMENT_BYTES = 50 * 1024 * 1024

function assertSendable(f: string): void {
  // Reject non-absolute paths to prevent relative path traversal
  if (!f.startsWith('/')) {
    throw new Error(`refusing to send file with relative path: ${f}`)
  }
  let real: string, stateReal: string
  try {
    real = realpathSync(f)
    stateReal = realpathSync(STATE_DIR)
  } catch {
    // Fail closed: if we can't resolve the real path (broken symlink, no
    // permission, etc.), refuse to send. The old behavior silently allowed
    // the file through on resolution failure.
    throw new Error(`refusing to send file — cannot resolve real path: ${f}`)
  }
  // Block sending any channel state files (access.json, .env, history.db, etc.)
  // except files in the inbox directory (which are user-downloaded attachments).
  const inbox = join(stateReal, 'inbox')
  if (real.startsWith(stateReal + sep) && !real.startsWith(inbox + sep)) {
    throw new Error(`refusing to send channel state: ${f}`)
  }
  // Block known sensitive paths
  const SENSITIVE_PREFIXES = ['/proc/', '/sys/']
  const SENSITIVE_EXACT = ['/etc/shadow', '/etc/gshadow']
  for (const prefix of SENSITIVE_PREFIXES) {
    if (real.startsWith(prefix)) {
      throw new Error(`refusing to send system file: ${f}`)
    }
  }
  for (const exact of SENSITIVE_EXACT) {
    if (real === exact) {
      throw new Error(`refusing to send system file: ${f}`)
    }
  }
}

function readAccessFile(): Access {
  try {
    const raw = readFileSync(ACCESS_FILE, 'utf8')
    const parsed = JSON.parse(raw) as Partial<Access>
    const allowFrom = validateStringArray('allowFrom', parsed.allowFrom ?? [])
    const groups: Record<string, GroupPolicy> = {}
    for (const [chatId, policy] of Object.entries(parsed.groups ?? {})) {
      groups[chatId] = {
        ...policy,
        allowFrom: validateStringArray(`groups.${chatId}.allowFrom`, policy.allowFrom ?? []),
      }
    }
    return {
      dmPolicy: parsed.dmPolicy ?? 'pairing',
      allowFrom,
      groups,
      pending: parsed.pending ?? {},
      mentionPatterns: parsed.mentionPatterns,
      ackReaction: parsed.ackReaction,
      replyToMode: parsed.replyToMode,
      textChunkLimit: parsed.textChunkLimit,
      chunkMode: parsed.chunkMode,
      parseMode: parsed.parseMode,
      disableLinkPreview: parsed.disableLinkPreview,
      coalescingGapMs: parsed.coalescingGapMs,
      coalesceMaxAttachments: parsed.coalesceMaxAttachments,
      interruptSafeBoundary: parsed.interruptSafeBoundary,
      interruptMaxWaitMs: parsed.interruptMaxWaitMs,
      statusReactions: parsed.statusReactions,
      historyEnabled: parsed.historyEnabled,
      historyRetentionDays: parsed.historyRetentionDays,
      // #596: telegram features projected into access.json by scaffold.
      // Without these passthroughs, gateway readers (`access.voice_in`,
      // `access.telegraph`, `access.stickers`) silently see undefined.
      stickers: parsed.stickers,
      voice_in: parsed.voice_in,
      voice_out: parsed.voice_out,
      telegraph: parsed.telegraph,
    }
  } catch (err) {
    if ((err as NodeJS.ErrnoException).code === 'ENOENT') return defaultAccess()
    try { renameSync(ACCESS_FILE, `${ACCESS_FILE}.corrupt-${Date.now()}`) } catch {}
    process.stderr.write(`telegram gateway: access.json is corrupt, moved aside. Starting fresh.\n`)
    return defaultAccess()
  }
}

const BOOT_ACCESS: Access | null = STATIC
  ? (() => {
      const a = readAccessFile()
      if (a.dmPolicy === 'pairing') {
        process.stderr.write('telegram gateway: static mode — dmPolicy "pairing" downgraded to "allowlist"\n')
        a.dmPolicy = 'allowlist'
      }
      a.pending = {}
      return a
    })()
  : null

function loadAccess(): Access {
  return BOOT_ACCESS ?? readAccessFile()
}

function assertAllowedChat(chat_id: string | number): void {
  const id = String(chat_id)
  const access = loadAccess()
  if (access.allowFrom.includes(id)) return
  if (id in access.groups) return
  throw new Error(`chat ${id} is not allowlisted — add via /telegram:access`)
}

function saveAccess(a: Access): void {
  if (STATIC) return
  mkdirSync(STATE_DIR, { recursive: true, mode: 0o700 })
  const tmp = ACCESS_FILE + '.tmp'
  writeFileSync(tmp, JSON.stringify(a, null, 2) + '\n', { mode: 0o600 })
  renameSync(tmp, ACCESS_FILE)
}

function pruneExpired(a: Access): boolean {
  const now = Date.now()
  let changed = false
  for (const [code, p] of Object.entries(a.pending)) {
    if (p.expiresAt < now) {
      delete a.pending[code]
      changed = true
    }
  }
  return changed
}

// ─── History ──────────────────────────────────────────────────────────────
const HISTORY_ACCESS = loadAccess()
const HISTORY_ENABLED = HISTORY_ACCESS.historyEnabled !== false
if (HISTORY_ENABLED) {
  try {
    initHistory(STATE_DIR, HISTORY_ACCESS.historyRetentionDays ?? 30)
    process.stderr.write(`telegram gateway: history capture enabled at ${join(STATE_DIR, 'history.db')}\n`)
  } catch (err) {
    process.stderr.write(`telegram gateway: history init failed (${(err as Error).message}) — capture disabled\n`)
  }
}

// ─── Turn-tracking registry + honest-restart-resume ────────────────────────
// On boot, open the per-agent registry.db and reap any turn that never got an
// ended_at — those were killed mid-flight (operator restart, SIGKILL, OOM,
// hard reboot). The reaper CLASSIFIES each orphan from the on-disk
// turn-active marker's age:
//   - marker older than the hang-watchdog window → 'timeout' (the turn
//     stalled with no tool progress; report it, don't blindly resume).
//   - otherwise → 'restart' (a clean interrupt; resume it).
// Then, if the LATEST turn was interrupted, we build a synthetic resume /
// report inbound and (further down, once the inbound spool exists) inject it
// so the agent wakes on its own and either picks the work back up or tells
// the user why it stopped — no human nudge required.
//
// The classifier MUST read the marker before the boot-cleanup sweep removes
// it (the sweep runs much later, in the bridge-registration path). This block
// runs at module top, so the marker is still present here.
let turnsDb: ReturnType<typeof openTurnsDb> | null = null
// Stashed here; pushed to the spool once it's constructed below. The spool's
// turn_key-keyed dedup makes a re-stash across multiple restarts a no-op.
let bootResumeInbound: { agent: string; msg: InboundMessage } | null = null
try {
  // STATE_DIR is `<agentDir>/telegram` in production. openTurnsDb expects
  // the parent (agent dir) and joins `telegram/registry.db` itself.
  const agentDir = STATE_DIR.endsWith('/telegram')
    ? STATE_DIR.slice(0, -'/telegram'.length)
    : STATE_DIR
  turnsDb = openTurnsDb(agentDir)
  // Apply subagents schema in the same DB. openTurnsDb only applies the turns
  // schema; subagents lives alongside in registry.db. Idempotent — safe on
  // pre-existing DBs (handles the jsonl_agent_id column migration).
  applySubagentsSchema(turnsDb)

  // Read the turn-active marker (the in-flight turn the watchdog tracks)
  // BEFORE classifying — its mtime is "ms since last tool progress" and its
  // payload carries the in-flight turn_key.
  let markerTurnKey: string | null = null
  let markerAgeMs: number | null = null
  try {
    const markerPath = join(STATE_DIR, TURN_ACTIVE_MARKER_FILE)
    if (existsSync(markerPath)) {
      const st = statSync(markerPath)
      markerAgeMs = Date.now() - st.mtimeMs
      try {
        const payload = JSON.parse(readFileSync(markerPath, 'utf8')) as { turnKey?: unknown }
        if (typeof payload.turnKey === 'string' && payload.turnKey.length > 0) {
          markerTurnKey = payload.turnKey
        }
      } catch { /* unreadable/torn marker — age alone still classifies */ }
    }
  } catch { /* stat failure — treat as no marker (plain restart) */ }

  // TURN_HANG_SECS is the watchdog's hang threshold (default 300s); the
  // classifier uses the same signal so "would the watchdog have killed it"
  // is answered identically whether or not the watchdog is live (it's
  // disabled under Docker, but the staleness judgement still holds).
  const hangSecs = Number(process.env.TURN_HANG_SECS)
  const hangThresholdMs = (Number.isFinite(hangSecs) && hangSecs > 0 ? hangSecs : 300) * 1000
  const reasonSnapshot =
    markerAgeMs != null ? JSON.stringify({ idleMs: Math.round(markerAgeMs) }) : null

  const { reaped, timeoutTurnKey } = markOrphanedWithTimeoutClassification(turnsDb, {
    markerTurnKey,
    markerAgeMs,
    hangThresholdMs,
    reasonSnapshot,
  })
  if (reaped > 0) {
    process.stderr.write(
      `telegram gateway: turn-registry boot-reaper stamped ${reaped} orphaned turn(s)` +
      `${timeoutTurnKey ? ` (turnKey=${timeoutTurnKey} as 'timeout', markerAgeMs=${markerAgeMs})` : " as 'restart'"}\n`,
    )
  } else {
    process.stderr.write(`telegram gateway: turn-registry initialized at ${join(agentDir, 'telegram', 'registry.db')}\n`)
  }

  // Build the boot resume/report inbound for the LATEST turn if it was
  // interrupted. selectResumeBuilder owns the resume-vs-report policy.
  const pending = findLatestTurnIfInterrupted(turnsDb)
  const selfAgent = process.env.SWITCHROOM_AGENT_NAME ?? ''
  if (pending != null && selfAgent) {
    // Clean-shutdown gate: suppress auto-resume when the prior shutdown was
    // operator/roll/CLI-initiated (clean). A clean-shutdown marker present and
    // fresh means the agent was asked to stop; the "interrupted" turn was
    // abandoned by that decision. Replaying it on every planned restart wastes
    // subscription quota for no user benefit. Only unclean exits (crash/OOM/
    // unexpected kill) should auto-resume.
    //
    // NOTE: GATEWAY_CLEAN_SHUTDOWN_MARKER_PATH is defined lower in this file
    // (module-init order); we compute the path inline here using the same
    // formula so we can read it at boot-resume time.
    // SWITCHROOM_BOOT_RESUME_ALWAYS=1 is an escape hatch that restores
    // unconditional resume if needed.
    const bootResumeMarkerPath =
      process.env.SWITCHROOM_GATEWAY_CLEAN_SHUTDOWN_MARKER ?? join(STATE_DIR, 'clean-shutdown.json')
    const bootResumeCleanMarker = readCleanShutdownMarker(bootResumeMarkerPath)
    const bootResumeForceAlways = process.env.SWITCHROOM_BOOT_RESUME_ALWAYS === '1'
    const bootResumeSuppressed = shouldSuppressBootResume(bootResumeCleanMarker, Date.now(), {
      forceAlways: bootResumeForceAlways,
    })
    if (bootResumeSuppressed) {
      process.stderr.write(
        `telegram gateway: boot-resume suppressed (clean shutdown` +
        `${bootResumeCleanMarker?.reason ? ` reason=${JSON.stringify(bootResumeCleanMarker.reason)}` : ''}` +
        `) — unclean exits still resume turnKey=${pending.turn_key}\n`,
      )
    } else {
      // 3h staleness failsafe (operator spec, 2026-06-03): never AUTO-resume
      // interrupted work older than RESUME_MAX_AGE_MS — selectResumeBuilder
      // downgrades a stale 'resume' to the passive 'report' so the user is told
      // ("I was working on X ~Nh ago") but nothing replays unprompted. Env
      // override SWITCHROOM_RESUME_MAX_AGE_MS (ms); set very high to disable.
      const RESUME_MAX_AGE_MS = (() => {
        const v = Number(process.env.SWITCHROOM_RESUME_MAX_AGE_MS)
        return Number.isFinite(v) && v > 0 ? v : 10_800_000 // 3h
      })()
      const kind = selectResumeBuilder(pending.ended_via, {
        ageMs: Math.max(0, Date.now() - pending.started_at),
        maxAgeMs: RESUME_MAX_AGE_MS,
      })
      if (kind === 'resume') {
        bootResumeInbound = { agent: selfAgent, msg: buildResumeInterruptedInbound({ turn: pending }) }
      } else if (kind === 'report') {
        // idleMs: this boot's measured marker age if it just classified this
        // turn; otherwise recover it from the persisted interrupt_reason (a
        // later boot, marker already swept); else fall back to total runtime.
        let idleMs = pending.turn_key === timeoutTurnKey && markerAgeMs != null ? markerAgeMs : null
        if (idleMs == null && pending.interrupt_reason) {
          try {
            const parsed = JSON.parse(pending.interrupt_reason) as { idleMs?: unknown }
            if (typeof parsed.idleMs === 'number' && Number.isFinite(parsed.idleMs)) idleMs = parsed.idleMs
          } catch { /* malformed snapshot — fall through */ }
        }
        if (idleMs == null) idleMs = Math.max(0, Date.now() - pending.started_at)
        bootResumeInbound = {
          agent: selfAgent,
          msg: buildResumeWatchdogReportInbound({ turn: pending, idleMs }),
        }
      }
      if (bootResumeInbound != null) {
        process.stderr.write(
          `telegram gateway: boot-resume queued kind=${kind} turnKey=${pending.turn_key} ` +
          `endedVia=${pending.ended_via ?? 'open'} chat=${pending.chat_id}\n`,
        )
      }
    }
  }

  // Diagnostic env file (one-shot, sourced by start.sh) — kept for the
  // wake-audit context. The injected inbound above is the real wake signal;
  // these vars are passive context only.
  const pendingEnvPath = join(agentDir, '.pending-turn.env')
  try {
    if (pending != null) {
      const lines = [
        `SWITCHROOM_PENDING_TURN=true`,
        `SWITCHROOM_PENDING_TURN_KEY=${pending.turn_key}`,
        `SWITCHROOM_PENDING_CHAT_ID=${pending.chat_id}`,
        pending.thread_id != null ? `SWITCHROOM_PENDING_THREAD_ID=${pending.thread_id}` : `SWITCHROOM_PENDING_THREAD_ID=`,
        pending.last_user_msg_id != null ? `SWITCHROOM_PENDING_USER_MSG_ID=${pending.last_user_msg_id}` : `SWITCHROOM_PENDING_USER_MSG_ID=`,
        `SWITCHROOM_PENDING_ENDED_VIA=${pending.ended_via ?? 'unknown'}`,
        `SWITCHROOM_PENDING_STARTED_AT=${pending.started_at}`,
        pending.interrupt_reason != null ? `SWITCHROOM_PENDING_INTERRUPT_REASON=${pending.interrupt_reason}` : `SWITCHROOM_PENDING_INTERRUPT_REASON=`,
      ]
      // Atomic write: tmp + rename. Without this, a crash mid-write
      // (power loss, OOM, panic) leaves a truncated `.pending-turn.env`
      // that start.sh `source`s — partial SWITCHROOM_PENDING_* vars
      // or a malformed line break shell parsing inside the source.
      const pendingEnvTmp = `${pendingEnvPath}.tmp-${process.pid}`
      writeFileSync(pendingEnvTmp, lines.join('\n') + '\n', { mode: 0o600 })
      renameSync(pendingEnvTmp, pendingEnvPath)
      process.stderr.write(`telegram gateway: pending-turn env written to ${pendingEnvPath} turnKey=${pending.turn_key} endedVia=${pending.ended_via ?? 'open'}\n`)
    } else if (existsSync(pendingEnvPath)) {
      rmSync(pendingEnvPath, { force: true })
      process.stderr.write(`telegram gateway: pending-turn env cleared (clean previous shutdown)\n`)
    }
  } catch (err) {
    process.stderr.write(`telegram gateway: pending-turn env write failed (${(err as Error).message})\n`)
  }
} catch (err) {
  process.stderr.write(`telegram gateway: turn-registry init failed (${(err as Error).message}) — turn tracking disabled\n`)
  turnsDb = null
}

/**
 * Resolve the chat/thread a background sub-agent was dispatched from, so
 * its live worker card + handback route back to the originating
 * conversation (group / forum topic) instead of the operator DM.
 *
 * Walks jsonl_agent_id → `subagents.parent_turn_key` →
 * `turns.chat_id`/`thread_id`. Returns null on any miss so the caller
 * keeps its existing `allowFrom[0]` DM fallback — best-effort, never
 * throws out of the worker-card hot path. This restores the chat context
 * the pinned-card fleet used to carry before it was removed in #1122
 * (progressDriver is permanently null, so the old fleet lookup always
 * yielded the DM for a Task dispatched from a group/topic).
 */
function resolveSubagentOriginChat(
  agentId: string,
): { chatId: string; threadId?: number } | null {
  if (turnsDb == null) return null
  try {
    // Transitive walk: a NESTED (depth-2+) worker's own parent_turn_key is
    // NULL by construction (its dispatching context is another sub-agent,
    // not a gateway turn) — resolveSubagentOriginTurnKey follows the
    // parent_agent_id chain to the ancestor row that WAS stamped at
    // main-turn dispatch time, so nested cards + handbacks route to the
    // originating chat/topic instead of falling back to the owner DM.
    const originKey = resolveSubagentOriginTurnKey(turnsDb, agentId)
    if (originKey == null) return null
    const turn = getTurnByKey(turnsDb, originKey)
    if (turn == null || turn.chat_id.length === 0) return null
    const threadNum =
      turn.thread_id != null && turn.thread_id.length > 0
        ? Number(turn.thread_id)
        : NaN
    return {
      chatId: turn.chat_id,
      threadId: Number.isFinite(threadNum) ? threadNum : undefined,
    }
  } catch {
    return null
  }
}

// ─── Periodic history reaper (#1073) ──────────────────────────────────────
// The init-time prune in history.ts only touched the `messages` table.
// `subagents` and `turns` in registry.db grew unbounded — every Agent()
// call and every turn added a row that never expired. The SQLite WAL
// also grew without bound because no path issued a checkpoint.
//
// Strategy:
//   1. At boot, prune both registry tables on the same window as
//      messages (catch-up for long-stopped agents waking up to stale
//      data). Plus a one-shot WAL checkpoint on history.db.
//   2. Every 6h thereafter, re-run the registry reaper + history WAL
//      checkpoint. The window is intentionally coarse — a daily-ish
//      cadence keeps the WAL bounded without thrashing IO on a quiet
//      agent.
//
// Retention selection — same resolveRegistryRetentionDays helper used
// at boot and on every tick, so an operator can change env or
// access.json and the next tick picks it up.
const REGISTRY_REAPER_INTERVAL_MS = 6 * 60 * 60 * 1000
function runHistoryReaperNow(reason: 'boot' | 'periodic'): void {
  const retentionDays = resolveRegistryRetentionDays(HISTORY_ACCESS.historyRetentionDays)
  // Registry reaper: subagents + turns + WAL checkpoint on registry.db.
  if (turnsDb != null) {
    try {
      const result = runRegistryReaper(turnsDb, { retentionDays })
      process.stderr.write(
        `telegram gateway: registry-reaper (${reason}) retentionDays=${retentionDays}`
        + ` subagents.deleted=${result.subagents.deleted} (${result.subagents.batches} batches)`
        + ` turns.deleted=${result.turns.deleted} (${result.turns.batches} batches)`
        + ` wal.checkpoint=${result.walCheckpointed ? 'ok' : 'busy'}\n`,
      )
    } catch (err) {
      process.stderr.write(`telegram gateway: registry-reaper (${reason}) failed: ${(err as Error).message}\n`)
    }
  }
  // History DB extension: on boot, extend the messages init-prune to
  // cover the case where the existing one-shot prune in initHistory()
  // ran with a stale retention value (or didn't run at all on an old
  // DB). On periodic ticks, also prune messages so a multi-month
  // session doesn't slowly outgrow its window. We deliberately reuse
  // the messages-table retention from access.json (`historyRetentionDays`,
  // defaulting to 30) here — the new HISTORY_RETENTION_DAYS env applies
  // to registry tables only, per the issue scope. Messages retention
  // policy is unchanged.
  if (HISTORY_ENABLED) {
    try {
      const messagesRetentionDays = HISTORY_ACCESS.historyRetentionDays ?? 30
      const deleted = pruneMessagesOlderThanDays(messagesRetentionDays)
      const walOk = checkpointHistoryWal()
      if (deleted > 0 || reason === 'boot') {
        process.stderr.write(
          `telegram gateway: history-reaper (${reason}) messagesRetentionDays=${messagesRetentionDays}`
          + ` messages.deleted=${deleted} wal.checkpoint=${walOk ? 'ok' : 'busy'}\n`,
        )
      }
    } catch (err) {
      process.stderr.write(`telegram gateway: history-reaper (${reason}) failed: ${(err as Error).message}\n`)
    }
  }
}
// Run once at boot to catch up long-stopped agents.
runHistoryReaperNow('boot')
// Then every 6h. unref() so the interval doesn't keep the process alive
// past shutdown.
if (!STATIC) {
  setInterval(() => runHistoryReaperNow('periodic'), REGISTRY_REAPER_INTERVAL_MS).unref()
}

// ─── Approval polling ─────────────────────────────────────────────────────
function checkApprovals(): void {
  let files: string[]
  try { files = readdirSync(APPROVED_DIR) } catch { return }
  for (const senderId of files) {
    const file = join(APPROVED_DIR, senderId)
    // allow-raw-bot-api: Paired! sendMessage to DM senderId; no thread_id, cannot trigger THREAD_NOT_FOUND
    void bot.api.sendMessage(senderId, "Paired! Say hi to Claude.").then(
      () => rmSync(file, { force: true }),
      err => {
        process.stderr.write(`telegram gateway: failed to send approval confirm: ${err}\n`)
        rmSync(file, { force: true })
      },
    )
  }
}
if (!STATIC) setInterval(checkApprovals, 5000).unref()
// Idle auto-clear: check wall-clock idle every minute; maybeIdleClear no-ops
// when disabled ('0s'), mid-turn, or already cleared this idle period. The
// `let` state + maybeIdleClear are hoisted/initialized before this fires.
const IDLE_CLEAR_CHECK_MS = Number(process.env.SWITCHROOM_IDLE_CLEAR_CHECK_MS ?? 60_000)
if (!STATIC && IDLE_CLEAR_CHECK_MS > 0) setInterval(maybeIdleClear, IDLE_CLEAR_CHECK_MS).unref()

// ─── Thread / status / stream state ───────────────────────────────────────
const chatThreadMap = new Map<string, number>()
const activeStatusReactions = new Map<string, StatusReactionController>()
const activeReactionMsgIds = new Map<string, { chatId: string; messageId: number }>()
// Component 5 (queued-status UX). When a cross-topic inbound buffers behind
// an in-flight turn in another topic, we post ONE self-updating status into
// the buffered message's OWN topic ("Queued — replying in <other topic>
// first" → "On it — replying now" → deleted when the answer lands). Keyed
// by chatKey(chat_id, bufferedThread). Delete-on-answer: never a dangling
// placeholder. Reaped on answer (executeReply/stream), on turn-flush, and
// in purgeReactionTracking cleanup so an abnormal turn-end can't strand it.
const queuedStatusMsgIds = new Map<string, { chatId: string; threadId: number; messageId: number }>()
// Reactions whose terminal 👍 is deferred because a background sub-agent
// worker was still running when the parent's `turn_end` fired. Painting 👍
// then would read as "done / nothing happening" while the worker keeps
// going. The controller is `hold()`-frozen on a working glyph; the entry
// is promoted to 👍 by `deferredDoneReactions.promote()` (wired to the
// watcher's `onFinish`) when the last worker completes. See
// `reaction-defer.ts` for the promote/purge interaction the unit tests pin.
const deferredDoneReactions = new DeferredDoneReactions<StatusReactionController>({
  countRunningWorkers: () => countRunningWorkers(),
  getActive: (key) => activeStatusReactions.get(key),
  purge: (key) => purgeReactionTracking(key),
})

// #546 — outbound content-dedup window. PR #599 introduced the four read
// sites (`outboundDedup.check` / `.record` in executeReply, executeStreamReply,
// turn-flush) but the declaration was lost in a merge somewhere — every reply
// path threw `outboundDedup is not defined` at runtime, blocking ALL outbound
// from the agent. Restore the module-level singleton here.
const outboundDedup = new OutboundDedupCache()
/**
 * Per-chat cache of `available_reactions` from `getChat`. Populated lazily —
 * the FIRST message in a chat creates a controller without the filter (null
 * = "try all whitelisted variants"); a fire-and-forget probe populates the
 * cache for subsequent messages. Closes #542: when a chat restricts
 * reactions (common in supergroups), Telegram silently rejects intermediate
 * emoji like 🤔 / 👨‍💻 / ⚡ with 400 REACTION_INVALID, the controller's
 * catch logs and continues, and only 👍 lands. With this cache wired in,
 * StatusReactionController.resolveEmoji() falls through to a permitted
 * variant instead of letting the call fail silently.
 *
 * `null` means "no filter / first probe in flight". `Set<string>` means
 * "Telegram returned the explicit list". Empty Set means the chat allows
 * NO reactions (rare; controller's last-resort branch will return null
 * and emits become no-ops, which is correct).
 */
const chatAvailableReactions = new Map<string, Set<string> | null>()
const chatProbesInFlight = new Set<string>()
const activeTurnStartedAt = new Map<string, number>()
// PR3b parallel-turns: tracks turns claude has ACTUALLY been handed
// (set after successful sendToAgent, cleared on turn_end), as opposed
// to activeTurnStartedAt which is set eagerly on inbound receipt to
// stamp the user-visible turn start time. Under fleet-shared and DM
// topologies these are equivalent — every received inbound is delivered.
// Under supergroup-owned (one agent owns the whole supergroup, multiple
// topics share this gateway process), topic B's inbound that arrives
// while topic A is processing gets buffered; without this split, keyB
// stays in activeTurnStartedAt forever (no turn_end ever fires for a
// turn claude never started), so the fleet-wide "claude is idle" gate
// at purgeReactionTracking/releaseTurnBufferGate never re-opens — the
// canonical supergroup-mode deadlock. Fleet gates read claudeBusyKeys;
// per-key reads (status-query metric, wedge detection, etc.) keep
// reading activeTurnStartedAt because they want the receipt timestamp.
const claudeBusyKeys = new Set<string>()

/**
 * #2527 observability: count emoji transitions per status-reaction controller
 * so `turn_no_reply_warn` can report how many reaction changes happened while
 * producing zero text. Keyed by statusKey(chatId, threadId); cleared in
 * purgeReactionTracking alongside the controller itself.
 */
const reactionTransitionCounts = new Map<string, number>()

/**
 * #2527 observability: tracks which (chatId:threadId) keys have already emitted
 * a `turn_reply_timing` event this turn so we only fire it on the FIRST text
 * reply. Cleared in purgeReactionTracking at turn-end alongside the controller.
 */
const firstTextReplyLogged = new Set<string>()

/**
 * Helper: stamp a claudeBusyKeys entry for an inbound about to be
 * handed to claude. Pulls the thread id from the top-level field if
 * present, otherwise falls back to meta.message_thread_id (cron and
 * vault-synthetic inbounds put it there). chatKey canonicalises
 * null/undefined/0 to `_` so callers don't need to think about it.
 */
function markClaudeBusyForInbound(m: {
  chatId: string
  threadId?: number
  meta?: Record<string, string>
}): string {
  let tid: number | null = m.threadId ?? null
  if (tid == null && m.meta?.message_thread_id != null) {
    const n = Number(m.meta.message_thread_id)
    if (Number.isFinite(n)) tid = n
  }
  const key = chatKey(m.chatId, tid)
  claudeBusyKeys.add(key)
  return key
}

// ─── Reliable inbound delivery: deliver-until-acked (the marko drop-wedge) ─
// A delivered inbound is ACKED only by the `enqueue` session-event (claude
// actually started the turn) — NOT by sendToAgent returning true. Until
// acked, the message stays queued; if it didn't land within the timeout it
// stranded in claude's composer, so we re-deliver it. Re-deliver forever
// until acked — never drop (vs the old fire-and-forget that the 300s
// silence-poke swallowed). Kill switch: SWITCHROOM_INBOUND_DELIVERY_CONFIRM=0
// → legacy fire-and-forget. See inbound-delivery-confirm.ts.
const DELIVERY_CONFIRM_ENABLED = process.env.SWITCHROOM_INBOUND_DELIVERY_CONFIRM !== '0'
// How long to wait for claude's `enqueue` ack before treating a delivery as
// stranded and re-delivering. Generous by default — claude acks within ~1s of
// a clean delivery, so 15s won't false-positive on a healthy turn. Tunable
// (env) for tests/forensics; a too-low value re-delivers healthy slow turns
// (duplicate turn), which is why the default is comfortably above ack latency.
const _deliveryTimeoutRaw = process.env.SWITCHROOM_INBOUND_DELIVERY_TIMEOUT_MS
const _deliveryTimeoutParsed =
  _deliveryTimeoutRaw != null && _deliveryTimeoutRaw !== '' ? Number(_deliveryTimeoutRaw) : 15_000
// Clamp to a positive, finite value: a negative / zero / NaN env override would
// make the sweep treat every tracked entry as stranded and re-deliver every
// cycle forever (a self-inflicted re-delivery loop). To disable the feature,
// use SWITCHROOM_INBOUND_DELIVERY_CONFIRM=0, not a degenerate timeout.
const DELIVERY_CONFIRM_TIMEOUT_MS =
  Number.isFinite(_deliveryTimeoutParsed) && _deliveryTimeoutParsed > 0 ? _deliveryTimeoutParsed : 15_000
const DELIVERY_CONFIRM_SWEEP_MS = 5_000
const deliveryQueue = createDeliveryQueue<InboundMessage>()

// ─── Deterministic delivery-obligation ledger (systems-analysis PR2) ──────────
// An inbound is an OBLIGATION (keyed origin_turn_id) that is OPEN at receipt and
// CLOSED only by an observable substantive reply resolving to that origin —
// never the model's words. An open obligation that survives a turn boundary is
// re-presented (bounded) until it closes, so a message the model read but never
// answered (the marko 715 drop) cannot be silently lost. ADDITIVE + flagged: it
// runs ALONGSIDE the existing acks/spool/buffer (PR3 retires the redundant
// pieces). DEFAULT ON (graduated from canary 2026-06-04 after the hang-fix
// (#2152, total-proof), the escalate-grace (#2156, kills the fuzz-found
// over-escalation), and interrupt-cancel (#2157) — proven on marko (supergroup)
// + test-harness for days with 0 false cards). Kill switch:
// SWITCHROOM_OBLIGATION_LEDGER=0 → every hook below is a no-op → zero change.
const OBLIGATION_LEDGER_ENABLED = process.env.SWITCHROOM_OBLIGATION_LEDGER !== '0'
const OBLIGATION_REPRESENT_MAX = 2
// Minimum reply length (chars) the duplicate-represent guard (#2472/#2474) treats
// as "the user was answered". DECOUPLED from the escalate branch's 200-char proxy:
// for the represent guard ANY genuine assistant reply — even a terse "Yes — done."
// — satisfies the obligation, so suppressing the duplicate re-ask must not require
// 200 chars. Default 1 (any non-empty real reply; empty/whitespace rows are
// clamped out inside hasOutboundDeliveredSince). Override via env for tuning. Safe
// because only recordOutbound writes role='assistant' rows — progress-card edits
// and typing indicators are never counted.
const OBLIGATION_REPRESENT_GUARD_MIN_REPLY_CHARS = (() => {
  const raw = process.env.SWITCHROOM_OBLIGATION_REPRESENT_GUARD_MIN_REPLY_CHARS
  const n = raw != null ? Number.parseInt(raw, 10) : NaN
  return Number.isFinite(n) && n >= 1 ? n : 1
})()
const OBLIGATION_SWEEP_MS = 5_000
// Bound on escalation SEND attempts. The escalation now closes only AFTER a
// successful send (a transient failure stays OPEN and retries next sweep), so a
// PERMANENTLY-undeliverable nudge (dead/renumbered topic → Telegram 400 even
// after thread-fallback, blocked bot) would loop forever — and, with the
// durable snapshot, re-enter that loop on every boot. After this many failed
// attempts the gateway closes best-effort (loud log): the user is genuinely
// unreachable, so a bounded give-up beats an infinite/poison loop.
const OBLIGATION_ESCALATE_MAX = 3
// Deadline for a single escalation send. grammy/fetch impose NO request timeout,
// and the in-flight guard (obligationEscalateInFlight) is cleared only in the
// send's `.finally` — which never runs if the send hangs. Without a bound, one
// stalled send leaks the in-flight flag forever and the obligation is stuck OPEN
// (never re-escalated, never closed) — the sole liveness hole a total proof
// found. Racing the send against this deadline makes the wait bounded BY
// CONSTRUCTION (see with-deadline.ts): the chain always settles, `.finally`
// always clears the flag, and a hang becomes a bounded reject that feeds the
// bounded escalate ladder to a terminal. 45s comfortably exceeds robustApiCall's
// 3-attempt network backoff so a legitimate slow send isn't cut short.
const OBLIGATION_ESCALATE_SEND_DEADLINE_MS = 45_000
// Escalate-grace window. A slow / background-worker / multi-segment turn ends
// (the in-flight gate clears) BEFORE its trailing answer's reply lands, and the
// 5s sweep would re-present/escalate in that gap — a false "⚠️ I may have missed
// this" on a message that's actively being answered (fuzz-confirmed on v0.14.62:
// ~14% of marko's no-reply turn-ends had the answer in flight). An obligation
// whose handling turn ended < this ago is skipped by decideAtIdle, giving the
// trailing answer's close a beat to fire. Bounded: each re-present is itself a
// turn that re-stamps once, representCount is capped → the ladder still
// terminates. 45s > the observed "answer lands within ~60s, usually <40s" gap.
// Kill switch: SWITCHROOM_OBLIGATION_ESCALATE_GRACE_MS=0 → pre-grace behaviour.
const OBLIGATION_ESCALATE_GRACE_MS = (() => {
  const raw = process.env.SWITCHROOM_OBLIGATION_ESCALATE_GRACE_MS
  if (raw == null || raw === '') return 45_000
  const n = Number(raw)
  return Number.isFinite(n) && n >= 0 ? n : 45_000
})()

// Background-work escalate-grace ceiling. The 45s grace above is far too short
// for extended-autonomous sub-agent work: an agent that ack-firsts ("on it")
// then delegates to a background worker OR an orphaned foreground sub-agent ends
// its FOREGROUND turn in seconds, but the real answer lands minutes later. The
// turn-in-flight machine (turn already ended) doesn't see that work, so the
// sweep would re-present/escalate a false "⚠️ I may have missed this — re-send"
// while the agent is genuinely researching (the gymbro liven-research case,
// 2026-06-10). While `agentHasInFlightBackgroundWork()` holds, an open
// obligation younger than THIS ceiling (from openedAt) is skipped. Bounded BY
// CONSTRUCTION — a hard wall-clock ceiling, so even a stuck/leaked worker can't
// suppress escalation forever; the obligation FSM still terminates. This also
// preserves the represent budget across a restart that kills the work: with the
// false represents suppressed, the hydrated obligation re-presents (resumes the
// research) instead of prematurely escalating. Kill switch: =0 → pre-fix
// behaviour (no background-work grace).
const OBLIGATION_BACKGROUND_WORK_GRACE_MS = (() => {
  const raw = process.env.SWITCHROOM_OBLIGATION_BACKGROUND_WORK_GRACE_MS
  if (raw == null || raw === '') return 20 * 60_000 // 20 min — generous for real research, still bounded
  const n = Number(raw)
  return Number.isFinite(n) && n >= 0 ? n : 20 * 60_000
})()
// Per-represent grace window. After a re-present fires, the obligation is
// ineligible for the next represent/escalate until at least this many ms have
// elapsed since markRepresented. Without this the 5s sweep can fire again
// before the re-presented turn even reaches the agent, burning the represent
// budget and producing back-to-back re-presents or a premature escalation.
// Default 120s — generous enough for a turn to start + deliver an answer;
// small enough not to delay genuine unanswered re-presents.
// Kill switch: SWITCHROOM_OBLIGATION_REPRESENT_GRACE_MS=0 → no per-represent grace.
const OBLIGATION_REPRESENT_GRACE_MS = (() => {
  const raw = process.env.SWITCHROOM_OBLIGATION_REPRESENT_GRACE_MS
  if (raw == null || raw === '') return 120_000
  const n = Number(raw)
  return Number.isFinite(n) && n >= 0 ? n : 120_000
})()
// Marker-freshness window for the orphaned-foreground signal. The turn-active
// marker is touched on every foreground tool_use and on foreground sub-agent
// JSONL growth, so an mtime younger than this means a sub-agent is touching it
// RIGHT NOW; older ⇒ the work stopped (or the marker leaked) ⇒ not active.
// Comfortably exceeds the sub-agent poll cadence so it doesn't flap.
const TURN_ACTIVE_MARKER_FRESH_MS = 90_000

// ─── Mid-turn auto-classify (steer-vs-queue), SHADOW mode ─────────────────────
// Today a no-prefix mid-turn message always QUEUES. autoClassifyMidTurnInbound
// (auto-classify-mid-turn.ts) is the basis for a smarter default using
// topic-vs-active-turn + reply-recency. Phase 1 ships SHADOW-ONLY: when this
// flag is on we COMPUTE + LOG what we'd decide (decision/reason/same_topic/
// ms_since_out) but the behaviour is UNCHANGED (still queue) — to gather the
// real-world distribution (how often mid-turn messages are same-topic
// continuations vs cross-topic, and the recency spread) before any action flips
// on. DEFAULT ON fleet-wide (data-gathering: zero behaviour change — only logs +
// a bounded recency map). This is a TEMPORARY default; when auto-steer ships it
// supersedes shadow. Kill switch: SWITCHROOM_AUTOCLASSIFY_MIDTURN_SHADOW=0.
const AUTOCLASSIFY_MIDTURN_SHADOW = process.env.SWITCHROOM_AUTOCLASSIFY_MIDTURN_SHADOW !== '0'
// Per-(chat,thread) wall-clock ms of the agent's LAST visible output — the
// recency clock the classifier uses (NOT turn age: a long actively-narrating
// worker turn must not read "stale"). Stamped beside signalTracker.noteOutbound.
// LRU-bounded so a long-lived gateway with many topics can't grow unboundedly.
const lastAgentOutputAt = new Map<string, number>()
const LAST_OUTPUT_MAX_KEYS = 512
function noteAgentOutputAt(key: string, ts: number): void {
  lastAgentOutputAt.delete(key) // re-insert → most-recently-used at the tail
  lastAgentOutputAt.set(key, ts)
  if (lastAgentOutputAt.size > LAST_OUTPUT_MAX_KEYS) {
    const oldest = lastAgentOutputAt.keys().next().value
    if (oldest !== undefined) lastAgentOutputAt.delete(oldest)
  }
}
// Durable snapshot of the open obligation set on the persistent per-agent
// volume (STATE_DIR = /state/agent/telegram in prod). Closes the restart hole:
// the in-memory ledger alone empties on restart and the spool's boot-replay
// bypasses handleInbound (where obligations OPEN), so a delivered-but-unanswered
// message used to lose its obligation across a restart. onChange persists every
// mutation; boot hydrate (below) restores OPEN/ESCALATING with representCount +
// escalateAttempts intact. STATIC mode (no runtime) and flag-off both skip disk.
const OBLIGATION_STORE_PATH = join(STATE_DIR, 'obligations.json')
const obligationStoreFs = {
  readFileSync: (p: string) => readFileSync(p, 'utf8'),
  writeFileSync: (p: string, d: string) => writeFileSync(p, d),
  renameSync: (a: string, b: string) => renameSync(a, b),
  existsSync: (p: string) => existsSync(p),
}
const obligationLedger = new ObligationLedger(OBLIGATION_REPRESENT_MAX, {
  onChange:
    STATIC || !OBLIGATION_LEDGER_ENABLED
      ? undefined
      : (snapshot) => persistObligations(OBLIGATION_STORE_PATH, obligationStoreFs, snapshot),
})
if (!STATIC && OBLIGATION_LEDGER_ENABLED) {
  // Restart-durability: re-open obligations that were OPEN/ESCALATING when the
  // gateway last ran. The very next idle sweep re-presents or re-escalates them.
  const restored = loadObligations(OBLIGATION_STORE_PATH, obligationStoreFs)
  if (restored.length > 0) {
    obligationLedger.hydrate(restored)
    process.stderr.write(
      `telegram gateway: obligation-ledger hydrated ${restored.length} open obligation(s) from ${OBLIGATION_STORE_PATH}\n`,
    )
  }
}
// Origin ids with an escalation send IN FLIGHT — prevents the 5s sweep from
// firing a second concurrent send for the same obligation while the first is
// still awaiting (an escalation that takes >5s, or repeated failures).
const obligationEscalateInFlight = new Set<string>()

// ─── Serialize-until-replied (multitopic reply-routing) ───────────────────
// Component 1 (deliver-before-drain gate). A buffered cross-topic inbound
// drains ONLY after the just-ended turn delivered its reply to its own
// thread — see `serialize-drain-gate.ts` for the full rationale (the
// Brevo→Meta wrong-topic bug). Kill switch off (=0) → legacy behaviour:
// drain on the bare turn-end signal.
const SERIALIZE_UNTIL_REPLIED_ENABLED =
  process.env.SWITCHROOM_SERIALIZE_UNTIL_REPLIED !== '0'
// Component 2 (bounded no-reply escape hatch). A turn that legitimately
// ends with NO reply (handback ack, NO_REPLY marker, silent-end) sets
// finalAnswerDelivered=false and would block the serialize gate forever.
// When such a turn ends with a buffered inbound waiting, arm a short
// bounded timer that force-drains regardless. The 300s silence-poke
// unwedge fallback remains the long-stop. Tunable for tests/forensics;
// clamped to a positive finite value (a degenerate override would either
// drain instantly — defeating serialization — or, if negative, be
// rejected). To disable the serialize feature entirely use
// SWITCHROOM_SERIALIZE_UNTIL_REPLIED=0, not a degenerate timeout.
const _noReplyDrainRaw = process.env.SWITCHROOM_SERIALIZE_NOREPLY_DRAIN_MS
const _noReplyDrainParsed =
  _noReplyDrainRaw != null && _noReplyDrainRaw !== '' ? Number(_noReplyDrainRaw) : 2_500
const SERIALIZE_NOREPLY_DRAIN_MS =
  Number.isFinite(_noReplyDrainParsed) && _noReplyDrainParsed > 0 ? _noReplyDrainParsed : 2_500
// Component 3 (turn-origin reply routing). Resolve an answer's thread from
// the turn that OWNS the reply (matched by origin_turn_id), not the live
// currentTurn if it has flipped. Kill switch off (=0) → legacy turn-pinned
// behaviour (#1664: thread from the live currentTurn capture).
const TURN_ORIGIN_ROUTING_ENABLED =
  process.env.SWITCHROOM_TURN_ORIGIN_ROUTING !== '0'
// Framework-owned origin recovery (2026-06-05 determinism pass). The origin
// signal that survives a currentTurn flip (tier 2) travels through the MODEL
// (it echoes `origin_turn_id`). When the model OMITS it, routing falls to the
// live turn — the wrong topic if currentTurn flipped (HOLE a). The model rarely
// passes `reply_to` explicitly, but WHEN it quotes a specific earlier message
// that message_id is a FRAMEWORK-owned anchor: reverse-index it to the turn
// that owns it and recover the origin without the model echo. Strictly
// additive — it only fires when the echo is absent AND a quote is present, and
// resolves to the ACTUAL origin turn (never the live successor), so it cannot
// mask a misroute. Kill switch off (=0) → echo-only origin (today's behaviour).
const FRAMEWORK_ORIGIN_ROUTING_ENABLED =
  process.env.SWITCHROOM_FRAMEWORK_ORIGIN_ROUTING !== '0'
// Reply-topic framework authority (2026-06-08 determinism pass). The topic an
// ANSWER lands in is owned by the TURN it answers (origin → live), NOT the
// model's `message_thread_id`. The model's explicit thread is demoted to a
// last resort (consulted only when there is no origin AND no live turn). Closes
// the model-chosen-topic override that sent a General-topic question's answer
// into the CRM topic (marko) — the model could redirect any reply. Kill switch
// off (=0) → legacy explicit-first precedence (the model's thread wins).
const REPLY_TOPIC_AUTHORITY_ENABLED =
  process.env.SWITCHROOM_REPLY_TOPIC_AUTHORITY !== '0'
// Component 4 (per-turn topic framing). Add a one-line directive to the
// channel meta + bridge instructions telling the model to answer ONLY the
// current message's topic. Kill switch off (=0) → no framing field.
const TOPIC_FRAMING_ENABLED =
  process.env.SWITCHROOM_TOPIC_FRAMING !== '0'
// Component 5 (queued-status UX). Post a self-updating "Queued — replying
// in <other topic> first" status into a cross-topic buffered message's own
// topic, then edit→delete it as the turn progresses. Kill switch off (=0)
// → no placeholder (the 👀 ack reaction still fires). Delete-on-answer.
const QUEUED_STATUS_UX_ENABLED =
  process.env.SWITCHROOM_QUEUED_STATUS_UX !== '0'
// Feed-reopen-after-ack. When a tool label arrives for a turn already
// marked finalAnswerDelivered, the model is still WORKING — so the earlier
// "final" reply was an interim ACK (an ack-first reply pings or runs ≥200
// chars, both of which isFinalAnswerReply classifies as final). Re-open the
// live activity feed for the post-ack work instead of dropping the label.
// Kill switch off (=0) → legacy behaviour: the label is dropped and the
// post-ack feed stays dark. See `feed-reopen-gate.ts` for the rationale and
// the finalAnswerDelivered-consumer interactions.
const FEED_REOPEN_AFTER_ACK_ENABLED =
  process.env.SWITCHROOM_FEED_REOPEN_AFTER_ACK !== '0'

// Activity-feed heartbeat (PR1). The feed is pull-only — it only re-renders on
// a tool_label event, so a long single step that emits no new label leaves the
// feed frozen on "→ doing X" for tens of seconds (the marko ~26s freeze). The
// heartbeat re-renders the live feed every FEED_HEARTBEAT_TICK_MS with a
// climbing " · Ns" elapsed on the in-progress line, but only once the current
// step has run >= FEED_HEARTBEAT_MIN_STALE_MS (so a normally-advancing feed is
// untouched). Kill switch: SWITCHROOM_FEED_HEARTBEAT=0. Default on.
const FEED_HEARTBEAT_ENABLED = process.env.SWITCHROOM_FEED_HEARTBEAT !== '0'
const FEED_HEARTBEAT_TICK_MS = 6_000
const FEED_HEARTBEAT_MIN_STALE_MS = 6_000
// Liveness-driven feed open. The activity feed is otherwise TOOL-driven — it
// opens only when a tool emits a non-null label. A turn dominated by thinking
// or by suppressed-by-design tools (typing / memory recall / reply) emits no
// label, so the feed never opens and a long turn reads as pure silence until
// the 300s silence-poke (the #680 dark-turn). When a turn has been alive >=
// FEED_LIVENESS_OPEN_MS with no feed yet, open a minimal "Working…" feed so the
// user always has a live indicator; the first real tool label edits it with
// real content.
//
// Two callers reach the SAME open path (`openLivenessFeedIfDue`):
//   1. an enqueue-time one-shot timer (`scheduleEarlyLivenessOpen`) fires at
//      `FEED_LIVENESS_OPEN_MS` after turn start — this is the early-open that
//      kills the dead-air gap (narration emitted before the first tool now
//      surfaces ~`FEED_LIVENESS_OPEN_MS` after enqueue, not after a 6 s
//      heartbeat phase + the old 12 s threshold);
//   2. the 6 s heartbeat tick, which maintains/climbs the card and is the
//      backstop if the one-shot ever missed (e.g. a clock skew).
// The threshold dropped from 12 s → ~1.2 s so the "something is happening"
// signal lands within a second or two of the inbound, matching the JTBD
// `know-what-my-agent-is-doing` p95 ≤ ~1 s ambient-ack bar. Kill switch:
// SWITCHROOM_FEED_LIVENESS_OPEN=0. Default on.
const FEED_LIVENESS_OPEN_ENABLED = process.env.SWITCHROOM_FEED_LIVENESS_OPEN !== '0'
const FEED_LIVENESS_OPEN_MS = (() => {
  const raw = process.env.SWITCHROOM_FEED_LIVENESS_OPEN_MS
  const n = raw ? Number(raw) : NaN
  return Number.isFinite(n) && n > 0 ? n : 1_200
})()

// Post-answer background-agent liveness STALENESS CAP (Fix 2 / #2587 supersede,
// concern 3). The `feedHeartbeatTick` post-answer branch re-renders a "background
// agent still working" card every FEED_HEARTBEAT_TICK_MS while the sub-agent
// watcher keeps advancing `turn.subagentActivityAt`. Without a cap that card kept
// emitting `state:'running'` with an ever-climbing `elapsed` FOREVER — even after
// the worker's `onFinish` froze the timestamp — because (unlike the pre-answer
// path's `FEED_LIVENESS_OPEN_MS` recency cap) the post-answer branch had no
// staleness bound. This cap mirrors that pre-answer pattern: once the worker's
// last advance is older than the cap, the heartbeat stops re-rendering and the
// card freezes at its last state. Parsed via the same pure `parsePostAnswerLivenessMs`
// helper (positive int or 0); `|| 30_000` supplies a default-ON 30s cap, so an
// unset env keeps the cap active. Override with SWITCHROOM_POST_ANSWER_LIVENESS_STALE_MS.
const POST_ANSWER_LIVENESS_STALE_MS = parsePostAnswerLivenessMs(
  process.env.SWITCHROOM_POST_ANSWER_LIVENESS_STALE_MS,
) || 30_000

// Live-feed step suffixes render via `formatStepSuffix` (tool-activity-summary):
// the CURRENT step's own elapsed, shown only past STEP_TIMER_MIN_MS (10 s).

/**
 * Authoritative "is a turn in flight?" for every gate that previously
 * read `claudeBusyKeys.size`. PR 3b cutover (extends PR 3a's bridgeUp
 * dispatch): when the delivery state machine is authoritative
 * (`SWITCHROOM_DELIVERY_MACHINE_CUTOVER` on + shadow on) the answer is
 * its single-`activeTurn` global state, which — unlike the
 * per-delivery `claudeBusyKeys` set — cannot accumulate orphan keys and
 * wedge the gate "in-flight forever" (the gymbro/clerk 5-min dangle,
 * 2026-05-28). Kill-switch off → exact legacy claudeBusyKeys behaviour.
 *
 * NOT for the inbound-receipt gate (line ~8551): that must snapshot the
 * machine state BEFORE the inbound event advances it, or a fresh-turn
 * message self-blocks. See the snapshot at the inbound handler.
 */
function turnInFlightForGate(): boolean {
  return isDeliveryCutoverEnabled() ? isMachineInTurn() : claudeBusyKeys.size > 0
}

/**
 * Deliver a synthetic "resume" inbound — the wake-up the gateway sends
 * after an operator approves/denies a vault grant, provides/declines a
 * requested secret, or completes/fails/discards a vault save — turn-gated
 * exactly like a real Telegram inbound.
 *
 * THE BUG (clerk `hotdoc/credentials`, 2026-06-13): these synthetics did a
 * raw `ipcServer.sendToAgent` and buffered ONLY on `delivered=false`
 * (bridge disconnected). But approvals routinely land WHILE the agent's
 * grant-requesting turn is still finishing — the socket write succeeds
 * (`delivered=true`) yet claude is mid-turn, so the channel notification
 * is typed into its TUI composer and stranded by the turn-completion race
 * (#1556, the lawgpt wedge). `delivered=true` → the buffer never rescued
 * it → the agent sat idle until the operator manually poked it. Observed:
 * injection 179ms BEFORE turn_end, then 2 minutes of silence.
 *
 * Fix: route through the SAME `decideInboundDelivery` gate the Telegram
 * `handleInbound` path uses. Mid-turn → `buffer-until-idle` (the
 * turn-complete hook `releaseTurnBufferGate → drainBufferedIfAllowed`,
 * plus the idle-drain timer, flush it the instant claude goes idle, where
 * it lands cleanly as a fresh turn). Idle → deliver now; buffer on a
 * genuine delivery miss exactly as before. Unlike the cron `inject_inbound`
 * path (deliberately ungated — at-least-once replay), a one-shot resume
 * synthetic must never strand, so it IS gated.
 *
 * Returns true iff delivered to the bridge now (false = buffered/held;
 * the caller's forensic log records this as `delivered=false`, which now
 * means "held mid-turn OR bridge-down" — both are "will flush when idle",
 * never "dropped").
 */
function deliverResumeSyntheticOrBuffer(agent: string, inbound: InboundMessage): boolean {
  const decision = decideInboundDelivery({
    turnInFlight: turnInFlightForGate(),
    isSteering: false,
    isInterrupt: false,
  })
  if (decision === 'buffer-until-idle') {
    pendingInboundBuffer.push(agent, inbound)
    return false
  }
  const delivered = ipcServer.sendToAgent(agent, inbound)
  if (delivered) markClaudeBusyForInbound(inbound)
  else pendingInboundBuffer.push(agent, inbound)
  return delivered
}

const pendingRestarts = new Map<string, number>()  // agentName -> timestamp when restart was requested

// ─── Proactive context compaction (session.max_context_tokens) ──────────
//
// Opt-in: when the resolved agent config sets session.max_context_tokens,
// we fire `/compact` once the live context-window occupancy of the latest
// assistant turn reaches that many tokens. Evaluated ONLY at the
// model-idle gate inside purgeReactionTracking (activeTurnStartedAt.size
// === 0) — never mid-turn — mirroring the pendingRestarts drain. The
// `/compact` verb is allowlisted in src/agents/inject.ts and runs via the
// tmux send-keys path (the only path that actually executes the slash
// command; inject_inbound would deliver it as literal text).
//
// `lastSessionActiveFile` is the session-tail's tracked currentFile,
// forwarded by the bridge on every session_event — we read occupancy from
// exactly that file (never an independent findActiveSessionFile re-scan).
let lastSessionActiveFile: string | null = null
// Anti-spam state machine lives in ./proactive-compact (pure, unit
// tested). `compactDispatching` is a synchronous re-entrancy guard for
// the async tmux send — purgeReactionTracking can run several times per
// turn and we must not double-dispatch before the first send settles.
let compactState: CompactState = initialCompactState()
let compactDispatching = false

// User-facing proactive-compaction notification (single Telegram card
// edited START → FINISH; transition selection is pure in
// ./compact-notify). Session reset/rotation stays silent — not here.
// The wall-clock timer is owned HERE (not the pure helper): an idle
// agent produces no idle evaluations, so a card that never gets a
// re-arm edge must be resolved by a real timer, independent of the
// eval loop, or it would dangle forever.
const COMPACT_CARD_TIMEOUT_MS = 15 * 60 * 1000
interface OutstandingCompactCard {
  chatId: string
  threadId: number | undefined
  messageId: number
  occAtStart: number
  capAtStart: number
  timer: ReturnType<typeof setTimeout>
}
let compactNotifyState: CompactNotifyState = idleCompactNotifyState()
let outstandingCompactCard: OutstandingCompactCard | null = null
const activeDraftStreams = new Map<string, DraftStreamHandle>()
const suppressPtyPreview = new Set<string>()
const lastPtyPreviewByChat = new Map<string, string>()
const progressUpdateLastSent = new Map<string, number>()
const progressUpdateTurnCount = new Map<string, number>()

// Pre-allocated placeholder drafts (issue #416) and the associated
// heartbeat / phase enrichment were removed in #553 PR 5. Real-text +
// 👀 status reaction (#568) + sendChatAction('typing') indicator
// (#585) replace the visual gap that the placeholder used to fill.
// recall.py's update_placeholder IPC calls now no-op cleanly because
// the gateway no longer registers an onUpdatePlaceholder handler.

/**
 * Per-turn singletons consolidated into one atom (#1067).
 *
 * Pre-#1067, this was 13 module-level `let`s (currentSessionChatId,
 * currentTurnStartedAt, currentSessionThreadId, currentTurnReplyCalled,
 * currentTurnCapturedText, orphanedReplyTimeoutId, currentTurnRegistryKey,
 * currentTurnLastAssistantMsgId, currentTurnLastAssistantDone,
 * currentTurnToolCallCount, activeAnswerStream, currentTurnIsDm,
 * currentTurnGatewayReceiveAt). Every async session-event handler read
 * those singletons directly — so a handler that captured a value,
 * awaited, and resumed could see the next turn's state instead of its
 * own. Concretely: tool_use for chat A could route its visible effect
 * (status reaction, progress card mutation, answer-stream update) to
 * chat B if an `enqueue` for B landed during the handler's await.
 *
 * The fix: a single mutable atom that `enqueue` swaps wholesale and
 * `turn_end` nulls. Every handler captures `const turn = currentTurn`
 * at entry — closures and async continuations use that snapshot for
 * the rest of the handler, so a mid-handler enqueue can't reattribute.
 *
 * Field-name mapping (old → new):
 *   currentSessionChatId            → turn.sessionChatId
 *   currentSessionThreadId          → turn.sessionThreadId
 *   currentTurnStartedAt            → turn.startedAt
 *   currentTurnGatewayReceiveAt     → turn.gatewayReceiveAt
 *   currentTurnReplyCalled          → turn.replyCalled
 *   currentTurnCapturedText         → turn.capturedText
 *   orphanedReplyTimeoutId          → turn.orphanedReplyTimeoutId
 *   currentTurnRegistryKey          → turn.registryKey
 *   currentTurnLastAssistantMsgId   → turn.lastAssistantMsgId
 *   currentTurnLastAssistantDone    → turn.lastAssistantDone
 *   currentTurnToolCallCount        → turn.toolCallCount
 *   activeAnswerStream              → turn.answerStream
 *   currentTurnIsDm                 → turn.isDm
 */
type CurrentTurn = {
  sessionChatId: string
  sessionThreadId: number | undefined
  // Inbound message id this turn answers. Anchors the activity feed's
  // native reply-quote (reply_parameters) so the user's question renders
  // as a quoted header on the feed message. Null for synthesized turns
  // (cron/handback) that have no originating inbound message.
  sourceMessageId: number | null
  startedAt: number
  gatewayReceiveAt: number
  // #2527 — the single turn-provenance discriminator, stamped once at
  // enqueue from the channel envelope `source`. `user` (a human is waiting:
  // never-silent guarantee + mid-turn floor), `system` (cron/scheduled:
  // silence is legitimate). The gateway never builds a turn atom for a
  // sub-agent, so `sub-agent` never appears here. Read by the mid-turn floor
  // eligibility and the role-aware terminal reaction gate. Replaces the
  // scattered `chatType`/`chatId==null`/`source==='cron'` predicates.
  role: LoopRole
  // PR1 (cross-turn stale-card guard, design `docs/message-emission-determinism.md`
  // §9 lever 4 / race C/D). Present ONLY when this turn is a cross-turn SYNTHETIC
  // surface whose card OPEN must be gated against an answer already delivered in
  // an EARLIER turn — i.e. an `obligation_represent` re-delivery (and the
  // liveness/heartbeat timer firing on it). `sinceMs` is the obligation's
  // `openedAt` — the moment the obligation was RAISED — so the card-OPEN gate
  // asks `hasOutboundDeliveredSince(chat, openedAt)`: did a substantive answer
  // already land since then? Stamped at the turn ctor from a pending marker that
  // `obligationSweep` writes when it pushes the represent inbound (see
  // `pendingCrossTurnGate`). `undefined` for a normal foreground turn → the
  // cross-turn lever-4 gate is inert there (the foreground turn's own card is
  // governed only by the per-turn `finalAnswerEverDelivered` latch, lever 1).
  crossTurnGate?: { sinceMs: number }
  replyCalled: boolean
  // #1664 — whether the model has delivered its *final answer* this turn
  // (as opposed to only an interim ack). `replyCalled` flips on the first
  // reply / stream_reply tool_use and stays true for the rest of the turn,
  // so it cannot tell "ack only" from "ack + real answer". This flag is the
  // finer signal the silent-end re-prompt needs: it is set only when a reply
  // actually lands AND `isFinalAnswerReply` (final-answer-detect.ts)
  // classifies it as the final answer — notification-bearing, or long
  // enough to be substantive, or a stream_reply done=true — OR when the
  // turn-flush safety net legitimately emits the model's terminal text. A
  // turn that ends with this still `false` triggers the silent-end re-prompt
  // even though `replyCalled` is true — the #1664 case where the real answer
  // ended up as plain transcript text rendered into an ephemeral draft.
  finalAnswerDelivered: boolean
  // Feed-reopen-after-ack refinement — whether the reply that set
  // `finalAnswerDelivered` was a *substantive* final answer (stream
  // `done`, or ≥200 chars) as opposed to a short pinging interim ACK.
  // Set via `isSubstantiveFinalReply` at every site that sets
  // `finalAnswerDelivered = true`. The tool_label handler re-opens the
  // live activity feed ONLY when `finalAnswerDelivered && !finalAnswer-
  // Substantive` (the prior "final" was an ack). After a genuine final
  // answer this stays true, so routine post-answer housekeeping (memory
  // write / TodoWrite / Bash — non-surface tools that reach the handler)
  // does NOT reopen and does NOT reset `finalAnswerDelivered`, which would
  // otherwise spuriously trip the silent-end re-prompt → duplicate answer.
  // Reset to false on every fresh-turn enqueue alongside
  // `finalAnswerDelivered`.
  finalAnswerSubstantive: boolean
  // Sticky "a substantive final answer has been delivered this turn" latch
  // (design `docs/message-emission-determinism.md` §9 preamble / R0). Distinct
  // from the MUTABLE `finalAnswerDelivered`, which the ack-reopen path clears
  // mid-turn (`feed-reopen-gate.ts:157`) so an "On it…" ack keeps a live feed
  // (#2141). Ordering gates (the no-OPEN-after-final card gate, lever 1) MUST
  // key on this sticky latch, not the mutable flag — keying on the mutable flag
  // is a no-op on exactly the ack-first turn where the reorder originates. Set
  // true ONLY at the points that set `finalAnswerDelivered = true` AND only when
  // the reply is `isSubstantiveFinalReply`; NEVER cleared by reopen. Reset to
  // false ONLY at turn start, mirroring `activityEverOpened`'s sticky-true
  // contract.
  finalAnswerEverDelivered: boolean
  // #1675 (over-ping safety net): wall-clock ms of the first reply
  // this turn that landed with `disable_notification: false` (a real
  // device ping). The conversational-pacing contract
  // (`reference/rfcs/conversational-pacing.md` beat 5) says EXACTLY ONE
  // ping per turn — the final answer. When the model violates that
  // (sends a substantive answer pinged + a wrap-up "Delivered…" or
  // meta-narration also pinged), subsequent reply calls with
  // `disable_notification: false` are auto-downgraded to silent by
  // the framework. Null until the first ping lands. Reset on every
  // fresh-turn enqueue.
  firstPingAt: number | null
  // Notification ownership (R8 / PR-2 — design `docs/message-emission-
  // determinism.md` §over-ping). Whether the send that CLAIMED this turn's
  // ping slot (`firstPingAt`) was itself a *substantive* final answer
  // (`isSubstantiveFinalReply`) as opposed to a short interim ACK. The
  // over-ping safety net keys on this so a substantive answer pinging AFTER
  // an ack already pinged is UPGRADED (let through, owns the slot) rather
  // than silenced — otherwise "the reply is last but the phone never buzzed
  // for the answer." Set ATOMICALLY with `firstPingAt` (same synchronous
  // block, no await between) on a claim/upgrade so a racing second reply
  // reads a consistent pair. Init false; reset to false on every fresh-turn
  // enqueue alongside `firstPingAt`.
  firstPingWasSubstantive: boolean
  // #1677 silent-reply auto-edit. The first silent reply of a turn
  // captures `silentAnchorMessageId` + `silentAnchorText`; subsequent
  // silent replies in the SAME turn editMessageText that anchor
  // (appending with paragraph-break separator). Net visual: one
  // growing silent bubble instead of N stacked silent bubbles.
  // Cleared by turn-atom replacement on enqueue. See
  // `telegram-plugin/silent-reply-anchor.ts` for the pure
  // `decideSilentReplyAnchor` predicate.
  silentAnchorMessageId: number | null
  silentAnchorText: string
  capturedText: string[]
  orphanedReplyTimeoutId: ReturnType<typeof setTimeout> | null
  // How many times the orphaned-reply backstop timer has been re-armed
  // mid-tool-call instead of firing a synthetic turn_end. Bounded so a
  // genuinely wedged single long-running tool still surfaces: the cap is
  // ORPHANED_REPLY_MAX_REARMS (20 × 30 s = 10 min of genuine tool activity).
  // Reset to 0 on a fresh enqueue; NOT reset on text/tool_label re-arms —
  // only a new turn resets the budget.
  orphanedReplyRearmCount: number
  // Component 3 (turn-origin reply routing). A stable per-turn identity,
  // `${registryKey-or-chatKey}#${startedAt}`, assigned when the turn
  // starts and stamped into the inbound meta (`origin_turn_id`) so a reply
  // can be matched back to the turn that OWNS it — even after `currentTurn`
  // has flipped to a successor. Recently-ended turns are retained in
  // `recentTurnsById` so a late reply (the Brevo answer landing 42s after
  // turn-end, when currentTurn already points at Meta) routes to its
  // origin thread instead of the live (wrong) turn's thread.
  turnId: string
  registryKey: string | null
  // Component 2 (bounded no-reply escape hatch). When a turn ends with
  // finalAnswerDelivered=false AND a buffered cross-topic inbound is
  // waiting, this timer force-drains after SERIALIZE_NOREPLY_DRAIN_MS so
  // the queue can never wedge on a legitimately silent turn. Armed in
  // `endCurrentTurnAtomic`, cleared if the turn delivers first.
  noReplyDrainTimer: ReturnType<typeof setTimeout> | null
  // Last assistant outbound message id for the current turn — populated
  // on reply / stream_reply emit, captured into recordTurnEnd. Stage 4
  // reads this on resume to thread-jump back to the in-flight conversation.
  lastAssistantMsgId: string | null
  // Whether the current turn produced a stream_reply with done=true. The
  // resume protocol uses this to decide "did the previous turn actually
  // finish a reply, or was it interrupted before commit?".
  lastAssistantDone: boolean
  // Phase 1 of #332: count of tool_use events in the current turn, for
  // the tool_call_count column in the turns registry.
  toolCallCount: number
  // Count of tool_label events that passed the isTelegramSurfaceTool guard
  // this turn — the deterministic, surface-tool-excluded step count used by
  // the `✓ N steps` activity-feed total and the `tools=` lifecycle log.
  // Incremented in `case 'tool_label':` AFTER the surface-tool guard so
  // reply/stream_reply/edit_message/react are never counted. send_typing and
  // sync_retain are suppressed at the hook (computeLabel returns null) and
  // never arrive as tool_label events — excluded automatically.
  labeledToolCount: number
  // Tool-activity summary — mirrors Claude Code's native chat-UI
  // rendering ("Ran 5 commands, read a file"). Counters are
  // incremented in `case 'tool_use'`; `activityMessageId` holds the
  // Telegram message id we send/edit so a single message accumulates
  // the summary in place. Stops updating once `replyCalled` flips —
  // the model's own reply lands below the summary as the actual
  // content.
  //
  // Parallel-tool-use coalescing (PR #1926 review): modern Claude
  // emits multiple tool_uses in a tight synchronous loop (e.g. 3
  // parallel Reads). Without coalescing, each would see
  // `activityMessageId == null` and fire its own sendMessage,
  // producing N messages instead of one editable summary. Pattern
  // mirrors `telegram-plugin/answer-stream.ts`:
  //   - `activityInFlight` — promise that resolves when the current
  //     send/edit settles. While set, NEW tool_uses just update
  //     `activityState` and `activityPendingRender` and return.
  //   - When the in-flight resolves, it picks the latest
  //     `activityPendingRender`, fires the next send/edit, and
  //     repeats until the pending matches the last-sent.
  // Result: at most one Telegram call in flight at a time; the
  // final state always lands.
  activityMessageId: number | null
  activityInFlight: Promise<void> | null
  activityPendingRender: string | null
  activityLastSentRender: string | null
  // Status-surface observability. `activityEverOpened` is sticky-true once the
  // feed posts its first message — unlike `activityMessageId`, it is NOT nulled
  // by `clearActivitySummary`, so the turn-end DEGRADED check can tell "feed
  // never opened" (the resume-400 signature) from "feed finalized + cleared".
  // `activityDrainFailures` counts real activity-feed send/edit failures this
  // turn (429s + "message is not modified" excluded). Both reset per turn.
  activityEverOpened: boolean
  activityDrainFailures: number
  // Wall-clock anchor for the newest in-progress feed step — set each time a
  // tool_label re-renders the feed. The heartbeat (`feedHeartbeatTick`) reads
  // it to show a climbing " · Ns" elapsed on the live line so a long single
  // step that emits no new label doesn't read as frozen (the feed is otherwise
  // pull-only). undefined until the first label of the turn renders.
  lastToolLabelAt?: number
  // Fix 2 (post-answer background-agent liveness): wall-clock timestamp last
  // updated by the sub-agent/workflow watcher's onProgress callback whenever
  // it surfaces a NEW sub-agent step AFTER this turn's substantive answer was
  // delivered. Written INDEPENDENTLY of the tool_label path so the drop-guard
  // (`shouldReopenFeedAfterAck` / `finalAnswerSubstantive`) cannot gate it.
  // `feedHeartbeatTick` reads THIS (not `lastToolLabelAt`, which is frozen by
  // the drop-guard) to drive the post-answer liveness card — the core fix for
  // #2587's inert state. undefined until the first post-answer watcher advance.
  subagentActivityAt?: number
  // Sticky wall-clock timestamp when finalAnswerEverDelivered first latched
  // true this turn. Allows the heartbeat to distinguish "tool label arrived
  // before the answer" (lastToolLabelAt ≤ finalAnswerDeliveredAt, inert) from
  // "sub-agent active after the answer" (subagentActivityAt >
  // finalAnswerDeliveredAt, liveness card warranted). undefined until the
  // first substantive final answer of the turn.
  finalAnswerDeliveredAt?: number
  // Accumulating friendly-action feed for this turn. Each non-surface
  // tool_label appends a line via `appendActivityLabel`; the feed renders
  // (via `renderActivityFeed`) as a capped chronological list into the
  // in-place edited activity message and clears on reply. Reset per turn.
  mirrorLines: string[]
  // Narrative-dedup gate state (JSONL-text-narrative primitive). A `text`
  // block is held here for ONE lookahead step so the next event (a tool_use
  // or turn_end) can decide draft-then-send (SUPPRESS, it duplicates the
  // reply) vs working-narration (SHOW it as a transient mirrorLines step).
  // Null when nothing is pending. The pure decision lives in
  // narrative-dedup.ts; this slot is the per-turn cursor. Reset per turn.
  // Invariant `chat-is-the-single-source-of-truth`: a SHOWN narrative is
  // rendered through the SAME appendActivityLabel→renderStepFeed path as a
  // tool step — a transient, clipped, rolling-window line replaced by the
  // next event, never a persisted parallel mirror.
  pendingNarrative: { text: string } | null
  // Most-recently-seen reply/stream_reply `input.text` for this turn — the
  // ACTUAL delivered answer surface. Set wherever a REPLY_TOOL tool_use is
  // handled in the reducer. `flushPendingNarrativeAtTurnEnd` compares a
  // trailing narrative block against THIS (not capturedText.join(''), which
  // can mis-suppress when the model emits the same short string twice in a
  // turn). Empty string until the turn delivers a reply. Reset per turn.
  lastReplyText: string
  // Model A — foreground sub-agent nesting. A foreground sub-agent (Task/Agent
  // with no run_in_background) runs INSIDE this turn while the parent blocks at
  // the Task tool, so its live steps nest under the parent's activity feed
  // rather than a separate message. Keyed by jsonl agent id; value = the
  // sub-agent's accumulated narrative lines (oldest→newest, deduped + capped).
  // Background workers are NOT here — they get the standalone worker feed.
  foregroundSubAgents: Map<string, string[]>
  // Issue #195 — answer-lane streaming. Lazily created on the first text
  // event of a turn (once enough text has accumulated, the stream itself
  // gates on minInitialChars). Materialized and cleared at turn_end.
  answerStream: AnswerStreamHandle | null
  isDm: boolean
  // PR-4a (message-emission-determinism, `emission-authority.ts`). The
  // per-foreground-turn emission-authority façade the foreground-lane card/ping
  // emission call sites route through. Constructed ONCE per turn in the ctor
  // with the chat/thread key passed in explicitly (the PR-4e seam). Per-turn
  // only — a fresh `CurrentTurn` literal gets a fresh façade, so it never
  // persists across turns. Optional in the type so the bounded recently-ended
  // registry's older entries (and any hand-built test turn) tolerate its
  // absence; `emissionAuthorityFor` lazily backfills one when missing.
  emissionAuthority?: EmissionAuthority
}

// PR-4e — the singleton `currentTurn` is RETAINED as (a) the flag-OFF store and
// (b) the flag-ON "most-recent-set" MIRROR. Every GLOBAL-liveness read in this
// file (`isBusy`, the `if (currentTurn != null) return` poke guards, the
// orphaned-reply guard, the synchronous-to-live-turn `const turn = currentTurn`
// captures) keeps reading this variable, so under the sequential-CLI invariant
// (the most-recently-set turn IS the live turn) those reads stay byte-identical.
// The per-topic isolation lives in `currentTurnMap.byKey`: a LATE async event
// captured for topic A resolves A's authority by ITS OWN key even after the live
// turn flipped to topic B (see current-turn-map.ts). Under the flag OFF the map
// is never written and this is exactly the old singleton.
let currentTurn: CurrentTurn | null = null
const currentTurnMap = new CurrentTurnMap<CurrentTurn>()
// Captures the most-recently-started turn's sessionChatId. Unlike currentTurn,
// this is NOT cleared by the silence poke (firePoke/clearTurnStarted). It lets
// the Bug B fallback in executeReply route to the correct chat even when the
// model calls reply AFTER the silence poke has nulled currentTurn (Bug D).
// Safe in single-tenant gateways: the fallback only fires when the raw chat_id
// fails the allowlist, and this value was itself validated at inbound receipt.
let lastActiveTurnChatId: string | undefined

/**
 * Set the live turn for `key`. Flag-branches in ONE place (inside the map):
 * flag-OFF assigns the singleton only; flag-ON sets the per-topic entry AND
 * updates the most-recent mirror. We keep the module-scope `currentTurn`
 * variable in lock-step with the map's mirror so the 140 unchanged global reads
 * see the same value.
 */
function setCurrentTurn(turn: CurrentTurn, key: string): void {
  currentTurnMap.set(turn, key)
  currentTurn = currentTurnMap.get() // mirror most-recent-set (== `turn`)
  lastActiveTurnChatId = turn.sessionChatId
}

/**
 * End (delete) the live turn for `key`, iff `key` still maps to `turn`. Routes
 * the clear through the keyed accessor (leak-close-at-origin) and re-syncs the
 * module-scope mirror to the map's mirror.
 */
function endCurrentTurnForKey(turn: CurrentTurn, key: string): boolean {
  const ended = currentTurnMap.endTurnForKey(turn, key)
  currentTurn = currentTurnMap.get() // re-sync mirror (null iff it pointed at turn)
  return ended
}

/**
 * Clear the ENTIRE per-topic store + mirror (disconnect-flush / bridge-died:
 * every entry is a ghost).
 */
function clearAllCurrentTurns(): void {
  currentTurnMap.clearAll()
  currentTurn = null
}

/**
 * Is `turn` still the live turn FOR ITS OWN topic? Flag-OFF: `currentTurn ===
 * turn` (the ambient check, verbatim). Flag-ON: `byKey.get(turn'sKey) === turn`,
 * so a B-flip never falsifies A's own liveness. The callsites keep the literal
 * `currentTurn === turn` in source (the silence-liveness-wiring oracle) by
 * inlining the flag-OFF branch and delegating the flag-ON branch here.
 */
function turnLiveForItsTopic(turn: CurrentTurn): boolean {
  return currentTurnMap.isLiveForKey(
    turn,
    statusKey(turn.sessionChatId, turn.sessionThreadId),
  )
}

/**
 * Accessor for a turn's per-foreground-turn emission-authority façade (PR-4a).
 * Returns the façade constructed at the turn ctor; lazily backfills one (keyed
 * on the turn's chat/thread) for any turn that predates the field or was built
 * outside the ctor. Per-turn: the memoized instance lives on the turn object,
 * so it is discarded with the turn and never persists across turns.
 */
function emissionAuthorityFor(turn: CurrentTurn): EmissionAuthority {
  if (turn.emissionAuthority == null) {
    turn.emissionAuthority = new EmissionAuthority(
      statusKey(turn.sessionChatId, turn.sessionThreadId),
    )
  }
  // PR-4b — CENTRALIZE the OPEN-gate wiring here, the single accessor every
  // routed call site already funnels through, so all 6 `openOrEditCard(...)`
  // sites stay byte-identical `(producer, apply)`. The façade reads the LIVE
  // turn view (a thunk — the card id / latch / tool-count mutate during the
  // turn) + the injected history deps from this one place, not per-call.
  // Idempotent; harmless under the flag OFF (the disabled branch never reads
  // it). The turn IS a structural `FeedOpenGateView`.
  turn.emissionAuthority.wireFeedOpenGate(() => turn, feedOpenGateDeps())
  return turn.emissionAuthority
}

/**
 * The injected history dependencies the PR-4b OPEN gate needs (the real
 * `hasOutboundDeliveredSince` predicate + `HISTORY_ENABLED` + the substantive
 * `FINAL_ANSWER_MIN_CHARS` floor). Centralized so both the façade's enabled
 * branch AND the drain's own (now-redundant) inline gate consume the SAME deps
 * via the SAME pure helpers — flag-ON and flag-OFF cannot diverge. Keeps
 * `feed-open-gate.ts` sqlite-free (it never imports `history.js`).
 */
function feedOpenGateDeps(): FeedOpenGateDeps {
  return {
    hasOutboundDeliveredSince,
    historyEnabled: HISTORY_ENABLED,
    finalAnswerMinChars: FINAL_ANSWER_MIN_CHARS,
  }
}

/**
 * The deliver-before-drain inputs the PR-4d card-drain gate threads into the
 * façade's pure `mayDrainCardNow`. Centralized so the card-drain helper sources
 * the SAME `turnInFlightForGate()` + kill-switch the buffer-drain gate uses.
 *
 * `endingTurnFinalAnswerDelivered` is FIXED to `null` for the card path (§5
 * modeling decision): the live foreground card single-flight is governed by
 * `turn.activityInFlight` (via `mayDrain`), NOT by an ending turn's delivery
 * state — so `mayDrainBufferedInbound` degenerates to `!turnInFlight` and a
 * synthetic represent turn (finalAnswerDelivered=false) can never wedge the card.
 */
function cardDrainGateCtx(): CardDrainGateCtx {
  return {
    turnInFlight: turnInFlightForGate(),
    endingTurnFinalAnswerDelivered: null,
    enabled: SERIALIZE_UNTIL_REPLIED_ENABLED,
  }
}

/**
 * PR-4d centralized card-drain gate (Option A). The 6 foreground card-drain
 * sites pass their EXISTING single-flight-guarded block (the `mayDrain` guard +
 * the `openOrEditCard(producer, …)` thunk that assigns `turn.activityInFlight =
 * drainActivitySummary(…)`) in VERBATIM as `run`, so those load-bearing literals
 * stay byte-identical (the wiring oracles still see them).
 *
 *  - **Flag OFF (default):** runs the guarded block directly — NO `chatLock`
 *    wrapper, byte-equivalent to base.
 *  - **Flag ON:** acquires `chatLock` AROUND the deliver-before-drain decision
 *    (`mayDrainCardNow`) + the synchronous block, unifying the card path with
 *    the #2137 serialization gate. The lock spans ONLY the gate decision + the
 *    synchronous `openOrEditCard` kick-off inside `run` (which only ASSIGNS
 *    `turn.activityInFlight = drainActivitySummary(...)`; the async send is NOT
 *    awaited inside the lock). The lock is released before any drain
 *    `await sendMessage` suspends, so a card OPEN never holds `chatLock` across
 *    the gate's release — a synthetic represent turn can never wedge the gate,
 *    and `mayDrain` stays callable lock-free.
 *
 * LOCK ORDERING (no-deadlock invariant): `chatLock` is acquired EXCLUSIVELY
 * here, around the gate; never the reverse. `mayDrainCardNow` is a pure read.
 */
function cardDrainGate(turn: CurrentTurn, ea: EmissionAuthority, run: () => void): void {
  if (EMISSION_AUTHORITY_ENABLED) {
    void chatLock.run(
      statusKey(turn.sessionChatId, turn.sessionThreadId),
      async () => {
        if (ea.mayDrainCardNow(turn, cardDrainGateCtx())) run()
      },
    )
    return
  }
  run()
}

// Component 3 (turn-origin reply routing). Recently-ended turns retained
// by `turnId` so a LATE reply (the Brevo answer landing ~42s after
// turn-end, after `currentTurn` has flipped to the Meta turn) can still
// resolve its ORIGIN turn's thread instead of the live successor's. Bug:
// `executeReply` captured `const turn = currentTurn` at entry and, when
// the model omitted message_thread_id, routed to `turn.sessionThreadId`
// — the flipped turn's thread. Pinning by origin turnId closes that.
// Bounded LRU (insertion-ordered Map) so it can't grow unbounded across
// a long-lived supergroup session.
const RECENT_TURNS_MAX = 32
const recentTurnsById = new Map<string, CurrentTurn>()
// Framework-owned origin recovery: reverse-index from an inbound's source
// message_id to the turnId that owns it, so a reply that QUOTES a specific
// message (args.reply_to) resolves its origin turn deterministically — a
// real message_id the framework stamped, never a model-asserted thread.
// Evicted in lock-step with recentTurnsById so it can't outgrow it.
const recentTurnIdBySourceMessageId = new Map<number, string>()
function rememberRecentTurn(turn: CurrentTurn): void {
  recentTurnsById.set(turn.turnId, turn)
  if (turn.sourceMessageId != null) {
    recentTurnIdBySourceMessageId.set(turn.sourceMessageId, turn.turnId)
  }
  while (recentTurnsById.size > RECENT_TURNS_MAX) {
    const oldest = recentTurnsById.keys().next().value
    if (oldest === undefined) break
    const evicted = recentTurnsById.get(oldest)
    recentTurnsById.delete(oldest)
    // Drop the reverse-index entry for the evicted turn (only when it still
    // points at THIS turn — a newer turn may have reused the same message id).
    if (evicted?.sourceMessageId != null &&
        recentTurnIdBySourceMessageId.get(evicted.sourceMessageId) === oldest) {
      recentTurnIdBySourceMessageId.delete(evicted.sourceMessageId)
    }
  }
}

/**
 * Framework-owned origin recovery (kill switch SWITCHROOM_FRAMEWORK_ORIGIN_ROUTING).
 * Resolve the turn that owns a reply from the message_id it QUOTES (args.reply_to),
 * via the source-message reverse index. Returns null when disabled, when reply_to
 * is absent/non-numeric, or when no turn owns that message id (evicted / unknown).
 * Deterministic: a real framework-stamped message_id → its turn, with no model
 * thread assertion and no dependence on the live currentTurn.
 *
 * SCOPED to `chatId`: Telegram numbers message ids PER CHAT, so the same numeric
 * id exists in a DM and a supergroup. The reverse index is keyed by id alone, so
 * the resolved turn MUST be confirmed to belong to this reply's chat — otherwise
 * a reply quoting its own id could inherit another chat's thread (a cross-chat
 * leak). On a chat mismatch we return null (decline to recover → fall through to
 * the live-turn behaviour), never a wrong-chat thread.
 */
function findTurnByQuotedMessageId(chatId: string, replyTo: unknown): CurrentTurn | null {
  if (!FRAMEWORK_ORIGIN_ROUTING_ENABLED) return null
  if (replyTo == null) return null
  const mid = Number(replyTo)
  if (!Number.isFinite(mid)) return null
  const owner = recentTurnIdBySourceMessageId.get(mid)
  if (owner == null) return null
  const turn = recentTurnsById.get(owner) ?? null
  if (turn == null || turn.sessionChatId !== chatId) return null
  return turn
}
/**
 * Component 3 — derive the stable per-turn identity from the chat, thread,
 * and originating message id. Stamped into the inbound meta at build time
 * (`origin_turn_id`) AND reconstructed at enqueue time from the same three
 * values, so the id stamped on the message the model reads matches the id
 * on the turn the gateway started for it. Using the message id (not the
 * not-yet-known startedAt) is what lets the two sites agree. Returns null
 * when there is no message id (synthetic / cron / handback turns have no
 * originating inbound — they never need origin routing, the live turn IS
 * the origin).
 */
function deriveTurnId(
  chatId: string,
  threadId: number | null | undefined,
  messageId: string | number | null | undefined,
): string | null {
  if (messageId == null || messageId === '' || String(messageId) === '0') return null
  return `${chatKey(chatId, threadId ?? null)}#${messageId}`
}

/**
 * Component 3 — resolve the turn that OWNS a reply by its `origin_turn_id`
 * (the meta field the model echoes back from the channel tag). Checks the
 * live turn first, then the recently-ended registry. Returns null when the
 * id is absent or unknown (a model that didn't echo it, or a turn evicted
 * from the bounded registry) — callers then fall back to the existing
 * turn-pinned / chatThreadMap precedence.
 */
function findTurnByOriginId(originTurnId: string | null | undefined): CurrentTurn | null {
  if (originTurnId == null || originTurnId === '') return null
  // PR-4e — resolve the LIVE turn by ITS OWN topic key under the flag. The
  // turnId encodes the key: `deriveTurnId` builds `${chatKey}#${messageId}`, so
  // the substring before `#` IS the statusKey. Flag-ON does an O(1)
  // `byKey.get(key)` and matches on turnId — so a reply whose origin turn is
  // STILL live for topic A resolves A even after the singleton mirror flipped to
  // B. Flag-OFF keeps the singleton check, verbatim. The recentTurnsById
  // registry fallback is UNCHANGED in both branches.
  if (EMISSION_AUTHORITY_ENABLED) {
    const hashIdx = originTurnId.indexOf('#')
    if (hashIdx > 0) {
      const live = currentTurnMap.get(originTurnId.slice(0, hashIdx))
      if (live != null && live.turnId === originTurnId) return live
    }
  } else if (currentTurn != null && currentTurn.turnId === originTurnId) {
    return currentTurn
  }
  return recentTurnsById.get(originTurnId) ?? null
}

// Late-reply topic recovery (2026-06-05 marko triage). Default ON; kill switch
// SWITCHROOM_LATE_REPLY_TOPIC_RECOVERY=0 restores the legacy behaviour (a late
// reply with no echoed origin and no live turn defaults to General).
const LATE_REPLY_TOPIC_RECOVERY_ENABLED =
  process.env.SWITCHROOM_LATE_REPLY_TOPIC_RECOVERY !== '0'

/**
 * The most-recently-started turn for a chat from the bounded recently-ended
 * registry — the deterministic fallback for a LATE answer reply when the model
 * echoed no `origin_turn_id` and `currentTurn` has already cleared. Iterates in
 * insertion order so the last match is the most recent turn for that chat.
 * Returns null when the chat has no remembered turn (so the caller keeps the
 * legacy result). NB: this is the chat's own most-recent TURN, not the
 * `chatThreadMap` last-seen-any-message heuristic that caused the wrong-topic
 * bug — a late reply almost always belongs to the turn that just ended.
 */
function findLatestEndedTurnForChat(chatId: string): CurrentTurn | null {
  let latest: CurrentTurn | null = null
  for (const t of recentTurnsById.values()) {
    if (t.sessionChatId === chatId) latest = t
  }
  return latest
}

/**
 * Resolve the answer-reply thread AND emit `reply-route` telemetry. The
 * 2026-06-05 triage showed reply routing was the blind spot: `reply: invoked`
 * logged only chat + char count, so a late reply landing in the wrong topic was
 * invisible without hand-correlating raw tg-post threads against turn-lifecycle
 * timestamps. This wrapper logs, per reply: which precedence tier won (`via`),
 * the resolved thread, the origin turn + its thread, and whether the reply was
 * late (turn already ended). `via=recovered` marks a late reply this fix saved
 * from General; `via=quoted` marks an origin recovered from the framework-owned
 * quoted message_id (no model echo); `UNROUTED` flags a supergroup reply that
 * resolved to no topic with NO owner turn to attribute it to (genuinely lost).
 * `MISROUTE_RISK` flags the irreducible determinism residual: a no-echo,
 * no-quote reply that fell to the LIVE turn while a DIFFERENT topic recently had
 * a turn — the framework cannot tell which topic the bare reply answers, so the
 * routing MIGHT be wrong (HOLE a). It is observability only (the reply still
 * routes to the live turn) — it makes the one case that is genuinely
 * model-dependent visible instead of silently mis-routed. A General-topic turn
 * legitimately has no thread, so its replies are NOT UNROUTED-flagged.
 *
 * `originVia` distinguishes how the origin turn was resolved: 'echo' (model
 * echoed origin_turn_id), 'quoted' (framework recovered it from args.reply_to),
 * or null (no origin turn). It only affects the `via` label, never the routing.
 */
function resolveAnswerThreadWithLog(
  chatId: string,
  explicitThreadId: number | undefined,
  originTurn: CurrentTurn | null,
  originVia: 'echo' | 'quoted' | null,
  liveTurn: CurrentTurn | null,
  surface: 'reply' | 'stream_reply',
): number | undefined {
  // Recover ONLY for a genuinely LATE reply — no live turn at all. Gating on
  // `liveTurn?.sessionThreadId == null` (the original) also fired for a
  // threadless DM that still had a live turn, marking every DM reply
  // `via=recovered`/RECOVERED in the telemetry (routing result unchanged —
  // DM → undefined — but it drowned the real supergroup recoveries the marker
  // exists to surface). `liveTurn == null` is the precise late-reply condition.
  const recovered =
    LATE_REPLY_TOPIC_RECOVERY_ENABLED &&
    explicitThreadId == null &&
    originTurn == null &&
    liveTurn == null
      ? findLatestEndedTurnForChat(chatId)
      : null
  const threadId = resolveAnswerThreadId({
    explicitThreadId,
    originResolved: originTurn != null,
    originThreadId: originTurn?.sessionThreadId,
    liveThreadId: liveTurn?.sessionThreadId,
    liveTurnPresent: liveTurn != null,
    lastEndedResolvedForChat: recovered != null,
    lastEndedThreadIdForChat: recovered?.sessionThreadId,
    frameworkTopicAuthority: REPLY_TOPIC_AUTHORITY_ENABLED,
  })
  // `via` reflects the ACTIVE precedence so telemetry matches routing.
  const via = REPLY_TOPIC_AUTHORITY_ENABLED
    ? (originTurn != null ? (originVia === 'quoted' ? 'quoted' : 'origin')
      : liveTurn != null ? 'live'
      : explicitThreadId != null ? 'explicit'
      : recovered != null ? 'recovered'
      : 'none')
    : (explicitThreadId != null ? 'explicit'
      : originTurn != null ? (originVia === 'quoted' ? 'quoted' : 'origin')
      : liveTurn?.sessionThreadId != null ? 'live'
      : recovered != null ? 'recovered'
      : 'none')
  // Observability: the model passed an explicit topic but a framework anchor
  // (origin/live) overrode it. This is the deterministic correction that fixes
  // the General→CRM misroute; surface it so the model's topic-grabbing is
  // visible rather than silent.
  const explicitOverridden =
    REPLY_TOPIC_AUTHORITY_ENABLED &&
    explicitThreadId != null &&
    (originTurn != null || liveTurn != null) &&
    threadId !== explicitThreadId
  const ownerTurn = originTurn ?? recovered ?? liveTurn
  const isSupergroup = chatId.startsWith('-100')
  // UNROUTED = a supergroup reply that resolved to NO topic with NO owner turn
  // to attribute it to (genuinely lost). A General-topic turn legitimately has
  // no thread, so a reply owned by it resolving to `-` is CORRECT, not lost —
  // gate on `ownerTurn == null` so General replies don't false-alarm (found by
  // the multi-topic UAT stress, 2026-06-05).
  const unrouted = isSupergroup && threadId == null && ownerTurn == null
  // MISROUTE_RISK = the irreducible determinism residual (HOLE a). A no-echo,
  // no-quote reply fell to the LIVE turn (via=live), but a DIFFERENT topic
  // recently had a turn for this chat — so this bare reply MIGHT belong to that
  // other topic and we cannot tell without the model's echo. Observability only;
  // routing is unchanged. This is the one case framework state cannot
  // disambiguate, surfaced instead of silently mis-routed.
  const misrouteRisk =
    isSupergroup &&
    via === 'live' &&
    hasDifferentThreadedRecentTurn(chatId, liveTurn?.sessionThreadId)
  process.stderr.write(
    `telegram gateway: reply-route surface=${surface} chat=${chatId} ` +
      `resolved_thread=${threadId ?? '-'} via=${via} late=${liveTurn == null} ` +
      `originTurn=${ownerTurn?.turnId ?? '-'} origin_thread=${ownerTurn?.sessionThreadId ?? '-'}` +
      (via === 'recovered' ? ' RECOVERED' : '') +
      (via === 'quoted' ? ' QUOTED(framework-origin)' : '') +
      (unrouted ? ' UNROUTED(supergroup→no-topic)' : '') +
      (misrouteRisk ? ' MISROUTE_RISK(no-echo→live-successor)' : '') +
      (explicitOverridden
        ? ` EXPLICIT_OVERRIDDEN(model→${explicitThreadId},routed→${threadId ?? '-'})`
        : '') +
      '\n',
  )
  return threadId
}

/**
 * Determinism-residual detector (HOLE a observability). True when a DIFFERENT
 * forum topic recently had a turn for this chat than the live turn's thread —
 * i.e. a currentTurn flip plausibly happened, so a no-echo / no-quote reply
 * routed to the live turn MIGHT belong to the other topic. Scans the bounded
 * recently-ended registry; cheap (≤32 entries). Used only to ALARM, never to
 * route.
 */
function hasDifferentThreadedRecentTurn(
  chatId: string,
  liveThreadId: number | undefined,
): boolean {
  const live = liveThreadId ?? null
  for (const t of recentTurnsById.values()) {
    if (t.sessionChatId === chatId && (t.sessionThreadId ?? null) !== live) return true
  }
  return false
}

/**
 * PR2 obligation-ledger CLOSE. Called when a SUBSTANTIVE final answer lands
 * (not a bare interim ack — using finalAnswerSubstantive, the #2141 signal): the
 * obligation discharged is the one for the SAME origin the answer routes to
 * (origin_turn_id the model echoed, else the routed origin the gateway resolved,
 * else the live turn). So 713's reply closes 713's obligation even after
 * currentTurn flipped to 715, and 715 stays open until ITS own substantive
 * answer. Answers to re-presented obligations (via=quoted, no model echo) close
 * via the gateway-resolved routedOriginTurn. An ack does NOT close (so
 * ack-then-ghost is re-presented, not re-dropped). The live-turn fallback fires
 * only for the live turn's OWN obligation (it was the turn delivering this
 * reply), preserving the 713/715 invariant. No-op unless the flag is on.
 *
 * @param routedOriginTurn — the origin the reply router already resolved
 *   (echoedTurn ?? quotedTurn); pass whenever the TURN_ORIGIN_ROUTING path ran.
 *   Skipped when null/undefined (pre-routing paths, or DM with no quote).
 */
function closeObligationOnSubstantiveReply(
  args: Record<string, unknown>,
  liveTurn: CurrentTurn | null | undefined,
  routedOriginTurn?: CurrentTurn | null,
): void {
  if (!OBLIGATION_LEDGER_ENABLED) return
  const echoed = findTurnByOriginId(args.origin_turn_id as string | undefined)
  // routedOriginTurn is the gateway-resolved origin (echoedTurn ?? quotedTurn).
  // Only pass it as routedOriginId when it DIFFERS from the echoed turn (if
  // echoed is present, resolveCloseTarget's first branch already handles it),
  // and only when it is NOT the live turn (live-turn is the fallback, not the
  // routed origin — passing live turn here would bypass the live-turn fallback
  // logic and still close correctly, but naming matters for the 713/715 case:
  // the routed origin on a via=quoted reply IS the origin, not "live fallback").
  const routedOriginId =
    routedOriginTurn != null && echoed == null
      ? routedOriginTurn.turnId
      : null
  const target = obligationLedger.resolveCloseTarget(echoed?.turnId, liveTurn?.turnId, routedOriginId)
  if (target != null) obligationLedger.close(target)
}

/**
 * PR2 obligation-ledger OPEN. Track a fresh user inbound as an unanswered
 * obligation the moment it is received — called BEFORE the buffer-until-idle /
 * deliver split so a mid-turn cross-topic inbound (the 715 case: buffered while
 * another turn runs) is tracked too. Drain paths re-deliver buffered inbounds
 * via sendToAgent (NOT through handleInbound), so handleInbound is the ONLY
 * point that sees every fresh inbound — opening here is mandatory for both
 * branches. Same gate as delivery-tracking (real user turns only; synthetic /
 * steering / `!` interrupt / empty excluded — they have no origin id / need no
 * answer; deriveTurnId null-guards them). Idempotent → opening at buffer-time
 * and any later delivery is safe. No-op unless the flag is on.
 */
function openObligationFromInbound(
  inboundMsg: InboundMessage,
  gate: { isSteering: boolean; isInterrupt: boolean; effectiveText: string },
): void {
  if (!OBLIGATION_LEDGER_ENABLED) return
  if (
    !shouldTrackDelivery({
      isSteering: gate.isSteering,
      isInterrupt: gate.isInterrupt,
      hasSource: inboundMsg.meta?.source != null,
      effectiveText: gate.effectiveText,
    })
  ) {
    return
  }
  const oid = deriveTurnId(inboundMsg.chatId, inboundMsg.threadId, inboundMsg.messageId)
  if (oid == null) return
  obligationLedger.openIfAbsent({
    originTurnId: oid,
    chatId: inboundMsg.chatId,
    threadId: inboundMsg.threadId,
    messageId: inboundMsg.messageId,
    text: inboundMsg.text ?? '',
    openedAt: Date.now(),
  })
}

/**
 * Component 5 — post a "Queued — replying in another topic first" status
 * into a cross-topic buffered message's OWN topic. Fire-and-forget through
 * the swallowing wrapper (carries message_thread_id so it lands in the
 * right topic). Suppressed for DMs and same-topic queues by the CALLER.
 * Records the sent message id keyed by chatKey(chatId, bufferedThread) for
 * the later edit (Hook B) / delete (Hook C / reap).
 */
function postQueuedStatus(chatId: string, bufferedThread: number, inFlightThread: number | undefined): void {
  if (!QUEUED_STATUS_UX_ENABLED) return
  const key = statusKey(chatId, bufferedThread)
  // Idempotent: a second buffered message in the same topic re-uses the
  // existing placeholder (don't stack).
  if (queuedStatusMsgIds.has(key)) return
  const otherTopic = inFlightThread != null ? `another topic` : `another conversation`
  const text = `⏳ Queued — replying in ${otherTopic} first, then I'll get to this.`
  void (async () => {
    const sent = await swallowingApiCall(
      () =>
        // Queued-placeholder status, not the user's answer — silence the
        // open ping (BORDERLINE: it's a "your message is queued" notice;
        // see PR description).
        bot.api.sendMessage(chatId, text, { message_thread_id: bufferedThread, disable_notification: true }),
      { chat_id: chatId, verb: 'queued-status.post', threadId: bufferedThread },
    )
    const messageId = (sent as { message_id?: number } | undefined)?.message_id
    if (typeof messageId !== 'number') return
    // Re-check after the await: the turn may have already started and
    // edited/deleted via Hook B/C in the gap. If the key is now occupied
    // by a different placeholder, delete this orphan; otherwise record it.
    if (queuedStatusMsgIds.has(key)) {
      void swallowingApiCall(
        () => bot.api.deleteMessage(chatId, messageId),
        { chat_id: chatId, verb: 'queued-status.post-race-cleanup', threadId: bufferedThread },
      )
      return
    }
    queuedStatusMsgIds.set(key, { chatId, threadId: bufferedThread, messageId })
  })()
}

/**
 * Component 5 (Hook B) — the buffered message's turn just STARTED. Edit the
 * queued placeholder in its topic to "On it — replying now." Best-effort.
 */
function promoteQueuedStatus(chatId: string, thread: number | undefined): void {
  if (!QUEUED_STATUS_UX_ENABLED) return
  if (thread == null) return
  const key = statusKey(chatId, thread)
  const entry = queuedStatusMsgIds.get(key)
  if (entry == null) return
  // editMessageText targets a specific message id, which already implies
  // its thread — grammy's typed signature has no message_thread_id (the
  // swallowingApiCall opts still carry threadId for the deleted-topic
  // fallback policy).
  void swallowingApiCall(
    () =>
      bot.api.editMessageText(chatId, entry.messageId, '✍️ On it — replying now.', {}),
    { chat_id: chatId, verb: 'queued-status.promote', threadId: thread },
  )
}

/**
 * Component 5 (Hook C / reap) — the answer landed (or the turn ended
 * abnormally). Delete the queued placeholder and drop the map entry so the
 * topic shows the real answer, never a stale "Queued" line. Idempotent.
 */
function reapQueuedStatus(chatId: string, thread: number | undefined): void {
  const key = statusKey(chatId, thread ?? null)
  const entry = queuedStatusMsgIds.get(key)
  if (entry == null) return
  queuedStatusMsgIds.delete(key)
  void swallowingApiCall(
    () => bot.api.deleteMessage(chatId, entry.messageId),
    { chat_id: chatId, verb: 'queued-status.reap', ...(entry.threadId != null ? { threadId: entry.threadId } : {}) },
  )
}

// Problem B — deferred safe-boundary interrupt.
//
// `toolFlightTracker` mirrors the session-event stream to know whether a
// top-level tool call is open right now (an unsafe point to SIGINT). When the
// `interrupt.safe_boundary` flag is on and a `!` lands mid-tool-call, we don't
// fire the SIGINT — we stash the fully-built replacement inbound here and fire
// it (SIGINT + deliver) at the next clean boundary (tool_result drains the
// last open tool, or turn_end), or when the max-wait timer expires. Rapid
// repeated `!` while one is pending coalesce: the latest body replaces the
// stashed inbound, the original deadline is preserved (bounded wait).
const toolFlightTracker = new ToolFlightTracker()

interface PendingDeferredInterrupt {
  agentName: string
  inboundMsg: InboundMessage
  chatId: string
  msgId: number | null
  threadId: number | undefined
  registeredAt: number
  deadlineTimer: ReturnType<typeof setTimeout>
}
let pendingDeferredInterrupt: PendingDeferredInterrupt | null = null

/**
 * Fire a stashed deferred interrupt: SIGINT the (now safely-bounded) turn via
 * tmux, then deliver the replacement body as a fresh inbound — the same two
 * primitives the synchronous `!` path uses, just gated on a clean boundary.
 * Idempotent: nulls the slot and clears the timer before doing any work so a
 * boundary event and the timeout can't double-fire.
 */
/**
 * An `!` interrupt SIGINT-kills the in-flight turn. That turn was handling a
 * user message with an open obligation, and the killed turn does NOT reliably
 * emit turn_end (so endCurrentTurnAtomic never closes it) — so without this the
 * obligation survives and the idle sweep later re-presents/escalates "you have
 * an earlier message you never answered" for a question the user EXPLICITLY
 * cancelled. An interrupt is a deliberate redirect, so closing that obligation
 * is the correct terminal (the user chose to interrupt; they can re-ask). Only
 * the interrupted turn's OWN obligation is closed — queued siblings (other open
 * obligations) are untouched. No-op when the flag is off, no turn is in flight,
 * or the turn isn't a tracked obligation (synthetic / already closed).
 */
function cancelInterruptedObligation(): void {
  if (!OBLIGATION_LEDGER_ENABLED) return
  const turn = currentTurn
  if (turn == null) return
  if (obligationLedger.close(turn.turnId)) {
    process.stderr.write(
      `telegram gateway: obligation cancelled by interrupt origin=${turn.turnId}\n`,
    )
  }
}

async function fireDeferredInterrupt(reason: 'boundary' | 'timeout'): Promise<void> {
  const pending = pendingDeferredInterrupt
  if (pending == null) return
  pendingDeferredInterrupt = null
  clearTimeout(pending.deadlineTimer)

  const waitedMs = Date.now() - pending.registeredAt
  process.stderr.write(
    `telegram gateway: deferred-interrupt firing reason=${reason} agent=${pending.agentName} ` +
    `chat=${pending.chatId} waited_ms=${waitedMs} in_flight=${toolFlightTracker.inFlightCount()}\n`,
  )

  try {
    const { sendAgentInterrupt } = await import('../../src/agents/tmux.js')
    const r = sendAgentInterrupt({ agentName: pending.agentName })
    if ('ok' in r) {
      process.stderr.write(
        `telegram gateway: deferred-interrupt SIGINT delivered via tmux send-keys agent=${pending.agentName}\n`,
      )
    } else {
      process.stderr.write(
        `telegram gateway: deferred-interrupt SIGINT via tmux failed agent=${pending.agentName}: ${r.error}\n`,
      )
    }
  } catch (err) {
    process.stderr.write(`telegram gateway: deferred-interrupt SIGINT failed: ${(err as Error).message}\n`)
  }

  // The SIGINT just killed the in-flight turn — cancel its obligation so the
  // interrupted (user-redirected) question isn't re-presented/escalated later.
  cancelInterruptedObligation()

  // Deliver the replacement body as a fresh turn to the freshly-killed
  // bridge — same sendToAgent + buffer-on-miss primitive the synchronous
  // interrupt carve-out uses at the handleInbound delivery site.
  const delivered = ipcServer.sendToAgent(pending.agentName, pending.inboundMsg)
  if (delivered) {
    markClaudeBusyForInbound(pending.inboundMsg)
  } else {
    pendingInboundBuffer.push(pending.agentName, pending.inboundMsg)
    process.stderr.write(
      `telegram gateway: deferred-interrupt body buffered (bridge miss) agent=${pending.agentName} chat=${pending.chatId}\n`,
    )
  }
}

// #549 fix — preamble suppression for the answer-stream path.
//
// Background: assistant text emitted before a tool_use is "preamble"
// (think-out-loud guidance about what's about to happen). The
// progress-card driver consumes preamble as a narrative row for the
// upcoming tool. Independently, the answer-stream path was sending the
// same text to chat as a standalone message — user saw it twice (#549).
//
// The buffering policy lives in `preamble-suppressor.ts` so it can be
// unit-tested without spinning the whole gateway. The suppressor's
// `emitAnswer` callback is what bridges back to `activeAnswerStream` —
// when text is promoted from "pending" to "answer text", we update the
// stream with the cumulative answer-only payload (excluding preamble).
const preambleSuppressor = new PreambleSuppressor({
  emitAnswer: (cumulative) => {
    // Re-reads currentTurn at call time on purpose: the suppressor is
    // long-lived and flushes can occur outside any session-event
    // handler's scope. If the turn has been cleared, the update is
    // dropped (no chat to send to, no stream to mutate).
    //
    // PR-4e — the module-scope suppressor carries NO per-topic key (it is a
    // single global instance reset/flushed per turn), so there is no key to
    // scope by here: the correct resolution under BOTH flag states is the
    // most-recent-set live turn — exactly the singleton mirror `currentTurn`.
    // The per-turn `reset()` / `flushNow()` / `dropNow()` lifecycle (driven from
    // the live turn's own handlers) keeps the suppressor aligned with whichever
    // topic is currently live, so the mirror read is byte-identical to base and
    // cannot leak A's answer text into B (a flush for A runs while A is still the
    // most-recent turn; once B flips, A's stream is already force-superseded).
    const stream = currentTurn?.answerStream ?? null
    if (stream != null) stream.update(cumulative)
  },
})

/**
 * Telegram chat-id convention: positive ids are private chats (DM with a
 * user; chat.id === user.id). Negative ids are groups, supergroups, or
 * channels. Used to pick the answer-stream transport without an extra
 * getChat round-trip.
 */
function isDmChatId(chatId: string | null | undefined): boolean {
  if (!chatId) return false
  const id = Number(chatId)
  return Number.isFinite(id) && id > 0
}

// Phase 1 of #332: extract the plain-text body from the channel XML wrapper
// produced by the Telegram MCP plugin. The wrapper looks like:
//   <channel source="telegram" chat_id="..." ...>user text here</channel>
// We strip the outer tag and return a ~200-char preview for the turns table.
const TURN_PREVIEW_MAX = 200
function extractUserPromptPreview(rawContent: string): string | null {
  const m = rawContent.match(/<channel[^>]*>([\s\S]*?)<\/channel>/)
  const body = m ? m[1].trim() : rawContent.trim()
  if (!body) return null
  return body.length > TURN_PREVIEW_MAX ? body.slice(0, TURN_PREVIEW_MAX) : body
}

const CONTEXT_EXHAUSTION_COOLDOWN_MS = 10 * 60 * 1000
let lastContextExhaustionWarningAt = 0

let pendingPtyPartial: string | null = null

// statusKey + streamKey are thin re-exports of the canonical chatKey()
// constructor (see telegram-plugin/gateway/chat-key.ts). chatKey()
// collapses 0/null/undefined thread IDs to the same token (`_`),
// closing the sibling-key class behind #1564 (where one site set the
// entry under `null → _` and another cleared under `0 → 0`, leaving
// activeTurnStartedAt non-empty forever).
function statusKey(chatId: string, threadId?: number | null): string {
  return chatKey(chatId, threadId)
}

function streamKey(chatId: string, threadId?: number | null): string {
  return chatKey(chatId, threadId)
}

// PR1 (cross-turn stale-card guard, design §9 lever 4 / race C/D).
// `obligationSweep` writes one entry here, keyed on the obligation's
// `originTurnId`, the instant it pushes an `obligation_represent` inbound —
// carrying the obligation's `openedAt` (when the obligation was RAISED). The
// represent inbound reuses the obligation's chat/thread/messageId, so the
// `enqueue` that spawns the synthetic represent turn reconstructs the SAME
// `deriveTurnId` value as the key. That represent turn — and ONLY that turn —
// consumes and clears it, stamping `turn.crossTurnGate = { sinceMs: openedAt }`.
// That turn's first card-OPEN then consults `hasOutboundDeliveredSince(chat,
// openedAt)` and is suppressed iff a SUBSTANTIVE answer already landed since the
// obligation was raised — so a "thinking…" card never narrates beneath an answer
// the user already received in the original turn. Keying on `originTurnId` (not
// chat/thread) means an unrelated later foreground turn on the same chat/thread
// derives a different turn id, finds no entry, and is never mis-gated — closing
// the residual cross-contamination window where a represent that was armed but
// never enqueued (degenerate bridge-death) left a stale chat/thread-keyed gate
// that the next foreground turn could wrongly consume. A normal foreground turn
// never has an entry here, so the gate stays scoped to the synthetic surface.
// The map holds at most one entry per obligation; re-arming the same obligation
// overwrites its own entry with the latest openedAt.
const pendingCrossTurnGate = new Map<string, { sinceMs: number }>()

/**
 * Component 1 — deliver-before-drain. The single chokepoint that both
 * turn-end drain sites (`purgeReactionTracking`, `releaseTurnBufferGate`)
 * route through. Drains the pending-inbound buffer ONLY when
 * `mayDrainBufferedInbound` says so: claude is idle AND (the
 * serialize-until-replied kill switch is off, OR there is no ending-turn
 * handle, OR the ending turn delivered its final answer). A no-reply turn
 * (finalAnswerDelivered=false) deliberately does NOT drain here — the
 * bounded escape-hatch timer in `endCurrentTurnAtomic` covers that
 * liveness case. The 300s silence-poke fallback (`redeliverBufferedInbound`
 * called directly, bypassing this gate) remains the long-stop.
 */
function performBufferDrain(reason: string): void {
  const selfAgentForFlush = process.env.SWITCHROOM_AGENT_NAME ?? ''
  if (pendingInboundBuffer.depth(selfAgentForFlush) <= 0) return
  const fr = redeliverBufferedInbound(
    pendingInboundBuffer,
    selfAgentForFlush,
    (m) => {
      const d = ipcServer.sendToAgent(selfAgentForFlush, m)
      if (d) markClaudeBusyForInbound(m)
      return d
    },
    inboundSpool,
    trackRedeliveredInbound,
  )
  if (fr.redelivered > 0) {
    process.stderr.write(
      `telegram gateway: ${reason} flushed ${fr.redelivered}/${fr.drained} ` +
      `held inbound for ${selfAgentForFlush}` +
      `${fr.rebuffered > 0 ? ` (${fr.rebuffered} re-buffered)` : ''}\n`,
    )
  }
}

function drainBufferedIfAllowed(endingTurn: CurrentTurn | undefined, reason: string): void {
  if (
    !mayDrainBufferedInbound({
      turnInFlight: turnInFlightForGate(),
      endingTurnFinalAnswerDelivered: endingTurn?.finalAnswerDelivered ?? null,
      enabled: SERIALIZE_UNTIL_REPLIED_ENABLED,
    })
  ) {
    return
  }
  performBufferDrain(reason)
}

/**
 * Component 2 — bounded no-reply escape hatch (THE liveness guarantee).
 *
 * A turn that legitimately ends with NO reply (handback ack, NO_REPLY /
 * HEARTBEAT_OK marker, silent-end, greeting already handled) sets
 * `finalAnswerDelivered=false`. Under component 1's serialize gate that
 * turn would block `drainBufferedIfAllowed` FOREVER — and the 300s
 * silence-poke is disarmed for these silent-end turns, so without this
 * timer a queued cross-topic message would never be released (a permanent
 * wedge). This timer is the bounded force-drain: SERIALIZE_NOREPLY_DRAIN_MS
 * (default 2500ms) after such a turn ends with a buffered inbound waiting,
 * drain unconditionally — the serialize gate's delivered-check is bypassed
 * because the turn ended for real with no reply coming. The drain still
 * respects `turnInFlightForGate()` indirectly: if a new turn started in the
 * window (e.g. the 300s fallback or another path drained first), the buffer
 * is already empty so `performBufferDrain` is a depth-checked no-op.
 *
 * Liveness proof: a no-reply turn followed by a queued cross-topic message
 * releases within SERIALIZE_NOREPLY_DRAIN_MS. The 300s silence-poke
 * unwedge fallback (`redeliverBufferedInbound` at the silence-poke
 * framework-fallback, called directly) remains the independent long-stop.
 */
function armNoReplyDrainTimer(turn: CurrentTurn): void {
  const selfAgent = process.env.SWITCHROOM_AGENT_NAME ?? ''
  // Pure guard (shared with the test): arm only for a no-reply turn that
  // has a buffered inbound waiting, and only when the feature is enabled.
  if (
    !shouldArmNoReplyDrain({
      enabled: SERIALIZE_UNTIL_REPLIED_ENABLED,
      finalAnswerDelivered: turn.finalAnswerDelivered,
      bufferedDepth: pendingInboundBuffer.depth(selfAgent),
    })
  ) {
    return
  }
  // Idempotent: clear any prior timer for this turn before re-arming.
  if (turn.noReplyDrainTimer != null) {
    clearTimeout(turn.noReplyDrainTimer)
    turn.noReplyDrainTimer = null
  }
  turn.noReplyDrainTimer = setTimeout(() => {
    turn.noReplyDrainTimer = null
    process.stderr.write(
      `telegram gateway: no-reply bounded drain (${SERIALIZE_NOREPLY_DRAIN_MS}ms) — ` +
      `turn ${turn.turnId} ended without a reply; force-draining buffered inbound\n`,
    )
    performBufferDrain('no-reply-bounded-drain')
  }, SERIALIZE_NOREPLY_DRAIN_MS)
  turn.noReplyDrainTimer.unref?.()
}

function purgeReactionTracking(key: string, endingTurn?: CurrentTurn): void {
  // Phase 2b: turn end. The key was registered via setTurnStarted when
  // the inbound arrived; purge is the canonical turn-end signal.
  //
  // outboundEmitted: read from the explicit `endingTurn` parameter when
  // provided (canonical path via endCurrentTurnAtomic — module-scope
  // currentTurn is already null by the time we get here), falling back
  // to `currentTurn?.replyCalled` for the legacy callsites that haven't
  // been threaded yet (sibling-key purges, restart-init cleanup).
  // Without this explicit-turn handoff the shadow trace would report
  // outboundEmitted=false on every replied turn (the dominant happy
  // path), producing strictly worse data than the blind `true` it
  // replaced. Invariant #5's `lastOutboundAt` correctness depends on
  // this signal being accurate.
  const outboundEmitted = endingTurn != null
    ? endingTurn.replyCalled === true
    : currentTurn?.replyCalled === true
  shadowEmit({ kind: 'turnEnd', key: key as _ChatKey, at: Date.now(), outboundEmitted })
  const msgInfo = activeReactionMsgIds.get(key)
  activeStatusReactions.delete(key)
  activeReactionMsgIds.delete(key)
  activeTurnStartedAt.delete(key)
  // Component 5 (reap) — defense-in-depth. The happy path deletes the
  // queued-status placeholder on the answer (executeReply / stream /
  // turn-flush). This catches the abnormal turn-end (silent-marker, wedge,
  // sibling purge) so a stale "Queued"/"On it" line can never dangle in
  // the topic. Idempotent: a no-op when already reaped. Prefer the ending
  // turn's session ids (canonical ownership); else parse the chatKey.
  if (endingTurn != null) {
    reapQueuedStatus(endingTurn.sessionChatId, endingTurn.sessionThreadId)
  } else {
    const pqChatId = chatIdOfChatKey(key as _ChatKey)
    const pqThreadPart = (key as string).slice(pqChatId.length + 1)
    const pqThread = pqThreadPart === '_' || pqThreadPart === '' ? null : Number(pqThreadPart)
    reapQueuedStatus(pqChatId, Number.isFinite(pqThread) ? (pqThread as number) : undefined)
  }
  // PR3b: clear the parallel-turns fleet-gate entry. Symmetric with
  // the markClaudeBusyForInbound on the delivery path. Safe no-op
  // when the key was never marked (synthetic purge from a sweep).
  claudeBusyKeys.delete(key)
  // #2527: clear the per-key reaction-transition counter and first-reply
  // sentinel alongside the controller so we don't leak state across turns.
  reactionTransitionCounts.delete(key)
  firstTextReplyLogged.delete(key)
  // Human-feel UX: stop the turn-long `typing…` indicator started in
  // the turn-start block. `purgeReactionTracking` is the canonical
  // turn-end, so this is the single owner of the stop. (If an abnormal
  // abort skips purge, the stray loop self-heals: the next turn on this
  // chat calls `startTurnTypingLoop`, which stops the old interval
  // first.)
  // PR3 supergroup-mode: stop the per-(chat,thread) typing loop, not
  // the whole chat's. Prefer the ending-turn's session ids (the
  // canonical turn ownership); fall back to parsing the chatKey
  // for sibling-purge / restart-cleanup callers that don't have a
  // Turn handle.
  if (endingTurn != null) {
    stopTurnTypingLoop(endingTurn.sessionChatId, endingTurn.sessionThreadId ?? null)
  } else {
    const chatId = chatIdOfChatKey(key as _ChatKey)
    const threadPart = (key as string).slice(chatId.length + 1)
    const threadId = threadPart === '_' || threadPart === '' ? null : Number(threadPart)
    stopTurnTypingLoop(chatId, Number.isFinite(threadId) ? threadId : null)
  }
  // Cancel the enqueue-time early-open timer (paired with
  // `scheduleEarlyLivenessOpen` at turn start). `key` is the same status-key the
  // timer was registered under, so this is the single owner of the cancel. A
  // leaked timer would otherwise fire its `openLivenessFeedIfDue` against a
  // successor turn; the timer's own turnId match is the second guard, this is
  // the first. Idempotent — a no-op when no timer is registered.
  stopEarlyLivenessOpen(key as string)
  // Status-pin: turn end is the canonical unpin point for the foreground
  // pin. `purgeReactionTracking` is the single turn-end owner (all normal /
  // abnormal exit branches funnel here), so this is the one place the
  // foreground status pin is dropped. Idempotent: a no-op when nothing was
  // pinned (trivial turn that never opened a status message). The
  // drop-on-unpin contract in reconcilePin guarantees state clears even if
  // the unpin API throws — a stuck pin can never outlive its turn.
  {
    const pinChatId = endingTurn != null
      ? endingTurn.sessionChatId
      : chatIdOfChatKey(key as _ChatKey)
    void reconcileStatusPin(`fg:${key}`, pinChatId, { pinned: false })
  }
  if (msgInfo) {
    const agentDir = resolveAgentDirFromEnv()
    if (agentDir != null) removeActiveReaction(agentDir, msgInfo.chatId, msgInfo.messageId)
  }

  // If no more active turns and a restart is pending, perform it now.
  //
  // Cycle BOTH the agent unit and the gateway unit (us). Rationale: users
  // who ran `switchroom agent restart <name> --graceful-restart` after a
  // code change expect their telegram-plugin edits to land, and that code
  // only reloads when this gateway process restarts. Restarting only the
  // agent unit leaves us running the stale code until something else kicks
  // us over, which is a foot-gun (as observed on 2026-04-21 when a
  // klanker gateway ran pre-reorder progress-card code for half a day).
  //
  // Use detached spawn for the combined restart so the systemctl job
  // survives us getting killed by our own restart. Fire-and-forget;
  // response to the client was already sent when the restart was
  // scheduled, so nobody is waiting on this.
  //
  // PR3b: gated on `claudeBusyKeys.size`, not `activeTurnStartedAt.size`,
  // so a buffered topic-B inbound (which had eagerly set its own
  // activeTurnStartedAt entry in the fresh-turn branch) doesn't pin this
  // gate forever while claude is genuinely idle. See the claudeBusyKeys
  // declaration for the supergroup deadlock this fixes.
  // PR3b-cutover: `turnInFlightForGate()` reads the delivery machine
  // when the cutover kill-switch is on; the turnEnd event was emitted
  // just above (purgeReactionTracking head), so the machine is already
  // idle here.
  // #1556: the deterministic delivery point. claude has just gone idle —
  // flush any inbound held mid-turn so the channel notification lands at
  // the idle prompt and submits as a fresh turn (instead of stranding in
  // the composer, the lawgpt wedge). Component 1 (deliver-before-drain):
  // routed through `drainBufferedIfAllowed`, which additionally gates on
  // the ending turn having delivered its reply so a buffered cross-topic
  // message can't drain ahead of the just-ended turn's late reply (the
  // Brevo→Meta wrong-topic bug). Zero-churn: the helper depth-checks
  // first. Lossless: redeliver re-buffers any per-message miss.
  drainBufferedIfAllowed(endingTurn, 'turn-complete')

  // Restart / compaction stay on the bare turn-end signal (NOT the
  // serialize gate): a pending self-restart or proactive compaction must
  // fire when claude is idle regardless of whether the last turn replied.
  if (!turnInFlightForGate()) {
    if (pendingRestarts.size > 0) {
      for (const [agentName, _timestamp] of pendingRestarts.entries()) {
        triggerSelfRestart(agentName, 'turn-complete-pending-restart');
        pendingRestarts.delete(agentName);
      }
    } else {
      // Strictly lower priority than a pending restart: if we just
      // kicked a restart the process is going away and compacting is
      // moot, so only evaluate when no restart drained this pass.
      maybeProactiveCompact();
    }
    // Context-headroom snapshot (RFC context-headroom-surface) — write the
    // current occupancy + cap so `switchroom status`/`doctor`/web can show
    // headroom. Independent of proactive-compaction (writes even when no cap
    // is configured) and best-effort (never throws). Runs on the same idle
    // signal — never mid-turn.
    snapshotContextOccupancy();
  }
}

/**
 * Write the per-agent context-occupancy snapshot from the same live occupancy
 * proactive-compaction reads — but unconditionally (even with no cap set), so
 * the operator always sees headroom. Best-effort; never throws.
 */
function snapshotContextOccupancy(): void {
  try {
    const agentName = process.env.SWITCHROOM_AGENT_NAME;
    const file = lastSessionActiveFile;
    if (!agentName || !file) return;
    const turns = readTurnUsages(file, 1);
    if (turns.length === 0) return;
    const t = turns[0];
    const occupancy = t.input + t.cacheRead + t.cacheCreate;
    let cap: number | null = null;
    try {
      const cfg = loadSwitchroomConfig();
      const rawAgent = cfg.agents?.[agentName] ?? {};
      const resolved = resolveAgentConfig(cfg.defaults, cfg.profiles, rawAgent);
      cap = resolved.session?.max_context_tokens ?? null;
    } catch {
      cap = null; // config unreadable → show occupancy without a ratio
    }
    const stateDir = process.env.SWITCHROOM_AGENT_STATE_DIR ?? "/state/agent";
    writeContextOccupancySnapshot(
      stateDir,
      buildContextOccupancy(occupancy, cap, Date.now()),
    );
  } catch {
    /* best-effort — never disrupt the idle gate */
  }
}

/**
 * Narrow buffer-gate release. Clears the per-key
 * `activeTurnStartedAt` entry and triggers the held-inbound flush
 * if the fleet went idle, WITHOUT touching the reaction
 * controller, the active-reaction message-id, or the typing loop.
 *
 * Why split from `purgeReactionTracking`. #1718's contract keeps
 * `activeStatusReactions[key]` alive across the turn so the
 * working-state ladder can re-paint on every tool/thinking event
 * (and the steer-vs-queue logic at the inbound handler reads the
 * controller — gateway.ts:8322-8323 — to classify mid-turn
 * messages). Wiping the controller mid-turn would either collapse
 * the ladder to 👍 prematurely (#1713 regression) or break the
 * steer detection.
 *
 * The BUFFER gate (`activeTurnStartedAt`) is a separate concern:
 * it gates `shouldBufferInbound` (gateway.ts:8603) and the
 * "claude is idle" flush at `purgeReactionTracking`'s tail. The
 * #1728/#1729 fix released both halves together by gating on
 * `isFinalAnswerReply`, but a trivial-prompt reply that sets
 * `disable_notification: true` and is < 200 chars (e.g. the model
 * mis-classifies "4" as an interim ack) returns false from
 * `isFinalAnswerReply`, so neither half releases and the gate
 * wedges (v0.13.30 UAT regression — every subsequent inbound logs
 * `held mid-turn ... will flush on turn-complete` forever).
 *
 * `releaseTurnBufferGate` is called from `executeReply` on EVERY
 * successful reply finalize — regardless of `isFinalAnswerReply` —
 * so the buffer gate releases independently of the reaction
 * state. The reaction controller stays for #1713's bidirectional
 * ladder + steer detection; only the gate flips.
 *
 * Idempotent: a second release is a no-op `.delete()` on an
 * already-empty key.
 *
 * @internal exported only via the `gateway.ts` module — used by
 * `executeReply`'s post-send block and by tests via source-level
 * pinning in `vault-approval-posture.test.ts` / wedge-guard suites.
 */
function releaseTurnBufferGate(key: string, endingTurn?: CurrentTurn): void {
  if (!activeTurnStartedAt.has(key)) return
  activeTurnStartedAt.delete(key)
  // PR3b: keep claudeBusyKeys in sync — same lifecycle as the
  // activeTurnStartedAt entry it's mirroring here.
  claudeBusyKeys.delete(key)
  // Shadow trace so the structural turn-end metric still records.
  // outboundEmitted=true is correct here — we only reach this from
  // executeReply AFTER an outbound landed.
  shadowEmit({ kind: 'turnEnd', key: key as _ChatKey, at: Date.now(), outboundEmitted: true })

  // Mirror the deterministic-delivery flush from `purgeReactionTracking`.
  // When the fleet hits zero-active-turns, drain any held inbound. This is
  // the load-bearing wedge fix: the gate that pinned msg 1874+ in
  // test-harness's 13:02 UAT now opens after the reply.
  //
  // Component 1 (deliver-before-drain): routed through the shared
  // `drainBufferedIfAllowed`. `releaseTurnBufferGate` is called on EVERY
  // reply finalize — interim ack AND final answer. The serialize gate
  // checks `endingTurn.finalAnswerDelivered`, so an INTERIM ack ("On it")
  // does NOT drain the cross-topic buffer (its turn hasn't delivered its
  // real answer yet); only the final-answer reply releases it. That is
  // exactly the serialize-until-replied contract. When the kill switch is
  // off, or no turn handle is threaded, the helper falls back to the
  // legacy drain-on-idle behaviour.
  drainBufferedIfAllowed(endingTurn, 'reply-released-gate')
}

/**
 * Atomic null-and-purge for a wedged turn. Every site that ends a
 * turn by nulling `currentTurn` MUST also clear the turn's statusKey
 * from `activeTurnStartedAt` — else a dangling entry survives and
 * `#1556`'s turn-gate holds every new inbound mid-turn forever
 * (gymbro / klanker held-mid-turn symptom, 2026-05-20).
 *
 * Pre-this, three turn-end paths (silent-marker / turn-flush /
 * `turn_end`) nulled `currentTurn` on code-paths whose
 * `purgeReactionTracking` calls weren't reached on every branch,
 * leaving sibling entries under the turn's statusKey that the
 * silence-poke framework-fallback's `purgeReactionTracking(fbKey)`
 * couldn't catch (different key shape). The fallback now also sweeps
 * siblings for `fbChatId` (`turn-state-purge.ts`) as defense-in-depth,
 * but THIS helper closes the leak at origin: null and purge are
 * inseparable at every call site.
 *
 * Idempotent: a second purge is a no-op `.delete()` on a key already
 * gone — handlers that already purge elsewhere are unharmed.
 */
function emitTurnRecord(turn: CurrentTurn, endedAt: number): void {
  try {
    const rec =
      JSON.stringify({
        ts: Math.floor(endedAt / 1000),
        agent: process.env.SWITCHROOM_AGENT_NAME ?? 'unknown',
        duration_ms: turn.startedAt > 0 ? endedAt - turn.startedAt : 0,
        tools: turn.toolCallCount ?? 0,
        status: turn.finalAnswerDelivered ? 'complete' : 'no_reply',
        turn_id: turn.turnId,
      }) + '\n'
    const turnsPath = '/state/agent/turns.jsonl'
    // Size-cap rotation: keep at most one rotated generation so the file can't
    // grow unbounded on a long-lived agent. Best-effort (never throws).
    maybeRotate(turnsPath, {
      statSize: (p) => {
        try {
          return statSync(p).size
        } catch {
          return undefined
        }
      },
      rename: (from, to) => renameSync(from, to),
    })
    appendFileSync(turnsPath, rec)
  } catch {
    // best-effort — never let metrics emission break turn teardown
  }
}

function endCurrentTurnAtomic(turn: CurrentTurn): void {
  // PR-4e — keyed liveness + keyed clear (leak-close-at-origin). Flag-OFF: the
  // guard is `currentTurn === turn` and the clear nulls the singleton, verbatim.
  // Flag-ON: the guard becomes `byKey.get(turn'sKey) === turn` (so a flip to
  // another topic doesn't spuriously short-circuit THIS topic's teardown) and
  // the clear does `byKey.delete(key)` + nulls the mirror iff it still points at
  // `turn`. `endCurrentTurnForKey` returns false (no delete) when the entry no
  // longer matches — the same early-return semantics as the old `!== turn` guard.
  const key = statusKey(turn.sessionChatId, turn.sessionThreadId)
  if (!turnLiveForItsTopic(turn)) return
  endCurrentTurnForKey(turn, key) // currentTurnByKey.delete(key) + mirror clear
  // Status-surface observability: one line at every turn CLEAR (with how far
  // the turn got), plus a DEGRADED warning when the turn did tool work but the
  // live feed never opened because its sends failed (the resume-400 signature).
  const turnEndedAt = Date.now()
  process.stderr.write(
    `telegram gateway: ${formatTurnLifecycle('clear', 'turn_end', turn, turnEndedAt)}\n`,
  )
  emitTurnRecord(turn, turnEndedAt)
  const degraded = detectStatusSurfaceDegraded(turn)
  if (degraded != null) {
    process.stderr.write(
      `telegram gateway: status-surface DEGRADED reason=${degraded.reason} ` +
        `turnId=${turn.turnId} chat=${turn.sessionChatId} ` +
        `thread=${turn.sessionThreadId ?? '-'} ${degraded.detail}\n`,
    )
  }
  // PR2 obligation-ledger CLOSE-at-turn-end. Close the ended turn's obligation
  // when it delivered a final answer. finalAnswerDelivered is the right signal
  // HERE (not isSubstantiveFinalReply at reply-time): a SHORT genuine answer
  // ("4") is final-but-not-substantive, so the reply-time substantive-close
  // missed it → it looked unanswered → the idle sweep double-asked every short
  // turn (canary, v0.14.59). At turn_end the #2141 logic has already demoted a
  // bare interim ack to non-final, so finalAnswerDelivered===true means GENUINELY
  // answered. This runs before the next idle sweep, so a short answer closes
  // cleanly (no double-ask); an ack-then-ghost / no-reply turn ends with
  // finalAnswerDelivered===false → stays open → re-presented (the intended
  // catch). close() is a no-op for synthetic turns (turnId not in the ledger).
  // No-op when the flag is off.
  //
  // #2624 — sr-* model short-reply cascade fix. When the model routes through
  // LiteLLM (sr-* path), the claude CLI calls reply("OK", {disable_notification:
  // true}) for short answers — below the 200-char backstop and notification-
  // suppressed, so isFinalAnswerReply returns false and finalAnswerDelivered stays
  // false. This triggers a cascade: obligation re-presents with growing 25k-token
  // context, blocking the agent for minutes. The ack-then-ghost case that
  // obligations are designed to catch ends via silence_fallback, NOT turn_end.
  // At turn_end with replyCalled=true the model explicitly signalled completion
  // AND replied, so the obligation is satisfied regardless of finalAnswerDelivered.
  if (OBLIGATION_LEDGER_ENABLED) {
    if (decideObligationTurnEnd(turn.finalAnswerDelivered, turn.replyCalled) === 'close') {
      obligationLedger.close(turn.turnId)
    } else {
      // Turn ended WITHOUT any reply (no ack, no answer). If this turn was
      // handling an open obligation, stamp its grace clock so the idle sweep
      // waits before re-presenting/escalating. No-op when turn.turnId isn't
      // in the ledger (synthetic / already-closed turn).
      obligationLedger.noteTurnEnded(turn.turnId, Date.now())
    }
  }
  // Component 2 — clear any prior no-reply drain timer for this turn; a
  // fresh end re-evaluates below. (Idempotent — null when never armed.)
  if (turn.noReplyDrainTimer != null) {
    clearTimeout(turn.noReplyDrainTimer)
    turn.noReplyDrainTimer = null
  }
  // Pass `turn` so purgeReactionTracking sees the authoritative
  // replyCalled flag even though we just nulled module-scope
  // currentTurn. Without this, the shadow trace's outboundEmitted
  // would be false on every replied turn (the dominant happy path),
  // producing strictly worse data than the blind `true` it replaced.
  // Component 1: purgeReactionTracking runs the serialize-gated drain —
  // it drains only if this turn delivered its final answer.
  purgeReactionTracking(statusKey(turn.sessionChatId, turn.sessionThreadId), turn)
  // Component 2 — bounded no-reply escape hatch. If this turn ended
  // WITHOUT delivering (finalAnswerDelivered=false) the serialize gate
  // above did NOT drain. Arm the bounded timer so a queued cross-topic
  // message still releases within SERIALIZE_NOREPLY_DRAIN_MS instead of
  // wedging forever. No-op when this turn delivered, when nothing is
  // buffered, or when the serialize feature is off.
  armNoReplyDrainTimer(turn)
}

/**
 * Model-idle proactive-compaction check. Called ONLY from the
 * activeTurnStartedAt.size === 0 gate above (never mid-turn). Opt-in via
 * the resolved agent config's session.max_context_tokens; a no-op when
 * unset, so a fresh `switchroom setup` is unchanged.
 *
 * Occupancy = the latest usage-bearing assistant turn's
 * input + cache_read + cache_creation tokens (the prefix the model
 * actually re-read this turn ≈ current window fill). readTurnUsages(_,1)
 * returns exactly that single turn and skips tool-only / usage-less
 * lines, so we never under-count off a sub-line.
 *
 * Note (accepted, benign): there is a check-to-send race — a new inbound
 * could set activeTurnStartedAt between this idle check and the async
 * tmux send. A `/compact` that lands as a new turn starts is queued in
 * claude's prompt buffer and runs at the next idle prompt (see the
 * FUTURE-GAP note in src/agents/inject.ts); it is not a mid-generation
 * injection. We do not claim size===0 is atomic.
 */
function maybeProactiveCompact(): void {
  if (compactDispatching) return;

  const agentName = process.env.SWITCHROOM_AGENT_NAME;
  if (!agentName) return;

  let cap: number | undefined;
  try {
    const cfg = loadSwitchroomConfig();
    // Resolve through the cascade so a fleet-wide
    // `defaults.session.max_context_tokens` applies even when the agent
    // has no explicit per-agent session block (rawAgent → {}).
    const rawAgent = cfg.agents?.[agentName] ?? {};
    const resolved = resolveAgentConfig(cfg.defaults, cfg.profiles, rawAgent);
    cap = resolved.session?.max_context_tokens;
  } catch {
    // Best-effort — config may be unreadable in odd boot states; a
    // failed read just means "no proactive compaction this pass".
    return;
  }
  if (cap == null || cap <= 0) return; // opt-in: unset → native compaction only

  const file = lastSessionActiveFile;
  if (!file) return;

  const turns = readTurnUsages(file, 1);
  if (turns.length === 0) return;
  const t = turns[0];
  const occupancy = t.input + t.cacheRead + t.cacheCreate;

  const wasArmed = compactState.armed;
  const decision = decideProactiveCompact(compactState, occupancy, cap);
  compactState = decision.state;
  // Re-arm edge: the decider only flips disarmed→armed when post-
  // /compact occupancy fell below 0.6×cap — i.e. context verifiably
  // shrank. That edge is the honest "compaction finished" signal.
  const rearmed = !wasArmed && decision.state.armed;

  // User-facing notification transitions (pure). Resolved synchronously
  // here — before any await and before the !fire return — so a
  // re-entrant purge pass can't double-post (compactState was already
  // persisted/disarmed above). All card I/O is reached only past the
  // `cap == null` opt-in return earlier in this function, so a fleet
  // with the feature off never posts anything (Defaults preserved).
  const nt = nextCompactNotify(compactNotifyState, {
    fired: decision.fire,
    rearmed,
    activeFile: file,
  });
  compactNotifyState = nt.state;
  if (nt.action === 'finish') {
    void resolveCompactCard('finished', occupancy);
  } else if (nt.action === 'start' || nt.action === 'start-superseding') {
    if (nt.action === 'start-superseding') {
      void resolveCompactCard('superseded', occupancy);
    }
    void postCompactCard(occupancy, cap);
    // #1713: compaction is a reflective working state — paint ✍ on
    // every in-flight inbound's status reaction so the user can see
    // the agent is doing compaction work, not stuck. Non-terminal:
    // post-compact transitions back to thinking/tool resume normally.
    for (const ctrl of activeStatusReactions.values()) {
      ctrl.setCompacting()
    }
  }

  if (!decision.fire) return;

  // Set the re-entrancy guard synchronously BEFORE the await so a
  // re-entrant purge pass can't double-dispatch (the decider already
  // disarmed + armed the cooldown in decision.state).
  compactDispatching = true;
  process.stderr.write(
    `telegram gateway: proactive /compact for ${agentName} ` +
      `(occupancy=${occupancy} >= cap=${cap})\n`,
  );
  void injectSlashCommandImpl(agentName, '/compact')
    .catch((err: unknown) => {
      process.stderr.write(
        `telegram gateway: proactive /compact inject failed for ` +
          `${agentName}: ${err instanceof Error ? err.message : String(err)}\n`,
      );
    })
    .finally(() => {
      compactDispatching = false;
    });
}

// ─── Idle auto-clear ──────────────────────────────────────────────────────
// Wall-clock idle → /clear (idle-clear.ts). Independent of proactive-compact
// (occupancy-driven at the turn-end gate): a fully-idle agent never ends a
// turn, so this runs on its own interval. Any activity (inbound / turn start /
// cron fire) resets the timer via markIdleActivity(); fires once per idle
// period; never mid-turn (turnInFlightForGate, the same gate compaction uses).
let lastIdleActivityAt = Date.now();
let idleAutoCleared = false;
let idleClearDispatching = false;

/** Reset the idle timer + re-arm auto-clear. Call on ANY activity. */
function markIdleActivity(): void {
  lastIdleActivityAt = Date.now();
  idleAutoCleared = false;
}

/** Idle window in ms: env override → per-agent config → 3h default. 0 disables. */
function resolveIdleClearMs(): number {
  const env = process.env.SWITCHROOM_IDLE_CLEAR_MS;
  if (env != null && env !== '') {
    const n = Number(env);
    return Number.isFinite(n) && n >= 0 ? n : DEFAULT_IDLE_CLEAR_MS;
  }
  try {
    const agentName = process.env.SWITCHROOM_AGENT_NAME;
    if (!agentName) return DEFAULT_IDLE_CLEAR_MS;
    const cfg = loadSwitchroomConfig();
    const rawAgent = cfg.agents?.[agentName] ?? {};
    const resolved = resolveAgentConfig(cfg.defaults, cfg.profiles, rawAgent);
    const raw = resolved.session?.idle_clear_after;
    if (raw == null) return DEFAULT_IDLE_CLEAR_MS; // unset → on by default (3h)
    const ms = idleDurationToMs(raw);
    return ms == null ? DEFAULT_IDLE_CLEAR_MS : ms;
  } catch {
    return DEFAULT_IDLE_CLEAR_MS; // config unreadable → keep the default on
  }
}

/** Evaluate idle auto-clear (runs on IDLE_CLEAR_CHECK_MS interval). */
function maybeIdleClear(): void {
  if (idleClearDispatching) return;
  const agentName = process.env.SWITCHROOM_AGENT_NAME;
  if (!agentName) return;
  const idleClearMs = resolveIdleClearMs();
  const decision = decideIdleClear(
    {
      lastActivityAt: lastIdleActivityAt,
      idleClearMs,
      alreadyCleared: idleAutoCleared,
      turnInFlight: turnInFlightForGate(),
    },
    Date.now(),
  );
  if (!decision.clear) return;
  // Fire once per idle period — set BEFORE the await so the next tick can't
  // double-dispatch. markIdleActivity() re-arms on the next real activity.
  idleAutoCleared = true;
  idleClearDispatching = true;
  process.stderr.write(
    `telegram gateway: idle auto-/clear for ${agentName} ` +
      `(idle >= ${Math.round(idleClearMs / 60_000)}m)\n`,
  );
  // Accepted check-to-send race (same as maybeProactiveCompact): a new inbound
  // could arrive between the gate check and the tmux send; /clear then lands in
  // claude's prompt buffer and runs at the next idle prompt (inject.ts FUTURE-GAP).
  void injectSlashCommandImpl(agentName, '/clear')
    .catch((err: unknown) => {
      process.stderr.write(
        `telegram gateway: idle /clear inject failed for ` +
          `${agentName}: ${err instanceof Error ? err.message : String(err)}\n`,
      );
    })
    .finally(() => { idleClearDispatching = false; });
}

/**
 * Post the START card for a proactive compaction. Best-effort: a failed
 * send just means no card (the compaction itself still happens). The
 * outstanding record + a wall-clock timeout are armed so the card can
 * never dangle if the re-arm edge never arrives (failed/idle case).
 */
async function postCompactCard(occ: number, cap: number): Promise<void> {
  try {
    const chatId = loadAccess().allowFrom[0];
    if (!chatId) return;
    // PR4b-compact: supergroup-owned agents route the compaction card
    // into the `alerts` alias topic (or default_topic_id fallback) so
    // operators see lifecycle/system events in a predictable lane
    // instead of conversation lanes. Fleet/DM agents fall through to
    // the existing chatThreadMap last-seen-thread fallback (no
    // observable change).
    // The compact-watchdog topic is valid ONLY in the agent's supergroup;
    // attaching it to an operator DM recipient 400s "message thread not found"
    // and the notice silently vanishes (the marko #2096 class — proactiveCompact
    // was the one operator-send still missing this guard, 2026-06-05). DM
    // recipients get a thread-less send; the supergroup owner keeps the lane.
    const threadId = topicForRecipient({
      recipientChatId: chatId,
      resolvedTopic:
        resolveAgentOutboundTopic({ kind: 'compact-watchdog' })
        ?? chatThreadMap.get(chatId),
      supergroupChatId: resolveAgentSupergroupChatId(),
    });
    const text =
      `🗜️ **Context compaction**\n` +
      `Working context hit ~${occ.toLocaleString()} tokens ` +
      `(cap ${cap.toLocaleString()}) — running \`/compact\`. ` +
      `Older detail moves to Hindsight; I'll confirm here once the ` +
      `context has shrunk (may take a turn or two).`;
    const sent = await swallowingApiCall(
      () =>
        bot.api.sendRichMessage(chatId, richMessage(text), {
          ...(threadId != null ? { message_thread_id: threadId } : {}),
        }),
      { chat_id: chatId, verb: 'proactiveCompact.start' },
    );
    const messageId = (sent as { message_id?: number } | undefined)
      ?.message_id;
    if (typeof messageId !== 'number') return;
    const timer = setTimeout(() => {
      void resolveCompactCard('timeout', null);
    }, COMPACT_CARD_TIMEOUT_MS);
    timer.unref?.();
    outstandingCompactCard = {
      chatId,
      threadId,
      messageId,
      occAtStart: occ,
      capAtStart: cap,
      timer,
    };
  } catch (err) {
    process.stderr.write(
      `telegram gateway: proactive-compact start card failed: ` +
        `${err instanceof Error ? err.message : String(err)}\n`,
    );
  }
}

/**
 * Resolve the outstanding START card to a terminal state by editing it
 * in place. `finished` is driven by the decider re-arm edge (context
 * verifiably shrank), `superseded` when a newer compaction starts first,
 * `timeout` by the wall-clock timer (re-arm never arrived). The
 * outstanding record + timer are cleared synchronously BEFORE the await
 * so a stale message_id can never be edited twice and the timer can't
 * double-fire. On `timeout` the pure notify state is also reset so a
 * future compaction starts a clean lifecycle.
 */
async function resolveCompactCard(
  kind: 'finished' | 'superseded' | 'timeout',
  occNow: number | null,
): Promise<void> {
  const card = outstandingCompactCard;
  if (!card) return;
  outstandingCompactCard = null;
  clearTimeout(card.timer);
  if (kind === 'timeout') compactNotifyState = idleCompactNotifyState();
  let text: string;
  if (kind === 'finished') {
    text =
      `✅ **Context compacted**\n` +
      `Working context reduced` +
      (occNow != null
        ? ` (~${card.occAtStart.toLocaleString()} → ` +
          `~${occNow.toLocaleString()} tokens)`
        : '') +
      `. Hindsight retains the detail.`;
  } else if (kind === 'superseded') {
    text =
      `↩️ **Context compaction superseded**\n` +
      `A newer compaction started before this one confirmed.`;
  } else {
    text =
      `⚠️ **Compaction issued**\n` +
      `\`/compact\` was requested but the context isn't ` +
      `confirmed reduced yet. Native compaction and Hindsight still apply.`;
  }
  try {
    await swallowingApiCall(
      () =>
        bot.api.editMessageText(card.chatId, card.messageId, richMessage(text), {
        }),
      { chat_id: card.chatId, verb: `proactiveCompact.${kind}` },
    );
  } catch (err) {
    process.stderr.write(
      `telegram gateway: proactive-compact ${kind} card edit failed: ` +
        `${err instanceof Error ? err.message : String(err)}\n`,
    );
  }
}

/**
 * Terminal-only reaction helper — routes through `finalize()` per #1713.
 *
 * Only the `turn_end` IPC handler, disconnect-flush, and boot-sweep
 * should call this. Mid-turn replies and stream-done events are
 * NON-EVENTS for the reaction (the reaction reflects current turn
 * activity, not delivery state). See `reference/know-what-my-agent-is-
 * doing.md` for the user-perceived contract.
 */
function finalizeStatusReaction(
  chatId: string,
  threadId: number | undefined,
  reason: 'done' | 'undelivered' | 'error' = 'done',
): void {
  const key = statusKey(chatId, threadId)
  const ctrl = activeStatusReactions.get(key)
  if (!ctrl) return
  // Don't paint the terminal 👍 while a background sub-agent worker is
  // still running — it reads as "done / nothing happening" even though
  // the text said work continues. `tryDefer` holds the working glyph
  // (✍️/⚡) and registers the controller; the watcher's onFinish promotes
  // it to 👍 once the last worker completes. Errors are terminal
  // regardless: a failed/aborted turn shouldn't wait on a worker.
  if (reason === 'done' && deferredDoneReactions.tryDefer(key, ctrl)) return
  deferredDoneReactions.drop(key)
  ctrl.finalize(reason)
  // #2527: log controller dispose so the lifecycle end is observable. Use
  // activeReactionMsgIds to reconstruct the turnId token before purge clears it.
  const msgInfo = activeReactionMsgIds.get(key)
  if (msgInfo != null) {
    logStreamingEvent({
      kind: 'status_reaction_dispose',
      chatId,
      turnId: `${chatId}:${msgInfo.messageId}`,
      reason,
    })
  }
  purgeReactionTracking(key)
}

/**
 * Count sub-agent workers currently running (excludes historical
 * boot-leftover entries and any already-terminal worker). The registry
 * deletes terminal entries after a short grace, so a worker that has
 * fired its `done`/`failed` onFinish no longer counts here.
 */
function countRunningWorkers(): number {
  // Prefer the dispatch-time DB count: a background worker's row is INSERTed
  // `status='running'` when its `Agent` tool_use fires, i.e. BEFORE the parent
  // turn ends. The registry below is populated by on-disk file discovery, which
  // lags dispatch by a poll/fswatch tick — so a just-dispatched worker was
  // invisible to the deferred-done gate and the 👍 promoted prematurely.
  const dbCount = subagentWatcher?.countRunningBackgroundWorkers?.()
  if (dbCount != null) return dbCount
  const reg = subagentWatcher?.getRegistry()
  if (reg == null) return 0
  let n = 0
  for (const e of reg.values()) {
    if (e.state === 'running' && !e.historical) n++
  }
  return n
}

/**
 * Non-terminal error paint (😱). Distinct from `finalize('error')` —
 * recovery to a working state is allowed after this (#1713). Mid-turn
 * 5xx surfaces use this; the terminal turn_end handler decides whether
 * the turn actually ends in error.
 */
function paintStatusReactionError(chatId: string, threadId: number | undefined): void {
  const key = statusKey(chatId, threadId)
  const ctrl = activeStatusReactions.get(key)
  if (!ctrl) return
  ctrl.setError()
}

/**
 * Flip the current turn's status reaction off 🙏 (awaiting-approval) back
 * to a working glyph once a permission verdict has been dispatched. The
 * turn was suspended *inside* the bridge's permission call, so `currentTurn`
 * still points at it; the verdict un-parks claude and it resumes the SAME
 * turn. `setThinking()` re-arms the stall watchdog that `setAwaiting()`
 * suspended, so a genuine post-approval hang still promotes to 🥱/😨, and
 * it is replaced by the real tool glyph (✍/⚡) as soon as the resumed turn
 * fires its next PreToolUse. Non-terminal — 👍 still waits for `turn_end`.
 */
function resumeReactionAfterVerdict(): void {
  const turn = currentTurn
  if (turn == null) return
  activeStatusReactions
    .get(statusKey(turn.sessionChatId, turn.sessionThreadId))
    ?.setThinking()
}

/**
 * The recipient set for a permission card (the initial Approve/Deny card
 * AND the post-verdict resume message — they MUST route identically, so
 * both go through this one helper).
 *
 * Turn-initiated (the normal case — a permission gate fires mid-tool-use
 * with an active turn): send to the ORIGINATING chat+thread. For a
 * supergroup-owned agent working in a forum topic that is the supergroup +
 * the topic, so the card lands IN the topic the operator asked from (e.g.
 * marko's "CRM (Brevo)" topic) — not the operator's DM. For a DM agent the
 * originating chat IS the operator's DM (thread-less), unchanged.
 *
 * No active turn (cron / background / a swept turn at TTL): fall back to the
 * configured operator DMs (`allowFrom`), thread-stripped via
 * `topicForRecipient` so a DM never gets a `message_thread_id` (the 400
 * "message thread not found" → auto-deny wedge, #2096).
 *
 * Before this helper the INITIAL card emitter iterated `allowFrom`
 * unconditionally, so a supergroup card could only ever reach operator DMs —
 * the topic chat id is never in `allowFrom`. The resume message already
 * routed correctly; the card now matches it (marko, 2026-06-03).
 */
function resolvePermissionCardTargets(): Array<{ chatId: string; threadId: number | undefined }> {
  const turn = currentTurn
  if (turn != null) {
    return [{ chatId: turn.sessionChatId, threadId: turn.sessionThreadId }]
  }
  // currentTurn was nulled — most commonly because the orphaned-reply backstop
  // force-closed the turn while the single claude session kept running and then
  // hit a permission-gated tool (e.g. a retry after a first card auto-denied:
  // marko Rentals-budget, 2026-06-17). Recover the originating topic from the
  // recently-started turn registry so the card lands where the operator is
  // working, instead of fanning out to operator DMs (thread-stripped) where it
  // sits unseen until the 10-min TTL auto-denies it. Kill switch (=0) restores
  // the legacy DM fan-out.
  if (PERMISSION_CARD_ORIGIN_RECOVERY_ENABLED) {
    const recovered = pickRecoveredPermissionOrigin(
      recentTurnsById.values(),
      Date.now(),
      PERMISSION_CARD_ORIGIN_MAX_AGE_MS,
    )
    if (recovered != null) {
      process.stderr.write(
        `telegram gateway: permission-card origin recovered from recent turn ` +
        `chat=${recovered.chatId} thread=${recovered.threadId ?? '-'} ` +
        `(currentTurn was null — force-closed turn)\n`,
      )
      return [recovered]
    }
  }
  const sg = resolveAgentSupergroupChatId()
  const topic = resolveAgentOutboundTopic({
    kind: 'permission',
    turnInitiated: false,
    originThreadId: undefined,
  })
  // allowFrom is normally operator DMs — attach the topic only to a
  // recipient that owns it (the supergroup), never a DM (marko wedge).
  return loadAccess().allowFrom.map(chatId => ({
    chatId,
    threadId: topicForRecipient({ recipientChatId: chatId, resolvedTopic: topic, supergroupChatId: sg }),
  }))
}

/**
 * Post the agent-voiced "got your verdict — continuing" message the
 * instant the operator answers a permission card. Travels right beside
 * `resumeReactionAfterVerdict()` at every operator-driven verdict site so
 * the legible signal (a distinct message naming the work) can't drift away
 * from the reaction flip — the same 5-paths-drift hazard #2019 guards.
 *
 * The card edit + 🙏→working reaction are easy to miss (a reaction lands on
 * the turn's triggering message far up the chat; the card footnote is a
 * one-liner). This message is the thing the operator actually sees.
 *
 * Posts to the suspended turn's chat/thread (`currentTurn` still points at
 * it mid-gate — the same controller `resumeReactionAfterVerdict` addresses)
 * so it lands in the conversation the gate belongs to; falls back to the
 * configured operator chats when there's no active turn (e.g. a swept turn
 * at TTL-sweep time). Kill-switch: `SWITCHROOM_RESUME_MSG=0`.
 */
function postPermissionResumeMessage(opts: {
  behavior: 'allow' | 'deny'
  action: string
  timeoutMinutes?: number
}): void {
  if (process.env.SWITCHROOM_RESUME_MSG === '0') return
  const text = formatPermissionResumeMessage({
    agentName: process.env.SWITCHROOM_AGENT_NAME ?? null,
    behavior: opts.behavior,
    action: opts.action,
    timeoutMinutes: opts.timeoutMinutes,
  })
  const targets = resolvePermissionCardTargets()
  for (const { chatId, threadId } of targets) {
    // allow-raw-bot-api: wrapped in swallowingApiCall (retry policy); thread-aware send
    void swallowingApiCall(
      () =>
        bot.api.sendRichMessage(chatId, richMessage(text), {
          ...(threadId != null ? { message_thread_id: threadId } : {}),
        }),
      { chat_id: chatId, verb: 'permission-resume', ...(threadId != null ? { threadId } : {}) },
    )
  }
}

function resolveThreadId(chat_id: string, explicit?: string | number | null): number | undefined {
  if (explicit != null) return Number(explicit)
  return chatThreadMap.get(chat_id)
}

/**
 * Background probe that populates `chatAvailableReactions` for `chatId`
 * via `getChat`. Fire-and-forget — never blocks the caller. Coalesces
 * concurrent probes via `chatProbesInFlight`. Failure (rate limit, no
 * permission, network) leaves the cache empty so subsequent messages
 * fall back to the "no filter" path (current production behavior).
 *
 * Closes #542 — see chatAvailableReactions block comment for rationale.
 */
function probeAvailableReactions(chatId: string): void {
  if (chatAvailableReactions.has(chatId)) return
  if (chatProbesInFlight.has(chatId)) return
  chatProbesInFlight.add(chatId)
  void (async () => {
    try {
      const chat = await bot.api.getChat(chatId)
      // Telegram convention: `available_reactions` undefined ⇒ "all
      // emoji reactions allowed" (no filter). Explicit array ⇒ this
      // exact set is permitted; everything else is rejected.
      //
      // Cache `null` for the "no filter" case. The controller also
      // treats null as "no filter" — both meanings converge to the
      // same call site behaviour, which is intentional. `has(chatId)`
      // distinguishes "probed and got null" from "never probed" so
      // we don't re-probe forever.
      const reactions = chat.available_reactions
      if (reactions == null) {
        chatAvailableReactions.set(chatId, null)
      } else {
        const allowed = new Set<string>()
        for (const r of reactions) {
          if (r.type === 'emoji') allowed.add(r.emoji)
          // ReactionTypeCustomEmoji and ReactionTypePaid are skipped —
          // the StatusReactionController only emits standard emoji.
        }
        chatAvailableReactions.set(chatId, allowed)
        process.stderr.write(
          `telegram gateway: probed available_reactions chatId=${chatId} count=${allowed.size}\n`,
        )
      }
    } catch (err) {
      // Don't poison the cache on transient failure — leave the entry
      // unset so the next message retries.
      process.stderr.write(
        `telegram gateway: available_reactions probe failed chatId=${chatId} ${(err as Error).message}\n`,
      )
    } finally {
      chatProbesInFlight.delete(chatId)
    }
  })()
}

// ─── Text chunking ────────────────────────────────────────────────────────
const PHOTO_EXTS = new Set(['.jpg', '.jpeg', '.png', '.gif', '.webp'])

function chunk(text: string, limit: number, mode: 'length' | 'newline'): string[] {
  if (text.length <= limit) return [text]
  const out: string[] = []
  let rest = text
  while (rest.length > limit) {
    let cut = limit
    if (mode === 'newline') {
      const para = rest.lastIndexOf('\n\n', limit)
      const line = rest.lastIndexOf('\n', limit)
      const space = rest.lastIndexOf(' ', limit)
      cut = para > limit / 2 ? para : line > limit / 2 ? line : space > 0 ? space : limit
    }
    out.push(rest.slice(0, cut))
    rest = rest.slice(cut).replace(/^\n+/, '')
  }
  if (rest) out.push(rest)
  return out
}

// ─── Typing indicator ─────────────────────────────────────────────────────
// All four state maps re-keyed from `chat_id` to `chatKey(chat, thread)`
// in PR3 of the supergroup-mode rollout. In supergroup mode one agent
// owns many topics in one chat; chatId-only keying meant topic A's
// typing indicator died when topic B's tool call ended (last-stop-wins
// on a shared key). Per-(chat,thread) keying preserves independent
// typing loops across topics. Callers without thread context pass
// `null` and behave exactly as before (chatKey collapses null→`_`).
const typingIntervals = new Map<string, ReturnType<typeof setInterval>>()
// Track pending backoff-retry timers so shutdown and stop can cancel them.
const typingRetryTimers = new Map<string, ReturnType<typeof setTimeout>>()
let typingBackoffMs = 0
const TYPING_BACKOFF_MAX = 5 * 60 * 1000

/**
 * Telegram Bot API allowed chat actions. Each describes a different
 * "the bot is doing X" indicator the client renders next to the chat
 * title — far more informative than a generic "typing…" when the
 * agent is uploading a document or recording a voice note. See
 * https://core.telegram.org/bots/api#sendchataction.
 */
const CHAT_ACTION_WHITELIST = new Set([
  'typing',
  'upload_photo',
  'record_video',
  'upload_video',
  'record_voice',
  'upload_voice',
  'upload_document',
  'choose_sticker',
  'find_location',
  'record_video_note',
  'upload_video_note',
] as const)
type ChatAction = typeof CHAT_ACTION_WHITELIST extends Set<infer T> ? T : never

function startTypingLoop(
  chat_id: string,
  thread_id: number | null = null,
  action: ChatAction = 'typing',
): void {
  stopTypingLoop(chat_id, thread_id)
  const key = chatKey(chat_id, thread_id) as string
  const sendOpts = thread_id != null ? { message_thread_id: thread_id } : undefined
  const send = () => {
    bot.api.sendChatAction(chat_id, action, sendOpts).then(
      () => { typingBackoffMs = 0 },
      (err) => {
        const msg = err instanceof Error ? err.message : String(err)
        if (msg.includes('401') || msg.includes('Unauthorized')) {
          typingBackoffMs = Math.min(Math.max(typingBackoffMs * 2 || 1000, 1000), TYPING_BACKOFF_MAX)
          stopTypingLoop(chat_id, thread_id)
          const retry = setTimeout(() => {
            typingRetryTimers.delete(key)
            startTypingLoop(chat_id, thread_id, action)
          }, typingBackoffMs)
          typingRetryTimers.set(key, retry)
        }
      },
    )
  }
  send()
  typingIntervals.set(key, setInterval(send, 4000))
}

function stopTypingLoop(chat_id: string, thread_id: number | null = null): void {
  const key = chatKey(chat_id, thread_id) as string
  const iv = typingIntervals.get(key)
  if (iv) { clearInterval(iv); typingIntervals.delete(key) }
  const retry = typingRetryTimers.get(key)
  if (retry) { clearTimeout(retry); typingRetryTimers.delete(key) }
}

// Turn-level `typing…` indicator. The lifecycle (immediate fire, 4 s refresh,
// stop-at-turn-end, no leak) lives in the testable `turn-typing-loop.ts`
// factory; the gateway just injects the real `sendChatAction` + `chatKey`.
// Deliberately a SEPARATE interval map from `typingIntervals` (the reply handler
// + tool-use typing wrapper share that one and freely stop it). If the turn loop
// lived in the shared map, a mid-turn reply's `finally { stopTypingLoop }` would
// kill it and the chat would go dark for the rest of the turn — the exact
// black-box gap this closes. The dedicated map (private to the factory) makes
// the turn loop structurally immune to those stops: only the canonical turn-end
// stop clears it. The redundant `typing` pings while a reply is mid-flight are
// harmless — same action, and sendChatAction is cheap.
const turnTypingLoop = createTurnTypingLoop({
  sendChatAction: (chat_id, thread_id) => {
    const sendOpts = thread_id != null ? { message_thread_id: thread_id } : undefined
    void bot.api.sendChatAction(chat_id, 'typing', sendOpts).catch(() => {})
  },
  chatKey: (chat_id, thread_id) => chatKey(chat_id, thread_id) as string,
})

function startTurnTypingLoop(chat_id: string, thread_id: number | null = null): void {
  turnTypingLoop.start(chat_id, thread_id)
}

function stopTurnTypingLoop(chat_id: string, thread_id: number | null = null): void {
  turnTypingLoop.stop(chat_id, thread_id)
}

const typingWrapper = createTypingWrapper({
  startTypingLoop,
  stopTypingLoop,
  isSurfaceTool: isTelegramSurfaceTool,
})

// ─── Robust API call wrapper ──────────────────────────────────────────────
// Extracted to telegram-plugin/retry-api-call.ts so it's unit-testable in
// isolation; the gateway just composes the pure policy with its own logger.
const robustApiCall = createRetryApiCall({
  log: (line) => process.stderr.write(line),
})

// Fire-and-forget wrapper for outbound surfaces that previously had
// `.catch(() => {})` directly on `bot.api.*` calls. Resolves to undefined
// (instead of crashing the gateway) on THREAD_NOT_FOUND, give-up, 403,
// and any non-benign error — logs a one-liner so the failure isn't
// completely silent. See #1075.
const swallowingApiCall = createSwallowingRetryApiCall(
  robustApiCall,
  (line) => process.stderr.write(line),
)

/**
 * Adapter factory for `startBootCard`'s `BotApiForBootCard` interface.
 *
 * Wraps each call through `robustApiCall` so flood-wait / not-found /
 * THREAD_NOT_FOUND are handled by the standard policy instead of bubbling
 * up to crash the boot path (#1075). `threadId` is the topic the card is
 * posted into; passed to retryApiCall opts so the wrapper can fall back
 * to the main chat on stale-thread 400s.
 *
 * Boot-card itself already wraps each send/edit in try/catch, so on the
 * THREAD_NOT_FOUND throw the card just logs and stops updating — which
 * is the correct UX: if the user deleted the topic, there's nothing to
 * edit anyway.
 */
function wrapBootCardApi(
  threadId: number | undefined,
): import('./boot-card.js').BotApiForBootCard {
  const opts = (chat_id: string): { threadId?: number; chat_id: string; verb: string } => ({
    chat_id,
    verb: 'boot-card',
    ...(threadId != null ? { threadId } : {}),
  })
  // #2669: card bodies are raw GFM markdown — send them via the
  // rich-message path. The card modules pass plain `opts` (no parse_mode).
  return {
    sendMessage: async (cid, text, sendOpts) => {
      const sent = await robustApiCall(
        () =>
          // allow-raw-bot-api: sendRichMessage routed through robustApiCall (not in the THREAD_NOT_FOUND blast pattern)
          lockedBot.api.sendRichMessage(
            cid,
            richMessage(text),
            sendOpts as Parameters<typeof lockedBot.api.sendRichMessage>[2],
          ),
        opts(cid),
      )
      return sent as { message_id: number }
    },
    editMessageText: (cid, mid, text, editOpts) =>
      robustApiCall(
        () =>
          lockedBot.api.editMessageText(
            cid,
            mid,
            richMessage(text),
            editOpts as Parameters<typeof lockedBot.api.editMessageText>[3],
          ),
        opts(cid),
      ) as Promise<unknown>,
    // Strict edit for the boot-card edit-in-place probe: distinguishes
    // "message gone" (→ 'gone', caller sends fresh) from a landed/identical
    // edit (→ 'edited'). robustApiCall SWALLOWS "message to edit not found"
    // to undefined (retry-api-call.ts), so this can't go through it — a
    // deliberate single-attempt raw edit that classifies the error itself.
    editMessageTextStrict: async (cid, mid, text, editOpts) => {
      type EditOpts = Parameters<Api['editMessageText']>[3]
      try {
        // allow-raw-bot-api: boot-card edit-in-place probe — must detect a deleted target, which the shared retry policy swallows.
        await lockedBot.api.editMessageText(cid, mid, richMessage(text), editOpts as EditOpts)
        return 'edited'
      } catch (err) {
        const desc =
          err instanceof GrammyError ? err.description : err instanceof Error ? err.message : String(err)
        // Content identical → message still exists; reuse it.
        if (typeof desc === 'string' && desc.toLowerCase().includes('not modified')) return 'edited'
        // Not found, or any other error → fall back to a fresh silent send.
        return 'gone'
      }
    },
  }
}

/**
 * Adapter factory for `createIssuesCardHandle`'s bot interface. Same
 * shape as `wrapBootCardApi` — wraps each call through `robustApiCall`
 * so THREAD_NOT_FOUND surfaces as an inspectable throw inside the card
 * handle's own try/catch (where it already logs + re-posts). Without the
 * wrapper, the raw grammY GrammyError previously bubbled and crashed
 * the gateway. See #1075.
 */
function wrapIssuesCardApi(
  threadId: number | undefined,
): import('../issues-card.js').BotApiForIssuesCard {
  const opts = (chat_id: string): { threadId?: number; chat_id: string; verb: string } => ({
    chat_id,
    verb: 'issues-card',
    ...(threadId != null ? { threadId } : {}),
  })
  // #2669: issues-card body is raw GFM markdown — send via the rich path.
  return {
    sendMessage: async (cid, text, sendOpts) => {
      const sent = await robustApiCall(
        () =>
          // allow-raw-bot-api: sendRichMessage routed through robustApiCall (not in the THREAD_NOT_FOUND blast pattern)
          lockedBot.api.sendRichMessage(
            cid,
            richMessage(text),
            sendOpts as Parameters<typeof lockedBot.api.sendRichMessage>[2],
          ),
        opts(cid),
      )
      return sent as { message_id: number }
    },
    editMessageText: (cid, mid, text, editOpts) =>
      robustApiCall(
        () =>
          lockedBot.api.editMessageText(
            cid,
            mid,
            richMessage(text),
            editOpts as Parameters<typeof lockedBot.api.editMessageText>[3],
          ),
        opts(cid),
      ) as Promise<unknown>,
    deleteMessage: (cid, mid) =>
      robustApiCall(() => lockedBot.api.deleteMessage(cid, mid), opts(cid)) as Promise<unknown>,
  }
}

// ─── Structured outbound log ──────────────────────────────────────────────
function logOutbound(
  path: 'reply' | 'stream_reply' | 'backstop' | 'pty_preview' | 'edit' | 'forward' | 'answer_lane',
  chatId: string, messageId: number | null, chars: number, extra?: string,
  opts?: { turnKey?: string; formatHint?: 'html' | 'markdownv2' | 'text'; textPreview?: string },
): void {
  const ts = new Date().toISOString()
  const turnKeyPart = opts?.turnKey ? ` turnKey=${opts.turnKey}` : ''
  const formatPart = opts?.formatHint ? ` formatHint=${opts.formatHint}` : ''
  const previewPart = opts?.textPreview
    ? ` text_preview="${opts.textPreview.replace(/\n/g, '\\n').slice(0, 80)}"`
    : ''
  process.stderr.write(
    `telegram gateway [outbound] ${ts} path=${path} chat=${chatId} ` +
    `msg_id=${messageId ?? 'pending'} chars=${chars}` +
    turnKeyPart + formatPart + previewPart +
    (extra ? ` ${extra}` : '') + '\n',
  )
}

// Issue #109: when a user types just "status" or "status?" they're asking
// because the live progress surface failed to communicate. Anchored regex,
// case-insensitive, optional trailing "?" — must be the entire body.
const STATUS_QUERY_RE = /^\s*status\??\s*$/i

// ─── Permission handling ──────────────────────────────────────────────────
const PERMISSION_REPLY_RE = /^\s*(y|yes|n|no)\s+([a-km-z]{5})\s*$/i
const pendingPermissions = new Map<string, { tool_name: string; description: string; input_preview: string; startedAt: number; card_text: string; cards: { chatId: string; messageId: number }[] }>()
// PERMISSION_TTL_MS / ttlForTool / the timed-out card builder now live in
// ./permission-timeout.ts (pure + unit-testable). hostd gated verbs get a
// 30-min window; everything else keeps the 10-min default.
// No-repeat-on-timeout (marko Rentals-budget loop, 2026-06-17). When a card
// auto-denies on TTL, the model is told it was a TIMEOUT (not a denial) so it
// doesn't retry; if it retries the identical (tool, input) anyway while the
// operator is still absent, we short-circuit-deny it WITHOUT posting a second
// card. `permissionTimeoutSignatures` maps signature → last-timeout epoch ms;
// it is cleared the moment the operator is active again (answers any card, or
// sends a message), so suppression only ever holds during genuine absence.
// Kill switch: SWITCHROOM_PERMISSION_NO_REPEAT=0.
const PERMISSION_NO_REPEAT_ENABLED =
  process.env.SWITCHROOM_PERMISSION_NO_REPEAT !== '0'
// Safety cap on how long a timed-out signature suppresses retries even if the
// operator-activity reset is somehow missed; the reset is the primary bound.
const PERMISSION_DUPLICATE_WINDOW_MS = 60 * 60_000
const permissionTimeoutSignatures = new Map<string, number>()
function clearPermissionTimeoutSuppression(reason: string): void {
  if (permissionTimeoutSignatures.size === 0) return
  const n = permissionTimeoutSignatures.size
  permissionTimeoutSignatures.clear()
  process.stderr.write(
    `telegram gateway: permission no-repeat suppression cleared (${n} sig(s)) — ${reason}\n`,
  )
}
// Permission/approval-card origin recovery (marko Rentals-budget, 2026-06-17).
// When `currentTurn` was force-closed by the orphaned-reply backstop but the
// claude session kept running into a permission-gated tool, recover the card's
// origin topic from the recently-started turn registry instead of fanning out
// to operator DMs. Kill switch: SWITCHROOM_PERMISSION_CARD_ORIGIN_RECOVERY=0.
const PERMISSION_CARD_ORIGIN_RECOVERY_ENABLED =
  process.env.SWITCHROOM_PERMISSION_CARD_ORIGIN_RECOVERY !== '0'
// A backstop-closed turn is seconds-to-minutes old; bound recovery so a
// long-idle agent's stale registry entry can't mis-route a much later
// permission into an old topic (it falls back to the operator-DM fan-out).
const PERMISSION_CARD_ORIGIN_MAX_AGE_MS = 30 * 60_000

// #1977 — single-tap correlation for the durable "🔁 Always allow"
// flow. When the gateway dispatches a `config_propose_edit` to hostd in
// response to an operator tap, hostd calls BACK asking for operator
// approval. We pre-register the (agent, rule) pair here keyed
// `${agentName}::${rule}` so that callback auto-approves WITHOUT a
// second card. Forge-resistance: the auto-resolve match requires the
// rule the inbound diff ADDS (via extractAddedAllowRule) to equal a
// rule the gateway itself just queued — a forged edit touching any
// other field finds no entry and falls through to a real operator card.
// Single-shot (deleted on match) + 30s TTL sweep so a stale correlation
// can't be replayed.
const pendingAlwaysAllowCorrelations = new Map<string, { agentName: string; rule: string; unifiedDiff: string; createdAt: number }>()
const ALWAYS_ALLOW_CORRELATION_TTL_MS = 30_000
function sweepStaleAlwaysAllowCorrelations(now = Date.now()): void {
  for (const [key, entry] of pendingAlwaysAllowCorrelations) {
    if (now - entry.createdAt > ALWAYS_ALLOW_CORRELATION_TTL_MS) {
      pendingAlwaysAllowCorrelations.delete(key)
    }
  }
}

// Scoped-approval store: the 30-min window that backs the "✅ Allow" tap for
// narrow non-destructive scopes (not a separate button — it IS what Allow
// means for those). Operator-tapped, gateway-side ONLY (never pushed to the
// bridge's untimed sessionAllowRules), fixed-window, fail-closed. Keyed by
// agent name for per-agent isolation. All policy lives in
// ../scoped-approval.ts (pure + unit-tested); this gateway only wires it.
const scopedGrants: ScopedGrantStore = new Map()
const selfAgentName = (): string => process.env.SWITCHROOM_AGENT_NAME ?? ''

// `ask_user` MCP tool — open prompts awaiting a user button-tap.
// Keyed by askId (8 hex chars from generateAskId). Each entry holds
// the deferred promise that resolves the originating tool call, the
// option list (so the dispatcher can map the tapped index back to a
// label), the chat we sent the prompt to (so timeout can edit the
// message), the message_id of the question (so we can edit-in-place
// on resolution / timeout), and the timer that fires the timeout.
// Cleared on shutdown / chat-close (see clearAskUserPromptsForChat).
interface PendingAskUser {
  options: string[]
  chatId: string
  threadId?: number
  messageId: number | null
  resolve: (outcome: AskUserOutcome) => void
  timer: ReturnType<typeof setTimeout>
  startedAt: number
}
const pendingAskUser = new Map<string, PendingAskUser>()

// Reauth flows
const pendingReauthFlows = new Map<string, { agent: string; startedAt: number }>()
const REAUTH_INTERCEPT_TTL_MS = 10 * 60_000

// #710: per-message agent-button metadata (ack_text / single_use). Keyed by
// `${chatId}:${messageId}` → Map<rawCallbackData, AgentButtonMeta>. Populated
// when an agent-emitted inline_keyboard is sent; consumed by the
// callback_query handler to honor agent-specified post-tap UX. Bounded by
// AGENT_BUTTON_META_MAX (LRU-ish — oldest insertion deleted when over cap)
// so a long-lived gateway can't grow the map unbounded. Restart-safe by
// design: when this map is empty (e.g. fresh process) the defaults apply
// (`'✓ received'` toast + strip keyboard) — the agent only loses any
// custom ack_text override.
const agentButtonMeta = new Map<string, Map<string, AgentButtonMeta>>()
const AGENT_BUTTON_META_MAX = 1000
function rememberAgentButtonMeta(
  chatId: string | number,
  messageId: number,
  meta: Map<string, AgentButtonMeta>,
): void {
  if (meta.size === 0) return
  const key = `${chatId}:${messageId}`
  agentButtonMeta.set(key, meta)
  while (agentButtonMeta.size > AGENT_BUTTON_META_MAX) {
    const oldest = agentButtonMeta.keys().next().value
    if (oldest === undefined) break
    agentButtonMeta.delete(oldest)
  }
}

// Vault
const vaultPassphraseCache = new Map<string, { passphrase: string; expiresAt: number }>()
const VAULT_PASSPHRASE_TTL_MS = 30 * 60 * 1000

/**
 * Approval posture for vault grant cards. Controlled by
 * `vault.broker.approvalAuth` in switchroom.yaml.
 *
 *  - "passphrase" (default): Approve tap prompts the operator for the
 *    vault passphrase before minting (today's behaviour, two-factor:
 *    Telegram ID + passphrase).
 *  - "telegram-id": Approve tap mints immediately using the
 *    auto-unlock-derived passphrase silently held in memory below.
 *    Single-factor (Telegram ID only); the schema rejects this without
 *    `autoUnlock: true`.
 *
 * Loaded once at gateway boot from `loadSwitchroomConfig()` — see the
 * startup IIFE near the bottom of this file.
 */
let VAULT_APPROVAL_AUTH_MODE: 'passphrase' | 'telegram-id' = 'passphrase'

/**
 * Admin-only vault keys (`vault.broker.adminOnlyKeys`). A grant for one
 * of these may be approved ONLY by the admin operator
 * (`access.allowFrom[0]`) and is always minted via the operator
 * passphrase — never posture, even under telegram-id mode (the broker
 * enforces the same rule). Cached at boot alongside the posture mode.
 */
let ADMIN_ONLY_KEYS: string[] = []

export function initVaultApprovalPosture(): void {
  let cfg: ReturnType<typeof loadSwitchroomConfig>
  try {
    cfg = loadSwitchroomConfig()
  } catch (err) {
    // Best-effort — gateway may run in dirs where loadSwitchroomConfig
    // fails. Stay on the default passphrase posture.
    process.stderr.write(
      `telegram gateway: could not load switchroom config for vault approval ` +
        `posture (${(err as Error).message}); defaulting to passphrase.\n`,
    )
    return
  }
  // #1115 follow-up: the gateway no longer holds the passphrase in
  // memory under telegram-id mode. The broker keeps it; the gateway
  // signals operator-tap intent via `attest_via_posture: true` on
  // mint_grant / list_grants calls. So this init is purely
  // configuration-reading — no IPC / file read / passphrase fetch.
  //
  // The schema guarantees telegram-id implies autoUnlock:true. If the
  // broker actually fails to auto-unlock at boot, the gateway's first
  // mint_grant will be rejected with BROKER-LOCKED at run-time. We
  // don't probe here because boot failures elsewhere (broker
  // singleton crash, slow start) shouldn't deadlock every agent.
  const resolved = resolveVaultApprovalPosture(cfg.vault?.broker)
  VAULT_APPROVAL_AUTH_MODE = resolved.mode
  if (resolved.mode === 'telegram-id') {
    process.stderr.write(
      `telegram gateway: vault approval posture = telegram-id ` +
        `(single-factor — broker mediates attestation via attest_via_posture)\n`,
    )
  }
  ADMIN_ONLY_KEYS = cfg.vault?.broker?.adminOnlyKeys ?? []
  if (ADMIN_ONLY_KEYS.length > 0) {
    process.stderr.write(
      `telegram gateway: ${ADMIN_ONLY_KEYS.length} admin-only vault key pattern(s) ` +
        `— grants approved by allowFrom[0] + operator passphrase only\n`,
    )
  }
}
/**
 * Gateway-side guard on vault-key shape — UX gate, not a security
 * boundary (the broker accepts any non-empty string per
 * `src/vault/broker/protocol.ts:32`). Includes `/` so canonical
 * namespaced keys like `fatsecret/client_id`, `mff/agent-private-key`,
 * `microsoft/ken-tokens` are accepted in the vault_request_save /
 * vault_request_access / [✏️ Rename] flows. See #1047.
 */
const VAULT_KEY_REGEX = /^[A-Za-z0-9_./-]{1,200}$/
/** Human-readable label embedded in error messages and rename prompts. */
const VAULT_KEY_REGEX_LABEL = "[A-Za-z0-9_./-]{1,200}"
type PendingVaultOp =
  | { kind: 'passphrase'; op: 'list' | 'get' | 'delete' | 'set'; key?: string; startedAt: number }
  | { kind: 'value'; op: 'set'; key: string; passphrase: string; startedAt: number }
  // Issue #44: passphrase entry triggered by tapping "🔓 Unlock vault & save"
  // on a deferred-secret card. After the passphrase is cached we look up the
  // held secret by deferKey and write it directly — no re-paste required.
  | {
      kind: 'passphrase-for-deferred'
      deferKey: string
      cardChatId: string
      cardMessageId: number
      startedAt: number
    }
  // Issue #158: passphrase collected for /vault unlock — sent directly to the
  // broker unlock socket, never logged or cached beyond the op itself.
  | { kind: 'unlock'; startedAt: number }
  // Issue #227: inline-keyboard wizard for /vault grant
  | {
      kind: 'grant-wizard'
      step: 'agent' | 'keys' | 'duration' | 'confirm'
      wizardMsgId?: number      // message to edit for each step
      agent?: string
      selectedKeys?: string[]   // keys toggled on in step 2
      availableKeys?: string[]  // list fetched from broker
      ttlSeconds?: number | null // null = never expires
      expiresLabel?: string     // human-readable label for confirmation
      description?: string
      awaitingCustomDuration?: boolean  // true while waiting for text reply
      /**
       * Approval-kernel request_id minted at the wizard confirm step
       * (MIGRATION.md §2, Phase 1 dual-dispatch — audit-only, advisory).
       * When set, `vg:generate` ALSO consumes + records an `allow_once`
       * decision on the kernel; `vg:cancel` records a `deny`. Cards in
       * flight from before this PR landed have it `undefined` and the
       * legacy `mintGrantViaBroker` runs alone — no kernel write. After
       * 1-2 releases the legacy-only branch can be removed (#833 Phase 2
       * is the enforcing flip).
       */
      kernel_request_id?: string
      startedAt: number
    }
  // Issue #228: waiting for confirmation before revoking a grant.
  | { kind: 'revoke_confirm'; grantId: string; agent: string; keys: string[]; startedAt: number }
  // Issue #969 P1a: user tapped "Rename" on a vault_request_save card;
  // the next message becomes the new key name for the staged save.
  | { kind: 'rename-vault-save'; stageId: string; startedAt: number }
  // Issue #1012 Phase 2 follow-up: operator tapped Approve on a
  // vault_request_access card without first unlocking the vault. The
  // next message becomes the passphrase — we cache it, delete the
  // passphrase message, and auto-resume the approval mint flow without
  // making the operator tap Approve a second time. Mirrors the
  // `passphrase-for-deferred` flow from #44.
  //
  // #1051: `items` is a queue so concurrent Approve taps (operator
  // taps card 2 before typing passphrase for card 1) don't strand
  // earlier stages. On passphrase reply we process all queued items
  // sequentially. Each item carries its own stageId + card refs;
  // they're all in the same chat by construction (pendingVaultOps
  // map is keyed by chat_id).
  | {
      kind: 'passphrase-for-access-approve'
      items: Array<{
        stageId: string
        cardChatId: string
        cardMessageId: number
        senderId: string
      }>
      startedAt: number
    }
const VAULT_INPUT_TTL_MS = 5 * 60 * 1000
const pendingVaultOps = new Map<string, PendingVaultOp>()

// Secret-detection staging: ambiguous hits the user must confirm before we
// store/delete. Also holds the deferred "we need a passphrase before we can
// store this high-confidence hit" cases so the re-run after passphrase entry
// is seamless.
const secretStaging = new StagingMap()
interface DeferredSecret {
  chat_id: string
  original_message_id: number
  text: string
  staged_at: number
  /**
   * Slug suggested by the detector at the time we deferred the secret.
   * Captured up-front so the post-unlock auto-write doesn't have to re-run
   * detection (which would have to handle the no-detection-fired case for
   * Channel B context-rule defers — issue #44). Falls back to a generic
   * slug if detection didn't fire.
   */
  suggested_slug: string
  /**
   * Approval-kernel request_id minted alongside the bespoke deferred-secret
   * card (MIGRATION.md §1, Phase 1 dual-dispatch). When set, the
   * `vd:unlock` / `vd:cancel` callback handler ALSO records the user's
   * decision on the kernel side via `approvalConsume` + `approvalRecord`,
   * so the audit log captures the unlock event.
   *
   * `undefined` on cards built before this PR landed (in-flight at deploy
   * time) — the legacy handler runs alone, no kernel record. After ~1-2
   * releases the legacy-only branch can be removed (separate cleanup PR).
   */
  kernel_request_id?: string
}
const deferredSecrets = new Map<string, DeferredSecret>()

/**
 * Agent-initiated save staging (issue #969 P1a). When an agent calls the
 * `vault_request_save` MCP tool, we stage the value here, render an
 * approval card to the user, and write to vault only on tap. The value
 * is held in gateway memory ONLY — never echoed back to the agent and
 * never logged.
 */
interface PendingVaultRequestSave {
  /** Agent that requested the save (process.env.SWITCHROOM_AGENT_NAME). */
  agent: string
  /** Chat to edit when the user taps. */
  chat_id: string
  /** Card message id (filled in after we send the card). */
  card_message_id?: number
  /** Supergroup forum topic the agent was working in when it requested the
   *  save — carried into the save-outcome inbound so the resumed reply lands
   *  back in that topic, not General. */
  threadId?: number
  /** Currently-suggested slug; may be renamed by the user. */
  key: string
  /** Storage shape — 'string' (default) or 'binary'. */
  kind: 'string' | 'binary'
  /** The secret value, held in memory until the user approves/discards. */
  value: string
  /** Optional rationale shown on the card. */
  why?: string
  /** Unix-ms timestamp; entries are reaped after VAULT_REQUEST_SAVE_TTL_MS. */
  staged_at: number
}
const pendingVaultRequestSaves = new Map<string, PendingVaultRequestSave>()
// Gateway-side reap window for a staged vault-save card. Tracks the operator
// approval-card lifetime (config-driven, 60-min default) so the reap never
// races ahead of the card the operator is still looking at.
const VAULT_REQUEST_SAVE_TTL_MS = approvalTtlMs()
function sweepPendingVaultRequestSaves(): void {
  const cutoff = Date.now() - VAULT_REQUEST_SAVE_TTL_MS
  for (const [k, v] of pendingVaultRequestSaves) {
    if (v.staged_at < cutoff) pendingVaultRequestSaves.delete(k)
  }
}

/**
 * Issue #1012 — agent-initiated vault ACL request. The agent calls
 * `vault_request_access` when it hits VAULT-BROKER-DENIED (or
 * preemptively, when it knows it'll need a key it doesn't yet have).
 * The card carries [Approve] / [Deny] inline buttons; only the
 * operator can mint the grant (same authorization gate as the
 * existing /vault audit one-tap allow flow). The agent never sees
 * the grant token directly — `mintGrantViaBroker` writes it to the
 * agent's `.vault-token` file, which the agent's CLI reads on the
 * next vault request.
 *
 * Mirrors PendingVaultRequestSave above (#969 P1a). No secret
 * material is staged here — only the request metadata.
 */
interface PendingVaultRequestAccess {
  /** Agent that initiated the request (process.env.SWITCHROOM_AGENT_NAME). */
  agent: string
  /** Chat the card was rendered into; edited on tap. */
  chat_id: string
  /** Card message id (filled in after we send the card). */
  card_message_id?: number
  /** Supergroup forum topic the agent was working in when it requested (the
   *  card's originating thread). Carried into the grant-outcome inbound so the
   *  resumed reply lands back in that topic, not General. */
  threadId?: number
  /** Vault key the agent wants to read. */
  key: string
  /** 'read' (default) or 'write'. */
  scope: 'read' | 'write'
  /** Optional rationale the agent supplied; rendered on the card. */
  reason?: string
  /** Grant TTL in seconds (max 90 days; null = never, refused). */
  ttl_seconds: number
  /** Unix-ms timestamp; entries are reaped after VAULT_REQUEST_ACCESS_TTL_MS. */
  staged_at: number
}
const pendingVaultRequestAccesses = new Map<string, PendingVaultRequestAccess>()
// Gateway-side reap window for a staged vault-access card. Tracks the operator
// approval-card lifetime (config-driven, 60-min default) — see approvalTtlMs.
const VAULT_REQUEST_ACCESS_TTL_MS = approvalTtlMs()
function sweepPendingVaultRequestAccesses(): void {
  const cutoff = Date.now() - VAULT_REQUEST_ACCESS_TTL_MS
  for (const [k, v] of pendingVaultRequestAccesses) {
    if (v.staged_at < cutoff) pendingVaultRequestAccesses.delete(k)
  }
}

/**
 * Mint an approval-kernel decision row for a deferred-secret card
 * (MIGRATION.md §1). Best-effort: if the kernel/broker is unreachable, we
 * return null and the caller proceeds with the legacy-only path so the
 * core unlock UX never depends on kernel availability.
 *
 * `agent_unit` is the gateway's agent — the per-agent ACL ships in Docker
 * Phase 2b. The kernel-server checks the listener's bound socket against
 * the claimed agent, so passing the local agent name is safe.
 */
async function mintDeferredSecretKernelRequest(
  slug: string,
  approverSet: string[],
): Promise<string | null> {
  const agentName = process.env.SWITCHROOM_AGENT_NAME
  if (!agentName) return null
  try {
    const r = await approvalRequest({
      agent_unit: `switchroom-${agentName}.service`,
      scope: `vault:secret:${slug}`,
      action: 'unlock',
      approver_set: approverSet,
      why: 'Unlock vault to save a deferred secret detected in chat.',
    })
    if (r === null || r.state !== 'pending') return null
    return r.request_id
  } catch (err) {
    process.stderr.write(
      `[approval-kernel] mintDeferredSecretKernelRequest failed: ${(err as Error).message}\n`,
    )
    return null
  }
}

/**
 * Record the user's decision (allow/deny) on the approval kernel for a
 * deferred-secret card. Best-effort and idempotent — a missing
 * `request_id` (legacy in-flight card) or an unreachable kernel both
 * silently no-op so the legacy UX is unaffected.
 */
async function recordDeferredSecretKernelDecision(
  request_id: string | undefined,
  decision: 'allow_once' | 'deny',
  granted_by_user_id: number,
  approverSet: string[],
): Promise<void> {
  if (!request_id) return
  try {
    const consumed = await approvalConsume(request_id)
    if (consumed === null || !consumed.consumed) return
    await approvalRecord({
      request_id,
      decision,
      approver_set: approverSet,
      granted_by_user_id,
      ttl_ms: null,
    })
  } catch (err) {
    process.stderr.write(
      `[approval-kernel] recordDeferredSecretKernelDecision failed: ${(err as Error).message}\n`,
    )
  }
}
function deferredKey(chat_id: string, message_id: number): string {
  return `${chat_id}:${message_id}`
}

/**
 * Mint an approval-kernel decision row for a `/vault grant` wizard
 * confirm step (MIGRATION.md §2, Phase 1 audit-only dual-dispatch).
 *
 * Best-effort: kernel/broker unreachable → returns null and the wizard
 * proceeds on the legacy `mint_grant` path alone, so the user-facing
 * grant UX never depends on kernel availability. This is *advisory*
 * in Phase 1 — the kernel verdict is informational alongside the
 * legacy `vault_grants` row, not enforcing. Phase 2 (issue #833) flips
 * enforcement.
 *
 * Scope shape `vault:grant:<agent_slug>` mirrors the `vault:secret:<slug>`
 * namespacing established in #832 / PR #830 — one decision per (agent,
 * grant-mint) tuple. Action `mint`. Approver-set is the gateway's
 * allowFrom (same set that gates the wizard callback in the first place).
 */
async function mintGrantWizardKernelRequest(
  agentSlug: string,
  approverSet: string[],
  selectedKeys: string[],
  ttlSeconds: number | null,
): Promise<string | null> {
  const agentName = process.env.SWITCHROOM_AGENT_NAME
  if (!agentName) return null
  try {
    const why =
      `Mint capability token for agent "${agentSlug}" — ` +
      `${selectedKeys.length} key(s), ` +
      `${ttlSeconds === null ? 'no expiry' : `${ttlSeconds}s TTL`}.`
    const r = await approvalRequest({
      agent_unit: `switchroom-${agentName}.service`,
      scope: `vault:grant:${agentSlug}`,
      action: 'mint',
      approver_set: approverSet,
      why,
    })
    if (r === null || r.state !== 'pending') return null
    return r.request_id
  } catch (err) {
    process.stderr.write(
      `[approval-kernel] mintGrantWizardKernelRequest failed: ${(err as Error).message}\n`,
    )
    return null
  }
}

/**
 * Record the user's wizard decision (allow/deny) on the approval kernel
 * for a `/vault grant` wizard card. Best-effort and idempotent — a
 * missing `request_id` (legacy in-flight wizard) or an unreachable
 * broker silently no-op so the legacy UX is unaffected. Audit-only in
 * Phase 1: nothing downstream reads this verdict yet.
 */
async function recordGrantWizardKernelDecision(
  request_id: string | undefined,
  decision: 'allow_once' | 'deny',
  granted_by_user_id: number,
  approverSet: string[],
): Promise<void> {
  if (!request_id) return
  try {
    const consumed = await approvalConsume(request_id)
    if (consumed === null || !consumed.consumed) return
    await approvalRecord({
      request_id,
      decision,
      approver_set: approverSet,
      granted_by_user_id,
      ttl_ms: null,
    })
  } catch (err) {
    process.stderr.write(
      `[approval-kernel] recordGrantWizardKernelDecision failed: ${(err as Error).message}\n`,
    )
  }
}

// Channel B context rule — tracks when the gateway has emitted the
// "Paste the browser code here" prompt so that the next inbound message
// in the same chat is treated as auth-flow-sensitive regardless of whether
// the pattern rule fires (belt-and-braces: pattern covers the known shape,
// context rule covers future shape changes).
const awaitingAuthCodeAt = new Map<string, number>()
const AUTH_CODE_CONTEXT_TTL_MS = 5 * 60_000 // 5 min — OAuth code lifetime
const DEFERRED_SECRET_TTL_MS = 24 * 60 * 60_000 // 24 h — ignored one-tap cards

// Freshness throttle for `auth:refresh` taps. Keyed by `<chat_id>:<message_id>`
// so two different snapshot messages throttle independently. Each refresh
// fan-fires N live api.anthropic.com probes (one per account), so we cap
// rapid re-taps to one per AUTH_REFRESH_THROTTLE_MS.
const lastAuthRefreshAtMs = new Map<string, number>()
const AUTH_REFRESH_THROTTLE_MS = 5_000

// ─── TTL reaper ───────────────────────────────────────────────────────────
// Pending state maps above all grow whenever a flow starts and only shrink
// when the flow completes. Users abandoning a flow (closing Telegram, losing
// connection, hitting cancel on client) leaves entries behind. Without a
// reaper, long-running gateways leak memory across days/weeks. A single
// Maximum time to wait for an in-flight turn before forcing a pending
// restart (the `--force` SIGKILL fallback documented in the spec).
const PENDING_RESTART_DRAIN_CAP_MS = 60_000

/**
 * Compact one-line summary of a turn-active marker payload, for the
 * [markersweep] log line. Resilient to malformed JSON — returns
 * `payload=unparseable` rather than throwing.
 */
function summariseMarkerPayload(payload: string | null): string {
  if (!payload) return 'payload=missing'
  try {
    const parsed = JSON.parse(payload) as { turnKey?: unknown; chatId?: unknown; startedAt?: unknown }
    const turnKey = typeof parsed.turnKey === 'string' ? parsed.turnKey : 'unknown'
    const chatId = typeof parsed.chatId === 'string' ? parsed.chatId : 'unknown'
    const startedAt = typeof parsed.startedAt === 'number' ? parsed.startedAt : 0
    return `turnKey=${turnKey} chat=${chatId} started=${new Date(startedAt).toISOString()}`
  } catch {
    return 'payload=unparseable'
  }
}

/**
 * Returns true when the persisted auto-fallback lockout for this
 * agent's directory shows we just rotated slots within the cooldown
 * window. Used by the pending-restart drain cap to defer a forced
 * restart that would otherwise stack on top of an in-flight slot
 * rotation. Best-effort: any read error returns false (fail-open),
 * matching the lockout's "noise filter, not a security boundary" role.
 */
function isAutoFallbackCooldownActive(_agentName: string, now: number): boolean {
  try {
    const agentDir = resolveAgentDirFromEnv()
    if (!agentDir) return false // No state dir → no persisted lockout to check.
    const persisted = loadLockout(agentDir, lockoutOps)
    if (!persisted.lastTransitionedFrom) return false
    return now - persisted.lastTransitionAt < DEFAULT_FALLBACK_COOLDOWN_MS
  } catch {
    return false
  }
}

// 60-second sweep drops anything past its documented TTL.
const pendingStateReaper = setInterval(() => {
  const now = Date.now()
  // OAuth-code state grouped first (pinned by secret-detect-oauth-code.test.ts).
  for (const [k, v] of pendingReauthFlows) {
    if (now - v.startedAt > REAUTH_INTERCEPT_TTL_MS) pendingReauthFlows.delete(k)
  }
  for (const [k, v] of pendingAuthAddFlows) {
    if (now - v.startedAt > REAUTH_INTERCEPT_TTL_MS) {
      cancelAccountAuthSession(v)
      pendingAuthAddFlows.delete(k)
    }
  }
  for (const [k, v] of awaitingAuthCodeAt) {
    if (now - v > AUTH_CODE_CONTEXT_TTL_MS) awaitingAuthCodeAt.delete(k)
  }
  // Microsoft connect flows self-expire at the device code's own expiry
  // (~15 min) — sweep past that + grace so an abandoned card doesn't pin
  // its key. Setting cancelled makes any still-running poll bail. Placed
  // AFTER the OAuth-code cluster above, which secret-detect-oauth-code.
  // test.ts pins as contiguous within the first 800 chars of the reaper.
  for (const [k, v] of pendingMicrosoftConnectFlows) {
    if (now - v.startedAt > v.device.expires_in * 1000 + 30_000) {
      v.cancelled = true
      pendingMicrosoftConnectFlows.delete(k)
    }
  }
  // Auth-refresh throttle entries decay quickly (5s window); sweep
  // anything older than 60s so abandoned snapshot messages don't pin
  // their key forever.
  for (const [k, v] of lastAuthRefreshAtMs) {
    if (now - v > 60_000) lastAuthRefreshAtMs.delete(k)
  }
  // /auth rm two-step confirm window — self-expires at `expiresAt`.
  for (const [k, v] of pendingAuthRmFlows) {
    if (now >= v.expiresAt) pendingAuthRmFlows.delete(k)
  }
  for (const [k, v] of pendingVaultOps) {
    if (now - v.startedAt > VAULT_INPUT_TTL_MS) pendingVaultOps.delete(k)
  }
  for (const [k, v] of pendingPermissions) {
    // hostd gated fleet-mutation verbs get a longer (30-min) human-scale
    // decision window than the 10-min default (Bug 2 fix #2).
    const ttl = ttlForTool(v.tool_name)
    if (now - v.startedAt > ttl) {
      // Don't just drop it: the claude turn is suspended INSIDE the MCP
      // permission call waiting for a verdict. A silent delete left it
      // wedged forever when the operator never tapped — permanent
      // silence, the exact symptom this series fixes. Auto-deny so the
      // call unblocks; claude then tells the user it couldn't get
      // permission (or takes a fallback). Routed through
      // dispatchPermissionVerdict so it's buffered+redelivered too if
      // the bridge is also offline at sweep time.
      // Carry a TIMEOUT reason to the model (claude renders it as "…the user
      // said: …") so it can tell a timeout from a real denial and not retry
      // the identical call — the duplicate-card loop this series closes.
      const timeoutMinutes = Math.round(ttl / 60000)
      dispatchPermissionVerdict({
        type: 'permission',
        requestId: k,
        behavior: 'deny',
        message: timeoutDenyMessage(timeoutMinutes),
      })
      // Strip the card's inline keyboard + mark it timed out (Bug 2 fix #1).
      // Before this, the reaper deleted the pending entry but left a LIVE
      // Approve button — a late operator tap then dispatched a verdict for an
      // already-resolved/dead request_id, which Claude Code ignores, so the
      // operator "approved" but work never continued. Stripping the keyboard
      // makes the timeout legible and removes the stale tappable button.
      void stripTimedOutPermissionCards(v.card_text, v.cards)
      // The auto-deny un-parks the suspended turn — flip 🙏 → working so
      // it doesn't sit on the awaiting glyph (or stall) after the timeout.
      resumeReactionAfterVerdict()
      postPermissionResumeMessage({
        behavior: 'deny',
        action: naturalAction(v.tool_name, v.input_preview),
        timeoutMinutes,
      })
      // Remember this (tool, input) timed out so an immediate identical retry
      // (while the operator is still absent) is short-circuited without a
      // second card. Cleared on operator activity.
      if (PERMISSION_NO_REPEAT_ENABLED) {
        permissionTimeoutSignatures.set(
          permissionSignature(v.tool_name, v.input_preview),
          now,
        )
      }
      process.stderr.write(
        `telegram gateway: permission TTL expired — auto-deny request=${k} ` +
        `tool=${v.tool_name} (no operator response in ` +
        `${timeoutMinutes}m)\n`,
      )
      pendingPermissions.delete(k)
      permCardStore.remove(k)
    }
  }
  // Drop no-repeat suppression entries past the safety-cap window (the primary
  // bound is the operator-activity reset; this just keeps the map from growing).
  for (const [sig, at] of permissionTimeoutSignatures) {
    if (now - at > PERMISSION_DUPLICATE_WINDOW_MS) permissionTimeoutSignatures.delete(sig)
  }
  for (const [k, v] of vaultPassphraseCache) {
    if (now > v.expiresAt) vaultPassphraseCache.delete(k)
  }
  // Drop expired "⏱ 30 min" scoped grants. (Lookup already fails closed on
  // expiry; this just keeps the map from accumulating dead entries.)
  sweepScopedGrants(scopedGrants, now)
  for (const [k, v] of deferredSecrets) {
    if (now - v.staged_at > DEFERRED_SECRET_TTL_MS) deferredSecrets.delete(k)
  }
  // #550: sweep a stale turn-active marker. Defence-in-depth for the
  // case where neither the turn_end arm nor onTurnComplete fired (SDK
  // killed before the JSONL turn_duration record, compaction window,
  // forceCompleteTurn silent no-op on torn-down card, etc). We use
  // currentTurnRegistryKey as the "is a turn in flight?" signal — when
  // null we sweep aggressively (>60s mtime), and we always sweep when
  // the marker is older than 10min regardless. Both bounds are well
  // under the watchdog's TURN_HANG_SECS=300s threshold for the in-
  // flight case but generous enough that real long-running tool calls
  // (which touch mtime on every tool_use) won't trip the idle path.
  //
  // Logging: include agent name + age + reason + payload so a marker
  // leak (or a real wedge) leaves enough breadcrumbs in journalctl to
  // diagnose without needing to inspect the file (which is gone after
  // the sweep). `journalctl -u switchroom-<agent>-gateway -g markersweep`
  // is the audit trail.
  try {
    sweepStaleTurnActiveMarker(STATE_DIR, {
      turnInFlight: currentTurn?.registryKey != null,
      idleSweepMs: 60_000,
      hardTtlMs: 10 * 60_000,
      now,
      onRemove: ({ ageMs, reason, payload }) => {
        const agent = getMyAgentName()
        const ageSec = Math.round(ageMs / 1000)
        const turnInFlight = currentTurn?.registryKey != null
        const summary = summariseMarkerPayload(payload)
        process.stderr.write(
          `telegram gateway: [markersweep] removed agent=${agent} age=${ageSec}s reason=${reason} turn_in_flight=${turnInFlight} ${summary}\n`,
        )
      },
    })
  } catch { /* best-effort */ }
  // Drain cap: if a scheduled restart has been waiting >60s for a turn
  // to complete, force it through anyway (spec: 60s cap → SIGKILL fallback).
  //
  // Auto-fallback cooldown gate: if the persisted lockout shows we just
  // rotated this agent's slot inside the cooldown window, defer the
  // forced restart by another tick. This closes a churn window where a
  // 429-driven fallback already spawned a restart, and a parallel
  // schedule_restart IPC sat in pendingRestarts — without this gate the
  // drain cap would fire a SECOND restart 60s later. Bound: at most
  // FALLBACK_COOLDOWN_MS / 60s extra deferrals per pending restart.
  for (const [agentName, requestedAt] of pendingRestarts.entries()) {
    if (now - requestedAt > PENDING_RESTART_DRAIN_CAP_MS) {
      const waitedSec = Math.round((now - requestedAt) / 1000)
      const cooldownActive = isAutoFallbackCooldownActive(agentName, now)
      if (cooldownActive) {
        process.stderr.write(
          `telegram gateway: [restart-drain] deferred agent=${agentName} waited=${waitedSec}s reason=auto-fallback-cooldown-active\n`,
        )
        continue
      }
      process.stderr.write(
        `telegram gateway: [restart-drain] forcing agent=${agentName} waited=${waitedSec}s threshold=${Math.round(PENDING_RESTART_DRAIN_CAP_MS / 1000)}s\n`,
      )
      pendingRestarts.delete(agentName)
      triggerSelfRestart(agentName, 'restart-drain-cap-forced', 100)
    }
  }
}, 60_000)
pendingStateReaper.unref()

/**
 * Does a message look like a Claude setup-token browser code?
 *
 * The intercept path in the inbound-message handler uses this to decide
 * whether to treat a pending-reauth chat's next message as `/auth code`.
 * Return value drives whether the gateway hijacks the message or lets
 * it through to the agent bridge — false negatives are user-visible as
 * 'I pasted my code and nothing happened'.
 *
 * Format evolution:
 *   - Legacy:  opaque 20+ char alphanum+underscore+hyphen token
 *   - 2025+:   `sk-ant-...` API tokens emitted by setup-token
 *   - 2026+:   `<code>#<state>` format from the claude.com/cai
 *              authorize URL (see parseSetupTokenUrl regex). The `#`
 *              in the middle was the breakage surfaced 2026-04-22 —
 *              user's code starting with `tle0rm...#00EySj...` fell
 *              through because the character class missed `#`.
 *
 * Character class now includes `#` and `.` for future-proofing (dot
 * is common in JWT-style tokens). Length cap raised to 500 because
 * the new dual-section format is ~90+ chars and will likely grow.
 */
function looksLikeAuthCode(text: string): boolean {
  const trimmed = text.trim()
  if (!trimmed || /\s/.test(trimmed)) return false
  if (trimmed.startsWith('session_')) return true
  if (trimmed.startsWith('sk-ant-')) return true
  if (/^[A-Za-z0-9_.#-]{6,500}$/.test(trimmed)) return true
  return false
}

// ─── Coalescing ───────────────────────────────────────────────────────────
type AttachmentMeta = {
  kind: string
  file_id: string
  size?: number
  mime?: string
  name?: string
}

// One attachment slot carried by a coalesced message — primary or extra.
type CoalesceAttachment = {
  downloadImage?: () => Promise<string | undefined>
  attachment?: AttachmentMeta
}

// CoalescePayload is what the InboundCoalescer carries per buffered message.
// `ctx` must be the *latest* message's context (latest message_id, etc.) so
// the merge function picks the last entry's ctx.
//
// Each inbound Telegram message carries at most one attachment, so an enqueued
// payload sets at most `downloadImage`/`attachment`. The merge collects every
// attachment-bearing entry in the window (up to coalesce.max_attachments): the
// first becomes the primary `downloadImage`/`attachment`, the rest ride along
// in `extraAttachments` (A2). When the cap is 1 (default), the
// handleInboundCoalesced guards still bypass a second attachment / album part
// to its own turn, so the single-attachment behaviour is byte-for-byte
// preserved.
type CoalescePayload = {
  text: string
  ctx: Context
  downloadImage?: () => Promise<string | undefined>
  attachment?: AttachmentMeta
  // Set only by `merge`: the 2nd..Nth attachments folded into this turn.
  extraAttachments?: CoalesceAttachment[]
}

// Count of attachment-bearing entries currently buffered per coalesce key.
// A new attachment for a key whose count has reached the per-agent cap
// (coalesce.max_attachments, default 10) bypasses coalescing (see
// handleInboundCoalesced) so no media is dropped past the cap. Cleared on
// flush (below) and on the synchronous bypass path.
const bufferedAttachmentKeys = new Map<string, number>()

function coalesceMaxAttachments(): number {
  return resolveCoalesceMaxAttachments(loadAccess().coalesceMaxAttachments)
}

const inboundCoalescer = createInboundCoalescer<CoalescePayload>({
  // Read per-call from the access file so an operator-tuned
  // channels.telegram.coalesce.window_ms (projected to coalescingGapMs by
  // scaffold) takes effect on the next message after apply+restart.
  //
  // Default lowered 1500 → 500 in #553 PR 3 to shrink the gateway-side
  // contribution to first-real-text latency.
  gapMs: () => loadAccess().coalescingGapMs ?? 500,
  merge: (entries) => {
    const last = entries[entries.length - 1]
    // Collect every attachment-bearing entry in arrival order. The first is
    // the primary (unsuffixed image_path/attachment_* meta); the remainder,
    // capped at max_attachments, become numbered extras. A [photo][text]
    // burst keeps its image even though the last entry is text-only.
    const { primary, extras } = splitCoalescedAttachments(
      entries,
      (e) => e.downloadImage != null || e.attachment != null,
      coalesceMaxAttachments(),
    )
    return {
      // Drop empty texts (e.g. caption-less album parts) so the join doesn't
      // emit blank lines between attachments.
      text: entries.map((e) => e.text).filter((t) => t.length > 0).join('\n'),
      ctx: last.ctx,
      downloadImage: primary?.downloadImage,
      attachment: primary?.attachment,
      extraAttachments: extras.length > 0
        ? extras.map((e) => ({ downloadImage: e.downloadImage, attachment: e.attachment }))
        : undefined,
    }
  },
  onFlush: (key, merged) => {
    bufferedAttachmentKeys.delete(key)
    void handleInbound(
      merged.ctx,
      merged.text,
      merged.downloadImage,
      merged.attachment,
      merged.extraAttachments,
    )
  },
})

/**
 * Gateway-side emission for an OperatorEvent — the single point where:
 *   - per-agent per-kind cooldown is enforced
 *   - the event is recorded into the in-memory history (feeds /status)
 *   - the rendered card is broadcast to every chat in `access.allowFrom`
 *
 * Producers (the IPC `onOperatorEvent` handler, the boot-card crash
 * detector, the restart-watchdog) all funnel through here so the dedupe,
 * record, and post logic stays in one place.
 *
 * Each step is independently fault-tolerant — a failure to record
 * doesn't block the post; a bad send to one chat doesn't block siblings.
 */
function emitGatewayOperatorEvent(event: OperatorEvent): void {
  const { agent, kind } = event

  if (!shouldEmitOperatorEvent(agent, kind)) {
    process.stderr.write(
      `telegram gateway: operator-event suppressed (cooldown) agent=${agent} kind=${kind}\n`,
    )
    return
  }

  try {
    recordOperatorEvent(event)
  } catch (err) {
    process.stderr.write(
      `telegram gateway: recordOperatorEvent failed agent=${agent} kind=${kind}: ${(err as Error).message}\n`,
    )
  }

  // Issue #394 Fix 2: when the failure is model-unavailable (quota out,
  // overloaded, or the network can't even reach Anthropic), suppress the
  // raw stderr/detail and post the actionable ⚠️ card instead. The card
  // points at the commands that move the needle (`/auth` Switch
  // primary picker, `/auth add`, `/usage`) so the user isn't left
  // staring at "You're out of extra usage · resets May 3, 11am" with
  // no idea what to do.
  //
  // Two routes match:
  //   - kind already classified as quota-exhausted / rate-limited / unknown-5xx
  //     by the upstream classifier
  //   - detail string contains one of the model-unavailable text patterns
  //     (covers raw stderr that slipped past structured classification)
  const modelUnavailable = resolveModelUnavailableFromOperatorEvent(event)
  let renderedText: string
  let renderedKeyboard: ReturnType<typeof renderOperatorEvent>['keyboard'] | undefined
  if (modelUnavailable) {
    // Two questions, asked synchronously to avoid the "card promises
    // an announcement that never arrives" trap:
    //   1. Is this a kind that AUTO-fallback can address?
    //   2. Will the dispatcher actually fire (vs. dedup-drop)?
    // Card text branches on the AND. wouldFireFleetAutoFallback is a
    // pure read of the dedup state; calling fireFleetAutoFallback only
    // when both are true keeps the card honest.
    // Only a genuine quota / usage-limit hit is addressable by fleet
    // auto-fallback (swap to an account that still has runway). An
    // `overload` is transient Anthropic SERVER-side capacity pressure —
    // every account is equally affected, so failing over does nothing;
    // it just produces a self-cancelling "probed healthy / Stale event?"
    // loop on every 529. Overload is handled by Claude Code's own
    // internal retry, not by switching accounts.
    const isAutoKind = modelUnavailable.kind === 'quota_exhausted'
    const willActuallyFire = isAutoKind && wouldFireFleetAutoFallback()
    process.stderr.write(
      `telegram gateway: operator-event suppressing-raw-stderr-for-model-unavailable agent=${agent} kind=${kind} detected=${modelUnavailable.kind} autoKind=${isAutoKind} willFire=${willActuallyFire}\n`,
    )
    renderedText = formatModelUnavailableCard(modelUnavailable, agent, {
      autoFallbackInFlight: willActuallyFire,
    })
    renderedKeyboard = undefined
    // Trigger fleet-wide auto-fallback. Pre-fix this branch only
    // rendered the card; the fallback machinery was unreachable from
    // here. We fire-and-forget so card delivery is never blocked on
    // broker / API latency. The fallback's own announcement is sent
    // separately with the causal-shape headline ("5-hour limit on
    // ken" instead of generic "quota exhausted") — see
    // auth-snapshot-format.ts → renderFallbackAnnouncement.
    //
    // Thread the parsed reset as markExhausted's `until` via the shared
    // resolveExhaustUntil floor. parseResetTime gives a finite epoch for
    // ROLLING wordings ("resets in 2h", "retry after 60s"); a WEEKLY wall
    // ("resets Jun 9, 5am") is UNPARSEABLE here → undefined → +7d floor.
    // Pre-fix this called fireFleetAutoFallback(agent) with no until, so a
    // weekly wall that surfaced as a 429 got markExhausted's ~5h default and
    // the broker re-mirrored the still-walled account onto the fleet after 5h.
    if (willActuallyFire) {
      const untilMs = resolveExhaustUntil(modelUnavailable.resetAt?.getTime())
      void fireFleetAutoFallback(agent, untilMs)
    }
  } else {
    try {
      const r = renderOperatorEvent(event)
      renderedText = r.text
      renderedKeyboard = r.keyboard
    } catch (err) {
      process.stderr.write(
        `telegram gateway: renderOperatorEvent failed agent=${agent} kind=${kind}: ${(err as Error).message}\n`,
      )
      return
    }
  }

  const access = loadAccess()
  if (access.allowFrom.length === 0) {
    process.stderr.write(
      `telegram gateway: operator-event no-allowlist agent=${agent} kind=${kind} (recorded only)\n`,
    )
    return
  }

  // PR4b emitter sweep: supergroup-mode agents route operator-event
  // cards (boot crash, restart-watchdog, model-unavailable, etc.) into
  // the alerts/admin alias topic instead of chat-root. The
  // 'compact-watchdog' kind covers all system-initiated notifications
  // — alerts alias → default_topic_id fallback (see router contract).
  // Fleet-shared / DM agents see `undefined` → no `message_thread_id`
  // is added to the broadcast opts → behavior unchanged.
  const opEventTopic = resolveAgentOutboundTopic({ kind: 'compact-watchdog' })
  const opEventSupergroup = resolveAgentSupergroupChatId()

  process.stderr.write(
    `telegram gateway: operator-event posting agent=${agent} kind=${kind} to ${access.allowFrom.length} chat(s)` +
      (opEventTopic != null ? ` topic=${opEventTopic}` : '') + '\n',
  )
  for (const chat_id of access.allowFrom) {
    // The resolved topic is valid ONLY in the agent's supergroup — attaching
    // it to an operator DM recipient yields 400 "message thread not found" and
    // the event silently fails to deliver (the marko #2096 class). Guard it:
    // DM recipients get a thread-less send; the supergroup owner gets the lane.
    const opEventThread = topicForRecipient({ recipientChatId: chat_id, resolvedTopic: opEventTopic, supergroupChatId: opEventSupergroup })
    // grammy's Other<...> opts type is generated and stricter than our
    // call shape; runtime accepts both. Cast through unknown.
    const opts = {
      ...(renderedKeyboard ? { reply_markup: renderedKeyboard } : {}),
      ...(opEventThread != null ? { message_thread_id: opEventThread } : {}),
    }
    // Comment-only context for the reader; the lint marker on the
    // very next line is what unlocks the raw bot.api call.
    // Opts now includes message_thread_id when supergroup mode is on.
    // allow-raw-bot-api: operator-event broadcast loop; topic-aware opts
    void bot.api.sendRichMessage(chat_id, richMessage(renderedText), opts as never).catch(e => {
      process.stderr.write(
        `telegram gateway: operator-event send to ${chat_id} failed agent=${agent} kind=${kind}: ${e}\n`,
      )
    })
  }
}

/**
 * Legacy "restarted — ready" banner, used when BOOT_CARD_ENABLED=false.
 * Kept as a safe fallback so reverting to the old behavior is one env var flip.
 */
function postLegacyBanner(
  chatId: string,
  threadId: number | undefined,
  ackMessageId: number | undefined,
  ageSec: number,
  site: string,
): void {
  const text = `🎛️ Switchroom restarted — ready. (took ~${ageSec}s)`
  process.stderr.write(`telegram gateway: ${site}: posting legacy banner chat_id=${chatId}\n`)
  // #1075: thread-id-bearing call — route through robustApiCall so a
  // stale thread (THREAD_NOT_FOUND) becomes a swallowed log line, not
  // a crash. Use retryWithThreadFallback so the banner still lands on
  // the main chat when the topic is gone.
  retryWithThreadFallback(
    robustApiCall,
    (tid) =>
      lockedBot.api.sendRichMessage(chatId, richMessage(text), {
        ...(tid != null ? { message_thread_id: tid } : {}),
        ...(ackMessageId != null ? { reply_parameters: { message_id: ackMessageId } } : {}),
      }),
    { threadId, chat_id: chatId, verb: 'legacy-banner' },
  )
    .then((sent) => {
      if (HISTORY_ENABLED) {
        try {
          recordOutbound({
            chat_id: chatId,
            thread_id: threadId ?? null,
            message_ids: [sent.message_id],
            texts: [text],
            attachment_kinds: [],
          })
        } catch {
          /* best-effort */
        }
      }
    })
    .catch((err: Error) => {
      process.stderr.write(
        `telegram gateway: ${site}: legacy banner send failed: ${err.message}\n`,
      )
    })
}

// ─── Session/PTY tail state ───────────────────────────────────────────────
// The pinned progress card was deleted in #1122 PR3. The variables below
// are retained as permanent `null` so the dozens of optional-chained
// call sites scattered through this file (`progressDriver?.ingest(...)`,
// `unpinProgressCardForChat?.(...)`, etc.) remain valid TypeScript and
// short-circuit to no-ops at runtime. `progressDriver` is typed `any`
// so TS doesn't resolve `progressDriver?.X` to `never`.
const streamMode = process.env.SWITCHROOM_TG_STREAM_MODE ?? 'checklist'
// Per-agent stream throttle override via channels.telegram.stream_throttle_ms.
// When unset, draft-stream.ts applies DM/group defaults (400 ms DMs, 1000 ms
// groups). Parsed once at boot; sub-zero / NaN values fall back to undefined
// so the per-chat-type default wins. See `src/agents/scaffold.ts`
// `channelsToEnv()` for the yaml → env wiring.
const STREAM_THROTTLE_MS_OVERRIDE: number | undefined = (() => {
  const raw = process.env.SWITCHROOM_TG_STREAM_THROTTLE_MS
  if (raw == null || raw === '') return undefined
  const n = Number.parseInt(raw, 10)
  return Number.isFinite(n) && n >= 0 ? n : undefined
})()
const TURN_FLUSH_SAFETY_ENABLED = isTurnFlushSafetyEnabled()

// When SET, the answer-lane stream (telegram-plugin/answer-stream.ts) renders
// the model's transcript text as a USER-VISIBLE edit-in-place message. Default
// OFF: the lane stays dormant and the reply tool is the single canonical
// formatted message — no unformatted preliminary that flashes and gets deleted.
// With this flag on, minInitialChars is set to 1 and the first text chunk opens
// a visible preview immediately. At turn_end, if the model never called reply /
// stream_reply AND the streamed message has substantive captured text, the
// gateway materializes it as a pinged final answer (materialize()) and deletes
// the silent preview. When the model uses an explicit reply tool the prior
// streamed message is retracted instead.
// The draft transport (sendMessageDraft) is permanently retired — both ON and
// OFF use sendMessage + editMessageText; the difference is whether a visible
// preview is opened at all.
// Opt back IN per agent with SWITCHROOM_VISIBLE_ANSWER_STREAM=1.
const ANSWER_STREAM_VISIBLE_ENABLED = parseVisibleAnswerStreamEnabled(
  process.env.SWITCHROOM_VISIBLE_ANSWER_STREAM,
)
// Single source of truth for the answer-lane behaviour. The draft transport
// (sendMessageDraft) is permanently retired — the lane is either VISIBLE
// (opt-in) or DORMANT (the unconditional default: reply tool is the only
// message). Resolved here once and consulted at the createAnswerStream config,
// the materialize-as-answer guard, and the boot log.
const ANSWER_LANE = resolveAnswerLaneConfig({
  visibleEnabled: ANSWER_STREAM_VISIBLE_ENABLED,
})

// Whether to DELETE the activity/status feed when the final answer lands.
// Default OFF (2026-06-04, operator request): the status message stays in the
// chat as a record (finalized to an all-done render) instead of being deleted
// — no post-then-delete flicker. Opt IN per agent via
// channels.telegram.clear_status_on_completion: true (→ this env). See the
// clearActivitySummary doc-comment.
const CLEAR_STATUS_ON_COMPLETION = (() => {
  const raw = process.env.SWITCHROOM_TG_CLEAR_STATUS_ON_COMPLETION
  if (raw == null) return false
  const v = raw.trim().toLowerCase()
  return v === '1' || v === 'true' || v === 'on' || v === 'yes'
})()

// Whether to SILENTLY pin the already-rendered status message while its work
// is in-flight (auto-unpinned on completion). Default ON (silent + low-risk):
// keeps in-flight work in view when the conversation scrolls past it. This is
// the ONE sanctioned pin under `chat-is-the-single-source-of-truth` — it pins
// a message the chat ALREADY rendered (the per-turn activity/status message,
// the `🛠 Worker` message), never a new parallel surface, never with a device
// buzz. Opt OUT per agent via channels.telegram.pin_status_while_working: false
// (→ this env). See status-pin.ts / status-pin-driver.ts and
// `reference/invariants.md` § chat-is-the-single-source-of-truth.
const PIN_STATUS_WHILE_WORKING = (() => {
  const raw = process.env.SWITCHROOM_TG_PIN_STATUS_WHILE_WORKING
  if (raw == null) return true // default ON
  const v = raw.trim().toLowerCase()
  return !(v === '0' || v === 'false' || v === 'off' || v === 'no')
})()

// ─── Status-pin: single-owner state + reconcile ────────────────────────────
// EXACTLY ONE owner of pin state. Every desired-state change for a key routes
// through `reconcileStatusPin`, which computes ONE action (pin|unpin|noop) via
// the pure `decidePinAction` and executes it through `reconcilePin` (which
// drops the claim on unpin even if the API throws — so pin state can never get
// stuck). Two desired-state sources feed distinct keys:
//   - foreground: `fg:<statusKey>` — pinned while the per-turn activity message
//     is in-flight; unpinned at the canonical turn-end (purgeReactionTracking).
//   - background: `wk:<agentId>`   — pinned while the `🛠 Worker` message runs;
//     unpinned on that worker's completion (worker-feed finish).
// It does NOT touch the reply / stream_reply send handlers (the v1 bug was send
// handlers unconditionally unpinning on every send) and runs NO polling
// watchdog / getChat().pinned_message reconciler.
const statusPinState = new Map<string, PinState>()
// Companion registry: pinKey → chatId, so the pre-restart sweep can unpin
// owned pins without threading the chat id through every call site. Written on
// every desired-pinned reconcile, cleared alongside the state on unpin.
const statusPinChatIds = new Map<string, string>()

// Durable snapshot of the pin claim set on the persistent per-agent volume
// (STATE_DIR = /state/agent/telegram in prod). Closes the crash hole: the
// in-memory Maps alone empty on restart, so a status pin left dangling by a
// crashed session is never unpinned and the service-message-deletion handler
// can't recognise it as ours. Every reconcile persists the current claim set;
// boot cleanup (statusPinBootCleanup, wired after lockedBot is defined) unpins
// each persisted entry and clears the store. STATIC mode and feature-off skip
// disk. Mirrors obligation-store.ts.
const STATUS_PIN_STORE_PATH = join(STATE_DIR, 'status-pins.json')
const statusPinStoreFs = {
  readFileSync: (p: string) => readFileSync(p, 'utf8'),
  writeFileSync: (p: string, d: string) => writeFileSync(p, d),
  renameSync: (a: string, b: string) => renameSync(a, b),
  existsSync: (p: string) => existsSync(p),
}
const statusPinPersistEnabled = !STATIC && PIN_STATUS_WHILE_WORKING

// Slot-banner pin persistence (#421 crash-recovery). The slot banner is pinned
// in the owner chat when the agent is on a non-default OAuth slot. Rather than a
// parallel store + second boot hook, its pin is persisted in the SAME
// status-pins.json store under a distinct `banner:` pinKey, so the ONE existing
// runStatusPinBootCleanup unpins an orphaned banner on boot for free. Held at
// module scope so snapshotStatusPins() can fold it into the persisted set — that
// keeps the two pin kinds (map-backed status pins + this banner row) from
// clobbering each other's rows when either path rewrites the snapshot.
const BANNER_PIN_KEY = 'banner:owner'
let bannerPersistedRow: PersistedStatusPin | null = null
// Banner persistence rides the same "store is usable" gate as status pins minus
// the worker-pin feature flag: the banner is an independent feature, so it must
// persist/recover whenever there's a real state volume (STATIC = no volume/dry
// run → no-op). The boot-cleanup gate below is widened to cover this.
const bannerPinPersistEnabled = !STATIC

// The map-backed status-pin claim set only (fg:/wk: rows), from the Maps.
function snapshotStatusPinMapRows(): PersistedStatusPin[] {
  const snapshot: PersistedStatusPin[] = []
  for (const [pinKey, state] of statusPinState) {
    const chatId = statusPinChatIds.get(pinKey)
    if (chatId == null) continue
    snapshot.push({ pinKey, chatId, messageId: state.messageId })
  }
  return snapshot
}

// The full live claim set persisted to disk: the map-backed status pins PLUS the
// slot-banner row (if any). Both pin kinds share status-pins.json, so every
// write must carry the other kind's rows through unchanged.
function snapshotStatusPins(): PersistedStatusPin[] {
  const snapshot = snapshotStatusPinMapRows()
  if (bannerPersistedRow) snapshot.push(bannerPersistedRow)
  return snapshot
}

// Persist (or drop) the slot-banner's pin row into the shared store, carrying
// the live status-pin rows through unchanged. Best-effort + gated: no-op when
// the store isn't usable (STATIC). Mirrors persistStatusPins' fail-open contract.
function persistBannerRow(row: PersistedStatusPin | null): void {
  if (!bannerPinPersistEnabled) return
  bannerPersistedRow = row
  persistStatusPins(STATUS_PIN_STORE_PATH, statusPinStoreFs, snapshotStatusPins())
}

// The live claim set EXCLUDING one key — used by reconcileAndPersistStatusPin so
// it can rewrite the whole set atomically while it flips that one key's record
// between pending / confirmed / absent.
function snapshotStatusPinsExcept(exceptKey: string): PersistedStatusPin[] {
  return snapshotStatusPins().filter((p) => p.pinKey !== exceptKey)
}

// The Bot API surface the pin driver needs. `lockedBot` is defined later; wrap
// lazily so this helper can be declared alongside the state it owns.
function statusPinApi(): PinBotApi {
  return {
    pinChatMessage: (chat_id, message_id, opts) =>
      robustApiCall(
        () => lockedBot.api.pinChatMessage(chat_id, message_id, opts),
        { chat_id: String(chat_id), verb: 'status-pin.pin' },
      ),
    unpinChatMessage: (chat_id, message_id) =>
      robustApiCall(
        () => lockedBot.api.unpinChatMessage(chat_id, message_id),
        { chat_id: String(chat_id), verb: 'status-pin.unpin' },
      ),
  }
}

/**
 * Boot-time orphan cleanup — thin gateway wrapper over the pure
 * `runStatusPinBootCleanup` (which owns the load → best-effort-unpin →
 * empty-store contract). Binds the live fs seam, the robust unpin api, and the
 * gateway logger.
 *
 * MUST run ONLY after this gateway wins the startup mutex (the store is a
 * shared per-agent file; a losing double-boot would unpin the live holder's
 * legitimate pins). Runs before any new pin claim is written, so the emptied
 * store leaves the service-message handler's ownership check with no false
 * positives.
 */
async function statusPinBootCleanup(): Promise<void> {
  // Runs when EITHER pin kind could have written the shared store: the
  // map-backed status pins (statusPinPersistEnabled) or the slot banner
  // (bannerPinPersistEnabled). A single cleanup drains ALL orphaned rows —
  // status pins AND banner alike — since they share status-pins.json.
  if (!statusPinPersistEnabled && !bannerPinPersistEnabled) return
  const api = statusPinApi()
  const { cleared, total } = await runStatusPinBootCleanup({
    path: STATUS_PIN_STORE_PATH,
    fs: statusPinStoreFs,
    unpin: (chatId, messageId) => api.unpinChatMessage(chatId, messageId),
  })
  if (total > 0) {
    process.stderr.write(
      `telegram gateway: status-pin: cleared ${cleared}/${total} ` +
        `orphaned pin(s) from a prior session\n`,
    )
  }
}
// NOTE: statusPinBootCleanup() is deliberately NOT invoked here at import time.
// The status-pin store is a SHARED per-agent file, and cleanup issues real
// unpinChatMessage calls. On a double-boot the losing gateway must NOT touch
// that shared state — its unpins would strip pins the STILL-ALIVE holder
// legitimately owns. So the call is gated on winning the startup mutex
// (top-level await below); see the acquireStartupLock block.

/**
 * The single entry point that mutates pin state for `pinKey`. Serialises
 * nothing itself — callers fire-and-forget; the pure decision + drop-on-unpin
 * contract keep state consistent. No-op when the feature is disabled.
 */
async function reconcileStatusPin(
  pinKey: string,
  chatId: string,
  desired: DesiredPin,
): Promise<void> {
  // Fire-and-forget hard boundary. Most callers invoke this as
  // `void reconcileStatusPin(...)` (auto status-pin is best-effort — it must
  // never affect turn flow). reconcilePin already swallows pin/unpin API
  // errors via onError, but the surrounding persistence + Map bookkeeping
  // (and any future edge) could still reject the returned promise. A rejected
  // fire-and-forget promise becomes a process-level `unhandledRejection` which
  // the gateway's handler crashes on — that is exactly how a benign
  // "not enough rights to manage pinned messages" 400 in a supergroup took the
  // whole gateway down (marko, 2026-07-01). Auto status-pin is cosmetic; it
  // must NEVER be able to crash the gateway. Any throw here is logged and
  // absorbed. (The `pin_message` MCP tool still surfaces failures to the agent
  // as a normal tool-error — that path is `executePinMessage`, not this one.)
  try {
    await reconcileStatusPinInner(pinKey, chatId, desired)
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err)
    process.stderr.write(
      `telegram gateway: status-pin reconcile absorbed error ` +
        `(key=${pinKey} chat=${chatId}): ${msg}\n`,
    )
  }
}

async function reconcileStatusPinInner(
  pinKey: string,
  chatId: string,
  desired: DesiredPin,
): Promise<void> {
  if (!PIN_STATUS_WHILE_WORKING) return
  if (chatId.length === 0) return
  const prev = statusPinState.get(pinKey) ?? null

  const runReconcile = () =>
    reconcilePin({
      api: statusPinApi(),
      chatId,
      prevState: prev,
      desired,
      onError: (phase, err) => {
        const msg = err instanceof Error ? err.message : String(err)
        process.stderr.write(
          `telegram gateway: status-pin ${phase} failed (key=${pinKey} chat=${chatId}): ${msg}\n`,
        )
      },
    })

  // Classify the action so we persist INTENT before the pin API call. Only a
  // fresh `pin` of a message that isn't already our claim opens the leak window
  // (the API call actually pins something new); everything else (unpin, noop,
  // re-pin of the same id) clears / leaves the record and is safe to persist
  // after. See reconcileAndPersistStatusPin for the ordering rationale.
  const action = decidePinAction(prev, desired)
  const op: StatusPinPersistOp =
    action.kind === 'pin'
      ? { kind: 'pin', messageId: action.messageId }
      : { kind: 'clear' }

  if (!statusPinPersistEnabled) {
    // Persistence off (STATIC / feature-off): just reconcile + update Maps.
    const next = await runReconcile()
    if (next == null) {
      statusPinState.delete(pinKey)
      statusPinChatIds.delete(pinKey)
    } else {
      statusPinState.set(pinKey, next)
      statusPinChatIds.set(pinKey, chatId)
    }
    return
  }

  // Persist-BEFORE-pin ordering lives in reconcileAndPersistStatusPin: for a
  // pin it writes a `pending` record first, then confirms it after the API call
  // lands (or drops it on failure). A crash in the window leaves a pending
  // record boot cleanup will unpin. In-memory Maps are updated from the result.
  const next = await reconcileAndPersistStatusPin({
    path: STATUS_PIN_STORE_PATH,
    fs: statusPinStoreFs,
    pinKey,
    chatId,
    op,
    snapshotOthers: () => snapshotStatusPinsExcept(pinKey),
    applyPin: runReconcile,
  })
  if (next == null) {
    statusPinState.delete(pinKey)
    statusPinChatIds.delete(pinKey)
  } else {
    statusPinState.set(pinKey, next)
    statusPinChatIds.set(pinKey, chatId)
  }
}

/**
 * Background-worker desired-pin, driven off the live `🛠 Worker` message.
 * Reads the worker feed's current message_id (the EXISTING message — we pin
 * what the feed already rendered, never a new send) and reconciles a silent
 * pin while it's running / an unpin on completion. No-op until the feed has
 * actually painted a message for this worker (trivial sub-second workers stay
 * silent and are never pinned). Keyed `wk:<agentId>`.
 */
function reconcileWorkerPin(
  agentId: string,
  chatId: string | null,
  running: boolean,
): void {
  if (!PIN_STATUS_WHILE_WORKING) return
  const key = `wk:${agentId}`
  if (!running) {
    // Unpin: recover the chat we pinned in (caller may not have it at
    // completion). No-op when nothing was pinned for this worker.
    const unpinChat = chatId ?? statusPinChatIds.get(key)
    if (unpinChat == null) return
    void reconcileStatusPin(key, unpinChat, { pinned: false })
    return
  }
  if (chatId == null) return
  const messageId = workerActivityFeed?.messageIdOf(agentId) ?? null
  if (messageId == null) return // no message painted yet — nothing to pin
  void reconcileStatusPin(key, chatId, { pinned: true, messageId })
}

/** Unpin every owned status pin — used by the pre-restart sweep so a
 *  crash / interrupt never leaves a permanent pin behind. Best-effort;
 *  clears the claim regardless of the unpin outcome (drop-on-unpin). */
async function unpinAllStatusPins(): Promise<void> {
  const keys = [...statusPinState.keys()]
  for (const key of keys) {
    const st = statusPinState.get(key)
    if (st == null) continue
    // Recover the chat id from the state map's companion key registry.
    const chatId = statusPinChatIds.get(key)
    if (chatId == null) { statusPinState.delete(key); continue }
    await reconcileStatusPin(key, chatId, { pinned: false })
  }
}

// Activity feed. The gateway streams a live "what it's doing" tool-activity
// feed for every turn. The PreToolUse sidecar emits a `tool_label` per tool
// call (flush-independent, so it stays real-time on fast/clustered-tool
// turns); each label appends to `turn.mirrorLines`, and `renderActivityFeed`
// renders the capped list into an in-place EDITED message (sendMessage +
// editMessageText) anchored as a native reply-quote to the user's question.
// The feed clears on the first reply (hand-off to the answer) and again at
// turn_end (the no-reply safety net). It does NOT touch the answer-stream's
// draft/visible lane — the two render on separate surfaces, so they never
// collide.
// eslint-disable-next-line @typescript-eslint/no-explicit-any
const progressDriver: any = null
const unpinProgressCardForChat: ((chatId: string, threadId: number | undefined) => void) | null = null
const getPinnedProgressCardMessageId: ((turnKey: string, agentId?: string) => number | null) | null = null
const completeProgressCardTurn:
  | ((args: { chatId: string; threadId: number | undefined; turnKey: string }) => void)
  | null = null
// #1122 PR3: flushProgressCardsForShutdown deleted with the card. No
// replacement needed — there are no pinned progress messages to flush.
let subagentWatcher: SubagentWatcherHandle | null = null
// Background-worker activity feed manager. Module-scoped so shutdown can stop()
// its internal heartbeat interval (mirrors subagentWatcher). Recreated per
// bridge connect; the stale handle's interval is unref'd, so a missed stop()
// can't keep the process alive, but we stop() on shutdown for cleanliness.
let workerActivityFeed: ReturnType<typeof createWorkerActivityFeed> | null = null

// ─── IPC server ───────────────────────────────────────────────────────────
const SOCKET_PATH = process.env.SWITCHROOM_GATEWAY_SOCKET ?? join(STATE_DIR, 'gateway.sock')
// Ensure the directory for the socket exists
mkdirSync(STATE_DIR, { recursive: true, mode: 0o700 })

// PID file + session marker. See pid-file.ts and session-marker.ts for
// the 2026-04-22 incident that motivates these. The PID file lets the
// in-agent plugin distinguish "gateway gone" from "socket blinked on a
// live gateway"; the session marker lets the crash-recovery banner
// distinguish a real process restart from a grammY poll-restart.
const GATEWAY_PID_PATH = process.env.SWITCHROOM_GATEWAY_PID_FILE ?? join(STATE_DIR, 'gateway.pid.json')
const GATEWAY_SESSION_MARKER_PATH = process.env.SWITCHROOM_GATEWAY_SESSION_MARKER ?? join(STATE_DIR, 'gateway-session.json')
// Separate from gateway-session.json (which fires the recovery banner on a
// real process restart) and from restart-pending.json (the user-initiated
// /restart marker carrying chat_id + ack_message_id). This one is written
// by the SIGTERM/SIGINT handler so the next boot can suppress the
// "recovered from unexpected restart" banner for planned shutdowns.
const GATEWAY_CLEAN_SHUTDOWN_MARKER_PATH = process.env.SWITCHROOM_GATEWAY_CLEAN_SHUTDOWN_MARKER ?? join(STATE_DIR, 'clean-shutdown.json')
const GATEWAY_STARTED_AT_MS = Date.now()

// Boot card: feature flag (default on) + handle for unpinning on first turn
const BOOT_CARD_ENABLED = process.env.SWITCHROOM_BOOT_CARD !== 'false'
let activeBootCard: BootCardHandle | null = null
// In-flight indicator for the boot card sendMessage. Set synchronously
// at the start of an emission, cleared in finally. The bridge-reconnect
// dedupe checks this so it can't race against the boot path's await.
// See issue #489 (klanker msgId 4715 + 4716, 2026-05-01 10:13:15).
let bootCardPending = false

// Issues card (#428) — pinned per-agent surface listing current
// unresolved entries from the issue sink (#425). Idempotent across
// the bridge-reconnect and boot-card paths so we never spawn two
// watchers per gateway lifetime.
const ISSUES_CARD_ENABLED = process.env.SWITCHROOM_ISSUES_CARD !== 'false'
let activeIssuesCard: IssuesCardHandle | null = null
let activeIssuesWatcher: IssuesWatcherHandle | null = null

/**
 * Idempotently start the issues card + watcher for this gateway. Called
 * from both the boot-path and bridge-reconnect paths once we've
 * resolved the chat to post into. Subsequent calls are no-ops — the
 * first call wins for the gateway's lifetime.
 */
function ensureIssuesCard(chatId: string, threadId: number | undefined): void {
  if (!ISSUES_CARD_ENABLED) return
  if (activeIssuesCard != null) return
  const agentSlug = process.env.SWITCHROOM_AGENT_NAME ?? '-'
  const agentDisplayName = resolvePersonaName(agentSlug)
  const stateDir = process.env.TELEGRAM_STATE_DIR
  if (!stateDir) {
    process.stderr.write(
      `telegram gateway: issues-card: TELEGRAM_STATE_DIR unset, skipping\n`,
    )
    return
  }
  const botApi: import('../issues-card.js').BotApiForIssuesCard = wrapIssuesCardApi(threadId)
  activeIssuesCard = createIssuesCardHandle({
    agentName: agentDisplayName,
    chatId,
    threadId,
    bot: botApi,
    log: (msg) => process.stderr.write(`telegram gateway: ${msg}\n`),
    // Closes #472 finding #19 — persist the card's message_id so a
    // gateway crashloop edits the existing pinned card on every boot
    // instead of posting a duplicate. Lives in the gateway's per-agent
    // state dir alongside other ephemerals.
    persistPath: join(stateDir, 'issues-card.json'),
  })
  activeIssuesWatcher = startIssuesWatcher({
    stateDir,
    card: activeIssuesCard,
    log: (msg) => process.stderr.write(`telegram gateway: ${msg}\n`),
  })
  process.stderr.write(
    `telegram gateway: issues-card: started watcher chat_id=${chatId} thread_id=${threadId ?? '-'} state_dir=${stateDir}\n`,
  )
}

// Startup mutex. Atomic single-writer claim on the PID file so two
// gateway processes can't race on Telegram's getUpdates long-poll.
// See startup-mutex.ts for the 2026-04-23 incident this closes
// (clerk-gateway looped 13+ times on 409 Conflict because the OLD
// process's long-poll TCP socket hadn't FIN'd before the NEW one
// started polling).
//
// Behaviour:
//   - acquired       → we own the file, log boot.lock_acquired, continue
//   - blocked (alive holder)  → log boot.lock_blocked, exit(1).
//                                systemd's restart-burst limiter
//                                (StartLimitBurst=10/IntervalSec=60)
//                                handles the back-off so we don't
//                                hot-loop spawning processes.
//   - acquired with stale recovery → log boot.lock_stale_recovered then
//                                     boot.lock_acquired
//
// We use top-level await so the mutex resolves BEFORE any other module
// code runs (in particular before the bot.start IIFE further down).
{
  const SWITCHROOM_AGENT_NAME = process.env.SWITCHROOM_AGENT_NAME ?? '-'
  try {
    const outcome = await acquireStartupLock({
      path: GATEWAY_PID_PATH,
      record: { pid: process.pid, startedAtMs: GATEWAY_STARTED_AT_MS },
      agentName: SWITCHROOM_AGENT_NAME,
    })
    if (outcome.status === 'blocked') {
      // Another live gateway already owns the lock. Exit non-zero so
      // systemd applies its restart-burst backoff. Logging done by
      // acquireStartupLock; add one extra line so the operator sees
      // WHY we're exiting.
      process.stderr.write(
        `telegram gateway: boot.aborting another_gateway_is_live holder_pid=${outcome.holder.pid} agent=${SWITCHROOM_AGENT_NAME}\n`,
      )
      process.exit(1)
    }
    // Backwards compatibility: the non-atomic writePidFile() that this
    // block REPLACES used to log a `wrote PID file` line. Keep an
    // equivalent so anything grepping older logs still finds it.
    process.stderr.write(
      `telegram gateway: wrote PID file ${GATEWAY_PID_PATH} pid=${process.pid} startedAt=${GATEWAY_STARTED_AT_MS}\n`,
    )
    // We WON the startup mutex — this gateway is the sole live owner of the
    // shared per-agent status-pin store, so it's now safe to clean up orphaned
    // pins from a prior (dead) session. Gated here (not at import time) so a
    // LOSING double-boot never unpins the live holder's legitimate pins.
    // Fire-and-forget: cleanup is best-effort and must not block boot.
    void statusPinBootCleanup()
  } catch (err) {
    process.stderr.write(
      `telegram gateway: boot.lock_acquire_failed err=${(err as Error).message} agent=${SWITCHROOM_AGENT_NAME}\n`,
    )
    // Fall through to the legacy non-atomic write so we don't make
    // things WORSE on filesystems where link() doesn't work (FAT, some
    // FUSE mounts). The mutex is best-effort defence-in-depth; the
    // existing pid-file probe + 409-retry loop are still in place.
    try {
      writePidFile(GATEWAY_PID_PATH, { pid: process.pid, startedAtMs: GATEWAY_STARTED_AT_MS })
      process.stderr.write(`telegram gateway: wrote PID file ${GATEWAY_PID_PATH} pid=${process.pid} startedAt=${GATEWAY_STARTED_AT_MS} (mutex-fallback)\n`)
      // Mutex was unavailable (link() unsupported fs); the legacy pid-file
      // probe + 409-retry loop is still the liveness guard on this path. A
      // successful writePidFile here means no live holder was detected, so
      // running orphan cleanup is consistent with the pre-mutex behaviour.
      void statusPinBootCleanup()
    } catch (writeErr) {
      process.stderr.write(`telegram gateway: writePidFile failed: ${writeErr}\n`)
    }
  }
}

// #1122: framework safety-net for "model is silent to the user for >5min."
// Starts a single setInterval poll that walks active turns; at 300s of
// silence the framework unwedges the turn. The generic "still working… /
// still thinking…" stall message it used to send was a stop-gap from
// before the live draft carried the progress beats and has been retired
// (the stall-stop-gap PR) — the surviving user-visible sends are the
// deterministic update_apply phase line and the approval-blocked re-ping.
// The model-targeted nudge ladder (ack/soft/firm) and the 60s awareness
// ping were retired earlier once the live-updating reply/draft took over
// the pacing job — only this single unwedge fallback remains. Honours
// SWITCHROOM_DISABLE_SILENCE_POKE=1 kill switch (no-op if set).
// Set when this gateway dispatches an `update_apply` to hostd that
// returns `started`; cleared when the dispatch poll resolves (terminal
// / not-configured / timeout). While set, the framework silence
// fallback substitutes hostd's real phase + elapsed for the generic
// "still working…" text — deterministic, model-free, the klanker
// incident fix. In-memory only; a gateway recreate naturally resets it.
let inFlightUpdate: { requestId: string; startedAt: number } | null = null

// Fix A — silence-fallback tuning (status-surface darkening, 2026-06-05). A long
// quiet tool stretch (foreground sub-agent / big research) crossed the 300s
// fallback and nulled currentTurn, darkening the live activity feed mid-work.
//   SWITCHROOM_SILENCE_FALLBACK_MS         — base threshold (default 300000)
//   SWITCHROOM_SILENCE_FALLBACK_HARD_MS    — hard ceiling for the in-flight-tool
//                                            defer (default 900000 = 15min)
//   SWITCHROOM_SILENCE_DEFER_INFLIGHT_TOOLS=1 — enable the defer. NOTE: this is
//                                            now set fleet-wide in defaults.env
//                                            (was a marko canary against #2162;
//                                            promoted to the fleet default). The
//                                            code default below is still OFF, so
//                                            the live behaviour comes from config.
function parsePositiveMsEnv(name: string, fallbackMs: number): number {
  const raw = process.env[name]
  if (raw == null || raw === '') return fallbackMs
  const n = Number(raw)
  return Number.isFinite(n) && n > 0 ? Math.floor(n) : fallbackMs
}
const SILENCE_FALLBACK_MS = parsePositiveMsEnv('SWITCHROOM_SILENCE_FALLBACK_MS', 300_000)
const SILENCE_FALLBACK_HARD_MS = parsePositiveMsEnv('SWITCHROOM_SILENCE_FALLBACK_HARD_MS', 900_000)
// #2527 — mid-turn liveness floor threshold (default 45s). The early, quiet
// beat: a `user` turn working silently this long without a substantive answer
// gets ONE honest "still on it" interim, so the ambient 👀 never masquerades
// as "done". Strictly below SILENCE_FALLBACK_MS (the loud 300s unwedge).
// Whole floor is kill-switchable via SWITCHROOM_TG_LIVENESS_FLOOR=0.
const SILENCE_FLOOR_MS = parsePositiveMsEnv('SWITCHROOM_SILENCE_FLOOR_MS', 45_000)
// #2527 — role-aware terminal reaction honesty (the "thumbs-up false done"
// fix). Default ON; SWITCHROOM_TG_TERMINAL_HONESTY=0 reverts to always-👍.
const LIVENESS_TERMINAL_HONESTY = process.env.SWITCHROOM_TG_TERMINAL_HONESTY !== '0'
// SILENCE_DEFER_INFLIGHT_TOOLS: previously an opt-in (=1). The new
// isLegitimatelyWorking callback supersedes this — defer is now the DEFAULT
// when the callback is wired. The legacy flag is kept so `=0` still lets
// operators force-disable the defer (handled inside silence-poke.ts tick()).
// The old `=1` path is kept for back-compat but is now redundant.
const SILENCE_DEFER_INFLIGHT_TOOLS = process.env.SWITCHROOM_SILENCE_DEFER_INFLIGHT_TOOLS === '1'
// Production-liveness (2026-06-05 UAT finding). Count an activity-feed render or
// an answer-stream draft update as liveness for the silence clock, so a long
// tool/composition turn that's visibly producing doesn't trip the 300s fallback
// and null currentTurn mid-work. Default ON; SWITCHROOM_SILENCE_LIVENESS_PRODUCTION=0
// restores the legacy "only a real reply resets the clock" behaviour.
const SILENCE_LIVENESS_PRODUCTION = process.env.SWITCHROOM_SILENCE_LIVENESS_PRODUCTION !== '0'

/**
 * Feed-survival predicate — the single source of truth for "is this turn
 * legitimately working?" used by BOTH teardown timers (orphaned-reply fuse
 * and silence-poke framework fallback).
 *
 * Returns true if ANY of the following hold for the given chat key:
 *
 *   (a) A foreground tool call is in flight in the current turn
 *       (`toolFlightTracker.isMidToolCall()`). This covers most tools
 *       including ask_user while it blocks awaiting a tap.
 *
 *   (b) Detached background work was dispatched in the current turn and has
 *       not yet resolved — `pendingProgress.hasPendingAsyncDispatch(key)`.
 *       Covers `Bash run_in_background:true` (which returns a near-instant
 *       handle, emptying inFlight, while the background process keeps
 *       running) and `Agent` / `Task` dispatches.
 *
 *   (c) A human-wait tool (`ask_user`) is open for this chat. A pending
 *       ask_user IS already captured by (a) while the tool_use is in flight,
 *       but we include the explicit pendingAskUser check for defence-in-depth
 *       (e.g. after an unlikely inFlight clear without a tool_result).
 *
 * The key is `statusKey(chatId, threadId)` — the same key used by
 * silencePoke / pendingProgress.
 */
function isLegitimatelyWorking(key: string): boolean {
  // (a) foreground in-flight tool.
  // NOTE: toolFlightTracker is GLOBAL, not per-key. In a hypothetical
  // multi-chat agent a tool in flight for chat A would make this return
  // true for chat B's key. Accepted: the gateway runs one Claude session
  // (one turn in flight at a time); true multi-chat concurrency is not
  // currently supported. (b) and (c) below are correctly per-key.
  if (toolFlightTracker.isMidToolCall()) return true
  // (b) detached background work dispatched this turn
  if (pendingProgress.hasPendingAsyncDispatch(key)) return true
  // (c) ask_user open for this chat (defence-in-depth)
  const { chatId: keyChatId } = parseKeyForSurvival(key)
  for (const entry of pendingAskUser.values()) {
    if (entry.chatId === keyChatId) return true
  }
  return false
}

/** Parse `<chatId>:<threadIdOrEmpty>` — mirrors silence-poke's parseKey.
 *  Local copy so we don't need to re-export from silence-poke. */
function parseKeyForSurvival(key: string): { chatId: string } {
  const idx = key.indexOf(':')
  return { chatId: idx < 0 ? key : key.slice(0, idx) }
}

silencePoke.startTimer({
  thresholdsMs: { fallback: SILENCE_FALLBACK_MS, fallbackHardCeiling: SILENCE_FALLBACK_HARD_MS, floor: SILENCE_FLOOR_MS },
  deferFallbackWhileToolInFlight: SILENCE_DEFER_INFLIGHT_TOOLS,
  isLegitimatelyWorking: (key) => isLegitimatelyWorking(key),
  emitMetric: (event) => {
    // Re-emit through the unified runtime-metrics fan-out (PostHog + JSONL).
    emitRuntimeMetric(event)
  },
  // #2527 — the gateway-owned half of the mid-turn-floor decision: only the
  // live turn knows its loop role + whether a substantive answer has landed.
  // Keyed on statusKey so a DM (threadId null) and a forum topic are identical.
  floorState: (key) => {
    const turn = currentTurn
    if (turn == null) return null
    if (statusKey(turn.sessionChatId, turn.sessionThreadId) !== key) return null
    return { role: turn.role, finalAnswerDelivered: turn.finalAnswerDelivered }
  },
  // #2527 — the early, quiet liveness beat. Honest text from the longest
  // in-flight tool (model-free, claude-native), routed through the SAME send
  // path as the 300s fallback; pings OFF (this is the gentle beat, not the
  // loud unwedge) and the turn is NOT torn down — it keeps working.
  onMidTurnFloor: async (ctx) => {
    // Late-fire guard, mirroring the fallback: a clean turn-end can race the
    // tick. If the turn is gone, stay silent.
    if (activeTurnStartedAt.get(ctx.key) == null && currentTurn == null) return
    const blockedOnApproval = activeStatusReactions
      .get(statusKey(ctx.chatId, ctx.threadId))
      ?.isAwaiting() ?? false
    const text = silencePoke.formatFrameworkFallbackText(
      'working',
      ctx.silenceMs,
      ctx.inFlightTools,
      blockedOnApproval,
    )
    // The stall-notice stop-gap is retired: `formatFrameworkFallbackText`
    // returns null for the pure-liveness "still working / running <Tool>"
    // beat (the only string it still emits is the approval-blocked re-ping).
    // The early quiet floor beat existed ONLY to surface that stall notice, so
    // with the notice gone there is nothing to send here unless the turn is
    // parked on an approval card. Skip silently otherwise; the live draft +
    // the model's own pacing beats carry progress.
    if (text == null) return
    try {
      await robustApiCall(
        () => bot.api.sendMessage(ctx.chatId, text, {
          ...(ctx.threadId != null ? { message_thread_id: ctx.threadId } : {}),
          // The quiet beat: visible in-thread, no device buzz. (The 300s
          // fallback pings; the floor must not train the user to mute.)
          disable_notification: true,
        }),
        { chat_id: ctx.chatId, ...(ctx.threadId != null ? { threadId: ctx.threadId } : {}) },
      )
      // Count it as production so the silence clock resets — the user just
      // saw a real message, so the 300s loud fallback is measured from here.
      silencePoke.noteProduction(ctx.key, Date.now())
    } catch (err) {
      process.stderr.write(
        `silence-poke mid-turn floor sendMessage failed chat=${ctx.chatId} thread=${ctx.threadId}: ${err}\n`,
      )
    }
  },
  onFrameworkFallback: async (ctx) => {
    // Late-fire short-circuit (2026-05-23 audit finding). The fallback
    // can race a clean turn-end: the model's actual reply lands inside
    // the silence window's final ~50ms, the canonical turn-end path
    // clears `activeTurnStartedAt` and nulls `currentTurn`, and then
    // this handler fires anyway. Without this check we emit a noisy
    // "still working…" ping to the user (right after they got their
    // real reply) AND a misleading "ended wedged turn ... currentTurn_
    // nulled=false drained_buffered=0/0" log line. The 7-day audit
    // showed this race accounts for ~90% of all framework_fallback log
    // events (124 of 138 `currentTurn_nulled=false` cases). Distinct
    // log line so observability still tracks the fact that the silence
    // crossed threshold; the wedge counter is no longer polluted.
    if (activeTurnStartedAt.get(ctx.key) == null && currentTurn == null) {
      process.stderr.write(
        `telegram gateway: silence-poke framework-fallback late-fire skipped — ` +
        `turn ended cleanly during silence window ` +
        `chat=${ctx.chatId} thread=${ctx.threadId ?? '-'} silence_ms=${ctx.silenceMs}\n`,
      )
      // #2527: structured skip event so the late-fire race is machine-readable.
      logStreamingEvent({
        kind: 'silence_poke_skip',
        chatId: ctx.chatId,
        threadId: ctx.threadId ?? undefined,
        silenceMs: ctx.silenceMs,
        skipReason: 'turn_ended_cleanly_during_window',
      })
      // Tell silence-poke this chat-thread is finished so the next
      // arming doesn't carry stale state.
      silencePoke.endTurn(ctx.key)
      return
    }

    // Deterministic in-flight update status (klanker incident). If this
    // gateway dispatched an update_apply that's still running, the
    // recurring framework fallback carries hostd's REAL phase + elapsed
    // instead of the content-free "still working…". No model: pure
    // get_status snapshot → pure formatter. Any hostd unavailability
    // degrades silently to the existing generic text (zero regression).
    let text: string | null = null
    // Hoisted out of the generic-fallback branch below because the send site
    // gates `disable_notification` on it: when the turn is parked on an
    // approval card, the fallback TEXT is a user-gating re-ping ("waiting for
    // your approval — tap Approve or Deny …"), and that must stay LOUD so the
    // user knows the ball is in their court. The reaction controller tracks the
    // park via setAwaiting on the permission-request.
    const blockedOnApproval = activeStatusReactions
      .get(statusKey(ctx.chatId, ctx.threadId))
      ?.isAwaiting() ?? false
    const upd = inFlightUpdate
    if (upd != null) {
      try {
        const st = await hostdGetStatusOnce(getMyAgentName(), upd.requestId)
        if (st !== 'not-configured' && st !== 'unavailable') {
          text = formatUpdateStatusLine(st, upd.startedAt, Date.now())
        }
      } catch {
        /* degrade to generic fallback below */
      }
    }
    if (text == null) {
      // Wording is load-bearing — extracted to `formatFrameworkFallbackText`
      // in `silence-poke.ts` so it can be snapshot-tested in isolation
      // (CC-4 in `docs/status-ask-cause-classes.md`). Derives "N min" suffix
      // from `ctx.silenceMs` so the wording stays honest if the 300s
      // threshold is tuned.
      // Honesty: if the turn is parked on an approval card (the dominant
      // benign "wedge" class — claude is alive, waiting on the operator's
      // tap), say so instead of "still working…". The reaction controller
      // already tracks this (setAwaiting on the permission-request park).
      text = silencePoke.formatFrameworkFallbackText(
        ctx.fallbackKind,
        ctx.silenceMs,
        ctx.inFlightTools,
        blockedOnApproval,
      )
    }
    // #2527: log the actual poke fire with structured data before sending,
    // so the event is visible even if the send fails. The stall-notice
    // stop-gap is retired (the user-visible send below is now gated), but the
    // fire event is still logged so observability + the unwedge accounting are
    // unchanged — mirrors PR #2641 (drop the chat badge, keep the log).
    logStreamingEvent({
      kind: 'silence_poke_fire',
      chatId: ctx.chatId,
      threadId: ctx.threadId ?? undefined,
      silenceMs: ctx.silenceMs,
      fallbackKind: ctx.fallbackKind,
    })
    // Send a user-visible message ONLY when there's something honest to say:
    //   - a deterministic in-flight update_apply phase (`text` set above), or
    //   - the approval-blocked re-ping (`formatFrameworkFallbackText` returns a
    //     string only for that case).
    // The generic "still working… (no update from agent in N min)" stall notice
    // is retired — `formatFrameworkFallbackText` returns null for it, so `text`
    // stays null and we skip the send. The turn-teardown below (the unwedge —
    // the one job the live draft can't do, per the conversational-pacing RFC)
    // still runs unconditionally.
    if (text != null) {
      try {
        await robustApiCall(
          () => bot.api.sendMessage(ctx.chatId, text, {
            ...(ctx.threadId != null ? { message_thread_id: ctx.threadId } : {}),
            // Conditional: when the turn is parked on an approval card, this
            // fallback carries a user-gating re-ping ("waiting for your
            // approval — tap Approve or Deny …") — that must PING, because the
            // user is the one being waited on. The deterministic update-status
            // line stays SILENT (a status surface). Gate on `blockedOnApproval`.
            disable_notification: blockedOnApproval ? false : true,
          }),
          { chat_id: ctx.chatId, ...(ctx.threadId != null ? { threadId: ctx.threadId } : {}) },
        )
      } catch (err) {
        process.stderr.write(
          `silence-poke fallback sendMessage failed chat=${ctx.chatId} thread=${ctx.threadId}: ${err}\n`,
        )
      }
    }
    // #1122 follow-up: end the wedged turn AFTER the fallback fires.
    // Without this, `activeTurnStartedAt` stays set, every subsequent
    // inbound is routed as `queued="true" prior_turn_in_progress="true"`
    // (see handleInbound mid-turn branch ~line 6160), and the user's
    // conversation is permanently stuck behind a dead turn no signal
    // will ever close. Caught by the human-style fuzz on 2026-05-13:
    // 23/23 inbounds queued behind msg 599 that never got a turn_ended.
    //
    // Cleanup mirrors the regular reply / silent-marker turn-end paths
    // (lines 4985 / 5274) so a late `turn_end` from claude — once it
    // finally exits the wedge — finds nulled state and bails at the
    // handler-entry `const turn = currentTurn` check (lines 4441,
    // 4593, etc), avoiding a double-emit / stale-turn-close on the
    // next inbound's fresh turn.
    const fbKey = ctx.key
    const fbChatId = ctx.chatId
    const fbThreadId = ctx.threadId ?? undefined
    const wedgedTurn = currentTurn
    // Match by sessionChatId + sessionThreadId before mutating
    // `currentTurn` — multi-chat agents shouldn't have their CURRENT
    // (different-chat) turn nulled by this fallback.
    const turnMatchesFallback =
      wedgedTurn != null &&
      wedgedTurn.sessionChatId === fbChatId &&
      wedgedTurn.sessionThreadId === fbThreadId
    const turnStartedAt = activeTurnStartedAt.get(fbKey)
    if (turnStartedAt != null) {
      const turnDurationMs = Date.now() - turnStartedAt
      const outboundMetrics = signalTracker.getOutboundMetrics(fbKey)
      emitRuntimeMetric({
        kind: 'turn_ended',
        chat_id: fbChatId,
        thread_id: ctx.threadId,
        duration_ms: turnDurationMs,
        ttfo_ms: outboundMetrics.ttfoMs,
        outbound_count: outboundMetrics.outboundCount,
        longest_silent_gap_ms: outboundMetrics.longestOutboundGapMs,
        ended_via: 'framework_fallback',
      })
      // #1892-follow-up: do NOT clear signalTracker state here. When the
      // model recovers post-fallback (the framework's user-visible
      // "still working" message is the load-bearing unwedge primitive —
      // see `project_silence_poke_broken_and_cross_turn_fix`), its late
      // reply calls fire `signalTracker.noteOutbound(fbKey, ...)`. If
      // state is already cleared, that's a silent no-op and the late
      // reply is invisible to outbound_count + ttfo metrics — the
      // canonical session-end path (silent-marker line 7407 or normal
      // turn-end line 7502) emits turn_ended a second time, reading
      // the empty state and reporting outbound_count=0 even though
      // replies landed. Defer clear to the canonical paths so
      // post-fallback recoveries are correctly counted.
    }
    // Stamp the turn-DB end row as `timeout` so the wedged turn doesn't
    // stay open until a SIGTERM/restart relabels it (false-negative for
    // clean completion). Mirrors the canonical stop-path at line 5250.
    if (turnsDb != null && turnMatchesFallback && wedgedTurn?.registryKey != null) {
      const _turnKey = wedgedTurn.registryKey
      const capturedJoined = wedgedTurn.capturedText.join('')
      const assistantReplyPreview = capturedJoined
        ? capturedJoined.slice(0, TURN_PREVIEW_MAX)
        : null
      try {
        recordTurnEnd(turnsDb, {
          turnKey: _turnKey,
          endedVia: 'timeout' as const,
          lastAssistantMsgId: wedgedTurn.lastAssistantMsgId,
          lastAssistantDone: wedgedTurn.lastAssistantDone,
          assistantReplyPreview,
          toolCallCount: wedgedTurn.toolCallCount,
        })
      } catch (err) {
        process.stderr.write(
          `telegram gateway: recordTurnEnd(timeout) failed turnKey=${_turnKey}: ${(err as Error).message}\n`,
        )
      }
    }
    // Bridge-watchdog (#412): clear the on-disk turn-active marker so
    // the watchdog doesn't read a stale "turn active" file after a
    // wedge-recovery. Same defence the canonical paths run at 4971,
    // 5270.
    try { removeTurnActiveMarker(STATE_DIR) } catch { /* best-effort */ }
    // Stream/lane teardown — a pinned progress card or buffered
    // preamble survives the wedge otherwise and lands on the next
    // turn. Mirror the canonical stop-path at 5228-5229; skip
    // closeProgressLane analogue from the silent-marker path because
    // we have no streams to finalize here.
    closeActivityLane(fbChatId, fbThreadId)
    closeProgressLane(fbChatId, fbThreadId)
    lastPtyPreviewByChat.delete(fbKey)
    preambleSuppressor.dropNow()
    // Drop silence-poke state and clear turn-active so the next inbound
    // for this chat starts a fresh turn instead of queueing forever.
    silencePoke.endTurn(fbKey)
    pendingProgress.noteTurnEnd(fbKey)
    purgeReactionTracking(fbKey)
    // Defense-in-depth: the fallback's purgeReactionTracking above
    // clears the canonical statusKey(chatId, threadId) for fbKey
    // only. activeTurnStartedAt can hold sibling entries for the
    // SAME chat (different threads, or a `null` vs `undefined`-thread
    // variant left over from a normal turn-end path that nulled
    // currentTurn without invoking purgeReactionTracking — the
    // gymbro/klanker held-mid-turn symptom, 2026-05-20); sweep them via
    // the same purger. Multi-chat-safe — only touches keys for fbChatId, so
    // #1546's intentional cross-chat safety guard is preserved.
    //
    // BUT a sibling is NOT "by definition stale": in one-agent-owns-supergroup
    // every forum topic shares fbChatId, so a chatId-only sweep would purge a
    // LIVE sibling topic's reaction controller + typing loop when THIS topic's
    // poke fires. Gate each sibling on its OWN silence clock — purge only those
    // also silent ≥ the fallback threshold (their own poke would fire too),
    // sparing topics that are actively mid-turn. Use silence, not turn-start
    // age, so a long-but-narrating turn isn't mistaken for stale.
    // See turn-state-purge.ts.
    const fbNow = Date.now()
    const fbExtraPurge = purgeStaleTurnsForChat(
      fbChatId,
      activeTurnStartedAt.keys(),
      purgeReactionTracking,
      (siblingKey) => {
        if (siblingKey === fbKey) return true // the firing key is genuinely stale
        const sib = silencePoke.silenceMsForKey(siblingKey, fbNow)
        // No silence-poke state → dangling (turn ended, key not purged) → stale.
        return sib == null || sib >= silencePoke.DEFAULT_THRESHOLDS.fallback
      },
    )
    // PR-4e self-heal backstop: drop any per-topic `currentTurnByKey` entries
    // for fbChatId whose turn is stale-by-the-same-silence-gate the sibling
    // sweep above used — the same precedent as `purgeStaleTurnsForChat`'s
    // activeTurnStartedAt sweep, so a leaked map entry (a turn whose keyed
    // delete somehow never ran) can never outlive its chat. Gated identically:
    // the firing key is always stale; a sibling is stale iff it's silent ≥ the
    // fallback threshold (or has no silence state). No-op under the flag OFF
    // (the map is empty).
    currentTurnMap.purgeChatStale(fbChatId, (siblingKey) => {
      if (siblingKey === fbKey) return true
      const sib = silencePoke.silenceMsForKey(siblingKey, fbNow)
      return sib == null || sib >= silencePoke.DEFAULT_THRESHOLDS.fallback
    })
    // Null `currentTurn` if it's still pointing at the wedged turn —
    // when claude eventually fires a late `turn_end` for this session
    // (or never does), the handler's `const turn = currentTurn` snapshot
    // returns null and the regular teardown short-circuits. Without
    // this, the late event would re-emit `turn_ended` AND clobber
    // whatever fresh turn the next inbound started.
    // PR-4e — keyed liveness for the guard. Flag-OFF: `turnLiveForItsTopic`
    // reduces to `currentTurn === wedgedTurn` (singleton mirror), verbatim.
    // Flag-ON: `byKey.get(fbKey) === wedgedTurn`, so the keyed delete still
    // fires when the LIVE mirror has already flipped to another topic B (a bare
    // `currentTurn === wedgedTurn` would falsely skip and leak A's byKey entry).
    if (turnMatchesFallback && wedgedTurn != null && turnLiveForItsTopic(wedgedTurn)) {
      // Status-surface observability: emit the lifecycle CLEAR for the
      // silence-poke teardown so a fallback-nulled turn has a turn-lifecycle
      // line like every other clear path (the framework-fallback line below is
      // its own format — this makes the dark-out greppable in the same shape).
      process.stderr.write(
        `telegram gateway: ${formatTurnLifecycle('clear', 'silence_fallback', wedgedTurn, Date.now())}\n`,
      )
      // PR-4e — keyed delete for the wedged turn's OWN key (fbKey == the
      // statusKey this fallback fired for, == the wedgedTurn's key since
      // turnMatchesFallback gated chat+thread equality). Flag-OFF nulls the
      // singleton, verbatim; flag-ON deletes only this topic's entry and clears
      // the mirror iff it still points here — a live sibling topic is untouched.
      endCurrentTurnForKey(wedgedTurn, fbKey)
    }
    // Best-effort: clear any pending silent-end marker so the Stop hook
    // doesn't double-block when claude eventually exits the wedged turn.
    try {
      clearSilentEndState(fbKey)
    } catch { /* best-effort */ }
    // Self-heal the inbound buffer. pendingInboundBuffer otherwise
    // drains ONLY on bridge re-register (onClientRegistered). After a
    // network storm that settles with the bridge STILL connected, user
    // messages buffered during the flap sit forever — until a manual
    // restart forces a re-register (the fleet-update thundering-herd
    // incident, 2026-05-19: agents "not responding", logs show
    // pending-inbound-buffer depth>0 with no drain). Flushing on
    // wedge-clear makes the agent self-heal. selfAgent-keyed; a miss
    // re-buffers so nothing is lost if the bridge is genuinely offline.
    const fbSelfAgent = process.env.SWITCHROOM_AGENT_NAME ?? ''
    const fbRedeliver = redeliverBufferedInbound(
      pendingInboundBuffer,
      fbSelfAgent,
      (m) => {
        const d = ipcServer.sendToAgent(fbSelfAgent, m)
        if (d) markClaudeBusyForInbound(m)
        return d
      },
      inboundSpool,
      trackRedeliveredInbound,
    )
    process.stderr.write(
      `telegram gateway: silence-poke framework-fallback ended wedged turn ` +
      `chat=${fbChatId} thread=${ctx.threadId ?? '-'} silence_ms=${ctx.silenceMs} ` +
      `currentTurn_nulled=${turnMatchesFallback} ` +
      `drained_buffered=${fbRedeliver.redelivered}/${fbRedeliver.drained}` +
      `${fbRedeliver.rebuffered > 0 ? ` rebuffered=${fbRedeliver.rebuffered}` : ''}` +
      `${fbExtraPurge.purged.length > 0 ? ` extra_keys_purged=${fbExtraPurge.purged.length}` : ''}\n`,
    )
  },
})

// PR3b-cutover: drive the delivery machine's TTL `tick`. The machine
// expires any turn whose `turnStartedAt` is older than TURN_TTL_MS
// (5 min) and drops global state back to idle — its structural
// equivalent of the imperative silence-poke framework-fallback. This
// is the load-bearing safety net for the cutover gate: even if a
// `turnEnd` event is somehow missed (the dangle class), the machine
// self-heals at TTL instead of pinning the gate "in-flight forever".
// shadowEmit only advances state + logs the predicted effects; we
// deliberately do NOT execute the machine's firePoke here (the
// imperative silence-poke still owns the user-facing ping), so there
// is no double-poke. unref so the interval never holds the process.
const DELIVERY_MACHINE_TICK_MS = 30_000
const _deliveryMachineTick = setInterval(() => {
  shadowEmit({ kind: 'tick', now: Date.now() })
}, DELIVERY_MACHINE_TICK_MS)
_deliveryMachineTick.unref?.()

// Enrol a buffer-redelivered inbound in the deliver-until-acked queue so the
// existing sweep re-delivers it until claude's `enqueue` ack lands. Wired into
// EVERY redelivery path (bridgeUp drain, silence-poke fallback, flap/reply-gate
// flushes) — `send` returning true only means the bytes reached the bridge, NOT
// that claude consumed them. Right after a restart (esp. a slow MCP boot) the
// inject can hit a not-ready session and be silently dropped, and nothing
// retried it: the clerk 2026-06-03 lost-message incident. Mirrors the
// live-delivery tracking at the handleInbound site (chatKey + messageId), so
// DMs and supergroup forum topics are handled identically. Only real user
// inbounds are tracked — shouldTrackDelivery excludes steer/interrupt/
// synthetic-source/empty, which never produce an `enqueue` and would otherwise
// re-deliver forever.
function trackRedeliveredInbound(merged: InboundMessage): void {
  if (!DELIVERY_CONFIRM_ENABLED) return
  // The boot-resume synthetic ('resume_interrupted') is the ONE synthetic we DO
  // enrol: a restart can drop it into a not-ready session exactly like a user
  // inbound, leaving the interrupted work silently un-resumed. Safe iff it
  // carries the chat_id + message_id that make its enqueue ack-able — see
  // isTrackableResumeSynthetic. Every other synthetic stays excluded below.
  const isTrackableResume = isTrackableResumeSynthetic(merged.meta)
  if (
    !isTrackableResume &&
    !shouldTrackDelivery({
      isSteering: false,
      isInterrupt: false,
      hasSource: merged.meta?.source != null,
      effectiveText: merged.text,
    })
  ) {
    return
  }
  const key = chatKey(merged.chatId, merged.threadId != null ? Number(merged.threadId) : null)
  trackDelivery(
    deliveryQueue,
    key,
    merged,
    Date.now(),
    merged.messageId != null ? String(merged.messageId) : null,
  )
}

// Re-deliver stranded inbounds until claude acks (the marko drop-wedge).
// Every few seconds, re-send any inbound that was handed to claude but never
// acked by an `enqueue` — it stranded unsubmitted in the composer. Re-clear
// the composer so the re-sent notification lands on a clean line, then
// re-send. Reuses the same delivery primitives; the message is never dropped.
// (Refs ipcServer / pendingInboundBuffer declared below — resolved at fire
// time, after module init.) unref so the interval never holds the process.
async function redeliverStrandedInbound(p: PendingDelivery<InboundMessage>): Promise<void> {
  const selfAgent = process.env.SWITCHROOM_AGENT_NAME ?? ''
  process.stderr.write(
    `telegram gateway: inbound strand (no enqueue ack) key=${p.key} — re-clearing composer + re-delivering\n`,
  )
  try {
    const { clearAgentComposer } = await import('../../src/agents/tmux.js')
    if (selfAgent) clearAgentComposer({ agentName: selfAgent })
  } catch { /* best-effort; re-deliver regardless */ }
  const ok = ipcServer.sendToAgent(selfAgent, p.inbound)
  if (ok) {
    // Keep the #1556 gate coherent with the re-sent delivery, and survive an
    // ack that raced the `await import` above: only `enqueue` clears tracking,
    // so if a concurrent ack removed the entry, re-affirm it — never drop.
    // Both ops are idempotent.
    markClaudeBusyForInbound(p.inbound)
    if (!deliveryQueue.pending.has(p.key)) {
      trackDelivery(deliveryQueue, p.key, p.inbound, Date.now(), p.messageId)
    }
  } else {
    // Bridge offline between attempts — hand off to the offline buffer
    // (bridgeUp drains it) and stop tracking here; the spool owns it now.
    pendingInboundBuffer.push(selfAgent, p.inbound)
    forgetDelivery(deliveryQueue, p.key)
  }
}
const _deliveryConfirmSweep = setInterval(() => {
  if (!DELIVERY_CONFIRM_ENABLED) return
  // Re-deliver ONLY when claude is genuinely idle. `currentTurn` is set solely
  // by the enqueue session-event and nulled at turn-end, so `currentTurn != null`
  // means a real turn is in flight — re-clearing the composer + re-sending now
  // would clobber it (the exact mid-turn wedge this queue exists to prevent). A
  // pending permission / ask_user prompt is likewise a live interaction. Defer:
  // leave the entry pending (it isn't acked) so the next idle sweep retries.
  // NB: claudeBusyKeys (turnInFlightForGate) is set EAGERLY at delivery and
  // stays set through a strand, so it is NOT a usable "idle" signal here.
  if (currentTurn != null) return
  if (pendingPermissions.size > 0 || pendingAskUser.size > 0) return
  for (const p of sweepDeliveryQueue(deliveryQueue, Date.now(), DELIVERY_CONFIRM_TIMEOUT_MS)) {
    void redeliverStrandedInbound(p)
  }
}, DELIVERY_CONFIRM_SWEEP_MS)
_deliveryConfirmSweep.unref?.()

// #1445 cross-turn pending-async ambient. When a turn ends after the
// model dispatched background async work (Agent / Task / Bash run-in-
// background) and the model has stopped speaking, keep editing the
// model's last reply in place at 60s intervals so the user sees
// ambient liveness during the wait. Edits are silent, never spawn a
// new pinged message, and stop the moment the user re-engages or the
// model synthesises a handback. The full design rationale lives in
// `pending-work-progress.ts`'s header docblock. Kill switch:
// `SWITCHROOM_DISABLE_PENDING_PROGRESS=1`.
pendingProgress.startTimer({
  editMessage: async (ctx) => {
    // #2669: re-edit via the SAME shape the anchor was sent with. A rich
    // anchor (the reply tool's default) re-edits via the rich-markdown
    // path so the body keeps rendering its markdown; a literal
    // `format:'text'` anchor re-edits as a plain string. This is the
    // single-rich-path successor to the #1698 parse-mode contract.
    await swallowingApiCall(
      () =>
        lockedBot.api.editMessageText(
          ctx.chatId,
          ctx.messageId,
          ctx.literalText ? ctx.newText : richMessage(ctx.newText),
          undefined,
        ),
      {
        chat_id: ctx.chatId,
        verb: 'pending-progress-edit',
        ...(ctx.threadId != null ? { threadId: ctx.threadId } : {}),
      },
    )
  },
  emitMetric: (event) => emitRuntimeMetric(event),
  // #1760 defense-in-depth: if a newer turn for this chat is active at
  // tick time, the prior turn's pending-progress is stale (the
  // canonical teardown was missed). Drop the ticker instead of editing
  // the old anchor — see pending-work-progress.ts's docblock.
  isActiveTurnNewerThan: (key, activatedAt) => {
    const turnStartedAt = activeTurnStartedAt.get(key)
    return turnStartedAt != null && turnStartedAt > activatedAt
  },
})

// Per-agent buffer for synthetic inbounds the gateway couldn't deliver
// because the bridge wasn't connected at send-time. Drained on
// bridge-register so a fresh client picks up missed wake-ups before
// any other work happens. See #1150 — pre-buffer, an Approve tap on a
// vault_request_access card during the 100ms bridge-reconnect window
// would mint the grant but silently drop the `vault_grant_approved`
// inbound, leaving the agent stuck waiting for a manual poke.
// Durable inbound spool on the persistent per-agent volume
// (STATE_DIR = /state/agent/telegram in prod — survives container
// recreate). Makes the "⏳ your message is queued and will be
// processed when it reconnects" promise deterministic across a
// gateway/container restart (finn/carrie lost-on-restart incident,
// 2026-05-19). STATIC mode has no runtime/bridge, so no spool.
const inboundSpool = STATIC
  ? undefined
  : createInboundSpool({
      path: join(STATE_DIR, 'inbound-spool.jsonl'),
      fs: {
        appendFileSync: (p, d) => appendFileSync(p, d),
        readFileSync: (p) => readFileSync(p, 'utf8'),
        writeFileSync: (p, d) => writeFileSync(p, d),
        renameSync: (a, b) => renameSync(a, b),
        existsSync: (p) => existsSync(p),
        statSizeSync: (p) => statSync(p).size,
      },
    })
const pendingInboundBuffer = createPendingInboundBuffer({ spool: inboundSpool })

// PR2 obligation-ledger idle sweep. Re-present an OPEN obligation only at a
// CLEAN idle: no turn in flight AND the inbound buffer is empty — so the
// existing buffer-drain has already had its turn and anything still OPEN is
// "delivered but never answered" (the 715 gap). Re-present by pushing a
// synthetic must-answer inbound through the SAME buffer→drain path (idempotent
// OPEN via meta.source; reuses tested delivery). Bounded: after maxRepresents,
// escalate to ONE operator-visible "did I miss this?" and close — no loop.
// No-op unless the flag is on; gated on the same idle predicate as the drains.
// DETERMINISM (closed-form, not sampled). The obligation ledger itself
// (obligation-ledger.ts) is a finite FSM with a total transition function and a
// strictly-decreasing measure μ = (REPRESENT_MAX - representCount) +
// (ESCALATE_MAX - escalateAttempts): every markRepresented/markEscalateAttempt
// decreases μ, both terms are bounded below, and at the floor the only move is
// close → terminal. So on the FSM, every OPEN reaches answered | escalation-
// delivered | bounded give-up (no cycle re-increments a counter). This sweep is
// the FSM's driver; its termination rests on three liveness facts, all bounded:
//   (1) the 5s setInterval keeps firing;
//   (2) the gate (turnInFlightForGate) opens — claudeBusyKeys is cleared at
//       turn-end (purgeReactionTracking / releaseTurnBufferGate), on bridge
//       disconnect (disconnect-flush.ts), and by the 300s silence-poke watchdog;
//   (3) the escalation send settles — bounded BY CONSTRUCTION via withDeadline
//       below (grammy has no request timeout, so an unbounded send was the one
//       way an obligation could get stuck OPEN forever — now closed);
//   (4) the background-work grace releases — an obligation skipped because
//       agentHasInFlightBackgroundWork() is true is bounded by
//       OBLIGATION_BACKGROUND_WORK_GRACE_MS (a hard wall-clock ceiling from
//       openedAt). Even a permanently-stuck/leaked worker signal cannot suppress
//       the act past the ceiling, so this adds NO unbounded liveness dependency:
//       decideAtIdle ignores the work signal once now ≥ openedAt + ceiling, μ
//       resumes decreasing, and termination still holds.
// The only residual liveness assumption is the bridge eventually reconnecting /
// the process restarting, which the entire gateway's inbound delivery already
// depends on and which durable spool + boot-replay make self-healing.
// True when the agent has in-flight autonomous sub-agent work the turn-in-flight
// gate does NOT see: a running background worker (countRunningWorkers — its row
// is INSERTed status='running' at dispatch, before the parent turn ends), OR an
// orphaned/extended-autonomous FOREGROUND sub-agent that outlived its turn and is
// still touching the turn-active marker (#2240; background activity deliberately
// does NOT touch the parent marker, so the two signals are complementary).
// Used ONLY by the obligation sweep to bound a false escalation during genuine
// post-turn work. The caller already established the turn machine is idle (the
// `turnInFlightForGate()` early-return), so a fresh marker here means orphaned
// sub-agent activity (or a just-ended turn within the freshness window — a
// harmless small extra grace, bounded by the ceiling either way).
function agentHasInFlightBackgroundWork(now: number): boolean {
  if (countRunningWorkers() > 0) return true
  const ageMs = readTurnActiveMarkerAgeMs(STATE_DIR, now)
  return ageMs != null && ageMs < TURN_ACTIVE_MARKER_FRESH_MS
}
// Throttle for the background-work defer diagnostic (the 5s sweep would otherwise
// log every tick across a multi-minute research window).
let lastBgWorkDeferLogMs = 0
function obligationSweep(): void {
  if (!OBLIGATION_LEDGER_ENABLED) return
  if (!obligationLedger.hasOpen()) return
  if (turnInFlightForGate()) return // a turn is running — let it finish/answer
  const agent = process.env.SWITCHROOM_AGENT_NAME ?? ''
  const now = Date.now()
  // Background-work grace: while genuine autonomous sub-agent work is in flight
  // (a running worker, or an orphaned foreground sub-agent — neither visible to
  // the turn machine), an obligation younger than the ceiling is NOT re-presented
  // /escalated. Bounded by OBLIGATION_BACKGROUND_WORK_GRACE_MS so escalation
  // always eventually fires. =0 disables it.
  const backgroundWorkActive =
    OBLIGATION_BACKGROUND_WORK_GRACE_MS > 0 && agentHasInFlightBackgroundWork(now)
  // Grace window: skip an obligation whose handling turn ended < grace ago — its
  // trailing slow/worker answer may still be landing (over-escalation fix).
  // Per-represent grace: skip an obligation re-presented < grace ago — prevents
  // the 5s sweep from immediately firing again before the re-present even lands.
  const decision = obligationLedger.decideAtIdle(
    OBLIGATION_ESCALATE_GRACE_MS > 0 || backgroundWorkActive || OBLIGATION_REPRESENT_GRACE_MS > 0
      ? {
          now,
          graceMs: OBLIGATION_ESCALATE_GRACE_MS,
          backgroundWorkActive,
          backgroundGraceMs: OBLIGATION_BACKGROUND_WORK_GRACE_MS,
          representGraceMs: OBLIGATION_REPRESENT_GRACE_MS,
        }
      : undefined,
  )
  const o = decision.obligation
  if (decision.action === 'none' || o == null) {
    if (backgroundWorkActive && obligationLedger.hasOpen() && now - lastBgWorkDeferLogMs > 60_000) {
      lastBgWorkDeferLogMs = now
      process.stderr.write(
        `telegram gateway: obligation sweep deferred — in-flight autonomous sub-agent work ` +
          `(${obligationLedger.size()} open, bounded ${Math.round(OBLIGATION_BACKGROUND_WORK_GRACE_MS / 60_000)}m from receipt)\n`,
      )
    }
    return
  }
  if (decision.action === 'represent') {
    // Fix #2472 — duplicate-represent guard. Before re-presenting AGAIN, check
    // whether the agent has ALREADY delivered a substantive outbound reply to
    // this chat SINCE the obligation was most recently re-presented. If so the
    // obligation is satisfied-but-misdetected (the reply landed but its routing
    // didn't resolve back to this origin, so the normal close path missed it) —
    // close silently and do NOT re-fire, which is what produced the near-identical
    // duplicate in #2472 (reply 10608 answered represent_count=1, yet
    // represent_count=2 fired anyway → duplicate 10609).
    //
    // The cutoff is `lastRepresentedAt` (the time of the PREVIOUS represent), NOT
    // `openedAt`. This is load-bearing: the genuine "agent wrote a plain-text
    // answer and never called reply" case must still represent ONCE. On the first
    // represent `lastRepresentedAt` is undefined, so this guard is a no-op and the
    // single represent fires as before. Only the SECOND-and-later represent is
    // gated — exactly where a reply that landed between fires must suppress the
    // re-ask. Falls back to false (never suppresses) if history is unavailable.
    if (
      shouldSuppressRepresent(o, {
        historyEnabled: HISTORY_ENABLED,
        // Pass the represent-guard's OWN low threshold — a terse-but-real reply
        // must suppress the duplicate (#2472/#2474), unlike the escalate branch
        // below which keeps the 200-char default.
        hasOutboundDeliveredSince: (chatId, sinceMs, threadId) =>
          hasOutboundDeliveredSince(
            chatId,
            sinceMs,
            threadId,
            OBLIGATION_REPRESENT_GUARD_MIN_REPLY_CHARS,
          ),
      })
    ) {
      process.stderr.write(
        `telegram gateway: obligation closed silently — reply delivered since last represent (no re-fire) origin=${o.originTurnId}\n`,
      )
      obligationLedger.close(o.originTurnId)
      return
    }
    // Re-present goes through the bridge → buffer. Only the represent path is
    // gated on an empty buffer (let the existing drain run first, avoid
    // double-presenting). Escalation below is NOT gated on the buffer — it is a
    // direct Telegram send, independent of the bridge, so a represent stranded
    // behind a dead bridge can never block the operator nudge.
    if (pendingInboundBuffer.depth(agent) > 0) return
    pendingInboundBuffer.push(agent, buildObligationRepresentInbound(o, Date.now()))
    // PR1 (cross-turn stale-card guard, §9 lever 4 / race C/D). Arm the
    // card-OPEN gate for the synthetic turn this represent inbound will spawn:
    // carry the obligation's `openedAt` so that turn's first card-OPEN can ask
    // "was a substantive answer already delivered since the obligation was
    // raised?" and, if so, suppress the card (it would otherwise narrate beneath
    // the answer the user already received). Keyed on the obligation's
    // `originTurnId` — the SAME id the represent inbound carries
    // (`buildObligationRepresentInbound` reuses `o.messageId`/`o.chatId`/
    // `o.threadId`, so the enqueue-time `deriveTurnId` reconstructs exactly
    // `o.originTurnId`). Keying on the turn id (not chat/thread) means ONLY the
    // exact represent turn this gate was armed for can consume it; an unrelated
    // later foreground turn on the same chat/thread has a different originTurnId
    // → finds no entry → its card opens normally. This closes the residual
    // cross-contamination window where a never-enqueued represent's stale gate
    // could suppress an unrelated turn's card (the represent/duplicate-reply
    // family). This does NOT gate the represent SEND — the represent guard above
    // already owns suppressing an already-satisfied represent; this only governs
    // the decorative card.
    pendingCrossTurnGate.set(o.originTurnId, { sinceMs: o.openedAt })
    const attempt = obligationLedger.markRepresented(o.originTurnId)
    process.stderr.write(
      `telegram gateway: obligation re-presented origin=${o.originTurnId} attempt=${attempt}/${OBLIGATION_REPRESENT_MAX}\n`,
    )
    return
  }
  // escalate — re-present ladder exhausted. Before sending the user-visible
  // apology, check whether the agent has ALREADY delivered an outbound reply
  // to this chat since the obligation was opened. If yes, the obligation is
  // stale (the agent did answer, just without closing the obligation via the
  // normal close path) — close silently instead of alarming the user with a
  // false "I may have missed this". This is Fix 4: escalate only on knowledge,
  // not doubt. Fall back to false (safe: never suppresses) if history unavailable.
  if (HISTORY_ENABLED && hasOutboundDeliveredSince(o.chatId, o.openedAt, o.threadId)) {
    process.stderr.write(
      `telegram gateway: obligation closed silently — outbound delivered since open origin=${o.originTurnId}\n`,
    )
    obligationLedger.close(o.originTurnId)
    return
  }
  // Proceed with escalation: send ONE operator-visible nudge and close the
  // obligation ONLY AFTER it actually lands. This inverts the old
  // close-before-send (which silently dropped the terminal whenever the send
  // failed): the close is now itself an observable terminal. A transient send
  // failure leaves the obligation OPEN → retried next sweep; a PERMANENT one
  // (dead topic even after thread-fallback, blocked bot) is bounded by
  // OBLIGATION_ESCALATE_MAX → close best-effort (the user is unreachable, so a
  // bounded give-up beats an infinite loop / a boot-surviving poison record).
  // Drive one escalation attempt. The send is a direct Telegram nudge
  // (retryWithThreadFallback: a stale/renumbered topic → THREAD_NOT_FOUND retries
  // thread-less, the #2096 pattern). driveEscalation guards against concurrent
  // sends, bounds the send with withDeadline (so a hung send can't leak the
  // in-flight flag and wedge the obligation OPEN), closes only after a successful
  // send, and bounds permanent failures to a best-effort close. Extracted so the
  // hang → bounded → terminal path is executable in escalation-drive.test.ts —
  // the path neither mtcute (can't hang Telegram) nor a synchronous test reaches.
  void driveEscalation({
    escId: o.originTurnId,
    inFlight: obligationEscalateInFlight,
    ledger: obligationLedger,
    send: () =>
      retryWithThreadFallback(
        robustApiCall,
        (tid) =>
          bot.api.sendMessage(o.chatId, obligationEscalationText(o), {
            ...(tid != null ? { message_thread_id: tid } : {}),
          }),
        { threadId: o.threadId, chat_id: o.chatId, verb: 'obligation.escalate' },
      ),
    maxAttempts: OBLIGATION_ESCALATE_MAX,
    deadlineMs: OBLIGATION_ESCALATE_SEND_DEADLINE_MS,
  })
}
if (!STATIC && OBLIGATION_LEDGER_ENABLED) {
  setInterval(obligationSweep, OBLIGATION_SWEEP_MS).unref()
}

// Honest-restart-resume: inject the boot resume/report inbound built by the
// registry classifier above. When the spool exists we only PUT it (the
// boot-replay loop below pulls it into the in-memory buffer exactly once via
// liveEntries — pushing here too would double-queue). The turn_key-keyed
// spoolId makes this a no-op if a prior restart already queued the same turn
// and it hasn't been delivered yet — so a multi-restart sequence resumes a
// given turn once, not N times. When there's no spool (STATIC mode) push
// straight to the in-memory buffer.
if (bootResumeInbound != null) {
  if (inboundSpool != null) {
    inboundSpool.put(bootResumeInbound.agent, bootResumeInbound.msg)
  } else {
    pendingInboundBuffer.push(bootResumeInbound.agent, bootResumeInbound.msg)
  }
}
// Boot-replay: re-queue every un-acked spooled inbound into the
// in-memory buffer so the existing drain triggers (onClientRegistered
// / silence-poke #1546 / idle-drain #1549) deliver them. push →
// spool.put dedups on the already-live id, so this re-push does NOT
// double-append. This is what makes a queued message survive a
// restart instead of being silently lost.
if (inboundSpool != null) {
  const replay = inboundSpool.liveEntries()
  for (const e of replay) pendingInboundBuffer.push(e.agent, e.msg)
  if (replay.length > 0) {
    process.stderr.write(
      `telegram gateway: inbound-spool boot-replay re-queued ${replay.length} ` +
      `un-acked inbound (durable-queue, survives restart)\n`,
    )
  }
}
const pendingPermissionBuffer = createPendingPermissionBuffer()

/**
 * Deliver a permission verdict to this agent's bridge, buffering on a
 * miss so it's redelivered when the bridge reconnects. Replaces the
 * bare `ipcServer.broadcast({type:'permission',...})` at every verdict
 * site (and the TTL-sweep auto-deny). broadcast was fire-and-forget:
 * a verdict produced while the bridge was mid-reconnect was dropped
 * and the claude turn stayed suspended INSIDE the MCP permission call
 * forever — the user tapped Approve/Deny and nothing happened, no
 * further output, permanent silence. sendToAgent is registered-keyed
 * and returns a real delivered bool; on a miss we buffer and
 * onClientRegistered re-sends so the reconnecting bridge relays the
 * verdict to the still-suspended call. A late verdict for a dead
 * request_id is harmless — the bridge relays it and Claude Code
 * ignores an unknown request_id. (Function declaration so the
 * pre-2747 TTL sweep can reference it; ipcServer/pendingPermissionBuffer
 * are resolved at call-time, after module init.)
 */
/**
 * The default permission-card action row: ❌ Deny · ✅ Allow ·
 * 🔁 Always… (the last only when a meaningful always-rule exists).
 * Tapping "🔁 Always…" swaps this row for the scope sub-menu; "← Back"
 * rebuilds this row. callback_data stays tiny (verb + 5-char id) so we
 * never approach Telegram's 64-byte ceiling.
 *
 * "✅ Allow" is no longer always literally "once": for a NARROW,
 * non-destructive scope it auto-grants a fixed 30-min window (so the same
 * action stops re-asking) — that is the default behavior of the allow tap,
 * not a separate button. Broad / MCP / destructive scopes stay truly once.
 * The post-tap card states which happened (honest-card contract). The
 * decision lives in the allow handler via resolveTimeBox; the label here is
 * deliberately neutral ("Allow", not "Allow once" or "Allow 30 min").
 */
function buildPermissionActionRow(
  requestId: string,
  showAlways: boolean,
): InlineKeyboard {
  const kb = new InlineKeyboard()
    .text('❌ Deny', `perm:deny:${requestId}`)
    .text('✅ Allow', `perm:allow:${requestId}`)
  if (showAlways) kb.text('🔁 Always…', `perm:always:${requestId}`)
  return kb
}

/**
 * Strip the inline keyboard from one or more timed-out permission cards and
 * append a "timed out — re-request to act" line (Bug 2 fix #1). Called from
 * the pendingStateReaper, which has no grammy `ctx`, so it edits via the
 * bot.api directly — routed through `swallowingApiCall` so a deleted card
 * (operator removed the message) is swallowed rather than crashing the sweep.
 *
 * A single `editMessageText` re-renders the original card body plus a
 * timed-out footer; omitting `reply_markup` drops the keyboard atomically
 * with the text edit (same approach the normal tap finalizer uses, which
 * strips the keyboard alongside its status-line edit). Best-effort: a failed
 * edit never blocks the auto-deny that already fired.
 */
async function stripTimedOutPermissionCards(
  cardText: string,
  cards: PermissionCardRef[],
): Promise<void> {
  for (const edit of buildTimedOutCardEdits(cardText, cards)) {
    await swallowingApiCall(
      // allow-raw-bot-api: routed through swallowingApiCall (retry policy); message-id-targeted edit (no thread to lose). Passing {} as opts (no reply_markup) strips the stale Allow/Deny keyboard atomically with the text edit.
      () => bot.api.editMessageText(edit.chatId, edit.messageId, richMessage(edit.text), {}),
      { chat_id: edit.chatId, verb: 'permission_timeout.strip' },
    )
  }
}

function dispatchPermissionVerdict(ev: PermissionEvent): void {
  const selfAgent = process.env.SWITCHROOM_AGENT_NAME ?? ''
  const delivered = ipcServer.sendToAgent(selfAgent, ev)
  if (!delivered) {
    pendingPermissionBuffer.push(selfAgent, ev)
    process.stderr.write(
      `telegram gateway: permission verdict buffered (bridge offline) ` +
      `request=${ev.requestId} behavior=${ev.behavior}\n`,
    )
  }
}

const ipcServer: IpcServer = createIpcServer({
  socketPath: SOCKET_PATH,

  onClientRegistered(client: IpcClient) {
    process.stderr.write(`telegram gateway: bridge registered — agent=${client.agentName}\n`)
    // Cheap-cron (§2.4/§3.3): a `<agent>-cron` bridge is the Tier-1 cheap
    // session. It is STATUS-SILENT — it must NOT drive the gateway's
    // singleton machinery (shadow bridge-state, warmup, boot card, which all
    // track the MAIN agent's liveness). Drain any buffered cron fire to it
    // (so a fire that triggered a lazy spawn lands), then return early.
    if (isCronIdentity(client.agentName)) {
      client.send({ type: 'status', status: 'agent_connected' })
      const pending = pendingInboundBuffer.drain(client.agentName ?? '')
      for (const m of pending) {
        try { client.send(m) } catch { /* cron fire drop — best-effort, like today's cron */ }
      }
      return
    }
    // Phase 2b shadow: ONLY emit bridgeUp for the REAL bridge sidecar
    // (with an agent name). Anonymous IPC clients (recall.py, mcp
    // handshakes, etc.) connect briefly without a name and would
    // false-positive a bridgeUp/bridgeDown cycle that doesn't reflect
    // the real bridge state. This bug — discovered post-v0.12.24 — was
    // causing the shadow state to read `bridge_dead` even when the
    // real bridge was healthy, because every recall.py connect+disconnect
    // would flip the state.
    const bridgeUpEffects = client.agentName != null
      ? shadowEmit({ kind: 'bridgeUp', at: Date.now() })
      : []
    client.send({ type: 'status', status: 'agent_connected' })

    // Phase 2b PR 3a — bridgeUp cutover. The state machine's `bridgeUp`
    // transition returns `redeliverPersistedPermVerdicts`, `drainBuffer`,
    // and `logTrace` effects. The dispatcher executes them in order:
    // the perm-verdict drain unblocks any claude turn suspended inside
    // an MCP permission call; the inbound drain flushes synthetic
    // inbounds queued while the bridge was offline (#1150) so the agent
    // wakes up to missed wake-ups before the boot-card path below runs.
    // Lossless: `redeliverBufferedInbound` re-buffers per-message misses
    // and `spool.ack` tombstones confirmed deliveries. Skipped when
    // agentName is null (pre-handshake / anonymous client — those
    // bridges never registered an identity and can't have accumulated
    // buffered inbounds keyed by name).
    if (client.agentName != null) {
      if (isDispatchEnabled()) {
        dispatchEffects(bridgeUpEffects, {
          selfAgent: client.agentName,
          ipcServer,
          pendingInboundBuffer,
          inboundSpool: inboundSpool ?? null,
          pendingPermissionBuffer,
          client,
          // Enrol each drained user inbound in the deliver-until-acked queue
          // so the 5s sweep re-delivers until claude's `enqueue` ack lands —
          // a socket-write into a still-booting session is NOT consumption
          // (clerk lost-message incident, 2026-06-03).
          onUserInboundDelivered: trackRedeliveredInbound,
        })
      } else {
        // Kill-switch fallback: imperative drain (parity with pre-cutover
        // behavior). Kept for SWITCHROOM_DELIVERY_MACHINE_CUTOVER=0
        // rollback safety; deleted in PR 4 once the cutover bakes.
        const pending = pendingInboundBuffer.drain(client.agentName)
        for (const msg of pending) {
          try {
            client.send(msg)
            inboundSpool?.ack(msg)
            // Same enrol as the cutover drain path: a socket-write success is
            // not proof claude consumed it — enrol so the sweep re-delivers
            // until `enqueue` (clerk lost-message incident, 2026-06-03).
            trackRedeliveredInbound(msg)
          } catch (err) {
            process.stderr.write(
              `telegram gateway: pending-inbound drain failed agent=${client.agentName} ` +
              `source=${msg.meta?.source ?? '-'}: ${(err as Error).message}\n`,
            )
          }
        }
        const pendingVerdicts = pendingPermissionBuffer.drain(client.agentName)
        for (const ev of pendingVerdicts) {
          try {
            client.send(ev)
          } catch (err) {
            process.stderr.write(
              `telegram gateway: pending-permission drain failed agent=${client.agentName} ` +
              `request=${ev.requestId} behavior=${ev.behavior}: ${(err as Error).message}\n`,
            )
          }
        }
      }
    }

    // Prefix-cache warmup (cold-start TTFO RFC, opt-in via
    // SWITCHROOM_PREFIX_WARMUP=1). Fires a synthetic inbound to claude
    // BEFORE the user's next real message so Anthropic's prefix cache
    // is warm on the user-perceived first turn. Gated, debounced
    // (5-min cooldown per agent), and skipped if no boot chat resolves.
    // Claude responds NO_REPLY per inline instruction; existing
    // silent-marker suppression at gateway.ts:5906 swallows the
    // outbound. See reference/rfcs/cold-start-ttfo.md Option A.
    if (client.agentName != null) {
      maybeFireWarmup({
        selfAgent: client.agentName,
        client,
        resolveBootTarget: () => {
          const marker = readRestartMarker()
          const ageMs = marker ? Date.now() - marker.ts : undefined
          const target = resolveBootChatId(marker, ageMs)
          if (!target) return null
          return { chatId: target.chatId, threadId: target.threadId }
        },
      })
    }

    // If the agent reconnected after a /restart (or any restart), post a boot
    // card. The restart-marker carries the ack chat; if absent we fall back to
    // resolveBootChatId so crash-recovery reconnects also get a card.
    //
    // Skip if the boot path already posted a card OR is currently in-flight
    // on its sendMessage await (issue #489 — klanker msgId 4715+4716,
    // 2026-05-01). The original dedupe (msgId 2245+2248, 2026-04-26) only
    // covered the post-resolution case; bootCardPending closes the in-flight
    // race window. See `shouldSkipDuplicateBootCard`.
    const dedupeDecision = shouldSkipDuplicateBootCard({ activeBootCard, bootCardPending }, 'bridge-reconnect')
    if (dedupeDecision.skip) {
      process.stderr.write(`telegram gateway: bridge-reconnect: skipping boot card (${dedupeDecision.reason})\n`)
    } else {
      const nowMs = Date.now()
      const marker = readRestartMarker()
      const cleanMarker = readCleanShutdownMarker(GATEWAY_CLEAN_SHUTDOWN_MARKER_PATH)
      const storedSession = readSessionMarker(GATEWAY_SESSION_MARKER_PATH)
      const markerAgeMs = marker ? nowMs - marker.ts : undefined

      if (marker) {
        const ageSec = Math.max(1, Math.round((markerAgeMs ?? 0) / 1000))
        process.stderr.write(`telegram gateway: bridge-reconnect: restart-marker present, chat_id=${marker.chat_id} age=${ageSec}s agent=${client.agentName}\n`)
        clearRestartMarker()
      }

      const reason = determineRestartReason({ marker, cleanMarker, sessionMarker: storedSession, now: nowMs })
      const target = resolveBootChatId(marker, markerAgeMs)

      if (target) {
        const { chatId, threadId, ackMsgId } = target
        process.stderr.write(`telegram gateway: bridge-reconnect: posting boot card reason=${reason} chat_id=${chatId} thread_id=${threadId ?? '-'} ackReply=${ackMsgId ?? '-'} boot_card=${BOOT_CARD_ENABLED}\n`)
        ensureIssuesCard(chatId, threadId)
        if (BOOT_CARD_ENABLED) {
          const agentDir = resolveAgentDirFromEnv()
          const agentSlug = process.env.SWITCHROOM_AGENT_NAME ?? client.agentName ?? '-'
          const agentDisplayName = resolvePersonaName(agentSlug)
          const botApiForCard: import('./boot-card.js').BotApiForBootCard = wrapBootCardApi(threadId)
          // Symmetric to the boot path: claim ownership synchronously so a
          // second bridge-reconnect in the same lifetime can't race against
          // an in-flight sendMessage here either (#489).
          bootCardPending = true
          // PR C: surface the most recent terminal update_apply audit
          // row if it lands within the lookback window AND no other
          // boot has claimed it. Cheap (one file read + one O_EXCL).
          const updateOutcomeLine = (() => {
            try { return maybeRenderUpdateAnnouncement() ?? undefined } catch { return undefined }
          })()
          const resolvedAgentDirForCard = agentDir ?? (process.env.TELEGRAM_STATE_DIR ? require('path').dirname(process.env.TELEGRAM_STATE_DIR) : '/tmp')
          startBootCard(chatId, threadId, botApiForCard, {
            agentName: agentDisplayName,
            agentSlug,
            version: formatBootVersion(),
            agentDir: resolvedAgentDirForCard,
            gatewayInfo: { pid: process.pid, startedAtMs: GATEWAY_STARTED_AT_MS },
            restartReason: reason,
            restartAgeMs: markerAgeMs,
            restartReasonDetail: cleanMarker?.reason,
            loadAccounts: () => loadAccountsForBootCard(agentSlug),
            probeQuotaViaBroker: (t) => probeQuotaForBootCard(agentSlug, t),
            tmuxSupervisor: process.env.SWITCHROOM_TMUX_SUPERVISOR === '1',
            dockerMode: process.env.SWITCHROOM_RUNTIME === 'docker',
            configSnapshotPath: join(resolvedAgentDirForCard, '.config-snapshot.json'),
            bootCardStatePath: join(resolvedAgentDirForCard, '.boot-card-msgid.json'),
            ...(updateOutcomeLine ? { updateOutcomeLine } : {}),
          }, ackMsgId).then(handle => {
            activeBootCard = handle
          }).catch((err: Error) => {
            process.stderr.write(`telegram gateway: bridge-reconnect: boot card error: ${err.message}\n`)
          }).finally(() => {
            bootCardPending = false
          })
        } else {
          const ageSec = markerAgeMs != null ? Math.max(1, Math.round(markerAgeMs / 1000)) : 0
          postLegacyBanner(chatId, threadId, ackMsgId, ageSec, 'bridge-reconnect')
        }
      } else {
        process.stderr.write(`telegram gateway: bridge-reconnect: no known chat for boot card (reason=${reason}) — skipping\n`)
      }
    }
  },

  onClientDisconnected(client: IpcClient) {
    // Cheap-cron §2.4: a `<agent>-cron` bridge is the status-silent cron
    // session. Its disconnect (e.g. B3 lazy idle-teardown) must NOT touch
    // the MAIN agent's singleton state — emitting bridgeDown (the shadow
    // state is unkeyed) or flushOnAgentDisconnect (flushes the main agent's
    // active reactions / disposes its progress driver mid-turn) would be the
    // "premature 👍" bug for the main session. Symmetric to the cron gate in
    // onClientRegistered / onSessionEvent / onPtyPartial.
    if (isCronIdentity(client.agentName)) {
      process.stderr.write(`telegram gateway: cron-session bridge disconnected — agent=${client.agentName}\n`)
      return
    }
    // ONLY log "bridge disconnected" + emit bridgeDown for the REAL
    // bridge sidecar (matching the bridgeUp gate above). Anonymous IPC
    // clients — e.g. recall.py's one-shot legacy update_placeholder
    // handshake — connect and disconnect constantly with agentName=null;
    // logging those as "bridge disconnected — agent=null" reads as a
    // bridge flap in the supervisor log when nothing flapped. The
    // anonymous disconnect is still traced by disconnect-flush.ts.
    if (client.agentName != null) {
      process.stderr.write(`telegram gateway: bridge disconnected — agent=${client.agentName}\n`)
      shadowEmit({ kind: 'bridgeDown', at: Date.now() })
    }

    // Scope the flush to clients that actually registered as an agent.
    // Anonymous one-shot connections (e.g. recall.py's legacy
    // update_placeholder IPC handshake) close their socket as soon as the
    // single JSON line is sent — firing this handler with agentName=null.
    // The old code unconditionally flushed every active reaction to 👍 and
    // disposed the progress driver, which fired the "premature 👍" UX bug
    // mid-turn whenever recall.py ran. See `disconnect-flush.ts` for the
    // gating policy and the test in
    // `tests/gateway-disconnect-flush.test.ts` for the contract.
    flushOnAgentDisconnect({
      agentName: client.agentName,
      activeStatusReactions,
      activeReactionMsgIds,
      activeTurnStartedAt,
      claudeBusyKeys,
      activeDraftStreams,
      clearActiveReactions: () => {
        const ad = resolveAgentDirFromEnv()
        if (ad) clearActiveReactions(ad)
      },
      disposeProgressDriver: () => {
        // dispose is optional on the ProgressDriver interface — chain
        // through both possibly-undefined hops. Caught by
        // scripts/check-plugin-references.mjs (TS2722).
        progressDriver?.dispose?.({ preservePending: true })
      },
      // When dangling activeTurnStartedAt keys were swept (setDone raced
      // disconnect), the module-scope `currentTurn` may also point at the
      // dead bridge's turn. Null it so the next inbound starts a fresh
      // turn instead of inheriting a ghost.
      onDanglingTurnsSwept: () => {
        if (currentTurn != null) {
          process.stderr.write(
            `telegram gateway: disconnect-flush nulled currentTurn (bridge died with turn in flight)\n`,
          )
          // PR-4e — the bridge DIED with a turn in flight: EVERY per-topic entry
          // is a ghost, not just the mirror's. Clear the whole map + mirror.
          // Flag-OFF: this nulls the singleton only (the map is empty), verbatim.
          clearAllCurrentTurns()
        }
      },
      log: (msg) => process.stderr.write(`${msg}\n`),
    })
  },

  async onToolCall(client: IpcClient, msg: ToolCallMessage): Promise<ToolCallResult> {
    process.stderr.write(`telegram gateway: ipc: tool_call tool=${msg.tool} agent=${client.agentName ?? '-'} clientId=${client.id ?? '-'} callId=${msg.id}\n`)
    try {
      const result = await executeToolCall(msg.tool, msg.args)
      return { type: 'tool_call_result', id: msg.id, success: true, result }
    } catch (err) {
      return {
        type: 'tool_call_result',
        id: msg.id,
        success: false,
        error: err instanceof Error ? err.message : String(err),
      }
    }
  },

  onSessionEvent(client: IpcClient, msg: SessionEventForward) {
    // Cheap-cron §2.4: the cron session is status-silent — its session
    // events must not drive the main agent's progress card, transcript
    // tail, currentTurn, or silence-poke. Its reply still flows (onToolCall
    // is not gated). currentTurn was never set for a cron fire (onInjectInbound
    // skips markClaudeBusy), so the card machinery has nothing to attach to.
    if (isCronIdentity(client.agentName)) return
    // Track the session-tail's attached file for the proactive-
    // compaction occupancy read (see maybeProactiveCompact).
    if (msg.activeFile) lastSessionActiveFile = msg.activeFile
    const ev = msg.event as unknown as SessionEvent
    // #1122/#1126: session events used to be ingested into the pinned progress
    // card here (`progressDriver.ingest`). The card is retired and the driver
    // is permanently null, so that call was a dead no-op — removed. Session
    // events still drive the live surfaces via `handleSessionEvent`.
    handleSessionEvent(ev)
    // Problem B: keep the deferred-interrupt boundary tracker in lockstep with
    // the session stream (tool_use opens, tool_result/turn_end close). If a `!`
    // interrupt is parked waiting for a clean boundary and this event drains
    // the last in-flight tool, fire it now rather than waiting out the timer.
    toolFlightTracker.onEvent(ev)
    if (pendingDeferredInterrupt != null && !toolFlightTracker.isMidToolCall()) {
      void fireDeferredInterrupt('boundary')
    }
    // #1122 silence-poke: surface activity signals from the session
    // stream so the 300s framework-fallback message wording is honest
    // (thinking vs working, plus the longest-running in-flight tool).
    if (currentTurn != null) {
      const key = statusKey(currentTurn.sessionChatId, currentTurn.sessionThreadId)
      if (ev.kind === 'thinking') {
        silencePoke.noteThinking(key, Date.now())
      } else if (ev.kind === 'tool_use') {
        // #1292: track in-flight tool calls so the 300s framework
        // fallback message can name the actual observable (e.g.
        // "running Grep \"foo\" for 4m") instead of the dishonest
        // generic "still working… no update in 5 min" when the agent
        // is clearly busy on tool calls. Telegram-surface tools are
        // excluded — their job IS the outbound message, the silence
        // clock resets via noteOutbound when they fire. Sub-agent
        // tool_use events (kind='sub_agent_tool_use') intentionally
        // NOT tracked: the parent's Task tool_use is already on the
        // map and represents the user-observable wait.
        if (
          ev.toolUseId != null
          && ev.toolUseId.length > 0
          && !isTelegramSurfaceTool(ev.toolName)
        ) {
          const label = toolLabel(
            ev.toolName,
            ev.input,
            /*preamble*/ undefined,
            ev.precomputedLabel,
          )
          silencePoke.noteToolStart(
            key,
            ev.toolUseId,
            ev.toolName,
            label.length > 0 ? label : null,
            Date.now(),
          )
          // #1445 cross-turn pending-async ambient. Mark the chat as
          // having dispatched background work this turn so a turn_end
          // that follows activates the edit-in-place ambient line.
          // Covers `Agent` / `Task` (the harness-managed async path
          // — handback channel turn clears it) and `Bash` with
          // run_in_background:true (model is expected to poll
          // BashOutput; the ambient ticks until next inbound or the
          // 30-min budget cap).
          const evInput = ev.input as { run_in_background?: boolean } | undefined
          if (
            ev.toolName === 'Agent'
            || ev.toolName === 'Task'
            || (ev.toolName === 'Bash' && evInput?.run_in_background === true)
          ) {
            pendingProgress.noteAsyncDispatch(key)
          }
        }
      } else if (ev.kind === 'tool_result') {
        // #1292: drain the in-flight entry. Idempotent on unknown ids
        // (covers Telegram-surface tools we skipped at start time).
        if (ev.toolUseId != null && ev.toolUseId.length > 0) {
          silencePoke.noteToolEnd(key, ev.toolUseId, Date.now())
        }
      }
    }
  },

  onPermissionRequest(_client: IpcClient, msg: PermissionRequestForward) {
    const { requestId, toolName, description, inputPreview } = msg
    // "⏱ 30 min" short-circuit: if the operator tapped a live scoped grant
    // covering this exact request, auto-allow without posting a card. CRITICAL:
    // dispatch WITHOUT a `rule` so the bridge does NOT cache it untimed
    // (sessionAllowRules has no TTL — a `rule` here would silently promote the
    // 30-min window to session-forever). The fixed window lives only in
    // scopedGrants. lookupScopedGrant fails closed on expiry and on a
    // destructive Bash command matching a family grant. No card, no pending
    // entry, no awaiting reaction — the turn just continues, silently.
    const scopedTtl = scopedApprovalTtlMs()
    if (scopedTtl > 0) {
      const hit = lookupScopedGrant(scopedGrants, selfAgentName(), toolName, inputPreview, Date.now())
      if (hit) {
        // Silent auto-allow — no card was posted and the turn was never parked
        // on the awaiting glyph, so we intentionally OMIT the resume-glyph flip
        // and the agent-voiced resume message (posting "got it, continuing" on
        // every auto-allowed call is the exact noise this tier removes). The
        // `no-card-verdict` sentinel below exempts this callsite from the
        // resume-guard pairing test.
        dispatchPermissionVerdict({ type: 'permission', requestId, behavior: 'allow' }) // no-card-verdict
        process.stderr.write(
          `telegram gateway: scoped-approval auto-allow tool=${toolName} rule="${hit}" ` +
          `request=${requestId} (time-boxed window)\n`,
        )
        return
      }
    }
    // No-repeat short-circuit: this exact (tool, input) already timed out and
    // the operator hasn't been active since (the suppression map is cleared on
    // any operator activity). Deny it WITH a timeout-duplicate reason and post
    // NO second card — the model retrying into an absent operator is the loop
    // this closes. The turn still unblocks (deny verdict), and a returning
    // operator resets suppression so the next ask gets a fresh card.
    if (PERMISSION_NO_REPEAT_ENABLED) {
      const sig = permissionSignature(toolName, inputPreview)
      if (isRecentTimeoutDuplicate(permissionTimeoutSignatures, sig, Date.now(), PERMISSION_DUPLICATE_WINDOW_MS)) {
        // no-card-verdict: no card was posted and the turn was never parked on
        // the awaiting glyph, so we omit the resume-reaction flip / resume msg.
        dispatchPermissionVerdict({
          type: 'permission',
          requestId,
          behavior: 'deny',
          message: duplicateDenyMessage,
        })
        process.stderr.write(
          `telegram gateway: permission no-repeat short-circuit — duplicate of a ` +
          `timed-out request tool=${toolName} request=${requestId} (no card posted)\n`,
        )
        return
      }
    }
    // Natural-language card body — a plain sentence ("Gymbro wants to
    // edit: supplement-log.md" + a why-line), never a raw tool id.
    // The operator sees what is being requested and why at a glance.
    // Mirrors the `vault_request_access` card layout. Sent via the
    // rich-markdown path below.
    const text = formatPermissionCardBody({
      toolName,
      inputPreview,
      description,
      agentName: _client.agentName,
    })
    // `card_text` is retained so the TTL reaper can re-edit the SAME body
    // with a "timed out" footer while stripping the keyboard atomically
    // (Bug 2 fix #1) — the reaper has no grammy ctx to read the live text.
    pendingPermissions.set(requestId, { tool_name: toolName, description, input_preview: inputPreview, startedAt: Date.now(), card_text: text, cards: [] })
    // Compact action row: ❌ Deny · ✅ Allow · 🔁 Always… — the scope of an
    // "always" grant stays hidden until the operator taps "🔁 Always…",
    // which swaps the row for a scope choice (this file / any file ⚠️). The
    // "🔁 Always…" button only appears when we can synthesize a meaningful
    // rule for this tool; unknown tools get the two-button row only. "Allow"
    // itself auto-grants a 30-min window for narrow non-destructive scopes
    // (decided in the allow handler), so there is no separate time-box button.
    const showAlways = resolveScopedAllowChoices(toolName, inputPreview) != null
    const keyboard = buildPermissionActionRow(requestId, showAlways)
    // Route the card to the SAME place the post-verdict resume message
    // lands (resolvePermissionCardTargets): the ORIGINATING chat+topic when
    // there's an active turn — so a supergroup agent's card appears IN the
    // topic the operator asked from (marko's "CRM (Brevo)"), not the
    // operator DM — else the configured operator DMs, thread-stripped. The
    // old code iterated `allowFrom` unconditionally, so a supergroup card
    // could only ever reach operator DMs (the topic chat id is never in
    // `allowFrom`) (marko, 2026-06-03).
    const activeTurn = currentTurn
    const targets = resolvePermissionCardTargets()
    for (const { chatId, threadId } of targets) {
      // The rich-markdown path pairs with formatPermissionCardBody (#1790)
      // so its bold/italic render. retryWithThreadFallback: if the topic was
      // deleted/recreated (stale thread id → 400 "message thread not
      // found"), re-send thread-less into the main chat so the card still
      // ARRIVES rather than vanishing → 10-min TTL auto-deny → wedge.
      // allow-raw-bot-api: wrapped in retryWithThreadFallback (retry policy); topic-aware send
      void retryWithThreadFallback<{ message_id: number }>(
        robustApiCall,
        (tid) =>
          bot.api.sendRichMessage(chatId, richMessage(text), {
            reply_markup: keyboard,
            ...(tid != null ? { message_thread_id: tid } : {}),
          }),
        { threadId, chat_id: chatId, verb: 'permission_request' },
      ).then(sent => {
        // Record the live card's (chat, message) so the TTL reaper can strip
        // its inline keyboard on auto-deny — a stale Approve button left
        // tappable dispatches a verdict for a dead request_id (Bug 2). The
        // entry may already be gone (operator tapped before this resolved);
        // guard the lookup.
        const pend = pendingPermissions.get(requestId)
        if (pend && sent && typeof sent.message_id === 'number') {
          pend.cards.push({ chatId, messageId: sent.message_id })
          permCardStore.add({
            requestId,
            chatId,
            messageId: sent.message_id,
            startedAt: pend.startedAt,
            toolName: pend.tool_name,
            cardText: pend.card_text,
          })
        }
      }).catch(e => {
        process.stderr.write(`telegram gateway: permission_request send to ${chatId} failed: ${e}\n`)
      })
    }
    // Park the turn's status reaction on 🙏 (awaiting your tap) and
    // suspend the stall watchdog — a turn blocked on the operator is not
    // stalled, so it must not degrade to 🥱/😨 while the card sits
    // unanswered. The verdict path (`resumeReactionAfterVerdict`) flips it
    // back to a working state the instant you tap.
    if (activeTurn != null) {
      activeStatusReactions
        .get(statusKey(activeTurn.sessionChatId, activeTurn.sessionThreadId))
        ?.setAwaiting()
    }
  },

  onHeartbeat(_client: IpcClient, _msg: HeartbeatMessage) {
    // Heartbeat received — no action needed, the server tracks lastHeartbeat
  },

  onScheduleRestart(client: IpcClient, msg: ScheduleRestartMessage) {
    const { agentName } = msg;

    // Check if any turn is currently in flight.
    // PR3b: gated on claudeBusyKeys (actually-handed-to-claude turns)
    // not activeTurnStartedAt (receipt-eager), so a buffered topic-B
    // inbound doesn't pin this as turnInFlight=true forever.
    // PR3b-cutover: reads the delivery machine when the kill-switch is on.
    const turnInFlight = turnInFlightForGate();

    if (!turnInFlight) {
      // No active turn, restart immediately. Cycle both the agent and
      // gateway side-by-side so telegram-plugin code changes always
      // propagate. Send the client response FIRST, then trigger the
      // restart after a brief delay so the IPC response has flushed
      // before we get killed. (Under docker the helper SIGTERM's PID 1;
      // under systemd it spawns a detached `systemctl restart`.)
      try {
        client.send({
          type: 'schedule_restart_result',
          success: true,
          restartedImmediately: true,
        });
        triggerSelfRestart(agentName, 'schedule-restart-immediate');
      } catch (err) {
        client.send({
          type: 'schedule_restart_result',
          success: false,
          error: err instanceof Error ? err.message : String(err),
        });
        process.stderr.write(`telegram gateway: restart spawn failed for ${agentName}: ${err}\n`);
      }
    } else {
      // Turn is active, schedule restart for when turn completes
      process.stderr.write(`telegram gateway: scheduling restart for ${agentName} after current turn\n`);

      // Set a flag that will be checked when turns complete
      pendingRestarts.set(agentName, Date.now());

      client.send({
        type: 'schedule_restart_result',
        success: true,
        waitingForTurn: true,
      });
    }
  },

  onOperatorEvent(_client: IpcClient, msg: OperatorEventForward) {
    // Bridge has detected an Anthropic API error (or synthetic gateway-side
    // event). chatId on the wire is currently always empty — operator events
    // are agent-level, not tied to a specific user message; the helper
    // resolves the destination from `access.allowFrom`.
    emitGatewayOperatorEvent({
      kind: msg.kind as OperatorEventKind,
      agent: msg.agent,
      detail: msg.detail,
      suggestedActions: [],
      firstSeenAt: new Date(),
    })
  },

  // onUpdatePlaceholder handler removed in #553 PR 5 — fake placeholder
  // text (`🔵 thinking`, `📚 recalling memories`, `💭 thinking`) is no
  // longer emitted. recall.py's update_placeholder IPC calls become
  // benign no-ops: the IPC client validates the wire shape but no
  // server-side handler is registered, so the message is silently
  // ignored at dispatch.

  /**
   * Forwarded PTY-tail partial: the latest extracted assistant-reply
   * text from Claude Code's TUI rendering. Routes through
   * `handlePtyPartial` (declared further down) which writes the text
   * into the active draft stream for `currentSessionChatId`. The chat
   * id is resolved from the most recent enqueue session_event the
   * bridge has forwarded — same pattern as the legacy monolith path
   * in server.ts.
   *
   * Best-effort: silently no-op when the stream isn't ready (no chat
   * resolved yet, suppressed by an in-flight reply, dedup match).
   * `handlePtyPartial` does its own buffering for the
   * partial-before-enqueue race.
   */
  onPtyPartial(client: IpcClient, msg: PtyPartialForward) {
    // Cheap-cron §2.4: cron session is status-silent — no visible reply
    // stream from its PTY tail (it would edit a card the main session owns).
    if (isCronIdentity(client.agentName)) return
    handlePtyPartial(msg.text)
  },

  /**
   * Phase 2 cron-fold-in: forward a synthesized inbound from the
   * in-agent scheduler sibling to the registered bridge for the
   * named agent. The wrapped `inbound` envelope is shipped verbatim
   * — the in-agent scheduler is the synthesis authority (it runs
   * `dispatchAsInbound` from `src/scheduler/dispatch.ts` to build
   * the message). The gateway only validates wire shape (handled
   * in ipc-server.ts:validateClientMessage) and routes.
   *
   * Logs every fire so an operator can correlate the agent's
   * transcript turn against the scheduler's audit row by `prompt_key`.
   */
  async onRequestDriveApproval(client: IpcClient, msg) {
    // RFC E §4.2 Cut 2 — Drive-write PreToolUse hook is asking the
    // gateway to post a diff-preview card so the user can decide.
    await handleRequestDriveApproval(client, msg, {
      agentName: getMyAgentName(),
      loadAllowFrom: () => loadAccess().allowFrom,
      loadTargetChat: () => {
        const access = loadAccess()
        const operator = access.allowFrom[0]
        if (operator === undefined) return null
        // For DM-paired setups the target chat IS the operator's
        // user id. For group setups the gateway already has a topic
        // routing surface (see how /folders posts) — this picks the
        // DM path which is the common case; group-routing follow-up
        // can extend this.
        // PR4b emitter sweep — supergroup-mode adds an explicit
        // topic. Drive approval cards follow the originating turn
        // (operator-initiated tool call), admin alias fallback.
        const activeTurn = currentTurn
        // Attach the topic only when `operator` IS the agent's supergroup —
        // operator DMs have no topics (marko brevo wedge, 2026-06-02).
        const driveTopic = topicForRecipient({
          recipientChatId: operator,
          resolvedTopic: resolveAgentOutboundTopic({
            kind: 'hostd-approval',
            originThreadId: activeTurn?.sessionThreadId,
          }),
          supergroupChatId: resolveAgentSupergroupChatId(),
        })
        return {
          chatId: operator,
          ...(driveTopic != null ? { threadId: driveTopic } : {}),
        }
      },
      registerApproval: async (args) => {
        const r = await kernelApprovalRequest({
          agent_unit: args.agent_unit,
          scope: args.scope,
          action: args.action,
          approver_set: args.approver_set,
          why: args.why,
          ttl_ms: args.ttl_ms,
        })
        if (r === null || r.state === 'rate_limited') return null
        return {
          request_id: r.request_id,
          expires_at_ms: r.expires_at,
        }
      },
      postCard: async (args) => {
        try {
          const sent = await robustApiCall(
            () =>
              bot.api.sendRichMessage(args.chatId, richMessage(args.text), {
                ...(args.threadId !== undefined
                  ? { message_thread_id: args.threadId }
                  : {}),
                reply_markup: args.replyMarkup as never,
              }),
            {
              chat_id: String(args.chatId),
              verb: 'drive-approval-card',
              ...(args.threadId !== undefined ? { threadId: args.threadId } : {}),
            },
          )
          return { messageId: (sent as { message_id: number }).message_id }
        } catch (err) {
          process.stderr.write(
            `telegram gateway: drive-approval postCard failed: ${(err as Error).message}\n`,
          )
          return null
        }
      },
      buildCard: ({ preview, suggestRequestId }) =>
        buildDiffPreviewCard({ preview, suggestRequestId }),
      log: (m) => process.stderr.write(`telegram gateway: drive-approval — ${m}\n`),
    })
  },

  /**
   * RFC #1873 §8 — MS-365 write approval card. Mirrors
   * onRequestDriveApproval but with the weak-metadata v1 preview shape
   * (no diff-preview — just plain text card).
   */
  async onRequestMs365Approval(client: IpcClient, msg) {
    await handleRequestMs365Approval(client, msg, {
      agentName: getMyAgentName(),
      loadAllowFrom: () => loadAccess().allowFrom,
      loadTargetChat: () => {
        const access = loadAccess()
        const operator = access.allowFrom[0]
        if (operator === undefined) return null
        // PR4b emitter sweep — MS365 write approval cards route into
        // the originating turn's topic in supergroup mode, admin
        // alias fallback for background cases. Same shape as hostd /
        // drive approvals below.
        const activeTurn = currentTurn
        // Topic valid only in the agent's supergroup — never on the operator DM.
        const ms365Topic = topicForRecipient({
          recipientChatId: operator,
          resolvedTopic: resolveAgentOutboundTopic({
            kind: 'hostd-approval',
            originThreadId: activeTurn?.sessionThreadId,
          }),
          supergroupChatId: resolveAgentSupergroupChatId(),
        })
        return {
          chatId: operator,
          ...(ms365Topic != null ? { threadId: ms365Topic } : {}),
        }
      },
      registerApproval: async (args) => {
        const r = await kernelApprovalRequest({
          agent_unit: args.agent_unit,
          scope: args.scope,
          action: args.action,
          approver_set: args.approver_set,
          why: args.why,
          ttl_ms: args.ttl_ms,
        })
        if (r === null || r.state === 'rate_limited') return null
        return {
          request_id: r.request_id,
          expires_at_ms: r.expires_at,
        }
      },
      postCard: async (args) => {
        try {
          const sent = await robustApiCall(
            () =>
              bot.api.sendMessage(args.chatId, args.text, {
                ...(args.threadId !== undefined
                  ? { message_thread_id: args.threadId }
                  : {}),
                reply_markup: args.replyMarkup as never,
              }),
            {
              chat_id: String(args.chatId),
              verb: 'ms365-approval-card',
              ...(args.threadId !== undefined ? { threadId: args.threadId } : {}),
            },
          )
          return { messageId: (sent as { message_id: number }).message_id }
        } catch (err) {
          process.stderr.write(
            `telegram gateway: ms365-approval postCard failed: ${(err as Error).message}\n`,
          )
          return null
        }
      },
      log: (m) => process.stderr.write(`telegram gateway: ms365-approval — ${m}\n`),
    })
  },

  /**
   * #1623 — hostd-initiated config-edit approval card. hostd posts a
   * `request_config_approval` message; we render the card via
   * `handleRequestConfigApproval`, awaiting the operator tap (or
   * timeout) before sending `config_approval_resolved` back. After
   * hostd's apply attempt completes it posts
   * `request_config_finalize` to flip the card to the terminal
   * outcome.
   */
  async onRequestConfigApproval(client: IpcClient, msg) {
    const { handleRequestConfigApproval } = await import(
      './config-approval-handler.js'
    )
    const { InlineKeyboard } = await import('grammy')
    await handleRequestConfigApproval(client, msg, {
      agentName: getMyAgentName(),
      loadTargetChat: () => {
        const access = loadAccess()
        const operator = access.allowFrom[0]
        if (operator === undefined) return null
        // PR4b emitter sweep — hostd config-approval cards are
        // operator-initiated (someone typed /update apply or tapped
        // a button). Follow the originating turn when there is one;
        // admin alias fallback in supergroup mode otherwise. Helper
        // returns undefined for non-supergroup agents → behavior
        // unchanged.
        const activeTurn = currentTurn
        // Topic valid only in the agent's supergroup — never on the operator DM.
        const cfgTopic = topicForRecipient({
          recipientChatId: operator,
          resolvedTopic: resolveAgentOutboundTopic({
            kind: 'hostd-approval',
            originThreadId: activeTurn?.sessionThreadId,
          }),
          supergroupChatId: resolveAgentSupergroupChatId(),
        })
        return {
          chatId: operator,
          ...(cfgTopic != null ? { threadId: cfgTopic } : {}),
        }
      },
      buildKeyboard: (requestId, epoch) =>
        new InlineKeyboard()
          .text('✅ Approve', `cfg:${requestId}:${epoch}:approve`)
          .text('🚫 Deny', `cfg:${requestId}:${epoch}:deny`),
      postCard: async (args) => {
        try {
          const sent = await robustApiCall(
            () =>
              // allow-raw-bot-api: sendRichMessage routed through robustApiCall (not in the THREAD_NOT_FOUND blast pattern)
              bot.api.sendRichMessage(args.chatId, richMessage(args.text), {
                ...(args.threadId !== undefined
                  ? { message_thread_id: args.threadId }
                  : {}),
                reply_markup: args.replyMarkup as never,
              }),
            {
              chat_id: String(args.chatId),
              verb: 'config-approval-card',
              ...(args.threadId !== undefined ? { threadId: args.threadId } : {}),
            },
          )
          return { messageId: (sent as { message_id: number }).message_id }
        } catch (err) {
          process.stderr.write(
            `telegram gateway: config-approval postCard failed: ${(err as Error).message}\n`,
          )
          return null
        }
      },
      editCard: async (args) => {
        try {
          await robustApiCall(
            () =>
              bot.api.editMessageText(args.chatId, args.messageId, richMessage(args.text), {
                // Strip the inline keyboard on a terminal/interim edit so the
                // [Approve]/[Deny] buttons stop being tappable on a resolved card.
                ...(args.stripKeyboard ? { reply_markup: { inline_keyboard: [] } } : {}),
              }),
            { chat_id: String(args.chatId), verb: 'config-approval-edit' },
          )
        } catch (err) {
          process.stderr.write(
            `telegram gateway: config-approval editCard failed: ${(err as Error).message}\n`,
          )
        }
      },
      // #1762: send the full diff as a `.patch` attachment when the
      // card body would exceed Telegram's 4096-char sendMessage limit.
      postAttachment: async (args) => {
        const input = new InputFile(Buffer.from(args.content, 'utf8'), args.filename)
        await robustApiCall(
          () =>
            bot.api.sendDocument(args.chatId, input, {
              ...(args.threadId !== undefined
                ? { message_thread_id: args.threadId }
                : {}),
            }),
          {
            chat_id: String(args.chatId),
            verb: 'config-approval-attachment',
            ...(args.threadId !== undefined ? { threadId: args.threadId } : {}),
          },
        )
      },
      log: (m) =>
        process.stderr.write(`telegram gateway: config-approval — ${m}\n`),
      // #1977 single-tap correlation: auto-approve a config edit the
      // gateway itself just queued in response to an operator tap on
      // the "🔁 Always allow" permission card. Forge-resistant — the
      // match requires the rule the diff ADDS to equal a rule the
      // gateway queued; an agent-forged edit touching any other field
      // finds no entry and falls through to a real operator card.
      tryAutoResolve: (msg) => {
        sweepStaleAlwaysAllowCorrelations()
        // `extractAddedAllowRule` only locates a CANDIDATE entry by the
        // rule token — it is shape-based, not YAML-location-aware, so it
        // is NOT the security gate. The gate is an EXACT byte-match of
        // the incoming diff against the diff the gateway itself
        // synthesized and queued. A forged config_propose_edit (the same
        // consented token placed under `deny:`/`secrets:`, a different
        // field, or any other byte difference) won't match → falls
        // through to a real operator approval card.
        const added = extractAddedAllowRule(msg.unifiedDiff)
        if (!added) return null
        const key = `${msg.agentName}::${added}`
        const entry = pendingAlwaysAllowCorrelations.get(key)
        if (entry && entry.unifiedDiff === msg.unifiedDiff) {
          pendingAlwaysAllowCorrelations.delete(key)
          return 'approve'
        }
        return null
      },
    })
  },

  async onRequestConfigFinalize(client: IpcClient, msg) {
    const { handleRequestConfigFinalize } = await import(
      './config-approval-handler.js'
    )
    await handleRequestConfigFinalize(client, msg, {
      editCard: async (args) => {
        try {
          await robustApiCall(
            () =>
              bot.api.editMessageText(args.chatId, args.messageId, richMessage(args.text), {
                // Finalize is terminal — drop the keyboard so buttons are gone.
                ...(args.stripKeyboard ? { reply_markup: { inline_keyboard: [] } } : {}),
              }),
            { chat_id: String(args.chatId), verb: 'config-approval-finalize' },
          )
        } catch (err) {
          process.stderr.write(
            `telegram gateway: config-finalize editCard failed: ${(err as Error).message}\n`,
          )
        }
      },
      log: (m) =>
        process.stderr.write(`telegram gateway: config-finalize — ${m}\n`),
    })
  },

  // #2726 — hostd-initiated rollout status message. Part 1 uses this only for
  // the terminal ping; Part 2 uses the same post as the FIRST narration
  // message, then EDITs it (onRolloutStatusEdit) as later phases arrive. This
  // is an ORDINARY operator-DM message, NOT a pinned card — the framework
  // speaking a plain progress line in the chat. We reply with the message_id so
  // hostd can edit it later; a post failure replies ok:false (hostd then just
  // won't edit — the durable audit log remains the record).
  async onRolloutStatusPost(client: IpcClient, msg: RolloutStatusPostMessage) {
    const self = process.env.SWITCHROOM_AGENT_NAME
    if (self && msg.agentName !== self) {
      process.stderr.write(
        `telegram gateway: rollout_status_post rejected — agent mismatch (${msg.agentName} != ${self})\n`,
      )
      try {
        client.send({ type: 'rollout_status_posted', requestId: msg.requestId, ok: false, reason: 'agent mismatch' })
      } catch { /* best effort */ }
      return
    }
    const operator = loadAccess().allowFrom[0]
    if (operator === undefined) {
      process.stderr.write(`telegram gateway: rollout_status_post — no operator chat (allowFrom empty)\n`)
      try {
        client.send({ type: 'rollout_status_posted', requestId: msg.requestId, ok: false, reason: 'no operator chat' })
      } catch { /* best effort */ }
      return
    }
    try {
      const sent = await robustApiCall(
        () =>
          // allow-raw-bot-api: rich progress line, routed through robustApiCall.
          bot.api.sendRichMessage(operator, richMessage(msg.text), {}),
        { chat_id: String(operator), verb: 'rollout-status-post' },
      )
      const messageId = (sent as { message_id: number }).message_id
      process.stderr.write(
        `telegram gateway: rollout_status_post agent=${msg.agentName} request=${msg.requestId} message_id=${messageId}\n`,
      )
      try {
        client.send({ type: 'rollout_status_posted', requestId: msg.requestId, ok: true, messageId })
      } catch { /* best effort */ }
    } catch (err) {
      process.stderr.write(
        `telegram gateway: rollout_status_post send failed: ${(err as Error).message}\n`,
      )
      try {
        client.send({ type: 'rollout_status_posted', requestId: msg.requestId, ok: false, reason: (err as Error).message })
      } catch { /* best effort */ }
    }
  },

  // #2726 Part 2 — edit the previously-posted rollout status message in place as
  // later phases arrive. Fire-and-forget: an edit failure (incl. Telegram 429)
  // is swallowed here and NEVER surfaced back toward the roll. hostd owns the
  // debounce + 429 retry cadence; this handler is a thin edit relay.
  onRolloutStatusEdit(_client: IpcClient, msg: RolloutStatusEditMessage) {
    const self = process.env.SWITCHROOM_AGENT_NAME
    if (self && msg.agentName !== self) {
      process.stderr.write(
        `telegram gateway: rollout_status_edit rejected — agent mismatch (${msg.agentName} != ${self})\n`,
      )
      return
    }
    const operator = loadAccess().allowFrom[0]
    if (operator === undefined) {
      process.stderr.write(`telegram gateway: rollout_status_edit — no operator chat (allowFrom empty)\n`)
      return
    }
    void swallowingApiCall(
      () =>
        // allow-raw-bot-api: in-place edit of the ordinary status message.
        bot.api.editMessageText(operator, msg.messageId, richMessage(msg.text), {}),
      { chat_id: String(operator), verb: 'rollout-status-edit' },
    )
  },

  onInjectInbound(_client: IpcClient, msg: InjectInboundMessage) {
    // Cron fires (incl. cheap-cron, whose session events are dropped before
    // currentTurn is set) are real activity — re-arm idle auto-clear so a
    // working scheduled agent isn't wiped after 3h of "no inbound".
    markIdleActivity()
    const promptKey = typeof msg.inbound.meta?.prompt_key === 'string'
      ? msg.inbound.meta.prompt_key
      : 'unknown'
    const source = typeof msg.inbound.meta?.source === 'string'
      ? msg.inbound.meta.source
      : 'unknown'
    // Cheap-cron (reference/rfcs/cheap-cron-sessions.md §3.3): a Tier-1 fire
    // carries meta.session='cron' → route to the derived `<agent>-cron`
    // bridge (a 2nd interactive Sonnet session in the same container).
    // Every other fire (and all of today's callers) routes to the agent
    // unchanged. Route+buffer share the same target so a fire that lands
    // mid cron-session-spawn buffers under the cron identity and drains to
    // it on register.
    // Graceful Tier-1 fallback (cheap-crons JTBD: a cron must NEVER be
    // dropped because of tier routing). A cron-routed fire whose `<agent>-cron`
    // bridge isn't connected (boot-forked session not up yet for a hot-added
    // frequent cron, or a crashed cron session) falls back to the MAIN agent
    // bridge so the fire lands now; it routes cheap again once the session is
    // up. See deliverInjectWithFallback.
    const { target, delivered, fellBackToMain } = deliverInjectWithFallback(
      msg.agentName,
      msg.inbound.meta,
      (t) => ipcServer.sendToAgent(t, msg.inbound),
    )
    if (fellBackToMain) {
      process.stderr.write(
        `telegram gateway: cron fire fell back to main session (no cron bridge) agent=${msg.agentName} prompt_key=${promptKey}\n`,
      )
      // #2307 Tier-1 observability: a climbing counter means the cron session is
      // down (registered then died, or never came up) — the Tier-1 saving is
      // lost for this fire. Surfaced via the unified runtime-metrics fan-out.
      emitRuntimeMetric({ kind: 'cron_fell_back_to_main', agent: msg.agentName, prompt_key: promptKey })
    }
    // Status-silent (§2.4): a cron fire delivered to the CRON session must NOT
    // set the MAIN agent's currentTurn. But a fire that LANDED on the main
    // bridge (a non-cron fire, or one that fell back) IS a main-session turn —
    // surface it on the progress card, or the session looks dark.
    if (delivered && target === msg.agentName) markClaudeBusyForInbound(msg.inbound)
    process.stderr.write(
      `telegram gateway: inject_inbound agent=${msg.agentName} target=${target}${fellBackToMain ? " (fellback)" : ""} source=${source} prompt_key=${promptKey} delivered=${delivered}\n`,
    )
    // #1150: same buffer-on-failure pattern as vault_grant_approved.
    // Only reached if BOTH the cron bridge and the main bridge are down
    // (e.g. mid-restart) — buffer under the bridge we tried last so it
    // drains on the next register.
    if (!delivered) {
      pendingInboundBuffer.push(target, msg.inbound)
    }
  },

  // #2307 Tier-0 action tier — a MODEL-FREE outbound post. The agent-scheduler
  // fires this for a `kind: action` `telegram-message`; the gateway posts the
  // (already-substituted) text to the agent's OWN chat with NO model: no
  // inject_inbound, no session wake, no currentTurn mutation. Two fences:
  //   1. agentName must match this gateway's own SWITCHROOM_AGENT_NAME.
  //   2. chatId must be an allowlisted chat for this agent (assertAllowedChat).
  // An action carries no chat target of its own — the scheduler supplies the
  // agent's own chat — so 2 is belt-and-braces against a malformed/foreign id.
  onSendOutbound(_client: IpcClient, msg: SendOutboundMessage) {
    const self = process.env.SWITCHROOM_AGENT_NAME
    if (self && msg.agentName !== self) {
      process.stderr.write(
        `telegram gateway: send_outbound rejected — agent mismatch (${msg.agentName} != ${self})\n`,
      )
      return
    }
    try {
      assertAllowedChat(msg.chatId)
    } catch (err) {
      process.stderr.write(
        `telegram gateway: send_outbound rejected — ${(err as Error).message}\n`,
      )
      return
    }
    const threadId = msg.threadId
    // #2669: literal `text` mode → plain send; everything else → rich markdown.
    const literalText = msg.parseMode === 'text'
    const outOpts = {
      ...(threadId != null && threadId !== 1 ? { message_thread_id: threadId } : {}),
    }
    // allow-raw-bot-api: wrapped in swallowingApiCall (retry policy); thread-aware send.
    // General topic (thread 1) sends omit message_thread_id per the outbound convention.
    void swallowingApiCall(
      (): Promise<{ message_id: number }> =>
        literalText
          ? bot.api.sendMessage(msg.chatId, msg.text, outOpts)
          : bot.api.sendRichMessage(msg.chatId, richMessage(msg.text), outOpts),
      { chat_id: msg.chatId, verb: 'cron-action-send', ...(threadId != null ? { threadId } : {}) },
    )
    process.stderr.write(
      `telegram gateway: send_outbound agent=${msg.agentName} chat=${msg.chatId} thread=${threadId ?? '-'} len=${msg.text.length}\n`,
    )
  },

  // The wedge-watchdog detected claude's /rate-limit-options weekly-quota menu
  // (a TUI wall that never produced a 429, so the inference-path auto-fallback
  // never fired). Trigger the SAME fleet auto-fallback the 429 path uses,
  // threading the parsed weekly reset as markExhausted's `until` — with a
  // weekly-scale FALLBACK when the sidecar couldn't parse it (resetAt absent):
  // passing undefined would let markExhausted use its ~5h default, which would
  // un-exhaust a weekly-walled account and re-wedge it within hours. The
  // existing chain handles the rest (roll to a fallback subscription account,
  // or the all-exhausted operator alert when none has quota). Fire-and-forget.
  onQuotaWallDetected(_client: IpcClient, msg: QuotaWallDetectedMessage) {
    const untilMs = resolveExhaustUntil(msg.resetAt)
    process.stderr.write(
      `telegram gateway: quota_wall_detected agent=${msg.agentName} ` +
        `until=${new Date(untilMs).toISOString()}` +
        (msg.resetAt == null ? ' (reset unparsed → +7d default)' : '') +
        ' — triggering fleet auto-fallback\n',
    )
    void fireFleetAutoFallback(msg.agentName, untilMs)
  },

  // #2670 one-tap self-improvement — persist a skill-improvement proposal and
  // post its Approve/Dismiss card. The store transition + apply-injection on
  // Approve are owned by handleSkillProposalCallback (so a gateway restart
  // between post and tap still resolves correctly). Placed AFTER
  // onQuotaWallDetected so it doesn't fall inside the source slice that
  // send-outbound-wiring.test.ts takes between onSendOutbound and
  // onQuotaWallDetected.
  onPostSkillProposal(_client: IpcClient, msg: PostSkillProposalMessage) {
    const self = process.env.SWITCHROOM_AGENT_NAME
    if (self && msg.agentName !== self) {
      process.stderr.write(
        `telegram gateway: post_skill_proposal rejected — agent mismatch (${msg.agentName} != ${self})\n`,
      )
      return
    }
    try {
      assertAllowedChat(msg.chatId)
    } catch (err) {
      process.stderr.write(
        `telegram gateway: post_skill_proposal rejected — ${(err as Error).message}\n`,
      )
      return
    }
    const stateDir = process.env.TELEGRAM_STATE_DIR
    if (stateDir == null || stateDir.length === 0) {
      process.stderr.write(`telegram gateway: post_skill_proposal: TELEGRAM_STATE_DIR unset, skipping\n`)
      return
    }
    // Dedup against still-live rejection fingerprints — never re-surface a
    // proposal the operator already dismissed.
    if (isSkillProposalSuppressed(stateDir, {
      lesson: msg.lesson,
      draft: msg.draft,
      skill_slug: msg.skillSlug,
    })) {
      process.stderr.write(
        `telegram gateway: post_skill_proposal suppressed (rejected before) slug=${msg.skillSlug}\n`,
      )
      return
    }
    const proposal = enqueueSkillProposal(stateDir, {
      skill_slug: msg.skillSlug,
      is_new: msg.isNew,
      lesson: msg.lesson,
      draft: msg.draft,
      evidence: msg.evidence,
      chat_id: Number(msg.chatId),
    })
    const cardText = renderSkillProposalCard({
      id: proposal.id,
      skill_slug: proposal.skill_slug,
      is_new: proposal.is_new,
      lesson: proposal.lesson,
      evidence: proposal.evidence,
      skill_md: proposal.draft['SKILL.md'],
    })
    const threadId = msg.threadId
    void swallowingApiCall(
      () =>
        bot.api.sendMessage(msg.chatId, cardText, {
          parse_mode: 'HTML',
          reply_markup: skillProposalKeyboard(proposal.id),
          ...(threadId != null && threadId !== 1 ? { message_thread_id: threadId } : {}),
        }),
      { chat_id: msg.chatId, verb: 'skill-proposal-card', ...(threadId != null ? { threadId } : {}) },
    )
    process.stderr.write(
      `telegram gateway: post_skill_proposal agent=${msg.agentName} chat=${msg.chatId} ` +
      `proposal=${proposal.id} slug=${proposal.skill_slug} new=${proposal.is_new}\n`,
    )
  },

  log: (msg) => process.stderr.write(`telegram gateway: ipc — ${msg}\n`),
})

// ─── Webhook ingest server (RFC webhook-via-gateway-socket) ───────────────
// Under the Docker runtime the host-side web receiver runs as the operator
// UID and cannot write this agent's UID-owned dir (EACCES 500) nor connect
// gateway.sock. When `channels.telegram.webhook_via_gateway` is set, the
// receiver instead forwards verified+rendered events here over a dedicated
// peercred-gated UDS; this gateway (agent UID) owns the jsonl append,
// dedup, and dispatch firing. Wrapped so any failure is best-effort and can
// NEVER crash gateway boot (which would take the agent down).
;(() => {
  try {
    const selfAgent = process.env.SWITCHROOM_AGENT_NAME ?? ''
    if (!selfAgent) return

    let viaGateway = false
    try {
      const cfg = loadSwitchroomConfig()
      const raw = cfg.agents?.[selfAgent]
      viaGateway = raw
        ? resolveAgentConfig(cfg.defaults, cfg.profiles, raw).channels?.telegram
            ?.webhook_via_gateway === true
        : false
    } catch (err) {
      process.stderr.write(
        `telegram gateway: webhook-ingest config probe failed: ${(err as Error).message}\n`,
      )
    }
    if (!viaGateway) return

    // Allowed peer UIDs: the agent's own UID (self-connections) + the
    // operator/receiver UID emitted into the env by the compose generator
    // (SWITCHROOM_WEBHOOK_RECEIVER_UID == operatorUid). Fail-closed: if the
    // receiver UID is unset, only self can connect → receiver gets 503,
    // surfacing the misconfiguration instead of silently accepting any UID.
    const allowedUids: number[] = []
    const ownUid = typeof process.getuid === 'function' ? process.getuid() : null
    if (ownUid !== null) allowedUids.push(ownUid)
    const receiverUidRaw = process.env.SWITCHROOM_WEBHOOK_RECEIVER_UID
    const receiverUid = receiverUidRaw ? Number(receiverUidRaw) : NaN
    if (Number.isInteger(receiverUid)) allowedUids.push(receiverUid)

    const socketPath = join(STATE_DIR, 'webhook.sock')

    // In-process delivery of a synthesized webhook turn — the same
    // sendToAgent + buffer-on-failure primitive onInjectInbound uses, so a
    // webhook fire landing mid bridge-reconnect is buffered, not dropped.
    const webhookInject = (agentName: string, inbound: unknown): boolean => {
      // The wire record is a structural mirror of the bridge's
      // InboundMessage (same cast the scheduler's ipcDispatcher uses).
      const msg = inbound as InboundMessage
      const delivered = ipcServer.sendToAgent(agentName, msg)
      if (delivered) markClaudeBusyForInbound(msg)
      else pendingInboundBuffer.push(agentName, msg)
      return delivered
    }

    startWebhookIngestServer({
      socketPath,
      allowedUids,
      log: (s) => process.stderr.write(`telegram gateway: ${s}`),
      onRecord: (req) =>
        recordWebhookEvent(
          {
            agent: selfAgent,
            source: req.source,
            event_type: req.event_type,
            ts: req.ts,
            rendered_text: req.rendered_text,
            payload: req.payload,
            ...(req.delivery_id ? { delivery_id: req.delivery_id } : {}),
          },
          {
            inject: webhookInject,
            log: (s) => process.stderr.write(`telegram gateway: ${s}`),
          },
        ),
    })
  } catch (err) {
    process.stderr.write(
      `telegram gateway: webhook-ingest server start failed (non-fatal): ${(err as Error).message}\n`,
    )
  }
})()

// ─── Opportunistic idle-drain of pendingInboundBuffer ─────────────────────
// pendingInboundBuffer otherwise drains only on (a) bridge re-register
// (onClientRegistered) or (b) the silence-poke framework fallback
// clearing a wedged turn (#1546). NEITHER fires when a message is
// buffered during a bridge-IPC flap that then settles with no
// subsequent clean re-register AND claude is idle (no active turn →
// silence-poke never arms). The message orphans until a manual restart
// (finn, 2026-05-19 — buffered "verify with mff-query.py cashflow"
// while idle; last `bridge registered` predated the buffer push, so
// onClientRegistered's drain never ran for it).
//
// This is the third drain trigger. It's gated to be zero-cost and
// zero-churn: skip entirely when nothing is buffered (one Map.get, no
// log), when the bridge isn't alive (exactly sendToAgent's own guard —
// so we never drain into a dead bridge and re-buffer/log-spin), OR
// when a turn is in flight. The turn gate is #1556: a message
// delivered while a turn is active is NOT safely queued by the bridge
// — claude types it into its TUI composer and the auto-submit races
// turn-completion, stranding it (the lawgpt wedge). Draining only at
// `activeTurnStartedAt.size === 0` guarantees the channel notification
// lands at an idle prompt and submits as a fresh turn. Only when there
// IS a buffered message AND a live bridge AND no active turn do we
// reuse the #1546 `redeliverBufferedInbound` (lossless: re-buffers any
// per-message miss).
const IDLE_DRAIN_INTERVAL_MS = 5000
if (!STATIC) {
  setInterval(() => {
    const selfAgent = process.env.SWITCHROOM_AGENT_NAME ?? ''
    const r = idleDrainTick(
      pendingInboundBuffer,
      selfAgent,
      () => {
        // #1556: never drain mid-turn — that re-creates the composer
        // wedge this buffer exists to prevent.
        // PR3b: gated on claudeBusyKeys (see purgeReactionTracking).
        // PR3b-cutover: reads the delivery machine when the kill-switch is on.
        if (turnInFlightForGate()) return false
        const c = ipcServer.getClient(selfAgent)
        return c != null && c.isAlive()
      },
      (m) => {
        const d = ipcServer.sendToAgent(selfAgent, m)
        if (d) markClaudeBusyForInbound(m)
        return d
      },
      inboundSpool,
      trackRedeliveredInbound,
    )
    if (r != null && r.redelivered > 0) {
      process.stderr.write(
        `telegram gateway: idle-drain flushed ${r.redelivered}/${r.drained} ` +
        `buffered inbound for ${selfAgent}` +
        `${r.rebuffered > 0 ? ` (${r.rebuffered} re-buffered)` : ''}\n`,
      )
    }
    // Bounded escalation: a spooled inbound still un-acked past its
    // bound (default 15 min — well past the 5-min silence-poke ladder)
    // is undeliverable in practice. Retract the "will be processed"
    // promise EXPLICITLY (honest failure) instead of letting it sit
    // forever. This is what makes the guarantee deterministic: every
    // queued message ends either delivered or visibly retracted.
    inboundSpool?.sweepEscalations((e, { postNotice }) => {
      const chat = e.msg.chatId
      const escThread =
        typeof e.msg.meta?.threadId === 'string' && e.msg.meta.threadId
          ? Number(e.msg.meta.threadId)
          : undefined
      const threadOpts = escThread != null ? { message_thread_id: escThread } : {}
      // Reap any "Queued — replying in #X" placeholder for this topic first:
      // the message is being declared undeliverable, so the queued-status must
      // not dangle beside the "couldn't deliver" notice (idempotent best-effort;
      // a normal turn-start/turn-end reaps far sooner — this is the 15-min edge).
      // Reaping happens for EVERY dropped entry; only the user-facing notice is
      // coalesced (postNotice), so a burst of undeliverable inbounds doesn't
      // leave dangling placeholders even when its notice is suppressed.
      reapQueuedStatus(chat, escThread)
      // Coalesced per chat by the spool's sliding window — a multi-restart
      // outage that re-ages a synthetic into the bound every 15 min posts ONE
      // notice, not one per cycle (the 2026-06-09 marko "please resend" spam).
      if (!postNotice) return
      void swallowingApiCall(
        () =>
          bot.api.sendMessage(
            chat,
            "⚠️ I couldn't deliver an earlier message to the agent after repeated retries (it survived restarts but the agent never picked it up). Please resend it.",
            { ...threadOpts },
          ),
        { chat_id: chat, verb: 'inbound-spool-escalation' },
      )
    })
  }, IDLE_DRAIN_INTERVAL_MS).unref()
}

// ─── Tool execution ──────────────────────────────────────────────────────

/** Allowlisted tool names that bridges may invoke via IPC. Prevents a rogue
 *  bridge from calling arbitrary functions by name. */
const ALLOWED_TOOLS = new Set([
  'reply', 'stream_reply', 'progress_update', 'react', 'download_attachment',
  'edit_message', 'send_typing', 'pin_message', 'delete_message',
  'forward_message', 'get_recent_messages',
  'send_checklist', 'update_checklist',
  'ask_user',
  'send_sticker', 'send_gif',
  'vault_request_save',
  'vault_request_access',
  'request_secret',
  'linear_agent_activity',
  'linear_create_issue',
  'linear_agent_setup',
])

async function executeToolCall(tool: string, args: Record<string, unknown>): Promise<unknown> {
  if (!ALLOWED_TOOLS.has(tool)) {
    throw new Error(`tool not allowed: ${tool}`)
  }
  switch (tool) {
    case 'reply':
      return executeReply(args)
    case 'stream_reply':
      return executeStreamReply(args)
    case 'progress_update':
      return executeProgressUpdate(args)
    case 'react':
      return executeReact(args)
    case 'download_attachment':
      return executeDownloadAttachment(args)
    case 'edit_message':
      return executeEditMessage(args)
    case 'send_typing':
      return executeSendTyping(args)
    case 'pin_message':
      return executePinMessage(args)
    case 'delete_message':
      return executeDeleteMessage(args)
    case 'forward_message':
      return executeForwardMessage(args)
    case 'get_recent_messages':
      return executeGetRecentMessages(args)
    case 'send_checklist':
      return executeSendChecklist(args)
    case 'update_checklist':
      return executeUpdateChecklist(args)
    case 'ask_user':
      return executeAskUser(args)
    case 'send_sticker':
      return executeSendSticker(args)
    case 'send_gif':
      return executeSendGif(args)
    case 'vault_request_save':
      return executeVaultRequestSave(args)
    case 'vault_request_access':
      return executeVaultRequestAccess(args)
    case 'request_secret':
      return executeRequestSecret(args)
    case 'linear_agent_activity':
      return executeLinearAgentActivity(args)
    case 'linear_create_issue':
      return executeLinearCreateIssue(args)
    case 'linear_agent_setup':
      return executeLinearAgentSetup(args)
    default:
      throw new Error(`unknown tool: ${tool}`)
  }
}

async function executeSendChecklist(args: Record<string, unknown>): Promise<{ content: Array<{ type: string; text: string }> }> {
  const chat_id = String(args.chat_id ?? '')
  if (!chat_id) throw new Error('send_checklist: chat_id is required')
  const title = args.title as string | undefined
  if (!title) throw new Error('send_checklist: title is required')
  const tasks = args.tasks as Array<{ text: string; done?: boolean }> | undefined
  if (!Array.isArray(tasks) || tasks.length === 0) throw new Error('send_checklist: tasks must be a non-empty array')
  const threadId = args.message_thread_id != null ? Number(args.message_thread_id) : undefined
  const replyTo = args.reply_to != null ? Number(args.reply_to) : undefined
  const protectContent = args.protect_content === true

  assertAllowedChat(chat_id)

  const sent = await rawSendChecklist({
    chat_id,
    title,
    tasks,
    ...(threadId != null ? { message_thread_id: threadId } : {}),
    ...(replyTo != null ? { reply_to_message_id: replyTo } : {}),
    ...(protectContent ? { protect_content: true } : {}),
  })

  process.stderr.write(`telegram gateway: send_checklist: sent chatId=${chat_id} messageId=${sent.message_id} tasks=${tasks.length}\n`)
  return { content: [{ type: 'text', text: `checklist sent (id: ${sent.message_id})` }] }
}

/**
 * Per-(agent,reason) cooldown for the Linear-auth-dead operator alert. The
 * triggering 401 recurs on every Linear call once the token expires, so
 * without a cooldown the operator would be paged on every capture/activity.
 * One alert per reason per window is enough to surface the action item.
 */
const linearAuthAlertLast = new Map<string, number>()
const LINEAR_AUTH_ALERT_COOLDOWN_MS = 6 * 60 * 60 * 1000

/**
 * Surface an un-healable Linear auth failure (no refresh bundle / revoked
 * refresh token) to the operator as a Telegram message — not just a gateway
 * log line. Deduped per (agent,reason) and gated by SWITCHROOM_LINEAR_AUTH_ALERT=0.
 * Best-effort: a failed send never affects the agent's turn.
 */
function notifyLinearAuthDead(info: { agent: string; reason: LinearAuthDeadReason; detail: string }): void {
  if (process.env.SWITCHROOM_LINEAR_AUTH_ALERT === '0') return
  const key = `${info.agent}:${info.reason}`
  const now = Date.now()
  const last = linearAuthAlertLast.get(key)
  if (last != null && now - last < LINEAR_AUTH_ALERT_COOLDOWN_MS) return
  void (async () => {
    try {
      const chatId = loadAccess().allowFrom[0]
      if (!chatId) return
      const threadId = topicForRecipient({
        recipientChatId: chatId,
        resolvedTopic: resolveAgentOutboundTopic({ kind: 'linear-auth' }) ?? chatThreadMap.get(chatId),
        supergroupChatId: resolveAgentSupergroupChatId(),
      })
      const text = buildLinearAuthDeadMessage(info.agent, info.reason)
      await swallowingApiCall(
        () =>
          // allow-raw-bot-api: wrapped in swallowingApiCall (retry policy)
          bot.api.sendRichMessage(chatId, richMessage(text), {
            ...(threadId != null ? { message_thread_id: threadId } : {}),
          }),
        { chat_id: chatId, verb: 'linearAuthDead' },
      )
      // Stamp the cooldown only after a successful send so a transient
      // Telegram failure doesn't burn the 6h window (the 401 recurs and will
      // retry the page on the next Linear call).
      linearAuthAlertLast.set(key, now)
      process.stderr.write(`telegram gateway: linear auth-dead alert sent agent=${info.agent} reason=${info.reason}\n`)
    } catch {
      /* best-effort */
    }
  })()
}

async function executeLinearAgentActivity(args: Record<string, unknown>): Promise<{ content: Array<{ type: string; text: string }> }> {
  return emitLinearAgentActivity(args, { onAuthUnrecoverable: notifyLinearAuthDead })
}

async function executeLinearCreateIssue(args: Record<string, unknown>): Promise<{ content: Array<{ type: string; text: string }> }> {
  return createLinearIssue(args, { onAuthUnrecoverable: notifyLinearAuthDead })
}

async function executeLinearAgentSetup(args: Record<string, unknown>): Promise<{ content: Array<{ type: string; text: string }> }> {
  return runLinearAgentSetup(args)
}

async function executeUpdateChecklist(args: Record<string, unknown>): Promise<{ content: Array<{ type: string; text: string }> }> {
  const chat_id = String(args.chat_id ?? '')
  if (!chat_id) throw new Error('update_checklist: chat_id is required')
  const message_id = args.message_id as string | undefined
  if (!message_id) throw new Error('update_checklist: message_id is required')
  const title = args.title as string | undefined
  const tasks = args.tasks as Array<{ id?: string; text?: string; done?: boolean }> | undefined

  assertAllowedChat(chat_id)

  await rawEditMessageChecklist({ chat_id, message_id, title, tasks })

  process.stderr.write(`telegram gateway: update_checklist: updated chatId=${chat_id} messageId=${message_id}\n`)
  return { content: [{ type: 'text', text: `checklist updated (id: ${message_id})` }] }
}

/**
 * Outbound secret scrub (#2044). The agent is trusted, but it can still
 * echo a secret it read from a file, env, or a not-yet-vaulted value into
 * a reply — and outbound text had no redaction at all. This masks any
 * detected secret in agent-authored text BEFORE it is logged (the stderr
 * previews), forwarded (sent to Telegram), or stored (recordOutbound).
 *
 * It runs the SAME `detectSecrets` engine as the inbound gate, so a
 * pattern added once (e.g. the Sanctum `<id>|<token>` shape, #2043) covers
 * both directions. Applied at the entry of every agent-free-text tool
 * (reply / stream_reply / edit_message), mutating the text in place so all
 * downstream consumers — voice scrub, dedup key, chunker, answer-stream
 * diffing, history record — see the masked value. This is the same
 * in-place-mutation contract the voice scrub already relies on, which
 * keeps the answer-stream's incremental edit diffing consistent (it always
 * compares redacted-against-redacted).
 */
function redactOutboundText(text: string, site: string): string {
  const masked = redact(text)
  if (masked !== text) {
    // Never log the secret — only that a mask fired, and where.
    process.stderr.write(`telegram gateway: outbound secret masked site=${site}\n`)
  }
  return masked
}

/** Default per-voice-note chunk size (chars). A long reply is split into
 *  sequential voice notes of roughly this size on sentence/paragraph
 *  boundaries. Only the OpenAI (cloud) engine still uses this — the kokoro
 *  sidecar now takes the whole reply in one call and returns a single note. */
const VOICE_OUT_DEFAULT_CHUNK_CHARS = 600

/** Hard ceiling for a single OpenAI TTS request. OpenAI's TTS input caps at
 *  4096 chars, so client-side chunks for that engine never exceed this; the
 *  reply is spoken across sequential notes when it's longer. (The kokoro path
 *  no longer chunks — the sidecar owns length and returns one file.) */
const VOICE_OUT_HARD_CHUNK_CAP = 4096

/**
 * On-demand voice-out (reply_mode='on-demand'). Instead of synthesizing at
 * reply time, the gateway appends a single "🔊 Listen" inline button carrying
 * a reserved `voice:<token>` callback_data; audio is synthesized + sent only
 * when the user taps it. This keeps the voice pipeline subscription-honest and
 * visible — zero GPU/sidecar work happens behind the user's back.
 *
 * We cache the (speech-normalized text, voice, speed) needed to synthesize by
 * TOKEN, not message_id, because the message_id is not known at send time.
 * Bounded LRU with a TTL so a stale button (tapped an hour later) degrades to
 * a graceful "expired" toast rather than pinning reply text in memory forever.
 */
// Persist the Listen-token cache under STATE_DIR (= /state/agent/telegram in
// prod, a volume that survives container recreation). Without this the Map was
// wiped on every gateway restart, so a 🔊 Listen button tapped on a message
// sent before the restart degraded to "Voice expired". The same TTL + LRU cap
// still applies; expired entries are dropped on load.
const voiceOnDemandCache = new VoiceOnDemandCache({
  persistPath: join(STATE_DIR, 'voice-ondemand.json'),
})

// ─── Eager voice pre-synthesis (#2763) ─────────────────────────────────────
// Whenever a reply becomes Listen-eligible (a voiceOnDemandCache entry is
// persisted alongside the Listen button), ALSO synthesize the audio in the
// background via the LOCAL sidecar and park it on disk, so the 🔊 Listen tap
// attaches the pre-made file instantly instead of waiting on the GPU. Local
// engine only (kokoro — zero token/dollar cost); the openai cloud engine
// never pre-synthesizes. Strictly off the reply critical path: jobs drain
// through a bounded FIFO (concurrency 1, drop-oldest past the cap) and every
// failure is swallowed — the tap just falls back to the lazy synth path.
// Kill switch: SWITCHROOM_DISABLE_EAGER_VOICE=1 (the sweep still runs so old
// files age out).
const VOICE_CACHE_DIR = join(STATE_DIR, 'voice-cache')

const voicePreSynthQueue = new PreSynthQueue({
  runJob: async (job) => {
    const sidecarToken = await materializeSidecarToken()
    if (!sidecarToken) return // sidecar unavailable — lazy path will retry on tap
    const result = await synthesizeViaSidecar({
      token: sidecarToken,
      // Same deterministic normalization the lazy Listen path applies —
      // job.text is normalizeForSpeech(reply); normalizeForTts is the #2760
      // L1 pass on top.
      text: normalizeForTts(job.text),
      voice: job.voice,
      speed: job.speed,
    })
    if (!result.ok) {
      process.stderr.write(
        `telegram gateway: voice-presynth: sidecar synthesis failed token=${job.token} reason=${result.reason}\n`,
      )
      return
    }
    const filePath = writeVoiceCacheFile(VOICE_CACHE_DIR, job.token, result.audio)
    voiceOnDemandCache.setFilePath(job.token, filePath)
    process.stderr.write(
      `telegram gateway: voice-presynth: cached ${result.audio.length} bytes at ${filePath} ` +
        `(${result.durationMs}ms, backlog=${voicePreSynthQueue.size})\n`,
    )
  },
})

/** Rolling 7-day TTL + 500MB size-budget sweep over VOICE_CACHE_DIR. Runs at
 *  boot and hourly; ALWAYS runs (even under the eager-voice kill switch) so
 *  previously written files age out. Crash-safe: missing dir/files tolerated. */
function sweepVoiceCache(): void {
  try {
    const result = sweepVoiceCacheDir({ dir: VOICE_CACHE_DIR })
    if (result.deletedTokens.length > 0) {
      voiceOnDemandCache.prune(result.deletedTokens)
      process.stderr.write(
        `telegram gateway: voice-presynth: sweep removed ${result.deletedTokens.length} file(s), ` +
          `${result.remainingBytes} bytes remain\n`,
      )
    }
  } catch (err) {
    // Defence in depth — sweepVoiceCacheDir is already per-file crash-safe.
    process.stderr.write(`telegram gateway: voice-presynth: sweep failed: ${String(err)}\n`)
  }
}

if (!STATIC) {
  sweepVoiceCache() // boot sweep — covers a died timer / long downtime
  setInterval(sweepVoiceCache, VOICE_SWEEP_INTERVAL_MS).unref()
}

type VoiceOutAccess = NonNullable<Access['voice_out']>

/**
 * Resolve whether outbound TTS is active for this reply, and how
 * (engine + reply_mode + the plain-text TTS chunks). PR-C2.
 *
 * Mirrors the voice-IN engine-resolution precedence (message:voice
 * handler): the compose-injected SWITCHROOM_VOICE_ENGINE verdict gates the
 * local 'kokoro' engine, exactly like the STT sidecar. The 'openai' engine
 * is an honest-exception cloud path gated on an api_key vault ref — it does
 * NOT require a local verdict.
 *
 * Returns null when voice-out is off / not applicable; otherwise a plan the
 * caller acts on. `ttsChunks` is speech-normalized plain text (markdown and
 * TTS-mispronounced symbols removed — see normalizeForSpeech).
 *
 * ONE voice note per response: the kokoro (local sidecar) path now sends the
 * WHOLE normalized reply to `/tts` in a SINGLE call — the sidecar chunks +
 * concatenates internally on the GPU and returns a single ogg/opus file — so
 * `ttsChunks` is a single element for kokoro. `max_chars` is no longer a hard
 * client-side splitter for kokoro; it's retired for that path (the sidecar
 * owns length). The openai (cloud) engine keeps client-side chunking because
 * OpenAI's TTS input has its own hard cap; each chunk is one voice note.
 */
function resolveVoiceOutPlan(
  voiceOut: VoiceOutAccess | undefined,
  replyText: string,
): {
  engine: 'kokoro' | 'openai'
  voice?: string
  speed: number
  apiKeyRef?: string
  replyMode: 'voice+text' | 'voice-only' | 'on-demand'
  ttsChunks: string[]
} | null {
  if (voiceOut?.enabled !== true) return null

  const engine = voiceOut.engine ?? 'kokoro'

  // Engine gating mirrors the voice-in handler precedence: the
  // compose-injected env wins, then the persisted host-capabilities file,
  // then a fail-safe 'cloud'. The in-container ~/.switchroom is a read-only
  // view that does NOT carry host-capabilities.json, so the env is
  // load-bearing in-fleet (see message:voice). Kokoro requires 'local';
  // openai requires a resolvable api_key.
  if (engine === 'kokoro') {
    const envVoiceEngine = process.env.SWITCHROOM_VOICE_ENGINE
    const voiceEngine: VoiceEngine =
      envVoiceEngine === 'local' || envVoiceEngine === 'cloud'
        ? envVoiceEngine
        : loadHostCapabilities()?.voice.engine ?? 'cloud'
    if (voiceEngine !== 'local') return null
  }

  // Speech-normalized TTS input: strip markdown AND translate/drop the
  // symbols TTS mispronounces (~, backticks, arrows, tables, code fences,
  // link URLs) REGARDLESS of mode so the engine reads clean prose. Applied
  // for BOTH engines — the older partial stripMarkdown pass leaked `~`,
  // code fences and arrows.
  const ttsText = normalizeForSpeech(replyText)
  if (ttsText.length === 0) return null

  // ONE voice note for kokoro: the sidecar accepts arbitrarily long text and
  // returns a single concatenated ogg/opus file, so we send the whole reply
  // in one call — no client-side splitting, no multi-sendVoice. `max_chars`
  // is retired as a hard splitter here.
  //
  // OpenAI still needs client-side chunking (its TTS input has a hard cap),
  // so for that engine we split at the engine cap; each chunk is one note.
  let ttsChunks: string[]
  if (engine === 'kokoro') {
    ttsChunks = [ttsText]
  } else {
    const chunkChars = Math.min(
      voiceOut.max_chars ?? VOICE_OUT_DEFAULT_CHUNK_CHARS,
      VOICE_OUT_HARD_CHUNK_CAP,
    )
    ttsChunks = chunkTtsText(ttsText, chunkChars)
  }
  if (ttsChunks.length === 0) return null

  // Kokoro playback speed: default 1.1 (fleet default) when unset, clamped to
  // 0.5–2.0. Threaded into the /tts body by synthesizeVoiceOut. The OpenAI
  // path ignores it.
  const speed = clampTtsSpeed(voiceOut.speed, VOICE_OUT_DEFAULT_SPEED)

  return {
    engine,
    voice: voiceOut.voice,
    speed,
    apiKeyRef: voiceOut.api_key,
    replyMode: voiceOut.reply_mode ?? 'voice+text',
    ttsChunks,
  }
}

/**
 * Synthesize `ttsText` into OGG/Opus bytes via the configured engine.
 * Best-effort: returns null on ANY failure (logged to stderr), never
 * throws. The caller treats null as "voice unavailable, fall back to
 * text". PR-C2.
 */
async function synthesizeVoiceOut(plan: {
  engine: 'kokoro' | 'openai'
  voice?: string
  speed?: number
  apiKeyRef?: string
  ttsText: string
}): Promise<Uint8Array | null> {
  try {
    // #2760 Phase 1: deterministic L1 TTS normalization, applied at the
    // single choke point where every engine's request body is built.
    // On by default; kill switch: SWITCHROOM_DISABLE_TTS_NORMALIZE=1.
    const ttsText = normalizeForTts(plan.ttsText)
    if (plan.engine === 'kokoro') {
      const token = await materializeSidecarToken()
      if (!token) return null // materializeSidecarToken already logged why.
      const result = await synthesizeViaSidecar({
        token,
        text: ttsText,
        voice: plan.voice,
        speed: plan.speed,
      })
      if (!result.ok) {
        process.stderr.write(
          `telegram gateway: voice-out: local sidecar synthesis failed reason=${result.reason}` +
            (result.detail ? ` detail=${JSON.stringify(result.detail).slice(0, 100)}` : '') +
            '\n',
        )
        return null
      }
      process.stderr.write(
        `telegram gateway: voice-out: local sidecar synthesized ${result.audio.length} bytes in ${result.durationMs}ms ` +
          `voice=${result.voice ?? '?'} audio_s=${result.audioSeconds ?? '?'} chars=${plan.ttsText.length}\n`,
      )
      return result.audio
    }

    // engine === 'openai' — honest-exception cloud path.
    const apiKey = await materializeVoiceKey({ apiKeyRef: plan.apiKeyRef })
    if (!apiKey) return null // materializeVoiceKey already logged why.
    const result = await synthesizeViaOpenAi({
      apiKey,
      text: ttsText,
      voice: plan.voice,
    })
    if (!result.ok) {
      process.stderr.write(
        `telegram gateway: voice-out: openai synthesis failed reason=${result.reason}` +
          (result.detail ? ` detail=${JSON.stringify(result.detail).slice(0, 100)}` : '') +
          '\n',
      )
      return null
    }
    process.stderr.write(
      `telegram gateway: voice-out: openai synthesized ${result.audio.length} bytes in ${result.durationMs}ms ` +
        `voice=${result.voice} chars=${plan.ttsText.length}\n`,
    )
    return result.audio
  } catch (err) {
    // Defence in depth: the synth helpers never throw, but the vault
    // materialize calls might. Voice is best-effort — swallow + fall back.
    process.stderr.write(
      `telegram gateway: voice-out: synthesis threw (non-fatal): ${err instanceof Error ? err.message : String(err)}\n`,
    )
    return null
  }
}

async function executeReply(args: Record<string, unknown>): Promise<{ content: Array<{ type: string; text: string }> }> {
  // #1664 — pin the turn this reply belongs to at entry. The
  // finalAnswerDelivered write near the end of this function runs after
  // several awaits; turn-pinning (the #1067 pattern used across the
  // gateway) keeps the write attributed to THIS turn rather than reading
  // module-scope currentTurn, which a future refactor could let roll over
  // mid-call.
  const turn = currentTurn
  const _rawChatId = String(args.chat_id ?? '')
  if (!_rawChatId) throw new Error('reply: chat_id is required')
  // Non-Claude models (e.g. Gemini via LiteLLM sr-* routing) sometimes pass a
  // chat_id that is not in the allowlist — either an int/string mismatch, or
  // the model echoing the wrong identifier from context. When the raw value
  // fails the allowlist check, fall back to the active (or last-known) turn's
  // validated sessionChatId so the reply still lands correctly.
  // Tier 1: live turn (currentTurn was non-null at reply entry).
  // Tier 2: last-known turn (survives silence poke — Bug D fix; currentTurn is
  //   null because clearTurnStarted fired ≥5 min of model silence, but the model
  //   finally called reply after the poke).
  const chat_id = (() => {
    const resolved = resolveChatIdFallback(
      _rawChatId,
      loadAccess(),
      turn?.sessionChatId,
      lastActiveTurnChatId,
      turn != null,
    )
    if (resolved.tier !== 'raw') {
      process.stderr.write(
        `telegram gateway: reply: model passed chat_id "${_rawChatId}" (not allowlisted) — ` +
          `routing to ${resolved.tier} turn chat "${resolved.chatId}"\n`,
      )
    }
    return resolved.chatId // raw tier → let assertAllowedChat throw the human-readable error
  })()
  const rawText = args.text as string | undefined
  if (rawText == null || rawText === '') throw new Error('reply: text is required and cannot be empty')
  // Repair LLM JSON-escape bungles, then promote lone prose paragraph breaks
  // into GFM hard breaks so the rich path doesn't collapse them (lists/tables/
  // code are left untouched — see normalizeParagraphBreaks).
  let text = normalizeParagraphBreaks(repairEscapedWhitespace(rawText))
  // Outbound secret scrub (#2044): mask any secret the agent echoed BEFORE
  // the stderr preview below, the dedup key, the send, and the history
  // record. Mutates `text` so every downstream consumer sees the masked
  // value, exactly like the voice scrub that follows. Runs BEFORE the
  // punctuation/bold normalizers so a secret containing an em-dash or `**`
  // is matched literally by the redactor before any mutation.
  text = redactOutboundText(text, 'reply')
  // Fleet-wide consistent formatting: normalize dashes/bullets and trip the
  // over-bold guard deterministically, on code-masked text (same contract on
  // reply / edit / stream paths). Runs before scrubVoice below so dashes get
  // the comma treatment on every path; scrubVoice's dash telemetry
  // (voice_scrub_applied) drops to ~zero here as a result — deliberate.
  text = stripExcessBold(normalizePunctuation(text))
  // Voice scrub (#1683): replace em / en dashes with commas / periods.
  // Runs BEFORE outboundDedup so retries see the scrubbed key, and on the
  // raw markdown text (the scrubber does its own code-region parking so
  // dashes inside fences/inline code are preserved). Kill switch:
  // `SWITCHROOM_DISABLE_VOICE_SCRUB=1`.
  {
    const scrub = scrubVoice(text)
    if (scrub.replaced > 0) {
      text = scrub.scrubbed
      emitRuntimeMetric({
        kind: 'voice_scrub_applied',
        chatKey: statusKey(chat_id, args.message_thread_id != null
          ? Number(args.message_thread_id) : undefined),
        replaced: scrub.replaced,
        site: 'reply',
      })
    }
  }
  process.stderr.write(`telegram channel: reply: invoked chatId=${chat_id} charCount=${text.length} preview=${JSON.stringify(text.slice(0, 80))}\n`)
  // #2527: emit time_to_first_text_reply_ms on the FIRST text reply of each
  // turn so operators can see how long users waited for any visible output.
  // Only fires once per turn (firstTextReplyLogged guards the repeat).
  if (turn != null) {
    const threadId = args.message_thread_id != null ? Number(args.message_thread_id) : undefined
    const replyKey = statusKey(chat_id, threadId)
    if (!firstTextReplyLogged.has(replyKey)) {
      firstTextReplyLogged.add(replyKey)
      logStreamingEvent({
        kind: 'turn_reply_timing',
        chatId: chat_id,
        threadId,
        turnId: turn.turnId,
        timeToFirstTextReplyMs: Date.now() - turn.gatewayReceiveAt,
      })
    }
  }

  // #546 dedup check: was this content just sent via turn-flush or
  // a sibling reply path? Skip the actual send and return a
  // plausible tool result so claude-code's retry loop closes
  // cleanly. NOTE: only fires when content matches; legitimate
  // late-replies with different content sail through.
  {
    const replyThreadId = args.message_thread_id != null ? Number(args.message_thread_id) : undefined
    const dup = outboundDedup.check(chat_id, replyThreadId, text, Date.now(), currentTurn?.registryKey ?? null)
    if (dup != null) {
      process.stderr.write(
        `telegram gateway: reply: deduped (#546) chatId=${chat_id} ` +
        `ageMs=${dup.ageMs} preview=${JSON.stringify(dup.preview)}\n`,
      )
      return { content: [{ type: 'text', text: 'sent (deduped — same content sent via earlier path)' }] }
    }
  }

  const files = (args.files as string[] | undefined) ?? []
  const quoteOptIn = args.quote !== false
  let reply_to = args.reply_to != null ? Number(args.reply_to) : undefined
  const protectContent = args.protect_content === true
  const quoteText = args.quote_text as string | undefined
  const access = loadAccess()
  // Outbound TTS plan (PR-C2). Resolved once here (engine gating + mode +
  // plain-text TTS input); synthesis happens just before the send so a
  // voice-only reply can suppress the text chunk loop on success. Voice is
  // fully best-effort — every failure below falls back to the text reply.
  const voiceOutPlan = resolveVoiceOutPlan(access.voice_out, text)
  const configParseMode = access.parseMode ?? 'html'
  const format = (args.format as string | undefined) ?? configParseMode
  const disableLinkPreview = args.disable_web_page_preview != null
    ? Boolean(args.disable_web_page_preview)
    : (access.disableLinkPreview ?? true)
  // #1122 conversational pacing: mid-turn updates pass disable_notification:true
  // so only the final answer pings the device. Default false (pings) so
  // existing call-sites and the typical "final answer" reply keep their
  // current behaviour without an explicit flag.
  let disableNotification = args.disable_notification === true
  // #2527/#1664 — the over-ping safety net below may downgrade
  // `disableNotification` ping→silent for ANTI-SPAM (one ping per turn). That
  // delivery-channel decision must NOT pollute final-answer CLASSIFICATION: a
  // final answer the model intended to ping is STILL the final answer even when
  // the framework silences the actual ping. Classify on the model's original
  // intent (what executeStreamReply already does), so an over-ping-silenced
  // final answer sets finalAnswerDelivered=true — fixing both a spurious
  // silent-end re-prompt and a false 'undelivered' (😐) terminal reaction.
  const modelDisableNotification = args.disable_notification === true

  // #1675 over-ping safety net. The conversational-pacing contract
  // (`reference/rfcs/conversational-pacing.md` beat 5) says EXACTLY ONE
  // device ping per turn — the final answer. The model sometimes
  // violates this by sending a substantive answer pinged + a wrap-up
  // ("Delivered all three steps…", "Sent.", or meta-narration) ALSO
  // pinged. Both messages then fire notifications. The fleet UAT on
  // 2026-05-23 reproduced this (Step 3 + Delivered both pinged, two
  // beeps for a turn that should have produced one). Framework owns
  // the safety net: once the turn has emitted ONE pinged reply, every
  // subsequent reply call in the same turn auto-downgrades to silent
  // (disable_notification: true). Model intent ("I want this loud")
  // is honoured for the first ping; subsequent pings are demoted with
  // a stderr log so operators can see the safety net engage.
  //
  // The slot is claimed BEFORE the actual send to keep the logic
  // sequential — a send that fails part-way leaves firstPingAt set
  // and subsequent pings would be silenced. Acceptable trade-off (a
  // failed first ping is an edge case; the alternative — claim after
  // send — races concurrent reply calls).
  // Tracks whether the over-ping safety net coerced this reply
  // from ping→silent. Threaded into the silent-anchor predicate
  // below: a demoted final-answer reply must NOT merge into the
  // silent preamble bubble; it lands as a fresh silent bubble so
  // the user can still find it (see #1674 / silent-anchor follow-up).
  let wasOverPingSuppressed = false
  {
    const turn = currentTurn
    if (turn != null) {
      const now = Date.now()
      // Notification ownership (R8 / PR-2): on the `reply` path,
      // substantiveness is purely the ≥200-char (or `done`) backstop —
      // `isSubstantiveFinalReply` is `done === true || text.length >= 200`
      // and ignores the notification flag entirely. `reply` carries no
      // `done`, so it reduces to the ≥200-char length test. We still pass
      // `modelDisableNotification` (the MODEL's original intent, not the
      // possibly-downgraded `disableNotification`) to mirror the #2533
      // final-answer decoupling call shape, but that arg does NOT
      // participate in classification here — it is inert on this path.
      const replySubstantive = isSubstantiveFinalReply({
        text: rawText,
        disableNotification: modelDisableNotification,
      })
      // PR-4c: the over-ping DECISION relocates into the emission-authority
      // façade, behind the kill-switch (default OFF), the same structural way
      // PR-4b moved the OPEN gate. `decideOverPing` is already pure, so PR-4c
      // extracts NOTHING new — it relocates the *call* into the façade's enabled
      // branch and keeps the *effects* (stderr, metric, the atomic
      // `firstPingAt`/`firstPingWasSubstantive` pair-set, the
      // `disableNotification`/`wasOverPingSuppressed` outer-scope writes) HERE,
      // parameterized by the decision the façade hands back via `applyDecision`.
      //
      //  - Disabled branch runs `disabledOverPing()` — its own LITERAL
      //    `decideOverPing(...)` call + the full effects block, VERBATIM from
      //    PR-4b-base (the disabled-path-is-byte-identical proof).
      //  - Enabled branch: the façade computes the decision and hands it to
      //    `applyOverPingDecision(decision)`, which performs the IDENTICAL
      //    effects. Same pure inputs ⇒ same decision ⇒ flag-ON ≡ flag-OFF ≡ base.
      //
      // The effects block is shared between both thunks by closing over `decision`
      // — but the disabled thunk computes it via its OWN literal `decideOverPing(`
      // first, so the disabled path never depends on the façade for the decision.
      const applyOverPingDecision = (decision: OverPingDecision): void => {
        if (decision.suppress) {
          process.stderr.write(
            `telegram gateway: reply over-ping safety net — ` +
            `downgrading disable_notification:false → true ` +
            `(chat=${chat_id} thread=${args.message_thread_id ?? '-'} ` +
            `firstPingAt=${turn.firstPingAt} sinceFirstPing_ms=${decision.sinceFirstPingMs})\n`,
          )
          // Observability: surface to the unified runtime-metrics
          // fan-out so the cadence dashboard can track fleet-wide
          // over-ping rate (leading indicator of model pacing drift).
          emitRuntimeMetric({
            kind: 'over_ping_suppressed',
            key: statusKey(chat_id, args.message_thread_id != null
              ? Number(args.message_thread_id) : undefined),
            sinceFirstPingMs: decision.sinceFirstPingMs ?? 0,
          })
          disableNotification = true
          wasOverPingSuppressed = true
        } else if (decision.claimSlot) {
          // Claim (first ping) OR upgrade (substantive answer pinging over an
          // ack's slot). Set firstPingAt AND firstPingWasSubstantive ATOMICALLY
          // (no await between) so a racing second reply reads a consistent pair.
          turn.firstPingAt = now
          turn.firstPingWasSubstantive = replySubstantive
          if (decision.upgrade) {
            process.stderr.write(
              `telegram gateway: reply over-ping safety net — ` +
              `UPGRADE: substantive answer pings over an ack's slot ` +
              `(chat=${chat_id} thread=${args.message_thread_id ?? '-'})\n`,
            )
          }
        }
      }
      emissionAuthorityFor(turn).claimOrDowngradePing(
        { modelRequestedPing: !disableNotification, substantive: replySubstantive },
        {
          firstPingAt: turn.firstPingAt,
          firstPingWasSubstantive: turn.firstPingWasSubstantive,
          nowMs: now,
        },
        applyOverPingDecision,
        () => {
          // Disabled-path: literal `decideOverPing(` + effects, VERBATIM base.
          const decision = decideOverPing({
            modelRequestedPing: !disableNotification,
            firstPingAt: turn.firstPingAt,
            substantive: replySubstantive,
            firstPingWasSubstantive: turn.firstPingWasSubstantive,
            nowMs: now,
          })
          applyOverPingDecision(decision)
        },
      )
    }
  }

  // Telegraph publish (#579). When the reply text is long enough AND
  // the agent has telegraph enabled in access.json, publish to
  // Telegraph + replace the local text with a single-message link.
  // Telegram renders the link as a native Instant View card.
  // Failure paths fall through to normal HTML chunking, so a flaky
  // Telegraph backend never breaks the reply path.
  const tg = access.telegraph
  const tgThreshold = tg?.threshold ?? 3000
  if (tg?.enabled && files.length === 0 && text.length > tgThreshold) {
    const agentSlug = process.env.SWITCHROOM_AGENT_NAME ?? 'switchroom-agent'
    const shortName = tg.short_name ?? agentSlug
    const url = await publishToTelegraph(text, shortName, tg.author_name)
    if (url != null) {
      const title = deriveTelegraphTitle(text)
      // Replace the local text with a one-line link. The first line
      // is the chosen title (so the user sees the topic at a glance);
      // the second line is the URL Telegram will Instant-View.
      text = `**${escapeMarkdown(title)}**\n${url}`
    }
    // url null → fall through and chunk; the user still gets the
    // long reply, just split across messages.
  }

  // Single rich-markdown path (#2669). The only fork is `format:'text'`,
  // a literal/no-markdown send: the body bypasses the rich parser entirely
  // (plain `sendMessage`, no rich wrapper). Everything else — the default —
  // ships the raw GFM markdown via `sendRichMessage`. `effectiveText` is the
  // raw text either way (no HTML/MarkdownV2 rendering happens here anymore).
  const literalText = format === 'text'
  // Paragraph-spacing fix (rich-message regression after #2669). The rich GFM
  // renderer collapses a `\n\n` gap TIGHT, so multi-paragraph replies render
  // jammed together — unlike the old HTML path. Inject a visible blank-line
  // spacer into prose `\n\n` gaps on the rich path only. The literal
  // (`format:'text'`) path must stay byte-exact, so it is left untouched.
  const effectiveText: string = literalText ? text : addParagraphSpacers(text)

  assertAllowedChat(chat_id)

  // Thread resolution precedence (ANSWER path, component 3 — turn-origin
  // routing): (1) explicit message_thread_id the model passed; else
  // (2) the ORIGIN turn's thread — the turn that OWNS this reply, matched
  // by origin_turn_id (the meta field the model echoes back). This is
  // authoritative even after `currentTurn` has flipped to a successor (the
  // Brevo→Meta late-reply bug). Else (3) the live turn's thread (legacy
  // #1664 fallback when no origin turn is resolvable). Answer paths
  // DELIBERATELY do NOT fall through to chatThreadMap last-seen — that
  // heuristic is what mis-routed a late reply to whichever topic most
  // recently received a message. DM: every tier is undefined → unchanged.
  // Kill switch off → exact legacy resolveThreadId precedence.
  // Hoist the resolved origin turn so the obligation-close path (below) can
  // pass it into resolveCloseTarget as routedOriginId, closing re-presented
  // obligations even when the model omitted origin_turn_id (Fix 1/2).
  let replyRoutedOriginTurn: CurrentTurn | null = null
  let threadId: number | undefined
  if (TURN_ORIGIN_ROUTING_ENABLED) {
    const explicit = args.message_thread_id != null ? Number(args.message_thread_id) : undefined
    // Origin precedence: model echo first (authoritative), then the
    // framework-owned quoted message_id (deterministic, no model thread
    // assertion) as a fallback when the model omitted the echo.
    const echoedTurn = findTurnByOriginId(args.origin_turn_id as string | undefined)
    const quotedTurn = echoedTurn == null ? findTurnByQuotedMessageId(chat_id, args.reply_to) : null
    const originTurn = echoedTurn ?? quotedTurn
    replyRoutedOriginTurn = originTurn ?? null
    threadId = resolveAnswerThreadWithLog(
      chat_id,
      Number.isFinite(explicit as number) ? (explicit as number) : undefined,
      originTurn,
      originTurn == null ? null : echoedTurn != null ? 'echo' : 'quoted',
      turn,
      'reply',
    )
  } else {
    threadId = resolveThreadId(
      chat_id,
      (args.message_thread_id as string | undefined) ??
        (turn?.sessionThreadId != null ? turn.sessionThreadId : undefined),
    )
  }

  if (reply_to == null && quoteOptIn && HISTORY_ENABLED) {
    try {
      const latest = getLatestInboundMessageId(chat_id, threadId ?? null)
      if (latest != null) reply_to = latest
    } catch (err) {
      process.stderr.write(`telegram gateway: quote-reply lookup failed: ${(err as Error).message}\n`)
    }
  }

  for (const f of files) {
    assertSendable(f)
    const st = statSync(f)
    if (st.size > MAX_ATTACHMENT_BYTES) {
      throw new Error(`file too large: ${f} (${(st.size / 1024 / 1024).toFixed(1)}MB, max 50MB)`)
    }
  }

  const limit = Math.max(1, Math.min(access.textChunkLimit ?? RICH_MESSAGE_MAX_CHARS, MAX_CHUNK_LIMIT))
  const replyMode = access.replyToMode ?? 'first'
  const chunks = literalText
    ? chunk(effectiveText, limit, access.chunkMode ?? 'length')
    : splitMarkdownChunks(effectiveText, limit)
  const sentIds: number[] = []

  // Outbound TTS synthesis (PR-C2). Done BEFORE the text send so a
  // voice-only reply can suppress the text chunks on success. ONE voice note
  // per response for the kokoro path (ttsChunks is a single element — the
  // whole normalized reply — synthesized in one /tts call). The OpenAI path
  // may still produce several ordered notes (one per chunk) because of its
  // input cap. Ken is often on a bike/driving and can't read the screen, so
  // the full answer must be SPOKEN. Best-effort: a chunk that fails to
  // synthesize is skipped; if NOTHING synthesizes the text path proceeds
  // unchanged so the answer is never dropped.
  // on-demand is a LOCAL-engine (kokoro) feature only: the tap handler
  // synthesizes via the local sidecar, so a Listen button is only meaningful
  // when the resolved engine is kokoro. resolveVoiceOutPlan already gated the
  // local host verdict for kokoro, so engine==='kokoro' here implies the
  // sidecar is available. For engine==='openai' + reply_mode='on-demand' we do
  // NOT inject a button (its taps would dead-end on the local sidecar) — we
  // fall through to the normal immediate-synth path so the openai reply behaves
  // exactly like a normal openai voice reply.
  const useOnDemandButton =
    voiceOutPlan != null &&
    voiceOutPlan.replyMode === 'on-demand' &&
    voiceOutPlan.engine === 'kokoro'

  const voiceOggs: Uint8Array[] = []
  // Skip reply-time synthesis ONLY when we're actually deferring to a Listen
  // button (kokoro on-demand). An openai on-demand config still synthesizes
  // immediately below.
  if (voiceOutPlan != null && !useOnDemandButton) {
    for (const chunkText of voiceOutPlan.ttsChunks) {
      const ogg = await synthesizeVoiceOut({
        engine: voiceOutPlan.engine,
        voice: voiceOutPlan.voice,
        speed: voiceOutPlan.speed,
        apiKeyRef: voiceOutPlan.apiKeyRef,
        ttsText: chunkText,
      })
      // Skip a failed chunk but keep going — a partial spoken answer still
      // beats silence; full-fail (no oggs at all) falls back to text below.
      if (ogg != null) voiceOggs.push(ogg)
    }
    if (voiceOggs.length < voiceOutPlan.ttsChunks.length) {
      process.stderr.write(
        `telegram gateway: voice-out: synthesized ${voiceOggs.length}/${voiceOutPlan.ttsChunks.length} voice-note chunk(s)\n`,
      )
    }
  }
  // Suppress the text body ONLY when voice-only AND we synthesized the FULL
  // set of chunks (every part of the answer is spoken). A partial or total
  // synthesis failure leaves the text path running so the answer still
  // lands in full — never drop the user's answer silently.
  const suppressText =
    voiceOutPlan?.replyMode === 'voice-only' &&
    voiceOutPlan.ttsChunks.length > 0 &&
    voiceOggs.length === voiceOutPlan.ttsChunks.length

  // #271: validate inline_keyboard and namespace any callback_data with
  // the `agent:` prefix so the gateway's callback_query dispatcher can
  // round-trip taps back to this agent without colliding with
  // infrastructure prefixes (auth:/op:/vd:/vg:/aq:/perm:). URL buttons
  // pass through unchanged. Attached to the LAST chunk only so buttons
  // appear on the final visible message.
  let replyMarkup: { inline_keyboard: AnyButton[][] } | undefined
  let replyButtonMeta: Map<string, AgentButtonMeta> | undefined
  const rawKeyboard = args.inline_keyboard as AnyButton[][] | undefined
  if (rawKeyboard != null) {
    const validationErrors = validateInlineKeyboard(rawKeyboard)
    if (validationErrors.length > 0) {
      const summary = validationErrors
        .map((e) => `${e.path}.${e.field}: ${e.reason}`)
        .join('; ')
      throw new Error(`inline_keyboard validation failed: ${summary}`)
    }
    replyButtonMeta = extractAgentButtonMeta(rawKeyboard)
    replyMarkup = { inline_keyboard: wrapAgentCallbacks(rawKeyboard) }
  }

  // on-demand voice: append a single '🔊 Listen' button that synthesizes the
  // spoken reply only when tapped. The button carries a RAW `voice:<token>`
  // callback_data (NOT wrapped with the agent: prefix) so the dispatcher
  // handles it internally and never routes it to the agent as an inbound.
  //
  // Collision gate: inject ONLY when the reply carries no agent-authored
  // buttons. If the agent supplied its own keyboard, the callback dispatcher's
  // single_use strip (keyboardIsSingleUse) governs that whole message; adding
  // a foreign single_use:false button would flip that message to a mixed
  // keyboard and defeat the agent's double-fire protection. Keep it simple —
  // agent buttons present → skip the Listen button for this message.
  //
  // useOnDemandButton already gates on engine==='kokoro': an openai on-demand
  // config never reaches here (it synthesized immediately above), so a Listen
  // button is never minted for an engine whose taps would dead-end on the
  // local sidecar.
  if (
    useOnDemandButton &&
    voiceOutPlan!.ttsChunks.length > 0 &&
    voiceOutPlan!.ttsChunks[0]!.length > 0
  ) {
    if (!mayInjectListenButton(rawKeyboard)) {
      process.stderr.write(
        'telegram gateway: voice-out on-demand: agent supplied inline_keyboard — skipping Listen button (single_use collision gate)\n',
      )
    } else {
      // Token is intentionally GLOBAL (not chat-keyed): under the single-tenant
      // invariant the operator is the only authorized sender across all chats,
      // and the tap handler re-checks access.allowFrom before synthesizing, so
      // a token needs no per-chat scoping to be safe.
      const token = mintVoiceOnDemandToken()
      voiceOnDemandCache.put(token, {
        // ttsChunks[0] is already normalizeForSpeech(reply) (kokoro path).
        text: voiceOutPlan.ttsChunks[0]!,
        ...(voiceOutPlan.voice != null ? { voice: voiceOutPlan.voice } : {}),
        speed: voiceOutPlan.speed,
      })
      // The keyboard stays after the tap (never stripped) so it can be
      // replayed. The gate above guarantees this is the ONLY button on the
      // message, so keeping it is safe (no agent buttons to protect).
      replyMarkup = buildListenKeyboard(token)
      // #2763 eager pre-synthesis: kick a background synth of the same
      // payload so the Listen tap attaches the pre-made file instantly.
      // Local-engine only (useOnDemandButton already gates engine==='kokoro'
      // — the cloud engine never eager-synthesizes). enqueue() is a
      // synchronous array push; the drain is deferred + async and never
      // awaited here, so the text sends below are never delayed and a synth
      // failure can never affect message delivery (the tap just falls back
      // to the lazy path).
      if (eagerVoiceEnabled()) {
        voicePreSynthQueue.enqueue({
          token,
          text: voiceOutPlan.ttsChunks[0]!,
          ...(voiceOutPlan.voice != null ? { voice: voiceOutPlan.voice } : {}),
          speed: voiceOutPlan.speed,
        })
      }
    }
  }

  const replySKey = streamKey(chat_id, threadId)
  suppressPtyPreview.add(replySKey)
  let previewMessageId: number | null = null
  const openStream = activeDraftStreams.get(replySKey)
  if (openStream && !openStream.isFinal()) {
    await openStream.finalize().catch(() => {})
    previewMessageId = openStream.getMessageId()
    activeDraftStreams.delete(replySKey)
    lastPtyPreviewByChat.delete(replySKey)
  }

  // Pre-alloc placeholder consumption removed in #553 PR 5 — the
  // gateway no longer pre-allocates a draft on inbound, so reply tools
  // simply render fresh. The 👀 reaction (#568) and typing indicator
  // (#585) provide the visual gap that the placeholder used to fill.

  const deleteStalePreview = async (id: number): Promise<void> => {
    // #1075: operates on a message in a (possibly-deleted) thread. The
    // "delete not found" case is already swallowed by robustApiCall; on
    // THREAD_NOT_FOUND, swallowingApiCall logs + returns undefined so the
    // reply flow continues with a fresh send.
    await swallowingApiCall(
      () => lockedBot.api.deleteMessage(chat_id, id),
      { chat_id, verb: 'reply.deleteStalePreview' },
    )
  }

  logStreamingEvent({
    kind: 'reply_called',
    chatId: chat_id,
    charCount: effectiveText.length,
    replacedPreview: previewMessageId != null,
    previewMessageId,
  })
  // #1122 KPI: a `reply` always produces a fresh user-visible outbound
  // message — count it for the outbound-gap / TTFO KPI AND reset the
  // silence-poke clock so the next poke is measured from this send.
  signalTracker.noteOutbound(statusKey(chat_id, threadId), Date.now())
  silencePoke.noteOutbound(statusKey(chat_id, threadId), Date.now())
  // Mid-turn auto-classify recency clock: the agent just produced visible output
  // in this chat/thread (cross-turn, unlike silencePoke's per-turn lastOutboundAt).
  // Only maintained when the shadow flag is on → truly zero overhead by default.
  if (AUTOCLASSIFY_MIDTURN_SHADOW) noteAgentOutputAt(statusKey(chat_id, threadId), Date.now())
  // PR3b-cutover: feed lastOutboundAt to the delivery machine so its
  // TTL `tick` suppresses the fallback for a long-but-active turn
  // (model streaming past 5 min) — parity with silencePoke's own
  // suppression, so the cutover gate doesn't clear a live turn.
  shadowEmit({ kind: 'modelOutbound', key: statusKey(chat_id, threadId) as _ChatKey, at: Date.now() })
  // #1741 — only clear silent-end state on a plausibly-final reply.
  // An interim ack (disable_notification:true, short text, no done)
  // must NOT clear the state file; otherwise a turn that ends with
  // ack-only + answer-as-transcript leaves no state for the Stop
  // hook to act on if `turn_end` never lands (the `turn_duration`
  // system event is unreliable for trivial-prompt turns — see the
  // executeReply finalize comments). Final-answer replies still
  // clear; the main turn-end path also re-writes the state when
  // finalAnswerDelivered=false, so this is a belt-and-braces gate
  // for the turn_end-missing case (#1741).
  if (isFinalAnswerReply({ text: rawText, disableNotification: modelDisableNotification })) {
    clearSilentEndState(statusKey(chat_id, threadId))
  }

  // Lever 2 (design §9 lever 2): finalize the activity card BEFORE the reply
  // chunks send, so the card keeps its (lower) message_id and the reply is
  // structurally last on screen. ONLY for a *substantive* final — for an ack
  // (non-substantive) do NOTHING: finalizing an ack early would
  // close → reopen → emit MORE messages (the #2141 ack-then-work feed, R3).
  // `clearActivitySummary` edits the existing card in place (no new send) and
  // nulls `activityMessageId`; combined with the sticky latch set here it
  // prevents any post-reply re-OPEN below the answer. Idempotent with the
  // tool_use-event clear at the first-reply handoff (the existing backstop).
  {
    const finalizeTurn = currentTurn
    if (
      finalizeTurn != null
      && isSubstantiveFinalReply({ text: rawText, disableNotification: modelDisableNotification })
    ) {
      // PR-4a: routed through the emission-authority façade (no-op delegates —
      // the latch-set and the finalize run exactly as before).
      const ea = emissionAuthorityFor(finalizeTurn)
      ea.markSubstantiveFinalDelivered(() => {
        finalizeTurn.finalAnswerEverDelivered = true
        finalizeTurn.finalAnswerDeliveredAt = Date.now()
      })
      ea.finalizeCard(() => {
        clearActivitySummary(finalizeTurn)
      })
    }
  }

  if (previewMessageId != null && reply_to != null && replyMode !== 'off') {
    await deleteStalePreview(previewMessageId)
    previewMessageId = null
  }

  startTypingLoop(chat_id, threadId ?? null)

  // #1677 silent-reply auto-edit. Consecutive silent replies within
  // a turn edit a single anchor message instead of stacking new
  // bubbles. We branch BEFORE the chunk loop so the single-chunk
  // common case takes an editMessageText path; everything else
  // (multi-chunk, ping, files, buttons) falls through to fresh send
  // and either captures a new anchor or doesn't, per the predicate.
  let silentAnchorEditDone = false
  {
    const turn = currentTurn
    if (turn != null && chunks.length === 1) {
      const decision = decideSilentReplyAnchor({
        effectivelySilent: disableNotification,
        anchorMessageId: turn.silentAnchorMessageId,
        anchorText: turn.silentAnchorText,
        newReplyText: effectiveText,
        hasFiles: files.length > 0,
        hasButtons: replyMarkup != null,
        wasOverPingSuppressed,
      })
      if (decision.kind === 'edit-anchor') {
        const editParams: {
          message_thread_id?: number
          link_preview_options?: { is_disabled: boolean }
        } = {
          link_preview_options: { is_disabled: disableLinkPreview },
        }
        if (threadId != null) editParams.message_thread_id = threadId
        try {
          await robustApiCall(
            () =>
              lockedBot.api.editMessageText(
                chat_id,
                decision.messageId,
                literalText ? decision.mergedText : richMessage(decision.mergedText),
                editParams,
              ),
            {
              chat_id,
              verb: 'reply.silent-anchor-edit',
              ...(threadId != null ? { threadId } : {}),
            },
          )
          turn.silentAnchorText = decision.mergedText
          sentIds.push(decision.messageId)
          logOutbound(
            'edit',
            chat_id,
            decision.messageId,
            decision.mergedText.length,
            'silent-anchor-merge',
          )
          process.stderr.write(
            `telegram gateway: silent-reply auto-edit — ` +
            `chat=${chat_id} anchor=${decision.messageId} ` +
            `merged_len=${decision.mergedText.length}\n`,
          )

          // #1679 — side effects the chunk-loop completion path runs.
          // The edit-anchor branch returns early below, so these must
          // be wired here too. Skipping them silently causes:
          //   - cross-turn ambient (`pending-work-progress.ts`) holds
          //     a stale anchor text and OVERWRITES the model's
          //     accumulated silent content with `still working (Nm)`
          //     when async work is in flight (this is the load-bearing
          //     fix);
          //   - SQLite history (`get_recent_messages`) misses the
          //     silent-anchor content;
          //   - #1664 silent-end re-prompt fires even when the
          //     accumulated silent content qualifies as substantive;
          //   - retries within the dedup window may double-send.
          // #1760 primary fix — clear any stale prior-turn ticker
          // before re-anchoring on this silent-reply edit. See the
          // matching comment at the executeReply finalize site below.
          pendingProgress.clearPending(statusKey(chat_id, threadId), 'reply_finalize')
          pendingProgress.noteOutbound(statusKey(chat_id, threadId), {
            messageId: decision.messageId,
            text: decision.mergedText,
            literalText,
          })
          if (HISTORY_ENABLED) {
            try {
              recordOutbound({
                chat_id,
                thread_id: threadId ?? null,
                message_ids: [decision.messageId],
                texts: [decision.mergedText],
                attachment_kinds: [null],
              })
            } catch (histErr) {
              process.stderr.write(
                `telegram gateway: history recordOutbound (silent-anchor-edit) failed: ${histErr instanceof Error ? histErr.message : String(histErr)}\n`,
              )
            }
          }
          if (
            turn != null
            && isFinalAnswerReply({
              text: decision.mergedText,
              disableNotification: modelDisableNotification,
            })
          ) {
            turn.finalAnswerDelivered = true
            // Feed-reopen refinement: a substantive merged silent-anchor
            // answer must NOT re-open the feed on post-answer housekeeping.
            turn.finalAnswerSubstantive = isSubstantiveFinalReply({
              text: decision.mergedText,
              disableNotification: modelDisableNotification,
            })
            // Sticky ordering latch (lever 1): a substantive final closes the
            // card OPEN gate for the rest of the turn. NEVER cleared by reopen.
            if (turn.finalAnswerSubstantive) turn.finalAnswerEverDelivered = true
            if (turn.finalAnswerSubstantive && turn.finalAnswerDeliveredAt == null) turn.finalAnswerDeliveredAt = Date.now()
            if (turn.finalAnswerSubstantive) closeObligationOnSubstantiveReply(args, turn, replyRoutedOriginTurn)
          }
          outboundDedup.record(
            chat_id,
            threadId,
            decision.mergedText,
            Date.now(),
            turn?.registryKey ?? null,
          )

          silentAnchorEditDone = true
        } catch (err) {
          // Edit failed (e.g. message deleted, rate limit exhausted,
          // parse error). Fall through to fresh-send below — the
          // anchor will be overwritten by whatever lands.
          process.stderr.write(
            `telegram gateway: silent-reply auto-edit failed, ` +
            `falling back to fresh send: ${err instanceof Error ? err.message : String(err)}\n`,
          )
        }
      }
    }
  }

  if (silentAnchorEditDone) {
    // Skip the chunk loop entirely — the anchor edit IS the send.
    // Match the normal exit path: stop typing, then return.
    stopTypingLoop(chat_id, threadId ?? null)
    return {
      content: [
        {
          type: 'text',
          text: `edited (id: ${sentIds[0]})`,
        },
      ],
    }
  }

  try {
    for (let i = 0; i < chunks.length; i++) {
      // PR-C2: voice-only mode with a successful synthesis suppresses the
      // text body — the spoken voice note IS the reply. Bail before the
      // first chunk send (sentIds stays empty for text); the voice send
      // below lands the answer. Any other mode (voice+text, or voice-only
      // that fell back) sends the text chunks as normal.
      if (suppressText) break
      const shouldReplyTo =
        reply_to != null && replyMode !== 'off' && (replyMode === 'all' || i === 0)
      const isLastChunk = i === chunks.length - 1
      const sendOpts = {
        ...(shouldReplyTo
          ? {
              reply_parameters: {
                message_id: reply_to,
                ...(quoteText != null ? { quote: { text: quoteText, position: 0 } } : {}),
              },
            }
          : {}),
        ...(threadId != null ? { message_thread_id: threadId } : {}),
        ...(disableLinkPreview ? { link_preview_options: { is_disabled: true } } : {}),
        ...(replyMarkup != null && isLastChunk ? { reply_markup: replyMarkup } : {}),
        ...(protectContent ? { protect_content: true } : {}),
        ...(disableNotification ? { disable_notification: true } : {}),
      }

      // The body argument for send/edit: a rich-markdown wrapper on the
      // default path, or the literal string for `format:'text'` (#2669).
      const richOrPlain = (s: string) => (literalText ? s : richMessage(s))

      if (i === 0 && previewMessageId != null) {
        const editOpts: Record<string, unknown> = {}
        if (disableLinkPreview) editOpts.link_preview_options = { is_disabled: true }
        if (replyMarkup != null && isLastChunk) editOpts.reply_markup = replyMarkup
        try {
          await robustApiCall(
            () => lockedBot.api.editMessageText(chat_id, previewMessageId!, richOrPlain(chunks[i]), editOpts),
            { threadId, chat_id },
          )
          sentIds.push(previewMessageId!)
          previewMessageId = null
          continue
        } catch (err) {
          const msg = err instanceof Error ? err.message : String(err)
          if (/not modified/i.test(msg)) {
            sentIds.push(previewMessageId!)
            previewMessageId = null
            continue
          }
          process.stderr.write(`telegram gateway: preview edit-in-place failed (${msg}), sending fresh\n`)
          await deleteStalePreview(previewMessageId!)
          previewMessageId = null
        }
      }

      // Last-resort: resend this chunk as plain text (no rich wrapper, so
      // the markdown parser never runs). Keeps thread / reply / markup
      // params; only the formatting is sacrificed. Used when Telegram
      // rejects our markdown — better an unformatted answer than a
      // vanished one. The raw markdown source is itself readable prose, so
      // we send it verbatim rather than strip anything.
      const sendChunkPlainText = async (opts: Record<string, unknown>): Promise<void> => {
        const plain =
          chunks[i].length > 0
            ? chunks[i]
            : '⚠️ (a fragment could not be rendered for Telegram)'
        // allow-raw-bot-api: plaintext last-resort fallback; wrapping would re-enter the parse policy that just rejected the payload
        const sent = await lockedBot.api.sendMessage(chat_id, plain, opts as never)
        sentIds.push(sent.message_id)
        logOutbound('reply', chat_id, sent.message_id, plain.length, `chunk=${i + 1}/${chunks.length} plaintext-fallback`)
        process.stderr.write(
          `telegram gateway: markdown parse-reject — resent chunk ${i + 1}/${chunks.length} as plain text\n`,
        )
      }

      // Literal `format:'text'` sends bypass the rich parser entirely
      // (plain sendMessage, no markdown). The default path ships rich
      // markdown via sendRichMessage. Both resolve to a Message with a
      // message_id, which is all the caller reads.
      const sendChunk = (opts: Record<string, unknown>): Promise<{ message_id: number }> => {
        if (literalText) {
          // allow-raw-bot-api: literal format:'text' send; the chunk-loop's own THREAD_NOT_FOUND + parse-reject handling wraps this
          return lockedBot.api.sendMessage(chat_id, chunks[i], opts as never)
        }
        // sendRichMessage does NOT accept link_preview_options (rich messages
        // control previews via entity detection) — drop it for the rich path.
        const richOpts = { ...opts }
        delete (richOpts as { link_preview_options?: unknown }).link_preview_options
        // allow-raw-bot-api: sendRichMessage is not in the THREAD_NOT_FOUND blast pattern; thread fallback handled in the catch below
        return lockedBot.api.sendRichMessage(chat_id, richMessage(chunks[i]), richOpts as never)
      }

      // Length-error recovery: a single pre-computed chunk can still exceed the
      // wire cap when splitMarkdownChunks hit an indivisible region and emitted
      // it whole (a giant fenced block, a no-boundary blob). Telegram answers
      // with RICH_MESSAGE_TEXT_TOO_LONG / MESSAGE_TOO_LONG. Re-split this chunk
      // at a harder boundary and send each piece, rather than misclassifying it
      // as a parse-reject (which would resend the same oversized payload as
      // plain text) or surfacing the raw 400.
      const sendChunkResplit = async (opts: Record<string, unknown>): Promise<void> => {
        // Re-split at the same cap; for a truly indivisible block this still
        // yields one oversized piece, but a hard character-cut on the rendered
        // markdown at least keeps each delivered piece under the wire cap.
        const subPieces = splitMarkdownChunks(chunks[i], RICH_MESSAGE_MAX_CHARS)
        const pieces =
          subPieces.length > 1
            ? subPieces
            : hardSliceToCap(chunks[i], RICH_MESSAGE_MAX_CHARS)
        for (let p = 0; p < pieces.length; p++) {
          let sent: { message_id: number }
          if (literalText) {
            // allow-raw-bot-api: length-error re-split last resort (literal text); wrapping would re-enter the chunk-loop's own classification on an already-classified length failure.
            sent = await lockedBot.api.sendMessage(chat_id, pieces[p], opts as never)
          } else {
            const ro = { ...opts }
            delete (ro as { link_preview_options?: unknown }).link_preview_options
            // allow-raw-bot-api: length-error re-split last resort (rich); wrapping would re-enter the chunk-loop's own classification on an already-classified length failure.
            sent = await lockedBot.api.sendRichMessage(chat_id, richMessage(pieces[p]), ro as never)
          }
          sentIds.push(sent.message_id)
          logOutbound('reply', chat_id, sent.message_id, pieces[p].length, `chunk=${i + 1}/${chunks.length} resplit=${p + 1}/${pieces.length}`)
        }
        process.stderr.write(
          `telegram gateway: rich body too long — re-split chunk ${i + 1}/${chunks.length} into ${pieces.length} piece(s)\n`,
        )
      }

      try {
        const sent = await robustApiCall(() => sendChunk(sendOpts), { threadId, chat_id })
        sentIds.push(sent.message_id)
        logOutbound('reply', chat_id, sent.message_id, chunks[i].length, `chunk=${i + 1}/${chunks.length}`)
      } catch (err) {
        if (err instanceof Error && err.message === 'THREAD_NOT_FOUND') {
          threadId = undefined
          const retryOpts = { ...sendOpts }
          delete (retryOpts as any).message_thread_id
          try {
            const sent = await sendChunk(retryOpts)
            sentIds.push(sent.message_id)
          } catch (retryErr) {
            // Thread dropped, AND another failure: length → re-split,
            // parse-reject → plain text, else propagate.
            if (isMessageTooLongError(retryErr)) await sendChunkResplit(retryOpts)
            else if (isHtmlParseRejectError(retryErr)) await sendChunkPlainText(retryOpts)
            else throw retryErr
          }
        } else if (isMessageTooLongError(err)) {
          await sendChunkResplit(sendOpts)
        } else if (isHtmlParseRejectError(err)) {
          await sendChunkPlainText(sendOpts)
        } else {
          throw err
        }
      }
    }
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err)
    throw new Error(`reply failed after ${sentIds.length} of ${chunks.length} chunk(s) sent: ${msg}`)
  } finally {
    stopTypingLoop(chat_id, threadId ?? null)
  }

  // Outbound voice notes (PR-C2). Sent IN ORDER, AFTER the text body
  // (voice+text) or INSTEAD of it (voice-only, where suppressText skipped
  // the chunk loop). A long reply produces SEVERAL notes — each spoken in
  // sequence so the whole answer is heard, never truncated. Best-effort and
  // fully non-fatal: a sendVoice failure must NEVER break the text reply
  // path. In voice-only mode a failure would leave the user with an
  // incomplete spoken answer, so on the FIRST send failure we recover by
  // sending the full text once and stop sending further notes.
  for (let v = 0; v < voiceOggs.length; v++) {
    const oggBytes = voiceOggs[v]!
    const voiceOpts: Record<string, unknown> = {
      // Quote the user's message only on the FIRST voice note (mirrors the
      // text chunk loop's first-chunk reply behaviour).
      ...(v === 0 && reply_to != null && replyMode !== 'off'
        ? { reply_parameters: { message_id: reply_to } }
        : {}),
      ...(threadId != null ? { message_thread_id: threadId } : {}),
      ...(disableNotification ? { disable_notification: true } : {}),
    }
    try {
      const sentVoice = await retryWithThreadFallback<{ message_id: number; message_thread_id?: number }>(
        robustApiCall,
        (tid) => {
          const opts = { ...voiceOpts }
          if (tid != null) opts.message_thread_id = tid
          else delete opts.message_thread_id
          // allow-raw-bot-api: adapter callback INSIDE retryWithThreadFallback→robustApiCall; the THREAD_NOT_FOUND fallback is handled by the wrapper.
          return lockedBot.api.sendVoice(chat_id, new InputFile(Buffer.from(oggBytes)), opts as never)
        },
        { threadId, chat_id, verb: 'sendVoice' },
      )
      sentIds.push(sentVoice.message_id)
      logOutbound(
        'reply',
        chat_id,
        sentVoice.message_id,
        voiceOutPlan?.ttsChunks[v]?.length ?? 0,
        `voice-note=${v + 1}/${voiceOggs.length}`,
      )
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err)
      process.stderr.write(
        `telegram gateway: voice-out: sendVoice ${v + 1}/${voiceOggs.length} failed (non-fatal): ${msg}\n`,
      )
      // voice-only fell over mid-stream with text suppressed → recover by
      // sending the FULL text body once so the answer still lands, then
      // stop sending further notes (the text now carries everything).
      if (suppressText) {
        try {
          const opts: Record<string, unknown> = {
            ...(reply_to != null && replyMode !== 'off'
              ? { reply_parameters: { message_id: reply_to } }
              : {}),
            ...(threadId != null ? { message_thread_id: threadId } : {}),
            ...(disableNotification ? { disable_notification: true } : {}),
          }
          // allow-raw-bot-api: voice-only recovery fallback — the rich path already ran/was skipped; send the source text plainly so the answer is never lost.
          const sent = await lockedBot.api.sendMessage(chat_id, effectiveText, opts as never)
          sentIds.push(sent.message_id)
          logOutbound('reply', chat_id, sent.message_id, effectiveText.length, 'voice-only-text-recovery')
        } catch (textErr) {
          process.stderr.write(
            `telegram gateway: voice-out: voice-only text recovery ALSO failed: ${textErr instanceof Error ? textErr.message : String(textErr)}\n`,
          )
        }
        break
      }
    }
  }

  // #710: remember per-button agent meta (ack_text / single_use) keyed
  // by the message that actually carries the keyboard — that's the last
  // text chunk, since the keyboard is attached only on isLastChunk.
  if (replyButtonMeta != null && replyButtonMeta.size > 0 && sentIds.length >= chunks.length) {
    const keyboardMsgId = sentIds[chunks.length - 1]
    if (typeof keyboardMsgId === 'number') {
      rememberAgentButtonMeta(chat_id, keyboardMsgId, replyButtonMeta)
    }
  }

  // #1445 cross-turn pending-async ambient. Capture the last text
  // chunk as the anchor — if this turn ends with a pending async
  // dispatch, the framework edits THIS message in place every 60s
  // with a `— still working (Nm)` suffix until the user re-engages.
  // Multi-chunk replies: anchor is the LAST chunk (edits append to
  // the visually-trailing message; earlier chunks are left intact).
  if (sentIds.length === chunks.length && chunks.length > 0) {
    const anchorMsgId = sentIds[chunks.length - 1]
    if (typeof anchorMsgId === 'number') {
      // #1760 primary fix — clear any stale prior-turn ticker BEFORE
      // re-anchoring. The canonical teardown wires (turn_end,
      // subagent_handback, inbound) can be missed (e.g. SDK turn_end
      // event dropped, as in the #1760 live evidence). Tearing down on
      // every reply-finalize is idempotent and resilient: it's a no-op
      // when nothing is active, and drops a stale ambient before the
      // new turn captures its anchor.
      pendingProgress.clearPending(statusKey(chat_id, threadId), 'reply_finalize')
      pendingProgress.noteOutbound(statusKey(chat_id, threadId), {
        messageId: anchorMsgId,
        text: chunks[chunks.length - 1],
        literalText,
      })
    }
  }

  // #1677 silent-reply auto-edit — anchor capture for the FIRST
  // silent reply of a turn (or the silent reply that replaced the
  // anchor on overflow). Only captures for the single-chunk,
  // silent, no-files, no-buttons happy path; the edit-anchor path
  // earlier in this function handles SUBSEQUENT silent replies by
  // editing. The next silent reply this turn will see the captured
  // anchor and edit it in place.
  if (
    chunks.length === 1
    && disableNotification
    && files.length === 0
    && replyMarkup == null
    && sentIds.length === 1
  ) {
    const turn = currentTurn
    if (turn != null) {
      turn.silentAnchorMessageId = sentIds[0]!
      turn.silentAnchorText = effectiveText
    }
  }

  // #273: when files is 2-10 photos, batch them into a single
  // sendMediaGroup album rather than N separate sendPhoto calls. The
  // user's device fires one notification for the album instead of N
  // (notification-budget protection per the issue's JTBD note). Falls
  // back to the per-file path for any non-all-photo set.
  const allPhotos = files.length >= 2 && files.length <= 10
    && files.every((f) => PHOTO_EXTS.has(extname(f).toLowerCase()))
  // #1075: thread-id-bearing file sends. Mirror the chunk-loop's
  // THREAD_NOT_FOUND fallback (deleted topic → drop the thread and
  // resend on the main chat) so an attachment-bearing reply doesn't
  // crash when the user deletes the topic mid-flight.
  const replyParams =
    reply_to != null && replyMode !== 'off' ? { reply_parameters: { message_id: reply_to } } : {}
  if (allPhotos) {
    const media = files.map((f) => ({
      type: 'photo' as const,
      media: new InputFile(f),
    }))
    const sent = await retryWithThreadFallback(
      robustApiCall,
      (tid) => {
        const baseOpts = {
          ...replyParams,
          ...(tid != null ? { message_thread_id: tid } : {}),
        }
        return lockedBot.api.sendMediaGroup(chat_id, media, baseOpts)
      },
      { threadId, chat_id, verb: 'sendMediaGroup' },
    )
    if (threadId != null) {
      // If the fallback dropped the thread id, propagate that decision
      // to subsequent calls in this reply (no further retries needed).
      // We can't observe which branch resolved cleanly, so peek at the
      // first sent message: Telegram echoes message_thread_id only when
      // present in the request. Absent → fallback fired.
      const first = sent[0] as { message_thread_id?: number } | undefined
      if (first && first.message_thread_id == null) threadId = undefined
    }
    for (const m of sent) sentIds.push(m.message_id)
  } else {
    for (const f of files) {
      const ext = extname(f).toLowerCase()
      const input = new InputFile(f)
      const isPhoto = PHOTO_EXTS.has(ext)
      const sent = await retryWithThreadFallback<{ message_id: number; message_thread_id?: number }>(
        robustApiCall,
        (tid) => {
          const baseOpts = {
            ...replyParams,
            ...(tid != null ? { message_thread_id: tid } : {}),
          }
          return isPhoto
            ? lockedBot.api.sendPhoto(chat_id, input, baseOpts)
            : lockedBot.api.sendDocument(chat_id, input, baseOpts)
        },
        { threadId, chat_id, verb: isPhoto ? 'sendPhoto' : 'sendDocument' },
      )
      // Mirror the threadId-clear above so the *next* file in the
      // loop skips the doomed thread without paying for another
      // round trip + retry.
      if (threadId != null && sent.message_thread_id == null) {
        threadId = undefined
      }
      sentIds.push(sent.message_id)
    }
  }

  const result = sentIds.length === 1
    ? `sent (id: ${sentIds[0]})`
    : `sent ${sentIds.length} parts (ids: ${sentIds.join(', ')})`

  if (HISTORY_ENABLED && sentIds.length > 0) {
    try {
      const fileCount = files.length
      const textCount = sentIds.length - fileCount
      const texts: string[] = []
      const attachKinds: (string | null)[] = []
      for (let i = 0; i < textCount; i++) { texts.push(chunks[i] ?? ''); attachKinds.push(null) }
      for (let i = 0; i < fileCount; i++) {
        const ext = extname(files[i] ?? '').toLowerCase()
        texts.push(`(${PHOTO_EXTS.has(ext) ? 'photo' : 'document'}: ${files[i]})`)
        attachKinds.push(PHOTO_EXTS.has(ext) ? 'photo' : 'document')
      }
      recordOutbound({ chat_id, thread_id: threadId ?? null, message_ids: sentIds, texts, attachment_kinds: attachKinds })
    } catch (err) {
      process.stderr.write(`telegram gateway: history recordOutbound (reply) failed: ${err}\n`)
    }
  }

  // Issue #137: signal to the progress driver that an actual outbound
  // landed, so a turn-end with replyToolCalled=true but zero deliveries
  // can render the "⚠️ Reply attempted but not delivered" variant.
  if (sentIds.length > 0) {
    try {
      progressDriver?.recordOutboundDelivered(
        chat_id,
        threadId != null ? String(threadId) : undefined,
      )
    } catch { /* best-effort signal */ }
    // #203: fresh sendMessage from reply tool is a user-visible signal.
    signalTracker.noteSignal(statusKey(chat_id, threadId), Date.now())
    // #1713: the reply tool is a NON-EVENT for the status reaction
    // WHEN IT'S AN INTERIM ACK. The reaction reflects current turn
    // activity, not delivery state — interim acks must not collapse
    // the working-state ladder to 👍.
    //
    // #1728 carve-out (2026-05-24): when this reply IS the final
    // answer (`isFinalAnswerReply` returns true — same classifier
    // #1664 uses for silent-end re-prompt gating), it IS effectively
    // turn-end and we MUST finalize here. Rationale: Claude Code's
    // `turn_duration` system event is unreliable for the trivial-
    // prompt happy path (driver sends "what's 2+2", model replies
    // "4", no `turn_duration` ever lands in the JSONL session tail).
    // Pre-#1718 this wedge was masked by the legacy
    // `endStatusReaction` shim running unconditionally on every
    // reply (outcome='done'); #1718 removed that call site
    // intending `turn_end` to be the sole terminal trigger. The
    // contract was right in spirit but `turn_end` doesn't fire 100%
    // of the time, so the buffer gate (activeTurnStartedAt) stays
    // set forever and every subsequent inbound gets `held mid-turn`
    // and never delivered. v0.13.27 shipped + reverted on this
    // failure mode (#1728).
    //
    // Net contract:
    //   - interim ack reply (isFinalAnswerReply === false)
    //         → non-event, no reaction finalize, buffer gate stays
    //   - final-answer reply (isFinalAnswerReply === true)
    //         → finalize reaction (debounced 👍) + release buffer
    //           gate via purgeReactionTracking (called inside
    //           finalizeStatusReaction). currentTurn stays alive so
    //           a subsequent `turn_end` still cleans up its share
    //           idempotently.
    //
    // #1664 — `turn.finalAnswerDelivered = true` keeps the silent-
    // end re-prompt from spuriously firing on a delivered final.
    if (turn != null && isFinalAnswerReply({ text: rawText, disableNotification: modelDisableNotification })) {
      turn.finalAnswerDelivered = true
      // Feed-reopen refinement: track whether this final was substantive
      // (≥200 chars or stream-done — not a short pinging ack) so post-answer
      // housekeeping tool work does NOT re-open the feed / trip silent-end.
      turn.finalAnswerSubstantive = isSubstantiveFinalReply({ text: rawText, disableNotification: modelDisableNotification })
      // Sticky ordering latch (lever 1): set once a SUBSTANTIVE final lands;
      // never cleared by reopen. The card OPEN gate keys on this, not the
      // mutable finalAnswerDelivered above (which reopen toggles).
      if (turn.finalAnswerSubstantive) turn.finalAnswerEverDelivered = true
      if (turn.finalAnswerSubstantive && turn.finalAnswerDeliveredAt == null) turn.finalAnswerDeliveredAt = Date.now()
      // #1728: release the buffer gate + emit terminal 👍. Mid-turn
      // acks bypass this branch and remain non-events for the
      // reaction (preserves #1713). The full turn-state teardown
      // (nulling `currentTurn`, the per-turn cleanup) still runs in
      // the `turn_end` handler when it lands; this only fires the
      // observable side effects that #1718 deferred unconditionally.
      finalizeStatusReaction(chat_id, threadId, 'done')
      // PR2: close this origin's obligation on a SUBSTANTIVE final answer
      // (after finalize so the reaction guard test's anchor window is stable).
      if (turn.finalAnswerSubstantive) closeObligationOnSubstantiveReply(args, turn, replyRoutedOriginTurn)
    }
    // v0.13.30 follow-up — release the buffer gate on EVERY reply
    // finalize, not just on `isFinalAnswerReply`. The narrow
    // `finalizeStatusReaction` path above misses short replies that
    // set `disable_notification: true` (the model mis-classifies a
    // genuine answer as an interim ack — e.g. "4" for "what's
    // 2+2"). Pre-fix the gate stayed set forever and every later
    // inbound logged `held mid-turn ... will flush on turn-
    // complete` — but turn-complete never came because Claude
    // Code's `turn_duration` system event doesn't reliably land
    // for trivial-prompt turns. v0.13.30 UAT showed the regression
    // (msg 1873 reply at 13:02:46, msg 1874 held at 13:03:04, gate
    // never released).
    //
    // The reaction controller stays alive (preserves #1713
    // bidirectional ladder + the steer-vs-queue logic at
    // gateway.ts:8322 which reads `activeStatusReactions`). Only
    // the buffer gate flips.
    //
    // Component 1: pass the turn so the serialize gate sees this turn's
    // `finalAnswerDelivered` (set just above for final-answer replies).
    // An interim ack leaves it false → the cross-topic buffer does NOT
    // drain yet; the real answer's reply releases it.
    releaseTurnBufferGate(statusKey(chat_id, threadId), turn ?? undefined)
    // Component 5: the final answer landed — reap the queued-status
    // placeholder for THIS turn's topic. Key on the turn's own session
    // thread (where the placeholder was posted / promoted), not the
    // answer's possibly-overridden threadId.
    if (turn?.finalAnswerDelivered === true) {
      reapQueuedStatus(turn.sessionChatId, turn.sessionThreadId)
    }
  }

  process.stderr.write(`telegram channel: reply: finalized chatId=${chat_id} messageIds=[${sentIds.join(',')}] chunks=${chunks.length}\n`)
  // #546 dedup record: future reply / stream_reply / turn-flush
  // calls with this same content within DEFAULT_DEDUP_TTL_MS will
  // be suppressed.
  if (sentIds.length > 0) {
    outboundDedup.record(chat_id, threadId, text, Date.now(), currentTurn?.registryKey ?? null)
  }
  return { content: [{ type: 'text', text: result }] }
}

async function executeStreamReply(args: Record<string, unknown>): Promise<unknown> {
  // #1664 — pin the turn at entry; see executeReply for the rationale.
  const turn = currentTurn
  if (!args.chat_id) throw new Error('stream_reply: chat_id is required')
  if (args.text == null || args.text === '') throw new Error('stream_reply: text is required and cannot be empty')
  // chat_id allowlist fallback — mirrors executeReply (~8725). stream_reply is
  // the primary final-answer path, so a wrong/late chat_id (int/string mismatch,
  // or the model echoing the wrong identifier after a silence poke flipped
  // currentTurn to null) would otherwise fail assertAllowedChat in the stream
  // controller → an invisible reply. Rewrite args.chat_id in place so every
  // downstream consumer (origin resolution, dedup key, the send) sees the
  // corrected value. Tier 1: live turn's sessionChatId. Tier 2: last-known
  // turn's chat (survives silence poke — Bug D fix; currentTurn is null).
  {
    const _rawChatId = String(args.chat_id ?? '')
    const resolved = resolveChatIdFallback(
      _rawChatId,
      loadAccess(),
      turn?.sessionChatId,
      lastActiveTurnChatId,
      turn != null,
    )
    if (resolved.tier !== 'raw') {
      process.stderr.write(
        `telegram gateway: stream_reply: model passed chat_id "${_rawChatId}" (not allowlisted) — ` +
          `routing to ${resolved.tier} turn chat "${resolved.chatId}"\n`,
      )
      args.chat_id = resolved.chatId
    }
  }
  // Thread precedence (matches executeReply; component 3 — turn-origin
  // routing): when the model passes no explicit message_thread_id, inject
  // the ORIGIN turn's thread (matched by origin_turn_id) — authoritative
  // even after currentTurn flips — falling back to the live turn's thread
  // when no origin is resolvable (legacy #1664). Injecting into
  // args.message_thread_id threads every downstream consumer consistently
  // (dedup key, voice-scrub metric, draft transport, the send), so a
  // streamed handback/synthetic-turn reply lands in the right supergroup
  // topic and a late stream-reply can't be stolen by a successor turn. DM:
  // every tier undefined → unchanged. Kill switch off → legacy live-turn
  // injection only.
  // Origin resolution is hoisted UNCONDITIONALLY (outside the
  // message_thread_id==null guard below) so the obligation-close path has
  // the correct routedOriginTurn even when the model explicitly passes
  // message_thread_id (forum-topic streams). Without this hoist, Fix 1
  // is a no-op for forum-topic streams — the origin is never resolved and
  // closeObligationOnSubstantiveReply falls through to the live-turn
  // fallback. Matches executeReply's unconditional resolution. Thread
  // injection still stays scoped to the message_thread_id==null branch —
  // only the obligation-close input changes.
  let streamRoutedOriginTurn: CurrentTurn | null = null
  // Track whether the origin was found via echo (for the routing log below).
  let streamOriginVia: 'echo' | 'quoted' | null = null
  if (TURN_ORIGIN_ROUTING_ENABLED) {
    // Origin precedence: model echo first, then the framework-owned quoted
    // message_id as a deterministic fallback (mirrors executeReply).
    const echoedTurn = findTurnByOriginId(args.origin_turn_id as string | undefined)
    const quotedTurn =
      echoedTurn == null ? findTurnByQuotedMessageId(String(args.chat_id), args.reply_to) : null
    const originTurn = echoedTurn ?? quotedTurn
    streamRoutedOriginTurn = originTurn ?? null
    streamOriginVia = originTurn == null ? null : echoedTurn != null ? 'echo' : 'quoted'
  }
  if (args.message_thread_id == null) {
    let injected: number | undefined
    if (TURN_ORIGIN_ROUTING_ENABLED) {
      injected = resolveAnswerThreadWithLog(
        String(args.chat_id),
        undefined,
        streamRoutedOriginTurn,
        streamOriginVia,
        turn,
        'stream_reply',
      )
    } else {
      injected = turn?.sessionThreadId
    }
    if (injected != null) args.message_thread_id = String(injected)
  }

  // Outbound secret scrub (#2044): mask before the dedup key, the draft
  // stream sends, and the history record. stream_reply carries the FULL
  // text-so-far on every call, so redacting each call keeps the answer-
  // stream's incremental diffing comparing redacted-against-redacted.
  args.text = redactOutboundText(args.text as string, 'stream_reply')

  // Voice scrub (PR #1683 follow-up). Modern Claude on the fleet
  // uses the answer-stream / draft-stream path for multi-paragraph
  // replies — the model emits via stream_reply and the original
  // PR #1683 scrub site (executeReply) never sees the text. klanker's
  // 2026-05-24 log showed model output with em-dashes routed via
  // stream_reply done=true, materializing as sendMessage with no
  // scrub. Mirror the executeReply pattern here: scrub BEFORE the
  // outbound-dedup check (so retries see the scrubbed key) and
  // mutate args.text so all downstream consumers (the stream-
  // controller, dedup record, history record) see the scrubbed
  // version. Kill switch: SWITCHROOM_DISABLE_VOICE_SCRUB.
  {
    // Cross-path consistency (#2755): normalizePunctuation runs BEFORE
    // scrubVoice here, matching the reply/edit paths, so a spaced em-dash
    // gets the same comma treatment on every outbound path (scrubVoice
    // would otherwise see the raw dash first on this path only and apply
    // its period substitution). handleStreamReply's own deps run
    // normalizePunctuation again downstream — it is idempotent, so the
    // second pass is a no-op. Side effect: scrubVoice's dash telemetry
    // (voice_scrub_applied) drops to ~zero on this path since the dashes
    // are consumed here first — deliberate.
    args.text = normalizePunctuation(args.text as string)
    const scrub = scrubVoice(args.text as string)
    if (scrub.replaced > 0) {
      args.text = scrub.scrubbed
      emitRuntimeMetric({
        kind: 'voice_scrub_applied',
        chatKey: statusKey(String(args.chat_id ?? ''), args.message_thread_id != null
          ? Number(args.message_thread_id) : undefined),
        replaced: scrub.replaced,
        site: 'stream_reply',
      })
    }
  }

  // #546 dedup check: stream_reply done=true is the most-common
  // retry shape — claude-code re-emits the final-text call when
  // the previous bridge missed the ack. If turn-flush already sent
  // the same content, swallow the retry and return success.
  // Only check on done=true (the terminal call); intermediate
  // streaming chunks are progress edits, not full sends.
  if (args.done === true) {
    const sChatId = String(args.chat_id ?? '')
    const sThreadId = args.message_thread_id != null ? Number(args.message_thread_id) : undefined
    const sText = args.text as string
    const dup = outboundDedup.check(sChatId, sThreadId, sText, Date.now(), currentTurn?.registryKey ?? null)
    if (dup != null) {
      process.stderr.write(
        `telegram gateway: stream_reply: deduped (#546) chatId=${sChatId} ` +
        `ageMs=${dup.ageMs} preview=${JSON.stringify(dup.preview)}\n`,
      )
      return { content: [{ type: 'text', text: 'sent (deduped — same content sent via earlier path)' }] }
    }
  }

  const access = loadAccess()
  // Detect chat type for throttle-default selection.
  // Private (DM) chats have positive numeric IDs; groups/channels are negative.
  const streamChatId = String(args.chat_id ?? '')
  const streamIsPrivate = isDmChatId(streamChatId)
  const streamIsForumTopic = args.message_thread_id != null && args.message_thread_id !== ''
  // Pre-allocated draft handoff removed in #553 PR 5 — draft-stream
  // now allocates a fresh draft id on its first send. The pre-alloc
  // path has been retired along with the placeholder text it was
  // designed to overwrite cleanly.

  // #271: validate + namespace callback_data for stream_reply. Same
  // wrapping as executeReply — URL buttons pass through, callback_data
  // gets the `agent:` prefix so the dispatcher can route taps back to
  // this agent. Only attached on done=true so buttons land on the
  // final answer message, not on intermediate draft edits.
  let streamReplyMarkup: { inline_keyboard: AnyButton[][] } | undefined
  let streamButtonMeta: Map<string, AgentButtonMeta> | undefined
  const rawStreamKeyboard = args.inline_keyboard as AnyButton[][] | undefined
  if (rawStreamKeyboard != null && Boolean(args.done)) {
    const validationErrors = validateInlineKeyboard(rawStreamKeyboard)
    if (validationErrors.length > 0) {
      const summary = validationErrors
        .map((e) => `${e.path}.${e.field}: ${e.reason}`)
        .join('; ')
      throw new Error(`inline_keyboard validation failed: ${summary}`)
    }
    streamButtonMeta = extractAgentButtonMeta(rawStreamKeyboard)
    streamReplyMarkup = { inline_keyboard: wrapAgentCallbacks(rawStreamKeyboard) }
  }

  // #1122 KPI: stream_reply's FIRST emit is a fresh user-visible outbound
  // message (subsequent calls edit the same message — no device ping).
  // Snapshot state BEFORE handleStreamReply to detect first-emit precisely.
  {
    const streamThreadId = args.message_thread_id != null ? Number(args.message_thread_id) : undefined
    const sKeyBefore = streamKey(streamChatId, streamThreadId)
    if (!activeDraftStreams.has(sKeyBefore)) {
      const sKey = statusKey(streamChatId, streamThreadId)
      signalTracker.noteOutbound(sKey, Date.now())
      silencePoke.noteOutbound(sKey, Date.now())
      // PR3b-cutover: feed lastOutboundAt to the delivery machine (see
      // executeReply) so its TTL tick suppresses an active-turn fallback.
      shadowEmit({ kind: 'modelOutbound', key: sKey as _ChatKey, at: Date.now() })
      // #2527: emit turn_reply_timing on the first stream_reply of the turn,
      // mirroring the same gate in executeReply. Guards with firstTextReplyLogged
      // so a turn that calls reply first and stream_reply second doesn't double-emit.
      if (turn != null && !firstTextReplyLogged.has(sKey)) {
        firstTextReplyLogged.add(sKey)
        logStreamingEvent({
          kind: 'turn_reply_timing',
          chatId: streamChatId,
          threadId: streamThreadId,
          turnId: turn.turnId,
          timeToFirstTextReplyMs: Date.now() - turn.gatewayReceiveAt,
        })
      }
      // #1741 — see executeReply for the rationale: only a plausibly-
      // final stream_reply clears the silent-end state. An interim
      // ack via stream_reply must NOT clear; the Stop hook needs
      // the state to persist if turn_end fails to land.
      if (
        isFinalAnswerReply({
          text: (args.text as string | undefined) ?? '',
          disableNotification: args.disable_notification === true,
          done: args.done === true,
        })
      ) {
        clearSilentEndState(sKey)
      }
    }
  }

  // Lever 2 (design §9 lever 2): finalize the activity card BEFORE the stream
  // send so the card keeps its lower message_id and the reply is structurally
  // last. ONLY for a *substantive* final (a stream_reply done=true or ≥200
  // chars) — for a short pinging interim chunk do NOTHING (finalizing an ack
  // early would close → reopen → emit more, the #2141 ack-then-work feed, R3).
  // `clearActivitySummary` edits in place + nulls activityMessageId; the sticky
  // latch set here blocks any post-reply re-OPEN below the answer.
  if (
    turn != null
    && isSubstantiveFinalReply({
      text: (args.text as string | undefined) ?? '',
      disableNotification: args.disable_notification === true,
      done: args.done === true,
    })
  ) {
    // PR-4a: routed through the emission-authority façade (no-op delegates —
    // the latch-set and the finalize run exactly as before).
    const ea = emissionAuthorityFor(turn)
    ea.markSubstantiveFinalDelivered(() => {
      turn.finalAnswerEverDelivered = true
      if (turn.finalAnswerDeliveredAt == null) turn.finalAnswerDeliveredAt = Date.now()
    })
    ea.finalizeCard(() => {
      clearActivitySummary(turn)
    })
  }

  const result = await handleStreamReply(
    {
      chat_id: streamChatId,
      text: args.text as string,
      done: Boolean(args.done),
      message_thread_id: args.message_thread_id as string | undefined,
      format: args.format as string | undefined,
      reply_to: args.reply_to as string | undefined,
      quote: args.quote as boolean | undefined,
      ...(args.protect_content === true ? { protect_content: true } : {}),
      ...(args.quote_text != null ? { quote_text: args.quote_text as string } : {}),
      ...(streamReplyMarkup != null ? { reply_markup: streamReplyMarkup } : {}),
      ...(args.disable_notification === true ? { disable_notification: true } : {}),
    },
    { activeDraftStreams, suppressPtyPreview },
    {
      // grammy's Bot<Context, Api<RawApi>> has a wider api shape than the
      // local StreamBotApi interface, but is structurally compatible at
      // runtime (StreamBotApi is a subset). Cast through unknown to
      // bypass the structural-typing strictness.
      bot: lockedBot as unknown as { api: import('../stream-controller.js').StreamBotApi },
      retry: robustApiCall,
      repairEscapedWhitespace,
      normalizeParagraphBreaks,
      normalizePunctuation,
      stripExcessBold,
      addParagraphSpacers,
      assertAllowedChat,
      resolveThreadId,
      disableLinkPreview: access.disableLinkPreview !== false,
      defaultFormat: access.parseMode ?? 'html',
      logStreamingEvent,
      isPrivateChat: streamIsPrivate,
      isForumTopic: streamIsForumTopic,
      // Issue #310: deliver the outbound count bump BEFORE forceCompleteTurn
      // so the terminal render sees outboundDeliveredCount > 0. The handler
      // calls this dep in that order internally.
      recordOutboundDelivered: (chatId, threadId) => {
        progressDriver?.recordOutboundDelivered(
          chatId,
          threadId != null ? String(threadId) : undefined,
        )
      },
      forceCompleteTurn: (chatId, threadId) => {
        progressDriver?.forceCompleteTurn({
          chatId,
          threadId: threadId != null ? String(threadId) : undefined,
        })
      },
      historyEnabled: HISTORY_ENABLED,
      recordOutbound,
      ...(HISTORY_ENABLED ? { getLatestInboundMessageId } : {}),
      writeError: (line) => process.stderr.write(line),
      // When the operator sets `channels.telegram.stream_throttle_ms` in yaml,
      // the env override wins; otherwise draft-stream's DM/group defaults apply
      // (400 ms for DMs, 1000 ms for groups). `throttleMs: undefined` passes
      // through to draft-stream where the per-chat-type default applies.
      ...(STREAM_THROTTLE_MS_OVERRIDE != null ? { throttleMs: STREAM_THROTTLE_MS_OVERRIDE } : {}),
      progressCardActive: streamMode === 'checklist',
    },
  )
  // Issue #137: bump the per-turn outbound counter on every successful
  // stream_reply call (partial OR final). Even a single chunk landing
  // proves the delivery path worked. messageId may be null when the
  // call only updated the streaming draft and didn't sendMessage on
  // this invocation — that case still counts as activity.
  if (result.messageId != null) {
    try {
      progressDriver?.recordOutboundDelivered(
        String(args.chat_id ?? ''),
        args.message_thread_id as string | undefined,
      )
    } catch { /* best-effort signal */ }
    // Issue #203: stream_reply is the agent's primary reply path. Without
    // ticking the silent-gap tracker here, turn_signal_gap reports the
    // entire turn duration as silent for any turn that uses stream_reply
    // — which per CLAUDE.md guidance is most of them. The metric would be
    // worse than no metric. Tick on every successful delivery (partial or
    // final) so the gap measurement reflects real silent intervals.
    try {
      const threadIdNum = args.message_thread_id != null
        ? Number(args.message_thread_id)
        : undefined
      signalTracker.noteSignal(
        statusKey(String(args.chat_id ?? ''), threadIdNum),
        Date.now(),
      )
    } catch { /* best-effort signal */ }
  }
  // #710: stash agent-button meta keyed by the final message id so the
  // callback handler can honor ack_text / single_use on tap.
  if (
    args.done === true
    && result.messageId != null
    && streamButtonMeta != null
    && streamButtonMeta.size > 0
  ) {
    rememberAgentButtonMeta(String(args.chat_id ?? ''), result.messageId, streamButtonMeta)
  }
  // #546 dedup record: capture the final stream_reply text on the
  // terminal call so a subsequent retry (different bridge, same
  // content) lands as a no-op instead of a second message.
  if (args.done === true && result.messageId != null) {
    const sChatId = String(args.chat_id ?? '')
    const sThreadId = args.message_thread_id != null ? Number(args.message_thread_id) : undefined
    outboundDedup.record(sChatId, sThreadId, args.text as string, Date.now(), currentTurn?.registryKey ?? null)
    // #1445 cross-turn pending-async ambient. The terminal stream_reply
    // (done=true) is the user-visible anchor for any cross-turn wait
    // that follows. Capture it so if this turn ends with a pending
    // async dispatch, the framework edits THIS message in place at
    // intervals.
    //
    // #2669 — capture whether the stream-reply-handler sent literally
    // (format:'text') so the cross-turn edit tick re-edits with the same
    // shape. The default rich-markdown path re-edits via the rich path.
    const streamFormat = (args.format as string | undefined) ?? (access.parseMode ?? 'html')
    const streamLiteralText = streamFormat === 'text'
    // #1760 primary fix — clear any stale prior-turn ticker before
    // re-anchoring on stream_reply done. See the matching comment at
    // the executeReply finalize site.
    pendingProgress.clearPending(statusKey(sChatId, sThreadId), 'reply_finalize')
    pendingProgress.noteOutbound(statusKey(sChatId, sThreadId), {
      messageId: result.messageId,
      text: args.text as string,
      literalText: streamLiteralText,
    })
  }
  // #1664 — mark the turn's final answer as delivered. For stream_reply a
  // call with done=true IS the final answer by definition (the model
  // explicitly closed the stream). A non-terminal stream_reply chunk also
  // counts when it carries the final-answer signals — notification-bearing
  // OR substantive length — via the same `isFinalAnswerReply` predicate
  // executeReply uses. See the CurrentTurn.finalAnswerDelivered doc-comment
  // for why replyCalled is not a sufficient signal here.
  if (
    turn != null &&
    isFinalAnswerReply({
      text: (args.text as string | undefined) ?? '',
      disableNotification: args.disable_notification === true,
      done: args.done === true,
    })
  ) {
    turn.finalAnswerDelivered = true
    // Feed-reopen refinement: a stream_reply done=true (or a ≥200-char
    // chunk) is substantive; a short pinging non-done chunk is an ack. Only
    // the latter should re-open the feed on subsequent post-answer work.
    turn.finalAnswerSubstantive = isSubstantiveFinalReply({
      text: (args.text as string | undefined) ?? '',
      disableNotification: args.disable_notification === true,
      done: args.done === true,
    })
    // Sticky ordering latch (lever 1): set once a SUBSTANTIVE final lands;
    // never cleared by reopen. The card OPEN gate keys on this sticky latch.
    if (turn.finalAnswerSubstantive) turn.finalAnswerEverDelivered = true
    if (turn.finalAnswerSubstantive && turn.finalAnswerDeliveredAt == null) turn.finalAnswerDeliveredAt = Date.now()
    if (turn.finalAnswerSubstantive) closeObligationOnSubstantiveReply(args, turn, streamRoutedOriginTurn)
    // #1744 follow-up — stream_reply edge case. The first-emit gate at
    // L5178 only clears silent-end state on the FIRST emit of a stream.
    // If a stream's first emit was ack-shaped (disable_notification:true,
    // short text, no done) it correctly did NOT clear the state. But a
    // LATER emit in the same stream may flip `done=true` or carry
    // substantive text — that's the real final answer landing, and the
    // state file must be cleared here too. clearSilentEndState is
    // idempotent (no-op when the file is absent or the turnKey doesn't
    // match), so calling it unconditionally on every final-answer-shaped
    // emit is safe even if the first-emit path already cleared.
    const streamThreadIdForClear = args.message_thread_id != null
      ? Number(args.message_thread_id)
      : undefined
    clearSilentEndState(statusKey(streamChatId, streamThreadIdForClear))
  }
  // v0.13.30 follow-up — release the buffer gate on every successful
  // stream_reply too. Same rationale as executeReply: short replies
  // with `disable_notification: true` would otherwise wedge the gate
  // forever. `result.status` is always 'updated' | 'finalized'
  // (stream-reply-handler.ts:305) at this point — earlier failures
  // throw or return before reaching here.
  {
    const sChat = String(args.chat_id ?? '')
    const sThread = resolveThreadId(sChat, args.message_thread_id as string | undefined)
    // Component 1: pass the turn (finalAnswerDelivered set above for a
    // final stream emit). Interim stream chunks leave it false → no
    // cross-topic drain until the done=true / substantive emit lands.
    releaseTurnBufferGate(statusKey(sChat, sThread), turn ?? undefined)
    // Component 5: reap the queued-status placeholder for THIS turn's
    // topic once the final answer landed. Key on the turn's own session
    // thread (where the placeholder lives), not the answer's resolved one.
    if (turn?.finalAnswerDelivered === true) {
      reapQueuedStatus(turn.sessionChatId, turn.sessionThreadId)
    }
  }
  return { content: [{ type: 'text', text: `${result.status} (id: ${result.messageId ?? 'pending'})` }] }
}

async function executeProgressUpdate(args: Record<string, unknown>): Promise<unknown> {
  if (!args.chat_id) throw new Error('progress_update: chat_id is required')
  if (!args.text) throw new Error('progress_update: text is required')

  const chat_id = String(args.chat_id ?? '')
  let text = args.text as string
  const threadId = resolveThreadId(chat_id, args.message_thread_id as string | undefined)
  const key = statusKey(chat_id, threadId)

  assertAllowedChat(chat_id)

  // Truncate to 300 chars
  if (text.length > 300) {
    text = text.slice(0, 299) + '…'
  }

  const now = Date.now()

  // Rate limit: ≥ 20s between calls
  const lastSent = progressUpdateLastSent.get(key)
  if (lastSent != null) {
    const elapsed = now - lastSent
    if (elapsed < 20_000) {
      return {
        content: [
          {
            type: 'text',
            text: JSON.stringify({ ok: false, reason: 'too_soon', retryAfterMs: 20_000 - elapsed }),
          },
        ],
      }
    }
  }

  // Turn cap: max 5 calls per turn
  const turnStart = activeTurnStartedAt.get(key)
  if (turnStart != null) {
    const currentCount = progressUpdateTurnCount.get(key) ?? 0
    if (currentCount >= 5) {
      return {
        content: [
          {
            type: 'text',
            text: JSON.stringify({ ok: false, reason: 'turn_limit' }),
          },
        ],
      }
    }
    progressUpdateTurnCount.set(key, currentCount + 1)
  }

  // Issue #305 Option A — the card-injection path (route a sub-agent's
  // `progress_update` narrative into its row on the parent's pinned card)
  // was retired with the progress card in #1122/#1126: `progressDriver` is
  // permanently null, so `recordSubAgentNarrative` could never fire and the
  // whole `resolveCallingSubagent` → card-inject block was a dead no-op that
  // always fell through here. Removed. Sub-agent progress now surfaces via
  // the `🛠 Worker` activity feed + the model's own in-voice handback, and a
  // `progress_update` call always takes the plain message-send path below.

  // Send plain message (no quote-reply). Single rich-markdown path (#2669):
  // `parseMode:'text'` config opts into a literal plain send; everything
  // else ships raw GFM markdown via sendRichMessage.
  const access = loadAccess()
  const literalText = (access.parseMode ?? 'html') === 'text'

  const sendOpts = {
    ...(threadId != null ? { message_thread_id: threadId } : {}),
  }

  const sent = await robustApiCall(
    (): Promise<{ message_id: number }> =>
      literalText
        // allow-raw-bot-api: literal progress-update send routed through robustApiCall
        ? lockedBot.api.sendMessage(chat_id, text, sendOpts as never)
        : lockedBot.api.sendRichMessage(chat_id, richMessage(text), sendOpts as never),
    { verb: 'sendMessage', chat_id, threadId },
  )

  // Record in sent-message history. RecordOutboundArgs uses `texts`
  // (parallel array to message_ids), not `text` — the singular-name
  // typo silently omitted progress_update outbounds from the history
  // DB. Caught by scripts/check-plugin-references.mjs (TS2561).
  if (HISTORY_ENABLED) {
    recordOutbound({
      chat_id,
      thread_id: threadId ?? null,
      message_ids: [sent.message_id],
      texts: [text],
    })
  }

  progressUpdateLastSent.set(key, now)

  // Issue #203: progress_update is a user-visible signal — tick the
  // silent-gap tracker so it doesn't count as silent time.
  try {
    signalTracker.noteSignal(key, Date.now())
  } catch { /* best-effort signal */ }

  return {
    content: [
      {
        type: 'text',
        text: JSON.stringify({ ok: true, message_id: sent.message_id }),
      },
    ],
  }
}

/**
 * `ask_user` MCP tool. Closes #574.
 *
 * The agent calls `ask_user({ chat_id, question, options[] })`; we
 * post the question to Telegram with one inline-keyboard button per
 * option, store the outstanding prompt in `pendingAskUser`, and
 * return a Promise that resolves when the user taps a button (the
 * callback dispatcher at the bottom of this file calls our resolve)
 * or the TTL fires. Either way, the agent's `tool_call_result` is a
 * structured `AskUserOutcome` it can branch on.
 *
 * Failure modes:
 *   - assertAllowedChat throws → return error to agent, no message sent.
 *   - sendMessage throws → reject the deferred immediately so the
 *     agent doesn't sit forever; map to `{ kind: 'cancelled', reason }`.
 *   - timeout → resolve `{ kind: 'timeout' }`, edit the message to
 *     show "(no response)" so the user knows the prompt expired.
 *   - gateway shutdown / chat-close → resolve `{ kind: 'cancelled' }`
 *     for every outstanding ask in that chat (see
 *     clearAskUserPromptsForChat below).
 */
async function executeAskUser(rawArgs: Record<string, unknown>): Promise<unknown> {
  const args = validateAskUserArgs(rawArgs as unknown as AskUserArgs)
  assertAllowedChat(args.chatId)

  // Resolve thread + reply-to using the same auto-thread heuristic
  // executeReply uses, so an agent that omits message_thread_id still
  // routes into the right forum topic and quotes the user's last
  // inbound message by default.
  const threadId = resolveThreadId(args.chatId, args.threadId)
  let replyTo: number | undefined = args.replyTo
  if (replyTo == null && HISTORY_ENABLED) {
    try {
      const latest = getLatestInboundMessageId(args.chatId, threadId ?? null)
      if (latest != null) replyTo = latest
    } catch (err) {
      process.stderr.write(`telegram gateway: ask_user quote lookup failed: ${(err as Error).message}\n`)
    }
  }

  // Build inline keyboard — one button per option, stacked vertically
  // so each label gets the full chat width on a phone. Telegram
  // supports horizontal pairs, but vertical reads cleanly even on
  // narrow screens.
  const askId = generateAskId()
  const keyboard = new InlineKeyboard()
  for (let i = 0; i < args.options.length; i++) {
    keyboard.text(args.options[i], encodeAskCallback(askId, i))
    if (i < args.options.length - 1) keyboard.row()
  }

  // Send the question. We need the message_id back so we can edit-in-
  // place on resolution / timeout — that's what makes the surface feel
  // alive (button tap turns into "✅ <choice>" inline) rather than a
  // graveyard of unanswered questions in the chat history.
  const sendOpts: Record<string, unknown> = {
    reply_markup: keyboard,
  }
  if (threadId != null) sendOpts.message_thread_id = threadId
  if (replyTo != null) sendOpts.reply_parameters = { message_id: replyTo }

  let messageId: number | null = null
  try {
    // #1075: thread-id-bearing — route through retryWithThreadFallback
    // so a deleted topic still gets the ask_user card on the main chat.
    const sent = await retryWithThreadFallback<{ message_id: number }>(
      robustApiCall,
      (tid) => {
        const opts = { ...sendOpts }
        if (tid == null) delete opts.message_thread_id
        else opts.message_thread_id = tid
        return lockedBot.api.sendRichMessage(args.chatId, richMessage(args.question), opts)
      },
      { threadId, chat_id: args.chatId, verb: 'ask_user.sendMessage' },
    )
    messageId = sent.message_id
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err)
    return { content: [{ type: 'text', text: JSON.stringify({ kind: 'cancelled', reason: `send-failed: ${msg}` }) }] }
  }

  // Open the deferred. The promise resolves either:
  //   1. via the callback dispatcher (user tap), or
  //   2. via the timeout below.
  return new Promise<unknown>((resolveTool) => {
    const timer = setTimeout(() => {
      const entry = pendingAskUser.get(askId)
      pendingAskUser.delete(askId)
      if (!entry) return
      // Edit the question to remove buttons + show timeout state.
      // Best-effort: a failed edit doesn't change the outcome.
      // #1075: edit operates on a message inside the (possibly-deleted)
      // thread — swallow on THREAD_NOT_FOUND so we don't crash on
      // timeout cleanup.
      void swallowingApiCall(
        () =>
          lockedBot.api.editMessageText(
            args.chatId,
            entry.messageId!,
            richMessage(`${args.question}\n\n_⏱ no response within ${Math.round(args.timeoutMs / 1000)}s_`),
          ),
        {
          chat_id: args.chatId,
          verb: 'ask_user.timeout-edit',
          ...(threadId != null ? { threadId } : {}),
        },
      )
      resolveTool({ content: [{ type: 'text', text: JSON.stringify({ kind: 'timeout' } satisfies AskUserOutcome) }] })
    }, args.timeoutMs)

    pendingAskUser.set(askId, {
      options: args.options,
      chatId: args.chatId,
      threadId,
      messageId,
      startedAt: Date.now(),
      timer,
      resolve: (outcome: AskUserOutcome) => {
        // Caller already deleted from map + cleared timer.
        resolveTool({ content: [{ type: 'text', text: JSON.stringify(outcome) }] })
      },
    })
  })
}

/**
 * Cancel every outstanding ask_user in a given chat. Called when the
 * gateway shuts down or when a turn ends without the question being
 * answered (the next user message implicitly invalidates pending
 * prompts — they'd otherwise leak across turns, which is confusing).
 */
function clearAskUserPromptsForChat(chatId: string, reason: string): void {
  for (const [askId, entry] of pendingAskUser.entries()) {
    if (entry.chatId !== chatId) continue
    clearTimeout(entry.timer)
    pendingAskUser.delete(askId)
    entry.resolve({ kind: 'cancelled', reason })
  }
}

/**
 * `send_sticker` MCP tool (#576). Send a Telegram sticker, resolving
 * either a raw file_id or an operator-curated alias from
 * `access.stickers`. Validation lives in the pure
 * `resolveStickerSendArgs` helper; this function is just glue.
 */
async function executeSendSticker(rawArgs: Record<string, unknown>): Promise<unknown> {
  const access = loadAccess()
  const args = resolveStickerSendArgs(rawArgs as unknown as StickerSendArgs, access.stickers ?? {})
  assertAllowedChat(args.chatId)

  // Same auto-thread + auto-reply heuristic as executeReply, so the
  // sticker lands in the right forum topic and quotes the user's
  // last inbound when not explicitly overridden.
  const threadId = resolveThreadId(args.chatId, args.threadId)
  let replyTo: number | undefined = args.replyTo
  if (replyTo == null && HISTORY_ENABLED) {
    try {
      const latest = getLatestInboundMessageId(args.chatId, threadId ?? null)
      if (latest != null) replyTo = latest
    } catch (err) {
      process.stderr.write(`telegram gateway: send_sticker quote lookup failed: ${(err as Error).message}\n`)
    }
  }

  const baseSendOpts: Record<string, unknown> = {}
  if (replyTo != null) baseSendOpts.reply_parameters = { message_id: replyTo }

  // #1075: thread-id-bearing — drop the thread on THREAD_NOT_FOUND so
  // the sticker still lands on the main chat.
  const sent = await retryWithThreadFallback<{ message_id: number }>(
    robustApiCall,
    (tid) => {
      const opts = { ...baseSendOpts }
      if (tid != null) opts.message_thread_id = tid
      return lockedBot.api.sendSticker(args.chatId, args.fileId, opts)
    },
    { threadId, chat_id: args.chatId, verb: 'sendSticker' },
  )
  process.stderr.write(
    `telegram gateway [outbound] ${new Date().toISOString()} path=sticker ` +
    `chat=${args.chatId} msg_id=${sent.message_id} ` +
    `resolution=${args.resolution}${args.aliasName ? ` alias=${args.aliasName}` : ''}\n`,
  )
  return {
    content: [{
      type: 'text',
      text: JSON.stringify({
        kind: 'sent',
        message_id: sent.message_id,
        resolution: args.resolution,
        ...(args.aliasName ? { alias: args.aliasName } : {}),
      }),
    }],
  }
}

/**
 * `send_gif` MCP tool (#576). Send an animated GIF / MP4 / WebM via
 * Telegram's sendAnimation. Accepts file_id or operator-trusted https
 * URL — there is no GIF search; agents pass references they've seen
 * or that the user has shared.
 */
async function executeSendGif(rawArgs: Record<string, unknown>): Promise<unknown> {
  const args = resolveGifSendArgs(rawArgs as unknown as GifSendArgs)
  assertAllowedChat(args.chatId)

  const threadId = resolveThreadId(args.chatId, args.threadId)
  let replyTo: number | undefined = args.replyTo
  if (replyTo == null && HISTORY_ENABLED) {
    try {
      const latest = getLatestInboundMessageId(args.chatId, threadId ?? null)
      if (latest != null) replyTo = latest
    } catch (err) {
      process.stderr.write(`telegram gateway: send_gif quote lookup failed: ${(err as Error).message}\n`)
    }
  }

  const baseSendOpts: Record<string, unknown> = {}
  if (args.caption != null) baseSendOpts.caption = args.caption
  if (replyTo != null) baseSendOpts.reply_parameters = { message_id: replyTo }

  // #1075: thread-id-bearing — drop the thread on THREAD_NOT_FOUND.
  const sent = await retryWithThreadFallback<{ message_id: number }>(
    robustApiCall,
    (tid) => {
      const opts = { ...baseSendOpts }
      if (tid != null) opts.message_thread_id = tid
      return lockedBot.api.sendAnimation(args.chatId, args.animationRef, opts)
    },
    { threadId, chat_id: args.chatId, verb: 'sendAnimation' },
  )
  process.stderr.write(
    `telegram gateway [outbound] ${new Date().toISOString()} path=gif ` +
    `chat=${args.chatId} msg_id=${sent.message_id} ref_kind=${args.refKind}\n`,
  )
  return {
    content: [{
      type: 'text',
      text: JSON.stringify({
        kind: 'sent',
        message_id: sent.message_id,
        ref_kind: args.refKind,
      }),
    }],
  }
}

/**
 * Telegraph publishing helper (#579). Lazy-creates a Telegraph
 * account on first use and caches the access_token at
 * `<STATE_DIR>/telegraph-account.json`. Returns the published URL
 * on success or null on any failure (caller falls back to normal
 * chunked HTML sending).
 *
 * Caller must already have decided that publishing is desired
 * (text > threshold AND telegraph.enabled). This function is the
 * I/O wrapper around the pure helpers in telegraph.ts.
 */
async function publishToTelegraph(
  text: string,
  shortName: string,
  authorName: string | undefined,
): Promise<string | null> {
  const accountPath = join(STATE_DIR, 'telegraph-account.json')
  let account: TelegraphAccount | null = null
  try {
    if (existsSync(accountPath)) {
      const raw = readFileSync(accountPath, 'utf-8')
      const parsed = JSON.parse(raw) as Partial<TelegraphAccount>
      if (parsed.shortName && parsed.accessToken) {
        account = parsed as TelegraphAccount
      }
    }
  } catch (err) {
    process.stderr.write(`telegram gateway: telegraph cache read failed: ${(err as Error).message}\n`)
  }

  if (account == null) {
    const created = await createTelegraphAccount({ shortName, authorName })
    if (!created.ok) {
      process.stderr.write(`telegram gateway: telegraph createAccount failed: ${created.reason}\n`)
      return null
    }
    account = created.value
    try {
      mkdirSync(STATE_DIR, { recursive: true, mode: 0o700 })
      writeFileSync(accountPath, JSON.stringify(account, null, 2), { mode: 0o600 })
    } catch (err) {
      process.stderr.write(`telegram gateway: telegraph cache write failed: ${(err as Error).message}\n`)
      // proceed — we have the token in memory for this turn at least
    }
  }

  const title = deriveTelegraphTitle(text)
  const content = markdownToTelegraphNodes(text)
  const page = await createTelegraphPage({
    accessToken: account.accessToken,
    title,
    content,
    authorName,
  })
  if (!page.ok) {
    process.stderr.write(`telegram gateway: telegraph createPage failed: ${page.reason}\n`)
    return null
  }
  process.stderr.write(`telegram gateway: telegraph published url=${page.value.url} title=${JSON.stringify(title)} chars=${text.length}\n`)
  return page.value.url
}

/**
 * Build the inline keyboard for the agent-initiated vault-save approval card.
 * Issue #969 P1a. Callback prefix `vrs:` (vault-request-save).
 *
 * Buttons must fit Telegram's 64-byte callback_data limit. Stage IDs are
 * 8 hex chars (32 bits of entropy), so each callback comfortably fits.
 */
function buildVaultRequestSaveKeyboard(stageId: string): { inline_keyboard: Array<Array<{ text: string; callback_data: string }>> } {
  return {
    inline_keyboard: [
      [
        { text: '✅ Save once', callback_data: `vrs:save:${stageId}` },
        { text: '🚫 Discard', callback_data: `vrs:discard:${stageId}` },
      ],
      [
        { text: '✏️ Rename', callback_data: `vrs:rename:${stageId}` },
      ],
    ],
  }
}

function renderVaultRequestSaveCard(req: PendingVaultRequestSave, agentSlug: string): string {
  const lines: string[] = []
  lines.push(`🔐 **${escapeHtmlForTg(agentSlug)}** wants to save a secret`)
  lines.push(`key: \`${req.key}\``)
  if (req.why && req.why.length > 0) {
    lines.push(`why: _${escapeHtmlForTg(req.why)}_`)
  }
  lines.push('')
  lines.push(`_Tap Save to write to the host vault, Rename to change the key name, or Discard to drop it. The value is held in this chat's gateway memory until you decide._`)
  return lines.join('\n')
}

/**
 * `vault_request_save` tool — agent surfaces an approval card asking
 * the user to confirm saving a secret. The value is staged here and
 * written to vault only on user tap. See #969 P1a.
 */
async function executeVaultRequestSave(args: Record<string, unknown>): Promise<{ content: Array<{ type: string; text: string }> }> {
  const chat_id = String(args.chat_id ?? '')
  if (!chat_id) throw new Error('vault_request_save: chat_id is required')
  const key = args.key as string
  if (!key || typeof key !== 'string') throw new Error('vault_request_save: key is required')
  const value = args.value as string
  if (typeof value !== 'string' || value.length === 0) {
    throw new Error('vault_request_save: value is required and must be a non-empty string')
  }
  const why = typeof args.why === 'string' ? args.why : undefined
  const kindRaw = typeof args.kind === 'string' ? args.kind : 'string'
  if (kindRaw !== 'string' && kindRaw !== 'binary') {
    throw new Error('vault_request_save: kind must be "string" or "binary"')
  }
  assertAllowedChat(chat_id)

  // Validate slug shape — vault keys must match a tight charset so the
  // host CLI hints render cleanly and reference resolution stays
  // predictable. Includes `/` so the canonical namespaced shape
  // (`fatsecret/client_id`, `mff/agent-private-key`, ...) is
  // accepted — issue #1047. The broker itself has no key regex
  // (just `z.string().min(1)` in protocol.ts); this gateway-side
  // gate is a UX guard, not a security boundary.
  if (!VAULT_KEY_REGEX.test(key)) {
    throw new Error(`vault_request_save: key must match ${VAULT_KEY_REGEX_LABEL}`)
  }

  const agentSlug = process.env.SWITCHROOM_AGENT_NAME || 'agent'

  // Stage the request server-side. The value never leaves gateway memory
  // until the user approves.
  const stageId = randomBytes(4).toString('hex')
  const pending: PendingVaultRequestSave = {
    agent: agentSlug,
    chat_id,
    key,
    kind: kindRaw,
    value,
    why,
    staged_at: Date.now(),
  }
  pendingVaultRequestSaves.set(stageId, pending)
  sweepPendingVaultRequestSaves()

  // Send the approval card. #1075: route through retryWithThreadFallback
  // so a deleted topic still lands the card on the main chat instead of
  // crashing the tool call.
  const text = renderVaultRequestSaveCard(pending, agentSlug)
  const threadId = args.message_thread_id != null ? Number(args.message_thread_id) : undefined
  // Remember the agent's working topic so the save-outcome inbound resumes in it.
  if (threadId != null) pending.threadId = threadId
  const sent = await retryWithThreadFallback<{ message_id: number }>(
    robustApiCall,
    (tid) =>
      lockedBot.api.sendRichMessage(chat_id, richMessage(text), {
        reply_markup: buildVaultRequestSaveKeyboard(stageId),
        ...(tid != null && Number.isFinite(tid) ? { message_thread_id: tid } : {}),
      }),
    { threadId, chat_id, verb: 'vault_request_save.card' },
  )
  pending.card_message_id = sent.message_id

  return {
    content: [
      {
        type: 'text',
        text: `vault_request_save: card sent (stage_id=${stageId}, key=${key}). The user must tap a button before the secret is persisted; do not assume success until you see the user's next message confirming the outcome.`,
      },
    ],
  }
}

// ─── #2045 request_secret — agent asks the operator to PROVIDE a secret ───
//
// The third member of the agent-vault tool family. `vault_request_save`
// = agent HAS a value and asks to save it; `vault_request_access` = agent
// needs read access to an existing key; `request_secret` = agent needs a
// value it does NOT have. The operator provides it through a secure card:
// they tap [Provide securely], send the value once, and the gateway deletes
// the message instantly + writes it straight to the vault. The raw value is
// never recorded to history, never logged, never returned to the agent —
// the agent only ever references `vault:<key>`. This removes the reason an
// agent would ever ask a user to paste a secret as a normal chat message.
interface PendingSecretRequest {
  agent: string
  chat_id: string
  key: string
  reason?: string
  staged_at: number
  card_message_id?: number
  /** Supergroup forum topic the agent was working in — carried into the
   *  provide/decline/fail outcome inbounds so the resumed reply lands back
   *  in that topic, not General. */
  threadId?: number
}
// stageId -> request (lives until tapped or TTL).
const pendingSecretRequests = new Map<string, PendingSecretRequest>()
// chat_id -> the armed capture: the operator's NEXT message in this chat is
// the value for `key`. Set when [Provide securely] is tapped.
interface ArmedSecretCapture { key: string; agent: string; stageId: string; armed_at: number; threadId?: number }
const armedSecretCaptures = new Map<string, ArmedSecretCapture>()
const PENDING_SECRET_REQUEST_TTL_MS = 30 * 60_000 // card lifetime
const ARMED_SECRET_CAPTURE_TTL_MS = 10 * 60_000   // window to send the value after tapping

function sweepSecretRequests(): void {
  const now = Date.now()
  for (const [k, v] of pendingSecretRequests) {
    if (now - v.staged_at > PENDING_SECRET_REQUEST_TTL_MS) pendingSecretRequests.delete(k)
  }
  for (const [k, v] of armedSecretCaptures) {
    if (now - v.armed_at > ARMED_SECRET_CAPTURE_TTL_MS) armedSecretCaptures.delete(k)
  }
}

function buildSecretRequestKeyboard(stageId: string): { inline_keyboard: Array<Array<{ text: string; callback_data: string }>> } {
  return {
    inline_keyboard: [
      [
        { text: '🔐 Provide securely', callback_data: `vsp:provide:${stageId}` },
        { text: '🚫 Decline', callback_data: `vsp:decline:${stageId}` },
      ],
    ],
  }
}

function renderSecretRequestCard(req: PendingSecretRequest): string {
  const lines: string[] = [
    `🔒 **${escapeHtmlForTg(req.agent)}** needs a secret:`,
    `\`${req.key}\``,
  ]
  if (req.reason) lines.push(`_${escapeHtmlForTg(req.reason)}_`)
  lines.push(
    '',
    'Tap **Provide securely**, then send the value as your next message. I’ll delete it instantly and store it in the vault — it is never shown in chat or to the agent.',
  )
  return lines.join('\n')
}

/**
 * `request_secret` tool — agent surfaces a card asking the operator to
 * provide a missing secret. No `value` arg: the value arrives via secure
 * capture (the operator's next message after they tap [Provide securely]).
 */
async function executeRequestSecret(args: Record<string, unknown>): Promise<{ content: Array<{ type: string; text: string }> }> {
  const chat_id = String(args.chat_id ?? '')
  if (!chat_id) throw new Error('request_secret: chat_id is required')
  const key = args.key as string
  if (!key || typeof key !== 'string') throw new Error('request_secret: key is required')
  const reason = typeof args.reason === 'string' ? args.reason : undefined
  assertAllowedChat(chat_id)
  if (!VAULT_KEY_REGEX.test(key)) {
    throw new Error(`request_secret: key must match ${VAULT_KEY_REGEX_LABEL}`)
  }
  const agentSlug = process.env.SWITCHROOM_AGENT_NAME || 'agent'

  // Dedupe: one open request per (chat, key). Drop any prior stage for
  // the same target so the operator never sees stacked cards.
  for (const [sid, p] of pendingSecretRequests) {
    if (p.chat_id === chat_id && p.key === key) pendingSecretRequests.delete(sid)
  }

  const stageId = randomBytes(4).toString('hex')
  const pending: PendingSecretRequest = { agent: agentSlug, chat_id, key, reason, staged_at: Date.now() }
  pendingSecretRequests.set(stageId, pending)
  sweepSecretRequests()

  const text = renderSecretRequestCard(pending)
  const threadId = args.message_thread_id != null ? Number(args.message_thread_id) : undefined
  // Remember the agent's working topic so the provide/decline/fail inbound resumes in it.
  if (threadId != null) pending.threadId = threadId
  const sent = await retryWithThreadFallback<{ message_id: number }>(
    robustApiCall,
    (tid) =>
      lockedBot.api.sendRichMessage(chat_id, richMessage(text), {
        reply_markup: buildSecretRequestKeyboard(stageId),
        ...(tid != null && Number.isFinite(tid) ? { message_thread_id: tid } : {}),
      }),
    { threadId, chat_id, verb: 'request_secret.card' },
  )
  pending.card_message_id = sent.message_id

  return {
    content: [
      {
        type: 'text',
        text: `request_secret: card sent (stage_id=${stageId}, key=${key}). END YOUR TURN now and wait — a fresh inbound message arrives once the operator provides (or declines) the secret. Do NOT ask them to paste it as a normal message; the card handles it securely.`,
      },
    ],
  }
}

/**
 * Write a provided secret to the vault. Mirrors the vrs:save write branch:
 * posture-attested broker put under telegram-id mode (no passphrase), else
 * the cached-passphrase CLI path. Returns the same {ok, output} shape.
 */
async function writeRequestedSecret(key: string, value: string, chat_id: string): Promise<{ ok: boolean; output: string }> {
  if (VAULT_APPROVAL_AUTH_MODE === 'telegram-id') {
    return await defaultVaultWritePosture(key, value)
  }
  const cached = vaultPassphraseCache.get(chat_id)
  if (!cached || cached.expiresAt <= Date.now()) {
    return { ok: false, output: 'VAULT-LOCKED: run /vault unlock once in this chat, then have the agent re-request.' }
  }
  return defaultVaultWrite(key, value, cached.passphrase)
}

/**
 * Secure value capture. Called early in handleInbound: if this chat is
 * armed (operator tapped [Provide securely]), the inbound message IS the
 * secret value. Delete it, write to the vault under the requested key, tell
 * the agent it's available, and STOP — never record / log / forward the raw
 * value. Returns true if it consumed the message (caller must return).
 */
async function captureProvidedSecret(
  ctx: Context,
  chat_id: string,
  msgId: number | undefined,
  value: string,
): Promise<boolean> {
  const armed = armedSecretCaptures.get(chat_id)
  if (!armed || Date.now() - armed.armed_at > ARMED_SECRET_CAPTURE_TTL_MS) {
    if (armed) armedSecretCaptures.delete(chat_id)
    return false
  }
  armedSecretCaptures.delete(chat_id)
  const pending = pendingSecretRequests.get(armed.stageId)
  pendingSecretRequests.delete(armed.stageId)

  // Delete the raw message FIRST — surfaces a warning if it fails.
  if (msgId != null) await deleteSensitiveMessage(chat_id, msgId, 'provided secret value')

  const write = await writeRequestedSecret(armed.key, value, chat_id)
  if (!write.ok) {
    const parsed = parseVaultCliError(write.output)
    const rendered = renderVaultCliError(parsed, { verb: 'save', key: armed.key })
    const body = rendered.suppressRaw ? rendered.html : `⚠️ vault write failed:\n\`\`\`\n${write.output}\n\`\`\``
    await switchroomReply(ctx, `${body}\n\n_The secret was NOT saved. The agent can re-request with \`request_secret\`._`, { html: true })
    // Wake the agent too (review #2047 finding #3): it ended its turn
    // waiting for a synthetic inbound; without this it stalls silently.
    const fts = Date.now()
    const failMsg: InboundMessage = {
      type: 'inbound',
      chatId: chat_id,
      ...(armed.threadId != null ? { threadId: armed.threadId } : {}),
      messageId: fts,
      user: 'vault-broker',
      userId: 0,
      ts: fts,
      text: `⚠️ The secret you requested for \`vault:${armed.key}\` could NOT be saved (vault write failed). Do not assume it is available; tell the operator or try request_secret again.`,
      meta: {
        source: 'secret_provide_failed',
        agent: armed.agent,
        ...(armed.threadId != null ? { message_thread_id: String(armed.threadId) } : {}),
        key: armed.key,
        stage_id: armed.stageId,
      },
    }
    deliverResumeSyntheticOrBuffer(armed.agent, failMsg)
    return true
  }

  await switchroomReply(
    ctx,
    `✅ saved as \`vault:${escapeHtmlForTg(armed.key)}\` (masked: \`${escapeHtmlForTg(maskToken(value))}\`). The agent can now reference it.`,
    { html: true },
  )

  // Resume the requesting agent with a synthetic inbound — mirrors the
  // vault_grant_approved injection. The value is NOT included; only the key.
  const ts = Date.now()
  const synthetic: InboundMessage = {
    type: 'inbound',
    chatId: chat_id,
    ...(armed.threadId != null ? { threadId: armed.threadId } : {}),
    messageId: ts,
    user: 'vault-broker',
    userId: 0,
    ts,
    text:
      `✅ Operator provided the secret you requested. It is saved as ` +
      `\`vault:${armed.key}\` — reference it the usual way. Resume the task ` +
      `that was waiting on this credential. Do NOT ask the operator to paste it.`,
    meta: {
      source: 'secret_provided',
      agent: armed.agent,
      ...(armed.threadId != null ? { message_thread_id: String(armed.threadId) } : {}),
      key: armed.key,
      stage_id: armed.stageId,
    },
  }
  const delivered = deliverResumeSyntheticOrBuffer(armed.agent, synthetic)
  process.stderr.write(
    `telegram gateway: secret_provided injection agent=${armed.agent} key=${armed.key} stage=${armed.stageId} delivered=${delivered}\n`,
  )
  return true
}

/**
 * `vsp:` callbacks — agent-requested-secret card.
 *   vsp:provide:<stageId>  — arm capture: operator's next message is the value
 *   vsp:decline:<stageId>  — drop the request; tell the agent it was declined
 */
async function handleSecretRequestCallback(ctx: Context, data: string): Promise<void> {
  const senderId = String(ctx.from?.id ?? '')
  const access = loadAccess()
  if (!access.allowFrom.includes(senderId)) {
    await ctx.answerCallbackQuery({ text: 'Not authorized.' }).catch(() => {})
    return
  }
  const parts = data.split(':')
  const action = parts[1]
  const stageId = parts[2] ?? ''
  const pending = pendingSecretRequests.get(stageId)
  if (!pending) {
    await ctx.answerCallbackQuery({ text: 'This request expired.' }).catch(() => {})
    return
  }

  if (action === 'provide') {
    armedSecretCaptures.set(pending.chat_id, {
      key: pending.key,
      agent: pending.agent,
      stageId,
      armed_at: Date.now(),
      ...(pending.threadId != null ? { threadId: pending.threadId } : {}),
    })
    await ctx.answerCallbackQuery({ text: 'Send the value now — it auto-deletes.' }).catch(() => {})
    if (pending.card_message_id != null) {
      await ctx.api
        .editMessageText(
          pending.chat_id,
          pending.card_message_id,
          richMessage(`🔐 Send the value for \`${pending.key}\` as your next message — a single message, exactly as-is (don't add other text). I’ll delete it instantly and store it in the vault.`),
          { reply_markup: { inline_keyboard: [] } },
        )
        .catch(() => {})
    }
    return
  }

  if (action === 'decline') {
    pendingSecretRequests.delete(stageId)
    armedSecretCaptures.delete(pending.chat_id)
    await ctx.answerCallbackQuery({ text: 'Declined.' }).catch(() => {})
    if (pending.card_message_id != null) {
      await ctx.api
        .editMessageText(pending.chat_id, pending.card_message_id, richMessage(`🚫 Declined — \`${pending.key}\` not provided.`), {
          reply_markup: { inline_keyboard: [] },
        })
        .catch(() => {})
    }
    // Tell the agent so it stops waiting.
    const ts = Date.now()
    const synthetic: InboundMessage = {
      type: 'inbound',
      chatId: pending.chat_id,
      ...(pending.threadId != null ? { threadId: pending.threadId } : {}),
      messageId: ts,
      user: 'vault-broker',
      userId: 0,
      ts,
      text: `🚫 Operator declined your request for \`vault:${pending.key}\`. Proceed without it or ask how they'd like to handle the task.`,
      meta: {
        source: 'secret_declined',
        agent: pending.agent,
        ...(pending.threadId != null ? { message_thread_id: String(pending.threadId) } : {}),
        key: pending.key,
        stage_id: stageId,
      },
    }
    deliverResumeSyntheticOrBuffer(pending.agent, synthetic)
    return
  }

  await ctx.answerCallbackQuery().catch(() => {})
}

/**
 * Issue #1012 — render the agent-initiated ACL request approval card.
 * Same visual language as the recent-denials one-tap allow (#969 P2b)
 * but with the agent's own reason and an explicit [Deny] path.
 */
function buildVaultRequestAccessKeyboard(stageId: string): { inline_keyboard: Array<Array<{ text: string; callback_data: string }>> } {
  return {
    inline_keyboard: [
      [
        { text: '✅ Approve', callback_data: `vra:approve:${stageId}` },
        { text: '🚫 Deny', callback_data: `vra:deny:${stageId}` },
      ],
    ],
  }
}

/**
 * `vault_request_access` tool — agent surfaces an approval card asking
 * the operator to grant a vault ACL it doesn't yet have. See #1012.
 * Auth boundary: only operators on the gateway allowFrom list can tap;
 * the agent itself can only REQUEST.
 */
async function executeVaultRequestAccess(args: Record<string, unknown>): Promise<{ content: Array<{ type: string; text: string }> }> {
  const chat_id = String(args.chat_id ?? '')
  if (!chat_id) throw new Error('vault_request_access: chat_id is required')
  const key = args.key as string
  if (!key || typeof key !== 'string') throw new Error('vault_request_access: key is required')
  if (!VAULT_KEY_REGEX.test(key)) {
    throw new Error(`vault_request_access: key must match ${VAULT_KEY_REGEX_LABEL}`)
  }
  const scopeRaw = typeof args.scope === 'string' ? args.scope : 'read'
  if (scopeRaw !== 'read' && scopeRaw !== 'write') {
    throw new Error('vault_request_access: scope must be "read" or "write"')
  }
  // Accept `why` as an alias for `reason`: the sibling tool
  // vault_request_save uses `why`, and agents cross-contaminate the two
  // schemas — without the alias the rationale silently drops off the
  // approval card and the operator sees "why: not provided".
  const reason =
    typeof args.reason === 'string' ? args.reason : typeof args.why === 'string' ? args.why : undefined
  // Duration: accept a "30d" / "12h" string from the agent OR default
  // to 30 days. Cap at 90 days — beyond that the operator should use
  // the host CLI and pick the lifetime explicitly. Refuse "never"
  // requests outright; agent-initiated grants must have a sunset.
  let ttl_seconds = 30 * 24 * 60 * 60
  const durRaw = args.duration
  if (typeof durRaw === 'string' && durRaw.length > 0) {
    const m = durRaw.match(/^(\d+)([dh])$/)
    if (!m) {
      throw new Error('vault_request_access: duration must look like "30d" or "12h"')
    }
    const n = Number(m[1])
    const unit = m[2]
    const parsed = unit === 'd' ? n * 86400 : n * 3600
    const NINETY_DAYS = 90 * 86400
    if (parsed <= 0 || parsed > NINETY_DAYS) {
      throw new Error('vault_request_access: duration must be > 0 and <= 90d')
    }
    ttl_seconds = parsed
  }
  assertAllowedChat(chat_id)

  const agentSlug = process.env.SWITCHROOM_AGENT_NAME || 'agent'

  // Fix B (#1487 follow-up): if this agent's STANDING ACL already
  // covers the key, do NOT render a card or mint a grant. Minting
  // writes a `.vault-token` that — pre-#1487 — *shadowed* the standing
  // ACL (the exact gymbro trap) and is simply redundant post-#1487.
  // Determine coverage AUTHORITATIVELY by probing the broker AS THIS
  // AGENT (no-token list over the per-agent socket — path-as-identity;
  // the gateway runs in the agent's container so the broker attributes
  // it to this agent). NOT a gateway-side config read: the gateway can
  // see newer config than the broker has loaded, so a config-derived
  // "covered" could be wrong where the broker still denies. `list`
  // returns only ACL-visible key NAMES — never secret values. Read
  // scope only: schedule.secrets[] confers read, not write.
  if (scopeRaw === 'read') {
    try {
      const visible = await listViaBroker()
      if (visible !== null && visible.includes(key)) {
        return {
          content: [
            {
              type: 'text',
              text:
                `vault_request_access: '${key}' is ALREADY covered by ${agentSlug}'s ` +
                `standing ACL (schedule.secrets[]). No approval card or grant is needed — ` +
                `read it directly: \`switchroom vault get ${key}\`. Do NOT request a grant ` +
                `for this key (a minted token would shadow the standing ACL). If a read ` +
                `still returns VAULT-BROKER-DENIED, the broker likely needs a restart to ` +
                `pick up a recent config change — tell the operator; don't re-request.`,
            },
          ],
        }
      }
    } catch {
      // Probe failed (broker unreachable / transient): fall through to
      // the normal card flow. Fail-open is correct here — a redundant
      // card is harmless; suppressing a needed card is not.
    }
  }

  const stageId = randomBytes(4).toString('hex')
  const pending: PendingVaultRequestAccess = {
    agent: agentSlug,
    chat_id,
    key,
    scope: scopeRaw,
    reason,
    ttl_seconds,
    staged_at: Date.now(),
  }
  pendingVaultRequestAccesses.set(stageId, pending)
  sweepPendingVaultRequestAccesses()

  const text = renderVaultRequestAccessCard(pending)
  const threadId = args.message_thread_id != null ? Number(args.message_thread_id) : undefined
  // Remember the agent's working topic so the grant-outcome inbound resumes in it.
  if (threadId != null) pending.threadId = threadId
  // #1075: deleted-topic safe — fall back to main chat.
  const sent = await retryWithThreadFallback<{ message_id: number }>(
    robustApiCall,
    (tid) =>
      lockedBot.api.sendRichMessage(chat_id, richMessage(text), {
        reply_markup: buildVaultRequestAccessKeyboard(stageId),
        ...(tid != null && Number.isFinite(tid) ? { message_thread_id: tid } : {}),
      }),
    { threadId, chat_id, verb: 'vault_request_access.card' },
  )
  pending.card_message_id = sent.message_id

  return {
    content: [
      {
        type: 'text',
        text: `vault_request_access: card sent (stage_id=${stageId}, key=${key}, scope=${scopeRaw}). Wait for the operator to tap Approve or Deny — do not retry the vault read until you see a confirmation message. If the card times out (10 min) you can re-request.`,
      },
    ],
  }
}

async function executeReact(args: Record<string, unknown>): Promise<unknown> {
  if (!args.chat_id) throw new Error('react: chat_id is required')
  if (!args.message_id) throw new Error('react: message_id is required')
  if (!args.emoji) throw new Error('react: emoji is required')
  assertAllowedChat(String(args.chat_id ?? ''))
  await lockedBot.api.setMessageReaction(String(args.chat_id ?? ''), Number(args.message_id), [
    { type: 'emoji', emoji: args.emoji as ReactionTypeEmoji['emoji'] },
  ])
  return { content: [{ type: 'text', text: 'reacted' }] }
}

async function executeDownloadAttachment(args: Record<string, unknown>): Promise<unknown> {
  if (!args.file_id) throw new Error('download_attachment: file_id is required')
  const file_id = String(args.file_id)
  // Validate file_id format — Telegram file IDs are alphanumeric with dashes/underscores
  if (!/^[\w-]{10,200}$/.test(file_id)) {
    throw new Error('download_attachment: invalid file_id format')
  }
  const file = await bot.api.getFile(file_id)
  if (!file.file_path) throw new Error('Telegram returned no file_path — file may have expired')
  // Build download URL — token is embedded but NEVER included in error messages.
  // Bounded fetch (30s) — without a timeout, the agent's tool_call hangs
  // indefinitely on a stalled CDN connection.
  const downloadUrl = `https://api.telegram.org/file/bot${TOKEN}/${file.file_path}`
  let res: Response
  try {
    res = await fetch(downloadUrl, { signal: AbortSignal.timeout(30_000) })
  } catch (err) {
    // Sanitize: never leak the token in network error messages
    throw new Error(`download failed: network error`)
  }
  if (!res.ok) throw new Error(`download failed: HTTP ${res.status}`)
  const buf = Buffer.from(await res.arrayBuffer())
  const dlPath = buildAttachmentPath({
    inboxDir: INBOX_DIR,
    telegramFilePath: file.file_path,
    fileUniqueId: file.file_unique_id,
    now: Date.now(),
  })
  mkdirSync(INBOX_DIR, { recursive: true, mode: 0o700 })
  assertInsideInbox(INBOX_DIR, dlPath)
  writeFileSync(dlPath, buf, { mode: 0o600 })
  return { content: [{ type: 'text', text: dlPath }] }
}

async function executeEditMessage(args: Record<string, unknown>): Promise<unknown> {
  if (!args.chat_id) throw new Error('edit_message: chat_id is required')
  if (!args.message_id) throw new Error('edit_message: message_id is required')
  if (args.text == null || args.text === '') throw new Error('edit_message: text is required and cannot be empty')
  assertAllowedChat(String(args.chat_id ?? ''))
  const editAccess = loadAccess()
  const editFormat = (args.format as string | undefined) ?? (editAccess.parseMode ?? 'html')
  // Single rich-markdown path (#2669): `format:'text'` edits as a literal
  // plain string; everything else edits via the rich-markdown path.
  const editLiteralText = editFormat === 'text'
  // Match the reply path: repair JSON-escape bungles, then promote lone prose
  // paragraph breaks for the rich path. A literal-text edit (`format:'text'`)
  // skips paragraph normalization — it must edit byte-for-byte as given.
  let editRawText = repairEscapedWhitespace(args.text as string)
  if (!editLiteralText) editRawText = normalizeParagraphBreaks(editRawText)
  // Outbound secret scrub (#2044): an edit must not re-introduce a raw
  // secret into a live bubble or the history row. Mask before scrub/send.
  editRawText = redactOutboundText(editRawText, 'edit_message')
  // Fleet-wide consistent formatting (same order as the reply path: redact
  // first so secrets are matched literally, then normalize, then spacers on
  // the rich path only).
  if (!editLiteralText) editRawText = addParagraphSpacers(stripExcessBold(normalizePunctuation(editRawText)))
  // Voice scrub (#1683): same em-dash scrub as the reply path. Edits
  // are how silent-anchor and progress-update mutate already-sent
  // bubbles, so without this an edit can re-introduce dashes the
  // original send had scrubbed out.
  {
    const scrub = scrubVoice(editRawText)
    if (scrub.replaced > 0) {
      editRawText = scrub.scrubbed
      emitRuntimeMetric({
        kind: 'voice_scrub_applied',
        chatKey: statusKey(String(args.chat_id ?? ''), undefined),
        replaced: scrub.replaced,
        site: 'edit_message',
      })
    }
  }
  const edited = await robustApiCall(
    () => lockedBot.api.editMessageText(
      String(args.chat_id ?? ''), Number(args.message_id),
      editLiteralText ? editRawText : richMessage(editRawText),
    ),
  )
  const id = typeof edited === 'object' && edited ? (edited as any).message_id : args.message_id
  if (HISTORY_ENABLED) {
    try {
      recordEdit({ chat_id: String(args.chat_id ?? ''), message_id: Number(args.message_id), text: args.text as string })
    } catch (err) {
      process.stderr.write(`telegram gateway: history recordEdit failed: ${err}\n`)
    }
  }
  return { content: [{ type: 'text', text: `edited (id: ${id})` }] }
}

async function executeSendTyping(args: Record<string, unknown>): Promise<unknown> {
  if (!args.chat_id) throw new Error('send_typing: chat_id is required')
  const stChatId = String(args.chat_id ?? '')
  assertAllowedChat(stChatId)
  // #273: granular chat actions. Default 'typing' preserves the
  // existing tool semantics; agents can opt in to upload_document,
  // record_voice, etc. so the indicator the user sees matches what
  // the agent is actually doing. Reject unsupported strings up front
  // — a silent passthrough would surface as 400 BAD_REQUEST in
  // sendChatAction, which is harder to diagnose.
  const rawAction = args.action
  let action: ChatAction = 'typing'
  if (typeof rawAction === 'string' && rawAction.length > 0) {
    if (!CHAT_ACTION_WHITELIST.has(rawAction as ChatAction)) {
      throw new Error(
        `send_typing: action="${rawAction}" is not in Telegram's chat-action whitelist. ` +
        `Allowed: ${Array.from(CHAT_ACTION_WHITELIST).join(', ')}`,
      )
    }
    action = rawAction as ChatAction
  }
  // PR3 supergroup-mode: resolve thread from args or fall back to the
  // last-seen thread for this chat so the indicator lands in the topic
  // the agent is working in (rather than the chat root).
  const stThreadId = resolveThreadId(stChatId, args.message_thread_id as string | number | undefined) ?? null
  startTypingLoop(stChatId, stThreadId, action)
  setTimeout(() => stopTypingLoop(stChatId, stThreadId), 30000)
  for (const [key, ctrl] of activeStatusReactions.entries()) {
    if (key.startsWith(`${stChatId}:`)) ctrl.setTool()
  }
  return { content: [{ type: 'text', text: `${action} indicator sent (auto-refreshes every 4s, stops after 30s or next reply)` }] }
}

async function executePinMessage(args: Record<string, unknown>): Promise<unknown> {
  if (!args.chat_id) throw new Error('pin_message: chat_id is required')
  if (!args.message_id) throw new Error('pin_message: message_id is required')
  const pinChatId = String(args.chat_id ?? '')
  assertAllowedChat(pinChatId)
  // #1075: wrap through robustApiCall so flood-wait / transient network
  // errors are retried. THREAD_NOT_FOUND on a stale topic surfaces to the
  // agent as a tool-error — pinning a vanished message is genuinely a
  // failure the agent should see.
  await robustApiCall(
    () => lockedBot.api.pinChatMessage(pinChatId, Number(args.message_id)),
    { chat_id: pinChatId, verb: 'pin_message' },
  )
  return { content: [{ type: 'text', text: `pinned message ${args.message_id}` }] }
}

async function executeDeleteMessage(args: Record<string, unknown>): Promise<unknown> {
  if (!args.chat_id) throw new Error('delete_message: chat_id is required')
  if (!args.message_id) throw new Error('delete_message: message_id is required')
  const delChatId = String(args.chat_id ?? '')
  const delMessageId = Number(args.message_id)
  assertAllowedChat(delChatId)
  await robustApiCall(() => lockedBot.api.deleteMessage(delChatId, delMessageId), { chat_id: delChatId })
  if (HISTORY_ENABLED) {
    try { deleteFromHistory({ chat_id: delChatId, message_id: delMessageId }) } catch (err) {
      process.stderr.write(`telegram gateway: history deleteFromHistory failed: ${err}\n`)
    }
  }
  return { content: [{ type: 'text', text: `deleted message ${delMessageId}` }] }
}

async function executeForwardMessage(args: Record<string, unknown>): Promise<unknown> {
  if (!args.chat_id) throw new Error('forward_message: chat_id is required')
  if (!args.from_chat_id) throw new Error('forward_message: from_chat_id is required')
  if (!args.message_id) throw new Error('forward_message: message_id is required')
  const fwdChatId = String(args.chat_id ?? '')
  const fwdFromChatId = args.from_chat_id as string
  const fwdMsgId = Number(args.message_id)
  assertAllowedChat(fwdChatId)
  const threadId = resolveThreadId(fwdChatId, args.message_thread_id as string | undefined)
  const fwd = await robustApiCall(
    () => lockedBot.api.forwardMessage(fwdChatId, fwdFromChatId, fwdMsgId, {
      ...(threadId != null ? { message_thread_id: threadId } : {}),
    }),
    { threadId, chat_id: fwdChatId },
  )
  if (HISTORY_ENABLED) {
    try {
      recordOutbound({
        chat_id: fwdChatId,
        thread_id: threadId ?? null,
        message_ids: [fwd.message_id],
        texts: [`(forwarded from ${fwdFromChatId}/${fwdMsgId})`],
      })
    } catch (err) {
      process.stderr.write(`telegram gateway: history recordOutbound (forward) failed: ${err}\n`)
    }
  }
  return { content: [{ type: 'text', text: `forwarded (id: ${fwd.message_id})` }] }
}

async function executeGetRecentMessages(args: Record<string, unknown>): Promise<unknown> {
  if (!HISTORY_ENABLED) {
    return {
      content: [{ type: 'text', text: 'history capture is disabled — set historyEnabled: true in access.json and restart' }],
      isError: true,
    }
  }
  if (!args.chat_id) throw new Error('get_recent_messages: chat_id is required')
  const chat_id = String(args.chat_id ?? '')
  assertAllowedChat(chat_id)
  const rawThread = args.message_thread_id as string | undefined
  let thread_id: number | null | undefined
  if (rawThread === undefined) thread_id = undefined
  else if (rawThread === '' || rawThread === '0' || rawThread === 'null') thread_id = null
  else thread_id = Number(rawThread)
  const limit = args.limit != null ? Number(args.limit) : 10
  const before_message_id = args.before_message_id != null ? Number(args.before_message_id) : undefined

  const rows = queryHistory({ chat_id, thread_id, limit, before_message_id })
  const summary = rows
    .map(r => {
      const who = r.role === 'user' ? r.user ?? 'user' : 'assistant'
      const time = new Date(r.ts * 1000).toISOString()
      const attach = r.attachment_kind ? ` [${r.attachment_kind}]` : ''
      // Match server.ts get_recent_messages format exactly — both code paths
      // serve the same MCP tool, so the agent's parsing must not depend on
      // which entry point handled the call. See issue #119 for replyCtx;
      // reaction tag added in #297 with the server.ts format as canonical.
      const replyCtx = r.reply_to_message_id != null
        ? ` ↪️#${r.reply_to_message_id}${r.reply_to_text ? `:"${r.reply_to_text.slice(0, 60)}${r.reply_to_text.length > 60 ? '…' : ''}"` : ''}`
        : ''
      const reactionTag = r.user_reaction ? ` [reaction: ${r.user_reaction}]` : ''
      return `[${time}] ${who}${attach}${replyCtx}: ${r.text}${reactionTag}`
    })
    .join('\n')
  return {
    content: [
      { type: 'text', text: summary || '(no recent messages)' },
      { type: 'text', text: JSON.stringify({ chat_id, thread_id: thread_id ?? null, count: rows.length, messages: rows }, null, 2) },
    ],
  }
}

// ─── Session event handling ───────────────────────────────────────────────

function resetOrphanedReplyTimeout(): void {
  const turn = currentTurn
  if (turn?.orphanedReplyTimeoutId != null) {
    clearTimeout(turn.orphanedReplyTimeoutId)
    turn.orphanedReplyTimeoutId = null
  }
  if (turn == null) return
  if (shouldArmOrphanedReplyTimeout({
    currentSessionChatId: turn.sessionChatId,
    capturedTextCount: turn.capturedText.length,
    replyCalled: turn.replyCalled,
    // #1122/#1126: the pinned card is retired and `progressDriver` is
    // permanently null, so this suppression signal is always false. Kept as a
    // literal (the shouldArm* predicate still accepts the flag) rather than
    // reading the dead driver.
    progressCardActive: false,
  })) {
    turn.orphanedReplyTimeoutId = setTimeout(() => {
      // The timer fires asynchronously; re-read currentTurn so we
      // don't operate on a captured-but-superseded turn. If a new
      // turn (or no turn) is in flight, the original turn's backstop
      // is no longer ours to fire.
      const t = currentTurn
      if (t == null || t !== turn) return
      t.orphanedReplyTimeoutId = null
      if (shouldArmOrphanedReplyTimeout({
        currentSessionChatId: t.sessionChatId,
        capturedTextCount: t.capturedText.length,
        replyCalled: t.replyCalled,
        // #1122/#1126: retired card / null driver — always false (see above).
        progressCardActive: false,
      })) {
        // Feed-survival guard: re-arm the fuse while the turn is
        // legitimately working — an in-flight tool, a detached background
        // process (Bash run_in_background), or a human-wait tool (ask_user).
        // This extends the original "isMidToolCall" guard to cover the
        // detached-work cases that empty inFlight prematurely.
        //
        // Cap logic:
        //  • Foreground tools / detached background work: bound by
        //    ORPHANED_REPLY_MAX_REARMS (20 × 30 s = 10 min). A genuinely
        //    hung tool still surfaces after the cap.
        //  • Human-wait tools (ask_user): NEVER forcibly backstop while
        //    ask_user is open for this chat — the human simply hasn't
        //    tapped yet. We keep re-arming unconditionally until the prompt
        //    resolves (TTL or tap) and inFlight empties.
        const turnKey = statusKey(t.sessionChatId, t.sessionThreadId)
        const working = isLegitimatelyWorking(turnKey)
        const humanWaiting = (() => {
          for (const entry of pendingAskUser.values()) {
            if (entry.chatId === t.sessionChatId) return true
          }
          return false
        })()
        if (working || humanWaiting) {
          const underCap = t.orphanedReplyRearmCount < ORPHANED_REPLY_MAX_REARMS
          if (humanWaiting || underCap) {
            t.orphanedReplyRearmCount++
            process.stderr.write(
              `telegram gateway: orphaned-reply fuse expired — re-arming` +
              ` (rearm ${t.orphanedReplyRearmCount}/${ORPHANED_REPLY_MAX_REARMS},` +
              ` in_flight=${toolFlightTracker.inFlightCount()},` +
              ` human_wait=${humanWaiting},` +
              ` bg_work=${pendingProgress.hasPendingAsyncDispatch(turnKey)})\n`,
            )
            resetOrphanedReplyTimeout()
            return
          }
          process.stderr.write(
            `telegram gateway: orphaned-reply rearm cap reached (${ORPHANED_REPLY_MAX_REARMS}) — forcing backstop despite working state\n`,
          )
        }
        process.stderr.write(
          `telegram gateway: orphaned-reply timeout (${ORPHANED_REPLY_TIMEOUT_MS}ms) — forcing backstop\n`,
        )
        handleSessionEvent({ kind: 'turn_end', durationMs: -1 })
      }
    }, ORPHANED_REPLY_TIMEOUT_MS)
  }
}

function closeActivityLane(chatId: string, threadId: number | undefined): void {
  const key = chatKeyWithSuffix(chatId, threadId, 'activity')
  const stream = activeDraftStreams.get(key)
  if (stream == null) return
  activeDraftStreams.delete(key)
  void stream.finalize().catch(() => {})
}

function closeProgressLane(chatId: string, threadId: number | undefined): void {
  // Progress-card streams include a turnKey suffix in their key
  // (e.g. "chatId:_:progress:chatId:1"). Iterate and match by prefix
  // so the backstop actually finds the stream.
  const prefix = chatKeyWithSuffix(chatId, threadId, 'progress')
  for (const [key, stream] of activeDraftStreams) {
    if (key.startsWith(prefix)) {
      activeDraftStreams.delete(key)
      void stream.finalize().catch(() => {})
    }
  }
}

/** Accumulation cap for a foreground sub-agent's nested narrative lines.
 *  Slightly larger than NESTED_MAX_LINES so the render's "↳ +N earlier…"
 *  header is meaningful without growing unbounded on a long sub-agent. */
const FOREGROUND_SUBAGENT_ACCUM_MAX = 12

/**
 * Render this turn's activity feed, nesting any active foreground sub-agent's
 * narrative beneath the parent's own steps (Model A). With no active
 * foreground sub-agent this is exactly the flat feed. Multiple concurrent
 * foreground sub-agents (rare — parallel Task dispatch) flatten in insertion
 * order; the single-sub-agent common case nests precisely under its
 * Delegating line.
 *
 * The header (elapsed + tool count) is now threaded into the render so the
 * main-session card matches the worker card's two-line header style. This
 * fixes the missing header regression where the worker card showed elapsed/
 * tool-count metadata but the main-session card rendered step-lines only.
 */
function composeTurnActivity(turn: CurrentTurn, final = false, liveSuffix = ''): string | null {
  const childLines: string[] = []
  for (const narrative of turn.foregroundSubAgents.values()) {
    childLines.push(...narrative)
  }
  // Pass labeledToolCount as stepCount only on the terminal (final) render so
  // the persisted feed record shows a `✓ N steps` total. The live in-progress
  // feed omits it (stepCount undefined) to stay clean and minimal.
  const stepCount = final ? turn.labeledToolCount : undefined
  // Build the session header so the main-session card renders the same two-line
  // elapsed/tool-count header as the worker card.
  const header: SessionActivityHeader = {
    label: 'Agent',
    elapsedMs: turn.startedAt > 0 ? Date.now() - turn.startedAt : 0,
    toolCount: turn.labeledToolCount,
    state: final ? 'done' : 'running',
  }
  return renderActivityFeedWithNested(turn.mirrorLines, childLines, final, liveSuffix, stepCount, header)
}

/**
 * Render a SHOWN narrative text block as a transient liveness step — the
 * same path a tool label takes (appendActivityLabel → renderStepFeed), so
 * the narrative line is rolling-window-clipped and replaced by the next
 * event exactly like a tool step. NOT a new message, NOT persisted as a
 * parallel mirror (invariant `chat-is-the-single-source-of-truth`,
 * reference/invariants.md). Clipped to a single 120-char line via
 * clipNarrative so it reads as a step, not a paragraph.
 */
function showNarrativeStep(turn: CurrentTurn, text: string): void {
  const rendered = appendActivityLabel(turn.mirrorLines, clipNarrative(text))
  if (rendered == null) return
  turn.activityPendingRender = composeTurnActivity(turn) ?? rendered
  const ea = emissionAuthorityFor(turn)
  // PR-4d: route the deliver-before-drain decision through the centralized
  // card-drain gate (chatLock-serialized under the flag; verbatim block OFF).
  cardDrainGate(turn, ea, () => {
  if (ea.mayDrain(turn)) {
    // Producer A (narrative SHOW): pre-answer narrative may now OPEN a card,
    // not just EDIT one — lever 5 is INERT (see feed-open-gate.ts), and
    // Lever 2 / clearActivitySummary guarantees reply-is-last ordering instead.
    // Accumulation into mirrorLines still happens, so any narration staged
    // before the card opened renders on the first OPEN (whichever producer
    // wins the race — narrative here, or the enqueue/liveness timer).
    // PR-4a: routed through the emission-authority façade (no-op delegate).
    ea.openOrEditCard('narrative', () => {
      turn.activityInFlight = drainActivitySummary(turn, 'narrative')
    })
  }
  })
}

/**
 * Narrative-dedup gate, step 2 (reducer-side): a tool_use just arrived while
 * a narrative block was pending. Decide SHOW vs SUPPRESS and clear the
 * pending slot. SUPPRESS only when the tool is reply/stream_reply AND the
 * pending text is a draft-then-send of that reply's `input.text`. Everything
 * else (a working tool, or a reply whose text differs — post-action
 * narration) is SHOWN. See narrative-dedup.ts §2b.
 */
function resolvePendingNarrativeOnTool(
  turn: CurrentTurn,
  toolName: string,
  input: Record<string, unknown> | undefined,
): void {
  const pending = turn.pendingNarrative
  if (pending == null) return
  turn.pendingNarrative = null
  if (REPLY_TOOLS.has(toolName)) {
    const replyText = typeof input?.text === 'string' ? (input.text as string) : ''
    if (isDraftOfReply(pending.text, replyText)) return // draft of the answer → SUPPRESS
  }
  showNarrativeStep(turn, pending.text) // working preamble / post-action narration → SHOW
}

/**
 * Narrative-dedup gate, step 1 (reducer-side): a new narrative block
 * arrived. A previously-pending block had nothing reply-shaped immediately
 * after it (pure narration) → flush it as SHOWN, then stage the new one for
 * one lookahead step. See narrative-dedup.ts §2b.
 */
function stagePendingNarrative(turn: CurrentTurn, text: string): void {
  if (turn.pendingNarrative != null) {
    showNarrativeStep(turn, turn.pendingNarrative.text)
  }
  turn.pendingNarrative = { text }
}

/**
 * Narrative-dedup gate, step 3 (reducer-side): the turn is ending with a
 * trailing narrative block and nothing after it. SUPPRESS only when the turn
 * already delivered its answer via reply/stream_reply and the trailing text
 * is a draft of that answer; otherwise SHOW (genuine trailing narration like
 * "Done — all green."). See narrative-dedup.ts §2b.
 */
function flushPendingNarrativeAtTurnEnd(turn: CurrentTurn, lastReplyText: string): void {
  const pending = turn.pendingNarrative
  if (pending == null) return
  turn.pendingNarrative = null
  if (lastReplyText.length > 0 && isDraftOfReply(pending.text, lastReplyText)) return // trailing duplicate of the answer
  showNarrativeStep(turn, pending.text)
}

/**
 * Drain the tool-activity summary's pending render queue. Single-flight
 * by construction (caller assigns the returned promise to
 * `turn.activityInFlight`; while set, new tool_uses only update
 * `turn.activityPendingRender` and return).
 *
 * Transport: a single in-place edited message. The first render does
 * `sendMessage` (capturing `turn.activityMessageId`); subsequent renders
 * `editMessageText` that id, so the summary accumulates in place without
 * retyping the whole block. `clearActivitySummary` deletes the message
 * when the reply tool takes over. Works in DMs, groups, and forum topics
 * alike (forum topics pass message_thread_id).
 *
 * The drain holds a reference to `turn`, so a turn-swap mid-drain
 * doesn't corrupt the next turn's atom — late writes land on the
 * captured `turn` (already-completed turn, harmless).
 */
async function drainActivitySummary(
  turn: CurrentTurn,
  // Which producer triggered this drain (design §9 levers 1 + 5). Gates the
  // OPEN (first sendMessage) branch via `mayOpenActivityCard`; EDITs of an
  // already-open card are never gated. Defaults to 'tool' — the historically
  // unconditional OPEN behaviour — so any caller that does not opt into the
  // gate is unaffected. Narrative-SHOW and liveness callers pass their producer
  // explicitly.
  producer: FeedOpenProducer = 'tool',
  // Optional flags forwarded to `mayOpenActivityCard`.
  openFlags?: { postAnswerSubagentActivity?: boolean },
): Promise<void> {
  try {
    while (turn.activityPendingRender !== turn.activityLastSentRender) {
      const target = turn.activityPendingRender
      if (target == null) break
      // OPEN gate (design §9 levers 1 + 5): when this drain would OPEN a fresh
      // card (activityMessageId == null), consult the pure gate. Refusing an
      // OPEN must NOT advance activityLastSentRender — the accumulated render
      // stays pending so a later OPEN-eligible producer (a tool label, or
      // liveness) renders it. An EDIT (activityMessageId != null) is never
      // gated. Enforced HERE so it covers BOTH the inline producers AND the
      // detached heartbeat setInterval drain (R7/concurrency). The gate guards
      // gate EVALUATION, not an in-flight send: it is not a hard mutex — a send
      // already PAST this check and suspended at its `await robustApiCall(
      // sendMessage)` when a substantive final lands still completes and opens a
      // card; that residual is reconciled by lever-2's `clearActivitySummary`
      // chaining its finalize onto `turn.activityInFlight` (the suspended drain)
      // and editing the card in place, not by this gate blocking it.
      // Lever 4 (cross-turn / race C/D): a synthetic represent/owed-reply turn
      // (and the liveness/heartbeat timer firing on it) starts with a CLEARED
      // per-turn `finalAnswerEverDelivered` latch even when a substantive answer
      // already reached the user in an EARLIER turn — so without this its first
      // drain opens a card BELOW that prior reply. Only such a turn carries
      // `crossTurnGate`; reuse the represent guard's delivered-since check
      // (`hasOutboundDeliveredSince`) with the obligation's `openedAt` cutoff and
      // the SUBSTANTIVE 200-char threshold (so an ack never trips it → #2141
      // stays green). Computed ONLY when about to OPEN (activityMessageId ==
      // null) AND only for a turn with a cross-turn gate — no history query on
      // the common foreground path. Scoped to the synthetic surface by the
      // presence of `crossTurnGate`, so it can never fire on a foreground turn.
      // PR-4b: the cross-turn predicate is now the PURE, shared helper extracted
      // into feed-open-gate.ts (body lifted verbatim) — the SAME function the
      // emission-authority façade calls in its enabled branch, so flag-ON and
      // flag-OFF compute an identical verdict. History deps injected (the module
      // stays sqlite-free). The pure-gate consult + the `break` below stay
      // LITERALLY in the drain (disabled-path byte-identity).
      const crossTurnAnswerDelivered = computeCrossTurnAnswerDelivered(
        turn,
        feedOpenGateDeps(),
      )
      if (
        turn.activityMessageId == null
        && !mayOpenActivityCard({
          producer,
          finalAnswerEverDelivered: turn.finalAnswerEverDelivered,
          labeledToolCount: turn.labeledToolCount,
          crossTurnAnswerDelivered,
          postAnswerSubagentActivity: openFlags?.postAnswerSubagentActivity,
        })
      ) {
        break
      }
      // `renderActivityFeed` already emitted ready Telegram HTML with per-line
      // markup (**→ current** / _✓ done_) and escaped each label's
      // <,>,& itself (#1942 class) — send verbatim, do NOT re-escape or
      // re-wrap (double-escaping would surface literal tags).
      const html = target
      const chat = turn.sessionChatId
      const thread = turn.sessionThreadId
      // Native reply-quote: anchor the feed message to the user's question so
      // it renders as a quoted header (reply_parameters renders on a real
      // message; edits preserve it). allow_sending_without_reply so a deleted
      // source can't drop the send.
      const replyAnchor = turn.sourceMessageId != null
        ? { reply_parameters: { message_id: turn.sourceMessageId, allow_sending_without_reply: true } }
        : {}
      try {
        if (turn.activityMessageId == null) {
          const sent = await robustApiCall(
            // allow-raw-bot-api: sendRichMessage routed through robustApiCall (not in the THREAD_NOT_FOUND blast pattern)
            () => bot.api.sendRichMessage(chat, richMessage(html), {
              ...(thread != null ? { message_thread_id: thread } : {}),
              disable_notification: true,
              ...replyAnchor,
            }),
            { chat_id: chat, ...(thread != null ? { threadId: thread } : {}), verb: 'activity-summary.send' },
          )
          turn.activityMessageId = sent.message_id
          turn.activityEverOpened = true
          // Status-pin: the per-turn status message just opened — it's the
          // in-flight "what it's doing" surface. Silently pin it so the turn
          // stays in view when the feed scrolls past. Keyed to the same
          // status-key the canonical turn-end (purgeReactionTracking) unpins.
          // Fire-and-forget; the single-owner reconcile keeps state consistent.
          void reconcileStatusPin(
            `fg:${statusKey(chat, thread)}`,
            chat,
            { pinned: true, messageId: sent.message_id },
          )
        } else {
          const id = turn.activityMessageId
          await robustApiCall(
            () => bot.api.editMessageText(chat, id, richMessage(html), {}),
            { chat_id: chat, ...(thread != null ? { threadId: thread } : {}), verb: 'activity-summary.edit' },
          )
        }
        turn.activityLastSentRender = target
      } catch (err) {
        const msg = err instanceof Error ? err.message : String(err)
        if (!msg.includes('message is not modified')) {
          turn.activityDrainFailures += 1
          // Surface the failing anchor + topic: the resume-400 bug fed a
          // fabricated 13-digit message_id as the reply anchor here, so every
          // send 400'd and the feed never opened. Logging the anchor +
          // everOpened makes a feed-blanking send self-explanatory (and the
          // turn-end DEGRADED line aggregates it).
          process.stderr.write(
            `telegram gateway: activity-summary drain failed: ${msg} ` +
              `(chat=${chat} thread=${thread ?? '-'} ` +
              `replyAnchor=${turn.sourceMessageId ?? 'none'} ` +
              `everOpened=${turn.activityEverOpened} failures=${turn.activityDrainFailures})\n`,
          )
        }
        // Mark as sent so we don't infinite-loop on a stuck render.
        turn.activityLastSentRender = target
      }
    }
  } finally {
    turn.activityInFlight = null
  }
}

/**
 * Open (or climb) the minimal "Working…" liveness card for a 0-label turn once
 * it has been alive >= FEED_LIVENESS_OPEN_MS. The ONE place the liveness card
 * may OPEN — both the enqueue-time early-open timer
 * (`scheduleEarlyLivenessOpen`) and the 6 s heartbeat call through here, so a
 * card opened by one caller is a clean no-op for the other:
 *   - `drainActivitySummary` OPENs when `activityMessageId == null` and EDITs
 *     once it is set, so a second call after an open just maintains the card;
 *   - the `mirrorLines.length === 0` guard at the heartbeat call site (and the
 *     drain's own gate) means once a real tool label lands this path is skipped
 *     and the labelled-feed heartbeat takes over;
 *   - the OPEN itself is still gated by `mayOpenActivityCard` (lever 1 / 4) via
 *     `ea.openOrEditCard('liveness', …)`, so a card never opens below a
 *     delivered answer or on a cross-turn synthetic surface.
 *
 * Renders the turn's accumulated narration when present (the §3 case: narration
 * staged before the first tool via `mirrorLines`) so the early open is not a
 * bare placeholder when there is real text to show; falls back to "Working…"
 * for a genuinely silent thinking turn.
 */
function openLivenessFeedIfDue(turn: CurrentTurn): void {
  const age = Date.now() - turn.startedAt
  // The WHEN decision (pure, `feed-open-gate.ts`): feature on, target chat,
  // past threshold, no card already open. Returns false once a card is open
  // (the drain EDITs instead) so the two callers can never double-open.
  if (!shouldEarlyOpenLiveness({
    enabled: FEED_LIVENESS_OPEN_ENABLED,
    ageMs: age,
    thresholdMs: FEED_LIVENESS_OPEN_MS,
    mirrorLineCount: turn.mirrorLines.length,
    activityMessageId: turn.activityMessageId,
    sessionChatId: turn.sessionChatId,
  })) return
  const lines = turn.mirrorLines.length > 0 ? turn.mirrorLines : ['Working…']
  const livenessHeader: SessionActivityHeader = {
    label: 'Agent', elapsedMs: age, toolCount: turn.labeledToolCount, state: 'running',
  }
  // Liveness card is a single "step" whose start is the turn start, so `age`
  // IS the step's own elapsed. formatStepSuffix keeps the `→` line timer-free
  // until the step has run ≥ STEP_TIMER_MIN_MS (header total still shows).
  const rendered = renderActivityFeedWithNested(lines, [], false, formatStepSuffix(age), undefined, livenessHeader)
  if (rendered == null) return
  turn.activityPendingRender = rendered
  const ea = emissionAuthorityFor(turn)
  // PR-4d: route through the centralized chatLock-serialized card-drain gate.
  cardDrainGate(turn, ea, () => {
    if (ea.mayDrain(turn)) {
      // Producer C (liveness timer): the thinking-gap / early-open. Now that
      // Lever 5 is inert (narrative may open pre-answer — #2588), liveness
      // remains the natural open for 0-tool pre-answer turns that are silent.
      // The sticky-latch (lever 1) still gates it in the drain.
      // PR-4a: routed through the emission-authority façade (no-op delegate).
      ea.openOrEditCard('liveness', () => {
        turn.activityInFlight = drainActivitySummary(turn, 'liveness')
      })
    }
  })
}

// Enqueue-time early-open timers, keyed by status-key. One per in-flight turn;
// cleared at turn-end (`stopEarlyLivenessOpen`) so a leaked timer can never fire
// against a successor turn. `unref()` so it never holds the process alive.
const earlyLivenessOpenTimers = new Map<string, ReturnType<typeof setTimeout>>()

/**
 * Schedule the enqueue-time early-open of the "Working…" liveness card. Called
 * once per fresh turn at the `enqueue` lifecycle event (the single chokepoint
 * every real turn atom passes through — inbound, cron, subagent-handback,
 * vault-resume, restart-marker; anonymous one-shot hook clients never emit
 * `enqueue`, so they are excluded by construction). Fires `openLivenessFeedIfDue`
 * once at `FEED_LIVENESS_OPEN_MS` after turn start so narration / thinking that
 * happens BEFORE the first tool surfaces a card within ~a second — no more dead
 * air until a tool label or the old 12 s threshold. A no-op if a tool/narrative
 * already opened the card (the helper's own guards). The 6 s heartbeat remains
 * the backstop + the climb.
 */
function scheduleEarlyLivenessOpen(turn: CurrentTurn): void {
  if (STATIC || !FEED_HEARTBEAT_ENABLED || !FEED_LIVENESS_OPEN_ENABLED) return
  if (turn.sessionChatId == null) return
  const key = statusKey(turn.sessionChatId, turn.sessionThreadId)
  stopEarlyLivenessOpen(key)
  const t = setTimeout(() => {
    earlyLivenessOpenTimers.delete(key)
    // Re-resolve the live turn for this key: only open if THIS turn is still the
    // live one for its topic (a successor turn would carry its own timer). Under
    // flag OFF `get(key)` returns the singleton — same turn unless a successor
    // already replaced it, which the turnId match below also guards.
    const live = currentTurnMap.get(key)
    if (live == null || live.turnId !== turn.turnId) return
    openLivenessFeedIfDue(live)
  }, FEED_LIVENESS_OPEN_MS)
  t.unref?.()
  earlyLivenessOpenTimers.set(key, t)
}

/** Cancel the enqueue-time early-open timer for a status-key (turn-end teardown
 *  + re-arm guard). Idempotent. */
function stopEarlyLivenessOpen(key: string): void {
  const t = earlyLivenessOpenTimers.get(key)
  if (t != null) { clearTimeout(t); earlyLivenessOpenTimers.delete(key) }
}

/**
 * Heartbeat tick (PR1): keep the live activity feed visibly advancing during a
 * long single step that emits no new tool_label. Re-renders the feed with a
 * climbing " · Ns" elapsed on the in-progress line through the SAME single-flight
 * drain path the tool_label handler uses (no separate transport, no race). Pure
 * no-op unless there is a live in-flight feed whose newest step has gone stale.
 * Skips once the final answer landed (the feed is handing off) and after the
 * turn ends (activityMessageId nulled by clearActivitySummary). Deterministic +
 * framework-owned — never depends on the model.
 */
function feedHeartbeatTick(): void {
  const turn = currentTurn
  if (turn == null) return
  if (turn.finalAnswerDelivered) {
    // Fix 2: post-answer background-agent liveness. When the sub-agent/workflow
    // watcher has surfaced a new step AFTER the substantive final answer, drive
    // a liveness card so the operator can see "background agent still working".
    //
    // Gate: `turn.subagentActivityAt` must be set (watcher fired) AND it must
    // exceed `turn.finalAnswerDeliveredAt` (the watcher advanced AFTER the answer
    // was delivered — not just any pre-answer label). This is the key fix:
    // #2587 read `lastToolLabelAt`, which is frozen by the drop-guard after a
    // substantive answer and therefore never crosses the threshold. `subagentActivityAt`
    // is written by the watcher's onProgress callback INDEPENDENTLY of the
    // tool_label / drop-guard path, so it correctly advances post-answer.
    //
    // Idle-gap suppression + staleness cap (concern 3) — the single pure decision
    // `evaluatePostAnswerLiveness`:
    //   - 'idle'  → no watcher activity after the answer (`subagentActivityAt`
    //               undefined or ≤ finalAnswerDeliveredAt). Stay silent; the
    //               reply-is-last invariant is fully preserved for idle turns.
    //   - 'stale' → the worker's last advance is older than POST_ANSWER_LIVENESS_STALE_MS
    //               (its `onFinish` froze `subagentActivityAt` and no new step has
    //               arrived). STOP re-rendering so the card doesn't climb `running`
    //               forever — mirrors the pre-answer FEED_LIVENESS_OPEN_MS cap. The
    //               worker's own terminal card (workerActivityFeed.finish) is the
    //               durable record once it completes.
    //   - 'emit'  → genuine in-flight post-answer activity; render the card below.
    const subagentAt = turn.subagentActivityAt
    const livenessVerdict = evaluatePostAnswerLiveness({
      subagentActivityAt: subagentAt,
      finalAnswerDeliveredAt: turn.finalAnswerDeliveredAt,
      now: Date.now(),
      staleCapMs: POST_ANSWER_LIVENESS_STALE_MS,
    })
    if (livenessVerdict !== 'emit' || subagentAt == null) return // idle gap or stale worker → stay silent (the `== null` also narrows subagentAt for the elapsed below)
    // A background worker is genuinely active after the answer. Open or maintain
    // a liveness card below the reply. Route through `mayOpenActivityCard` with
    // `postAnswerSubagentActivity:true` so Lever 1 is lifted for 'tool' producer
    // (Fix 2's Lever 1 exception in feed-open-gate.ts). The card renders the
    // turn's accumulated mirrorLines (which may be empty — in that case the drain
    // opens a "Working…" placeholder matching the pre-answer liveness path).
    if (turn.sessionChatId == null) return
    const age = Date.now() - turn.startedAt
    const livenessHeader: SessionActivityHeader = {
      label: 'Agent', elapsedMs: age, toolCount: turn.labeledToolCount, state: 'running',
    }
    const lines = turn.mirrorLines.length > 0 ? turn.mirrorLines : ['Working in background…']
    // `subagentAt` is the worker's last ADVANCE — the current step's start —
    // so this suffix is already per-step. formatStepSuffix adds the 10 s gate.
    const elapsed = Date.now() - subagentAt
    const rendered = renderActivityFeedWithNested(lines, [], false, formatStepSuffix(elapsed), undefined, livenessHeader)
    if (rendered == null) return
    turn.activityPendingRender = rendered
    const ea = emissionAuthorityFor(turn)
    cardDrainGate(turn, ea, () => {
    if (ea.mayDrain(turn)) {
      // Producer 'tool' with postAnswerSubagentActivity=true: the Lever 1
      // exception allows this OPEN. Lever 4 (cross-turn) and idle-liveness
      // blocks are still respected by the drain. The card surfaces BELOW the
      // reply showing the background agent's live activity.
      ea.openOrEditCard('tool', () => {
        turn.activityInFlight = drainActivitySummary(turn, 'tool', { postAnswerSubagentActivity: true })
      })
    }
    })
    return
  }

  // Liveness feed (open + maintain). `mirrorLines.length === 0` means no tool
  // has ever produced a label this turn — pure thinking, or only suppressed
  // tools. Open a minimal "Working…" feed once the turn passes the threshold,
  // and keep its elapsed climbing until a real label arrives. The first label
  // makes mirrorLines non-empty, so the labelled-feed heartbeat below takes
  // over and its edit cleanly replaces the placeholder. drainActivitySummary
  // sends (opens) when activityMessageId is null and edits (maintains) once set
  // — so this one branch handles both the open and the climb.
  //
  // The open/climb logic lives in ONE place (`openLivenessFeedIfDue`) so the
  // enqueue-time early-open timer (`scheduleEarlyLivenessOpen`) and this 6 s
  // heartbeat both reach the same drain — there is exactly one path that can
  // OPEN the liveness card, so the two callers can never double-open or race.
  if (turn.mirrorLines.length === 0) {
    openLivenessFeedIfDue(turn)
    return
  }

  // Labelled-feed heartbeat: keep a stale in-progress step visibly advancing.
  if (turn.activityMessageId == null) return // no live feed yet / already cleared
  if (turn.lastToolLabelAt == null) return // feed not driven by a labelled step
  const elapsed = Date.now() - turn.lastToolLabelAt
  if (elapsed < FEED_HEARTBEAT_MIN_STALE_MS) return // step is fresh; feed advancing normally
  // `lastToolLabelAt` resets on every new tool label, so `elapsed` is the
  // CURRENT step's own run time. formatStepSuffix holds the timer back until
  // the step passes STEP_TIMER_MIN_MS (10 s) — header total is unaffected.
  const rendered = composeTurnActivity(turn, false, formatStepSuffix(elapsed))
  if (rendered == null) return
  turn.activityPendingRender = rendered
  const ea = emissionAuthorityFor(turn)
  // PR-4d: route through the centralized chatLock-serialized card-drain gate.
  cardDrainGate(turn, ea, () => {
  if (ea.mayDrain(turn)) {
    // Maintains an already-open card (guarded above on activityMessageId !=
    // null) → only ever EDITs. 'liveness' is correct either way.
    // PR-4a: routed through the emission-authority façade (no-op delegate).
    ea.openOrEditCard('liveness', () => {
      turn.activityInFlight = drainActivitySummary(turn, 'liveness')
    })
  }
  })
}
if (!STATIC && FEED_HEARTBEAT_ENABLED) {
  setInterval(feedHeartbeatTick, FEED_HEARTBEAT_TICK_MS).unref()
}

/**
 * Reconcile the activity summary when the model's reply tool takes over as the
 * authoritative surface. Awaits any in-flight render so we don't race a stale
 * write, then EITHER:
 *   - FINALIZE (default, CLEAR_STATUS_ON_COMPLETION=false): edit the message to
 *     a terminal all-done render (no "→ in-progress" line) and stop tracking it
 *     — the status stays in the chat as a record beside the reply. No delete.
 *   - DELETE (CLEAR_STATUS_ON_COMPLETION=true, opt-in via
 *     channels.telegram.clear_status_on_completion): remove the message so only
 *     the reply remains (the pre-2026-06 behaviour).
 * Idempotent + best-effort — failures stderr-log but don't block.
 *
 * Called on the first reply (hand-off) and again at turn_end (no-reply safety
 * net); finalize edits are idempotent (a 'message is not modified' on the
 * second call is swallowed).
 *
 * `finalHtmlOverride` (finalize path only): a render captured by the caller
 * BEFORE it tore down turn state the finalize render depends on. The
 * foreground handoff-clear path passes this — it deletes the just-finished
 * sub-agent's narrative right after this call, so the async
 * `composeTurnActivity(turn, true)` below would see an emptied feed (and, on
 * ack-first turns, empty `mirrorLines`), render null, and skip the finalize —
 * freezing the last live "→ in-progress" line. The captured render keeps the
 * persisted record reading done (✓). Omitted → compute it here (the common
 * reply/turn_end callers, where state is stable).
 */
function clearActivitySummary(turn: CurrentTurn, finalHtmlOverride?: string | null): void {
  const chat = turn.sessionChatId
  const thread = turn.sessionThreadId
  const inFlight = turn.activityInFlight ?? Promise.resolve()
  void inFlight.then(async () => {
    if (turn.activityMessageId == null) return
    const id = turn.activityMessageId
    turn.activityMessageId = null
    if (CLEAR_STATUS_ON_COMPLETION) {
      try {
        await robustApiCall(
          () => bot.api.deleteMessage(chat, id),
          { chat_id: chat, ...(thread != null ? { threadId: thread } : {}), verb: 'activity-summary.delete' },
        )
      } catch (err) {
        process.stderr.write(`telegram gateway: activity-summary delete failed: ${err}\n`)
      }
      return
    }
    // Default: leave the status message as a record, edited to a terminal
    // all-done state so it doesn't freeze on a misleading "→ in-progress" line.
    let finalHtml =
      finalHtmlOverride !== undefined ? finalHtmlOverride : composeTurnActivity(turn, true)
    // Liveness-only feed: opened on the timer for a turn that never labelled a
    // tool (pure thinking / suppressed tools), so mirrorLines is empty and the
    // terminal render is null. Finalize to a done "✓ Working…" record instead
    // of leaving the message frozen on the live "→ Working…" line.
    if (finalHtml == null && turn.mirrorLines.length === 0 && turn.activityEverOpened) {
      const livenessElapsed = turn.startedAt > 0 ? Date.now() - turn.startedAt : 0
      const livenessHeader: SessionActivityHeader = {
        label: 'Agent', elapsedMs: livenessElapsed, toolCount: turn.labeledToolCount, state: 'done',
      }
      finalHtml = renderActivityFeedWithNested(['Working…'], [], true, '', undefined, livenessHeader)
    }
    if (finalHtml == null) return
    try {
      await robustApiCall(
        () => bot.api.editMessageText(chat, id, richMessage(finalHtml), {}),
        { chat_id: chat, ...(thread != null ? { threadId: thread } : {}), verb: 'activity-summary.finalize' },
      )
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err)
      if (!msg.includes('message is not modified')) {
        process.stderr.write(`telegram gateway: activity-summary finalize failed: ${msg}\n`)
      }
    }
  })
}

function handleSessionEvent(ev: SessionEvent): void {
  switch (ev.kind) {
    case 'enqueue': {
      // Drain any orphaned typing-wrap entries left over from a crashed
      // prior turn before resetting focus.
      typingWrapper.drainAll()
      if (ev.chatId) {
        // #1445 cross-turn pending-async ambient — backstop for the
        // `handleInbound` path's `clearPending('inbound')`. The
        // inbound path covers real user messages, but synthesised
        // wakes (subagent-handback channel turn, cron fires, vault
        // grant resumes, restart markers) push directly to
        // `pendingInboundBuffer` and bypass `handleInbound`. The
        // `enqueue` session-event fires for EVERY fresh turn atom
        // regardless of source — clearing here drops any prior turn's
        // ambient before the new turn's `noteOutbound` lands. The
        // call is idempotent so it's safe to fire in addition to the
        // inbound-path clear (for the real-inbound case, this is a
        // no-op because state was already deleted by then).
        const enqThreadId = ev.threadId != null ? Number(ev.threadId) : undefined
        pendingProgress.clearPending(
          statusKey(ev.chatId, enqThreadId),
          'handback',
        )
      }
      if (ev.chatId) {
        // Issue #195: if a previous turn left an answer-lane stream open
        // (rapid steer/queue), force it to a new generation so its in-flight
        // edits don't mutate the new turn's message. Materialize is best-effort
        // — we don't await here because turn_end on the prior turn should
        // have already done it; this is a defensive supersession guard.
        const prior = currentTurn
        if (prior?.answerStream != null) {
          prior.answerStream.forceNewMessage()
          prior.answerStream.stop()
          prior.answerStream = null
        }
        // #1067: swap the entire turn atom in one assignment. Every
        // handler captures `const turn = currentTurn` at entry, so a
        // captured-then-awaited read can't reattribute to the new turn.
        const startedAt = Date.now()
        // Component 3 — stable per-turn identity. For a real inbound this
        // matches the `origin_turn_id` stamped into the inbound meta at
        // build time (same chat/thread/messageId). Synthetic turns (cron /
        // handback — no messageId) get a unique startedAt-based fallback id
        // that no reply will ever echo, so they correctly fall through to
        // the live-turn routing in resolveAnswerThreadId.
        const enqThreadIdNum = ev.threadId != null ? Number(ev.threadId) : undefined
        const turnId =
          deriveTurnId(ev.chatId, enqThreadIdNum ?? null, ev.messageId)
          ?? `${chatKey(ev.chatId, enqThreadIdNum ?? null)}#synthetic-${startedAt}`
        // PR1 (cross-turn stale-card guard, §9 lever 4 / race C/D). Consume any
        // pending cross-turn gate `obligationSweep` armed for THIS exact turn
        // when it pushed an `obligation_represent` inbound. The gate is keyed on
        // the obligation's `originTurnId`, and the represent inbound reuses the
        // original chat/thread/messageId, so this turn's `turnId` (derived just
        // above) equals that key iff this turn IS the represent surface armed for.
        // An unrelated foreground turn on the same chat/thread derives a
        // different `turnId` → finds no entry → no gate → its card opens normally
        // (correct). Consume-once: delete on read so the matched gate can't leak
        // forward, and a never-matched stale gate can never suppress another turn.
        const xTurnGateKey = turnId
        const consumedCrossTurnGate = pendingCrossTurnGate.get(xTurnGateKey)
        if (consumedCrossTurnGate != null) pendingCrossTurnGate.delete(xTurnGateKey)
        const next: CurrentTurn = {
          sessionChatId: ev.chatId,
          sessionThreadId: enqThreadIdNum,
          // Accept the inbound id as a reply anchor only when it is a plausible
          // Telegram message id. Synthetic boot-resume inbounds fabricate a
          // 13-digit Date.now() message_id (for ack-tracking); if that reached
          // the activity-feed reply anchor it 400'd every feed send and darkened
          // the live feed for the whole resume turn (2026-06-05). The ack-queue
          // still keys on ev.messageId independently — only the anchor is gated.
          sourceMessageId: parseSourceMessageId(ev.messageId),
          startedAt,
          gatewayReceiveAt: startedAt,
          // #2527 — stamp the loop role once, from the enqueue envelope.
          role: deriveTurnRole(ev.rawContent),
          // PR1 (cross-turn stale-card guard, §9 lever 4 / race C/D). Only a
          // synthetic represent/owed-reply turn carries this; a foreground turn
          // leaves it undefined and the cross-turn card-OPEN gate is inert.
          ...(consumedCrossTurnGate != null ? { crossTurnGate: consumedCrossTurnGate } : {}),
          replyCalled: false,
          finalAnswerDelivered: false,
          finalAnswerSubstantive: false,
          // Sticky latch — reset ONLY here (turn start), never by reopen.
          finalAnswerEverDelivered: false,
          firstPingAt: null,
          // Notification ownership (R8 / PR-2): no slot claimed yet, so the
          // "claimer was substantive" flag starts false. Set atomically with
          // firstPingAt at the over-ping decision site.
          firstPingWasSubstantive: false,
          silentAnchorMessageId: null,
          silentAnchorText: '',
          capturedText: [],
          orphanedReplyTimeoutId: null,
          orphanedReplyRearmCount: 0,
          turnId,
          registryKey: null,
          noReplyDrainTimer: null,
          lastAssistantMsgId: null,
          lastAssistantDone: false,
          toolCallCount: 0,
          labeledToolCount: 0,
          activityMessageId: null,
          activityInFlight: null,
          activityPendingRender: null,
          activityLastSentRender: null,
          activityEverOpened: false,
          activityDrainFailures: 0,
          mirrorLines: [],
          pendingNarrative: null,
          lastReplyText: '',
          foregroundSubAgents: new Map(),
          answerStream: null,
          isDm: isDmChatId(ev.chatId),
          // PR-4a — construct ONE emission-authority façade per turn, passing
          // the chat/thread key in EXPLICITLY (the PR-4e seam; today equal to
          // the singleton-sourced key). Per-turn: born with this turn literal,
          // discarded with it — never persists across turns.
          emissionAuthority: new EmissionAuthority(
            statusKey(ev.chatId, enqThreadIdNum),
          ),
        }
        // PR-4e — route the turn-SET through the keyed accessor: flag-OFF assigns
        // the singleton (byte-identical to `currentTurn = next`); flag-ON sets the
        // per-topic `byKey[statusKey]` entry AND the most-recent mirror. The key is
        // the SAME statusKey the ctor's façade was constructed with just above.
        setCurrentTurn(next, statusKey(ev.chatId, enqThreadIdNum))
        markIdleActivity() // any turn start (main session) is activity — re-arm idle clear
        // Early-open the "Working…" liveness card at turn start so narration /
        // thinking emitted BEFORE the first tool surfaces within ~a second
        // instead of after the old 12 s threshold (the dead-air gap). Fires the
        // SAME `openLivenessFeedIfDue` the 6 s heartbeat uses — a no-op if a
        // tool/narrative already opened the card, and gated by `mayOpenActivityCard`
        // (lever 1/4) so it never opens below a delivered answer. Scoped to real
        // turns by construction: only the `enqueue` lifecycle event reaches here,
        // and anonymous one-shot hook clients (recall.py) never emit it.
        scheduleEarlyLivenessOpen(next)
        // Status-surface observability: one line at every turn SET so a later
        // dark card is traceable to which turn/topic key it belonged to.
        process.stderr.write(
          `telegram gateway: ${formatTurnLifecycle('set', 'enqueue', next, startedAt)}\n`,
        )
        // Component 3 — retain in the bounded recently-ended registry so a
        // LATE reply (landing after currentTurn flips to a successor) can
        // still resolve THIS turn's origin thread by its turnId.
        rememberRecentTurn(next)
        // Component 5 (Hook B) — this turn's topic had a queued placeholder
        // from Hook A; promote it to "On it — replying now." (deleted later
        // when the answer lands). No-op when there's no placeholder / DM.
        promoteQueuedStatus(ev.chatId, enqThreadIdNum)
        // Ack inbound delivery (the marko drop-wedge): claude actually started
        // this turn, so its delivered inbound landed — stop tracking it for
        // re-delivery. `enqueue` carries the same chat/thread the inbound was
        // keyed on, so the key matches.
        if (DELIVERY_CONFIRM_ENABLED) {
          // Match on the source message id: `enqueue` fires for EVERY turn
          // start (cron / subagent-handback / vault-resume / restart-marker
          // too — see comment below), so a key-only ack would let a synthetic
          // turn clear a real user message still waiting under the same key.
          ackDelivery(
            deliveryQueue,
            chatKey(ev.chatId, ev.threadId != null ? Number(ev.threadId) : null),
            ev.messageId,
          )
        }
        // PR3b-cutover: feed the authoritative turn-start to the delivery
        // machine. `enqueue` fires for EVERY turn atom regardless of
        // source — inbound, cron, subagent-handback, vault-resume,
        // restart-marker — so it is the single chokepoint that captures
        // the non-inbound turns the machine's own `inbound` event never
        // sees (those bypass handleInbound). Without it the machine reads
        // idle during a cron/handback turn and the gate would mis-deliver
        // a concurrent inbound mid-turn (the #1556 composer wedge).
        // Idempotent when already in_turn (turnStart only sets perKey).
        shadowEmit({
          kind: 'turnStart',
          key: statusKey(ev.chatId, ev.threadId != null ? Number(ev.threadId) : undefined) as _ChatKey,
          at: startedAt,
        })
        // #549 fix — fresh turn, reset preamble-suppression state.
        preambleSuppressor.reset()
        // Reset the silent-end retry budget for this chat. The stored
        // turnKey is `chat:thread` shape (no per-instance suffix), so
        // without an explicit per-turn clear, `writeSilentEndState`
        // (silent-end.ts:114) inherits `retryCount` across turns
        // whenever a prior turn for the same chat hit retryCount=1.
        // The Stop hook then sees `retryCount >= MAX_RETRIES=1` on the
        // very first silent-end of every subsequent turn and bails
        // without re-prompting. finn hit this on 2026-05-25 with a
        // stuck retryCount=1 file. A new turn invalidates any prior
        // turn's retry budget by definition; clear it eagerly here.
        // ev.threadId is `string | null` (Telegram's wire shape);
        // statusKey wants `number | null` — same conversion as the
        // registry-key branch a few lines down.
        clearSilentEndState(statusKey(
          ev.chatId,
          ev.threadId != null ? Number(ev.threadId) : null,
        ))
        // Stage 3b: stamp turn-start in the registry. turn_key is
        // chat:thread:startTs — unique per turn, distinct from the
        // progress-card-driver's per-chat sequence number (these are two
        // independent identifier schemes and don't need to align).
        if (turnsDb != null) {
          // ev.threadId is `string | null` (Telegram emits as string); convert
          // to number for chatKeyWithSuffix. Number(null) = 0 which canonicalizes
          // to '_' — same as the explicit `null` branch below.
          const evThreadIdNum = ev.threadId != null ? Number(ev.threadId) : null
          const turnKey = chatKeyWithSuffix(ev.chatId, evThreadIdNum, String(startedAt))
          next.registryKey = turnKey
          // Phase 1 of #332: capture first ~200 chars of the user's message.
          const userPromptPreview = extractUserPromptPreview(ev.rawContent)
          // Closes #472 finding #11. Pre-fix: this write was scheduled
          // via setImmediate to "avoid stalling the turn handler" — but
          // SQLite local writes are sub-millisecond, and the deferral
          // opened a SIGTERM race window: a kill landing in the gap
          // between scheduling and firing left a turn with no start
          // row, invisible to the resume protocol (the user sent a
          // message, the gateway lost it, no SWITCHROOM_PENDING_TURN
          // env on next boot). Sibling writeTurnActiveMarker has always
          // been synchronous here; this matches it.
          try {
            recordTurnStart(turnsDb, {
              turnKey,
              chatId: String(ev.chatId),
              threadId: ev.threadId != null ? String(ev.threadId) : null,
              lastUserMsgId: ev.messageId != null ? String(ev.messageId) : null,
              userPromptPreview,
            })
          } catch (err) {
            process.stderr.write(`telegram gateway: recordTurnStart failed turnKey=${turnKey}: ${(err as Error).message}\n`)
          }
          // #412: turn-active marker for the bridge-watchdog. File exists
          // for the duration of the in-flight turn; mtime advances on
          // every tool_use; deleted on turn_complete. The watchdog
          // distinguishes wedged-mid-turn from healthy-idle by checking
          // for this file's presence + mtime staleness.
          writeTurnActiveMarker(STATE_DIR, {
            turnKey,
            chatId: String(ev.chatId),
            threadId: ev.threadId != null ? String(ev.threadId) : null,
            startedAt,
          })
        }
        if (pendingPtyPartial != null) {
          const pending = pendingPtyPartial
          pendingPtyPartial = null
          handlePtyPartial(pending)
        }
      }
      return
    }
    case 'dequeue': return
    case 'thinking': {
      // #1067: snapshot the turn atom at handler entry. Even though this
      // handler is sync, the principle is uniform across all event arms
      // — read `turn` once, don't re-read currentTurn after any await.
      const turn = currentTurn
      if (turn == null) return
      const ctrl = activeStatusReactions.get(statusKey(turn.sessionChatId, turn.sessionThreadId))
      if (ctrl) ctrl.setThinking()
      return
    }
    case 'tool_use': {
      const turn = currentTurn
      if (turn == null) return
      // Narrative-dedup gate step 2 (JSONL-text-narrative primitive): a
      // narrative block was pending; this tool_use is the lookahead event
      // that decides it. reply/stream_reply with near-identical text ⇒
      // draft-then-send ⇒ SUPPRESS (the reply prints the canonical answer);
      // anything else ⇒ SHOW as a transient liveness step. Runs BEFORE the
      // normal tool handling so a working preamble surfaces just ahead of
      // its tool step.
      resolvePendingNarrativeOnTool(turn, ev.toolName, ev.input)
      // Phase 1 of #332: count every tool_use in the current turn.
      turn.toolCallCount++
      // #412: bump turn-active marker mtime so the watchdog sees this
      // turn is making forward progress. Stop-hook deadlocks (the
      // failure mode #116 originally tracked) emit no more tool_use
      // events, so the marker mtime stops advancing → watchdog acts.
      touchTurnActiveMarker(STATE_DIR)
      // #549 fix: a tool_use immediately following text events makes
      // those texts "preamble" — the progress card already captured
      // them as a narrative for this tool. Drop the pending answer-
      // stream buffer so the same text doesn't also land in chat as a
      // standalone message. Telegram-surface tools (reply / stream_reply)
      // are EXCEPTIONS: their text IS the answer, so we flush instead
      // of dropping. The answer-stream's own dedup handles overlap
      // with the reply tool's payload.
      preambleSuppressor.onTool({ isReplyTool: isTelegramSurfaceTool(ev.toolName) })
      const ctrl = activeStatusReactions.get(statusKey(turn.sessionChatId, turn.sessionThreadId))
      const name = ev.toolName
      // Phase tracking removed in #553 PR 5 — phases only fed the
      // placeholder-heartbeat label, which has been retired.
      if (isTelegramReplyTool(name)) {
        turn.replyCalled = true
        // NIT 2 (reply-proxy precision): capture the ACTUAL delivered reply
        // text so flushPendingNarrativeAtTurnEnd compares a trailing
        // narrative block against the real answer surface, not
        // capturedText.join('') (which mis-suppresses when the model emits
        // the same short string twice in a turn). REPLY_TOOLS ('reply',
        // 'stream_reply') carry the answer in input.text; only those count.
        if (REPLY_TOOLS.has(name) && typeof ev.input?.text === 'string') {
          turn.lastReplyText = ev.input.text as string
        }
        if (turn.orphanedReplyTimeoutId != null) {
          clearTimeout(turn.orphanedReplyTimeoutId)
          turn.orphanedReplyTimeoutId = null
        }
        // Delete the activity feed only when the FINAL answer has landed —
        // NOT on an ack-first interim reply ("On it"). Gating on the first
        // reply deleted the feed on the ack, so the post-ack work
        // (sub-agents/tools) rendered into nothing — the "agent went silent
        // after On it" gap. `finalAnswerDelivered` is set by executeReply
        // (isFinalAnswerReply) before this tool_use event fires; turn_end
        // (below) clears unconditionally as the idempotent no-reply / race net.
        if (turn.finalAnswerDelivered) {
          clearActivitySummary(turn)
        }
      }
      // The live activity feed is driven by the real-time `tool_label`
      // event (PreToolUse sidecar) rather than this flush-gated tool_use
      // path — see `case 'tool_label'`. The sidecar fires at tool-call
      // time regardless of when claude flushes the transcript, which is
      // the determinism fix: on a fast/clustered-tool turn the JSONL
      // tool_use rows aren't on disk until ~turn-end, so sourcing the
      // feed here would lose them.
      if (!ctrl) return
      if (isTelegramSurfaceTool(name)) return
      ctrl.setTool(name)
      if (ev.toolUseId) {
        typingWrapper.onToolUse(ev.toolUseId, turn.sessionChatId, name, turn.sessionThreadId ?? null)
      }
      return
    }
    case 'tool_label': {
      // Real-time activity-feed driver. The PreToolUse hook wrote this
      // label synchronously at tool-call time; the sidecar surfaced it
      // here (~250ms) independent of the transcript flush. Accumulate it
      // into the live feed and edit the activity message in place — this
      // is what makes the feed deterministic on fast/clustered-tool turns
      // where the JSONL tool_use rows arrive too late.
      const turn = currentTurn
      if (turn == null) return
      // SECONDARY FIX: an active tool_label means the model is producing work
      // right now — re-arm the orphaned-reply fuse so a multi-phase tool turn
      // (write → compile → test → fix) that regularly emits labels doesn't let
      // the 30 s timer run down between labels. Mirrors how `case 'text':` calls
      // resetOrphanedReplyTimeout() at ~line 10786.
      resetOrphanedReplyTimeout()
      // Surface tools (reply/stream_reply/react) are the conversation, not
      // activity — the hook labels them ("Replying"), so filter by name.
      if (isTelegramSurfaceTool(ev.toolName)) return
      // Stop feeding once the FINAL answer has landed — the hand-off where
      // `clearActivitySummary` deletes the feed so the answer is the
      // authoritative surface. Gating on `replyCalled` (any reply) killed the
      // feed on an ack-first interim "On it", so the post-ack work had no live
      // surface; gate on `finalAnswerDelivered` so the feed keeps narrating
      // between the ack and the real answer. Without this a tool called after
      // the FINAL answer would re-`sendMessage` a fresh feed below it (flicker).
      // Safe ordering: `tool_label` is real-time (PreToolUse, ~250ms) while
      // `finalAnswerDelivered` is set from executeReply on the final answer.
      //
      // Feed-reopen-after-ack: a tool label here means the model is STILL
      // working. If the turn was already marked finalAnswerDelivered, the
      // "final" reply MIGHT have been an interim ACK ("on it, checking
      // Brevo…" pings, classified final by isFinalAnswerReply), so the
      // post-ack work had no live feed — the gate above dropped every label.
      //
      // ACK-ONLY refinement: finalAnswerDelivered latches true for BOTH a
      // short pinging ack AND a substantive answer. Reopening unconditionally
      // is harmful after a GENUINE final answer — routine post-answer
      // housekeeping (memory write / TodoWrite / Bash; non-surface tools that
      // reach here) would reset finalAnswerDelivered=false and trip the
      // silent-end re-prompt (NOT zero-outbound gated) → duplicate answer. So
      // reopen ONLY when the prior final was a short ack
      // (finalAnswerSubstantive=false). When it was substantive, drop the
      // label (legacy gate) so the genuine final stays delivered.
      //
      // On reopen: reclassify the interim ack — the turn has NOT delivered its
      // final answer while still doing tool work. Reset the flag and clear
      // activityMessageId so a FRESH feed message opens below the ack, then
      // proceed normally. When the model's REAL final answer lands,
      // executeReply / stream_reply re-set finalAnswerDelivered=true (and
      // finalAnswerSubstantive) and the feed gates off again. The reset keeps
      // the #2137 serialize gate HOLDING the next topic mid-work (next-topic
      // liveness is the bounded no-reply timer's job) and lets the silent-end
      // re-prompt fire if the turn ends on only an ack.
      // Kill switch SWITCHROOM_FEED_REOPEN_AFTER_ACK=0 → legacy `return`.
      if (turn.finalAnswerDelivered) {
        // decideFeedReopen returns dropLabel (legacy return) or the reset
        // deltas: finalAnswerDelivered→false (the turn has NOT delivered its
        // final answer while still doing tool work), activityMessageId→null
        // (a FRESH feed message opens below the ack), activityLastSentRender
        // →null (so the drain loop's `pending !== lastSent` guard never
        // mistakes the fresh render for the ack's finalized one and skips it).
        const reopen = decideFeedReopen({
          finalAnswerDelivered: turn.finalAnswerDelivered,
          // ACK-ONLY: reopen only when the prior final was a short ack, not a
          // substantive answer — otherwise post-answer housekeeping would
          // reset finalAnswerDelivered and trip the silent-end re-prompt.
          finalAnswerSubstantive: turn.finalAnswerSubstantive,
          enabled: FEED_REOPEN_AFTER_ACK_ENABLED,
        })
        if (reopen.dropLabel) return
        turn.finalAnswerDelivered = reopen.reset!.finalAnswerDelivered
        turn.activityMessageId = reopen.reset!.activityMessageId
        turn.activityLastSentRender = reopen.reset!.activityLastSentRender
      }
      const rendered = appendActivityLabel(turn.mirrorLines, ev.label)
      if (rendered != null) {
        // Count surfaced tool steps — the single source of truth for the `tools=`
        // lifecycle field and the `✓ N steps` total. Incremented HERE (not at the
        // top of the case) so the count stays consistent with what the feed
        // actually surfaces: an empty label (appendActivityLabel → null) or a
        // label dropped by the post-final-answer reopen guard never inflates it.
        // Surface tools (reply/react) returned earlier; send_typing/sync_retain
        // are suppressed at the hook (computeLabel → null) so they never arrive.
        turn.labeledToolCount++
        // A new tool label = a new live step → re-anchor the heartbeat clock so
        // the " · Ns" elapsed restarts from this step (and the feed itself just
        // advanced, so it isn't stale).
        turn.lastToolLabelAt = Date.now()
        // Production-liveness: a NEW model-driven activity label is genuine
        // liveness (the model emitted a new step), so reset the silence-poke
        // clock — this is the safe site, NOT drainActivitySummary, because the
        // framework feedHeartbeatTick also drains (climbing-elapsed re-renders)
        // and would falsely reset the clock forever on a hung-mid-tool turn,
        // reintroducing the #1556 dangling-turn wedge. Only the model emitting a
        // fresh label reaches here.
        // PR-4e — keyed liveness under the flag. Flag-OFF keeps the literal
        // `currentTurn === turn` (a late tool-label for topic A must reset A's
        // silence clock, not topic B's); flag-ON resolves A by ITS OWN key so a
        // flip to B doesn't falsify A's liveness here.
        if (
          SILENCE_LIVENESS_PRODUCTION &&
          (EMISSION_AUTHORITY_ENABLED ? turnLiveForItsTopic(turn) : currentTurn === turn)
        ) {
          silencePoke.noteProduction(statusKey(turn.sessionChatId, turn.sessionThreadId), Date.now())
        }
        // Recompose so any active foreground sub-agent's nested block (Model A)
        // is preserved when the parent appends its own step. composeTurnActivity
        // == the flat render when no foreground sub-agent is active.
        turn.activityPendingRender = composeTurnActivity(turn) ?? rendered
        const ea = emissionAuthorityFor(turn)
        // PR-4d: route through the centralized chatLock-serialized card-drain gate.
        cardDrainGate(turn, ea, () => {
        if (ea.mayDrain(turn)) {
          // Producer B (tool label): always OPEN-eligible (labeledToolCount was
          // incremented just above). A turn that started conversational and now
          // dispatches a tool opens here, rendering any narration accumulated
          // by the suppressed narrative-SHOW drains (design §9 lever 5 / R4).
          // PR-4a: routed through the emission-authority façade (no-op delegate).
          ea.openOrEditCard('tool', () => {
            turn.activityInFlight = drainActivitySummary(turn, 'tool')
          })
        }
        })
      }
      return
    }
    case 'text': {
      // #1067: snapshot at entry. The answer-stream creation closures
      // below also read `turn` instead of currentTurn so they pin to
      // this turn's chat for the stream's lifetime.
      //
      // #1664 ordering note: a `text` event can arrive AFTER turn_end has
      // nulled currentTurn (the issue observed `answer_lane_update
      // transport:"draft"` firing post-turn_end). Such a late event is
      // dropped here by the `turn != null` guard — it is NOT folded back
      // into the just-ended turn. That is deliberate and safe: by the
      // time this fires, the turn atom has been handed to
      // endCurrentTurnAtomic and turn_end has already run its flush /
      // silent-end decision; re-opening a closed turn (re-creating an
      // answer stream, re-evaluating decideTurnFlush) would be a large,
      // race-prone change. The #1664 safety net does not depend on
      // catching the late text: a turn whose real answer lost the race
      // ends with finalAnswerDelivered=false, so recordUndeliveredTurnEnd
      // engages the Stop-hook re-prompt and the model re-delivers the
      // answer through the reply tool. The dropped draft text is
      // recovered by re-prompt, not by post-hoc materialization.
      const turn = currentTurn
      if (turn != null) {
        turn.capturedText.push(ev.text)
        // Narrative-dedup gate step 1 (JSONL-text-narrative primitive):
        // stage this text block for one lookahead step. If a previous block
        // was pending with nothing reply-shaped after it, it flushes here as
        // a SHOWN transient liveness step. The eventual SHOW/SUPPRESS of THIS
        // block is decided by the next tool_use / turn_end. Invariant
        // `chat-is-the-single-source-of-truth` (reference/invariants.md): a
        // SHOWN line rides the same renderStepFeed path as a tool step —
        // transient + clipped, never a persisted parallel mirror. This is a
        // separate lane from the answer-stream wiring below (which owns the
        // canonical reply), so the two never fight over the same text.
        stagePendingNarrative(turn, ev.text)
        // Issue #195: feed the answer-lane stream. The stream itself
        // gates on minInitialChars and throttles edits — short replies
        // stay below the threshold and never spawn a message.
        if (turn.answerStream == null) {
          turn.answerStream = createAnswerStream({
            chatId: turn.sessionChatId,
            threadId: turn.sessionThreadId,
            // VISIBLE on (opt-in, SWITCHROOM_VISIBLE_ANSWER_STREAM=1) →
            //   minInitialChars:1 opens a user-visible edit-in-place preview on the
            //   first text chunk. At turn_end the preview is materialized as a pinged
            //   final answer (materialize()) when the model never called reply.
            // VISIBLE off (default) → minInitialChars:MAX so NO visible preview ever
            //   opens; the reply tool is the single canonical formatted message
            //   (no flash). The draft transport is permanently retired — both modes
            //   use sendMessage + editMessageText for any message that does open.
            minInitialChars: ANSWER_LANE.minInitialChars,
            // #2669: the answer-stream ships the RAW transcript markdown; the
            // sendMessage/editMessageText wrappers below send it via the
            // rich-message path (`sendRichMessage` / `editMessageText({ markdown })`),
            // matching every other outbound lane. No render step needed.
            // #1075: route through robustApiCall so flood-wait,
            // benign-400, and THREAD_NOT_FOUND are handled uniformly
            // instead of crashing the answer-stream loop on a deleted
            // forum topic. answer-stream's own try/catch already
            // tolerates undefined returns from editMessageText.
            //
            // disable_notification gating by purpose (2026-05-25):
            //
            // - purpose='stream' (the live edit-in-place preview): SILENT.
            //   Without disable_notification, the first text chunk that
            //   opens the visible message device-pings, and then when the
            //   model later calls the reply MCP tool, that reply pings
            //   AGAIN (the over-ping safety net at gateway.ts:~4452 only
            //   sees executeReply paths, not this direct sendMessage). Two
            //   device pings per multi-step turn — the original Bug A.
            //   Edits in place don't notify regardless (Telegram semantics).
            //
            // - purpose='materialize' (turn-end final-answer fresh send,
            //   only fires for text-only turns where the stream IS the
            //   answer): PING. The user reached for the agent and the
            //   model produced an answer; per beat 5 of
            //   `reference/rfcs/conversational-pacing.md` the final answer MUST
            //   ping the device exactly once. Without this carve-out, a
            //   short text-only turn ("on it" being the whole response)
            //   lands silently and the user has no notification to know
            //   the answer arrived — the original over-correction.
            //
            // - purpose unset (defensive default): SILENT. Treat as
            //   stream-purpose so we never accidentally fire a stray ping
            //   from an unrecognised sendMessage callsite.
            sendMessage: async (chatId, text, params) => {
              const tid = params?.message_thread_id
              const silent = params?.purpose !== 'materialize'
              const msg = await robustApiCall(
                () =>
                  // allow-raw-bot-api: sendRichMessage is not in the THREAD_NOT_FOUND blast pattern; answer-stream tolerates failures via its own try/catch
                  // sendRichMessage doesn't accept link_preview_options — omit it.
                  bot.api.sendRichMessage(chatId, richMessage(text), {
                    disable_notification: silent,
                    ...(tid != null ? { message_thread_id: tid } : {}),
                    ...(params?.reply_parameters != null
                      ? { reply_parameters: params.reply_parameters }
                      : {}),
                  }),
                {
                  chat_id: chatId,
                  verb: `answer-stream.sendMessage(${params?.purpose ?? 'stream'})`,
                  ...(tid != null ? { threadId: tid } : {}),
                },
              )
              return { message_id: msg.message_id }
            },
            editMessageText: (chatId, messageId, text, params) => {
              const tid = params?.message_thread_id
              return robustApiCall(
                () =>
                  bot.api.editMessageText(chatId, messageId, richMessage(text), {
                    ...(tid != null ? { message_thread_id: tid } : {}),
                    ...(params?.link_preview_options != null
                      ? { link_preview_options: params.link_preview_options }
                      : {}),
                  }),
                {
                  chat_id: chatId,
                  verb: 'answer-stream.editMessageText',
                  ...(tid != null ? { threadId: tid } : {}),
                },
              )
            },
            deleteMessage: (chatId, messageId) =>
              robustApiCall(
                () => bot.api.deleteMessage(chatId, messageId),
                { chat_id: chatId, verb: 'answer-stream.deleteMessage' },
              ),
            log: (msg) => process.stderr.write(`telegram gateway: ${msg}\n`),
            warn: (msg) => process.stderr.write(`telegram gateway: ${msg}\n`),
            // Issue #203: route answer-lane events through the streaming
            // metrics sink. Each successful update/edit/draft and the final
            // materialize emit one event. Also tick the silent-gap tracker
            // so answer-lane activity doesn't count as silent.
            //
            // #1067: the closure captures `turn` so the signal tracker
            // ticks against THIS turn's chat key. If a new turn took over,
            // the captured `turn` no longer matches `currentTurn` and we
            // skip the tick (the new turn has its own answer stream).
            onMetric: (metricEv) => {
              logStreamingEvent(metricEv)
              // PR-4e — keyed liveness under the flag. Flag-OFF keeps the literal
              // `currentTurn === turn` (a draft-update metric for topic A's stream
              // must tick A's signal/silence clock); flag-ON resolves A by its own
              // key so a flip to B doesn't skip A's tick.
              if (EMISSION_AUTHORITY_ENABLED ? turnLiveForItsTopic(turn) : currentTurn === turn) {
                signalTracker.noteSignal(
                  statusKey(turn.sessionChatId, turn.sessionThreadId),
                  Date.now(),
                )
                // Production-liveness: a draft update is the agent visibly
                // composing — reset the silence-poke clock so a long
                // compose-only turn (no tools, no reply yet) isn't torn down.
                if (SILENCE_LIVENESS_PRODUCTION) {
                  silencePoke.noteProduction(
                    statusKey(turn.sessionChatId, turn.sessionThreadId),
                    Date.now(),
                  )
                }
              }
            },
            // #646 — wire the shared outboundDedup into the answer-stream
            // materialize path so it participates in the same dedup window
            // as turn-flush and reply/stream_reply. Closured chatId /
            // threadId come from the captured `turn` snapshot, stable for
            // the lifetime of the stream.
            checkDedup: (text: string) => {
              return outboundDedup.check(turn.sessionChatId, turn.sessionThreadId, text, Date.now(), turn.registryKey ?? null) != null
            },
            recordDedup: (text: string) => {
              outboundDedup.record(turn.sessionChatId, turn.sessionThreadId, text, Date.now(), turn.registryKey ?? null)
            },
            // #648 — write answer-stream materializations into the SQLite
            // history buffer so get_recent_messages can surface them. Guard
            // with HISTORY_ENABLED, matching the turn-flush pattern at ~3783.
            recordOutbound: ({ messageId, text }: { messageId: number; text: string }) => {
              if (!HISTORY_ENABLED) return
              try {
                recordOutbound({
                  chat_id: turn.sessionChatId,
                  thread_id: turn.sessionThreadId ?? null,
                  message_ids: [messageId],
                  texts: [text],
                })
              } catch {}
            },
          })
        }
        // #549 fix: route the chunk through the preamble suppressor
        // instead of immediately updating the answer stream. If a
        // tool_use arrives within the buffer window, the suppressor
        // drops the chunk (the card owns it). Otherwise it flushes as
        // answer text. `turn.capturedText` is unchanged — it remains
        // the safety-net source for turn-flush prose recovery.
        preambleSuppressor.onText(ev.text)
      }
      resetOrphanedReplyTimeout()

      if (isContextExhaustionText(ev.text) && turn != null) {
        const chatId = turn.sessionChatId
        const threadId = turn.sessionThreadId
        const now = Date.now()
        if (now - lastContextExhaustionWarningAt < CONTEXT_EXHAUSTION_COOLDOWN_MS) return
        lastContextExhaustionWarningAt = now
        process.stderr.write(`telegram gateway: context exhaustion detected — notifying user\n`)
        const warnOpts = {
          ...(threadId != null ? { message_thread_id: threadId } : {}),
        }
        // #1075: thread-id-bearing, fire-and-forget — swallow on
        // THREAD_NOT_FOUND so a deleted topic doesn't crash the gateway.
        void swallowingApiCall(
          () =>
            // allow-raw-bot-api: wrapped in swallowingApiCall (retry policy)
            bot.api.sendRichMessage(
              chatId,
              richMessage('⚠️ **Context window full** — send \`/restart\` to start a fresh session.'),
              warnOpts,
            ),
          {
            chat_id: chatId,
            verb: 'context-exhaust-warning',
            ...(threadId != null ? { threadId } : {}),
          },
        )
        // #1713: context-exhaustion is a terminal failure path — paint 😱
        // and finalize the controller. `setError` alone is non-terminal
        // (recovery permitted); since this turn is genuinely ending, route
        // through `finalize('error')` so the emoji lands and the controller
        // stops accepting further transitions.
        finalizeStatusReaction(chatId, threadId, 'error')
        // Surfaced during CC-5 investigation (`docs/status-ask-cause-classes.md`):
        // the context-exhaust bail path teardown was missing
        // `silencePoke.endTurn(key)`. Without it, the silence-poke state for
        // this turn lingers in the Map. Once 300s of clock-time passes from
        // the turn's original start, the framework fallback fires and the
        // gateway sends a user-visible "still working… (no update from agent
        // in 5 min)" message — for a turn the gateway internally considers
        // dead and has already told the user is over (the ⚠️ Context window
        // full message above). Match the pattern used at the regular
        // turn-end path (line ~5039) and the wedged-turn path (~5290).
        const ceKey = statusKey(chatId, threadId)
        silencePoke.endTurn(ceKey)
        pendingProgress.noteTurnEnd(ceKey)
        // Issue #195: tear down the answer-lane stream on context-exhaustion
        // bail-out. The user is being told the session needs /restart, so any
        // partially-streamed answer would be misleading.
        if (turn.answerStream != null) {
          turn.answerStream.stop()
          turn.answerStream = null
        }
        // Null the atom — this turn is being abandoned.
        endCurrentTurnAtomic(turn)
        // #549 fix — context-exhaustion teardown also resets preamble state.
        preambleSuppressor.reset()
      }
      return
    }
    case 'tool_result': {
      if (ev.toolUseId) typingWrapper.onToolResult(ev.toolUseId)
      return
    }
    case 'sub_agent_tool_use': {
      const turn = currentTurn
      if (turn == null) return
      if (!ev.toolUseId) return
      typingWrapper.onToolUse(ev.toolUseId, turn.sessionChatId, ev.toolName, turn.sessionThreadId ?? null)
      return
    }
    case 'sub_agent_tool_result': {
      if (ev.toolUseId) typingWrapper.onToolResult(ev.toolUseId)
      return
    }
    case 'turn_end': {
      // DEFENSIVE FIX: belt-and-braces guard against the synthetic backstop
      // (`durationMs: -1`) racing live work. durationMs >= 0 is the
      // authoritative signal from system/turn_duration; -1 is ONLY ever set
      // by the orphaned-reply backstop. Reject the synthetic event here so that
      // even if the PRIMARY fix's re-arm logic is bypassed (e.g. a very fast
      // fire before isLegitimatelyWorking() is sampled) we still don't tear
      // down a live feed mid-work. Extended from the original isMidToolCall()
      // check to the full isLegitimatelyWorking predicate so detached background
      // work and human-wait tools (ask_user) are also protected.
      // INVARIANT: a REAL turn_end (durationMs >= 0) is NEVER suppressed.
      if (ev.durationMs === -1) {
        const turn = currentTurn
        const key = turn != null ? statusKey(turn.sessionChatId, turn.sessionThreadId) : ''
        if (isLegitimatelyWorking(key)) {
          process.stderr.write(
            `telegram gateway: synthetic turn_end suppressed — legitimately working` +
            ` (in_flight=${toolFlightTracker.inFlightCount()},` +
            ` bg_work=${turn != null ? pendingProgress.hasPendingAsyncDispatch(key) : false})\n`,
          )
          return
        }
      }
      // Drain any still-pending tool dispatch typing entries — covers
      // transcript truncation or a Claude Code crash mid-tool.
      typingWrapper.drainAll()
      // Forum-topic placeholder cleanup removed in #553 PR 5 — the
      // forum-topic placeholder send is also gone, so there is
      // nothing to clear at turn_end.
      //
      // #1067: capture the turn atom at handler entry. The IIFE that
      // runs turn-flush below is async, so every read after the first
      // await would be subject to the reattribution race we're fixing.
      // All downstream code reads `turn.*` or its captured locals.
      const turn = currentTurn
      if (turn?.orphanedReplyTimeoutId != null) {
        clearTimeout(turn.orphanedReplyTimeoutId)
        turn.orphanedReplyTimeoutId = null
      }
      // Narrative-dedup gate step 3 (JSONL-text-narrative primitive): a
      // trailing narrative block with nothing after it. When the turn
      // delivered its answer via reply (replyCalled) the trailing text is
      // almost always a draft of that answer — compare against the ACTUAL
      // delivered reply text and SUPPRESS the duplicate; otherwise SHOW
      // genuine trailing narration ("Done — all green."). Must run BEFORE
      // clearActivitySummary so a SHOWN line lands in the feed's final
      // render. Always clears turn.pendingNarrative so it can't leak across
      // turns.
      //
      // NIT 2 (reply-proxy precision): use `turn.lastReplyText` (the
      // most-recent reply/stream_reply input.text) rather than
      // `capturedText.join('')`. The old proxy concatenated every captured
      // text block, so a turn that emitted the same short string twice
      // (e.g. "Done." as working narration, then "Done." as the reply) would
      // compare the trailing narration against a doubled "DoneDone" — still
      // a high-prefix match — and wrongly suppress genuine trailing
      // narration. Comparing against the actual reply text is exact. When
      // the turn delivered WITHOUT a reply tool (turn-flush emits
      // capturedText as the answer), fall back to capturedText.join('') so
      // that path's trailing-draft suppression is preserved.
      if (turn != null) {
        const deliveredText = turn.lastReplyText.length > 0
          ? turn.lastReplyText
          : (turn.replyCalled ? turn.capturedText.join('') : '')
        flushPendingNarrativeAtTurnEnd(turn, deliveredText)
      }
      // Clear the activity feed at the real end of the turn. This is the
      // no-reply safety net — a turn that ends without ever calling reply
      // (the answer is delivered by turn-flush / silent-end) still has its
      // feed removed. On a normal turn the feed was already cleared at the
      // first reply (the hand-off); clearActivitySummary is idempotent, so
      // the second call is a no-op.
      if (turn != null) {
        clearActivitySummary(turn)
      }
      // #549 fix — flush any pending preamble BEFORE the answer stream is
      // nulled below. Text emitted immediately before turn_end (no tool
      // followed) is the answer; the suppressor's emitAnswer callback
      // would no-op against a nulled stream, silently dropping the text
      // (regression for short no-tool replies). Order matters here: this
      // call must come before the retract/null block.
      preambleSuppressor.flushNow()
      // #656: by default we ALWAYS retract the answer-lane stream at
      // turn_end. Turn-flush is the canonical emitter for no-reply
      // turns; materialising here would race it and post raw model
      // text (no HTML conv).
      //
      // #869-Phase1 override: when `ANSWER_STREAM_VISIBLE_ENABLED` is
      // on, the stream is rendering a USER-VISIBLE message in the
      // chat timeline. When the stream is the de-facto final answer
      // (model never called reply, captured text is substantive), we
      // need to:
      //   1. Send a FRESH pinged message via `stream.materialize()`
      //      so the user gets a device notification — beat 5 of the
      //      conversational-pacing contract requires exactly one
      //      ping per turn for the final answer. Without this,
      //      text-only short turns ("on it" being the whole reply)
      //      land silently and the user has no notification to know
      //      the answer arrived (the failure caught by the
      //      midturn-silent-dm UAT, 2026-05-25).
      //   2. Delete the silent streamed preview message so the user
      //      doesn't see a duplicate (the streamed message in place
      //      + the fresh materialized ping). materialize() handles
      //      the fresh send but leaves the old streamed message_id
      //      orphaned by design — we delete it explicitly here.
      //
      // The previous behavior (just `stream.stop()` to freeze the
      // streamed message in place) avoided the duplicate but also
      // skipped the ping. Materialize-and-delete trades a brief
      // visual "the streamed message is replaced by a fresh one"
      // (often imperceptible for short turns where the streaming
      // barely had time to register; mildly visible for longer
      // turns) in exchange for an always-correct turn-end ping.
      let streamFinalizedAsAnswer = false
      if (turn?.answerStream != null) {
        const stream = turn.answerStream
        const streamedMsgId = stream.messageId()
        const streamedFinalText = turn.capturedText.join('').trim()
        if (
          // Only when a VISIBLE preview actually opened (visible flag on): a
          // text-only no-reply turn that streamed a visible preview must
          // materialize a pinged final answer + delete the preview, NOT fall into
          // the else-branch retract() which would delete the user's only copy of
          // the answer (a lost-answer bug). Gated on the visible flag alone (the
          // flash-regression decoupling): with the visible stream OFF (default)
          // no preview opens (minInitialChars:MAX), so streamedMsgId is null and
          // this branch is unreachable — the no-reply answer is delivered by the
          // turn-flush backstop below instead, the pre-v0.14.68 path. The
          // reply-tool branch hits retract() on a non-opened lane (a no-op), so
          // there is no preliminary to flash.
          ANSWER_LANE.opensVisiblePreview
          && !turn.replyCalled
          && streamedMsgId != null
          && streamedFinalText.length > 0
        ) {
          turn.answerStream = null
          streamFinalizedAsAnswer = true
          turn.finalAnswerDelivered = true
          // Feed-reopen refinement: the stream is being finalized as the
          // turn's answer (the model's terminal text), i.e. done=true by
          // construction → substantive. Post-answer housekeeping must NOT
          // re-open the feed.
          turn.finalAnswerSubstantive = true
          // Capture the old streamed message_id BEFORE materialize so
          // we can delete it after the fresh ping send. materialize()
          // overwrites `streamMsgId` internally with the new send's id;
          // without capturing here we'd lose the reference.
          const oldStreamedMsgId = streamedMsgId
          // Fire-and-forget materialize-and-delete sequence.
          //
          // Bookkeeping (dedup + history): handled inside
          // `materialize()` itself — see `answer-stream.ts:~548-549`
          // which calls the injected `recordDedup` + `recordOutbound`
          // callbacks with the NEW (fresh-send) message_id only after a
          // successful send. We deliberately do NOT pre-record here —
          // doing so populates the same `outboundDedup` store that
          // materialize's internal `checkDedup` consults at
          // `answer-stream.ts:~510`, causing materialize to dedup-
          // suppress its own send (return undefined, no ping fires) —
          // the exact failure mode this PR exists to fix. Let
          // materialize own the bookkeeping; gateway only sequences the
          // operations.
          //
          // Delete gating: only run the cleanup `deleteMessage` if
          // materialize actually sent (returned a numeric sentId). If
          // it dedup-suppressed or threw, the streamed preview is the
          // user's only copy of the answer and MUST be preserved.
          void (async () => {
            let materializedId: number | undefined
            try {
              materializedId = await stream.materialize()
            } catch (err) {
              process.stderr.write(
                `telegram gateway: answer-stream materialize failed: ${
                  err instanceof Error ? err.message : String(err)
                }\n`,
              )
              return
            }
            if (typeof materializedId !== 'number' || !Number.isFinite(materializedId)) {
              // materialize() returned undefined — either pendingText
              // was empty, the body was a silent marker (NO_REPLY /
              // HEARTBEAT_OK), or `checkDedup` suppressed it. In every
              // such case the streamed preview is the user's only copy
              // of the content; don't delete it.
              process.stderr.write(
                `telegram gateway: answer-stream materialize returned no msgId ` +
                `chat=${turn.sessionChatId} oldMsg=${oldStreamedMsgId} — ` +
                `preserving silent preview as the user's only copy\n`,
              )
              return
            }
            // Materialize sent a fresh pinged message at materializedId.
            // Delete the silent streamed preview so the chat shows one
            // canonical message (the fresh pinged one) and not two with
            // duplicate content. Best-effort; failures (already gone,
            // permission denied) leave a brief visible duplicate which
            // we accept rather than retry-storming.
            try {
              // allow-raw-bot-api: cleanup delete of silent streamed preview
              await bot.api.deleteMessage(turn.sessionChatId, oldStreamedMsgId)
            } catch (delErr) {
              process.stderr.write(
                `telegram gateway: answer-stream materialize-cleanup ` +
                `delete failed for msgId=${oldStreamedMsgId}: ${
                  delErr instanceof Error ? delErr.message : String(delErr)
                }\n`,
              )
            }
            process.stderr.write(
              `telegram gateway: answer-stream materialized as answer ` +
              `chat=${turn.sessionChatId} oldMsg=${oldStreamedMsgId} ` +
              `newMsg=${materializedId} chars=${streamedFinalText.length}\n`,
            )
          })()
        } else {
          turn.answerStream = null
          void stream.retract().catch((err) => {
            process.stderr.write(
              `telegram gateway: answer-stream retract failed: ${
                err instanceof Error ? err.message : String(err)
              }\n`,
            )
          })
        }
      }
      if (turn == null) return
      const chatId = turn.sessionChatId
      const threadId = turn.sessionThreadId
      const ctrl = activeStatusReactions.get(statusKey(chatId, threadId))

      // #1122 PR3: #51 prose-as-step recovery removed with the
      // progress card. Without the card there's no narrative-steps
      // surface to recover from. The decideTurnFlush 'empty-text'
      // path now relies on capturedText alone.

      // #869-Phase1: when the answer-stream finalised as the answer
      // above, skip the turn-flush IIFE entirely — its job (deliver
      // captured text) is already done by the visible stream, and
      // running it would race a duplicate fresh-sendMessage against
      // the user-visible edited message.
      const flushDecision = streamFinalizedAsAnswer
        ? ({ kind: 'skip', reason: 'reply-called' } as ReturnType<typeof decideTurnFlush>)
        : decideTurnFlush({
            chatId: turn.sessionChatId,
            replyCalled: turn.replyCalled,
            capturedText: turn.capturedText,
            flushEnabled: TURN_FLUSH_SAFETY_ENABLED,
          })
      if (flushDecision.kind === 'skip' && flushDecision.reason !== 'reply-called') {
        process.stderr.write(
          `telegram gateway: turn-flush skipped — reason=${flushDecision.reason}\n`,
        )
        // Ghost-reply detection (#45): the model ended a Telegram-inbound turn
        // without calling reply/stream_reply AND without emitting any assistant
        // text that the turn-flush could forward. The user will see only the
        // progress card disappear — no visible output. Log a prominent warning
        // so this silent-drop pattern is immediately visible in the logs.
        if (
          flushDecision.reason === 'empty-text' &&
          !turn.replyCalled
        ) {
          process.stderr.write(
            `telegram gateway: WARN ghost-reply detected — turn ended with zero outbound messages` +
            ` chat=${chatId} turnStartedAt=${turn.startedAt} replyCalled=false capturedText=empty` +
            ` — the progress card steps were the only thing the user saw (#45)\n`,
          )
          // #2527: emit structured WARN so the reaction-only failure mode is
          // machine-readable in the streaming-metrics channel.
          const tKey = statusKey(chatId, threadId)
          logStreamingEvent({
            kind: 'turn_no_reply_warn',
            chatId,
            threadId,
            turnId: turn.turnId,
            turnDurationMs: turn.startedAt > 0 ? Date.now() - turn.startedAt : 0,
            reactionCount: reactionTransitionCounts.get(tKey) ?? 0,
          })
        }
      }

      // ── Sentinel suppression (NO_REPLY / HEARTBEAT_OK) ──────────────────
      // When the model's only output is a silent-turn sentinel we must:
      //  1. NOT finalise the progress card (that would push a "Done" edit).
      //  2. NOT send any reply message to the user.
      //  3. Unpin the progress card so no orphaned ⚙️ Working… lingers.
      //  4. Log at debug level and fall through to normal state cleanup.
      if (flushDecision.kind === 'skip' && flushDecision.reason === 'silent-marker') {
        // Don't try to distinguish NO_REPLY vs HEARTBEAT_OK in the log line:
        // `isSilentFlushMarker` accepts trailing punctuation (e.g. "NO_REPLY.")
        // and case variants, so a strict equality check would print the wrong
        // reason. The flushDecision.reason is the source of truth.
        process.stderr.write(
          `telegram gateway: silent-turn-suppression: chat=${chatId} turnKey=${turn.startedAt} reason=silent-marker\n`,
        )
        // Drop progress-card streams without finalising — the normal
        // closeProgressLane call below would call stream.finalize() which
        // sends a final "Done" edit to Telegram. Skip that for silent turns.
        const suppressPrefix = chatKeyWithSuffix(chatId, threadId, 'progress')
        for (const [key] of activeDraftStreams) {
          if (key.startsWith(suppressPrefix)) {
            activeDraftStreams.delete(key)
          }
        }
        // Unpin without editing the message so no orphaned card lingers.
        unpinProgressCardForChat?.(chatId, threadId)
        // Fall through to normal state cleanup (finalize, purge, etc.)
        // but skip the regular closeProgressLane so we don't re-finalize.
        // #1713: silent-marker turns still finalize to 👍 — turn_end is
        // the terminal trigger regardless of whether a reply landed.
        finalizeStatusReaction(chatId, threadId, 'done')
        // Match the normal turn_end path's telemetry so silent-marker turns
        // still appear in turn-duration graphs.
        {
          const sKey = streamKey(chatId, threadId)
          const turnDurationMs = turn.startedAt > 0 ? Date.now() - turn.startedAt : 0
          logStreamingEvent({
            kind: 'turn_end',
            chatId,
            durationMs: turnDurationMs,
            suppressClearedCount: suppressPtyPreview.has(sKey) ? 1 : 0,
          })
          // #203: compute trailing gap (last signal → turn_end) then emit.
          const tKey = statusKey(chatId, threadId)
          signalTracker.noteSignal(tKey, Date.now())
          logStreamingEvent({ kind: 'turn_signal_gap', chatId, longestGapMs: signalTracker.getLongestGap(tKey), turnDurationMs })
          // #1122 KPI: emit turn_ended (silent-marker path) with TTFO +
          // outbound-gap metrics for the conversational-pacing dashboard.
          const outboundMetrics = signalTracker.getOutboundMetrics(tKey)
          emitRuntimeMetric({
            kind: 'turn_ended',
            chat_id: chatId,
            thread_id: threadId ?? null,
            duration_ms: turnDurationMs,
            ttfo_ms: outboundMetrics.ttfoMs,
            outbound_count: outboundMetrics.outboundCount,
            longest_silent_gap_ms: outboundMetrics.longestOutboundGapMs,
            ended_via: 'silent',
          })
          // #1122 PR4 fix: deterministic silent-end detection for the
          // Stop hook. PR3 deleted the writer with the progress card;
          // this restores it. If the user-message turn ended without
          // any outbound, write the state file so silent-end-interrupt
          // -stop.mjs blocks the stop and re-prompts the agent.
          if (outboundMetrics.outboundCount === 0) {
            writeSilentEndState({
              chatId,
              threadId: threadId ?? null,
              turnKey: tKey,
            })
          }
          // #1122 PR4 fix: PR3 removed the progressDriver.onTurnComplete
          // callback that cleared the turn-active marker on silent-marker
          // turns. The main turn-end path at ~line 5180 has its own
          // cleanup (#550 defence-in-depth) but the silent-marker path
          // relied solely on the driver callback. Without this the
          // bridge-watchdog (#412) reads a stale marker and could
          // false-positive wedge-detection across silent turns.
          try { removeTurnActiveMarker(STATE_DIR) } catch { /* best-effort */ }
          signalTracker.clear(tKey)
          silencePoke.endTurn(tKey)
          pendingProgress.noteTurnEnd(tKey)
        }
        lastPtyPreviewByChat.delete(statusKey(chatId, threadId))
        pendingPtyPartial = null
        closeActivityLane(chatId, threadId)
        // NOTE: closeProgressLane intentionally skipped — streams already dropped above.
        // #1067: null the atom so any late-arriving event for THIS turn
        // returns early at handler entry. A new `enqueue` swaps in a
        // fresh atom; the silent-turn teardown doesn't need to preserve
        // any of the prior turn's state.
        endCurrentTurnAtomic(turn)
        // #549 fix — silent-marker teardown drops any pending preamble.
        preambleSuppressor.dropNow()
        return
      }

      if (flushDecision.kind === 'flush') {
        let capturedText = flushDecision.text
        // Component 3 — origin-thread backstop. `chatId`/`threadId` are
        // captured from the turn atom (turn.sessionChatId/sessionThreadId)
        // at the top of this turn_end handler, NOT from the live
        // currentTurn and NEVER from chatThreadMap. So the turn-flush
        // answer always lands in the thread the turn originated from, even
        // if currentTurn has flipped — the same guarantee the reply path
        // gets via origin_turn_id.
        const backstopChatId = chatId
        const backstopThreadId = threadId
        const backstopCtrl = ctrl

        // Outbound secret scrub (#2044). Turn-flush delivers the model's
        // terminal answer prose when it skipped reply/stream_reply — that
        // is arbitrary agent free-text, sent via sendMessage/editMessageText
        // and previewed to stderr below, so it needs the same mask as the
        // three reply tools. Mirror the voice scrub: mask before the send,
        // the preview, and recordOutbound.
        capturedText = redactOutboundText(capturedText, 'turn_flush')

        // Voice scrub (PR #1683 follow-up). Turn-flush is the path
        // that fires when the model emits raw transcript text WITHOUT
        // calling reply / stream_reply. That captured text bypasses
        // PR #1683's executeReply scrub site entirely and is delivered
        // via the rich-message path directly. Scrub the capturedText on the
        // raw markdown so em-dashes never reach the wire. Kill switch:
        // SWITCHROOM_DISABLE_VOICE_SCRUB.
        {
          const scrub = scrubVoice(capturedText)
          if (scrub.replaced > 0) {
            capturedText = scrub.scrubbed
            emitRuntimeMetric({
              kind: 'voice_scrub_applied',
              chatKey: statusKey(backstopChatId, backstopThreadId),
              replaced: scrub.replaced,
              site: 'turn_flush',
            })
          }
        }

        // #1664 — turn-flush only fires when !replyCalled (decideTurnFlush
        // returns 'reply-called' otherwise). It legitimately delivers the
        // model's terminal text as the answer, so the turn IS answered.
        // Mark it now so the early-return below skips the silent-end
        // re-prompt for a turn whose answer is genuinely on its way out.
        // (The IIFE that actually sends runs after this branch's `return`;
        // since the silent-end block is on the sibling reply-called path
        // that this branch never reaches, this set is belt-and-braces —
        // it keeps the captured `turn` atom internally consistent for any
        // future reader.)
        turn.finalAnswerDelivered = true
        // Feed-reopen refinement: turn-flush delivers the model's terminal
        // transcript text as the genuine answer (not an ack). Default to
        // substantive so a late tool label does NOT re-open the feed / trip
        // the silent-end re-prompt. (Belt-and-braces, like the set above —
        // this branch returns before any further tool_label can arrive.)
        turn.finalAnswerSubstantive = true

        // #654 deterministic double-message fix. Hand off the pinned
        // progress card BEFORE state reset so the driver doesn't keep
        // editing it while turn-flush is rewriting it with the answer.
        // `wasEmitted` tells us whether the card has already been
        // published; `turnKey` lets us look up the pinned messageId
        // via pinMgr below. Idempotent — calling later in the IIFE
        // would be no-op against the same chatState.
        const cardTakeover = progressDriver?.takeOverCard({
          chatId: backstopChatId,
          threadId: backstopThreadId != null ? String(backstopThreadId) : undefined,
        }) ?? { wasEmitted: false, turnKey: null }
        const backstopCardMessageId =
          cardTakeover.wasEmitted && cardTakeover.turnKey != null
            ? (getPinnedProgressCardMessageId?.(cardTakeover.turnKey) ?? null)
            : null
        const backstopCardTurnKey = cardTakeover.turnKey

        // #1067: null the atom BEFORE the async IIFE starts. Any event
        // that arrives during the 500ms-suppression window or the
        // sendMessage await for this turn will see currentTurn == null
        // and bail; a new enqueue will swap in a fresh atom. The
        // `backstop*` locals above hold everything the IIFE needs.
        endCurrentTurnAtomic(turn)
        // #549 fix — turn-flush takes ownership of the captured-text
        // backup; reset the preamble buffer (its content is already in
        // the captured `capturedText`, which turn-flush is about to send).
        preambleSuppressor.dropNow()
        // #1289 fix — drain silence-poke + signal-tracker state for this
        // turn. The three sibling turn_end exit branches (context-exhaust
        // at ~5098, silent-marker at ~5097-5098, default reply-called tail
        // at ~5348-5349) all call signalTracker.clear + silencePoke.endTurn.
        // The flush-backstop branch was retrofitted in #1067 to null
        // currentTurn early but never had this cleanup added — leaving the
        // silence-poke state in the Map, so 300s after the original turn
        // start the framework fallback fires and the user sees
        // "still working… (no update from agent in 5 min)" on a turn the
        // gateway already considers over.
        {
          const tKey = statusKey(chatId, threadId)
          signalTracker.clear(tKey)
          silencePoke.endTurn(tKey)
          pendingProgress.noteTurnEnd(tKey)
        }

        void (async () => {
          await new Promise<void>(resolve => setTimeout(resolve, 500))
          if (HISTORY_ENABLED) {
            try {
              const { getRecentOutboundCount } = await import('../history.js')
              const recentCount = getRecentOutboundCount(backstopChatId, 2)
              if (recentCount > 0) {
                process.stderr.write(`telegram gateway: turn-flush suppressed — reply tool sent ${recentCount} message(s) within 2s\n`)
                // Do NOT finalize the status reaction here. As of #1713
                // the reaction is only finalized by the `turn_end` IPC
                // handler — mid-turn delivery proofs (local history,
                // stream finalize callbacks, executeReply post-send) no
                // longer transition the emoji. This branch just purges
                // the per-turn reaction tracking entry and returns.
                purgeReactionTracking(statusKey(backstopChatId, backstopThreadId))
                return
              }
            } catch {}
          }

          process.stderr.write(
            `telegram gateway: turn-flush firing — ${capturedText.length} chars without reply tool ` +
            `(chat=${backstopChatId} cardMsgId=${backstopCardMessageId ?? 'none'})\n`,
          )
          const sendOpts = {
            ...(backstopThreadId != null ? { message_thread_id: backstopThreadId } : {}),
            link_preview_options: { is_disabled: true },
          }
          const limit = RICH_MESSAGE_MAX_CHARS
          const htmlChunks = splitMarkdownChunks(capturedText, limit)
          const sentIds: number[] = []
          try {
            // #654 deterministic double-message fix. If the progress
            // card is on screen (60s timer fired before turn_end), edit
            // it in place with the first chunk of the answer instead of
            // posting a fresh message — avoids the user seeing both the
            // pinned card AND a separate text bubble for the same turn.
            // Multi-chunk answers (>4000 chars) edit chunk[0] into the
            // card and send chunks[1..] fresh. If the edit fails (e.g.
            // user deleted the card, parse-mode conflict), fall back to
            // a fresh send for chunk[0] — accepts a 2-message outcome
            // for that edge case rather than dropping the answer.
            // #1075: route turn-flush sends/edits through robustApiCall.
            // Edit-in-place isn't thread-id-bearing on its own (the
            // target message id implies a thread), so a stale-thread
            // 400 just fails the edit and the loop falls back to fresh
            // sendMessage. sendMessage IS thread-id-bearing — drop the
            // thread on THREAD_NOT_FOUND so the captured prose still
            // lands somewhere instead of being lost entirely.
            let firstSendUsedEdit = false
            let liveThreadId: number | undefined = backstopThreadId
            if (backstopCardMessageId != null && htmlChunks.length > 0) {
              try {
                await robustApiCall(
                  () =>
                    bot.api.editMessageText(
                      backstopChatId,
                      backstopCardMessageId,
                      richMessage(htmlChunks[0]),
                      sendOpts,
                    ),
                  {
                    chat_id: backstopChatId,
                    verb: 'turn-flush.editMessageText',
                    ...(liveThreadId != null ? { threadId: liveThreadId } : {}),
                  },
                )
                sentIds.push(backstopCardMessageId)
                firstSendUsedEdit = true
              } catch (err) {
                process.stderr.write(
                  `telegram gateway: turn-flush card-takeover edit failed: ${(err as Error).message} — falling back to sendMessage\n`,
                )
                if (err instanceof Error && err.message === 'THREAD_NOT_FOUND') {
                  liveThreadId = undefined
                }
              }
            }
            const remainingChunks = firstSendUsedEdit ? htmlChunks.slice(1) : htmlChunks
            for (const c of remainingChunks) {
              const sent = await retryWithThreadFallback(
                robustApiCall,
                (tid) => {
                  const opts = {
                    link_preview_options: { is_disabled: true },
                    ...(tid != null ? { message_thread_id: tid } : {}),
                  }
                  return bot.api.sendRichMessage(backstopChatId, richMessage(c), opts)
                },
                {
                  threadId: liveThreadId,
                  chat_id: backstopChatId,
                  verb: 'turn-flush.sendMessage',
                },
              )
              if (liveThreadId != null) {
                const sentMsg = sent as { message_thread_id?: number }
                if (sentMsg.message_thread_id == null) liveThreadId = undefined
              }
              sentIds.push(sent.message_id)
            }
            if (HISTORY_ENABLED && sentIds.length > 0) {
              try {
                recordOutbound({
                  chat_id: backstopChatId,
                  thread_id: backstopThreadId ?? null,
                  message_ids: sentIds,
                  texts: htmlChunks,
                })
              } catch {}
            }
            // #546 dedup: record what turn-flush just sent so a
            // late-arriving reply / stream_reply with the same
            // content gets suppressed (claude-code retries the
            // un-acked tool_call after a bridge reconnect).
            outboundDedup.record(
              backstopChatId,
              backstopThreadId,
              capturedText,
              Date.now(),
              currentTurn?.registryKey ?? null,
            )
            // #1713: route the backstop terminal through finalize() —
            // single terminal path keeps the controller contract clean.
            if (backstopCtrl) backstopCtrl.finalize('done')
            // Unpin the card. completeTurn cleans up pinMgr's per-turn
            // state and unpins via the API. If we didn't take over a
            // turn (cardTakeover.turnKey == null), fall back to the
            // legacy unpinForChat sweep.
            if (backstopCardTurnKey != null) {
              completeProgressCardTurn?.({
                chatId: backstopChatId,
                threadId: backstopThreadId,
                turnKey: backstopCardTurnKey,
              })
            } else {
              unpinProgressCardForChat?.(backstopChatId, backstopThreadId)
            }
          } catch (err) {
            process.stderr.write(`telegram gateway: turn-flush send failed: ${(err as Error).message}\n`)
            // #1713: backstop send failed — finalize as error so the
            // turn ends cleanly with 😱 rather than leaving it open.
            if (backstopCtrl) backstopCtrl.finalize('error')
          } finally {
            purgeReactionTracking(statusKey(backstopChatId, backstopThreadId))
          }
        })()
        return
      }

      // #1713: turn_end is THE terminal trigger. Finalize via the
      // single terminal path. Any prior intermediate states pending in
      // the debounce window are flushed by `finalize()` before the
      // terminal emoji emits.
      //
      // #2527 — role-aware terminal honesty: a USER turn that ends without
      // a delivered answer must NOT paint 👍 (the operator's "thumbs up so
      // it feels like you're done" report). It finalizes to the gentle
      // 'undelivered' terminal (😐) instead; the silent-end fallback below
      // carries the apology text. system/cron turns and NO_REPLY/HEARTBEAT_OK
      // turns (which return earlier) keep 👍 — their silence is legitimate.
      let terminalReason = decideTerminalReason({
        enabled: LIVENESS_TERMINAL_HONESTY,
        role: turn.role,
        finalAnswerDelivered: turn.finalAnswerDelivered,
      })
      // #2527 review note 1 — worker-hold carve-out: if the turn is STILL
      // legitimately working at turn_end (a background sub-agent the parent
      // dispatched is running on), don't prematurely paint 😐. Fall back to
      // 'done' so the existing deferred-done path holds ✍️ until the worker
      // completes (then 👍) — the worker-activity feed carries the progress.
      // Only a turn that genuinely ended undelivered AND is not still working
      // gets the honest 😐.
      if (terminalReason === 'undelivered' && isLegitimatelyWorking(statusKey(chatId, threadId))) {
        terminalReason = 'done'
      }
      if (terminalReason === 'undelivered') {
        process.stderr.write(
          `telegram gateway: WARN turn_no_reply — user turn ended with an ` +
          `ambient ack but no delivered answer; painting 😐 not 👍 ` +
          `chat=${chatId} thread=${threadId ?? '-'} turnId=${turn.turnId} (#2527)\n`,
        )
      }
      finalizeStatusReaction(chatId, threadId, terminalReason)
      {
        const sKey = streamKey(chatId, threadId)
        const turnDurationMs = turn.startedAt > 0 ? Date.now() - turn.startedAt : 0
        logStreamingEvent({
          kind: 'turn_end',
          chatId,
          durationMs: turnDurationMs,
          suppressClearedCount: suppressPtyPreview.has(sKey) ? 1 : 0,
        })
        // #203: compute trailing gap (last signal → turn_end) then emit.
        const tKey = statusKey(chatId, threadId)
        signalTracker.noteSignal(tKey, Date.now())
        logStreamingEvent({ kind: 'turn_signal_gap', chatId, longestGapMs: signalTracker.getLongestGap(tKey), turnDurationMs })
        // #1122 KPI: emit turn_ended with TTFO + outbound-gap metrics so
        // the dashboard can compute outbound silence p95 and TTFO p95
        // without per-event reconstruction.
        const outboundMetrics = signalTracker.getOutboundMetrics(tKey)
        emitRuntimeMetric({
          kind: 'turn_ended',
          chat_id: chatId,
          thread_id: threadId ?? null,
          duration_ms: turnDurationMs,
          ttfo_ms: outboundMetrics.ttfoMs,
          outbound_count: outboundMetrics.outboundCount,
          longest_silent_gap_ms: outboundMetrics.longestOutboundGapMs,
          ended_via: outboundMetrics.outboundCount > 0 ? 'reply' : 'silent',
        })
        // #1122 PR4 / #1161 / #1664: deterministic undelivered-turn
        // handling (see the silent-marker path above for the rationale).
        //   - first undelivered turn-end → recordSilentTurnEnd writes the
        //     state file so the Stop hook (silent-end-interrupt-stop.mjs)
        //     blocks the session-end and re-prompts the agent to deliver.
        //   - the Stop-hook re-prompt is already spent and the agent is
        //     STILL undelivered → recordSilentTurnEnd returns
        //     exhausted:true; deliver a user-facing fallback so the turn
        //     never just vanishes (the user otherwise only sees the card
        //     disappear).
        //
        // #1664 — the trigger is "no final answer delivered", not "zero
        // outbound". `outboundCount === 0` is now just the special case
        // where nothing landed at all. The added case: the model sent an
        // interim ack via reply/stream_reply (outboundCount > 0,
        // replyCalled = true) but ended the turn with its real answer as
        // plain transcript text — rendered into an ephemeral answer-lane
        // draft and retracted at turn_end, never finalized. finalAnswer-
        // Delivered stays false there, so the re-prompt engages and the
        // model re-delivers the answer through the reply tool. NO_REPLY /
        // HEARTBEAT_OK silent-marker turns return earlier and never reach
        // this path. The turn-flush 'flush' branch also returns earlier
        // (and sets finalAnswerDelivered=true defensively).
        if (turn.finalAnswerDelivered === false) {
          const silentEnd = recordUndeliveredTurnEnd({
            chatId,
            threadId: threadId ?? null,
            turnKey: tKey,
          })
          if (silentEnd.exhausted) {
            process.stderr.write(
              `telegram gateway: WARN silent-end fallback — agent stayed ` +
              `silent after the Stop-hook re-prompt; delivering fallback ` +
              `message chat=${chatId} turnKey=${tKey} (#1161)\n`,
            )
            void retryWithThreadFallback(
              robustApiCall,
              (tid) =>
                bot.api.sendMessage(
                  chatId,
                  SILENT_END_FALLBACK_TEXT,
                  tid != null ? { message_thread_id: tid } : {},
                ),
              { threadId, chat_id: chatId, verb: 'silent-end-fallback.sendMessage' },
            ).catch((err) => {
              process.stderr.write(
                `telegram gateway: silent-end fallback send failed: ${
                  err instanceof Error ? err.message : String(err)
                }\n`,
              )
            })
          }
        }
        signalTracker.clear(tKey)
        silencePoke.endTurn(tKey)
        pendingProgress.noteTurnEnd(tKey)
      }
      lastPtyPreviewByChat.delete(statusKey(chatId, threadId))
      pendingPtyPartial = null
      closeActivityLane(chatId, threadId)
      closeProgressLane(chatId, threadId)
      // Pre-allocated draft orphan-cleanup removed in #553 PR 5 — the
      // gateway no longer pre-allocates drafts on inbound, so there
      // is nothing to clean up at turn_end.
      // Stage 3b: stamp turn-end in the registry as endedVia='stop' (clean
      // turn_end emit). The kill paths (schedule_restart / SIGTERM) handle
      // the 'restart' / 'sigterm' cases separately in 3c.
      if (turnsDb != null && turn.registryKey != null) {
        // Phase 1 of #332: capture first ~200 chars of the assistant's reply.
        const capturedJoined = turn.capturedText.join('')
        const assistantReplyPreview = capturedJoined
          ? capturedJoined.slice(0, TURN_PREVIEW_MAX)
          : null
        // Closes #472 finding #11 — same SIGTERM race as recordTurnStart
        // above. Sub-ms SQLite write; the setImmediate deferral wasn't
        // saving anything observable but was opening a window where a
        // SIGTERM between turn_end and the microtask losing the end row
        // (turn appears in DB as still-running, then 3c relabels it as
        // 'sigterm' on shutdown — false negative for clean completion).
        const _turnKey = turn.registryKey
        try {
          recordTurnEnd(turnsDb, {
            turnKey: _turnKey,
            endedVia: 'stop' as const,
            lastAssistantMsgId: turn.lastAssistantMsgId,
            lastAssistantDone: turn.lastAssistantDone,
            assistantReplyPreview,
            toolCallCount: turn.toolCallCount,
          })
        } catch (err) {
          process.stderr.write(`telegram gateway: recordTurnEnd(stop) failed turnKey=${_turnKey}: ${(err as Error).message}\n`)
        }
      }
      // #550: symmetric cleanup with the writeTurnActiveMarker call at
      // the enqueue arm (line ~2810). Pre-fix, removal was single-pathed
      // through the (now-retired, #1122/#1126) progressDriver.onTurnComplete
      // callback, which silently no-op'd when forceCompleteTurn found no
      // active card — leaking the marker across restarts and triggering
      // watchdog false-positive restarts. That driver callback no longer
      // exists (progressDriver is permanently null); this explicit
      // removeTurnActiveMarker is now the sole cleanup path (idempotent —
      // unlinkSync swallows ENOENT).
      removeTurnActiveMarker(STATE_DIR)
      // #1067: null the atom in one assignment, replacing the seven
      // field clears the pre-refactor version did. Any late-arriving
      // event for this turn will see currentTurn == null and bail.
      endCurrentTurnAtomic(turn)
      // #549 fix — preamble flush already happened at the TOP of this
      // turn_end handler (before turn.answerStream is nulled). See
      // comment near line 3431.
      return
    }
  }
}

// ─── PTY partial handler ─────────────────────────────────────────────────
function handlePtyPartial(text: string): void {
  // #1067: build the PtyHandlerState from a snapshot of currentTurn.
  // The pty-partial-handler module keeps its own state-shape contract
  // (currentSessionChatId / currentSessionThreadId) because it's
  // independently tested; we adapt the names at this boundary.
  const turn = currentTurn
  const state: PtyHandlerState = {
    currentSessionChatId: turn?.sessionChatId ?? null,
    currentSessionThreadId: turn?.sessionThreadId,
    pendingPtyPartial: pendingPtyPartial != null ? { text: pendingPtyPartial } : null,
    activeDraftStreams,
    suppressPtyPreview,
    lastPtyPreviewByChat,
  }
  handlePtyPartialPure(text, state, {
    // grammy's Bot has a wider api shape than the local StreamBotApi
    // interface; runtime-compatible. Cast through never.
    bot: bot as never,
    retry: robustApiCall,
    logEvent: logStreamingEvent,
    onStreamSend: (chatId, messageId, charCount) => {
      logOutbound('pty_preview', chatId, messageId, charCount, 'initial_send')
      logStreamingEvent({ kind: 'draft_send', chatId, messageId, charCount })
    },
    onStreamEdit: (chatId, messageId, charCount) =>
      logStreamingEvent({ kind: 'draft_edit', chatId, messageId, charCount, sameAsLast: false }),
    onFirstPartial: (chatId, charCount) => {
      process.stderr.write(`telegram gateway: pty first partial — chat=${chatId} chars=${charCount}\n`)
    },
    writeError: (line) => process.stderr.write(line),
  })
  pendingPtyPartial = state.pendingPtyPartial?.text ?? null
}

function handlePtyActivity(text: string): void {
  // #1067: snapshot at entry. handleStreamReply is async and runs in
  // the background via void; the closure already captures `chatId` /
  // `threadId` locals, so the supersession is correctly scoped.
  const turn = currentTurn
  if (turn == null) return
  if (shouldSuppressToolActivity(text)) return
  const chatId = turn.sessionChatId
  const threadId = turn.sessionThreadId
  const access = loadAccess()
  void handleStreamReply(
    {
      chat_id: chatId,
      text,
      done: false,
      message_thread_id: threadId != null ? String(threadId) : undefined,
      format: 'text',
      lane: 'activity',
    },
    { activeDraftStreams },
    {
      // See StreamBotApi cast comment above (line ~2522 area).
      bot: bot as never,
      retry: robustApiCall,
      repairEscapedWhitespace,
      assertAllowedChat,
      resolveThreadId,
      disableLinkPreview: access.disableLinkPreview !== false,
      defaultFormat: 'text',
      logStreamingEvent,
      historyEnabled: false,
      recordOutbound,
      writeError: (line) => process.stderr.write(line),
      // PR B note: this is the PTY-activity stream, NOT the LLM
      // stream_reply path. PTY drives many tiny partials as a TUI
      // re-renders; 600 ms is a deliberate compromise tuned for the
      // PTY flicker characteristics, not LLM token cadence. The
      // transport-aware defaults (300/1000) deliberately do NOT
      // apply here. If you change this, also check
      // telegram-plugin/pty-partial-handler.ts:159 which has the
      // same value for the same reason.
      throttleMs: 600,
    },
  ).catch((err) => {
    process.stderr.write(`telegram gateway: pty activity stream failed: ${(err as Error).message}\n`)
  })
}

// ─── Gate / inbound routing ───────────────────────────────────────────────

/**
 * Reasons the gate may drop an inbound. Surfaced through the rate-limited
 * `logGateDeny` so operators can debug allowlist / pairing misconfigs
 * without crawling the telegram-plugin source. Found while tracking down
 * a fuzz failure on 2026-05-13 where 23 inbounds were silently dropped —
 * a single line in the gateway log would have replaced ~30 min of
 * investigation.
 */
type GateDropReason =
  | 'dm_policy_disabled'
  | 'no_sender'
  | 'allowlist_no_match'
  | 'pairing_resend_exhausted'
  | 'pairing_capacity'
  | 'group_unknown'
  | 'group_allowFrom_no_match'
  | 'group_mention_required'
  | 'unknown_chat_type'

type GateResult =
  | { action: 'deliver'; access: Access }
  | { action: 'drop'; reason: GateDropReason }
  | { action: 'pair'; code: string; isResend: boolean }

/**
 * Per-(chat_id, senderId, reason) suppression so a chatty unauthorized
 * sender doesn't flood the gateway log. First hit always logs; repeats
 * within {@link GATE_DENY_LOG_WINDOW_MS} are silently swallowed.
 */
const gateDenyLastLoggedAt = new Map<string, number>()
const GATE_DENY_LOG_WINDOW_MS = 60_000

function logGateDeny(ctx: Context, reason: GateDropReason): void {
  // Defence in depth: never throw from the log helper. A misshapen ctx
  // (e.g. partial test fixture) would otherwise sink the inbound path.
  try {
    // `group_mention_required` is routine traffic in any active group
    // chat — every non-mentioning message from an allowlisted member
    // hits this reason. With per-(chat,sender) rate-limiting that's
    // still up to N log lines per minute per active group, which is
    // noise rather than signal: `requireMention=true` is doing exactly
    // what it's configured to do. Gate behind a debug env var so
    // operators can opt into it when they're explicitly debugging a
    // group-mention configuration. The other 8 reasons are all
    // genuine misconfig / unauthorized signals and stay loud.
    if (reason === 'group_mention_required' && process.env.SWITCHROOM_GATEWAY_DEBUG_DENY !== '1') {
      return
    }
    const chatId = ctx.chat?.id != null ? String(ctx.chat.id) : '?'
    const senderId = ctx.from?.id != null ? String(ctx.from.id) : '?'
    const chatType = ctx.chat?.type ?? '?'
    const key = `${chatId}:${senderId}:${reason}`
    const now = Date.now()
    const prev = gateDenyLastLoggedAt.get(key)
    if (prev != null && now - prev < GATE_DENY_LOG_WINDOW_MS) return
    gateDenyLastLoggedAt.set(key, now)
    process.stderr.write(
      `telegram gateway: inbound dropped reason=${reason} chat_id=${chatId} ` +
      `chat_type=${chatType} sender_id=${senderId}\n`,
    )
  } catch { /* swallow — best-effort log */ }
}

/**
 * Wrap `decideDmCommandGate` (pure helper in
 * `../dm-command-gate.ts`) with grammy ctx + access.json side effects.
 * Returns null (silent drop) on every reject path. See
 * dm-command-gate.ts for the upstream backport (#894) rationale.
 */
function dmCommandGate(ctx: Context): { access: Access; senderId: string } | null {
  const access = loadAccess()
  const pruned = pruneExpired(access)
  if (pruned) saveAccess(access)
  const decision = decideDmCommandGate({
    chatType: ctx.chat?.type,
    senderId: ctx.from?.id != null ? String(ctx.from.id) : undefined,
    dmPolicy: access.dmPolicy,
    allowFrom: access.allowFrom,
  })
  if (!decision.allow) return null
  return { access, senderId: decision.senderId }
}

function gate(ctx: Context): GateResult {
  const access = loadAccess()
  const pruned = pruneExpired(access)
  if (pruned) saveAccess(access)
  if (access.dmPolicy === 'disabled') return { action: 'drop', reason: 'dm_policy_disabled' }
  const from = ctx.from
  if (!from) return { action: 'drop', reason: 'no_sender' }
  const senderId = String(from.id)
  const chatType = ctx.chat?.type

  if (chatType === 'private') {
    if (access.allowFrom.includes(senderId)) return { action: 'deliver', access }
    if (access.dmPolicy === 'allowlist') return { action: 'drop', reason: 'allowlist_no_match' }

    for (const [code, p] of Object.entries(access.pending)) {
      if (p.senderId === senderId) {
        if ((p.replies ?? 1) >= 2) return { action: 'drop', reason: 'pairing_resend_exhausted' }
        p.replies = (p.replies ?? 1) + 1
        saveAccess(access)
        return { action: 'pair', code, isResend: true }
      }
    }
    if (Object.keys(access.pending).length >= 3) return { action: 'drop', reason: 'pairing_capacity' }
    const code = randomBytes(3).toString('hex')
    const now = Date.now()
    access.pending[code] = {
      senderId,
      chatId: String(ctx.chat!.id),
      createdAt: now,
      expiresAt: now + 60 * 60 * 1000,
      replies: 1,
    }
    saveAccess(access)
    return { action: 'pair', code, isResend: false }
  }

  if (chatType === 'group' || chatType === 'supergroup') {
    const groupId = String(ctx.chat!.id)
    const policy = access.groups[groupId]
    if (!policy) return { action: 'drop', reason: 'group_unknown' }
    const groupAllowFrom = policy.allowFrom ?? []
    const requireMention = policy.requireMention ?? true
    if (groupAllowFrom.length > 0 && !groupAllowFrom.includes(senderId)) {
      return { action: 'drop', reason: 'group_allowFrom_no_match' }
    }
    if (requireMention && !isMentioned(ctx, access.mentionPatterns)) {
      return { action: 'drop', reason: 'group_mention_required' }
    }
    return { action: 'deliver', access }
  }

  return { action: 'drop', reason: 'unknown_chat_type' }
}

function isMentioned(ctx: Context, extraPatterns?: string[]): boolean {
  const entities = ctx.message?.entities ?? ctx.message?.caption_entities ?? []
  const text = ctx.message?.text ?? ctx.message?.caption ?? ''
  for (const e of entities) {
    if (e.type === 'mention') {
      const mentioned = text.slice(e.offset, e.offset + e.length)
      if (mentioned.toLowerCase() === `@${botUsername}`.toLowerCase()) return true
    }
    if (e.type === 'text_mention' && e.user?.is_bot && e.user.username === botUsername) return true
  }
  if (ctx.message?.reply_to_message?.from?.username === botUsername) return true
  for (const pat of extraPatterns ?? []) {
    try { if (new RegExp(pat, 'i').test(text)) return true } catch {}
  }
  return false
}

function isAuthorizedSender(ctx: Context): boolean {
  const from = ctx.from
  if (!from) return false
  const senderId = String(from.id)
  const access = loadAccess()
  if (ctx.chat?.type === 'private') return access.allowFrom.includes(senderId)
  if (ctx.chat?.type === 'group' || ctx.chat?.type === 'supergroup') {
    const groupId = String(ctx.chat.id)
    const policy = access.groups[groupId]
    if (!policy) return false
    const groupAllowFrom = policy.allowFrom ?? []
    if (groupAllowFrom.length > 0 && !groupAllowFrom.includes(senderId)) return false
    return true
  }
  return false
}

function safeName(s: string | undefined): string | undefined {
  return s?.replace(/[<>\[\]\r\n;]/g, '_')
}

// ─── Inbound message handling ─────────────────────────────────────────────

async function handleInboundCoalesced(
  ctx: Context,
  text: string,
  downloadImage: (() => Promise<string | undefined>) | undefined,
  attachment?: AttachmentMeta,
): Promise<void> {
  // `!`-prefix interrupt (#575) bypasses coalescing. If we let an
  // interrupt sit in the coalesce window, an earlier non-`!` message
  // arriving in the same window would prepend itself and the marker
  // would no longer be at position 0 — handleInbound's parser would
  // miss it and the user's interrupt would silently get merged into a
  // normal turn. Bypass to handleInbound directly so the marker
  // stays at the start of the text. Checked first so a `!`-prefixed
  // media caption still interrupts.
  if (parseInterruptMarker(text).isInterrupt) {
    return handleInbound(ctx, text, downloadImage, attachment)
  }

  const hasAttachment = downloadImage != null || attachment != null
  const maxAttachments = coalesceMaxAttachments()

  // Albums (media_group_id): coalesce only when the cap allows >1 attachment
  // (A2). At the default cap of 10 the parts share the coalesce key and fold
  // into one multi-attachment turn (the cap-overflow bypass below catches
  // parts past the cap). With the cap lowered to 1 each album part keeps its
  // own turn — the single-attachment merge can't carry sibling photos, so
  // bypassing avoids dropping them.
  if (hasAttachment && ctx.message?.media_group_id != null && maxAttachments <= 1) {
    return handleInbound(ctx, text, downloadImage, attachment)
  }

  const from = ctx.from
  if (!from) return

  // An attachment past the per-agent cap would be dropped by the capped merge.
  // Bypass it to its own turn so no media is silently lost. At the default
  // cap of 10 this fires on the 11th attachment; with the cap lowered to 1 it
  // fires on the SECOND, preserving A1 behaviour.
  if (hasAttachment) {
    const probeKey = inboundCoalesceKey(
      String(ctx.chat!.id),
      ctx.message?.message_thread_id,
      String(from.id),
    )
    if ((bufferedAttachmentKeys.get(probeKey) ?? 0) >= maxAttachments) {
      return handleInbound(ctx, text, downloadImage, attachment)
    }
  }

  // F2 fix (#553): fire 👀 reaction on RAW arrival, before the coalesce
  // wait blocks first paint. Pre-fix, the controller's setQueued() inside
  // handleInbound only ran AFTER the coalesce flush (default gapMs=1500),
  // so the user perceived ~1.5s of silence after their message landed.
  // The spec deadline is 800ms.
  //
  // The controller's later setQueued() in handleInbound still runs on
  // flush; Telegram dedupes setMessageReaction calls with the same
  // emoji, so the visible state is unchanged. The duplicate emit is
  // one extra API call per coalesced burst — trivial cost vs. the UX win.
  //
  // Eligibility:
  //   - PRIVATE chat only (group flow uses requireMention/allowFrom
  //     checks that need the full gate; pre-acking those risks reacting
  //     to messages we'd later drop).
  //   - Sender already in access.allowFrom (paired) — unpaired senders
  //     get the pairing-required reply via the full gate path.
  //   - No active turn for this (chat, thread) — mid-turn messages
  //     would otherwise flash 👀 over the current 🔥/🤔 state.
  //   - msgId present (always true for `bot.on('message:*')` paths but
  //     defensive against future routers that might call this without one).
  maybeEarlyAckReaction(ctx, from)
  // #2527 — if this lands mid-turn, the user is asking "what's happening?";
  // fire the liveness floor immediately (DM + supergroup alike).
  maybePokeFloorForMidTurnInbound(ctx, from)

  const key = inboundCoalesceKey(
    String(ctx.chat!.id),
    ctx.message?.message_thread_id,
    String(from.id),
  )
  const result = inboundCoalescer.enqueue(key, { text, ctx, downloadImage, attachment })
  // Coalescing disabled (window <= 0): flush immediately, preserving any
  // media this message carried.
  if (result.bypass) return handleInbound(ctx, text, downloadImage, attachment)
  // Count the open window's attachments so any part past the cap (the 11th
  // at the default cap of 10, or the second when lowered to 1) bypasses
  // rather than overflows the capped merge (cleared in onFlush).
  if (hasAttachment) bufferedAttachmentKeys.set(key, (bufferedAttachmentKeys.get(key) ?? 0) + 1)
}

/**
 * Fire the 👀 status reaction immediately for paired DM users sending
 * a fresh-turn message. Returns silently for ineligible cases — the
 * caller proceeds either way; this is a UX optimisation, not a gate.
 *
 * Fire-and-forget: failures are swallowed since the controller's
 * setQueued() will retry the same emoji after the coalesce flush.
 */
function maybeEarlyAckReaction(ctx: Context, from: NonNullable<Context['from']>): void {
  const msgId = ctx.message?.message_id
  if (msgId == null) return
  const chatType = ctx.chat?.type
  // Intentionally DM-only (#2527 surface-parity note): pre-acking a GROUP
  // message risks reacting to one the full gate (requireMention / topic
  // scoping) would later DROP. The SUBSTANTIVE liveness parity a supergroup
  // needs — the mid-turn floor and the role-aware terminal reaction — is
  // surface-agnostic (keyed on statusKey + loop role, no chat-type branch),
  // so a forum topic gets identical never-silent guarantees without this
  // sub-second 👀 optimisation. See `maybePokeFloorForMidTurnInbound` for
  // the surface-agnostic "Status?" short-circuit.
  if (chatType !== 'private') return
  const chatId = String(ctx.chat!.id)
  const threadId = ctx.message?.is_topic_message ? ctx.message.message_thread_id : undefined
  if (activeTurnStartedAt.has(statusKey(chatId, threadId))) return
  const access = loadAccess()
  if (!access.allowFrom.includes(String(from.id))) return
  void bot.api.setMessageReaction(chatId, msgId, [
    { type: 'emoji', emoji: '👀' as ReactionTypeEmoji['emoji'] },
  ]).catch(() => {})
  // #2527: log the early-ack fire so operators can see how often the
  // fast pre-coalesce DM path triggers vs. the controller path.
  logStreamingEvent({ kind: 'early_ack_reaction', chatId, messageId: msgId, emoji: '👀' })
  // #553 PR 3: also fire the native "typing…" indicator. Bridges the
  // visual gap between the early-ack 👀 reaction and the first real
  // model text. No fake content — Telegram clients render this natively
  // and it auto-expires after ~5s if not refreshed (the answer-lane
  // first edit will land long before then under the new defaults).
  void bot.api.sendChatAction(chatId, 'typing').catch(() => {})
}

/**
 * #2527 — "Status?" short-circuit. A message arriving DURING an active turn
 * (the user explicitly asking what's happening) fires the mid-turn liveness
 * floor immediately, bypassing the timer/working gates. Surface-agnostic:
 * works identically in a DM and a forum-supergroup topic (keyed on statusKey).
 * Idempotent per turn (the floor's fire-once latch) and kill-switch-gated.
 */
function maybePokeFloorForMidTurnInbound(ctx: Context, from: NonNullable<Context['from']>): void {
  const rawChatId = ctx.chat?.id
  if (rawChatId == null) return
  const chatId = String(rawChatId)
  const threadId = ctx.message?.is_topic_message ? ctx.message.message_thread_id : undefined
  const key = statusKey(chatId, threadId)
  // Only mid-turn: a turn must already be in flight for this (chat, thread).
  if (!activeTurnStartedAt.has(key)) return
  const access = loadAccess()
  if (!access.allowFrom.includes(String(from.id))) return
  silencePoke.pokeFloorNow(key, Date.now())
}

async function handleInbound(
  ctx: Context,
  text: string,
  downloadImage: (() => Promise<string | undefined>) | undefined,
  attachment?: AttachmentMeta,
  // A2: 2nd..Nth attachments folded into this coalesced turn. Each is
  // resolved (photos downloaded) and surfaced as numbered meta fields
  // (image_path_2, attachment_file_id_2, …) alongside the primary.
  extraAttachments?: CoalesceAttachment[],
): Promise<void> {
  markIdleActivity() // any inbound resets the idle auto-clear timer + re-arms
  const isTopicMessage = ctx.message?.is_topic_message ?? false
  const messageThreadId = ctx.message?.message_thread_id

  if (TOPIC_ID != null) {
    if (!isTopicMessage || messageThreadId !== TOPIC_ID) return
  }

  const result = gate(ctx)
  if (result.action === 'drop') {
    logGateDeny(ctx, result.reason)
    return
  }
  if (result.action === 'pair') {
    const lead = result.isResend ? 'Still pending' : 'Pairing required'
    await ctx.reply(`${lead} — run in Claude Code:\n\n/telegram:access pair ${result.code}`)
    return
  }

  // A real message from an allowed sender (gate passed) ⇒ the operator is
  // present, so reset any no-repeat suppression: the next time the agent asks
  // for something that timed out earlier, they should see a fresh card.
  clearPermissionTimeoutSuppression('operator inbound')

  // Capture wall-clock receive time for inbound_ack metric (#203).
  // Must be after gate() so early-exit paths (drop/pair) don't skew the delta.
  //
  // Measurement caveat: the `setMessageReaction` API call that posts the 👀
  // is `void`-dispatched (fire-and-forget) before the metric is logged, so
  // `ackDelayMs` measures gateway-receive → reaction-DISPATCH not
  // gateway-receive → reaction-ACKNOWLEDGED-by-Telegram. The optimistic
  // bias is one network RTT (~50–200ms typically). Acceptable for
  // ambient-signal alerting (the dominant variance is reasoning time, not
  // network RTT) but not a user-perceived end-to-end measurement.
  const inboundReceivedAt = Date.now()

  // Phase 2b shadow: inbound arrival. Emit BEFORE the snapshot/gate
  // logic so the machine sees the event at the same point in time the
  // imperative code would. The machine internally handles fresh-turn
  // vs mid-turn — its decision will be visible in the gw-trace shadow
  // line emitted to stderr.
  const _shadowKey = statusKey(ctx.chat?.id != null ? String(ctx.chat.id) : '0', ctx.message?.message_thread_id) as _ChatKey
  // PR3b-cutover: snapshot the machine's in-turn state BEFORE the
  // inbound event advances it. A fresh-turn inbound transitions the
  // machine idle→in_turn; reading after the emit would see THIS
  // message's own just-started turn and self-block it (the same
  // self-block hazard the claudeBusyKeys snapshot below guards). When
  // the kill-switch is off this is null and the gate uses the legacy
  // claudeBusyKeys read.
  const machineInTurnAtReceipt = isDeliveryCutoverEnabled() ? isMachineInTurn() : null
  shadowEmit({
    kind: 'inbound',
    key: _shadowKey,
    msg: {
      msgId: ctx.message?.message_id ?? 0,
      isSteering: false, // refined in PR 3 — for now shadow conservatively classifies as non-steering
      payload: null,
    },
    at: Date.now(),
  })

  // #1556 self-blocking fix (v0.12.22): snapshot the live turn-state
  // BEFORE the fresh-turn branch (line ~7357) sets activeTurnStartedAt
  // for THIS inbound. The #1556 delivery gate further down asks "is a
  // turn ALREADY in flight" — but if we read activeTurnStartedAt.size
  // at the gate, we see the entry this handler just wrote, and buffer
  // the very message that just started the turn. Symptom: every first
  // post-restart message in each thread was held 5 minutes until the
  // silence-poke fallback drained the buffer; the "5-min blank after
  // restart" wedge documented in
  // feedback_5min_restart_wedge_violates_vision.md.
  //
  // Why ONLY first-after-restart, not every steady-state message: the
  // fresh-turn branch fires only when `priorActive = activeStatusReactions.get(key)`
  // returns null (no controller currently running for this chat+thread).
  // In a live conversation, the controller from the previous turn
  // typically hasn't been cleared yet when the user's follow-up
  // arrives (or follow-ups arrive mid-turn, taking the queued path) —
  // so the else branch at ~7313 is skipped and the .set never fires.
  // A fresh container after restart has EMPTY `activeStatusReactions`,
  // so the very first message in each thread is guaranteed to enter
  // the fresh-turn branch and trigger the self-block.
  //
  // Why snapshot, not move-the-set(): the .set() at ~7357 is embedded
  // in a coupled init bundle (controller, msgIds, signalTracker.reset,
  // silencePoke.startTurn, the 👀 reaction emit). Moving only the .set
  // splits the bundle in ways future maintainers will drift; moving
  // the WHOLE bundle past the gate changes user-visible ack timing
  // (👀 wouldn't land until after the gate decides to deliver, hiding
  // an ack on the buffered path). The snapshot is the minimal precise
  // fix. Phase 2b's state-machine extraction will revisit this
  // structurally.
  // PR3b: gated on claudeBusyKeys (turns claude has been handed) not
  // activeTurnStartedAt (eager set on receipt). In supergroup mode,
  // topic A active + topic B inbound arriving: pre-fix, B saw
  // turnInFlightAtReceipt=true because A's key was in
  // activeTurnStartedAt, AND B's fresh-turn branch then eagerly set
  // its OWN key — wedging the gate forever (claude is idle on B but
  // no turn_end ever fires). With claudeBusyKeys, B sees true (A is
  // busy) → B is buffered correctly, AND the gate cleanly reopens
  // when A's turn_end deletes keyA → flush triggers → B delivered.
  // PR3b-cutover: prefer the machine snapshot taken before the inbound
  // event advanced it (machineInTurnAtReceipt); null when the
  // kill-switch is off, in which case the legacy claudeBusyKeys read
  // stands. Both are "was a turn in flight at receipt", not a live
  // post-this-inbound read — see machineInTurnAtReceipt's comment.
  const turnInFlightAtReceipt = machineInTurnAtReceipt ?? (claudeBusyKeys.size > 0)

  const access = result.access
  const from = ctx.from!
  const chat_id = String(ctx.chat!.id)
  const msgId = ctx.message?.message_id

  if (messageThreadId != null) chatThreadMap.set(chat_id, messageThreadId)

  // #1122 KPI: classify "are you still working / status?" pings as the
  // primary lagging KPI of the conversational-turn-UX redesign. Every fire
  // means the design failed to make the user feel heard. Read-only —
  // never alters routing; the text still reaches the agent.
  try {
    const classification = classifyInbound(text)
    if (classification.isStatusQuery) {
      const priorKey = statusKey(chat_id, messageThreadId)
      const priorTurnStartedAt = activeTurnStartedAt.get(priorKey)
      const priorTurnInFlight = activeStatusReactions.get(priorKey) != null
      emitRuntimeMetric({
        kind: 'inbound_status_query',
        chat_id,
        message_id: msgId ?? null,
        thread_id: messageThreadId ?? null,
        text_length: text.length,
        prior_turn_in_flight: priorTurnInFlight,
        seconds_since_turn_start: priorTurnStartedAt != null
          ? Math.round((inboundReceivedAt - priorTurnStartedAt) / 1000)
          : null,
      })
    }
  } catch (err) {
    // Classifier is fire-and-forget — never break inbound on a metric error.
    process.stderr.write(`telegram gateway: inbound classifier error: ${(err as Error).message}\n`)
  }

  // `!`-prefix interrupt (#575). Closes
  // `reference/jobs/steer-or-queue-mid-flight.md`'s correction path.
  //
  // Behavior:
  //   1. SIGINT the agent service. This kills any in-flight turn —
  //      same primitive that powers `switchroom agent interrupt`.
  //      It's heavy, but the user explicitly asked for it; correctness
  //      beats elegance here.
  //   2. Strip the `!` and forward the body as a fresh turn so the
  //      agent sees clean intent. If the body is empty (just `!`),
  //      send a clarifying reply instead — forwarding empty text
  //      would just yield a tool-result-of-nothing.
  //   3. React with ⚡ on the `!` message so the user has a visible
  //      ack that the interrupt landed (separate from the 👀 the
  //      coalescer-bypass path skipped).
  //
  // Authorization: same allowFrom gate as any inbound message —
  // unauthorized senders never reach this code (gate() above).
  // Interrupt requires the same trust as sending a normal message.
  const interrupt = parseInterruptMarker(text)
  // Problem B: defer this `!`'s SIGINT to a safe boundary instead of firing it
  // synchronously below. Set only when the `interrupt.safe_boundary` flag is on
  // AND a top-level tool call is in flight AND the body is non-empty (an empty
  // `!` is an explicit halt-now and stays immediate). When set, we skip the
  // synchronous SIGINT here and stash the built inbound at the delivery site.
  let deferInterrupt = false
  if (interrupt.isInterrupt) {
    const agentName = process.env.SWITCHROOM_AGENT_NAME
    const access = loadAccess()
    deferInterrupt =
      !interrupt.emptyBody &&
      decideInterruptTiming({
        safeBoundaryEnabled: resolveSafeBoundaryEnabled(access.interruptSafeBoundary),
        midToolCall: toolFlightTracker.isMidToolCall(),
      }) === 'defer'
    process.stderr.write(
      `telegram gateway: interrupt-marker received chat_id=${chat_id} agent=${agentName ?? '-'} ` +
      `body_len=${interrupt.body.length} empty=${interrupt.emptyBody} defer=${deferInterrupt} ` +
      `in_flight=${toolFlightTracker.inFlightCount()}\n`,
    )
    if (msgId != null) {
      void bot.api.setMessageReaction(chat_id, msgId, [
        { type: 'emoji', emoji: '⚡' as ReactionTypeEmoji['emoji'] },
      ]).catch(() => {})
    }
    if (agentName && !deferInterrupt) {
      try {
        // The gateway runs INSIDE the agent container in docker mode,
        // so calling `interruptAgent` (which probes `docker inspect`
        // for the PID) always returns "no running PID" — the host's
        // docker socket isn't visible to us. Skip the PID round-trip
        // entirely and use tmux send-keys directly: the tmux socket
        // is local to our container. Discovered during UAT overnight
        // 2026-05-13 — pre-fix every `!` interrupt produced an
        // "Agent has no running PID" stderr line and the user got
        // ghosted because the SIGINT never fired.
        const { sendAgentInterrupt } = await import('../../src/agents/tmux.js')
        const r = sendAgentInterrupt({ agentName })
        if ('ok' in r) {
          process.stderr.write(
            `telegram gateway: interrupt-marker SIGINT delivered via tmux send-keys agent=${agentName}\n`,
          )
        } else {
          process.stderr.write(
            `telegram gateway: interrupt-marker SIGINT via tmux failed agent=${agentName}: ${r.error}\n`,
          )
        }
      } catch (err) {
        process.stderr.write(`telegram gateway: interrupt-marker SIGINT failed: ${(err as Error).message}\n`)
      }
      // The SIGINT just killed the in-flight turn — cancel its obligation so the
      // interrupted (user-redirected) question isn't re-presented/escalated later.
      cancelInterruptedObligation()
    }
    if (interrupt.emptyBody) {
      // #1075: thread-id-bearing — route through swallowingApiCall so
      // a deleted topic doesn't crash the gateway; the reaction
      // already acked the user so a missing follow-up is tolerable.
      await swallowingApiCall(
        () =>
          bot.api.sendMessage(
            chat_id,
            '⚡ Interrupted. Send your replacement instruction now.',
            messageThreadId != null ? { message_thread_id: messageThreadId } : {},
          ),
        {
          chat_id,
          verb: 'interrupt-empty-body',
          ...(messageThreadId != null ? { threadId: messageThreadId } : {}),
        },
      )
      return
    }
    // Replace the inbound text with the body and continue normal
    // processing. The agent receives a fresh turn with no `!` prefix.
    text = interrupt.body
  }

  // Issue #109: when the user has to ask "status?" mid-turn, the live progress
  // surface (status reactions + the edit-in-place `🛠 Worker` feed) may have
  // failed its job. Log the event with a snapshot of what is ACTUALLY in
  // flight so we can count + analyze frequency. We don't intercept the
  // message — it still flows through to the agent, since the agent may have a
  // useful answer the surfaces haven't communicated yet.
  //
  // Truthful telemetry (was a lying diagnostic): the pinned progress card was
  // retired in #1122/#1126 and `progressDriver` is now permanently null, so
  // the old `progressDriver.peek(...)` snapshot ALWAYS reported idle/zero
  // regardless of live work — actively misleading debugging. We now read the
  // LIVE surfaces instead: the running-background-worker DB count
  // (`countRunningWorkers`), the `🛠 Worker` activity-feed size, the
  // cross-turn pending-async-dispatch flag (`pending-work-progress.ts`), and
  // whether a turn is active (`activeTurnStartedAt`). A live background worker
  // ⇒ non-idle. A `ux-failure` is emitted ONLY when all of those are genuinely
  // zero AND no turn is active — i.e. the user asked "status?" and there really
  // was nothing in flight for the surfaces to have shown.
  //
  // Log shape (grep anchor: "status-query"):
  //   status-query agent=<n> chat_id=<n> thread=<n|none> stage=<stage>
  //                turn_age_s=<int> running_workers=<n> worker_feed=<n>
  //                pending_async=<0|1>
  // When idle, a second line carries the grep anchor "ux-failure: status-query".
  //
  // `turn_age_s` is always a non-negative integer; `-1` is the sentinel for
  // "no active turn" so structured-log parsers (Loki, Datadog, awk) can treat
  // the field as numeric without string-comparison branches.
  if (STATUS_QUERY_RE.test(text)) {
    try {
      const thread = messageThreadId != null ? String(messageThreadId) : 'none'
      const key = statusKey(chat_id, messageThreadId)
      const turnStartedAt = activeTurnStartedAt.get(key)
      const turnActive = turnStartedAt != null
      const surfaces: StatusQuerySurfaces = {
        turnActive,
        turnAgeS: turnActive
          ? Math.max(0, Math.floor((Date.now() - turnStartedAt) / 1000))
          : -1,
        runningWorkers: countRunningWorkers(),
        workerFeedSize: workerActivityFeed?.size ?? 0,
        pendingAsync: pendingProgress.hasPendingAsyncDispatch(key) ? 1 : 0,
      }
      const telemetry = deriveStatusQueryTelemetry(surfaces)
      const agentName = process.env.SWITCHROOM_AGENT_NAME ?? '-'
      process.stderr.write(
        formatStatusQueryLine(agentName, String(chat_id), thread, surfaces, telemetry),
      )
      if (telemetry.idle) {
        process.stderr.write(formatStatusQueryUxFailureLine(agentName, String(chat_id), thread))
      }
    } catch (err) {
      process.stderr.write(`telegram gateway: status-query telemetry failed: ${(err as Error).message}\n`)
    }
  }

  // Permission-reply intercept
  const permMatch = PERMISSION_REPLY_RE.exec(text)
  if (permMatch) {
    // Forward permission reply to connected bridge
    const behavior = permMatch[1]!.toLowerCase().startsWith('y') ? 'allow' : 'deny'
    const request_id = permMatch[2]!.toLowerCase()
    dispatchPermissionVerdict({
      type: 'permission',
      requestId: request_id,
      behavior,
    })
    resumeReactionAfterVerdict()
    const ftDetails = pendingPermissions.get(request_id)
    postPermissionResumeMessage({
      behavior,
      action: ftDetails ? naturalAction(ftDetails.tool_name, ftDetails.input_preview) : '',
    })
    if (msgId != null) {
      const emoji = behavior === 'allow' ? '✅' : '❌'
      void bot.api.setMessageReaction(chat_id, msgId, [
        { type: 'emoji', emoji: emoji as ReactionTypeEmoji['emoji'] },
      ]).catch(() => {})
    }
    return
  }

  // `/auth add` paste-back intercept — sibling to pendingReauthFlows.
  // Both intercepts are deliberate so the LLM never sees the OAuth
  // code (it doesn't need to + plaintext OAuth in chat history is bad
  // hygiene). The add-flow intercept comes first because /auth add
  // creates fresh credentials at the broker layer, vs /reauth which
  // mutates an existing agent's slot — different success paths.
  //
  // PR3 supergroup-mode: keyed by chatKey(chat, thread) so an OAuth
  // code pasted into topic A isn't intercepted when topic B has a
  // separate /auth add flow pending (security: prevents cross-topic
  // credential mis-attribution).
  const interceptKey = chatKey(chat_id, messageThreadId) as string
  const pendingAdd = pendingAuthAddFlows.get(interceptKey)
  if (pendingAdd && looksLikeAuthCode(text)) {
    const elapsed = Date.now() - pendingAdd.startedAt
    if (elapsed < REAUTH_INTERCEPT_TTL_MS) {
      pendingAuthAddFlows.delete(interceptKey)
      try {
        const credentials = await submitAccountAuthCode(pendingAdd, text.trim())
        try {
          await addAccountViaBroker(pendingAdd.label, credentials, { replace: false })
          // success — wipe scratch dir now that the broker owns the creds
          cleanAuthAddScratchDir(pendingAdd.scratchDir)
          await switchroomReply(
            ctx,
            `✓ Account \`${pendingAdd.label}\` added.\n` +
              `The fleet's active account hasn't changed. Send ` +
              `\`/auth use ${escapeHtmlForTg(pendingAdd.label)}\` to switch to it.`,
            { html: true },
          )
        } catch (brokerErr) {
          // Broker rejected (e.g. label already exists). Wipe scratch
          // either way — the credentials are useless without broker
          // bookkeeping.
          cleanAuthAddScratchDir(pendingAdd.scratchDir)
          await switchroomReply(
            ctx,
            `**/auth add failed at broker:** ${escapeHtmlForTg((brokerErr as Error)?.message ?? String(brokerErr))}`,
            { html: true },
          )
        }
      } catch (err) {
        // submitAccountAuthCode wiped the scratch dir on its own
        // failure paths (timeout, child exit, stdin broken).
        await switchroomReply(
          ctx,
          `**/auth add code failed:** ${escapeHtmlForTg((err as Error)?.message ?? String(err))}`,
          { html: true },
        )
      }
      // Redact the OAuth code paste from chat history (#488).
      redactAuthCodeMessage(bot.api as never, chat_id, msgId ?? null, line => process.stderr.write(line))
      return
    }
    // Stale — drop the pending entry but let the message fall through
    // to other intercepts (defensively wipe scratch).
    cancelAccountAuthSession(pendingAdd)
    pendingAuthAddFlows.delete(interceptKey)
  }

  // Auth-code intercept
  const pendingReauth = pendingReauthFlows.get(interceptKey)
  if (pendingReauth && looksLikeAuthCode(text)) {
    const elapsed = Date.now() - pendingReauth.startedAt
    if (elapsed < REAUTH_INTERCEPT_TTL_MS) {
      pendingReauthFlows.delete(interceptKey)
      const { result, errorText } = execAuthCode(pendingReauth.agent, text.trim())
      if (errorText) {
        await switchroomReply(ctx, `**auth code failed:**\n${preBlock(formatSwitchroomOutput(errorText))}`, { html: true })
      } else if (result) {
        const outcomeMsg = renderAuthCodeOutcome(result.outcome)
        if (outcomeMsg) {
          await switchroomReply(ctx, outcomeMsg, { html: true })
        } else {
          // success or no structured outcome — fall back to formatted text
          const output = result.instructions.join('\n')
          const formatted = formatAuthOutputForTelegram(output)
          await switchroomReply(ctx, formatted.text, { html: true })
        }
      }
      // Redact the OAuth code paste from chat history (#488).
      // Single-use code so a third party can't replay it after exchange,
      // but plaintext OAuth tokens in chat history are still poor
      // hygiene. The helper handles delete + 🔑 reaction silently.
      redactAuthCodeMessage(bot.api as never, chat_id, msgId ?? null, line => process.stderr.write(line))
      return
    }
    pendingReauthFlows.delete(interceptKey)
  }

  // Vault intercept
  const pendingVault = pendingVaultOps.get(chat_id)
  if (pendingVault) {
    const elapsed = Date.now() - pendingVault.startedAt
    if (elapsed > VAULT_INPUT_TTL_MS) {
      pendingVaultOps.delete(chat_id)
    } else {
      pendingVaultOps.delete(chat_id)
      if (pendingVault.kind === 'passphrase') {
        const passphrase = text.trim()
        if (!passphrase) {
          await switchroomReply(ctx, 'Passphrase cannot be empty. Try /vault again.', { html: true })
          return
        }
        vaultPassphraseCache.set(chat_id, { passphrase, expiresAt: Date.now() + VAULT_PASSPHRASE_TTL_MS })
        if (msgId != null) await deleteSensitiveMessage(chat_id, msgId, 'vault passphrase')
        await executeVaultOp(ctx, chat_id, pendingVault.op, pendingVault.key, passphrase, undefined)
      } else if (pendingVault.kind === 'unlock') {
        // Issue #158: passphrase for /vault unlock — sent directly to the
        // broker unlock socket, never cached or logged.
        const passphrase = text.trim()
        if (!passphrase) {
          await switchroomReply(ctx, 'Passphrase cannot be empty. Try /vault unlock again.', { html: true })
          return
        }
        if (msgId != null) await deleteSensitiveMessage(chat_id, msgId, 'vault unlock passphrase')
        const result = await unlockViaBroker(passphrase)
        if (result.ok) {
          await switchroomReply(ctx, '🔓 Vault broker unlocked.', { html: true })
        } else {
          await switchroomReply(ctx, `**vault unlock failed:** ${escapeHtmlForTg(result.msg ?? 'unknown error')}`, { html: true })
        }
      } else if (pendingVault.kind === 'passphrase-for-deferred') {
        // Issue #44: passphrase entered after tapping "🔓 Unlock vault &
        // save" on the deferred-secret card. Cache the passphrase then
        // auto-write the held secret directly — no re-paste required.
        // The passphrase message itself is deleted so it doesn't linger
        // in chat history (same protection as the original secret got).
        const passphrase = text.trim()
        if (!passphrase) {
          await switchroomReply(ctx, 'Passphrase cannot be empty. Tap the unlock button again.', { html: true })
          return
        }
        vaultPassphraseCache.set(chat_id, { passphrase, expiresAt: Date.now() + VAULT_PASSPHRASE_TTL_MS })
        if (msgId != null) await deleteSensitiveMessage(chat_id, msgId, 'vault passphrase')
        await executeDeferredSecretSave(ctx, pendingVault.deferKey, passphrase, pendingVault.cardMessageId)
      } else if (pendingVault.kind === 'passphrase-for-access-approve') {
        // #1012 Phase 2 follow-up + #1051: operator tapped Approve on
        // one or more vault_request_access cards without first
        // unlocking. We captured the next message as the passphrase,
        // cache it, delete the chat copy, and resume the approve
        // flow for EVERY queued stage (#1051 — without the queue, a
        // concurrent second tap orphaned the first stage). Wrong
        // passphrase surfaces via the broker's
        // DENIED:passphrase-mismatch path and edits each card to the
        // mint_grant-failed message (see performVaultAccessApproval).
        const passphrase = text.trim()
        if (!passphrase) {
          await switchroomReply(ctx, 'Passphrase cannot be empty. Ask the agent to re-issue the request card.', { html: true })
          return
        }
        vaultPassphraseCache.set(chat_id, { passphrase, expiresAt: Date.now() + VAULT_PASSPHRASE_TTL_MS })
        if (msgId != null) await deleteSensitiveMessage(chat_id, msgId, 'vault passphrase')
        // Drain the queued items SEQUENTIALLY. The grant-union step
        // inside performVaultAccessApproval lists existing grants
        // before minting; sequential processing means the union
        // grows monotonically (item 1 mints grant for [keyA]; item 2
        // lists, finds [keyA], unions with keyB → mints [keyA, keyB]).
        // Parallel processing would race on the list-and-merge.
        for (const item of pendingVault.items) {
          const stagedAccess = pendingVaultRequestAccesses.get(item.stageId)
          if (!stagedAccess) {
            // Stage expired or denied between tap and passphrase reply.
            // Edit its card to a clean explanation; don't break the
            // loop (sibling cards may still be valid).
            await ctx.api
              .editMessageText(
                item.cardChatId,
                item.cardMessageId,
                richMessage(`⌛ _Vault unlocked, but this access-request card expired or was denied before you replied. Ask the agent to re-issue if still needed._`),
                { reply_markup: { inline_keyboard: [] } },
              )
              .catch(() => {})
            continue
          }
          await performVaultAccessApproval(ctx, stagedAccess, item.stageId, item.senderId, { kind: 'passphrase', passphrase })
        }
      } else if (pendingVault.kind === 'grant-wizard' && pendingVault.awaitingCustomDuration) {
        // Issue #227: custom duration text reply for grant wizard
        const input = text.trim()
        const ttlSeconds = parseGrantDuration(input)
        if (ttlSeconds === null) {
          // Re-set state so user can try again
          pendingVaultOps.set(chat_id, { ...pendingVault, startedAt: Date.now() })
          await switchroomReply(ctx, '⚠️ Invalid duration. Use \`Nd\` (days) or \`Nh\` (hours), e.g. \`30d\` or \`12h\`.', { html: true })
          return
        }
        const newState = { ...pendingVault, ttlSeconds, awaitingCustomDuration: false }
        await grantWizardConfirm(ctx, chat_id, newState)
      } else if (pendingVault.kind === 'grant-wizard') {
        // Text received mid-wizard but not awaiting custom duration — ignore and re-set
        pendingVaultOps.set(chat_id, { ...pendingVault, startedAt: Date.now() })
      } else if (pendingVault.kind === 'value') {
        let value = text
        const codeBlockMatch = /^```[\w]*\n?([\s\S]*?)```$/m.exec(text)
        if (codeBlockMatch) value = codeBlockMatch[1]!
        if (msgId != null) await deleteSensitiveMessage(chat_id, msgId, 'vault secret value')
        await executeVaultOp(ctx, chat_id, 'set', pendingVault.key, pendingVault.passphrase, value.trim())
      } else if (pendingVault.kind === 'rename-vault-save') {
        // Issue #969 P1a: user tapped Rename on a vault_request_save
        // card and is now telling us the new key name. Validate the
        // slug, update the staged entry, refresh the card.
        const newKey = text.trim()
        const staged = pendingVaultRequestSaves.get(pendingVault.stageId)
        if (!staged) {
          await switchroomReply(ctx, '⌛ That save card expired before you renamed. Ask the agent to re-issue.', { html: true })
          return
        }
        if (!VAULT_KEY_REGEX.test(newKey)) {
          // Re-arm the pending state so the user can try again.
          pendingVaultOps.set(chat_id, { ...pendingVault, startedAt: Date.now() })
          await switchroomReply(ctx, `⚠️ Key must match \`${VAULT_KEY_REGEX_LABEL}\`. Send a different name.`, { html: true })
          return
        }
        staged.key = newKey
        if (msgId != null) await deleteSensitiveMessage(chat_id, msgId, 'vault rename input')
        // Edit the card in place with the new suggested key + same buttons.
        if (staged.card_message_id != null) {
          await ctx.api
            .editMessageText(
              staged.chat_id,
              staged.card_message_id,
              richMessage(renderVaultRequestSaveCard(staged, staged.agent)),
              { reply_markup: buildVaultRequestSaveKeyboard(pendingVault.stageId) },
            )
            .catch(() => {})
        }
      }
      return
    }
  }

  // --- Secret-detect follow-up command intercept ---
  // `stash NAME` / `ignore` / `rename X` / `forget` on a pending ambiguous
  // detection. The user is replying to our "looks like a high-entropy
  // string — reply `stash NAME` or `ignore`" prompt. We look up the most
  // recent staged detection for this chat and act on it.
  const stagedMatch = /^\s*(stash|ignore|rename|forget)\b\s*(\S+)?/i.exec(text)
  if (stagedMatch) {
    const staged = secretStaging.latestForChat(chat_id)
    if (staged != null) {
      const verb = stagedMatch[1]!.toLowerCase()
      const arg = stagedMatch[2]?.trim()
      if (verb === 'ignore' || verb === 'forget') {
        secretStaging.delete(staged.chat_id, staged.message_id)
        await switchroomReply(ctx, 'ok — ignored. nothing stored.', { html: true })
        // #1075: operates on a message in a (possibly-deleted) thread.
        if (msgId != null) {
          void swallowingApiCall(
            () => bot.api.deleteMessage(chat_id, msgId),
            { chat_id, verb: 'staged-secret.delete-ignored' },
          )
        }
        return
      }
      if (verb === 'stash' || verb === 'rename') {
        const cached = vaultPassphraseCache.get(chat_id)
        if (!cached || cached.expiresAt <= Date.now()) {
          await switchroomReply(ctx, 'No vault passphrase cached. Run \`/vault list\` first (or any /vault command) to unlock, then re-send \`stash NAME\`.', { html: true })
          return
        }
        const slugBase = arg && arg.length > 0 ? arg : staged.detection.suggested_slug
        const listed = defaultVaultList(cached.passphrase)
        const existing = new Set(listed.ok ? listed.keys : [])
        let slug = slugBase
        let n = 2
        while (existing.has(slug)) slug = `${slugBase}_${n++}`
        const write = defaultVaultWrite(slug, staged.detection.matched_text, cached.passphrase)
        if (!write.ok) {
          // Route P0a markers (#969) through the structured renderer so
          // a "new key, needs operator approval" failure surfaces a
          // host-CLI hint instead of a raw stderr blob.
          const parsed = parseVaultCliError(write.output)
          const rendered = renderVaultCliError(parsed, { verb: 'save', key: slug })
          const body = rendered.suppressRaw
            ? rendered.html
            : `**vault write failed:**\n${preBlock(write.output)}`
          await switchroomReply(ctx, body, { html: true })
          return
        }
        secretStaging.delete(staged.chat_id, staged.message_id)
        if (msgId != null) await deleteSensitiveMessage(chat_id, msgId, 'stash command')
        await deleteSensitiveMessage(chat_id, staged.message_id, 'detected secret')
        await switchroomReply(ctx, `✅ stored as \`vault:${slug}\` (masked: \`${maskToken(staged.detection.matched_text)}\`)`, { html: true })
        return
      }
    }
    // No staged entry to act on — fall through to normal handling.
  }

  // Typing indicator in the ORIGINATING topic — on a supergroup-topic inbound,
  // an un-threaded sendChatAction shows "typing" in General, not the topic the
  // user is in. messageThreadId is the inbound's thread (undefined in a DM).
  void bot.api.sendChatAction(
    chat_id,
    'typing',
    messageThreadId != null ? { message_thread_id: messageThreadId } : {},
  ).catch(() => {})

  // Parse explicit prefixes first. `/steer ` / `/s ` opts IN to steering;
  // `/queue ` / `/q ` are legacy aliases that opt in to the new default (queued).
  const parsedSteer = parseSteerPrefix(text)
  const isSteerPrefix = parsedSteer.steering
  const parsedQueue = isSteerPrefix ? { queued: false, body: parsedSteer.body } : parseQueuePrefix(text)
  const isQueuedPrefix = parsedQueue.queued
  let effectiveText = isSteerPrefix ? parsedSteer.body : (isQueuedPrefix ? parsedQueue.body : text)

  // --- #2045 provided-secret capture ---
  // If this chat is armed (operator tapped [Provide securely] on a
  // request_secret card), THIS message is the secret value: delete it,
  // write it to the vault, resume the agent, and STOP. Runs before secret
  // detection, recordInbound, and the IPC broadcast so the raw value is
  // never recorded, logged, or forwarded.
  if (armedSecretCaptures.has(chat_id)) {
    // Capture the RAW message text, not effectiveText — the secret value
    // must be vaulted verbatim, without the steer/queue prefix-stripping or
    // trim that effectiveText applies (review #2047 finding #1). A
    // credential that legitimately starts with `/s` or has surrounding
    // whitespace would otherwise be mangled.
    const consumed = await captureProvidedSecret(ctx, chat_id, msgId ?? undefined, text)
    if (consumed) return
  }

  // --- Secret detection + vault-scrub ---
  // If the user pasted a secret, intercept BEFORE we record to history or
  // broadcast to the agent: write to vault, delete the Telegram message,
  // rewrite the prompt so the downstream session .jsonl, Hindsight memory,
  // and IPC payload never see the raw bytes. If there's no cached vault
  // passphrase, high-confidence hits are deferred and the user is asked to
  // unlock first.
  //
  // FAIL-CLOSED: if the pipeline throws, drop the message and warn the user
  // — never fall through to recordInbound/broadcast with raw bytes. See
  // gateway-secret-detect.test.ts and secret-detect-fail-closed.test.ts.
  try {
    // Channel B context rule: if we emitted "Paste the browser code here"
    // recently in this chat, treat the inbound as auth-flow-sensitive —
    // high-confidence secret detection regardless of pattern match. This
    // survives Anthropic changing their token format because it tracks the
    // gateway's own prompt, not the token shape.
    const authCodeSentAt = awaitingAuthCodeAt.get(chat_id)
    const isAuthFlowContext =
      authCodeSentAt !== undefined && Date.now() - authCodeSentAt < AUTH_CODE_CONTEXT_TTL_MS
    if (isAuthFlowContext) {
      process.stderr.write(`[secret-detect] auth-flow context rule active for chat ${chat_id}\n`)
    }

    const cachedPp = vaultPassphraseCache.get(chat_id)
    const passphrase = cachedPp && cachedPp.expiresAt > Date.now() ? cachedPp.passphrase : null
    if (passphrase) {
      const pipeRes = runPipeline({
        chat_id,
        message_id: msgId ?? null,
        text: effectiveText,
        passphrase,
        vaultWrite: defaultVaultWrite,
        vaultList: defaultVaultList,
      })
      if (pipeRes.stored.length > 0) {
        effectiveText = pipeRes.rewritten_text
        if (isAuthFlowContext) {
          awaitingAuthCodeAt.delete(chat_id) // consume: one message per prompt
        }
        // 2026-05-12: route through deleteSensitiveMessage so a
        // failed delete posts an in-chat warning naming the leaked
        // message id, instead of only logging to stderr (invisible
        // on mobile). Previously the operator saw "we deleted it
        // from chat" while the raw secret stayed visible. See
        // tests/secret-detect-delete-must-surface-failures.test.ts.
        if (msgId != null) {
          await deleteSensitiveMessage(chat_id, msgId, 'detected secret')
        }
        const lines = pipeRes.stored.map((s) =>
          `• \`${s.masked}\` → \`vault:${s.actual_slug}\``,
        )
        await switchroomReply(
          ctx,
          [`🔒 captured ${pipeRes.stored.length} secret${pipeRes.stored.length === 1 ? '' : 's'}:`, ...lines, '', 'reply \`rename X\` or \`forget\`.'].join('\n'),
          { html: true },
        )
        for (const s of pipeRes.stored) {
          secretStaging.set({
            chat_id,
            message_id: msgId ?? 0,
            detection: { ...s.detection, suggested_slug: s.actual_slug },
            staged_at: Date.now(),
          })
        }
      } else if (isAuthFlowContext && pipeRes.stored.length === 0) {
        // Channel B fallback: pattern didn't fire (Anthropic may have changed
        // the token format) but we know this is an auth code paste because we
        // prompted for it. Delete + stage + warn so no raw bytes leak.
        awaitingAuthCodeAt.delete(chat_id) // consume: one message per prompt
        // 2026-05-12: route through deleteSensitiveMessage. See
        // tests/secret-detect-delete-must-surface-failures.test.ts.
        if (msgId != null) {
          await deleteSensitiveMessage(chat_id, msgId, 'auth-flow secret')
        }
        // Issue #44: even with passphrase cached we hit this branch when the
        // pattern didn't fire — but at this point a vault write would still
        // need the user's intent. Stash with a one-tap unlock+save card so
        // the post-context flow stays seamless.
        const dKey = deferredKey(chat_id, msgId ?? 0)
        const cachedBranchDetection = detectSecrets(effectiveText).find((d) => d.confidence === 'high' && !d.suppressed)
        const cachedBranchSlug = cachedBranchDetection?.suggested_slug ?? (isAuthFlowContext ? 'anthropic_oauth_code' : 'secret')
        const cachedBranchKernelId = await mintDeferredSecretKernelRequest(
          cachedBranchSlug,
          loadAccess().allowFrom,
        )
        deferredSecrets.set(dKey, {
          chat_id,
          original_message_id: msgId ?? 0,
          text: effectiveText,
          staged_at: Date.now(),
          suggested_slug: cachedBranchSlug,
          kernel_request_id: cachedBranchKernelId ?? undefined,
        })
        await switchroomReply(
          ctx,
          '🔒 auth-flow secret detected. we deleted it from chat. tap below to save it to the vault — no re-paste needed.',
          { html: true, reply_markup: buildDeferredSecretKeyboard(dKey) },
        )
        return
      } else if (pipeRes.ambiguous.length > 0) {
        for (const d of pipeRes.ambiguous) {
          secretStaging.set({ chat_id, message_id: msgId ?? 0, detection: d, staged_at: Date.now() })
        }
        const top = pipeRes.ambiguous[0]!
        await switchroomReply(
          ctx,
          `👀 looks like a high-entropy string (rule: \`${top.rule_id}\`). reply \`stash NAME\` to store in vault, or \`ignore\`.`,
          { html: true },
        )
        // For ambiguous, we do NOT delete the message or rewrite — let the
        // user confirm first.
      }
    } else {
      // No passphrase cached — detect, but defer. Issue #44 turned this
      // into a one-tap unlock-and-save flow: previously the user had to
      // run `/vault list`, type their passphrase, then re-paste the
      // original secret (six steps for a non-technical user). Now they
      // tap a button and re-enter the passphrase exactly once.
      const detections = detectSecrets(effectiveText)
      const highConfDetection = detections.find((d) => d.confidence === 'high' && !d.suppressed)
      const hasHigh = highConfDetection !== undefined || isAuthFlowContext
      if (hasHigh) {
        if (isAuthFlowContext) {
          awaitingAuthCodeAt.delete(chat_id) // consume: one message per prompt
        }
        // Capture the slug at defer-time so the post-unlock auto-write
        // doesn't have to re-detect (which has a degenerate case for
        // Channel-B context defers where no pattern fired).
        const suggestedSlug =
          highConfDetection?.suggested_slug
          ?? (isAuthFlowContext ? 'anthropic_oauth_code' : 'secret')
        const dKey = deferredKey(chat_id, msgId ?? 0)
        const noPassKernelId = await mintDeferredSecretKernelRequest(
          suggestedSlug,
          loadAccess().allowFrom,
        )
        deferredSecrets.set(dKey, {
          chat_id,
          original_message_id: msgId ?? 0,
          text: effectiveText,
          staged_at: Date.now(),
          suggested_slug: suggestedSlug,
          kernel_request_id: noPassKernelId ?? undefined,
        })
        // 2026-05-12: route through deleteSensitiveMessage. See
        // tests/secret-detect-delete-must-surface-failures.test.ts.
        if (msgId != null) {
          await deleteSensitiveMessage(chat_id, msgId, 'detected secret')
        }
        await switchroomReply(
          ctx,
          '🔒 caught a secret. we deleted it from chat. tap below to unlock the vault and save it — no re-paste needed.',
          { html: true, reply_markup: buildDeferredSecretKeyboard(dKey) },
        )
        return
      }
    }
  } catch (err) {
    // FAIL-CLOSED: if the detector throws, we must NOT fall through to
    // recordInbound() / ipcServer.broadcast() with the raw text — that
    // would stamp the secret into SQLite and emit it to the agent
    // unscrubbed. Drop the message on the floor and warn the user.
    process.stderr.write(`[secret-detect] pipeline error: ${(err as Error).message}\n`)
    try {
      await switchroomReply(
        ctx,
        '⚠️ secret-detect pipeline crashed; this message was dropped for safety. please try again or check the agent log.',
        { html: true },
      )
    } catch {}
    // 2026-05-12: route through deleteSensitiveMessage. The
    // pipeline-error fail-closed path is the LAST line of defence —
    // if delete fails here, the operator must know so they can
    // delete manually. See
    // tests/secret-detect-delete-must-surface-failures.test.ts.
    if (msgId != null) {
      await deleteSensitiveMessage(chat_id, msgId, 'secret-detect pipeline-error fallback')
    }
    return
  }

  // Status reaction controller
  let isSteering = false
  let priorTurnStartedAt: number | undefined
  if (msgId != null) {
    const key = statusKey(chat_id, messageThreadId)
    const priorActive = activeStatusReactions.get(key)
    const priorTurnInFlight = priorActive != null
    // New default: mid-turn messages are queued unless the user explicitly
    // steers. isSteering is true only when the steer prefix is present.
    // (Legacy: without any prefix the old behavior was isSteering=true; now
    // it's false so the message goes through as queued="true".)
    isSteering = priorTurnInFlight && isSteerPrefix
    if (priorTurnInFlight) priorTurnStartedAt = activeTurnStartedAt.get(key)

    // Mid-turn auto-classify SHADOW: compute what a topic+recency classifier
    // WOULD decide and log it — behaviour is UNCHANGED (isSteering above is
    // untouched). Gathers the real-world distribution (same-topic continuation
    // vs cross-topic, recency spread) to tune auto-steer before it ever acts.
    // No-op unless the shadow flag is on AND a turn is in flight (the only case
    // a steer-vs-queue decision is meaningful).
    if (AUTOCLASSIFY_MIDTURN_SHADOW && priorTurnInFlight) {
      const lastOut = lastAgentOutputAt.get(key)
      const msSinceOut = lastOut != null ? Date.now() - lastOut : null
      const shadow = autoClassifyMidTurnInbound({
        isSteerPrefix,
        isQueuePrefix: isQueuedPrefix,
        priorTurnInFlight,
        isDm: isDmChatId(chat_id),
        incomingThreadId: messageThreadId ?? null,
        activeTurnThreadId: currentTurn?.sessionThreadId ?? null,
        msSinceLastAgentOutput: msSinceOut,
        dmSteerWindowMs: 0, // DM auto-steer stays off (the April regime)
        topicSteerWindowMs: 8_000, // candidate window — what we're tuning
      })
      process.stderr.write(
        `telegram gateway: autoclassify-shadow chat_id=${chat_id} ` +
        `would=${shadow.decision} reason=${shadow.reason} same_topic=${shadow.sameTopic ?? '-'} ` +
        `ms_since_out=${msSinceOut ?? '-'} actual=${isSteering ? 'steer' : 'queue'}\n`,
      )
    }

    if (access.statusReactions !== false) {
      if (isSteering) {
        // Explicit steer: mark with 🤝 on the inbound message; leave the
        // existing StatusReactionController running for the in-flight turn.
        void bot.api.setMessageReaction(chat_id, msgId, [{ type: 'emoji', emoji: '🤝' }]).catch(() => {})
      } else if (priorTurnInFlight) {
        // Queued mid-turn message (new default): don't touch the existing
        // controller; just ack the inbound message with 👀 so the user
        // knows we received it, without disrupting the in-flight reaction.
        void bot.api.setMessageReaction(chat_id, msgId, [{ type: 'emoji', emoji: '👀' }]).catch(() => {})
        // #203: time-to-ack metric — measure gateway-receive → ack-post delta.
        logStreamingEvent({ kind: 'inbound_ack', chatId: chat_id, messageId: msgId, ackDelayMs: Date.now() - inboundReceivedAt })
      } else {
        // Fresh turn — priorTurnInFlight is false, so priorActive is
        // provably undefined. Earlier `if (priorActive)` block was dead
        // code, removed in the same first-paint cleanup pass.
        const sKey = streamKey(chat_id, messageThreadId)
        const priorStream = activeDraftStreams.get(sKey)
        if (priorStream && !priorStream.isFinal()) {
          // Closes #472 finding #17 — pre-fix this finalize was
          // fire-and-forget. The new turn's reply tool would then create
          // a fresh stream and send its first chunk while the prior
          // stream's terminal sendMessage was still in flight. The
          // late-materialise landed AFTER the new turn's content,
          // visible to the user as a stale "Done" message followed by
          // the new reply (or worse — duplicate content).
          //
          // Awaiting here costs the few hundred ms the final API call
          // takes, but only on rapid follow-ups where the prior turn
          // hadn't yet flushed. The latency hit beats the duplicate-
          // content bug. Delete from the map FIRST so any concurrent
          // reads can't see the stale stream while we await.
          activeDraftStreams.delete(sKey)
          await priorStream.finalize().catch(() => {})
        }
        suppressPtyPreview.delete(sKey)

        // #542 fix: pass the cached chat-level allowed-reactions filter
        // so the controller's resolveEmoji can fall through to a permitted
        // variant instead of attempting an emoji Telegram will reject.
        // First message in a chat sees `null` (cache miss) — kicks off
        // the probe for next time.
        const allowedReactions = chatAvailableReactions.get(chat_id) ?? null
        if (!chatAvailableReactions.has(chat_id)) {
          probeAvailableReactions(chat_id)
        }
        // #2527: use inbound msgId as a stable per-turn reaction identifier.
        // The controller is created before currentTurn.turnId is assigned
        // (that happens in handleSessionEvent's enqueue branch), so we capture
        // msgId here and use it as the reaction-session token in log events.
        const ctrlTurnToken = `${chat_id}:${msgId}`
        const ctrl = new StatusReactionController(async (emoji) => {
          await bot.api.setMessageReaction(chat_id, msgId, [
            { type: 'emoji', emoji: emoji as ReactionTypeEmoji['emoji'] },
          ])
          // #203: every status-reaction transition is a user-visible signal.
          signalTracker.noteSignal(key, Date.now())
        }, allowedReactions, {
          // #2527: emit a structured transition event on each emoji change so
          // the reaction lifecycle is visible in streaming-metrics logs. Also
          // increment the per-key counter for the turn_no_reply_warn metric.
          onTransition: (emoji) => {
            reactionTransitionCounts.set(key, (reactionTransitionCounts.get(key) ?? 0) + 1)
            logStreamingEvent({
              kind: 'status_reaction_transition',
              chatId: chat_id,
              turnId: ctrlTurnToken,
              emoji,
            })
          },
        })
        activeStatusReactions.set(key, ctrl)
        activeReactionMsgIds.set(key, { chatId: chat_id, messageId: msgId })
        activeTurnStartedAt.set(key, Date.now())
        progressUpdateTurnCount.set(key, 0)  // Reset turn counter
        // #2527: log controller install so the lifecycle start is observable.
        logStreamingEvent({
          kind: 'status_reaction_install',
          chatId: chat_id,
          turnId: ctrlTurnToken,
          messageId: msgId,
        })
        ctrl.setQueued()
        // #203: time-to-ack metric — setQueued() triggers the initial 👀 reaction
        // asynchronously through the controller chain.
        logStreamingEvent({ kind: 'inbound_ack', chatId: chat_id, messageId: msgId, ackDelayMs: Date.now() - inboundReceivedAt })
        // #203: signal tracker — start tracking silent gaps for this fresh turn.
        signalTracker.reset(statusKey(chat_id, messageThreadId), Date.now())
        // #1122 silence-poke: start the silence clock for this turn so
        // the framework can nudge the model if it goes quiet past the
        // soft / firm thresholds.
        silencePoke.startTurn(statusKey(chat_id, messageThreadId), Date.now())
        // Ack-first gate clear is centralised in handleSessionEvent's
        // `enqueue` branch — that fires for EVERY fresh turn atom
        // (real inbound, cron, subagent-handback, vault-grant wake,
        // restart marker) so cron/handback turns also re-arm the gate.
        // See the call site under `case 'enqueue'` (~line 6794).
        // #1445 cross-turn pending-async ambient. A new turn starting
        // (user inbound, synthesised wake, or handback channel) is the
        // signal that the model is about to re-engage — clear any
        // pending-progress edits anchored to the *prior* turn's
        // outbound so the framework stops talking over the new turn.
        // clearPending drops the per-key state outright, so the new
        // turn's `tool_use(Agent|Task|Bash bg)` + outbound capture
        // afresh via `noteAsyncDispatch` / `noteOutbound`.
        pendingProgress.clearPending(
          statusKey(chat_id, messageThreadId),
          'inbound',
        )
        // Human-feel UX: hold a continuous `typing…` indicator for the
        // WHOLE turn, not just the split-second a reply is transmitted.
        // A person you message shows as typing the entire time they
        // compose; switchroom used to fire only one-shot ~5s pings, so
        // any turn that read a file or thought for a moment went dark
        // after 5s. Self-renews every 4s; stopped at the canonical
        // turn-end (`purgeReactionTracking → stopTurnTypingLoop`).
        // Deterministic, framework-owned, no prose — the mechanical
        // ambient layer of the pacing contract.
        // PR3 supergroup-mode: pass thread so the indicator lands in
        // this turn's topic (otherwise topic A's turn-end would kill
        // topic B's typing indicator on shared chat_id keying).
        startTurnTypingLoop(chat_id, messageThreadId ?? null)
        // #1122 KPI: emit turn_started so dashboards can compute funnel
        // start counts + correlate to turn_ended for duration / TTFO.
        emitRuntimeMetric({
          kind: 'turn_started',
          chat_id,
          message_id: msgId,
          thread_id: messageThreadId ?? null,
          inbound_classified_as_status_query: classifyInbound(text).isStatusQuery,
        })
        const agentDir = resolveAgentDirFromEnv()
        if (agentDir != null) {
          addActiveReaction(agentDir, { chatId: chat_id, messageId: msgId, threadId: messageThreadId ?? null, reactedAt: Date.now() })
        }
      }
    } else if (access.ackReaction) {
      void bot.api.setMessageReaction(chat_id, msgId, [
        { type: 'emoji', emoji: access.ackReaction as ReactionTypeEmoji['emoji'] },
      ]).catch(() => {})
      // #203: time-to-ack metric for the custom-ack-reaction path.
      logStreamingEvent({ kind: 'inbound_ack', chatId: chat_id, messageId: msgId, ackDelayMs: Date.now() - inboundReceivedAt })
    }
  }

  // Start a new progress card only for fresh turns (no prior turn in flight).
  // Queued mid-turn messages piggyback on the existing card; steer messages
  // also don't start a new card (the in-flight turn owns it).
  if (!isSteering && priorTurnStartedAt == null) {
    try {
      progressDriver?.startTurn({
        chatId: chat_id,
        threadId: messageThreadId != null ? String(messageThreadId) : undefined,
        userText: effectiveText,
        replyToMessageId: msgId != null ? msgId : undefined,
      })
    } catch (err) {
      process.stderr.write(`telegram gateway: progress-card startTurn failed: ${(err as Error).message}\n`)
    }

    // Pre-allocated draft + forum-topic placeholder send removed in
    // #553 PR 5. The 👀 status reaction (#568) and
    // sendChatAction('typing') indicator (#585) now bridge the
    // ~1s gap between inbound and the agent's first real text.
  }

  const imagePath = downloadImage ? await downloadImage() : undefined

  // A2: resolve the extra attachments (2nd..Nth in a coalesced multi-media
  // burst). Photos are downloaded the same way as the primary; documents/
  // voice carry only attachment metadata (the agent fetches them via
  // download_attachment). Numbered meta fields below let the agent see each.
  const extraResolved: Array<{ imagePath?: string; attachment?: AttachmentMeta }> = []
  if (extraAttachments && extraAttachments.length > 0) {
    for (const ex of extraAttachments) {
      const exImagePath = ex.downloadImage ? await ex.downloadImage() : undefined
      extraResolved.push({ imagePath: exImagePath, attachment: ex.attachment })
    }
  }
  // Flatten the numbered meta fields once so the InboundMessage literal can
  // spread them. Primary is "1" (unsuffixed); extras start at "_2".
  const extraMeta = buildExtraAttachmentMeta(extraResolved)
  // Total attachment count (primary + extras) so the agent knows how many to
  // expect without probing for numbered fields. Only emitted when >1.
  const primaryHasAttachment = imagePath != null || attachment != null
  const attachmentCount = (primaryHasAttachment ? 1 : 0) + extraResolved.length

  // Telegram-native reply context (issue #119). Same pattern as server.ts:
  // `replyToText` is raw (for SQLite); `replyToTextEscaped` is XML-escaped
  // (for channel meta).
  const replyToMsg = ctx.message?.reply_to_message
  const replyToMessageId = replyToMsg?.message_id
  const replyToTextRaw = replyToMsg
    ? (replyToMsg.text ?? replyToMsg.caption ?? undefined)
    : undefined
  const replyToText = replyToTextRaw != null
    ? (replyToTextRaw.length > REPLY_TO_TEXT_MAX
        ? replyToTextRaw.slice(0, REPLY_TO_TEXT_MAX - 1) + '…'
        : replyToTextRaw)
    : undefined
  const replyToTextEscaped = formatReplyToText(replyToTextRaw, REPLY_TO_TEXT_MAX)

  if (HISTORY_ENABLED) {
    try {
      recordInbound({
        chat_id,
        thread_id: messageThreadId ?? null,
        message_id: msgId,
        user: from.username ?? String(from.id),
        user_id: String(from.id),
        ts: ctx.message?.date ?? Math.floor(Date.now() / 1000),
        text: effectiveText,
        attachment_kind: attachment?.kind,
        reply_to_message_id: replyToMessageId ?? null,
        reply_to_text: replyToText ?? null,
      })
    } catch (err) {
      process.stderr.write(`telegram gateway: history recordInbound failed: ${err}\n`)
    }
  }

  // Build steering meta.
  // priorTurnInProgress is true for ANY mid-turn follow-up (queued or steering).
  // isSteering = explicit /steer or /s prefix was used.
  // isQueuedMidTurn = prior turn was in flight and no steer prefix (new default).
  const priorTurnInProgress = isSteering || (priorTurnStartedAt != null)
  const isQueuedMidTurn = priorTurnInProgress && !isSteering
  let secondsSinceTurnStart: number | undefined
  let priorAssistantPreview: string | undefined
  if (priorTurnInProgress) {
    if (priorTurnStartedAt != null) {
      secondsSinceTurnStart = Math.max(0, Math.floor((Date.now() - priorTurnStartedAt) / 1000))
    }
    if (HISTORY_ENABLED) {
      try {
        const rows = queryHistory({ chat_id, thread_id: messageThreadId ?? null, limit: 10 })
        for (let i = rows.length - 1; i >= 0; i--) {
          const r = rows[i]!
          if (r.role === 'assistant' && r.text && r.text.length > 0) {
            priorAssistantPreview = formatPriorAssistantPreview(r.text, 200)
            break
          }
        }
      } catch {}
    }
  }

  // Dispatch to connected bridge via IPC
  // Component 3 — stable origin turn id stamped into the meta the model
  // reads, so a reply can echo it back (origin_turn_id) and the gateway
  // can route the answer to the turn that owns it even after currentTurn
  // flips. Derived from chat/thread/messageId, matching the turnId the
  // enqueue handler computes for the turn this inbound starts.
  const originTurnId = deriveTurnId(chat_id, messageThreadId ?? null, msgId)
  // Component 4 — per-turn topic framing. In a forum supergroup a queued
  // cross-topic message could tempt the model to also answer a pending
  // question from another topic. A one-line directive (only for topic
  // inbounds, only when framing is enabled) pins the model to THIS
  // message's topic. DMs / non-topic chats get nothing.
  const topicScope =
    TOPIC_FRAMING_ENABLED && messageThreadId != null
      ? 'This message belongs to the current topic only — answer ONLY this question, in this topic. Do not also answer a pending message from another topic.'
      : undefined
  const inboundMsg: InboundMessage = {
    type: 'inbound',
    chatId: chat_id,
    ...(messageThreadId != null ? { threadId: messageThreadId } : {}),
    messageId: msgId ?? 0,
    user: from.username ?? String(from.id),
    userId: from.id,
    ts: ctx.message?.date ?? Math.floor(Date.now() / 1000),
    text: effectiveText,
    ...(imagePath ? { imagePath } : {}),
    ...(attachment ? {
      attachment: {
        fileId: attachment.file_id,
        mimeType: attachment.mime ?? 'application/octet-stream',
        ...(attachment.name ? { fileName: attachment.name } : {}),
      },
    } : {}),
    meta: {
      chat_id,
      ...(msgId != null ? { message_id: String(msgId) } : {}),
      user: from.username ?? String(from.id),
      user_id: String(from.id),
      ts: new Date((ctx.message?.date ?? 0) * 1000).toISOString(),
      ...(messageThreadId != null ? { message_thread_id: String(messageThreadId) } : {}),
      // Component 3 — origin turn id. The model is told to pass this back
      // as origin_turn_id on the reply so the answer routes to the topic
      // this message came from (turn-origin routing). The reply tool also
      // resolves it from the live/recent turn registry, so a model that
      // omits it still routes correctly via the live-turn fallback.
      ...(originTurnId != null ? { origin_turn_id: originTurnId } : {}),
      // Component 4 — per-turn topic-scope directive (supergroup topics).
      ...(topicScope != null ? { topic_scope: topicScope } : {}),
      ...(imagePath ? { image_path: imagePath } : {}),
      // Telegram-native reply context (issue #119). When set, the user
      // long-pressed a prior message and chose "Reply" — the agent should
      // treat this as the antecedent for "this" / "that" / pronoun
      // references in the body, instead of asking the user what they meant.
      ...(replyToMessageId != null ? { reply_to_message_id: String(replyToMessageId) } : {}),
      // Use the XML-escaped form for the meta — the raw form is in the
      // SQLite buffer for verbatim retrieval via get_recent_messages.
      ...(replyToTextEscaped != null && replyToTextEscaped.length > 0 ? { reply_to_text: replyToTextEscaped } : {}),
      // queued="true" when mid-turn with no steer prefix (new default), or
      // with explicit /queue or /q prefix (legacy alias).
      ...((isQueuedMidTurn || isQueuedPrefix) ? { queued: 'true' } : {}),
      // steering="true" only when explicit /steer or /s prefix used.
      ...(isSteering ? { steering: 'true' } : {}),
      ...(priorTurnInProgress ? { prior_turn_in_progress: 'true' } : {}),
      ...(priorTurnInProgress && secondsSinceTurnStart != null ? { seconds_since_turn_start: String(secondsSinceTurnStart) } : {}),
      ...(priorTurnInProgress && priorAssistantPreview != null && priorAssistantPreview.length > 0 ? { prior_assistant_preview: priorAssistantPreview } : {}),
      ...(attachment ? {
        attachment_kind: attachment.kind,
        attachment_file_id: attachment.file_id,
        ...(attachment.size != null ? { attachment_size: String(attachment.size) } : {}),
        ...(attachment.mime ? { attachment_mime: attachment.mime } : {}),
        ...(attachment.name ? { attachment_name: attachment.name } : {}),
      } : {}),
      // A2: numbered fields for the 2nd..Nth attachment + a total count so
      // the agent reads every item in a coalesced multi-media burst.
      ...(attachmentCount > 1 ? { attachment_count: String(attachmentCount) } : {}),
      ...extraMeta,
    },
  }

  // Deliver to THIS agent's registered bridge, buffering on miss.
  // broadcast()/clientCount() were the wrong primitives: broadcast is
  // not registered-keyed (writes to any alive socket incl. an
  // unregistered pre-handshake one) and yields no delivered signal,
  // and clientCount() counts unregistered sockets — so a bridge
  // mid-reconnect made clientCount()>0, the message was broadcast into
  // a non-registered socket, the "restarting" notice was suppressed,
  // and the user's message was silently lost. The old "queued either
  // way" comment was false: broadcast does not queue. sendToAgent is
  // registered-keyed + returns a real delivered bool; on a miss we
  // push to pendingInboundBuffer, which onClientRegistered drains on
  // the next bridge register — so the notice below is now truthful.
  const selfAgent = process.env.SWITCHROOM_AGENT_NAME ?? ''

  // #1556: turn-gated delivery. A non-steering inbound that arrives
  // mid-turn must NOT be sent to the bridge now — claude would type it
  // into its TUI composer and the auto-submit races turn-completion,
  // stranding the message (the lawgpt wedge, 2026-05-19). Buffer it;
  // `purgeReactionTracking`'s turn-complete hook and the turn-gated
  // idle-drain flush it the instant claude goes idle, where the channel
  // notification submits cleanly as a fresh turn. Steering messages are
  // exempt — reaching claude mid-turn is the whole point of /steer.
  //
  // CRITICAL: turnInFlight reads the snapshot taken at receipt above,
  // not `activeTurnStartedAt.size > 0` live. The fresh-turn branch at
  // line ~7357 already populated the Map for THIS inbound's turn;
  // reading the live size here would self-block (see the comment on
  // turnInFlightAtReceipt for the wedge symptom this fixes).
  // Problem B: a deferred `!` interrupt. The synchronous SIGINT was skipped
  // above (a tool was in flight) — claude is still working. Don't deliver the
  // replacement body now (it would race the live tool); stash the fully-built
  // inbound and let `fireDeferredInterrupt` SIGINT + deliver at the next clean
  // boundary, or when the max-wait timer expires. Rapid repeated `!` coalesce:
  // the latest body replaces the stashed inbound, the original deadline holds
  // so the wait stays bounded.
  if (deferInterrupt) {
    const selfAgentDefer = process.env.SWITCHROOM_AGENT_NAME ?? ''
    if (pendingDeferredInterrupt != null) {
      pendingDeferredInterrupt.inboundMsg = inboundMsg
      pendingDeferredInterrupt.msgId = msgId ?? null
      process.stderr.write(
        `telegram gateway: deferred-interrupt coalesced (replacing pending body) agent=${selfAgentDefer} chat=${chat_id} msg=${msgId ?? '-'}\n`,
      )
    } else {
      const maxWaitMs = resolveInterruptMaxWaitMs(loadAccess().interruptMaxWaitMs)
      pendingDeferredInterrupt = {
        agentName: selfAgentDefer,
        inboundMsg,
        chatId: chat_id,
        msgId: msgId ?? null,
        threadId: messageThreadId ?? undefined,
        registeredAt: Date.now(),
        deadlineTimer: setTimeout(() => { void fireDeferredInterrupt('timeout') }, maxWaitMs),
      }
      process.stderr.write(
        `telegram gateway: deferred-interrupt parked agent=${selfAgentDefer} chat=${chat_id} ` +
        `msg=${msgId ?? '-'} max_wait_ms=${maxWaitMs} in_flight=${toolFlightTracker.inFlightCount()}\n`,
      )
    }
    return
  }

  // PR2 obligation-ledger OPEN — BEFORE the buffer-until-idle / deliver split so
  // a mid-turn cross-topic inbound (the 715 case) is tracked whether it is
  // buffered or delivered now. Idempotent + gated; no-op when the flag is off.
  openObligationFromInbound(inboundMsg, {
    isSteering,
    isInterrupt: interrupt.isInterrupt,
    effectiveText,
  })

  if (
    decideInboundDelivery({
      turnInFlight: turnInFlightAtReceipt,
      isSteering,
      // Interrupt-marker carve-out (2026-05-24): the `!`-prefixed body
      // must bypass the "buffer-until-turn-complete" gate because the
      // SIGINT'd turn often doesn't emit turn_complete, leaving the
      // body stranded in pendingInboundBuffer indefinitely. The
      // `interrupt` const is computed at the start of handleInbound
      // (line ~7606) and remains in scope here. When the user fires
      // `!`-with-body, this delivers the body as a fresh inbound to
      // the freshly-killed bridge.
      isInterrupt: interrupt.isInterrupt,
    }) === 'buffer-until-idle'
  ) {
    pendingInboundBuffer.push(selfAgent, inboundMsg)
    process.stderr.write(
      `telegram gateway: inbound held mid-turn agent=${selfAgent} ` +
      `chat=${chat_id} msg=${msgId ?? '-'} — will flush on turn-complete\n`,
    )
    // Component 5 (Hook A) — queued-status UX. When this buffered inbound
    // is in a DIFFERENT forum topic than the in-flight turn, the user in
    // that topic otherwise sees only a 👀 reaction (or nothing). Post one
    // self-updating status into the buffered message's OWN topic so they
    // know they're queued. Suppressed for DMs (no topics) and same-topic
    // queues (the in-flight turn's own card already covers them).
    const inFlightThread = currentTurn?.sessionThreadId
    if (
      QUEUED_STATUS_UX_ENABLED &&
      !isDmChatId(chat_id) &&
      messageThreadId != null &&
      messageThreadId !== inFlightThread
    ) {
      postQueuedStatus(chat_id, messageThreadId, inFlightThread)
    }
    return
  }

  // Pre-send composer clear (the marko wedge). The inbound is about to be
  // delivered as an MCP `notifications/claude/channel` notification, which
  // the unmodified CLI appends into its composer and auto-submits ONLY when
  // the composer is empty + idle. The #1556 gate above guarantees idle, but
  // NOT empty: stale typed-ahead / ghost text stranded in the composer
  // (observed live on agent `marko`: "Yes, go ahead on both") makes the
  // appended inbound fail to submit and silently swallows every subsequent
  // queued inbound until a hard restart. Wipe the composer first so the
  // notification lands at a clean line. Soft-fail by contract — a clear
  // failure (no tmux session under legacy_pty, socket missing, timeout)
  // must NEVER block delivery; log and proceed.
  if (selfAgent) {
    try {
      const { clearAgentComposer } = await import('../../src/agents/tmux.js')
      const cleared = clearAgentComposer({ agentName: selfAgent })
      if ('error' in cleared) {
        process.stderr.write(
          `telegram gateway: pre-send composer-clear soft-failed agent=${selfAgent}: ${cleared.error} — delivering anyway\n`,
        )
      }
    } catch (err) {
      process.stderr.write(
        `telegram gateway: pre-send composer-clear threw agent=${selfAgent}: ${(err as Error).message} — delivering anyway\n`,
      )
    }
  }

  const delivered = ipcServer.sendToAgent(selfAgent, inboundMsg)
  if (delivered) {
    const busyKey = markClaudeBusyForInbound(inboundMsg)
    // Track until claude acks via `enqueue` (the marko drop-wedge): if no ack
    // lands, the message stranded in the composer and the sweep re-delivers
    // it. Track ONLY messages that produce an `enqueue` to ack against —
    // shouldTrackDelivery excludes steering / `!` interrupt (amend the running
    // turn), synthetic (meta.source) inbounds, and empty bodies, all of which
    // never enqueue and would re-deliver forever. The tracked messageId lets
    // the ack match only THIS message's enqueue (not a synthetic turn sharing
    // the key). See shouldTrackDelivery / ackDelivery (inbound-delivery-confirm.ts).
    if (
      DELIVERY_CONFIRM_ENABLED &&
      shouldTrackDelivery({
        isSteering,
        isInterrupt: interrupt.isInterrupt,
        hasSource: inboundMsg.meta?.source != null,
        effectiveText,
      })
    ) {
      trackDelivery(deliveryQueue, busyKey, inboundMsg, Date.now(), String(inboundMsg.messageId))
    }
  }
  if (!delivered) {
    // Only persist fresh user turns to the durable spool. Steering / `!`
    // interrupt / empty bodies are mid-turn amendments or no-ops that would
    // arrive orphaned if replayed as a fresh turn after a restart — drop them
    // (the restart notice below tells the user to re-send). Mirrors the
    // tracking + #1556-gate carve-outs.
    if (
      shouldTrackDelivery({
        isSteering,
        isInterrupt: interrupt.isInterrupt,
        hasSource: inboundMsg.meta?.source != null,
        effectiveText,
      })
    ) {
      pendingInboundBuffer.push(selfAgent, inboundMsg)
    }
    const threadOpts = messageThreadId != null ? { message_thread_id: messageThreadId } : {}
    // #1075: thread-id-bearing — swallow via robustApiCall so a deleted
    // topic doesn't crash the gateway. Fire-and-forget; the inbound is
    // genuinely buffered now, so the hint is accurate, not a guess.
    void swallowingApiCall(
      () => bot.api.sendMessage(chat_id, '⏳ Agent is restarting — your message is queued and will be processed when it reconnects.', { ...threadOpts }),
      {
        chat_id,
        verb: 'agent-restarting-notice',
        ...(messageThreadId != null ? { threadId: messageThreadId } : {}),
      },
    )
  }
}

// ─── Switchroom CLI helpers ───────────────────────────────────────────────
const SWITCHROOM_CLI = process.env.SWITCHROOM_CLI_PATH ?? 'switchroom'
const SWITCHROOM_CONFIG = process.env.SWITCHROOM_CONFIG

function switchroomExec(args: string[], timeoutMs = 15000): string {
  const fullArgs = SWITCHROOM_CONFIG ? ['--config', SWITCHROOM_CONFIG, ...args] : args
  return execFileSync(SWITCHROOM_CLI, fullArgs, {
    encoding: 'utf-8',
    timeout: timeoutMs,
    env: { ...process.env, FORCE_COLOR: '0', NO_COLOR: '1' },
    maxBuffer: 4 * 1024 * 1024,
  })
}

function switchroomExecCombined(args: string[], timeoutMs = 15000): string {
  const fullArgs = SWITCHROOM_CONFIG ? ['--config', SWITCHROOM_CONFIG, ...args] : args
  const quoted = [SWITCHROOM_CLI, ...fullArgs].map((a) => `'${String(a).replace(/'/g, "'\\''")}'`).join(' ')
  return execSync(`${quoted} 2>&1`, {
    encoding: 'utf-8',
    timeout: timeoutMs,
    env: { ...process.env, FORCE_COLOR: '0', NO_COLOR: '1' },
    maxBuffer: 4 * 1024 * 1024,
    shell: '/bin/bash',
  })
}

// Default truncation budget for CLI output bound for Telegram. The rich-message
// wire cap is RICH_MESSAGE_MAX_CHARS (32768) post-#2669, not the legacy 4096
// plain-text limit. Mirrors shared/bot-runtime.ts formatSwitchroomOutput.
function formatSwitchroomOutput(output: string, maxLen = RICH_MESSAGE_MAX_CHARS): string {
  const trimmed = output.trim()
  if (trimmed.length <= maxLen) return trimmed
  return trimmed.slice(0, maxLen - 20) + '\n... (truncated)'
}

function stripAnsi(text: string): string {
  return text.replace(/\x1b\[[0-9;]*[a-zA-Z]/g, '')
}

// #2669: escape GFM-markdown specials in dynamic values interpolated into
// rich-message bodies (kept under the legacy name to avoid churn).
function escapeHtmlForTg(text: string): string {
  return text.replace(/([\\`*_~=\[\]|])/g, '\\$1')
}

// Wrap CLI/command output in a fenced code block (content is literal there).
function preBlock(text: string): string {
  return '```\n' + text.replace(/```/g, '`​``') + '\n```'
}

type SwitchroomReplyMarkup =
  | InlineKeyboard
  | { force_reply: true; input_field_placeholder?: string; selective?: boolean }

async function switchroomReply(
  ctx: Context,
  text: string,
  options: {
    html?: boolean
    reply_markup?: SwitchroomReplyMarkup
    // PR5 — supergroup-mode slash-command smart split (CPO #4).
    // 'query' (default semantics) follows the originating topic;
    // 'mutation' and 'heavy' route to admin alias in supergroup mode;
    // omitted/undefined preserves legacy in-place reply behavior.
    classification?: 'query' | 'mutation' | 'heavy'
  } = {},
): Promise<void> {
  const chatId = String(ctx.chat!.id)
  const baseThreadId = resolveThreadId(chatId, ctx.message?.message_thread_id)
  // PR5 — when caller flagged the reply as mutation/heavy AND we're
  // in supergroup mode, override the in-place thread with the
  // admin-alias topic. For 'query' (or non-supergroup), routedOpts
  // is `{}` and baseThreadId wins → behavior unchanged.
  const routedOpts = options.classification
    ? slashCommandReplyOpts(ctx, options.classification)
    : {}
  const threadId = routedOpts.message_thread_id ?? baseThreadId
  const replyOpts = {
    ...(threadId != null ? { message_thread_id: threadId } : {}),
    ...(options.reply_markup ? { reply_markup: options.reply_markup } : {}),
  }
  // #2669: `options.html` now means "render `text` as GFM markdown via the
  // rich-message path" (legacy field name kept). Plain otherwise.
  if (options.html) {
    await ctx.replyWithRichMessage(richMessage(text), replyOpts)
  } else {
    await ctx.reply(text, replyOpts)
  }
}

/**
 * Best-effort delete of a message that contains a sensitive value
 * (passphrase, vault secret, raw detected secret). Closes #472 finding
 * #22 — pre-fix every site `void bot.api.deleteMessage(...).catch(() => {})`
 * silently swallowed failures, leaving the secret visible in chat
 * history forever with no operator signal.
 *
 * On failure: log loudly to stderr AND post an in-chat warning naming
 * the message_id the user must delete manually. Awaited so the caller
 * can rely on at-least-attempt + at-least-notify semantics.
 */
async function deleteSensitiveMessage(
  chatId: string,
  msgId: number,
  reason: string,
): Promise<void> {
  try {
    // #1075: wrap through robustApiCall for flood-wait retries. THIS
    // ONE must still throw on permanent failure — the caller's contract
    // is "delete the secret, otherwise log loudly + warn user", and
    // swallowing would lose the audit signal.
    await robustApiCall(
      () => bot.api.deleteMessage(chatId, msgId),
      { chat_id: chatId, verb: 'deleteSensitiveMessage' },
    )
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err)
    process.stderr.write(
      `telegram gateway: SECURITY: delete of ${reason} message ${msgId} in chat ${chatId} FAILED: ${msg}. ` +
      `The sensitive value remains visible in chat history.\n`,
    )
    // In-chat warning so the user knows to delete manually. Best-effort
    // — if this also fails (rare; same chat just rejected our delete),
    // the stderr log is the audit trail.
    await swallowingApiCall(
      () =>
        // allow-raw-bot-api: wrapped in swallowingApiCall (retry policy)
        bot.api.sendRichMessage(
          chatId,
          richMessage(`⚠️ **Could not auto-delete message containing your ${escapeHtmlForTg(reason)}.**\n\nPlease delete message \`${msgId}\` manually so the value is not retained in chat history.\n\n_Reason: ${escapeHtmlForTg(msg)}_`),
          {},
        ),
      { chat_id: chatId, verb: 'deleteSensitiveMessage.warning' },
    )
  }
}

function getCommandArgs(ctx: Context): string {
  const fromMatch = typeof ctx.match === 'string' ? ctx.match.trim() : ''
  if (fromMatch) return fromMatch
  const text = (ctx.msg as { text?: string } | undefined)?.text ?? (ctx.message as { text?: string } | undefined)?.text ?? ''
  const m = text.match(/^\/\S+\s+([\s\S]*)$/)
  return m ? m[1].trim() : ''
}

/**
 * True when a slash command's argument string carries a trailing `demo`
 * token — the per-command PII-mask modifier for screen recordings
 * (`/usage demo`, `/auth demo`, `/status demo`, `/whoami demo`). Matches
 * `demo` as the last whitespace-delimited token, case-insensitively, so
 * `/auth show demo` and `/usage demo` both flip the flag while a label
 * literally named `demo-foo` does not.
 */
function hasDemoFlag(args: string): boolean {
  return /(?:^|\s)demo$/i.test(args.trim())
}

/** Validate that a string looks like a safe agent/resource name.
 *  Agent names should be alphanumeric with hyphens/underscores only.
 *  This prevents shell metacharacter injection even though both exec
 *  functions already handle quoting. Defense in depth. */
function assertSafeAgentName(name: string): void {
  if (!/^[a-zA-Z0-9_-]{1,64}$/.test(name) && name !== 'all') {
    throw new Error(`invalid agent name: ${name}`)
  }
}

/**
 * Expand the special `all` keyword into the real agent list for restart-
 * driving. The CLI handles its own expansion for the YAML mutation; this
 * helper exists so the gateway's post-CLI restart loop knows whom to
 * bounce. Returns `agents` unchanged when `all` is not present.
 */
async function resolveAgentsForRestart(agents: string[]): Promise<string[]> {
  if (!(agents.length === 1 && agents[0] === 'all')) return agents
  type AgentListResp = { agents: Array<{ name: string }> }
  const data = switchroomExecJson<AgentListResp>(['agent', 'list'])
  return data?.agents?.map(a => a.name).filter(Boolean) ?? []
}

function getMyAgentName(): string {
  const fromEnv = process.env.SWITCHROOM_AGENT_NAME
  if (fromEnv && fromEnv.trim().length > 0) return fromEnv.trim()
  return basename(process.cwd())
}

function isSelfTargetingCommand(name: string): boolean {
  if (name === 'all') return true
  return name === getMyAgentName()
}

// ─── Restart marker ───────────────────────────────────────────────────────
type RestartMarker = { chat_id: string; thread_id: number | null; ack_message_id: number | null; ts: number }

/**
 * In-memory timestamp of the most recent planned restart written by this
 * gateway process. The restart-watchdog reads this (with a freshness
 * window) instead of `readRestartMarker()` to decide whether a NRestarts
 * uptick is user-initiated.
 *
 * The disk marker is unsafe for that purpose because the bridge-reconnect
 * handler clears it within ~1-2s of agent boot, before the next watchdog
 * tick (every 30s by default). That race made every \`/restart agent\`
 * produce a misleading "agent restarted unexpectedly" card. The in-memory
 * timestamp is set on every \`writeRestartMarker\` and survives bridge-
 * reconnect clearing, eliminating the false positive.
 *
 * 60s window is generous enough to cover systemd kill → restart →
 * bridge-reconnect (typically 2–5s) plus the next watchdog tick. After
 * 60s, any further NRestarts increment is genuinely unexpected.
 */
let lastPlannedRestartAt: number | null = null
const PLANNED_RESTART_FRESHNESS_MS = 60_000

function restartMarkerPath(): string | null {
  const agentDir = resolveAgentDirFromEnv()
  if (!agentDir) return null
  return join(agentDir, 'restart-pending.json')
}
function writeRestartMarker(marker: RestartMarker): void {
  const p = restartMarkerPath(); if (!p) return
  try {
    writeFileSync(p, JSON.stringify(marker))
    lastPlannedRestartAt = Date.now()
    process.stderr.write(`telegram gateway: restart-marker: write chat_id=${marker.chat_id} thread_id=${marker.thread_id ?? '-'} ack=${marker.ack_message_id ?? '-'} path=${p}\n`)
  } catch (err) {
    process.stderr.write(`telegram gateway: writeRestartMarker failed: ${err}\n`)
  }
}

/**
 * True when this gateway process initiated a planned restart in the last
 * `PLANNED_RESTART_FRESHNESS_MS`. Used by the restart-watchdog as the
 * authoritative "was this a /restart" signal — see `lastPlannedRestartAt`
 * comment for why the disk marker can't carry this responsibility.
 */
function isPlannedRestartFresh(now: number = Date.now()): boolean {
  if (lastPlannedRestartAt == null) return false
  return now - lastPlannedRestartAt < PLANNED_RESTART_FRESHNESS_MS
}
function readRestartMarker(): RestartMarker | null {
  const p = restartMarkerPath(); if (!p) return null
  try { return JSON.parse(readFileSync(p, 'utf8')) as RestartMarker } catch { return null }
}
function clearRestartMarker(): void {
  const p = restartMarkerPath(); if (!p) return
  try {
    rmSync(p, { force: true })
    process.stderr.write(`telegram gateway: restart-marker: cleared path=${p}\n`)
  } catch {}
}

/**
 * Resolve which Telegram chat should receive the boot card.
 *
 * Fallback chain:
 *   1. restart-pending.json chat_id (if present and fresh)
 *   2. SUBAGENT_OWNER_CHAT_ID env var
 *   3. Most recent inbound from history SQLite
 *   4. null → skip (no known chat)
 *
 * TODO: add test coverage for the history-SQLite fallback path
 */
function resolveBootChatId(
  marker: { chat_id: string; thread_id: number | null; ack_message_id: number | null; ts: number } | null,
  ageMs?: number,
): { chatId: string; threadId: number | undefined; ackMsgId: number | undefined } | null {
  // 1. Restart marker — operator-initiated; honor where they typed
  //    /restart. The marker carries the exact chat+thread context; no
  //    routing override because the user expects to see the boot card
  //    in the same lane where they invoked the restart.
  if (marker != null && (ageMs == null || ageMs < 5 * 60_000)) {
    return {
      chatId: marker.chat_id,
      threadId: marker.thread_id ?? undefined,
      ackMsgId: marker.ack_message_id ?? undefined,
    }
  }

  // For non-marker paths (spontaneous boot, crash recovery, env var,
  // history fallback): supergroup-mode agents route the boot card to
  // the `alerts` alias topic (or default_topic_id fallback) so the
  // operator sees lifecycle events in a predictable lane instead of
  // chat-root. For fleet-mode / DM agents the helper returns undefined
  // → behavior unchanged (lands at chat-root as today). PR4b of
  // supergroup-mode rollout (reference/rfcs/supergroup-mode.md).
  const supergroupBootTopic = resolveAgentOutboundTopic({ kind: 'boot' })
  const bootSupergroup = resolveAgentSupergroupChatId()
  // The boot topic is valid only in the agent's supergroup — attach it per
  // recipient so a DM owner doesn't 400 (marko #2096 class); the supergroup
  // owner gets the boot/alerts lane, a DM gets a thread-less boot card.

  // 2. Env var
  const envChat = process.env.SUBAGENT_OWNER_CHAT_ID
  if (envChat) return { chatId: envChat, threadId: topicForRecipient({ recipientChatId: envChat, resolvedTopic: supergroupBootTopic, supergroupChatId: bootSupergroup }), ackMsgId: undefined }
  // 3. Most-recent inbound from history
  if (HISTORY_ENABLED) {
    try {
      const access = loadAccess()
      const ownerChatId = access.allowFrom[0]
      if (ownerChatId) {
        const recent = queryHistory({ chat_id: ownerChatId, limit: 1 })
        if (recent.length > 0) return { chatId: ownerChatId, threadId: topicForRecipient({ recipientChatId: ownerChatId, resolvedTopic: supergroupBootTopic, supergroupChatId: bootSupergroup }), ackMsgId: undefined }
      }
    } catch {}
  }
  // 4. No known chat
  return null
}

/**
 * Resolve the supergroup-mode topic for an outbound event, or
 * undefined when the agent isn't in supergroup-owned mode. Best-effort
 * — any config-read failure returns undefined and the caller falls
 * through to today's behavior. Generic over every OutboundEvent
 * variant so the same helper backs boot card, compact card, vault,
 * permission, hostd, and watchdog emitters.
 *
 * Called sparingly (boot/reconnect, compaction edges, approval-card
 * dispatch) — not per turn — so the cost of a fresh config-read per
 * call is well within budget.
 */
function resolveAgentOutboundTopic(
  event: Parameters<typeof resolveOutboundTopicHelper>[1],
): number | undefined {
  const agentName = process.env.SWITCHROOM_AGENT_NAME
  if (!agentName) return undefined
  try {
    const cfg = loadSwitchroomConfig()
    const rawAgent = cfg.agents?.[agentName]
    if (!rawAgent) return undefined
    const resolved = resolveAgentConfig(cfg.defaults, cfg.profiles, rawAgent)
    const tg = resolved.channels?.telegram
    if (!tg) return undefined
    // The router treats the absence of default_topic_id as
    // "fleet-mode" and returns undefined for ops-lane events (the
    // caller's existing fallback). Only supergroup-owned agents
    // (with default_topic_id set) get a routed value.
    return resolveOutboundTopicHelper(tg as _OutboundRouterConfig, event)
  } catch {
    return undefined
  }
}

/**
 * The agent's supergroup chat id (`channels.telegram.chat_id`) when it is in
 * supergroup-owned mode, else undefined. A forum topic id resolved by
 * {@link resolveAgentOutboundTopic} is valid ONLY in this chat — used by
 * {@link topicForRecipient} to decide whether an approval/permission card sent
 * to a given recipient (operator DMs vs the supergroup itself) may carry a
 * `message_thread_id`. Attaching a topic to a DM is the marko brevo wedge
 * (2026-06-02): the card fails with "message thread not found" and auto-denies.
 */
function resolveAgentSupergroupChatId(): string | undefined {
  const agentName = process.env.SWITCHROOM_AGENT_NAME
  if (!agentName) return undefined
  try {
    const cfg = loadSwitchroomConfig()
    const rawAgent = cfg.agents?.[agentName]
    if (!rawAgent) return undefined
    const resolved = resolveAgentConfig(cfg.defaults, cfg.profiles, rawAgent)
    const tg = resolved.channels?.telegram as { chat_id?: string | number } | undefined
    return tg?.chat_id != null ? String(tg.chat_id) : undefined
  } catch {
    return undefined
  }
}

/** Whether THIS agent has `channels.telegram.linear_agent.enabled`. Used by the
 *  proactive Linear-auth watch to skip agents that aren't Linear actors. */
function isSelfLinearAgentEnabled(): boolean {
  const agentName = process.env.SWITCHROOM_AGENT_NAME
  if (!agentName) return false
  try {
    const cfg = loadSwitchroomConfig()
    const rawAgent = cfg.agents?.[agentName]
    if (!rawAgent) return false
    const resolved = resolveAgentConfig(cfg.defaults, cfg.profiles, rawAgent)
    const la = (resolved.channels?.telegram as { linear_agent?: { enabled?: boolean } } | undefined)?.linear_agent
    return la?.enabled === true
  } catch {
    return false
  }
}

/**
 * One proactive Linear-auth check for this agent (boot + interval). Reads the
 * refresh bundle via the broker; missing → operator alert, near-expiry →
 * proactive rotate, revoked → operator alert. Best-effort, never throws.
 * Disabled with SWITCHROOM_LINEAR_AUTH_WATCH_POLL_MS=0.
 */
async function runLinearAuthWatch(): Promise<void> {
  const agent = process.env.SWITCHROOM_AGENT_NAME
  if (!agent) return
  const io = brokerRefreshIO(agent)
  const status = await runLinearAuthCheck({
    agent,
    linearEnabled: isSelfLinearAgentEnabled,
    readBundle: io.readBundle,
    refresh: () => performLinearRefresh(io),
    onAuthDead: notifyLinearAuthDead,
    log: (s) => process.stderr.write(s),
  })
  if (status !== 'disabled' && status !== 'fresh') {
    process.stderr.write(`telegram gateway: linear-auth-watch agent=${agent} status=${status}\n`)
  }
}

/**
 * Stamp a user-facing restart reason into the clean-shutdown marker
 * (same file the SIGTERM handler writes to and the next session greeting
 * consumes). Called by /restart, /new, /reset BEFORE the
 * detached `switchroom agent restart …` CLI fires — so the agent-side
 * greeting card shows who asked ("user: /restart from chat") instead of
 * the downstream CLI's "cli: restart" default.
 *
 * Best-effort: if the write fails, the restart still proceeds. The
 * downstream CLI will fall back to its own "cli: restart" marker (the
 * CLI uses preserveExisting to avoid clobbering a fresh user marker).
 */
function stampUserRestartReason(reason: string): void {
  try {
    writeCleanShutdownMarker(GATEWAY_CLEAN_SHUTDOWN_MARKER_PATH, {
      ts: Date.now(),
      signal: 'SIGTERM',
      reason,
    })
    process.stderr.write(`telegram gateway: restart-reason.stamped reason=${JSON.stringify(reason)} path=${GATEWAY_CLEAN_SHUTDOWN_MARKER_PATH}\n`)
  } catch (err) {
    process.stderr.write(`telegram gateway: restart-reason.stamp_failed err=${(err as Error).message}\n`)
  }
}

/**
 * Fire-and-forget a detached `switchroom` CLI invocation.
 *
 * `onFailure`, if provided, is called with the child's exit code and the
 * tail of `detached-spawn.log` when the child exits non-zero BEFORE
 * ~5 seconds have passed (the rough window during which the gateway is
 * still alive and hasn't yet been SIGTERM'd by its own restart). This
 * lets us surface "agent not found in switchroom.yaml" and other
 * fail-fast CLI errors to the Telegram user instead of silently
 * swallowing them into detached-spawn.log.
 */
/**
 * Detect whether `systemd-run --user` is callable. Cached for the
 * process lifetime — the answer is essentially fixed by the host OS.
 *
 * When available, `spawnSwitchroomDetached` wraps every spawn through
 * `systemd-run --user --scope --collect` so the spawned child escapes
 * the gateway's cgroup. Without this escape, restarting the gateway
 * cgroup-kills the in-flight child mid-restart, and the agent service
 * never actually restarts (#177).
 *
 * `--scope` makes a transient scope unit (lives in its own cgroup,
 * doesn't trigger the spawn-supervised semantics of `--service`).
 * `--collect` auto-removes the unit when it exits so we don't
 * accumulate transient units.
 */
let _systemdRunPath: string | null | undefined
function resolveSystemdRunPath(): string | null {
  if (_systemdRunPath !== undefined) return _systemdRunPath
  // Try `command -v systemd-run` via execSync; on missing-binary or
  // a non-systemd box we set null and fall back to direct spawn.
  try {
    const out = execSync('command -v systemd-run 2>/dev/null', { encoding: 'utf-8' }).trim()
    _systemdRunPath = out.length > 0 ? out : null
  } catch {
    _systemdRunPath = null
  }
  return _systemdRunPath
}

/**
 * PR5 — supergroup-mode slash-command smart split (CPO #4 design).
 *
 * Classifies a slash-command response by event class and returns the
 * `message_thread_id` an outbound reply should target in supergroup
 * mode, or `undefined` when the agent isn't in supergroup-owned mode
 * (caller falls through to grammY's default `ctx.reply` which
 * routes to the originating topic).
 *
 * Three classes:
 *   - `query` (`/help`, `/status`, etc.) — follows the originating
 *     topic, identical to default `ctx.reply` behaviour.
 *   - `mutation` (`/restart`, `/update apply`) — admin alias.
 *   - `heavy` (`/logs`, `/audit`, `/upgradestatus`, `/memory <q>`)
 *     — admin alias (operational separation per CPO #4).
 *
 * Callers spread the returned topic onto their send opts:
 *
 *   await ctx.reply(text, {
 *     ...opts,
 *     ...slashCommandReplyOpts(ctx, 'heavy'),
 *   })
 *
 * Returns `{}` when no override is needed (non-supergroup, or
 * helper resolved to the originating topic). Returns
 * `{ message_thread_id: N }` otherwise.
 */
function slashCommandReplyOpts(
  ctx: Context,
  classification: 'query' | 'mutation' | 'heavy',
): { message_thread_id?: number } {
  const originThreadId = ctx.message?.message_thread_id
  const event =
    classification === 'query'
      ? ({ kind: 'command-query', originThreadId } as const)
      : classification === 'mutation'
        ? ({ kind: 'command-mutation' } as const)
        : ({ kind: 'command-heavy' } as const)
  const target = resolveAgentOutboundTopic(event)
  if (target == null) return {}
  // Avoid the spurious explicit thread_id when it would equal the
  // implicit-reply destination — keeps the wire identical to default
  // ctx.reply for the query class in supergroup mode.
  if (target === originThreadId) return {}
  return { message_thread_id: target }
}

/**
 * Detect whether `docker` is callable from this process — required by
 * `switchroom update`'s pull-images and recreate-containers steps.
 *
 * The gateway runs INSIDE the agent container (cron-fold-in / Phase 4
 * docker model), which by design has no docker binary AND no socket
 * mount. We probe both: binary on PATH (via `docker --version`) and
 * socket on disk (via existsSync). True only if BOTH are present —
 * mirroring the actual requirements `switchroom update` will hit when
 * it shells out.
 *
 * Cached: docker availability doesn't change at runtime within a
 * single container generation.
 */
let _dockerReachable: boolean | undefined
function isDockerReachable(): boolean {
  if (_dockerReachable !== undefined) return _dockerReachable
  // Cheap socket probe first — if the mount is absent, no need to
  // pay the execSync cost. Common-case fast-path on docker installs.
  if (!existsSync('/var/run/docker.sock')) {
    _dockerReachable = false
    return _dockerReachable
  }
  try {
    // -version is fast and doesn't require an actual daemon roundtrip
    // for binary-present probing. Bounded timeout in case the binary
    // exists but blocks (unlikely but defensive).
    execSync('docker --version', { stdio: 'ignore', timeout: 2000 })
    _dockerReachable = true
  } catch {
    _dockerReachable = false
  }
  return _dockerReachable
}

// @internal exported for tests — resets the docker-reachable cache so
// a test can swap underlying state and observe the new probe result.
export function _resetDockerReachableCache(): void {
  _dockerReachable = undefined
}

// hostd dispatch lives in `hostd-dispatch.ts` (extracted for testability).
// Re-export the cache-reset so existing test patterns that reach into
// gateway.ts for `_resetDockerReachableCache` find a parallel hook.
export { _resetHostdEnabledCache }

function spawnSwitchroomDetached(
  args: string[],
  onFailure?: (info: { code: number; tail: string }) => void,
): void {
  const fullArgs = SWITCHROOM_CONFIG ? ['--config', SWITCHROOM_CONFIG, ...args] : args
  const logPath = join(STATE_DIR, 'detached-spawn.log')
  let outFd: number | null = null
  try {
    mkdirSync(STATE_DIR, { recursive: true })
    outFd = openSync(logPath, 'a')
    writeFileSync(logPath, `\n[${new Date().toISOString()}] spawn ${SWITCHROOM_CLI} ${fullArgs.join(' ')}\n`, { flag: 'a' })
  } catch {}
  // Escape the gateway's cgroup via systemd-run --scope when available.
  // Without this, a gateway service restart (e.g. triggered as part of
  // the detached child's own work) cgroup-kills the child mid-flight.
  // See #177.
  const systemdRun = resolveSystemdRunPath()
  const spawnBin = systemdRun ?? SWITCHROOM_CLI
  const spawnArgs = systemdRun
    ? ['--user', '--scope', '--collect', '--quiet', '--', SWITCHROOM_CLI, ...fullArgs]
    : fullArgs
  const child = spawn(spawnBin, spawnArgs, {
    detached: true,
    stdio: outFd != null ? ['ignore', outFd, outFd] : 'ignore',
    env: { ...process.env, FORCE_COLOR: '0', NO_COLOR: '1' },
  })
  if (outFd != null) { try { closeSync(outFd) } catch {} }

  if (onFailure) {
    const started = Date.now()
    child.on('exit', (code) => {
      // Only surface "obvious-fail" exits — non-zero within 5 seconds.
      // A successful restart kills us before we'd ever see the exit
      // event, so any exit we DO observe here is almost certainly
      // fail-fast (bad agent name, bad args, missing config).
      if (code == null || code === 0) return
      if (Date.now() - started > 5000) return
      let tail = ''
      try {
        const full = readFileSync(logPath, 'utf8')
        tail = full.split('\n').slice(-30).join('\n').trim()
      } catch { /* best effort */ }
      try { onFailure({ code, tail }) } catch (err) {
        process.stderr.write(`telegram gateway: spawn onFailure handler threw: ${err}\n`)
      }
    })
    child.on('error', (err) => {
      try { onFailure({ code: -1, tail: String(err) }) } catch { /* ignore */ }
    })
  }

  child.unref()
}

/**
 * Build an `onFailure` handler that posts a user-facing error reply back
 * to the Telegram chat when a detached `switchroom` child fails fast.
 * Also clears the restart marker so the "🎛️ restarted — ready" follow-up
 * doesn't get stuck forever.
 */
function notifyDetachedFailure(
  chatId: string,
  threadId: number | null,
  label: string,
): (info: { code: number; tail: string }) => void {
  return ({ code, tail }) => {
    clearRestartMarker()
    const snippet = tail ? tail.slice(-800) : '(no output captured)'
    const text =
      `❌ **${escapeHtmlForTg(label)} failed** (exit ${code}):\n` +
      preBlock(snippet)
    // Fire-and-forget — we're off the command-handler context and don't
    // have an await to block on anyway.
    // #1075: thread-id-bearing, fire-and-forget — swallow on
    // THREAD_NOT_FOUND so a deleted topic doesn't crash the detached-
    // failure handler.
    void swallowingApiCall(
      () =>
        lockedBot.api.sendRichMessage(chatId, richMessage(text), {
          // Detached restart/update child-failure notice — status, not
          // the user's answer. Silence the open ping.
          disable_notification: true,
          ...(threadId != null ? { message_thread_id: threadId } : {}),
        }),
      {
        chat_id: chatId,
        verb: 'notifyDetachedFailure',
        ...(threadId != null ? { threadId } : {}),
      },
    )
  }
}

async function sweepBeforeSelfRestart(): Promise<void> {
  const agentDir = resolveAgentDirFromEnv()
  if (agentDir == null) return
  // #1122 PR3: pre-restart progress-card pin sweep removed with the card.
  // Status-pin: unpin every status pin we own before we hand control to the
  // restart, so a crash / interrupt / config-bounce never leaves a permanent
  // pin stuck at the top of the chat. Best-effort; the drop-on-unpin contract
  // clears the claim even if the API throws.
  try {
    await unpinAllStatusPins()
  } catch (err) {
    process.stderr.write(`telegram gateway: pre-restart status-pin sweep threw: ${(err as Error).message}\n`)
  }
  try {
    await sweepActiveReactions(
      agentDir,
      (chatId, messageId) => lockedBot.api.setMessageReaction(chatId, messageId, [{ type: 'emoji', emoji: '👍' as ReactionTypeEmoji['emoji'] }]),
      { log: (msg) => process.stderr.write(`telegram gateway: pre-restart reaction sweep — ${msg}\n`) },
    )
  } catch (err) {
    process.stderr.write(`telegram gateway: pre-restart reaction sweep threw: ${(err as Error).message}\n`)
  }
}

/**
 * Schedule a marker-safe, turn-deferred SELF-restart so a just-persisted
 * config change ACTUALLY takes effect. claude loads tools / MCP servers /
 * settings at process start, so a durable "Always allow" write is inert in
 * the running session until the next restart — the old "restart agent for
 * full effect" text asked the operator to do this by hand, and most never
 * did (so the grant didn't stick and the same prompt reappeared). This
 * completes the flow the operator already approved.
 *
 * CALLER-AGENT ONLY (an "Always allow" edits the calling agent's own
 * `agents.<self>.tools.allow`, a provably single-agent blast radius). The
 * restart fires when the CURRENT turn completes (via `pendingRestarts`),
 * never mid-turn — so the operator-approved action finishes first. If no
 * turn is in flight, it fires immediately after a short drain delay. A
 * marker is written first so the post-restart greeting lands in the chat
 * the operator tapped. Kill-switch: `SWITCHROOM_AUTORESTART_ON_GRANT=0`.
 *
 * Returns 'disabled' | 'deferred' | 'now'.
 */
function scheduleGrantRestart(
  agentName: string,
  chatId: string | number | undefined,
  threadId: number | undefined,
  reason: string,
): GrantRestartDecision {
  const decision = grantRestartDecision({
    killSwitch: process.env.SWITCHROOM_AUTORESTART_ON_GRANT,
    selfAgent: process.env.SWITCHROOM_AGENT_NAME,
    agentName,
    turnInFlight: turnInFlightForGate(),
  })
  if (decision === "disabled") return decision
  // Marker first → the post-restart greeting lands in the chat the operator
  // tapped, not the default operator DM.
  if (chatId != null) {
    writeRestartMarker({ chat_id: String(chatId), thread_id: threadId ?? null, ack_message_id: null, ts: Date.now() })
  }
  stampUserRestartReason(reason)
  if (decision === "deferred") {
    pendingRestarts.set(agentName, Date.now()) // fires at turn-complete (marker-safe)
  } else {
    // No turn to drain — restart now, after a short delay so this callback's
    // card edit flushes first.
    void sweepBeforeSelfRestart().finally(() => triggerSelfRestart(agentName, reason, 1500))
  }
  return decision
}

/**
 * Shape the `switchroom auth ...` CLI stdout into a Telegram-friendly
 * HTML block. Returns the body text AND the OAuth authorize URL (if
 * one was present in the output) so the caller can wire a tappable
 * InlineKeyboardButton in addition to the inline link.
 *
 * The URL-in-text is kept on its own line at the bottom as a fallback:
 * if the inline button ever fails to render (old client, unusual scope)
 * the user still has a copy-paste-able URL.
 */
function formatAuthOutputForTelegram(output: string): { text: string; url: string | null } {
  const trimmed = stripAnsi(output).trim()
  const url = trimmed.match(/https:\/\/\S+/)?.[0] ?? null
  const lines = trimmed.split(/\n+/).map(l => l.trim()).filter(Boolean)
  if (!url) return { text: preBlock(formatSwitchroomOutput(trimmed)), url: null }
  // Drop the `switchroom auth code ...` and `switchroom auth cancel ...`
  // CLI hints. In Telegram the user never types those — they just reply
  // with the code (intercepted by the pendingReauthFlows flow above) or
  // tap the inline button. Surfacing shell syntax is confusing noise on
  // a phone.
  const body = lines.filter(line => {
    if (line === url) return false
    if (line.startsWith('switchroom auth code')) return false
    if (line.startsWith('switchroom auth cancel')) return false
    if (line.startsWith("Use 'tmux attach")) return false
    if (line.startsWith('After Claude shows you a browser code')) return false
    if (line.startsWith('Then finish with:')) return false
    if (line.startsWith('Cancel with:')) return false
    return true
  })
  const rendered = body.map(line => {
    if (line.startsWith('Started Claude auth') || line.startsWith('Auth session already running')) return `**${escapeHtmlForTg(line)}**`
    if (line.startsWith('Open this URL')) return `_${escapeHtmlForTg(line)}_`
    return escapeHtmlForTg(line)
  })
  // Mobile-native post-script. Two paths depending on which Anthropic
  // account the user wants to authorize:
  //
  //   (a) Button: 🔐 Open Claude auth — opens in Telegram's in-app
  //       browser (WebView) on most mobile clients. WebView has its
  //       own cookie jar, separate from the user's main browser. Fine
  //       when the WebView is already signed into the intended Claude
  //       account; wrong when it's signed into a different one.
  //
  //   (b) Long-press the URL text at the bottom of this message — every
  //       mobile Telegram client exposes "Copy Link" / "Open in
  //       Browser" / "Open in Chrome" on long-press. That's the
  //       escape hatch when you need to land in your main browser
  //       where you control which account is signed in.
  //
  // Why not a copy_text button? We tried. Telegram's CopyTextButton.text
  // field caps at 256 chars and OAuth URLs run ~320–340 chars. Result
  // was BUTTON_COPY_TEXT_INVALID. The long-press-the-URL path achieves
  // the same outcome with no API constraint. See PR #30.
  rendered.push(
    '',
    '👇 Tap **🔐 Open Claude auth** below, then **reply with the browser code**.',
    '',
    '_Wrong Anthropic account getting authorized? Long-press the URL below and choose "Copy Link" or "Open in Browser" — lands in your main browser where the right account is signed in, bypassing Telegram\'s in-app browser cookies._',
    '',
    url,
  )
  return { text: rendered.join('\n'), url }
}

/**
 * Build the inline keyboard shown under an auth-flow response that has
 * an OAuth URL. Single button:
 *
 *   [🔐 Open Claude auth]   — `url` button. On mobile Telegram clients
 *                             this typically opens in the app's in-app
 *                             browser (WebView).
 *
 * We previously tried adding a `[📋 Copy URL]` button using Telegram's
 * Bot API 7.7 `copy_text` type but it capped at 256 chars for the
 * copyable text. OAuth URLs (~320–340 chars) exceed that and produce
 * `BUTTON_COPY_TEXT_INVALID`. Instead, the message body renders the
 * URL as a tappable link; users long-press the URL text to get native
 * "Copy Link" / "Open in Browser" actions, bypassing the WebView.
 *
 * Defense in depth: this function's output is validated against
 * Telegram's real field-length constraints in
 * `telegram-plugin/tests/auth-url-keyboard-constraints.test.ts` so
 * future changes that breach a limit fail loudly at CI time rather
 * than silently in production.
 */
function buildAuthUrlKeyboard(authorizeUrl: string): InlineKeyboard {
  return new InlineKeyboard().url('🔐 Open Claude auth', authorizeUrl)
}

/**
 * Issue #44: inline keyboard offering a one-tap unlock-and-save flow for
 * a deferred secret. The two buttons fire `vd:` callback_data which the
 * dispatcher in `bot.on('callback_query:data')` routes to
 * `handleVaultDeferCallback`.
 *
 *   `vd:unlock:<deferKey>` → prompt for passphrase, then auto-write the
 *                            held secret. Replaces the legacy six-step
 *                            "/vault list → re-paste" flow.
 *   `vd:cancel:<deferKey>` → discard the deferred secret without saving.
 *
 * `deferKey` is `<chat_id>:<message_id>` (the same key as
 * `deferredSecrets.set()`). Telegram limits callback_data to 64 bytes;
 * the prefix + key fits well within that on any realistic chat id.
 */
function buildDeferredSecretKeyboard(deferKey: string): InlineKeyboard {
  const unlockData = `vd:unlock:${deferKey}`
  const cancelData = `vd:cancel:${deferKey}`
  if (unlockData.length > 64 || cancelData.length > 64) {
    process.stderr.write(
      `telegram gateway: callback_data overflow — deferKey=${deferKey} unlockLen=${unlockData.length} cancelLen=${cancelData.length}\n`,
    )
    throw new Error(`callback_data overflow: deferKey too long (${deferKey.length} chars)`)
  }
  return new InlineKeyboard()
    .text('🔓 Unlock vault & save', unlockData)
    .text('🗑 Discard', cancelData)
}

async function runSwitchroomAuthCommand(ctx: Context, args: string[], label: string): Promise<void> {
  try {
    const output = switchroomExecCombined(args, 30000)
    const formatted = formatAuthOutputForTelegram(output)
    const keyboard = formatted.url ? buildAuthUrlKeyboard(formatted.url) : undefined
    await switchroomReply(ctx, formatted.text, { html: true, reply_markup: keyboard })
    // If this flow produced an OAuth URL, follow up with a ForceReply
    // prompt so Telegram's text-input bar shows a "Paste browser code"
    // placeholder. The user's next message (whether they 'reply' to
    // this explicitly or just type) is auto-captured by the existing
    // pendingReauthFlows intercept in the inbound-message handler.
    if (formatted.url) {
      // Channel B context rule: arm unconditionally — record that this chat
      // is awaiting an auth code paste so the inbound handler can treat the
      // next message as auth-flow-sensitive even if the pattern rule misses
      // it. Set BEFORE the ForceReply attempt so a switchroomReply throw
      // doesn't leave Channel B unarmed.
      const authChatId = String(ctx.chat!.id)
      awaitingAuthCodeAt.set(authChatId, Date.now())
      try {
        await switchroomReply(ctx, '📋 Paste the browser code here ↓', {
          reply_markup: { force_reply: true, input_field_placeholder: 'Paste browser code', selective: true },
        })
      } catch {
        // ForceReply is UX garnish — if it fails the flow still works
        // via the pending-intercept. Don't escalate.
      }
    }
  } catch (err: unknown) {
    const error = err as { status?: number; stderr?: string; message?: string }
    if (error.message?.includes('ENOENT')) { await switchroomReply(ctx, 'switchroom CLI not found.', { html: true }); return }
    if (error.message?.includes('ETIMEDOUT') || error.message?.includes('timed out')) { await switchroomReply(ctx, `${label}: timed out`); return }
    const detail = stripAnsi(error.stderr?.trim() || error.message || 'unknown error')
    await switchroomReply(ctx, `**${escapeHtmlForTg(label)} failed:**\n${preBlock(formatSwitchroomOutput(detail))}`, { html: true })
  }
}

function runVaultCli(args: string[], passphrase: string, stdinValue?: string): { ok: boolean; output: string } {
  // Suppress the #969 P3 deprecation warning on this per-spawn
  // invocation. The gateway forwarding the operator's passphrase to
  // the CLI (which in turn forwards it to the broker as the canonical
  // P1a passphrase-attestation) is intended; without this silencer the
  // warning would surface in error pre-blocks shown to the user.
  const env = {
    ...process.env,
    SWITCHROOM_VAULT_PASSPHRASE: passphrase,
    SWITCHROOM_NO_VAULT_DEPRECATION_WARNING: '1',
  }
  try {
    let result: string
    if (stdinValue !== undefined) {
      result = execFileSync(process.env.SWITCHROOM_CLI_PATH ?? 'switchroom', ['vault', ...args], { input: stdinValue, encoding: 'utf8', env, timeout: 10000 })
    } else {
      result = execFileSync(process.env.SWITCHROOM_CLI_PATH ?? 'switchroom', ['vault', ...args], { encoding: 'utf8', env, timeout: 10000 })
    }
    return { ok: true, output: result.trim() }
  } catch (err: unknown) {
    const e = err as { stdout?: string; stderr?: string; message?: string }
    return { ok: false, output: [e.stdout, e.stderr, e.message].filter(Boolean).join('\n').trim() }
  }
}

/**
 * Render a vault-CLI failure as Telegram HTML. Routes recognised P0a
 * stderr markers (VAULT-SANDBOX-CONTEXT / VAULT-NEEDS-APPROVAL /
 * VAULT-BROKER-UNREACHABLE / VAULT-BROKER-DENIED) through the structured
 * renderer; falls back to a raw pre-block for anything else.
 */
function renderVaultOpFailure(
  verbLabel: 'list' | 'get' | 'set' | 'delete',
  cliOutput: string,
  key: string | undefined,
): string {
  const parsed = parseVaultCliError(cliOutput)
  // Map the gateway-internal op label onto the renderer's verb. 'delete'
  // surfaces in the host hint as `switchroom vault remove <key>` (the
  // canonical CLI name); 'list' has no key.
  const verb = verbLabel === 'delete' ? 'remove' : verbLabel
  const rendered = renderVaultCliError(parsed, { verb, key })
  if (rendered.suppressRaw) return rendered.html
  return `**vault ${verbLabel} failed:**\n${preBlock(cliOutput)}`
}

async function executeVaultOp(ctx: Context, chatId: string, op: 'list' | 'get' | 'set' | 'delete', key: string | undefined, passphrase: string, setValue: string | undefined): Promise<void> {
  if (op === 'list') {
    const r = runVaultCli(['list'], passphrase)
    if (!r.ok) { await switchroomReply(ctx, renderVaultOpFailure('list', r.output, undefined), { html: true }); return }
    const keys = r.output.split('\n').filter(Boolean)
    if (keys.length === 0) { await switchroomReply(ctx, 'Vault is empty.', { html: true }) }
    else { await switchroomReply(ctx, `**Vault keys (${keys.length}):**\n${keys.map(k => `• \`${k}\``).join('\n')}`, { html: true }) }
  } else if (op === 'get') {
    const r = runVaultCli(['get', key!], passphrase)
    if (!r.ok) { await switchroomReply(ctx, renderVaultOpFailure('get', r.output, key), { html: true }); return }
    await switchroomReply(ctx, `\`${key!}\` =\n\`${r.output}\``, { html: true })
  } else if (op === 'set') {
    if (setValue === undefined) {
      pendingVaultOps.set(chatId, { kind: 'value', op: 'set', key: key!, passphrase, startedAt: Date.now() })
      await switchroomReply(ctx, `Send the value for \`${key!}\`.`, { html: true })
      return
    }
    const r = runVaultCli(['set', key!], passphrase, setValue)
    if (!r.ok) { await switchroomReply(ctx, renderVaultOpFailure('set', r.output, key), { html: true }) }
    else { await switchroomReply(ctx, `✅ \`${key!}\` saved to vault.`, { html: true }) }
  } else if (op === 'delete') {
    const r = runVaultCli(['remove', key!], passphrase)
    if (!r.ok) { await switchroomReply(ctx, renderVaultOpFailure('delete', r.output, key), { html: true }) }
    else { await switchroomReply(ctx, `✅ \`${key!}\` removed from vault.`, { html: true }) }
  }
}

/**
 * Dispatch a short-running verb (agent_start, agent_stop, cross-agent
 * agent_restart) through hostd when available, else fall back to the
 * legacy in-container CLI shell-out.
 *
 * Why: on docker-mode hosts the agent container has no docker binary,
 * so the legacy `runSwitchroomCommand` path silently exits 127 for any
 * verb that touches compose (RFC C §1, #926). Hostd runs on the host
 * with the docker socket mounted, so the verb actually works.
 *
 * Result handling:
 *   - `not-configured` → fall back to {@link runSwitchroomCommand}.
 *     (Operator opted out; let the legacy path's existing error
 *     surfacing handle the exit-127 case.)
 *   - `completed` → reply with the stdout tail (mirrors the legacy
 *     path's formatted-output reply).
 *   - `started`   → reply with a brief "🔄 dispatched" ack. Verbs that
 *     return `started` (agent_restart) finish asynchronously on the
 *     daemon; the audit log is the canonical record.
 *   - `error` / `denied` → reply with the error tail inline. No
 *     fallback (RFC §7 hard-fail contract — operator opted in).
 */
async function dispatchShortVerbViaHostd(
  ctx: Context,
  req: HostdRequest,
  label: string,
  legacyArgs: string[],
): Promise<void> {
  const hostdResp = await tryHostdDispatch(getMyAgentName(), req)
  if (hostdResp === 'not-configured') {
    warnLegacySpawnIfHostdDisabled(req.op)
    await runSwitchroomCommand(ctx, legacyArgs, label)
    return
  }
  if (hostdResp.result === 'completed') {
    const body = hostdResp.stdout_tail?.trim() || `${label}: done (exit ${hostdResp.exit_code})`
    const formatted = formatSwitchroomOutput(stripAnsi(body))
    if (formatted) {
      await switchroomReply(ctx, preBlock(formatted), { html: true })
    } else {
      await switchroomReply(ctx, `${label}: done (no output)`)
    }
    return
  }
  if (hostdResp.result === 'started') {
    await switchroomReply(
      ctx,
      `🔄 **${escapeHtmlForTg(label)}** dispatched via hostd ` +
        `(request_id=\`${hostdResp.request_id}\`). ` +
        `Check audit log for completion.`,
      { html: true },
    )
    return
  }
  // error / denied — surface inline. RFC §7 hard-fail: no spawn fallback.
  const errBody =
    hostdResp.error ??
    hostdResp.stderr_tail ??
    hostdResp.stdout_tail ??
    '(no error tail returned)'
  await switchroomReply(
    ctx,
    `❌ **${escapeHtmlForTg(label)} failed via hostd** ` +
      `(result=${escapeHtmlForTg(hostdResp.result)}):\n` +
      preBlock(stripAnsi(errBody)),
    { html: true },
  )
}

async function runSwitchroomCommand(
  ctx: Context,
  args: string[],
  label: string,
  // PR5 — supergroup-mode classification threaded through to
  // switchroomReply. Default 'query' so existing callers (most
  // commands) preserve in-place reply behavior. /logs /audit
  // /upgradestatus /memory pass 'heavy' to route to admin alias.
  classification: 'query' | 'mutation' | 'heavy' = 'query',
): Promise<void> {
  try {
    const output = stripAnsi(switchroomExec(args))
    const formatted = formatSwitchroomOutput(output)
    if (formatted) { await switchroomReply(ctx, preBlock(formatted), { html: true, classification }) }
    else { await switchroomReply(ctx, `${label}: done (no output)`, { classification }) }
  } catch (err: unknown) {
    const error = err as { status?: number; stderr?: string; message?: string }
    if (error.message?.includes('ENOENT')) { await switchroomReply(ctx, 'switchroom CLI not found.', { html: true, classification }); return }
    if (error.message?.includes('ETIMEDOUT') || error.message?.includes('timed out')) { await switchroomReply(ctx, `${label}: timed out`, { classification }); return }
    const detail = stripAnsi(error.stderr?.trim() || error.message || 'unknown error')
    await switchroomReply(ctx, `**${escapeHtmlForTg(label)} failed:**\n${preBlock(formatSwitchroomOutput(detail))}`, { html: true, classification })
  }
}

function switchroomExecJson<T = unknown>(args: string[]): T | null {
  try {
    const output = switchroomExec([...args, '--json'])
    return JSON.parse(stripAnsi(output)) as T
  } catch { return null }
}

function statusIcon(status: string): string {
  if (status === 'active' || status === 'running') return '🟢'
  if (status === 'inactive' || status === 'stopped' || status === 'dead') return '🔴'
  if (status === 'failed') return '⚠️'
  return '⚪'
}

/**
 * Render an `AuthCodeOutcome` as a user-facing Telegram HTML string.
 * Returns null when the outcome is not present or is `success` (caller
 * can handle success via the existing text path).
 */
function renderAuthCodeOutcome(outcome: AuthCodeOutcome | null | undefined): string | null {
  if (!outcome || outcome.kind === 'success') return null
  const tail = outcome.paneTailText
    ? `\n_${escapeHtmlForTg(outcome.paneTailText)}_`
    : ''
  switch (outcome.kind) {
    case 'invalid-code':
    case 'expired-code':
      return `Code rejected by Claude — tap **Restart flow** for a fresh URL.${tail}`
    case 'pane-not-ready':
      return `Auth pane not ready — tap **Retry**.`
    case 'timeout':
      return `Still waiting after 2 min — tap **Retry** or check \`switchroom auth list\`.${tail}`
  }
}

interface AuthCodeJsonResult {
  completed: boolean
  tokenSaved: boolean
  tokenPath: string | null
  outcome: AuthCodeOutcome | null
  instructions: string[]
}

/**
 * Run `switchroom auth code <agent> <code> --json` with a 150 s timeout
 * (allows for the full 120 s poll budget + startup overhead).
 *
 * Returns the parsed `AuthCodeJsonResult`, or null on exec failure.
 * On exec failure, `errorText` holds a formatted error string for the caller.
 */
function execAuthCode(
  agent: string,
  code: string,
): { result: AuthCodeJsonResult; errorText: null } | { result: null; errorText: string } {
  try {
    const output = switchroomExec(['auth', 'code', agent, code, '--json'], 150_000)
    const parsed = JSON.parse(stripAnsi(output)) as AuthCodeJsonResult
    return { result: parsed, errorText: null }
  } catch (err: unknown) {
    const error = err as { stderr?: string; stdout?: string; message?: string }
    // `auth code` exits 0 even on timeout/failure (it prints instructions).
    // However if the process itself fails (ENOENT, killed, etc.) we land here.
    // Try to salvage a JSON body from stdout if present.
    const rawOut = error.stdout ?? ''
    if (rawOut.trim().startsWith('{')) {
      try {
        const parsed = JSON.parse(stripAnsi(rawOut)) as AuthCodeJsonResult
        return { result: parsed, errorText: null }
      } catch { /* fall through */ }
    }
    const detail = stripAnsi(error.stderr?.trim() || error.message || 'unknown error')
    return { result: null, errorText: detail }
  }
}

async function runSwitchroomCommandFormatted(ctx: Context, args: string[], label: string, formatter: () => string | null): Promise<void> {
  try {
    const formatted = formatter()
    if (formatted) { await switchroomReply(ctx, formatted, { html: true }); return }
    await runSwitchroomCommand(ctx, args, label)
  } catch (err: unknown) {
    const error = err as { stderr?: string; message?: string }
    const detail = stripAnsi(error.stderr?.trim() || error.message || 'unknown error')
    await switchroomReply(ctx, `**${escapeHtmlForTg(label)} failed:**\n${preBlock(formatSwitchroomOutput(detail))}`, { html: true })
  }
}

// ─── Admin-command gating middleware ─────────────────────────────────────
// When AGENT_ADMIN=false (default), admin slash commands (/agents, /logs,
// /grant, etc.) must NOT execute locally — this agent isn't admin-flagged
// and routing them through Claude burns tokens for no benefit. Reply with a
// concise "admin required" warning instead.
//
// Special case: `/restart` with no arg, or `/restart <my-agent-name>`, is
// allowed to fall through to the local bot.command('restart', …) handler so
// every agent can self-restart without admin privilege. `/restart <other>`
// is blocked just like any other admin verb.
//
// sec WS7-F2 (#1394): when AGENT_ADMIN=true this middleware is NO LONGER a
// no-op — a `block`-classified verb (fleet-admin / `/restart <other>`)
// requires OPERATOR-PRIVATE (a private chat from a strict
// `access.allowFrom` sender), because the per-command `isAuthorizedSender`
// gate treats an empty group `allowFrom` as "allow every member". Non-
// admin-verb traffic (`pass-through`, incl. `/restart`-self and all normal
// chat) is untouched and reaches `next()` exactly as before.
bot.use(async (ctx, next) => {
  if (ctx.message?.text) {
    const myName = getMyAgentName()
    const decision = classifyAdminGate(ctx.message.text, myName)
    if (decision.action === 'block') {
      // `block` = a fleet-admin verb (ADMIN_COMMAND_NAMES) or
      // `/restart <other-agent>`. classifyAdminGate already lets
      // `/restart`-self and every non-admin command pass through, so
      // this branch is exactly the privileged set.
      const cmdHtml = escapeHtmlForTg(`/${decision.cmd}`)
      const nameHtml = escapeHtmlForTg(myName)
      const notFlagged =
        decision.reason === 'other-agent'
          ? `⚠️ \`${cmdHtml}\` targeting another agent is an admin operation — this agent (\`${nameHtml}\`) isn't admin-flagged. Run it from an admin agent, or set \`admin: true\` for this agent in switchroom.yaml. (Self-restart is allowed: send \`/restart\` with no arg.)`
          : `⚠️ \`${cmdHtml}\` is an admin command — this agent (\`${nameHtml}\`) isn't admin-flagged. Run it from an admin agent, or set \`admin: true\` for this agent in switchroom.yaml.`
      if (!AGENT_ADMIN) {
        // Unchanged behaviour: a non-admin agent never executes admin
        // verbs locally and must not forward them to Claude.
        process.stderr.write(
          `telegram gateway: admin-gate blocked cmd=/${decision.cmd} agent=${process.env.SWITCHROOM_AGENT_NAME ?? '-'} reason=${decision.reason} (AGENT_ADMIN=false)\n`,
        )
        await switchroomReply(ctx, notFlagged, { html: true })
        return
      }
      // sec WS7-F2 (#1394): fleet-admin is OPERATOR-PRIVATE. Honor it
      // ONLY in a private chat from an `access.allowFrom` sender.
      // Before this, when AGENT_ADMIN=true the middleware was a no-op
      // and the per-command `isAuthorizedSender` gate treats an empty
      // group `allowFrom` as "allow every member" — so any member of
      // an admin agent's forum/group could run /vault, /update apply,
      // /grant, /dangerous, etc. (the default shape for an agent
      // created via `agent add --topology forum` + `admin: true`).
      // Strict `access.allowFrom` + private-chat-only — never the
      // group-permissive isAuthorizedSender.
      const senderId = String(ctx.from?.id ?? '')
      const operatorPrivate =
        ctx.chat?.type === 'private' &&
        loadAccess().allowFrom.includes(senderId)
      if (!operatorPrivate) {
        process.stderr.write(
          `telegram gateway: admin-gate refused (not operator-private) cmd=/${decision.cmd} agent=${process.env.SWITCHROOM_AGENT_NAME ?? '-'} chat=${ctx.chat?.type ?? '?'} sender=${senderId}\n`,
        )
        await switchroomReply(
          ctx,
          `⚠️ \`${cmdHtml}\` is a fleet-admin command — it is **operator-private**. Send it as a direct message to me from your operator account (a private chat where your Telegram ID is on the access allowlist), not in a group or forum.`,
          { html: true },
        )
        return
      }
      // operator-private admin verb on an admin agent → fall through
      // to the bot.command() handler (which re-checks isAuthorizedSender
      // — redundant but harmless in a private allowFrom chat).
    }
  }
  await next()
})

// ─── Bot commands ─────────────────────────────────────────────────────────

/**
 * Build the optional audit details surfaced on `/status` (Profile, Tools,
 * Skills, Limits, Channel, Memory, Version). Populated from switchroom.yaml
 * at request time so the values reflect the live config.
 *
 * Pre-#142 this content was baked into a SessionStart curl script and
 * pushed on every restart. Now it's pulled on demand via /status (#142
 * PR 3) — server-side render of the same row shape.
 *
 * Best-effort: any failure (yaml unreadable, agent missing, etc.) returns
 * undefined so /status falls back to its previous (auth + uptime + agent
 * name) shape rather than blocking the reply.
 */
/**
 * Issue #969 P2b — read recent broker-denied vault accesses for an
 * agent. Used by `/vault audit <agent>` to surface a one-tap
 * "always allow" button per unique denied key, so the operator can
 * fix a misconfigured cron without editing switchroom.yaml.
 *
 * Thin wrapper over the pure-functional parser in `./recent-denials.ts`
 * which handles the actual parse + filter + group + sort logic and is
 * unit-tested directly.
 */
function readRecentDenialsForAgent(
  agentName: string,
  windowMs: number,
  limit: number,
): RecentDenial[] {
  try {
    const auditPath = join(homedir(), '.switchroom', 'vault-audit.log')
    if (!existsSync(auditPath)) return []
    const raw = readFileSync(auditPath, 'utf8')
    return recentDenialsFromAuditLog(raw, { agentName, windowMs, limit })
  } catch {
    return []
  }
}

function buildAgentAudit(agentName: string): AgentAudit | undefined {
  try {
    const config = loadSwitchroomConfig()
    const agentConfig = config.agents?.[agentName]
    if (!agentConfig) return undefined

    // Tools allowlist — same shape as the deleted greeting:
    //   "all" / first 5 names + "+N more" / "none (default)".
    const allow = agentConfig.tools?.allow
    const tools = allow?.includes('all')
      ? 'all'
      : (allow?.slice(0, 5).join(', ') ?? 'none (default)')
        + ((allow?.length ?? 0) > 5 ? ` +${(allow?.length ?? 0) - 5} more` : '')

    const denyList = agentConfig.tools?.deny
    const toolsDeny = denyList?.length ? denyList.join(', ') : null

    // Skills cap at 6 names + "…+N more" so the row never wraps 4+
    // mobile lines (matches the deleted greeting's behavior).
    const skillsList = agentConfig.skills
    let skills: string | null = null
    if (skillsList?.length) {
      const max = 6
      skills = skillsList.length <= max
        ? skillsList.join(', ')
        : `${skillsList.slice(0, max).join(', ')}, …+${skillsList.length - max} more`
    }

    // Session limits — concatenated idle + max-turns, or "unlimited".
    const session: string[] = []
    if (agentConfig.session?.max_idle) session.push(`idle ${agentConfig.session.max_idle}`)
    if (agentConfig.session?.max_turns) session.push(`${agentConfig.session.max_turns} turns`)
    const limits = session.length ? session.join(', ') : 'unlimited (default)'

    const channel = agentConfig.channels?.telegram?.plugin ?? 'switchroom (default)'
    const memoryBank = agentConfig.memory?.collection ?? `${agentName} (default)`

    return {
      version: formatBootVersion(),
      tools,
      toolsDeny,
      skills,
      limits,
      channel,
      memoryBank,
    }
  } catch {
    // Silent failure — gateway runs in agent dirs without switchroom.yaml
    // path resolution always succeeding. /status falls back gracefully.
    return undefined
  }
}

// Build an AgentMetadata snapshot for the current agent by shelling out
// to `switchroom agent list --json` and `switchroom auth show --json`.
// Best-effort — any missing piece renders as a placeholder in the text
// templates rather than blocking the reply. RFC H retired the per-agent
// `auth status --json` shape; auth state is now derived from the
// broker's fleet-wide `ListStateData` payload via
// `buildAuthSummaryFromBroker`, with billingType pulled from the
// agent's `.claude.json` (the broker doesn't track plan tier).
/**
 * Live session-model override set by the `/model` picker (session-only). Held
 * in gateway memory so it clears on restart, the same point at which claude's
 * session reverts to the configured model — keeping `/status` honest without
 * a persisted store. Null when no session switch is active.
 */
let activeSessionModelOverride: string | null = null

async function buildAgentMetadata(agentName: string): Promise<AgentMetadata> {
  type AgentListResp = {
    agents: Array<{
      name: string; status: string; uptime: string;
      extends?: string | null; template?: string | null;
      topic_name?: string | null; topic_emoji?: string | null;
      model?: string | null;
    }>
  }
  const list = switchroomExecJson<AgentListResp>(['agent', 'list'])
  const brokerState = switchroomExecJson<BrokerStateView>(['auth', 'show'])
  const a = list?.agents?.find(x => x.name === agentName) ?? null
  let claudeJson: ClaudeJsonView | null = null
  try {
    const agentDir = resolveAgentDirFromEnv()
    if (agentDir) {
      const raw = readFileSync(join(agentDir, '.claude', '.claude.json'), 'utf8')
      claudeJson = JSON.parse(raw) as ClaudeJsonView
    }
  } catch { /* leave null — billingType becomes null in the summary */ }
  const authSummary: AuthSummary | null = buildAuthSummaryFromBroker(
    brokerState,
    agentName,
    claudeJson,
  )
  return {
    agentName,
    model: a?.model ?? null,
    sessionModel: activeSessionModelOverride,
    extendsProfile: (a?.extends ?? a?.template) ?? null,
    topicName: a?.topic_name ?? null,
    topicEmoji: a?.topic_emoji ?? null,
    uptime: a?.uptime ?? null,
    status: a?.status ?? null,
    auth: authSummary,
    audit: buildAgentAudit(agentName),
    live: await buildLiveProbeRows(agentName),
  }
}

/**
 * Run the boot-card probe set on demand for `/status`. Same probes,
 * different rendering contract: `/status` shows every row (silent-when-
 * healthy is for the boot card; the user explicitly asked for current
 * state here). Failures are swallowed per-probe via runAllProbes's
 * Promise.allSettled, and we filter out anything we couldn't render so
 * the reply doesn't break on a broken probe.
 */
async function buildLiveProbeRows(agentName: string): Promise<StatusProbeRow[]> {
  try {
    const { runAllProbes } = await import('./boot-card.js')
    const agentDir = resolveAgentDirFromEnv()
      ?? (process.env.TELEGRAM_STATE_DIR
        ? require('path').dirname(process.env.TELEGRAM_STATE_DIR)
        : '/tmp')
    const probes = await runAllProbes({
      agentName,
      agentSlug: agentName,
      version: formatBootVersion(),
      agentDir,
      gatewayInfo: { pid: process.pid, startedAtMs: GATEWAY_STARTED_AT_MS },
      tmuxSupervisor: process.env.SWITCHROOM_TMUX_SUPERVISOR === '1',
      dockerMode: process.env.SWITCHROOM_RUNTIME === 'docker',
      probeQuotaViaBroker: (t) => probeQuotaForBootCard(agentName, t),
    })
    const rows: StatusProbeRow[] = []
    // Render order matches the boot card's PROBE_KEYS so the two
    // surfaces tell the same story in the same order.
    const order = ['account', 'agent', 'gateway', 'quota', 'hindsight',
      'scheduler', 'broker', 'kernel', 'skills', 'connections'] as const
    for (const k of order) {
      const r = probes[k]
      if (!r) continue
      rows.push({ status: r.status, label: r.label, detail: r.detail })
    }
    return rows
  } catch (err: unknown) {
    process.stderr.write(
      `telegram gateway: /status: probe gathering failed: ${
        (err as Error)?.message ?? String(err)
      }\n`,
    )
    return []
  }
}

// RFC B §9: register /approvals list|revoke against the approval kernel.
// The kernel's IPC client (`src/vault/approvals/client.ts`) round-trips
// through the vault broker — same socket, no new daemon. The isApprover
// gate reuses the existing dmCommandGate / allowFrom pattern.
{
  const { registerApprovalsCommands } = await import('./approvals-commands.js')
  registerApprovalsCommands(bot, {
    isApprover: ctx => dmCommandGate(ctx) !== null,
  })
}

bot.command('start', async ctx => {
  // dmCommandGate (#894 backport): silent drop on disabled or
  // non-allowlisted senders so the bot doesn't leak its existence.
  const gated = dmCommandGate(ctx)
  if (!gated) return
  const disabled = gated.access.dmPolicy === 'disabled'
  await ctx.replyWithRichMessage(richMessage(buildStartText(getMyAgentName(), disabled)))
})

bot.command('help', async ctx => {
  if (!dmCommandGate(ctx)) return
  await ctx.replyWithRichMessage(richMessage(buildHelpText(getMyAgentName())))
})

bot.command('status', async ctx => {
  // dmCommandGate (#894 backport) drops disabled / non-allowlisted in
  // allowlist mode. Pairing-mode users still fall through to either
  // the pending-code branch or the unpaired branch.
  const gated = dmCommandGate(ctx)
  if (!gated) return
  const { access, senderId } = gated
  const from = ctx.from!
  if (access.allowFrom.includes(senderId)) {
    const demo = hasDemoFlag(getCommandArgs(ctx))
    const userTag = from.username ? `@${from.username}` : senderId
    const meta = await buildAgentMetadata(getMyAgentName())
    await ctx.replyWithRichMessage(richMessage(buildStatusPairedText({ user: userTag, meta, demo })))
    return
  }
  for (const [code, p] of Object.entries(access.pending)) {
    if (p.senderId === senderId) {
      await ctx.replyWithRichMessage(richMessage(buildStatusPendingText(code)))
      return
    }
  }
  await ctx.reply(buildStatusUnpairedText())
})

bot.command('agents', async ctx => {
  if (!isAuthorizedSender(ctx)) return
  await runSwitchroomCommandFormatted(ctx, ['agent', 'list'], 'agent list', () => {
    type AgentListResp = { agents: Array<{ name: string; status: string; uptime: string; template: string; topic_name: string; topic_emoji?: string }> }
    const data = switchroomExecJson<AgentListResp>(['agent', 'list'])
    if (!data) return null
    if (data.agents.length === 0) return '_No agents defined_'
    const lines = ['**Agents**']
    for (const a of data.agents) {
      lines.push(`${statusIcon(a.status)} **${escapeHtmlForTg(a.name)}** · ${escapeHtmlForTg(a.status)} · ${escapeHtmlForTg(a.uptime)}`)
      lines.push(`    _${escapeHtmlForTg(a.template)} → ${escapeHtmlForTg(a.topic_name)}${a.topic_emoji ? ' ' + a.topic_emoji : ''}_`)
    }
    return lines.join('\n')
  })
})

// /inject — #725 Phase 2 slash-command bridge. Implementation in
// inject-handler.ts so it's unit-testable without booting the bot.
// Shared deps for the inject-backed commands. `/inject <verb>` uses the
// defaults; first-class /compact and /clear pass `open` (anyone in the chat —
// operator decision, single-tenant trust) + a `fixedVerb` so they don't need
// the `/inject` prefix.
function buildInjectDeps(opts?: { open?: boolean; fixedVerb?: string }): InjectDeps {
  return {
    isAuthorized: opts?.open ? () => true : isAuthorizedSender,
    inject: injectSlashCommandImpl,
    // accent is already inlined into the body by the handler via
    // buildAccentHeader; switchroomReply doesn't need to know about it.
    reply: async (ctx, text, replyOpts) => switchroomReply(ctx, text, { html: replyOpts?.html }),
    getAgentName: getMyAgentName,
    getArgs: opts?.fixedVerb != null ? () => opts.fixedVerb as string : getCommandArgs,
    escapeHtml: escapeHtmlForTg,
    preBlock,
    formatOutput: formatSwitchroomOutput,
  }
}

bot.command('inject', async ctx => {
  await handleInjectCommand(ctx, buildInjectDeps())
})

// /compact + /clear — first-class session-control commands, open to anyone in
// the chat. Both are in the INJECT_COMMANDS allowlist; they ride the same
// inject primitive as `/inject compact` / `/inject clear`.
bot.command('compact', async ctx => {
  await handleInjectCommand(ctx, buildInjectDeps({ open: true, fixedVerb: '/compact' }))
})
bot.command('clear', async ctx => {
  await handleInjectCommand(ctx, buildInjectDeps({ open: true, fixedVerb: '/clear' }))
})

// /model — model dashboard + switch for this agent's live session.
// Bare form: drives claude's own /model picker (open → parse → Esc,
// src/agents/model-picker.ts) to discover the live option list — no
// hardcoded model names — and renders it as an inline-keyboard menu
// with the current model + a brief quota line. A tap re-opens the
// picker fresh and applies session-only (`s`). Kill-switch
// SWITCHROOM_MODEL_MENU=0 reverts the bare form to the static v1
// text. The typed argument form rides the allowlisted inject
// primitive unchanged. Implementation in model-command.ts so it's
// unit-testable without booting the bot.
interface ModelDepsRestartContext {
  chatId: string
  threadId: number | undefined
}

function buildModelDeps(restartCtx?: ModelDepsRestartContext): ModelMenuDeps & ModelCommandDeps {
  return {
    discover: (a) => discoverModels(a),
    discoverSrModels: async () => {
      const base = process.env.ANTHROPIC_BASE_URL
      const headers = process.env.ANTHROPIC_CUSTOM_HEADERS
      if (!base || !headers) return []
      const keyMatch = headers.match(/x-litellm-api-key:\s*Bearer\s*(\S+)/)
      if (!keyMatch) return []
      try {
        const res = await fetch(`${base.replace(/\/$/, '')}/model/info`, {
          headers: { Authorization: `Bearer ${keyMatch[1]}` },
          signal: AbortSignal.timeout(5000),
        })
        if (!res.ok) return []
        const data = (await res.json()) as { data?: Array<{ model_name: string }> }
        return (data.data ?? [])
          .map((m) => m.model_name)
          .filter((n) => n.startsWith('sr-'))
          .sort()
      } catch {
        return []
      }
    },
    select: (a, label) => selectModel(a, label),
    isBusy: () => currentTurn !== null,
    getAgentName: getMyAgentName,
    getQuotaBrief: async () => {
      // Broker-routed probe first (authoritative), local headers as
      // fallback — same ladder as the boot card / legacy /usage.
      try {
        const probed = await probeQuotaForBootCard(getMyAgentName(), 4000)
        if (probed?.ok) return formatQuotaLine(probed.data)
      } catch { /* fall through */ }
      try {
        const agentDir = resolveAgentDirFromEnv()
        if (agentDir) {
          const local = await fetchQuota({ claudeConfigDir: join(agentDir, '.claude') })
          if (local.ok) return formatQuotaLine(local.data)
        }
      } catch { /* quota is garnish — never block the menu on it */ }
      return null
    },
    inject: injectSlashCommandImpl,
    getConfiguredModel: () => {
      type AgentListResp = { agents: Array<{ name: string; model?: string | null }> }
      const data = switchroomExecJson<AgentListResp>(['agent', 'list'])
      return data?.agents?.find(a => a.name === getMyAgentName())?.model ?? null
    },
    escapeHtml: escapeHtmlForTg,
    preBlock,
    getActiveSessionModel: () => activeSessionModelOverride,
    /**
     * Graceful restart for sr-* → Claude model switch. Same mechanism as
     * the /restart command: writes a restart marker (so the post-restart
     * greeting lands in the originating chat), stamps the reason, and
     * dispatches via hostd (or legacy detached spawn as fallback).
     */
    scheduleRestart: async (reason: string) => {
      const name = getMyAgentName()
      // Debounce: mirror the /restart command's 15 s guard to prevent
      // double-dispatch on a rapid double-tap of /model <claude-alias>.
      const existing = readRestartMarker()
      if (existing && Date.now() - existing.ts < 15_000) return
      if (restartCtx) {
        writeRestartMarker({
          chat_id: restartCtx.chatId,
          thread_id: restartCtx.threadId ?? null,
          ack_message_id: null,
          ts: Date.now(),
        })
      }
      stampUserRestartReason(reason)
      await sweepBeforeSelfRestart()
      const hostdResp = await tryHostdDispatch(name, {
        v: 1,
        op: 'agent_restart',
        request_id: hostdRequestId('gw-model-restart'),
        args: { name, force: true, reason },
      })
      if (hostdResp === 'not-configured') {
        warnLegacySpawnIfHostdDisabled('agent_restart')
        spawnSwitchroomDetached(
          ['agent', 'restart', name, '--force'],
          notifyDetachedFailure(
            restartCtx?.chatId ?? '',
            restartCtx?.threadId ?? null,
            `restart ${name}`,
          ),
        )
        return
      }
      // hostd is configured but returned an error/denied result.
      if (hostdResp.result !== 'started' && hostdResp.result !== 'completed') {
        clearRestartMarker()
        throw new Error(
          `hostd restart failed (result=${hostdResp.result}): ${hostdResp.error ?? '(no details)'}`,
        )
      }
    },
  }
}

function modelMenuReplyMarkup(reply: ModelMenuReply): InlineKeyboard | undefined {
  if (!reply.keyboard) return undefined
  const kb = new InlineKeyboard()
  for (const row of reply.keyboard) {
    for (const btn of row) kb.text(btn.text, btn.callback_data)
    kb.row()
  }
  return kb
}

bot.command('model', async ctx => {
  if (!isAuthorizedSender(ctx)) return
  const text = ctx.message?.text ?? ctx.channelPost?.text ?? ''
  const parsed = parseModelCommand(text) ?? { kind: 'show' as const }
  const chatId = String(ctx.chat!.id)
  const threadId = resolveThreadId(chatId, ctx.message?.message_thread_id)
  const deps = buildModelDeps({ chatId, threadId })
  if (parsed.kind === 'show' && process.env.SWITCHROOM_MODEL_MENU !== '0') {
    const menu = await buildModelMenu(deps)
    await switchroomReply(ctx, menu.text, { html: true, reply_markup: modelMenuReplyMarkup(menu) })
    return
  }
  const reply = await handleModelCommand(parsed, deps)
  await switchroomReply(ctx, reply.text, { html: reply.html })
})

// `/effort` — show or switch the reasoning effort for the live session.
// The effort sibling of `/model`: bare form renders a five-button menu
// (low/medium/high/xhigh/max, the live level ✅), a typed form
// `/effort <level>` sets it directly. Both ride the dedicated `applyEffort`
// driver (claude's own `/effort` REPL command, with the confirmation modal
// answered so the pane never wedges — NOT the bare inject primitive, which
// is blocklisted for `/effort` since #2471), session-scoped — boot re-pins
// the configured default via start.sh's `--effort`. Implementation in
// effort-command.ts so it's unit-testable without booting the bot.
function buildEffortDeps(): EffortCommandDeps {
  return {
    applyEffort: (agent, level) => applyEffort(agent, level),
    getAgentName: getMyAgentName,
    getConfiguredEffort: () => {
      type AgentListResp = { agents: Array<{ name: string; thinking_effort?: string | null }> }
      const data = switchroomExecJson<AgentListResp>(['agent', 'list'])
      return data?.agents?.find(a => a.name === getMyAgentName())?.thinking_effort ?? null
    },
    escapeHtml: escapeHtmlForTg,
  }
}

function effortMenuReplyMarkup(reply: EffortMenuReply): InlineKeyboard | undefined {
  if (!reply.keyboard) return undefined
  const kb = new InlineKeyboard()
  for (const row of reply.keyboard) {
    for (const btn of row) kb.text(btn.text, btn.callback_data)
    kb.row()
  }
  return kb
}

bot.command('effort', async ctx => {
  if (!isAuthorizedSender(ctx)) return
  const text = ctx.message?.text ?? ctx.channelPost?.text ?? ''
  const parsed = parseEffortCommand(text) ?? { kind: 'show' as const }
  const deps = buildEffortDeps()
  if (parsed.kind === 'show') {
    const menu = buildEffortMenu(deps)
    await switchroomReply(ctx, menu.text, { html: true, reply_markup: effortMenuReplyMarkup(menu) })
    return
  }
  const reply = await handleEffortCommand(parsed, deps)
  await switchroomReply(ctx, reply.text, { html: reply.html })
})

