bot.command('restart', async ctx => {
  if (!isAuthorizedSender(ctx)) return
  const name = ctx.match?.trim() || getMyAgentName()
  try { assertSafeAgentName(name) } catch { await switchroomReply(ctx, 'Invalid agent name.'); return }
  if (isSelfTargetingCommand(name)) {
    const existing = readRestartMarker()
    if (existing && Date.now() - existing.ts < 15_000) {
      await switchroomReply(ctx, `⏳ Restart already in progress — ignoring duplicate.`, { html: true })
      return
    }
    const chatId = String(ctx.chat!.id)
    const threadId = resolveThreadId(chatId, ctx.message?.message_thread_id)
    const ackText = buildRestartAckText(name)
    let ackId: number | null = null
    // #1075: thread-id-bearing — fall back to main chat on
    // THREAD_NOT_FOUND so the ack still lands somewhere.
    try {
      const sent = await retryWithThreadFallback<{ message_id: number }>(
        robustApiCall,
        (tid) =>
          lockedBot.api.sendRichMessage(chatId, richMessage(ackText), {
            // Restart acknowledgement is a status notice — silence the
            // open ping (the "restarted — ready" follow-up is what matters).
            disable_notification: true,
            ...(tid != null ? { message_thread_id: tid } : {}),
          }),
        { threadId, chat_id: chatId, verb: 'restart.ack' },
      )
      ackId = sent.message_id
      if (HISTORY_ENABLED) {
        try { recordOutbound({ chat_id: chatId, thread_id: threadId ?? null, message_ids: [sent.message_id], texts: [`🔄 Restarting ${name}…`], attachment_kinds: [] }) } catch {}
      }
    } catch {}
    writeRestartMarker({ chat_id: chatId, thread_id: threadId ?? null, ack_message_id: ackId, ts: Date.now() })
    // Stamp user attribution into the clean-shutdown marker so the next
    // greeting card shows "Restarted  user: /restart from chat" instead
    // of whatever reason the downstream CLI would default to.
    stampUserRestartReason('user: /restart from chat')
    await sweepBeforeSelfRestart()
    const hostdResp = await tryHostdDispatch(getMyAgentName(), {
      v: 1,
      op: 'agent_restart',
      request_id: hostdRequestId('gw-restart'),
      args: { name, force: true, reason: 'user: /restart from chat' },
    })
    if (hostdResp === 'not-configured') {
      warnLegacySpawnIfHostdDisabled('agent_restart')
      spawnSwitchroomDetached(
        ['agent', 'restart', name, '--force'],
        notifyDetachedFailure(chatId, threadId ?? null, `restart ${name}`),
      )
      return
    }
    if (hostdResp.result === 'started' || hostdResp.result === 'completed') {
      // Dispatched via hostd. The recreate will kill this gateway
      // shortly; the new gateway reads the marker and edits the ack.
      return
    }
    // hostd was attempted but errored/denied — clear marker and surface.
    clearRestartMarker()
    await switchroomReply(
      ctx,
      `❌ **restart ${escapeHtmlForTg(name)} failed via hostd** ` +
        `(result=${escapeHtmlForTg(hostdResp.result)}):\n` +
        preBlock(hostdResp.error ?? '(no error message)'),
      { html: true },
    )
    return
  }
  // Cross-agent /restart <other>. Same hostd-first shape as self-target,
  // but no restart marker / no self-kill: another agent's container is
  // about to bounce, not ours. The daemon spawns the work and returns
  // "started" (per handleAgentRestart at server.ts:466), so the user
  // sees a brief dispatch ack and the audit log carries the outcome.
  await dispatchShortVerbViaHostd(
    ctx,
    {
      v: 1,
      op: 'agent_restart',
      request_id: hostdRequestId('gw-restart-cross'),
      args: { name, force: true, reason: `user: /restart ${name} from chat` },
    },
    `restart ${name}`,
    ['agent', 'restart', name],
  )
})

// ─── /new and /reset ──────────────────────────────────────────────────────
// Start a fresh session: flush .handoff.md + .handoff-topic so the restarted
// claude session isn't primed with the prior conversation, then trigger a
// restart. MEMORY.md, workspace/, skills/ are preserved. A1/N1/C6 from the
// OpenClawification review pass all applied.
function flushAgentHandoff(agentDir: string): number {
  let removed = 0
  for (const fname of ['.handoff.md', '.handoff-topic']) {
    const p = join(agentDir, fname)
    try {
      if (existsSync(p)) { unlinkSync(p); removed++ }
    } catch (err) {
      process.stderr.write(`telegram gateway: flushAgentHandoff ${fname}: ${(err as Error).message}\n`)
    }
  }
  return removed
}

async function handleNewCommand(ctx: Context): Promise<void> {
  const kind = 'new' // /reset removed (was a pure alias); keep the string for messages
  if (!isAuthorizedSender(ctx)) return
  const name = (typeof ctx.match === "string" ? ctx.match : "").trim() || getMyAgentName()
  try { assertSafeAgentName(name) } catch { await switchroomReply(ctx, 'Invalid agent name.'); return }
  // N1: `all` passes isSelfTargetingCommand (for /restart), but /new and
  // /reset semantically require flushing each agent's handoff before
  // restarting it — only that agent's own gateway can do that. If we let
  // /new all through we'd flush ONLY this agent's handoff and restart every
  // agent, leaving the others with stale briefings.
  if (name === 'all') {
    await switchroomReply(
      ctx,
      `/${kind} only supports a single agent — “all” would leave other agents with stale handoff briefings. ` +
        `Run /${kind} from each agent’s own topic, or use \`switchroom agent restart all\` if you just want a plain restart without flushing sessions.`,
      { html: true },
    )
    return
  }
  // A1: Cross-agent /new is refused — this gateway can only flush its own
  // handoff. Silently wiping our handoff while restarting another agent is a
  // footgun.
  if (!isSelfTargetingCommand(name)) {
    await switchroomReply(
      ctx,
      `/${kind} only supports the current agent (**${escapeHtmlForTg(getMyAgentName())}**). ` +
        `To restart another agent with a fresh session, run /${kind} from its own topic, ` +
        `or use \`switchroom agent restart ${escapeHtmlForTg(name)}\`.`,
      { html: true },
    )
    return
  }
  // C6: debounce — /new and /reset are functionally self-restarts. Without
  // the same 15s marker guard /restart uses, a double-tap (because the ack
  // hasn't landed yet) would stack systemctl restarts.
  const existing = readRestartMarker()
  if (existing && Date.now() - existing.ts < 15_000) {
    await switchroomReply(
      ctx,
      `⏳ Restart of **${escapeHtmlForTg(name)}** already in progress (${Math.round((Date.now() - existing.ts) / 1000)}s ago) — ignoring duplicate /${kind}.`,
      { html: true },
    )
    return
  }
  // Flush handoff first — if we crash between here and the restart the
  // worst case is the next boot has no briefing, which is the intent anyway.
  const agentDir = resolveAgentDirFromEnv()
  const flushed = agentDir != null ? flushAgentHandoff(agentDir) : 0

  const chatId = String(ctx.chat!.id)
  const threadId = resolveThreadId(chatId, ctx.message?.message_thread_id)
  const ackText = buildNewSessionAckText(name, flushed > 0)
  let ackId: number | null = null
  // #1075: thread-id-bearing — fall back to main chat.
  try {
    const sent = await retryWithThreadFallback<{ message_id: number }>(
      robustApiCall,
      (tid) =>
        lockedBot.api.sendRichMessage(chatId, richMessage(ackText), {
          // /new /reset acknowledgement is a status notice — silence the
          // open ping (the post-restart greeting card is what matters).
          disable_notification: true,
          ...(tid != null ? { message_thread_id: tid } : {}),
        }),
      { threadId, chat_id: chatId, verb: 'new-or-reset.ack' },
    )
    ackId = sent.message_id
    if (HISTORY_ENABLED) {
      try { recordOutbound({ chat_id: chatId, thread_id: threadId ?? null, message_ids: [sent.message_id], texts: [ackText], attachment_kinds: [] }) } catch {}
    }
  } catch {}
  writeRestartMarker({ chat_id: chatId, thread_id: threadId ?? null, ack_message_id: ackId, ts: Date.now() })

  // Force-fresh-session marker: tell start.sh to skip --continue on next
  // boot so the user actually gets a new Claude session (and therefore a
  // SessionStart greeting). Flushing .handoff.md alone is not enough,
  // because start.sh auto-mode picks --continue whenever the JSONL
  // session file still exists under ~/.claude/projects/<slug>/. The
  // marker is consumed (removed) by start.sh on that one boot, so normal
  // resume behavior returns immediately after.
  if (agentDir != null) {
    try {
      writeFileSync(join(agentDir, '.force-fresh-session'), `${kind} at ${new Date().toISOString()}\n`, 'utf8')
    } catch (err) {
      process.stderr.write(`telegram gateway: failed to write force-fresh marker: ${err}\n`)
    }
  }

  // Stamp user attribution so the next greeting shows "Restarted  user:
  // /new" / "user: /reset" rather than the downstream CLI default.
  stampUserRestartReason(`user: /${kind} from chat`)
  await sweepBeforeSelfRestart()
  const hostdResp = await tryHostdDispatch(getMyAgentName(), {
    v: 1,
    op: 'agent_restart',
    request_id: hostdRequestId(`gw-${kind}`),
    args: { name, force: true, reason: `user: /${kind} from chat` },
  })
  if (hostdResp === 'not-configured') {
    warnLegacySpawnIfHostdDisabled('agent_restart')
    spawnSwitchroomDetached(
      ['agent', 'restart', name, '--force'],
      notifyDetachedFailure(chatId, threadId ?? null, `${kind} ${name}`),
    )
    return
  }
  if (hostdResp.result === 'started' || hostdResp.result === 'completed') {
    return
  }
  clearRestartMarker()
  await switchroomReply(
    ctx,
    `❌ **${escapeHtmlForTg(kind)} ${escapeHtmlForTg(name)} failed via hostd** ` +
      `(result=${escapeHtmlForTg(hostdResp.result)}):\n` +
      preBlock(hostdResp.error ?? '(no error message)'),
    { html: true },
  )
}

bot.command('new', async ctx => handleNewCommand(ctx))

// /update — host update from Telegram (#919). Default = dry-run plan
// (`switchroom update --check`); explicit `apply` triggers the real
// thing via spawnSwitchroomDetached so the gateway can be killed
// mid-flight by the recreate-containers step without orphaning the
// update. Admin-gated via ADMIN_COMMAND_NAMES.
bot.command('update', async ctx => {
  if (!isAuthorizedSender(ctx)) return
  const arg = ctx.match?.trim() || ''
  if (arg === '' || arg === 'check' || arg === '--check') {
    await runSwitchroomCommand(ctx, ['update', '--check'], 'update --check')
    await switchroomReply(
      ctx,
      'Reply with \`/update apply\` to execute, or \`/update apply --skip-images\` to skip the image pull.',
      { html: true },
    )
    return
  }
  // Parse `apply` (with optional --skip-images / --rebuild passthrough).
  // `/update apply` and `/update apply --skip-images` are the supported
  // forms; everything else surfaces a usage hint.
  const tokens = arg.split(/\s+/)
  if (tokens[0] !== 'apply' && tokens[0] !== '--apply') {
    await switchroomReply(
      ctx,
      'Usage: \`/update\` (dry-run) or \`/update apply [--skip-images] [--rebuild]\`',
      { html: true },
    )
    return
  }
  // Whitelist passthrough flags. Anything outside the allowlist is
  // refused — operators should not be able to inject arbitrary CLI
  // args via Telegram (defense in depth even though admin-gated).
  const ALLOWED_FLAGS = new Set(['--skip-images', '--rebuild'])
  const passthrough = tokens.slice(1)
  for (const tok of passthrough) {
    if (!ALLOWED_FLAGS.has(tok)) {
      await switchroomReply(
        ctx,
        `Refusing to pass unknown flag: \`${tok}\`. ` +
        `Allowed: \`--skip-images\`, \`--rebuild\`.`,
        { html: true },
      )
      return
    }
  }
  // Pre-dispatch availability gate (#926 / #1469 / #1470). The gateway
  // runs INSIDE the agent container, which has the switchroom CLI baked
  // in but no docker binary and no /var/run/docker.sock mount. So
  // `switchroom update`'s pull-images and recreate-containers steps
  // would fail with "docker: command not found" — UNLESS hostd is in
  // play (#1175 Phase 2 RFC C), in which case hostd runs on the host
  // with the docker socket mounted and the in-container docker
  // dependency goes away.
  //
  // Three states to distinguish here, so the operator gets a message
  // pointing at the right remediation:
  //
  //   - hostd ready (socket bound): proceed — no gate.
  //   - hostd configured-on but socket missing (#1470): tell the
  //     operator to run `switchroom hostd install`. Don't conflate
  //     with "enable host_control" — it's already on.
  //   - hostd off AND no in-container docker (#1469): fall through
  //     to spawn-detached would fail late; explain the choice between
  //     host CLI and enabling hostd.
  const myAgentName = getMyAgentName()
  const hostdReady = hostdWillBeUsed(myAgentName)
  if (!hostdReady && !isDockerReachable()) {
    if (isHostdEnabled()) {
      // hostd is configured on, but the per-agent socket isn't bound —
      // hostd hasn't been installed yet, or its daemon is down.
      await switchroomReply(
        ctx,
        `❌ **/update apply** needs \`hostd\`, but its socket ` +
        `for agent \`${myAgentName}\` isn't ` +
        `bound and in-container docker access isn't available either.\n\n` +
        `\`host_control.enabled\` is on in \`switchroom.yaml\`, ` +
        `so hostd is the expected dispatch path — but no socket at ` +
        `\`/run/switchroom/hostd/${escapeHtmlForTg(myAgentName)}/sock\`. ` +
        `On a fresh docker install this usually means hostd hasn't been ` +
        `installed yet.\n\n` +
        `Run \`switchroom hostd install\` on the host to install + ` +
        `start the daemon, then retry. Send \`/upgradestatus\` to ` +
        `re-check the daemon state from here.`,
        { html: true },
      )
    } else {
      // host_control explicitly off + no in-container docker: nothing
      // can drive the apply from inside the container. Operator has to
      // pick one of: host CLI, or enable hostd.
      await switchroomReply(
        ctx,
        `❌ **/update apply** needs docker access from inside the agent ` +
        `container, but it's not available (no \`docker\` binary on ` +
        `PATH, no \`/var/run/docker.sock\` mount) and ` +
        `\`host_control.enabled\` is off.\n\n` +
        `Either run \`switchroom update\` from the host shell, or ` +
        `set \`host_control.enabled: true\` in ` +
        `\`switchroom.yaml\` and run ` +
        `\`switchroom hostd install\` on the host so this verb ` +
        `can dispatch through the host-side daemon.`,
        { html: true },
      )
    }
    return
  }
  // Debounce vs concurrent self-restart commands (/restart, /new, /reset
  // and other /update). Reading + writing the SAME restart marker means
  // a double-tap of /update apply is rejected, AND a /restart fired
  // mid-update is rejected (and vice versa). 15s window matches the
  // /restart handler.
  const existing = readRestartMarker()
  if (existing && Date.now() - existing.ts < 15_000) {
    await switchroomReply(
      ctx,
      `⏳ Self-restart already in progress (started ${Math.round(
        (Date.now() - existing.ts) / 1000,
      )}s ago) — ignoring duplicate.`,
      { html: true },
    )
    return
  }
  const chatId = String(ctx.chat!.id)
  const threadId = resolveThreadId(chatId, ctx.message?.message_thread_id)
  // Send the ack and capture its message_id so the post-restart
  // greeting card can edit/reply into the same message. Mirrors the
  // /restart handler (gateway.ts ~6273) so the boot-card lookup
  // (gateway.ts ~10393) finds chat_id + ack_message_id in the marker.
  const ackText =
    `🚀 **update started** — running ${[
      '\`switchroom update\`',
      ...passthrough.map((t) => `\`${t}\``),
    ].join(' ')}\n` +
    `\nThe gateway will restart as part of the recreate step; watch ` +
    `for the post-restart greeting card to confirm completion.`
  let ackId: number | null = null
  // #1075: thread-id-bearing — fall back to main chat.
  try {
    const sent = await retryWithThreadFallback<{ message_id: number }>(
      robustApiCall,
      (tid) =>
        lockedBot.api.sendRichMessage(chatId, richMessage(ackText), {
          // "update started" acknowledgement is a status notice — silence
          // the open ping (the post-restart greeting card is what matters).
          disable_notification: true,
          ...(tid != null ? { message_thread_id: tid } : {}),
        }),
      { threadId, chat_id: chatId, verb: 'update.ack' },
    )
    ackId = sent.message_id
    if (HISTORY_ENABLED) {
      try {
        recordOutbound({
          chat_id: chatId,
          thread_id: threadId ?? null,
          message_ids: [sent.message_id],
          texts: [`🚀 update started`],
          attachment_kinds: [],
        })
      } catch {}
    }
  } catch {}
  writeRestartMarker({
    chat_id: chatId,
    thread_id: threadId ?? null,
    ack_message_id: ackId,
    ts: Date.now(),
  })
  // Reason banner for the post-restart greeting card. Without this the
  // banner falls back to whatever the CLI's clean-shutdown marker
  // stamped — usually 'unknown' or a docker-compose-restart string.
  stampUserRestartReason('user: /update from chat')
  // Unpin progress cards + clear active reactions before we die. The
  // pinned-progress-card surface is the headline feature per CLAUDE.md;
  // leaving one pinned across the recreate would surprise the operator.
  await sweepBeforeSelfRestart()
  const skipImages = passthrough.includes('--skip-images')
  const rebuild = passthrough.includes('--rebuild')
  const updateRequestId = hostdRequestId('gw-update')
  const hostdResp = await tryHostdDispatch(getMyAgentName(), {
    v: 1,
    op: 'update_apply',
    request_id: updateRequestId,
    args: {
      ...(skipImages ? { skip_images: true } : {}),
      ...(rebuild ? { rebuild: true } : {}),
    },
  })
  if (hostdResp === 'not-configured') {
    warnLegacySpawnIfHostdDisabled('update_apply')
    spawnSwitchroomDetached(
      ['update', ...passthrough],
      notifyDetachedFailure(chatId, threadId ?? null, 'update'),
    )
    return
  }
  if (hostdResp.result === 'completed') {
    return
  }
  if (hostdResp.result === 'started') {
    // Mark in-flight so the framework silence fallback renders hostd's
    // real phase + elapsed (deterministic, model-free) instead of the
    // content-free "still working…" — the klanker incident fix.
    inFlightUpdate = { requestId: updateRequestId, startedAt: Date.now() }
    // RFC C §5.3: long-running mutation. Poll get_status until terminal
    // or until the recreate kills this gateway (whichever happens first).
    // The success signal is the post-restart greeting card edited into
    // ackId via the restart marker. The poll is here so that
    // *fail-before-recreate* (image pull error, scaffold regen crash)
    // doesn't leave the operator staring at the orphan "🚀 update started"
    // ack indefinitely. Live repro: PR #1305.
    void (async () => {
     try {
      // 60s budget: RFC C §5.3 specs `apply` at 30s and `update_apply`
      // at 60s. Image pulls + scaffold regeneration dominate the wall
      // clock for update_apply, hence the larger budget. The poll
      // resolves earlier on any terminal state from the daemon.
      const terminal = await pollHostdStatus(getMyAgentName(), updateRequestId, {
        timeoutMs: 60_000,
      })
      if (terminal === 'not-configured') return
      // completed → recreate is about to run / has run; let the post-
      // restart greeting card handle the success message.
      if (terminal.result === 'completed') return
      // Anything else means the daemon's mutation failed before it could
      // kill us. Edit the ack to surface the tail and clear the marker
      // so the next gateway boot doesn't render a false success card.
      clearRestartMarker()
      const errBody =
        terminal.error ??
        terminal.stderr_tail ??
        terminal.stdout_tail ??
        '(no error tail returned)'
      const editedText =
        `🚀 **update started** — **FAILED** via hostd ` +
        `(result=${escapeHtmlForTg(terminal.result)}):\n` +
        preBlock(errBody)
      if (ackId != null) {
        try {
          await robustApiCall(
            () =>
              lockedBot.api.editMessageText(chatId, ackId!, richMessage(editedText), {
                link_preview_options: { is_disabled: true },
              }),
            { verb: 'update.poll.editAck' },
          )
        } catch {
          // edit-failed (message deleted, parse error) — fall back to
          // a fresh reply so the failure isn't silent.
          try {
            await switchroomReply(ctx, editedText, { html: true })
          } catch {}
        }
      } else {
        try {
          await switchroomReply(ctx, editedText, { html: true })
        } catch {}
      }
     } finally {
       // Poll resolved (terminal / completed / not-configured /
       // timeout) — stop substituting in-flight update status.
       inFlightUpdate = null
     }
    })()
    return
  }
  clearRestartMarker()
  await switchroomReply(
    ctx,
    `❌ **/update apply failed via hostd** ` +
      `(result=${escapeHtmlForTg(hostdResp.result)}):\n` +
      preBlock(hostdResp.error ?? '(no error message)'),
    { html: true },
  )
})

// /upgradestatus — read-only snapshot of where this host stands (#927).
// Wraps `switchroom update --status` synchronously and posts the
// formatted output. NOT admin-gated: read-only fleet metadata is safe
// for any allowFrom user to see, and the answer "is something behind?"
// is the missing companion to /update's "trigger an update".
// (Telegram slash-commands forbid hyphens, hence /upgradestatus not
// /upgrade-status. The /upgrade alias just below redirects.)
bot.command('upgradestatus', async ctx => {
  if (!isAuthorizedSender(ctx)) return
  // PR5 — heavy-output: route to admin alias in supergroup mode
  // (CPO #4). Fleet-shared / DM agents fall through to in-place reply.
  await runSwitchroomCommand(ctx, ['update', '--status'], 'update --status', 'heavy')
})
// Alias with hyphen — Grammy doesn't allow hyphens in command names
// (Telegram's slash-command grammar excludes them) but operators are
// likely to type /upgrade-status; surface a polite redirect.
bot.command('upgrade', async ctx => {
  if (!isAuthorizedSender(ctx)) return
  await switchroomReply(
    ctx,
    'Did you mean \`/upgradestatus\` (no hyphen — Telegram slash-command grammar)? ' +
    'Or \`/update\` to plan, \`/update apply\` to execute.',
    { html: true },
  )
})

// /audit hostd — tail/filter the hostd audit log. Mirrors `/vault audit`
// in spirit (operator observability over a privileged subsystem from any
// admin DM). Admin-gated via ADMIN_COMMAND_NAMES. Reads the audit JSONL
// at ~/.switchroom/host-control-audit.log directly — no hostd RPC needed
// because the file is shared via the host bind mount on docker installs.
bot.command('audit', async ctx => {
  if (!isAuthorizedSender(ctx)) return
  const arg = (ctx.match ?? '').trim()
  if (arg === '' || arg === 'help' || arg === '--help') {
    await switchroomReply(
      ctx,
      'Usage: \`/audit hostd [--tail N] [--agent <name>] [--op <verb>] [--error] [--verbose]\`',
      { html: true },
    )
    return
  }
  const tokens = arg.split(/\s+/)
  const sub = tokens[0]
  if (sub !== 'hostd') {
    await switchroomReply(
      ctx,
      `Unknown audit target \`${sub ?? ''}\`. ` +
      `Supported: \`hostd\`.`,
      { html: true },
    )
    return
  }
  // Build the CLI argv for switchroom hostd audit. Validate each
  // operator-supplied value to keep argv injection out of the picture.
  const ALLOWED_OPS = new Set([
    'agent_start', 'agent_stop', 'agent_restart', 'apply',
    'update_check', 'update_apply', 'update_status', 'upgrade_status',
    'get_status', 'doctor', 'fleet_state',
  ])
  const argv: string[] = ['hostd', 'audit']
  for (let i = 1; i < tokens.length; i++) {
    const t = tokens[i]!
    if (t === '--error') { argv.push('--error'); continue }
    if (t === '--verbose') { argv.push('--verbose'); continue }
    if (t === '--tail' || t === '--agent' || t === '--op') {
      const v = tokens[++i]
      if (v == null) {
        await switchroomReply(ctx, `Flag \`${t}\` requires a value.`, { html: true })
        return
      }
      if (t === '--tail' && !/^[0-9]{1,4}$/.test(v)) {
        await switchroomReply(ctx, `\`--tail\` must be an integer (1-9999).`, { html: true })
        return
      }
      if (t === '--agent' && !/^[a-z][a-z0-9-]{0,62}$/i.test(v)) {
        await switchroomReply(ctx, `\`--agent\` name has an invalid shape.`, { html: true })
        return
      }
      if (t === '--op' && !ALLOWED_OPS.has(v)) {
        await switchroomReply(
          ctx,
          `Unknown hostd verb \`${v}\`. ` +
          `Known: ${[...ALLOWED_OPS].sort().map(o => `\`${o}\``).join(', ')}.`,
          { html: true },
        )
        return
      }
      argv.push(t, v)
      continue
    }
    await switchroomReply(
      ctx,
      `Unknown flag \`${t}\`. ` +
      `Allowed: \`--tail\`, \`--agent\`, \`--op\`, \`--error\`, \`--verbose\`.`,
      { html: true },
    )
    return
  }
  // PR5 — heavy-output → admin alias in supergroup mode (CPO #4).
  await runSwitchroomCommand(ctx, argv, `hostd audit${argv.length > 2 ? ' …' : ''}`, 'heavy')
})

// ─── /approve, /deny, /pending ────────────────────────────────────────────
// Slash-command alternatives to the inline-button approval flow (useful for
// desktop-only sessions and power-users). Share pendingPermissions state
// with the button handler; emit the same `permission` IPC broadcast.
function isValidPermissionRequestId(id: string): boolean {
  return /^[a-z0-9-]{1,32}$/.test(id)
}

async function handlePermissionSlash(ctx: Context, behavior: 'allow' | 'deny'): Promise<void> {
  if (!isAuthorizedSender(ctx)) return
  const access = loadAccess()
  const senderId = String(ctx.from?.id ?? '')
  if (!access.allowFrom.includes(senderId)) {
    await switchroomReply(ctx, 'Not authorized to answer permission prompts.')
    return
  }
  const raw = (typeof ctx.match === "string" ? ctx.match : "").trim()
  let request_id = raw
  if (!request_id) {
    // Default to most-recently created pending permission. Map preserves
    // insertion order so Array.from(...).at(-1) gives us that.
    const entries = Array.from(pendingPermissions.keys())
    request_id = entries[entries.length - 1] ?? ''
  }
  if (!request_id) {
    await switchroomReply(ctx, 'No pending permission prompts right now.')
    return
  }
  // C2: sanity-check the id shape so we don't look up (or echo back)
  // arbitrary user input. Claude Code's request_ids are short alphanumeric
  // slugs; the button handler enforces /^[a-km-z]{5}$/. The slash path is
  // looser for forward compat but still rejects obvious junk.
  if (!isValidPermissionRequestId(request_id)) {
    await switchroomReply(ctx, `Invalid permission id. Expected lowercase alphanumeric / dashes up to 32 chars.`)
    return
  }
  const details = pendingPermissions.get(request_id)
  if (!details) {
    await switchroomReply(
      ctx,
      `No pending permission for id \`${request_id}\`. It may have already been answered or timed out.`,
      { html: true },
    )
    return
  }
  // Operator answered via slash ⇒ present; reset no-repeat suppression.
  clearPermissionTimeoutSuppression('operator answered via /approve|/deny')
  // Forward to connected bridges — same IPC the button handler uses.
  dispatchPermissionVerdict({ type: 'permission', requestId: request_id, behavior })
  resumeReactionAfterVerdict()
  postPermissionResumeMessage({
    behavior,
    action: naturalAction(details.tool_name, details.input_preview),
  })
  pendingPermissions.delete(request_id)
  permCardStore.remove(request_id)
  process.stderr.write(
    `[telegram gateway] slash-${behavior} request_id=${request_id} tool=${details.tool_name} by=${senderId}\n`,
  )
  const lbl = behavior === 'allow' ? '✅ Allowed' : '❌ Denied'
  const suffix = details.tool_name ? ` (\`${details.tool_name}\`)` : ''
  await switchroomReply(
    ctx,
    `${lbl}${suffix} via /${behavior} \`${request_id}\``,
    { html: true },
  )
}

bot.command('approve', async ctx => handlePermissionSlash(ctx, 'allow'))
bot.command('deny', async ctx => handlePermissionSlash(ctx, 'deny'))

// ─── Drive folder picker (RFC E §4.1) ───────────────────────────────────
// /folders — post a Telegram picker card listing this agent's top-level
// Drive folders. Tap [Allow] on a folder to grant the agent
// allow_always at doc:gdrive:folder/<id>/**; tap [Browse] to drill in.
//
// Authorisation: same dmCommandGate as the other operator slash
// commands — only allowFrom users can post-trigger.

const folderPickerCache = new FolderListCache()

function buildFolderPickerDeps(): FolderPickerHandlerDeps {
  const agentName = getMyAgentName()
  return {
    agentName,
    cache: folderPickerCache,
    fetchPage: async ({ parent_id, page_token }) => {
      const handle = await loadFromAuthBroker()
      if (handle === null) {
        throw new Error(
          `auth-broker unreachable for agent ${agentName} — is the broker container running?`,
        )
      }
      return fetchFolderPage({
        access_token: handle.access_token,
        ...(parent_id !== undefined ? { parent_id } : {}),
        ...(page_token !== undefined ? { page_token } : {}),
      })
    },
    approvalRequest: async (args) => {
      const r = await kernelApprovalRequest({
        agent_unit: args.agent_unit,
        scope: args.scope,
        action: args.action,
        approver_set: args.approver_set,
        ...(args.why !== null && args.why !== undefined ? { why: args.why } : {}),
        ...(args.ttl_ms !== null && args.ttl_ms !== undefined ? { ttl_ms: args.ttl_ms } : {}),
      })
      if (r === null || r.state === 'rate_limited') return null
      return { request_id: r.request_id }
    },
    approvalConsume: async (id) => {
      const r = await kernelApprovalConsume(id)
      return r !== null && r.consumed
    },
    approvalRecord: async (args) => kernelApprovalRecord(args),
  }
}

bot.command('folders', async ctx => {
  if (!isAuthorizedSender(ctx)) return
  await handleFoldersCommand(ctx, buildFolderPickerDeps())
})

// /pending — list current pending permission prompts with their ids, so the
// user can target a specific one via /approve <id> or /deny <id>.
// Restricted to access.allowFrom DMs to match /approve and /deny — it
// wouldn't make sense to let a group member see which permissions are
// pending when they can't actually answer them.
bot.command('pending', async ctx => {
  if (!isAuthorizedSender(ctx)) return
  const access = loadAccess()
  const senderId = String(ctx.from?.id ?? '')
  if (!access.allowFrom.includes(senderId)) {
    await switchroomReply(ctx, 'Not authorized to view pending permission prompts.')
    return
  }
  if (pendingPermissions.size === 0) {
    await switchroomReply(ctx, 'No pending permission prompts.')
    return
  }
  const lines: string[] = ['**Pending permission prompts**']
  for (const [id, details] of pendingPermissions.entries()) {
    lines.push(`• \`${id}\` — ${escapeHtmlForTg(details.tool_name)}`)
  }
  await switchroomReply(ctx, lines.join('\n'), { html: true })
})

bot.command('interrupt', async ctx => {
  if (!isAuthorizedSender(ctx)) return
  const name = ctx.match?.trim() || getMyAgentName()
  try { assertSafeAgentName(name) } catch { await switchroomReply(ctx, 'Invalid agent name.'); return }
  await runSwitchroomCommand(ctx, ['agent', 'interrupt', name], `interrupt ${name}`)
})

// Persist-ops bundle for the legacy auto-fallback lockout file. The
// only remaining reader is `isAutoFallbackCooldownActive` (line ~2030)
// — used by the pending-restart drain cap to defer a forced restart
// stacking on top of an in-flight slot rotation. The legacy poller
// that USED to write this file was retired alongside this refactor;
// existing on-disk lockouts age out via DEFAULT_FALLBACK_COOLDOWN_MS.
const lockoutOps: LockoutPersistOps = {
  readFileSync: (p, enc) => readFileSync(p, enc),
  writeFileSync: (p, data, opts) => writeFileSync(p, data, opts),
  existsSync: (p) => existsSync(p),
  mkdirSync: (p, opts) => mkdirSync(p, opts),
  joinPath: (...parts) => join(...parts),
}

// Pinned slot-banner state (#421). One banner per gateway process,
// in the owner chat (access.allowFrom[0]). Per-topic forum support
// + multi-chat pinning are tracked as #421 follow-ups.
let pinnedBannerState: BannerState | null = null

async function refreshPinnedBanner(reason: string): Promise<void> {
  try {
    const ownerChatId = loadAccess().allowFrom[0]
    if (!ownerChatId) return
    const agentDir = resolveAgentDirFromEnv()
    if (!agentDir) return // No TELEGRAM_STATE_DIR — banner has no slot context.
    const agentName = getMyAgentName()
    const slot = currentActiveSlot(agentDir)
    pinnedBannerState = await refreshBanner({
      bot,
      ownerChatId,
      agentName,
      currentSlot: slot,
      defaultSlot: DEFAULT_SLOT,
      prevState: pinnedBannerState,
      onError: (phase, err) => {
        process.stderr.write(`telegram gateway: banner ${phase} failed (${reason}): ${err}\n`)
      },
      // Durable pin persistence into the SHARED status-pin store (distinct
      // `banner:` pinKey). persist-BEFORE-pin ordering: pending() lands before
      // the pinChatMessage call so a crash in that window is recoverable by the
      // one runStatusPinBootCleanup on next boot. Best-effort / gated no-op.
      persist: {
        pending: (chatId, messageId) =>
          persistBannerRow({ pinKey: BANNER_PIN_KEY, chatId, messageId, pending: true }),
        confirm: (chatId, messageId) =>
          persistBannerRow({ pinKey: BANNER_PIN_KEY, chatId, messageId }),
        clear: () => persistBannerRow(null),
      },
    })
  } catch (err) {
    process.stderr.write(`telegram gateway: banner refresh error (${reason}): ${err}\n`)
  }
}

/**
 * Re-entry guard + dedup window for `fireFleetAutoFallback`. The state
 * was lifted into `fleet-fallback-gate.ts` so it can be tested in
 * isolation (gateway.ts module state was unreachable from vitest). The
 * gate ALSO enforces the broker-reachability honesty contract: when the
 * broker is down, `wouldFire()` returns false so the model-unavailable
 * card stays honest instead of advertising a swap that would bail with
 * `reason=no-broker-client`.
 */
const FLEET_FALLBACK_DEDUP_MS = 30_000

/** Synchronous reachability check for the auth-broker UDS. Used by the
 *  fleet-fallback gate to keep the model-unavailable card honest: if the
 *  broker socket isn't bound, the dispatcher would bail with
 *  `reason=no-broker-client`, so `wouldFire()` should return false and
 *  the card should fall back to the manual `/auth use <label>` hint. */
function isAuthBrokerSocketReachable(): boolean {
  try {
    return existsSync(resolveAuthBrokerSocketPath())
  } catch {
    return false
  }
}

const fleetFallbackGate = createFleetFallbackGate({
  dedupMs: FLEET_FALLBACK_DEDUP_MS,
  brokerReachable: isAuthBrokerSocketReachable,
})

/**
 * Resume-after-swap gate (auth-failover-stall fix). Owns the single-flight +
 * staleness decision for re-running the turn a mid-turn 429 killed. See
 * fleet-fallback-resume.ts. Wired into doFireFleetAutoFallback below: on a
 * 'switched' outcome we restart so the boot-resume path replays the dead turn
 * on the freshly-active account. 3h staleness mirrors the boot-resume
 * RESUME_MAX_AGE_MS failsafe (gateway boot path); single-flight stops a 429
 * storm from loop-restarting the agent.
 */
const fleetFallbackResumeGate = createFleetFallbackResumeGate({
  maxAgeMs: (() => {
    const v = Number(process.env.SWITCHROOM_RESUME_MAX_AGE_MS)
    return Number.isFinite(v) && v > 0 ? v : 10_800_000 // 3h, matches boot-resume
  })(),
})

/**
 * The start time (epoch-ms) of the most-recently-started active turn — the
 * staleness signal for the resume gate. `activeTurnStartedAt` is stamped on
 * inbound receipt (see its declaration), so the newest entry is the turn the
 * 429 just killed. Returns null when no turn is tracked (then the resume gate
 * defers staleness to the boot-resume 3h failsafe). */
function newestActiveTurnStartedAtMs(): number | null {
  let newest: number | null = null
  for (const ms of activeTurnStartedAt.values()) {
    if (newest == null || ms > newest) newest = ms
  }
  return newest
}

function wouldFireFleetAutoFallback(): boolean {
  return fleetFallbackGate.wouldFire()
}

/**
 * Fleet-wide auto-fallback dispatcher (RFC H follow-up).
 *
 * Wired from the model-unavailable card render path so a quota-out
 * event on ANY agent immediately triggers a fleet-wide swap (via
 * broker.setActive — same path /auth use takes), not the per-agent
 * legacy `runAutoFallbackCheck`. Pre-fix, the card path never called
 * any fallback machinery; the scheduled poller (60-min interval, only
 * fires on utilization headers) was the only trigger and missed
 * hard-rejection events.
 *
 * Concurrency: collapses concurrent triggers via the in-flight
 * promise above. Subsequent calls within `FLEET_FALLBACK_DEDUP_MS` of
 * a recent fire are dropped silently — the broadcast announcement is
 * the user-visible signal that the swap happened, no need to repeat.
 *
 * Fire-and-forget: never throws into the caller's flow. Posts the
 * causal-shape announcement to every chat in `loadAccess().allowFrom`
 * so the user sees the outcome inline with the original "Model
 * unavailable" card.
 */
async function fireFleetAutoFallback(triggerAgent: string, untilMs?: number): Promise<void> {
  return fleetFallbackGate.fire(
    () => doFireFleetAutoFallback(triggerAgent, untilMs),
    (err) => {
      process.stderr.write(
        `telegram gateway: [fleet-fallback] error agent=${triggerAgent}: ${(err as Error)?.message ?? err}\n`,
      )
    },
  )
}

/**
 * Broadcast a fleet-fallback FAILURE notice to every authorized chat.
 *
 * Why this exists: the model-unavailable card renders "Auto-failover in
 * progress — see the announcement below" BEFORE the dispatcher's outcome
 * is known. When the dispatcher errors (broker down, listState throw,
 * markExhausted failure), the success announcement never lands and the
 * card's promise is broken — the 2026-06-06→07 incident sent 12 such
 * broken-promise cards while every fallback errored "set-active requires
 * admin". The admin-gating root cause is fixed (#2206), but ANY future
 * dispatcher error reproduces the broken promise. This notice closes the
 * loop deterministically: card promised an announcement → an
 * announcement ALWAYS arrives, success or failure.
 *
 * Disable with SWITCHROOM_FLEET_FALLBACK_FAILURE_NOTICE=0 (log-only,
 * pre-fix behaviour).
 */
let fallbackFailureNoticeState: FallbackFailureNoticeState = { lastSentAtMs: 0 }

/**
 * Bug 2 — per-gateway cooldown for the "All accounts blocked" card. The
 * all-blocked outcome is a no-op swap (doFireFleetAutoFallback returns false),
 * so the fleetFallbackGate dedup window never arms for it, and the ~60s
 * quota_wall_detected re-trigger would otherwise re-broadcast the identical card
 * every minute for the life of the wall. This bounds it to one card per window.
 * Reset on a successful swap so a fresh all-blocked after a recovery (a real new
 * transition) is not stale-suppressed.
 */
let fallbackAllBlockedNoticeState: FallbackAllBlockedNoticeState = { lastSentAtMs: 0 }

function broadcastFleetFallbackFailure(triggerAgent: string, reason: string): void {
  if (process.env.SWITCHROOM_FLEET_FALLBACK_FAILURE_NOTICE === '0') return
  // Notice-level cooldown (30 min, per gateway). The fleetFallbackGate's
  // dedup window only arms on SUCCESSFUL swaps, so it bounds nothing
  // here — and the card-less quota_wall_detected trigger re-fires every
  // ~60s during a wall. Without this, a persistent broker outage would
  // stream failure notices for days. See evaluateFallbackFailureNotice.
  const verdict = evaluateFallbackFailureNotice(fallbackFailureNoticeState, Date.now())
  if (!verdict.send) {
    process.stderr.write(
      `telegram gateway: [fleet-fallback] failure notice suppressed (cooldown) agent=${triggerAgent}: ${reason}\n`,
    )
    return
  }
  fallbackFailureNoticeState = verdict.next
  const access = loadAccess()
  if (access.allowFrom.length === 0) return
  const html = renderFallbackFailureNotice(triggerAgent, reason)
  for (const chat_id of access.allowFrom) {
    void swallowingApiCall(
      // allow-raw-bot-api: wrapped in swallowingApiCall (retry policy)
      () => bot.api.sendRichMessage(chat_id, richMessage(html), {}),
      { chat_id, verb: 'fleet-fallback:failure-notify' },
    )
  }
}

/** Returns true iff the dispatcher actually performed a swap (and the
 *  user-visible announcement was broadcast). False on no-op /
 *  error / idempotent-skip — caller uses this to decide whether to
 *  arm the post-fire suppression window. */
async function doFireFleetAutoFallback(triggerAgent: string, untilMs?: number): Promise<boolean> {
  try {
    const client = await getAuthBrokerClient(triggerAgent)
    if (!client) {
      process.stderr.write(
        `telegram gateway: [fleet-fallback] skipped agent=${triggerAgent} reason=no-broker-client\n`,
      )
      // The model-unavailable card may have promised an announcement —
      // keep the promise even though nothing could run.
      broadcastFleetFallbackFailure(triggerAgent, 'auth-broker unreachable (no client).')
      return false
    }
    const state = await client.listState()
    // Probe live quota via the broker (#1336). Pre-fix this read
    // credentials.json off the agent HOME, which is never populated
    // post-RFC-H — every account looked "no credentials" and the
    // fallback logic rolled blindly. Broker-routed probes use the
    // canonical stored tokens.
    const probeResp = state.accounts.length > 0
      ? await client.probeQuota(state.accounts.map((a) => a.label)).catch(() => ({ results: [] }))
      : { results: [] }
    const quotas = state.accounts.map((a) => {
      const hit = probeResp.results.find((r) => r.label === a.label)
      return hit?.result ?? { ok: false as const, reason: 'broker returned no result for account' }
    })
    const tz = process.env.SWITCHROOM_TIMEZONE ?? process.env.TZ ?? 'UTC'
    const outcome = await runFleetAutoFallback({
      state,
      quotas,
      // Non-admin swap: mark-exhausted derives the account from THIS agent's
      // own identity and rolls the fleet to the next fallback. Replaces the
      // admin-gated client.setActive(), which 403'd ("set-active requires
      // admin") for every non-admin agent — i.e. the whole production fleet —
      // so auto-fallback only ever worked when an admin agent happened to be
      // the one that 429'd. The manual /auth button stays on set-active (the
      // operator is explicitly choosing, and is admin); only this automatic
      // path moves to the non-admin verb.
      failover: async () => {
        // BOTH paths now pass a resolved `untilMs` via resolveExhaustUntil
        // (never undefined): the rate-limit-MENU path threads the parsed weekly
        // reset, and the 429 inference path threads parseResetTime's value or
        // the +7d floor when it's a weekly wall it can't parse. So a
        // weekly-capped account is never re-probed (and re-wedged) within the
        // broker's ~5h default.
        const r = await client.markExhausted(untilMs)
        return { rolledTo: r.rolledTo ?? null, rolled: r.rolled }
      },
      triggerAgent,
      tz,
    })
    process.stderr.write(
      `telegram gateway: [fleet-fallback] outcome=${outcome.kind} agent=${triggerAgent}` +
        (outcome.kind === 'switched' ? ` old=${outcome.oldLabel} new=${outcome.newLabel}` : '') +
        '\n',
    )
    // Bug 2 — the all-blocked card is a no-op outcome, so the gate's dedup
    // window never arms for it and the ~60s quota_wall_detected re-trigger would
    // re-broadcast the identical card every minute. Gate it behind a per-gateway
    // cooldown; a successful swap resets the window so a later (genuinely new)
    // all-blocked still emits promptly.
    if (outcome.kind === 'switched') {
      fallbackAllBlockedNoticeState = { lastSentAtMs: 0 }
    } else if (outcome.kind === 'all-blocked') {
      const verdict = evaluateAllBlockedNotice(fallbackAllBlockedNoticeState, Date.now())
      if (!verdict.send) {
        process.stderr.write(
          `telegram gateway: [fleet-fallback] all-blocked card suppressed (cooldown) agent=${triggerAgent}\n`,
        )
        return false
      }
      fallbackAllBlockedNoticeState = verdict.next
    }
    // Post the announcement to every authorized chat. Mirrors the
    // operator-event broadcast pattern (line ~2290) — DM-only opts
    // (no message_thread_id) so THREAD_NOT_FOUND can't fire here;
    // wrap in swallowingApiCall anyway per the codebase rule.
    const access = loadAccess()
    if (access.allowFrom.length === 0) return outcome.kind === 'switched'
    // Account-switch / all-blocked announcement is a system status notice,
    // not the user's answer — silence the open ping.
    const opts = { disable_notification: true }
    for (const chat_id of access.allowFrom) {
      void swallowingApiCall(
        // allow-raw-bot-api: wrapped in swallowingApiCall (retry policy)
        () => bot.api.sendRichMessage(chat_id, richMessage(outcome.announcement), opts),
        { chat_id, verb: 'fleet-fallback:notify' },
      )
    }
    // ── Resume the dead turn (auth-failover-stall fix) ──────────────────────
    // A mid-turn 429 killed a turn; the swap above moved the fleet to a healthy
    // account, but that only takes effect on the NEXT claude invocation. Re-run
    // the dead turn via triggerSelfRestart: the boot-resume path (gateway boot,
    // findLatestTurnIfInterrupted → buildResumeInterruptedInbound) replays the
    // LATEST interrupted turn on the freshly-active account. We restart rather
    // than redeliver because the failed inbound was already DELIVERED (the turn
    // started, then the model 429'd) so it is NOT in pendingInboundBuffer —
    // redeliverBufferedInbound would find nothing. Guards live in
    // fleetFallbackResumeGate: single-flight (a 429 storm cannot loop-restart)
    // + 3h staleness (an ancient interrupted turn is not resurrected). Only
    // reached on 'switched'; all-blocked / no-op outcomes never get here, so the
    // all-blocked cooldown path above is preserved.
    if (outcome.kind === 'switched') {
      const verdict = fleetFallbackResumeGate.decide(newestActiveTurnStartedAtMs())
      if (verdict === 'resume') {
        const selfAgent = process.env.SWITCHROOM_AGENT_NAME ?? triggerAgent
        process.stderr.write(
          `telegram gateway: [fleet-fallback] resuming dead turn via self-restart ` +
          `agent=${selfAgent} (swap ${outcome.oldLabel}→${outcome.newLabel})\n`,
        )
        triggerSelfRestart(selfAgent, 'fleet-fallback-resume')
      } else {
        process.stderr.write(
          `telegram gateway: [fleet-fallback] resume suppressed (${verdict}) agent=${triggerAgent}\n`,
        )
      }
    }
    return outcome.kind === 'switched'
  } catch (err) {
    process.stderr.write(
      `telegram gateway: [fleet-fallback] error agent=${triggerAgent}: ${(err as Error)?.message ?? err}\n`,
    )
    // Keep the card's "see the announcement below" promise on the error
    // path — the 06-06→07 incident sent 12 cards whose promised
    // announcement never arrived because this catch was log-only.
    broadcastFleetFallbackFailure(triggerAgent, (err as Error)?.message ?? String(err))
    return false
  }
}

/**
 * Credit-exhaustion watcher loop body (#348). Reads the agent's
 * `.claude.json` for `cachedExtraUsageDisabledReason`, evaluates the
 * transition against the last-notified state, and emits a Telegram
 * message via the existing access.allowFrom path when the state
 * crosses a fatal-billing boundary.
 *
 * Idempotent: if the state hasn't changed since the last check, no
 * message is sent. State persists across gateway restarts via
 * `<stateDir>/credits-watch.json` so a restart inside an out-of-credits
 * window doesn't re-spam the user.
 */
async function runCreditWatch(): Promise<void> {
  const agentDir = resolveAgentDirFromEnv()
  if (!agentDir) return // No TELEGRAM_STATE_DIR — no agent context to watch.
  const agentName = getMyAgentName()
  const claudeConfigDir = join(agentDir, '.claude')
  const stateDir = STATE_DIR
  const reason = readClaudeJsonOverage(claudeConfigDir)
  const prev = loadCreditState(stateDir)
  const decision = evaluateCreditState({
    agentName,
    currentReason: reason,
    prev,
    now: Date.now(),
    // Subscription-only: empty by default → extra-usage-off never alarms.
    // Opt back in via SWITCHROOM_CREDITS_WATCH_FATAL_REASONS. See credits-watch.ts.
    fatalReasons: resolveCreditWatchFatalReasons(process.env),
  })
  if (decision.kind === 'skip') {
    return
  }
  // Notify path. Send to all configured allowFrom chats — the
  // assumption mirrors auto-fallback's notification routing.
  const access = loadAccess()
  for (const chat_id of access.allowFrom) {
    // Credit-watch notify — best-effort. Wrap via swallowingApiCall so
    // flood-wait / deleted-chat / not-found surface as a stderr log
    // rather than a thrown exception that aborts the loop and leaves
    // half the allowFrom chats unnotified. Matches the wrapping
    // contract enforced by scripts/check-bot-api-wrapping.sh (#1075).
    await swallowingApiCall(
      () =>
        bot.api.sendRichMessage(chat_id, richMessage(decision.message), {
          // Credit/quota warning is a system status notice — silence the
          // open ping (the user isn't waiting to tap anything).
          disable_notification: true,
        }),
      { chat_id, verb: 'credit-watch.notify' },
    )
  }
  // Persist state regardless of whether send succeeded — losing a
  // notify is bad, but re-spamming on every poll tick is worse.
  try {
    saveCreditState(stateDir, decision.newState)
  } catch (err) {
    process.stderr.write(`telegram gateway: credit-watch state persist failed: ${err}\n`)
  }
}

/**
 * Quota threshold-tier push loop body (#E4). Reads the broker's in-memory
 * cached utilization (populated by previous probeQuota calls from /auth,
 * auto-fallback, and boot cards) via `listState.accounts[].last_quota`.
 * Classifies each account via classifyHealth, and fires one Telegram message
 * per healthy ↔ throttling transition (edge-triggered, not level-triggered).
 * Does NOT fire on healthy → blocked or blocked → healthy — credits-watch.ts
 * owns those.
 *
 * Probe discipline:
 *   - Steady-state polls: ONE broker `listState` IPC call only (no network).
 *   - Accounts with no cached snapshot (null last_quota): skipped silently
 *     (classifyHealth returns 'unknown'). Cache populates from /auth, boot
 *     card, and auto-fallback probes in normal use.
 *   - State transition detected: ONE targeted `probeQuota` call for ONLY the
 *     crossing account, immediately before sending the notification, to get
 *     fresh numbers for the message body. All other steady-state accounts
 *     are not probed.
 *
 * This replaces the previous implementation that called probeQuota for ALL
 * accounts unconditionally on every 15-minute poll (~768 live Anthropic
 * network calls/day for an 8-account fleet). The corrected version makes
 * 0 network calls on steady-state polls and at most 1 call per crossing
 * event (which is also when we need to notify the user anyway).
 *
 * State persists across restarts via `<stateDir>/quota-watch.json`.
 * Mirrors runCreditWatch's structure and notification routing.
 */

/**
 * Ask the broker for the fleet-wide dedup claim on one notification key.
 * FAIL-OPEN on any error: a broker that predates the `claim-notification`
 * op (skewed rollout) rejects at the protocol layer, and a transient IPC
 * failure must degrade to duplicated notifications, never dropped ones.
 */
async function claimQuotaNotification(
  brokerClient: NonNullable<Awaited<ReturnType<typeof getAuthBrokerClient>>>,
  key: string,
): Promise<boolean> {
  try {
    const res = await brokerClient.claimNotification(key, QUOTA_WATCH_CLAIM_WINDOW_MS)
    return res.granted
  } catch (err) {
    process.stderr.write(`telegram gateway: quota-watch: claim failed (fail-open): ${err}\n`)
    return true
  }
}

async function runQuotaWatch(opts: { bootTick?: boolean } = {}): Promise<void> {
  const agentName = getMyAgentName()
  const stateDir = STATE_DIR
  const bootTick = opts.bootTick ?? false
  // Hardening knobs (2026-06-09 incident: fleet bounce released stale
  // recovery latches on all 11 agents at once → 26 duplicate sends).
  // See QuotaWatchTuning in quota-watch.ts for the env contract.
  const tuning = resolveQuotaWatchTuning(process.env)

  // Read broker state. The listState response now includes last_quota
  // per account — the broker's in-memory cache from previous probeQuota
  // calls. This is a local IPC call: no network, no Anthropic contact.
  const brokerClient = await getAuthBrokerClient(agentName)
  if (!brokerClient) {
    process.stderr.write('telegram gateway: quota-watch: broker client unavailable — skipping\n')
    return
  }

  let listStateData: Awaited<ReturnType<typeof brokerClient.listState>>
  try {
    listStateData = await brokerClient.listState()
  } catch (err) {
    process.stderr.write(`telegram gateway: quota-watch: listState failed: ${err}\n`)
    return
  }

  if (!listStateData.accounts || listStateData.accounts.length === 0) {
    return // No accounts — nothing to watch.
  }

  // Build AccountSnapshot[] from cached broker state only — no live probe.
  // Accounts with null last_quota produce quota=null snapshots; classifyHealth
  // returns 'unknown'; evaluateQuotaWatchAccount skips — no false alarms.
  const snapshots = buildSnapshotsFromCachedState(listStateData)

  // Load persisted per-account state.
  let watchState = loadQuotaWatchState(stateDir)
  const now = Date.now()
  const access = loadAccess()

  // Fleet-wide all-exhausted check FIRST — must run before the per-account
  // early-return below. When every account is exhausted, the per-account loop
  // produces only 'blocked' skips → pendingTransitions empty → early return;
  // so this fleet-level alert (the one the trigger-based all-blocked card
  // misses during quiet periods / for the consumer+cron paths) would never
  // fire if placed after. Authoritative source: broker `exhausted` flags.
  {
    const fleetPrev = watchState[FLEET_ALL_EXHAUSTED_KEY] ?? emptyAccountState()
    const fleetDecision = evaluateFleetAllExhausted({
      accounts: listStateData.accounts,
      prev: fleetPrev,
      now,
      // #2478: the same staleness ceiling the per-account loop uses. Gates the
      // `entered` alert behind live corroboration so a probe blackout's stale
      // marks can't false-fire 🔴 All accounts exhausted.
      tuning,
    })
    if (fleetDecision.kind === 'notify') {
      for (const chat_id of access.allowFrom) {
        // Fleet-level dedup: all 11 gateways detect this same edge within
        // one poll cycle — only the broker-claim winner sends per chat.
        if (tuning.fleetDedup) {
          const granted = await claimQuotaNotification(
            brokerClient,
            buildQuotaClaimKey(FLEET_ALL_EXHAUSTED_KEY, fleetDecision.transition, chat_id),
          )
          if (!granted) {
            process.stderr.write(
              `telegram gateway: quota-watch: fleet-all-exhausted claim denied chat=${chat_id} — another agent notified\n`,
            )
            continue
          }
        }
        await swallowingApiCall(
          () =>
            bot.api.sendRichMessage(chat_id, richMessage(fleetDecision.message), {
              // Quota status notice — silence the open ping.
              disable_notification: true,
            }),
          { chat_id, verb: 'quota-watch.fleet-all-exhausted' },
        )
      }
      // Persist immediately — the per-account early-return path below would
      // otherwise drop this flag change (edge-trigger would re-fire next poll).
      watchState = patchQuotaWatchState(watchState, FLEET_ALL_EXHAUSTED_KEY, fleetDecision.newState)
      try {
        saveQuotaWatchState(stateDir, watchState)
      } catch (err) {
        process.stderr.write(`telegram gateway: quota-watch: fleet-state save failed: ${err}\n`)
      }
      process.stderr.write(
        `telegram gateway: quota-watch: fleet all-exhausted ${fleetDecision.transition}\n`,
      )
    }
  }

  // First pass: evaluate all accounts against cached state. Collect
  // labels that need a live probe (i.e. accounts with a detected transition
  // that we're about to notify about). We probe those to get fresh
  // utilization numbers for the notification body — not for classification.
  const pendingTransitions: Array<{
    accountLabel: string
    snapIndex: number
    decision: ReturnType<typeof evaluateQuotaWatchAccount>
  }> = []

  const labelToSnapIndex = new Map<string, number>(
    snapshots.map((s, i) => [s.label, i]),
  )

  // Reconciled transitions: state advances (latch clears) but nothing is
  // sent — boot-tick and late recoveries (see QuotaWatchDecision docs).
  let reconciledCount = 0
  let mutatedState = watchState

  for (const snap of snapshots) {
    const prev = watchState[snap.label] ?? emptyAccountState()
    const decision = evaluateQuotaWatchAccount({ agentName, snap, prev, now, bootTick, tuning })
    if (decision.kind === 'reconcile') {
      mutatedState = patchQuotaWatchState(mutatedState, decision.accountLabel, decision.newAccountState)
      reconciledCount++
      process.stderr.write(
        `telegram gateway: quota-watch: reconciled ${decision.transition} for account=${decision.accountLabel} (${decision.reason}) — no notification\n`,
      )
    } else if (decision.kind !== 'skip') {
      pendingTransitions.push({
        accountLabel: snap.label,
        snapIndex: labelToSnapIndex.get(snap.label) ?? -1,
        decision,
      })
    }
  }

  if (pendingTransitions.length === 0) {
    // Steady-state: no notifications, no probes. Persist only if a
    // reconcile advanced the latch (otherwise no state write at all).
    if (reconciledCount > 0) {
      try {
        saveQuotaWatchState(stateDir, mutatedState)
      } catch (err) {
        process.stderr.write(`telegram gateway: quota-watch state persist failed: ${err}\n`)
      }
    }
    return
  }

  // Transition detected: probe ONLY the crossing accounts to get fresh
  // numbers for the notification message bodies. One batched RPC for all
  // crossing accounts (typically 1, rarely 2+).
  const crossingLabels = pendingTransitions.map(t => t.accountLabel)
  // #2495 BLOCKER fix — store the FULL entry (result + `served` tag), not just
  // `entry.result`. The corroboration gate below needs `served` to tell a true
  // live probe apart from a failed-probe cache fallback (which is `ok:true`
  // but `served:"cache"` — vacuous corroboration).
  let freshProbeMap = new Map<string, Awaited<ReturnType<typeof brokerClient.probeQuota>>['results'][number]>()
  try {
    // #2495 Change 3 — forceLive bypasses the broker's probe-on-open TTL so the
    // DECISION to alarm is corroborated by a TRUE live probe, never a cache hit.
    // Only the transition-to-alarm pays for this; steady-state polls stay on the
    // cheap cached listState read (no probe). Honors the existing fleet/consumer
    // probe knobs upstream — this re-evaluation never fires without a detected
    // transition.
    const probeData = await brokerClient.probeQuota(crossingLabels, 8000, true)
    for (const entry of probeData.results) {
      freshProbeMap.set(entry.label, entry)
    }
  } catch (err) {
    process.stderr.write(`telegram gateway: quota-watch: probe for crossing accounts failed: ${err}\n`)
    if (!tuning.sendOnProbeFail) {
      // A quota notification must never carry numbers we could not verify
      // live. Leave the crossing accounts' state untouched — the
      // transition re-evaluates (and re-probes) on the next 15-min tick.
      // Persist any reconciles already applied, then bail.
      if (reconciledCount > 0) {
        try {
          saveQuotaWatchState(stateDir, mutatedState)
        } catch (saveErr) {
          process.stderr.write(`telegram gateway: quota-watch state persist failed: ${saveErr}\n`)
        }
      }
      process.stderr.write(
        `telegram gateway: quota-watch: deferring ${pendingTransitions.length} notification(s) until probe succeeds\n`,
      )
      return
    }
    // Legacy (SWITCHROOM_QUOTA_WATCH_SEND_ON_PROBE_FAIL=1): fall through
    // and send from cached data.
  }

  // Build final notifications, enriching the snapshot with fresh probe
  // data where available.
  const notifications: Array<{ message: string; accountLabel: string; transition: string }> = []

  for (const { accountLabel, snapIndex, decision } of pendingTransitions) {
    // Re-evaluate with fresh probe data to get an accurate message body.
    // If the fresh probe succeeded, replace the snap's quota with live data.
    const freshEntry = freshProbeMap.get(accountLabel)
    let enrichedDecision = decision
    // pendingTransitions only ever holds notify decisions (pushed under
    // `decision.kind !== 'skip'` / `!== 'reconcile'`). Narrow explicitly so
    // `decision.transition` type-checks below; this continue never fires
    // at runtime.
    if (decision.kind !== 'notify') continue
    // #2495 BLOCKER fix — only a GENUINE live probe corroborates the alarm. A
    // forceLive entry that is `ok:true` but `served:"cache"` (the broker's
    // failed-probe cache fallback) is NOT corroboration: the upstream probe
    // failed, so we have no live confirmation that the throttling crossing is
    // real right now. Treat it exactly like a probe failure → fall through to
    // the defer branch below (state untouched, re-evaluated next tick). This
    // also guarantees the "Live-probe corroborated (#2495)" footnote is only
    // ever stamped on a real live probe.
    if (isLiveCorroboration(freshEntry) && freshEntry!.result.ok && snapIndex >= 0) {
      // Live numbers replace the cache — and capturedAtMs is cleared so the
      // staleness gate never misfires on data we JUST probed.
      const enrichedSnap = { ...snapshots[snapIndex]!, quota: freshEntry!.result.data, capturedAtMs: undefined }
      const prev = watchState[accountLabel] ?? emptyAccountState()
      const re = evaluateQuotaWatchAccount({ agentName, snap: enrichedSnap, prev, now, bootTick, tuning })
      // If the fresh probe still shows the same transition, use the
      // enriched message. If it no longer shows a transition (e.g. the
      // account recovered in the 100ms between listState and probe),
      // fall through to skip this notification.
      if (re.kind === 'notify' && re.transition === decision.transition) {
        enrichedDecision = re
      } else if (re.kind === 'reconcile') {
        // Fresh data confirms the transition but it isn't news (boot-tick /
        // late recovery) — advance the latch silently.
        mutatedState = patchQuotaWatchState(mutatedState, accountLabel, re.newAccountState)
        reconciledCount++
        process.stderr.write(
          `telegram gateway: quota-watch: reconciled ${re.transition} for account=${accountLabel} (${re.reason}) — no notification\n`,
        )
        continue
      } else if (re.kind === 'skip') {
        // State normalised by the time of the probe — don't notify.
        continue
      }
    } else if (!tuning.sendOnProbeFail) {
      // No verified fresh data for this account (per-account probe failure
      // or label missing from the batch result). Same rule as the batch
      // throw above: never send unverified numbers. State untouched —
      // re-evaluated (and re-probed) next tick.
      process.stderr.write(
        `telegram gateway: quota-watch: probe unavailable for account=${accountLabel} — deferring notification\n`,
      )
      continue
    }

    if (enrichedDecision.kind !== 'notify') continue
    notifications.push({
      message: enrichedDecision.message,
      accountLabel,
      transition: enrichedDecision.transition,
    })
    mutatedState = patchQuotaWatchState(mutatedState, accountLabel, enrichedDecision.newAccountState)
  }

  if (notifications.length === 0) {
    // All transitions resolved/deferred by the time of the live probe.
    // Reconciles may still have advanced the latch — persist those.
    if (reconciledCount > 0) {
      try {
        saveQuotaWatchState(stateDir, mutatedState)
      } catch (err) {
        process.stderr.write(`telegram gateway: quota-watch state persist failed: ${err}\n`)
      }
    }
    return
  }

  // Send all notifications (one message per crossing account).
  for (const { message, accountLabel, transition } of notifications) {
    for (const chat_id of access.allowFrom) {
      // Fleet-level dedup: every agent gateway independently detects the
      // same account transition within one poll cycle. The broker claim
      // grants exactly one sender per (account, transition, chat) per
      // window — the other ten agents advance their local state silently.
      // Fail-open on claim error (see claimQuotaNotification).
      if (tuning.fleetDedup) {
        const granted = await claimQuotaNotification(
          brokerClient,
          buildQuotaClaimKey(accountLabel, transition, chat_id),
        )
        if (!granted) {
          process.stderr.write(
            `telegram gateway: quota-watch: claim denied account=${accountLabel} chat=${chat_id} — another agent notified\n`,
          )
          continue
        }
      }
      // Quota-watch notify — best-effort. Wrap via swallowingApiCall so
      // flood-wait / deleted-chat / not-found surface as a stderr log
      // rather than a thrown exception that aborts the loop and leaves
      // half the allowFrom chats unnotified. Matches the wrapping
      // contract enforced by scripts/check-bot-api-wrapping.sh (#1075).
      await swallowingApiCall(
        () =>
          bot.api.sendRichMessage(chat_id, richMessage(message), {
            // Quota throttling status notice — silence the open ping.
            disable_notification: true,
          }),
        { chat_id, verb: 'quota-watch.notify' },
      )
    }
    process.stderr.write(`telegram gateway: quota-watch: notified transition for account=${accountLabel}\n`)
  }

  // Persist updated state regardless of whether sends succeeded.
  try {
    saveQuotaWatchState(stateDir, mutatedState)
  } catch (err) {
    process.stderr.write(`telegram gateway: quota-watch state persist failed: ${err}\n`)
  }
}

/**
 * Edit a Microsoft connect card from the BACKGROUND device-code poll
 * (no `ctx` — we hold the chat+message id). Wrapped in robustApiCall;
 * swallows failures (a deleted card / closed topic must not crash the
 * poll). RFC #1873 Phase 2.
 */
async function editMicrosoftConnectCard(
  chatId: number | string,
  messageId: number,
  html: string,
): Promise<void> {
  await robustApiCall(
    // allow-raw-bot-api: background connect-card edit by message id (no thread_id; not the reply chunk loop)
    () => bot.api.editMessageText(chatId, messageId, richMessage(html), {
      link_preview_options: { is_disabled: true },
    }),
    { chat_id: String(chatId), verb: 'microsoftConnectCard' },
  ).catch(() => {})
}

/**
 * Background half of `/connect microsoft`: poll Microsoft for consent,
 * register the account with the broker, then edit the card to the
 * outcome. Fire-and-forget from the command handler.
 */
async function finalizeMicrosoftConnect(key: string): Promise<void> {
  const flow = pendingMicrosoftConnectFlows.get(key)
  if (!flow) return
  const agentName = getMyAgentName()
  const result = await runMicrosoftConnectPoll(flow)
  // A `/connect cancel` (command or button) between consent and write
  // already edited the card and dropped the entry — don't clobber it.
  if (result.kind === 'cancelled' || !pendingMicrosoftConnectFlows.has(key)) {
    pendingMicrosoftConnectFlows.delete(key)
    return
  }
  pendingMicrosoftConnectFlows.delete(key)

  let html: string
  if (result.kind === 'connected') {
    html =
      `✅ **Connected** \`${result.account}\` ` +
      `(${result.accountType}).\n\n` +
      `To let **${escapeHtmlForTg(agentName)}** use it, run on the host:\n` +
      `\`switchroom auth microsoft enable ${escapeHtmlForTg(result.account)} ${escapeHtmlForTg(agentName)}\`\n` +
      `then restart ${escapeHtmlForTg(agentName)}.`
  } else if (result.kind === 'no-refresh-token') {
    html =
      `⚠ Microsoft returned no refresh token (the account would expire in ~1h), ` +
      `so it was not registered. Try \`/connect microsoft\` again, or ` +
      `connect from the host CLI.`
  } else {
    html =
      `❌ **Connect failed:** ${escapeHtmlForTg(result.message)}\n\n` +
      `_Work/school accounts can't use the phone flow at /common — connect those ` +
      `from the host: \`switchroom auth microsoft account add <email>\`._`
  }
  await editMicrosoftConnectCard(flow.cardChatId, flow.cardMessageId, html)
}

/**
 * `/connect microsoft` — Telegram-native device-code connect for a
 * Microsoft account (RFC #1873 Phase 2). The user signs in on their
 * phone; we register the account with the auth-broker (shipped default
 * app unless the operator BYO'd one). Admin-gated like `/auth add`.
 * `/connect cancel` aborts a pending flow. Google stays host-CLI.
 */
bot.command('connect', async ctx => {
  // Credential-plane admin is OPERATOR-PRIVATE (WS7-F2 / #1408), exactly
  // like `/auth`: honor `/connect` ONLY in a private chat from a strict
  // `access.allowFrom` sender — never the group-permissive
  // `isAuthorizedSender` (an empty group `allowFrom` = allow-all, so a
  // forum member could otherwise bind THEIR OWN Microsoft account as the
  // agent's credential). The agent-`admin:true` flag check below is
  // orthogonal and the broker enforces it server-side on add-account.
  const senderId = String(ctx.from?.id ?? '')
  const operatorPrivate =
    ctx.chat?.type === 'private' && loadAccess().allowFrom.includes(senderId)
  if (!operatorPrivate) {
    if (ctx.chat?.type !== 'private') {
      process.stderr.write(
        `telegram gateway: /connect refused (not operator-private) agent=${process.env.SWITCHROOM_AGENT_NAME ?? '-'} chat=${ctx.chat?.type ?? '?'} sender=${senderId}\n`,
      )
      await switchroomReply(
        ctx,
        `⚠️ \`/connect\` links account credentials — it is **operator-private**. ` +
          `Send it as a direct message to me from your operator account (a private chat where ` +
          `your Telegram ID is on the access allowlist), not in a group or forum.`,
        { html: true },
      ).catch(() => {})
    }
    return
  }

  const arg = String(ctx.match ?? '').trim().toLowerCase()
  const chatId = String(ctx.chat?.id ?? '')
  const key = chatKey(chatId, ctx.message?.message_thread_id ?? null) as string

  // Agent-`admin:true` gate (orthogonal to operator-private above; same
  // source as /auth + the broker's server-side add-account enforcement).
  let isAdmin = false
  try {
    const cfg = loadSwitchroomConfig()
    const me = (cfg as unknown as { agents?: Record<string, { admin?: boolean; root?: boolean }> })
      ?.agents?.[getMyAgentName()]
    // `root: true` (the root-tier debugging agent) is above admin and
    // carries admin authority — see docs/root-agent.md.
    isAdmin = me?.admin === true || me?.root === true
  } catch { /* non-admin is the safe default */ }
  if (!isAuthAdmin({ isAdmin })) {
    await switchroomReply(
      ctx,
      `**Not authorized.** \`/connect\` requires this agent to have ` +
        `\`admin: true\` in switchroom.yaml.`,
      { html: true },
    )
    return
  }

  if (arg === 'cancel') {
    const existing = pendingMicrosoftConnectFlows.get(key)
    if (!existing) {
      await switchroomReply(ctx, '_No pending connect flow in this chat._', { html: true })
      return
    }
    existing.cancelled = true
    pendingMicrosoftConnectFlows.delete(key)
    await switchroomReply(ctx, 'Cancelled.', { html: true })
    return
  }

  if (arg !== '' && arg !== 'microsoft' && arg !== 'ms') {
    await switchroomReply(
      ctx,
      `**Usage:** \`/connect microsoft\` to link a Microsoft account ` +
        `(Outlook / Office 365), or \`/connect cancel\`.\n` +
        `_Google accounts are connected from the host CLI._`,
      { html: true },
    )
    return
  }

  if (pendingMicrosoftConnectFlows.has(key)) {
    await switchroomReply(
      ctx,
      '_A Microsoft connect flow is already in progress here. Finish it on your phone, ' +
        'or send \`/connect cancel\`._',
      { html: true },
    )
    return
  }

  let configClientId: string | undefined
  let orgMode = false
  try {
    const cfg = loadSwitchroomConfig() as unknown as {
      microsoft_workspace?: { microsoft_client_id?: string; org_mode?: boolean }
    }
    configClientId = cfg?.microsoft_workspace?.microsoft_client_id
    orgMode = cfg?.microsoft_workspace?.org_mode === true
  } catch { /* fall back to the shipped default */ }

  const started = await startMicrosoftConnect({ configClientId, orgMode })
  if (started.kind === 'byo-vault') {
    await switchroomReply(
      ctx,
      `**Can't connect from chat:** this install uses a vaulted custom Microsoft ` +
        `app (\`${started.ref}\`) only the host CLI can read. ` +
        `Run \`switchroom auth microsoft account add <email>\` on the host.`,
      { html: true },
    )
    return
  }
  if (started.kind === 'error') {
    await switchroomReply(
      ctx,
      `**/connect failed:** ${escapeHtmlForTg(started.message)}`,
      { html: true },
    )
    return
  }

  const appNote =
    started.source === 'default'
      ? "_Using switchroom's shipped Microsoft app._"
      : '_Using your configured Microsoft app._'
  const keyboard = new InlineKeyboard()
    .url('🔐 Sign in to Microsoft', started.device.verification_uri)
    .row()
    .text('✖ Cancel', `cn:cancel:${key}`)
  const sent = await ctx.replyWithRichMessage(
    richMessage(
      `🔗 **Connect a Microsoft account**\n\n` +
      `1. Tap **Sign in to Microsoft** below.\n` +
      `2. Enter this code: \`${started.device.user_code}\`\n` +
      `3. Approve the requested permissions (Mail, Calendar, Files).\n\n` +
      `I'll confirm here once it's connected (within ~15 min).\n${appNote}`,
    ),
    {
      reply_markup: keyboard,
      ...(ctx.message?.message_thread_id != null
        ? { message_thread_id: ctx.message.message_thread_id }
        : {}),
    },
  )

  pendingMicrosoftConnectFlows.set(key, {
    initiatedBy: String(ctx.from?.id ?? ''),
    cardChatId: ctx.chat!.id,
    cardMessageId: sent.message_id,
    device: started.device,
    clientId: started.clientId,
    scopes: started.scopes,
    startedAt: Date.now(),
    cancelled: false,
  })

  // Background: poll Microsoft, register the account, edit the card.
  void finalizeMicrosoftConnect(key)
})

bot.command("auth", async ctx => {
  // sec WS7-F2b (#1394): `/auth` drives the auth-broker credential
  // lifecycle (`/auth add` mints/attaches an Anthropic account token,
  // `/auth use` switches the active account, …). It is NOT in
  // ADMIN_COMMAND_NAMES (deliberately gateway-handled even on
  // non-admin agents so it works when the model is unreachable — that
  // routing is unchanged), so the WS7-F2 operator-private middleware
  // does not cover it, and its only sender gate was the
  // group-permissive `isAuthorizedSender` (empty group `allowFrom` =
  // allow every member). On an `admin:true` forum agent any
  // forum/supergroup member could therefore run privileged `/auth`.
  // Credential-plane admin is OPERATOR-PRIVATE, exactly like the
  // ADMIN_COMMAND_NAMES verbs (WS7-F2 / #1408): honor `/auth` ONLY in
  // a private chat from a strict `access.allowFrom` sender — never the
  // group-permissive isAuthorizedSender. The agent-admin-flag /
  // broker-side enforcement (isAuthAdmin below) is orthogonal and
  // unchanged; operator auth-recovery is via DM (same as #1408).
  const authSenderId = String(ctx.from?.id ?? '')
  const authOperatorPrivate =
    ctx.chat?.type === 'private' &&
    loadAccess().allowFrom.includes(authSenderId)
  if (!authOperatorPrivate) {
    if (ctx.chat?.type !== 'private') {
      process.stderr.write(
        `telegram gateway: /auth refused (not operator-private) agent=${process.env.SWITCHROOM_AGENT_NAME ?? '-'} chat=${ctx.chat?.type ?? '?'} sender=${authSenderId}\n`,
      )
      await switchroomReply(
        ctx,
        `⚠️ \`/auth\` manages account credentials — it is **operator-private**. Send it as a direct message to me from your operator account (a private chat where your Telegram ID is on the access allowlist), not in a group or forum.`,
        { html: true },
      ).catch(() => {})
    }
    return
  }
  const rawText = ctx.message?.text ?? ""
  // `/auth demo` (and `/auth show demo` / `/auth list demo`) — the trailing
  // `demo` token masks account-email labels on the default dashboard view for
  // screen recordings. Strip it before parsing so `demo` isn't mistaken for a
  // verb/agent argument; it's honored only on the show/list path downstream.
  const authDemo = hasDemoFlag(getCommandArgs(ctx))
  const text = authDemo ? rawText.replace(/(\s+)demo\s*$/i, "") : rawText
  const parsed = parseAuthCommand(text)
  if (!parsed) return
  const currentAgent = getMyAgentName()
  // Post-unification admin gating: admin authority is sourced from each
  // agent's own `admin: true` flag (the same flag that gates /agents,
  // /restart, /update etc. per PR #1258). The gateway looks itself up
  // and passes a boolean through — handler-side code does not consult
  // any list. The broker enforces server-side from the same source.
  let isAdmin = false
  try {
    const cfg = loadSwitchroomConfig()
    const me = (cfg as unknown as { agents?: Record<string, { admin?: boolean; root?: boolean }> })?.agents?.[currentAgent]
    // `root: true` (the root-tier debugging agent) is above admin and
    // carries admin authority — see docs/root-agent.md.
    isAdmin = me?.admin === true || me?.root === true
  } catch { /* best-effort — non-admin is the safe default */ }

  // `/auth add` and `/auth cancel` are gateway-routed (drive a
  // scratch-dir-backed `claude setup-token` lifecycle the broker
  // client can't model). Everything else delegates to
  // handleAuthCommand which only needs the narrow broker surface.
  const chatId = String(ctx.chat?.id ?? '')
  if (parsed.kind === 'add' || parsed.kind === 'cancel') {
    if (!isAuthAdmin({ isAdmin })) {
      await switchroomReply(
        ctx,
        `**Not authorized.** \`/auth ${parsed.kind}\` is admin-only.\n` +
          `Set \`admin: true\` on this agent in switchroom.yaml to unlock ` +
          `(the same flag that gates \`/agents\`, \`/restart\`, ` +
          `\`/update\` etc.).`,
        { html: true },
      )
      return
    }
    // PR3 supergroup-mode: key auth-add flows by (chat, thread) so
    // separate flows in two topics of one supergroup can't collide.
    // In DM chats message_thread_id is undefined → key collapses to
    // `chatId:_`, identical to today's behavior.
    const authAddKey = chatKey(chatId, ctx.message?.message_thread_id ?? null) as string
    if (parsed.kind === 'cancel') {
      const existing = pendingAuthAddFlows.get(authAddKey)
      if (!existing) {
        await switchroomReply(ctx, "_No pending \`/auth add\` flow in this chat._", { html: true })
        return
      }
      cancelAccountAuthSession(existing)
      pendingAuthAddFlows.delete(authAddKey)
      await switchroomReply(ctx, "Cancelled.", { html: true })
      return
    }
    // parsed.kind === 'add'
    if (pendingAuthAddFlows.has(authAddKey)) {
      await switchroomReply(
        ctx,
        "_An \`/auth add\` flow is already in progress for this chat. " +
          "Finish the paste, or send \`/auth cancel\` to abort._",
        { html: true },
      )
      return
    }
    try {
      const { loginUrl, scratchDir, tmuxSocket, tmuxSession } = await startAccountAuthSession(parsed.label)
      pendingAuthAddFlows.set(authAddKey, {
        label: parsed.label,
        scratchDir,
        tmuxSocket,
        tmuxSession,
        startedAt: Date.now(),
      })
      await switchroomReply(
        ctx,
        `**Adding account** \`${parsed.label}\`\n\n` +
          `1. Open this URL on your phone:\n${loginUrl}\n\n` +
          `2. Log into Anthropic, copy the code Claude shows.\n` +
          `3. Paste it back here.\n\n` +
          `Send \`/auth cancel\` to abort.`,
        { html: true },
      )
    } catch (err) {
      await switchroomReply(
        ctx,
        `**/auth add failed:** ${escapeHtmlForTg((err as Error)?.message ?? String(err))}`,
        { html: true },
      )
    }
    return
  }

  const client = await getAuthBrokerClient(currentAgent)
  if (!client) {
    await switchroomReply(ctx, "**/auth unavailable:** auth-broker client is not loaded (post-RFC-H rewire in progress?).", { html: true })
    return
  }
  const reply = await handleAuthCommand(parsed, {
    agentName: currentAgent,
    isAdmin,
    client,
    chatId,
    demo: authDemo,
    // Format 2 enricher — live quota probe via the broker (#1336).
    // Pre-broker this read `~/.switchroom/accounts/<label>/credentials.json`
    // off the agent's HOME, which post-RFC-H is never populated (broker
    // writes only the per-agent .claude/.credentials.json mirror) — so
    // every account showed "no credentials.json or accessToken" in
    // /auth show. The broker is the source of truth for tokens and now
    // does the Anthropic probe server-side via `probe-quota`. Tokens
    // never leave the broker container.
    liveQuotas: async (accounts) => {
      try {
        const { results } = await client.probeQuota(accounts.map((a) => a.label))
        // #2495 Change 2 — the broker tags each result `served:"live"|"cache"`
        // (TTL hit or failed-probe fallback). When ANY account was served from
        // cache, surface the OLDEST snapshot's capturedAt so the card stamps
        // "⚠ cached Nm ago" instead of a false live stamp.
        let staleCachedAtMs: number | undefined
        // Preserve input order (broker also preserves it, but be defensive).
        const quotas = accounts.map((a) => {
          const hit = results.find((r) => r.label === a.label)
          if (!hit) return { ok: false as const, reason: "broker returned no result for account" }
          if (hit.served === 'cache' && hit.capturedAt != null) {
            staleCachedAtMs = staleCachedAtMs == null ? hit.capturedAt : Math.min(staleCachedAtMs, hit.capturedAt)
          }
          return hit.result
        })
        return { quotas, staleCachedAtMs }
      } catch (err) {
        // Surface a uniform per-account failure so the dashboard renders
        // gracefully (label badge stays UNKNOWN) instead of falling back
        // to the legacy table.
        const reason = `broker probe-quota failed: ${(err as Error)?.message ?? String(err)}`
        return { quotas: accounts.map(() => ({ ok: false as const, reason })) }
      }
    },
    tz: process.env.SWITCHROOM_TIMEZONE ?? process.env.TZ,
  })
  // Translate the handler's optional keyboard shape into grammy's
  // `reply_markup`. Buttons with `callbackData` become callback_data;
  // buttons with `insertText` become switch_inline_query_current_chat
  // (taps paste the slash-command into the user's input). Keep a
  // safe default for buttons missing both (shouldn't happen).
  if (reply.keyboard && reply.keyboard.length > 0) {
    // Build via grammy's InlineKeyboard so the type is correct
    // for switchroomReply's reply_markup field — no `as never`
    // cast needed.
    const kb = new InlineKeyboard()
    for (let i = 0; i < reply.keyboard.length; i++) {
      const row = reply.keyboard[i]!
      for (const b of row) {
        if (b.callbackData) kb.text(b.text, b.callbackData)
        else if (b.insertText) kb.switchInlineCurrent(b.text, b.insertText)
        else kb.text(b.text, 'auth:noop')
      }
      // grammy's row terminator — except after the last row.
      if (i < reply.keyboard.length - 1) kb.row()
    }
    await switchroomReply(ctx, reply.text, {
      html: reply.html,
      reply_markup: kb,
    })
  } else {
    await switchroomReply(ctx, reply.text, { html: reply.html })
  }
})

// Boot-card auth-row loader (issue #708, RFC H rewire). Queries the
// broker for `list-state` and hands the raw shape to the boot card,
// which delegates rendering to `renderAuthLine`. Returns null on any
// failure so the boot card silently omits the section.
async function loadAccountsForBootCard(agent: string): Promise<ListStateData | null> {
  try {
    const client = await getAuthBrokerClient(agent)
    if (!client) return null
    return await client.listState()
  } catch (err) {
    process.stderr.write(`telegram gateway: boot-card auth probe failed: ${(err as Error)?.message ?? String(err)}\n`)
    return null
  }
}

/**
 * Canonical boot-card quota probe (#1336): resolve this agent's
 * effective account, then have the broker probe Anthropic server-side.
 * Returns null on any failure (broker unreachable, no active account)
 * so `probeQuota` falls back to a direct probe. Mirrors
 * `loadAccountsForBootCard`'s broker-client + swallow-to-null shape,
 * and the override→account→active resolution used by auth-line.ts.
 */
async function probeQuotaForBootCard(
  agent: string,
  timeoutMs?: number,
): Promise<QuotaResult | null> {
  try {
    const client = await getAuthBrokerClient(agent)
    if (!client) return null
    const state = await client.listState()
    const entry = state.agents.find((a) => a.name === agent)
    const label = entry?.override ?? entry?.account ?? state.active
    if (!label) return null
    const { results } = await client.probeQuota([label], timeoutMs)
    return results.find((r) => r.label === label)?.result ?? null
  } catch (err) {
    process.stderr.write(`telegram gateway: boot-card quota probe failed: ${(err as Error)?.message ?? String(err)}\n`)
    return null
  }
}

/**
 * Read the pending auth session's target slot from the agent's
 * `.setup-token.session.json` meta file. Returns null when no session
 * is pending.
 */
function readPendingSessionSlot(agent: string): string | null {
  try {
    const agentDir = resolveAgentDirForName(agent)
    if (!agentDir) return null
    const metaPath = join(agentDir, '.claude', '.setup-token.session.json')
    const raw = readFileSync(metaPath, 'utf-8')
    const meta = JSON.parse(raw) as { slot?: string }
    return meta.slot ?? 'default'
  } catch {
    return null
  }
}

/**
 * Resolve the agent directory for a given name. Tries the local
 * SWITCHROOM_CONFIG-driven lookup first, falls back to scanning
 * known agent-root paths. Used by dashboard path probing without
 * blowing up when configs are split across roots (klanker setup).
 */
function resolveAgentDirForName(agent: string): string | null {
  try {
    // If this gateway is scoped to a specific agent, prefer that.
    if (agent === getMyAgentName()) {
      return resolveAgentDirFromEnv()
    }
  } catch { /* ignore */ }
  // Common split-root layout for klanker.
  const candidates = [
    join(process.env.HOME ?? '/root', `.switchroom-${agent}/agents/${agent}`),
    join(process.env.HOME ?? '/root', `.switchroom/agents/${agent}`),
  ]
  for (const c of candidates) {
    try { readFileSync(join(c, '.claude', 'settings.json'), 'utf-8'); return c } catch { /* try next */ }
  }
  return null
}

/**
 * Handle a callback_query from an auth dashboard button. Parses the
 * callback_data, runs the matching action, acknowledges the tap with a
 * toast, and refreshes the dashboard in-place via editMessageText.
 */
/**
 * Handle op:<action>:<encoded-agent> callbacks from operator-events.ts
 * renderOperatorEvent(). Phase 4b — closes the "buttons do nothing" gap.
 *
 * Actions:
 *   dismiss   — clear keyboard + toast
 *   restart   — systemctl --user restart switchroom-<agent>
 *   reauth    — delegate to runSwitchroomAuthCommand (same flow as /auth reauth)
 *   logs      — post last 30 lines of journalctl for the agent
 *   slot management buttons — removed (E5); use /auth use or /auth add instead.
 */
/**
 * Issue #44: handle taps on the deferred-secret card's inline buttons.
 *
 *   `vd:unlock:<deferKey>` — register a `passphrase-for-deferred` pending
 *      vault op and edit the card to ask the user for their passphrase.
 *      The text-handler picks the passphrase up via the existing
 *      pendingVaultOps intercept and calls `executeDeferredSecretSave`
 *      to write the held secret directly. No re-paste required.
 *
 *   `vd:cancel:<deferKey>` — drop the deferred secret and clear the card.
 *      The held bytes are evicted from the in-memory `deferredSecrets`
 *      map (they were never written to disk) so the secret vanishes.
 *
 * Authorization mirrors the operator-event callback: only senders on the
 * configured allowlist get to act on the buttons.
 */
/**
 * Issue #969 P1a — handle the agent-initiated vault-save approval card
 * (`vault_request_save` MCP tool).
 *
 * Callbacks:
 *   vrs:save:<stageId>     — confirm save; write to vault using broker put
 *                            with operator-passphrase attestation (#969 P1a)
 *                            so even new keys go through in one tap.
 *   vrs:discard:<stageId>  — drop the staged secret; never touches disk.
 *   vrs:rename:<stageId>   — set up a pending-op intercept so the user's
 *                            next message is taken as a new key name.
 */
/**
 * Issue #969 P2b — handle a tap on the "🔓 Allow <key>" button posted by
 * `/vault audit <agent>`'s Recent denials section. Mints a 30-day
 * read-grant for the agent + key via the broker.
 *
 * The grant also unioning into the agent's existing token if one is
 * already present is out of scope for this PR — the operator can
 * re-mint with a wider key list if they want consolidation.
 */
async function handleVaultRecentDenialCallback(ctx: Context, data: string): Promise<void> {
  const senderId = String(ctx.from?.id ?? '')
  const access = loadAccess()
  if (!access.allowFrom.includes(senderId)) {
    await ctx.answerCallbackQuery({ text: 'Not authorized.' }).catch(() => {})
    return
  }
  // vrd:<agent>:<key>  — parse, validate both halves against the strict
  // slug regex before doing anything else.
  const parts = data.split(':')
  if (parts.length !== 3) {
    await ctx.answerCallbackQuery({ text: 'Bad request' }).catch(() => {})
    return
  }
  const [, agentName, keyName] = parts
  if (!/^[a-z][a-z0-9-]{0,62}$/i.test(agentName)) {
    await ctx.answerCallbackQuery({ text: 'Invalid agent name' }).catch(() => {})
    return
  }
  // #1047: same canonical key shape as vault_request_save /
  // vault_request_access — namespaced keys like `fatsecret/client_id`
  // must round-trip through the /vault audit one-tap Allow flow too,
  // not just the agent-initiated approval cards.
  if (!VAULT_KEY_REGEX.test(keyName)) {
    await ctx.answerCallbackQuery({ text: 'Invalid key name' }).catch(() => {})
    return
  }
  await ctx.answerCallbackQuery({ text: '⏳ Minting 30-day read grant…' }).catch(() => {})

  const result = await mintGrantViaBroker({
    agent: agentName,
    keys: [keyName],
    ttl_seconds: 30 * 24 * 60 * 60,
    description: `auto-mint via /vault audit one-tap (#969 P2b)`,
  })

  if (result.kind === 'unreachable') {
    await switchroomReply(ctx, `🔴 Broker unreachable: ${escapeHtmlForTg(result.msg)}`, { html: true })
    return
  }
  if (result.kind === 'error') {
    await switchroomReply(ctx, `**mint_grant failed:** ${escapeHtmlForTg(result.msg)}`, { html: true })
    return
  }
  // Write the token to the agent's .vault-token file — same flow as the
  // vault grant wizard. The agent restarts in the background pick up
  // the new token via SWITCHROOM_AGENT_NAME on next CLI invocation.
  const { token, id } = result
  const tokenPath = join(homedir(), '.switchroom', 'agents', agentName, '.vault-token')
  try {
    mkdirSync(join(homedir(), '.switchroom', 'agents', agentName), { recursive: true })
    writeFileSync(tokenPath, token, { mode: 0o600 })
  } catch (err) {
    await switchroomReply(
      ctx,
      `**Grant created (${escapeHtmlForTg(id)}) but token write failed:** ` +
      `${escapeHtmlForTg(String(err))}\n` +
      `_Recover with: \`switchroom vault grant ${escapeHtmlForTg(agentName)} ` +
      `--keys ${escapeHtmlForTg(keyName)} --duration 30d\` on the host._`,
      { html: true },
    )
    return
  }
  // #1150 audit: P0 fix — pre-fix the audit-listing message kept its
  // tappable [Always allow ...] buttons after a successful mint, so
  // the operator could re-tap the same denial and re-mint the grant
  // (broker idempotency saves us from a duplicate write but the
  // operator experience was "did anything happen? let me tap again").
  // Strip the entire audit-listing keyboard on first tap + append a
  // status line so the action is visible. Operator re-runs `/vault
  // audit` to act on remaining denials — that's the documented flow.
  // HTML-escape the source text before concatenation. `ctx.callbackQuery.
  // message.text` returns the body with entities STRIPPED (Telegram
  // decodes the original HTML), so any raw `<`, `>`, `&` in agent/key
  // names that survived the original audit-listing's escape pass would
  // now break the HTML re-parse — and finalizeCallback's catch swallows
  // the failure, leaving the keyboard tappable. Caught in PR #1158 review
  // for the operator-event card; the same fix applies here.
  const sourceMsg = ctx.callbackQuery?.message
  const baseText = sourceMsg && 'text' in sourceMsg && sourceMsg.text
    ? escapeHtmlForTg(sourceMsg.text)
    : ''
  const statusLine =
    `\n\n✅ **${escapeHtmlForTg(agentName)}** granted read access to ` +
    `\`${keyName}\` for 30 days ` +
    `(grant \`${id}\`). ` +
    `Re-run /vault audit to act on remaining denials.`
  await finalizeCallback(ctx, {
    ackText: '✅ Grant minted',
    newText: baseText ? `${baseText}${statusLine}` : statusLine,
    // No synthInbound — operator-only flow. The granted agent picks
    // up the token via .vault-token file on next CLI invocation; no
    // turn-wake needed.
  })
}

/**
 * Issue #1012 — handle a tap on the vault_request_access approval card.
 *   vra:approve:<stageId> — mint a scoped grant token via the broker,
 *                           write the token to the agent's
 *                           `.vault-token` file, edit card to success.
 *   vra:deny:<stageId>    — drop the staged request, edit card to denied.
 *
 * Same authorization gate as the recent-denials one-tap handler:
 * sender must be on the gateway's allowFrom list.
 */
/**
 * Mint the scoped grant + write the token file for an approved
 * `vault_request_access` request. Factored out so both the direct
 * approve-tap (passphrase already cached) and the
 * `passphrase-for-access-approve` resume flow (passphrase captured
 * via text-message intercept after tap-on-locked) drive identical
 * minting behaviour. #1012 Phase 2 + follow-up.
 */
/**
 * #1115 follow-up: caller-supplied attestation. Either a real operator
 * passphrase (when the operator typed it in chat) or a posture flag
 * that tells the broker to use its own retained passphrase under
 * `vault.broker.approvalAuth: telegram-id`. The passphrase variant
 * never crosses into telegram-id callsites; the posture variant
 * never crosses into passphrase-mode callsites.
 */
type AccessApprovalAttestation =
  | { kind: 'passphrase'; passphrase: string }
  | { kind: 'posture' }

async function performVaultAccessApproval(
  ctx: Context,
  pending: PendingVaultRequestAccess,
  stageId: string,
  senderId: string,
  attestation: AccessApprovalAttestation,
): Promise<void> {
  const brokerAuthOpts =
    attestation.kind === 'passphrase'
      ? { passphrase: attestation.passphrase }
      : { attest_via_posture: true as const }

  // Fix B (#1487 follow-up), operator-tap guard. Defense-in-depth for a
  // card staged before the key became standing-ACL-covered (config edit
  // / #1487 deploy / drift): if the agent's standing ACL ALREADY covers
  // this read key, do NOT mint — minting writes a `.vault-token` that
  // shadows the standing ACL and is redundant. Authoritative broker
  // probe AS THIS AGENT (no-token list over the per-agent socket — same
  // rationale as executeVaultRequestAccess; never a gateway-side config
  // read). Read scope only. Fail-open on probe error (mint as before).
  if (pending.scope === 'read') {
    try {
      const visible = await listViaBroker()
      if (visible !== null && visible.includes(pending.key)) {
        pendingVaultRequestAccesses.delete(stageId)
        if (pending.card_message_id != null) {
          await ctx.api
            .editMessageText(
              pending.chat_id,
              pending.card_message_id,
              `ℹ️ **${escapeHtmlForTg(pending.agent)}** already has standing-ACL access to ` +
              `\`${pending.key}\` (schedule.secrets[]). ` +
              `**No grant minted** — a token would shadow the standing ACL. ` +
              richMessage(`The agent can read it directly.`),
              { reply_markup: { inline_keyboard: [] } },
            )
            .catch(() => {})
        }
        return
      }
    } catch {
      // Probe failed: fall through and mint as before (fail-open).
    }
  }

  // #1051: union the new key with the agent's existing active grant
  // before minting. Without this, each fresh Approve OVERWRITES the
  // agent's `.vault-token` file with a single-key grant — the
  // previous approval's grant is still in the broker DB but the
  // agent can no longer authenticate against it (the CLI reads the
  // file's current token, the broker validates it, sees the new key
  // isn't in the OLD grant's key_allow, and denies).
  //
  // Solution: list the agent's existing non-expired grants
  // (passphrase-attested per #1051's broker-side gate widening),
  // find the active read-grant (most recent non-revoked,
  // non-expired), and pass its keys ∪ new_key as `keys` to the
  // mint call. Old grant ages out via TTL — no explicit revoke
  // needed.
  let existingReadKeys: string[] = [];
  let existingWriteKeys: string[] = [];
  if (pending.scope === 'read' || pending.scope === 'write') {
    const list = await listGrantsViaBroker(pending.agent, brokerAuthOpts);
    if (list.kind === 'ok') {
      const now = Math.floor(Date.now() / 1000);
      // Prefer the MOST RECENT non-revoked, non-expired grant. The
      // broker's listGrants returns ALL non-revoked, but we still
      // filter expires_at locally as defence-in-depth + sort by
      // created_at desc for stability.
      const active = list.grants
        .filter((g) => g.expires_at === null || g.expires_at > now)
        // Reviewer-flagged on #1058 (Q4): `created_at` is
        // seconds-granularity, so two grants minted in the same
        // wall-clock second tie. Secondary sort by `id` (vg_<6hex>)
        // makes the ordering stable so item 2's drain reliably picks
        // up item 1's just-minted grant rather than an unrelated
        // same-second grant.
        .sort((a, b) => {
          const dt = (b.created_at ?? 0) - (a.created_at ?? 0);
          if (dt !== 0) return dt;
          return b.id.localeCompare(a.id);
        });
      if (active.length > 0) {
        existingReadKeys = active[0]!.key_allow ?? [];
        existingWriteKeys = active[0]!.write_allow ?? [];
      }
    }
    // If list fails (broker unreachable / error), proceed without
    // union — better to mint a single-key grant than fail closed
    // entirely. The agent loses the prior coverage in that edge
    // case, same as today, but the new key is granted.
  }

  // Compute the unioned key sets. Use Set to dedupe.
  const readKeys = new Set<string>(existingReadKeys);
  const writeKeys = new Set<string>(existingWriteKeys);
  if (pending.scope === 'read') readKeys.add(pending.key);
  if (pending.scope === 'write') writeKeys.add(pending.key);

  const mintArgs: Parameters<typeof mintGrantViaBroker>[0] = {
    agent: pending.agent,
    keys: Array.from(readKeys),
    ttl_seconds: pending.ttl_seconds,
    description:
      `auto-mint via vault_request_access (#1012, scope=${pending.scope}, by op ${senderId}` +
      (existingReadKeys.length + existingWriteKeys.length > 0
        ? `, unioned with prior grant`
        : ``) +
      `)`,
    ...(writeKeys.size > 0 ? { write_keys: Array.from(writeKeys) } : {}),
    ...brokerAuthOpts,
  }
  const result = await mintGrantViaBroker(mintArgs)
  if (result.kind === 'unreachable') {
    await switchroomReply(ctx, `🔴 Broker unreachable: ${escapeHtmlForTg(result.msg)}`, { html: true })
    return
  }
  if (result.kind === 'error') {
    // Mint refused (most likely wrong passphrase). Drop the staged
    // request so a re-attempt starts cleanly. The operator can ask
    // the agent to re-issue, or the broker error message will tell
    // them the next step.
    pendingVaultRequestAccesses.delete(stageId)
    if (pending.card_message_id != null) {
      await ctx.api
        .editMessageText(
          pending.chat_id,
          pending.card_message_id,
          richMessage(`**mint_grant failed:** ${escapeHtmlForTg(result.msg)}`),
          { reply_markup: { inline_keyboard: [] } },
        )
        .catch(() => {})
    }
    return
  }

  const { token, id } = result
  const tokenPath = join(homedir(), '.switchroom', 'agents', pending.agent, '.vault-token')
  try {
    mkdirSync(join(homedir(), '.switchroom', 'agents', pending.agent), { recursive: true })
    writeFileSync(tokenPath, token, { mode: 0o600 })
  } catch (err) {
    await switchroomReply(
      ctx,
      `**Grant created (${escapeHtmlForTg(id)}) but token write failed:** ` +
      `${escapeHtmlForTg(String(err))}\n` +
      `_Recover with: \`switchroom vault grant ${escapeHtmlForTg(pending.agent)} ` +
      `--keys ${escapeHtmlForTg(pending.key)} --duration ${Math.round(pending.ttl_seconds / 86400)}d\` on the host._`,
      { html: true },
    )
    return
  }

  pendingVaultRequestAccesses.delete(stageId)
  if (pending.card_message_id != null) {
    const days = Math.round(pending.ttl_seconds / 86400)
    const footer =
      VAULT_APPROVAL_AUTH_MODE === 'telegram-id'
        ? `\n_Approver verified by Telegram identity — broker auto-unlocked at startup._`
        : ''
    await ctx.api
      .editMessageText(
        pending.chat_id,
        pending.card_message_id,
        richMessage(
          buildVaultGrantApprovedCardText({
            agentEscaped: escapeHtmlForTg(pending.agent),
            scope: pending.scope,
            key: pending.key,
            days,
            grantId: id,
            footer,
          }),
        ),
        { reply_markup: { inline_keyboard: [] } },
      )
      .catch(() => {})
  }

  // #1052: deliver a synthetic inbound message back to the agent so
  // the task that fired vault_request_access auto-resumes — without
  // this, the agent's turn ended after the tool call ("waiting for
  // approval") and the operator has to send a fresh message to kick
  // it back into action.
  //
  // Uses the existing inject_inbound primitive (cron's pattern from
  // dispatch.ts:180-206). The bridge sees a normal channel event,
  // renders it as `<channel source="vault_grant_approved">`, and the
  // agent starts a new turn with the context that the operator just
  // approved.
  //
  // The synthetic message text is concise + actionable so the agent
  // knows (a) which key was approved, (b) at what scope, (c) what to
  // do next. Meta carries the structured fields for forensics + for
  // future filters that want to suppress these in the chat tail.
  const synthetic = buildVaultGrantApprovedInbound({
    ctx: {
      agent: pending.agent,
      key: pending.key,
      scope: pending.scope,
      chat_id: pending.chat_id,
      ttl_seconds: pending.ttl_seconds,
      ...(pending.threadId != null ? { threadId: pending.threadId } : {}),
    },
    grantId: id,
    stageId,
    operatorId: senderId,
  })
  // Turn-gated via deliverResumeSyntheticOrBuffer: mid-turn → buffer
  // (flushed at turn-end) so the resume never strands in claude's
  // composer (#1556); idle → deliver; bridge-down → buffer (#1150).
  const delivered = deliverResumeSyntheticOrBuffer(pending.agent, synthetic)
  process.stderr.write(
    `telegram gateway: vault_grant_approved injection agent=${pending.agent} ` +
    `key=${pending.key} stage=${stageId} delivered=${delivered}\n`,
  )
}

/**
 * #2670 — handle an Approve / Dismiss tap on a one-tap skill-improvement
 * proposal card.
 *
 *   Approve → mark the proposal approved + inject a synthetic
 *             `skill_proposal_apply` turn instructing the live agent to
 *             write the stored draft through `skill_*_personal` (so the
 *             secret-scan pipeline runs; agent never self-applies).
 *   Dismiss → mark rejected + write a rejection fingerprint so the weekly
 *             synthesis cron doesn't re-propose it.
 */
async function handleSkillProposalCallback(ctx: Context, data: string): Promise<void> {
  const senderId = String(ctx.from?.id ?? '')
  const access = loadAccess()
  if (!access.allowFrom.includes(senderId)) {
    await ctx.answerCallbackQuery({ text: 'Not authorized.' }).catch(() => {})
    return
  }
  const parsed = parseSkillProposalCallback(data)
  if (parsed == null) {
    await ctx.answerCallbackQuery({ text: 'Bad request' }).catch(() => {})
    return
  }
  const stateDir = process.env.TELEGRAM_STATE_DIR
  const agent = process.env.SWITCHROOM_AGENT_NAME ?? ''
  if (stateDir == null || stateDir.length === 0) {
    await ctx.answerCallbackQuery({ text: 'State dir unset — cannot apply.' }).catch(() => {})
    return
  }
  const proposal = getSkillProposal(stateDir, parsed.id)
  if (proposal == null) {
    await ctx.answerCallbackQuery({ text: 'Proposal expired or already actioned.' }).catch(() => {})
    if (ctx.callbackQuery?.message) {
      await ctx.editMessageReplyMarkup({ reply_markup: { inline_keyboard: [] } }).catch(() => {})
    }
    return
  }
  if (proposal.status !== 'pending') {
    await ctx.answerCallbackQuery({ text: `Already ${proposal.status}.` }).catch(() => {})
    if (ctx.callbackQuery?.message) {
      await ctx.editMessageReplyMarkup({ reply_markup: { inline_keyboard: [] } }).catch(() => {})
    }
    return
  }

  const cbChatId = String(ctx.chat?.id ?? ctx.from?.id ?? '')
  const cbThreadId = resolveThreadId(cbChatId, ctx.callbackQuery?.message?.message_thread_id)

  if (parsed.action === 'deny') {
    setSkillProposalStatus(stateDir, parsed.id, 'rejected')
    await ctx.answerCallbackQuery({ text: '🚫 Dismissed — won’t be proposed again.' }).catch(() => {})
    if (ctx.callbackQuery?.message && 'text' in ctx.callbackQuery.message) {
      await ctx
        .editMessageText(
          `${escapeHtmlForTg(ctx.callbackQuery.message.text ?? '')}\n\n🚫 <i>Dismissed.</i>`,
          { parse_mode: 'HTML', reply_markup: { inline_keyboard: [] } },
        )
        .catch(() => {})
    }
    return
  }

  // Approve.
  setSkillProposalStatus(stateDir, parsed.id, 'approved')
  const synthetic = buildSkillProposalApplyInbound({
    ctx: {
      agent,
      chat_id: cbChatId,
      ...(cbThreadId != null ? { threadId: cbThreadId } : {}),
    },
    proposalId: proposal.id,
    skillSlug: proposal.skill_slug,
    isNew: proposal.is_new,
    operatorId: senderId,
  })
  const delivered = deliverResumeSyntheticOrBuffer(agent, synthetic)
  await ctx.answerCallbackQuery({ text: '✅ Applying the skill…' }).catch(() => {})
  if (ctx.callbackQuery?.message && 'text' in ctx.callbackQuery.message) {
    await ctx
      .editMessageText(
        `${escapeHtmlForTg(ctx.callbackQuery.message.text ?? '')}\n\n✅ <i>Approved — applying.</i>`,
        { parse_mode: 'HTML', reply_markup: { inline_keyboard: [] } },
      )
      .catch(() => {})
  }
  process.stderr.write(
    `telegram gateway: skill_proposal_apply injection agent=${agent} ` +
    `proposal=${proposal.id} slug=${proposal.skill_slug} delivered=${delivered}\n`,
  )
}

async function handleVaultRequestAccessCallback(ctx: Context, data: string): Promise<void> {
  const senderId = String(ctx.from?.id ?? '')
  const access = loadAccess()
  if (!access.allowFrom.includes(senderId)) {
    await ctx.answerCallbackQuery({ text: 'Not authorized.' }).catch(() => {})
    return
  }
  const parts = data.split(':')
  if (parts.length < 3) {
    await ctx.answerCallbackQuery({ text: 'Bad request' }).catch(() => {})
    return
  }
  const action = parts[1]
  const stageId = parts.slice(2).join(':')
  const pending = pendingVaultRequestAccesses.get(stageId)
  if (!pending) {
    await ctx.answerCallbackQuery({ text: 'Card expired — ask the agent to re-request.' }).catch(() => {})
    if (ctx.callbackQuery?.message) {
      await ctx.api
        .editMessageText(
          ctx.callbackQuery.message.chat.id,
          ctx.callbackQuery.message.message_id,
          richMessage('⌛ _This access-request card expired before you tapped. Ask the agent to re-issue if the need still stands._'),
          { reply_markup: { inline_keyboard: [] } },
        )
        .catch(() => {})
    }
    return
  }

  if (action === 'deny') {
    pendingVaultRequestAccesses.delete(stageId)
    await ctx.answerCallbackQuery({ text: '🚫 Denied' }).catch(() => {})
    if (pending.card_message_id != null) {
      await ctx.api
        .editMessageText(
          pending.chat_id,
          pending.card_message_id,
          richMessage(`🚫 _Denied. **${escapeHtmlForTg(pending.agent)}** will not get access to \`${pending.key}\`._`),
          { reply_markup: { inline_keyboard: [] } },
        )
        .catch(() => {})
    }
    // #1150 sibling: invariant-3 was missing on the deny path too. The
    // agent originally ended its turn after `vault_request_access` and
    // waits for the gateway to wake it. On approve we already inject
    // `vault_grant_approved` (#1052); now we mirror that for deny so
    // the agent can pick the fallback path (apologise to the user,
    // try a different approach, skip the feature) instead of staying
    // wedged forever. Buffer-on-failure so a mid-reconnect bridge
    // still receives this on its next register.
    const denyInbound = buildVaultGrantDeniedInbound({
      ctx: {
        agent: pending.agent,
        key: pending.key,
        scope: pending.scope,
        chat_id: pending.chat_id,
        ttl_seconds: pending.ttl_seconds,
        ...(pending.threadId != null ? { threadId: pending.threadId } : {}),
      },
      stageId,
      operatorId: senderId,
    })
    const denyDelivered = deliverResumeSyntheticOrBuffer(pending.agent, denyInbound)
    process.stderr.write(
      `telegram gateway: vault_grant_denied injection agent=${pending.agent} ` +
      `key=${pending.key} stage=${stageId} delivered=${denyDelivered}\n`,
    )
    return
  }

  if (action === 'approve') {
    // Admin-only credentials (`vault.broker.adminOnlyKeys`) are held to a
    // higher bar: ONLY the admin operator (allowFrom[0]) may approve, and
    // the grant must be minted with the operator passphrase — never
    // posture, even under telegram-id mode (the broker enforces the same
    // rule, so a posture mint would just be rejected). So for an
    // admin-only key we (a) reject taps from any non-admin allowFrom
    // member, and (b) skip the telegram-id posture branch below, falling
    // through to the passphrase-prompt path. The card + buttons stay
    // intact on a non-admin tap so the admin can still approve.
    const isAdminOnly = matchesAdminOnlyKey(pending.key, ADMIN_ONLY_KEYS)
    if (isAdminOnly && senderId !== access.allowFrom[0]) {
      await ctx
        .answerCallbackQuery({
          text: '🔒 Admin-only credential — only the owner can approve this.',
        })
        .catch(() => {})
      return
    }

    // Posture: telegram-id (opt-in single-factor). The broker is
    // auto-unlocked and we silently hold the passphrase in memory; skip
    // the passphrase-cache lookup + prompt entirely and mint directly.
    // Allowlist check above already attested the operator's Telegram ID.
    // Admin-only keys are excluded — they take the passphrase path below.
    if (!isAdminOnly && VAULT_APPROVAL_AUTH_MODE === 'telegram-id') {
      const username = ctx.from?.username ?? ctx.from?.first_name ?? `id=${senderId}`
      if (pending.card_message_id != null) {
        await ctx.api
          .editMessageText(
            pending.chat_id,
            pending.card_message_id,
            richMessage(`✅ Approved by @${escapeHtmlForTg(username)} — minting…`),
            { reply_markup: { inline_keyboard: [] } },
          )
          .catch(() => {})
      }
      await ctx.answerCallbackQuery({ text: '⏳ Minting grant…' }).catch(() => {})
      await performVaultAccessApproval(ctx, pending, stageId, senderId, { kind: 'posture' })
      return
    }

    // Tap-to-unlock-and-approve: if the operator hasn't unlocked the
    // vault in this chat yet, capture the passphrase via a pending op
    // intercept and resume the approve flow automatically once it
    // arrives — no second tap, no separate /vault unlock detour.
    // Mirrors the `passphrase-for-deferred` flow from #44.
    const cached = vaultPassphraseCache.get(pending.chat_id)
    if (!cached || cached.expiresAt <= Date.now()) {
      if (pending.card_message_id == null) {
        await ctx
          .answerCallbackQuery({ text: 'Card missing — ask the agent to re-issue.' })
          .catch(() => {})
        return
      }
      // #1051: if there's ALREADY a passphrase-for-access-approve
      // pending op for this chat (operator tapped Approve on a
      // sibling card before typing the passphrase), APPEND this
      // stage to the existing queue instead of overwriting. When
      // the passphrase reply lands the text-handler drains every
      // queued stage — both cards get their grant minted off one
      // passphrase entry. Without this, the second Approve tap
      // orphans the first stage.
      const existing = pendingVaultOps.get(pending.chat_id)
      const newItem = {
        stageId,
        cardChatId: pending.chat_id,
        cardMessageId: pending.card_message_id,
        senderId,
      }
      const items =
        existing?.kind === 'passphrase-for-access-approve'
          ? [...existing.items.filter((it) => it.stageId !== stageId), newItem]
          : [newItem]
      pendingVaultOps.set(pending.chat_id, {
        kind: 'passphrase-for-access-approve',
        items,
        startedAt: existing?.kind === 'passphrase-for-access-approve' ? existing.startedAt : Date.now(),
      })
      // Card text differs slightly when joining an existing batch so
      // the operator isn't confused by two "Reply with passphrase"
      // cards open at once.
      const joiningBatch = items.length > 1
      await ctx.answerCallbackQuery({ text: joiningBatch ? `🔐 Queued — one passphrase covers ${items.length} cards` : '🔐 Send your passphrase…' }).catch(() => {})

      // Strip the buttons on the ORIGINAL card and mark it "waiting" so it
      // can't be re-tapped, but do NOT overload it as the passphrase prompt.
      // An in-place edit fires no notification and stays pinned to the card's
      // old position in the chat, so a busy topic buries it and the operator
      // never sees the passphrase ask — the exact admin-key miss this fixes
      // (v0.16.45: the prompt scrolled off, the passphrase never arrived, the
      // grant was never minted). The prompt goes out as a fresh message below.
      await ctx.api
        .editMessageText(
          pending.chat_id,
          pending.card_message_id,
          richMessage(`🔐 _Approved — waiting for your vault passphrase. See the prompt below._`),
          { reply_markup: { inline_keyboard: [] } },
        )
        .catch(() => {})

      // The passphrase prompt as a NEW rich message. Three fixes vs. the old
      // in-place edit, all of which the reported bug needed:
      //   1. Real bold/italic — rendered through the sanctioned `richMessage`
      //      GFM path (`sendRichMessage`), never a raw string. The old admin
      //      and joining-batch branches passed raw markdown to editMessageText
      //      (parse_mode=none), so `**`/`_` rendered as literal characters;
      //      the "locked" branch even concatenated a string with a
      //      `richMessage()` object (→ `[object Object]`). All three are gone.
      //   2. It lands at the BOTTOM of the chat, not stapled to an old card
      //      that later messages bury.
      //   3. It fires a notification — `disable_notification` is deliberately
      //      NOT set — so the operator is actually pinged to act.
      // Attention-grabbing header, short lines, key in code formatting.
      const promptText = joiningBatch
        ? `**⚠️🔐 ACTION NEEDED: passphrase required**\n\n` +
          `Type your vault passphrase as your **next message**.\n` +
          `One entry covers **${items.length}** pending approvals in this chat, no re-type per card.\n\n` +
          `_We delete the passphrase message the moment we read it._`
        : isAdminOnly
        ? `**⚠️🔐 ACTION NEEDED: passphrase required**\n\n` +
          `\`${pending.key}\` is an **admin-only credential**.\n` +
          `Type your vault passphrase as your **next message** to mint the grant for **${escapeHtmlForTg(pending.agent)}**.\n\n` +
          `_The passphrase is what proves it's you. An agent can never mint this key on its own. We delete the passphrase message the moment we read it._`
        : `**⚠️🔐 ACTION NEEDED: passphrase required**\n\n` +
          `Your vault is locked.\n` +
          `Reply with your passphrase as your **next message** to unlock and mint the grant for **${escapeHtmlForTg(pending.agent)}**.\n\n` +
          `_Mint authority stays operator-only: the broker only accepts the grant when the passphrase matches. We delete the passphrase message the moment we read it._`

      // #1075: deleted-topic safe — fall back to the main chat. Wrapped
      // through robustApiCall for flood-wait retries, mirroring the card send.
      await retryWithThreadFallback<{ message_id: number }>(
        robustApiCall,
        (tid) =>
          lockedBot.api.sendRichMessage(pending.chat_id, richMessage(promptText), {
            ...(tid != null && Number.isFinite(tid) ? { message_thread_id: tid } : {}),
          }),
        { threadId: pending.threadId, chat_id: pending.chat_id, verb: 'vault_request_access.passphrase_prompt' },
      ).catch(() => {})
      return
    }

    await ctx.answerCallbackQuery({ text: '⏳ Minting grant…' }).catch(() => {})
    await performVaultAccessApproval(ctx, pending, stageId, senderId, { kind: 'passphrase', passphrase: cached.passphrase })
    return
  }

  await ctx.answerCallbackQuery({ text: 'Unknown action' }).catch(() => {})
}

async function handleVaultRequestSaveCallback(ctx: Context, data: string): Promise<void> {
  const senderId = String(ctx.from?.id ?? '')
  const access = loadAccess()
  if (!access.allowFrom.includes(senderId)) {
    await ctx.answerCallbackQuery({ text: 'Not authorized.' }).catch(() => {})
    return
  }

  const parts = data.split(':')
  if (parts.length < 3) {
    await ctx.answerCallbackQuery({ text: 'Bad request' }).catch(() => {})
    return
  }
  const action = parts[1]
  const stageId = parts.slice(2).join(':')
  const pending = pendingVaultRequestSaves.get(stageId)
  if (!pending) {
    await ctx.answerCallbackQuery({ text: 'Card expired — ask the agent to re-send.' }).catch(() => {})
    if (ctx.callbackQuery?.message) {
      await ctx.api
        .editMessageText(
          ctx.callbackQuery.message.chat.id,
          ctx.callbackQuery.message.message_id,
          richMessage('⌛ _This vault-save card expired before you tapped. Ask the agent to re-issue if you still want to save._'),
          { reply_markup: { inline_keyboard: [] } },
        )
        .catch(() => {})
    }
    return
  }

  if (action === 'discard') {
    pendingVaultRequestSaves.delete(stageId)
    await ctx.answerCallbackQuery({ text: '🚫 Discarded' }).catch(() => {})
    if (pending.card_message_id != null) {
      await ctx.api
        .editMessageText(
          pending.chat_id,
          pending.card_message_id,
          richMessage(`🚫 _Discarded. The secret was not written to the vault._`),
          { reply_markup: { inline_keyboard: [] } },
        )
        .catch(() => {})
    }
    // Wake the agent that called vault_request_save — symmetric with
    // the vra: approve/deny path (#1052/#1150/#1156). Without this the
    // tool returned "waiting for operator", the turn ended, and a
    // Discard left the agent silently idle forever.
    const discardInbound = buildVaultSaveDiscardedInbound({
      ctx: {
        agent: pending.agent,
        key: pending.key,
        chat_id: pending.chat_id,
        ...(pending.threadId != null ? { threadId: pending.threadId } : {}),
      },
      stageId,
      operatorId: senderId,
    })
    const dDelivered = deliverResumeSyntheticOrBuffer(pending.agent, discardInbound)
    process.stderr.write(
      `telegram gateway: vault_save_discarded injection agent=${pending.agent} ` +
      `key=${pending.key} stage=${stageId} delivered=${dDelivered}\n`,
    )
    return
  }

  if (action === 'rename') {
    // Set up a pending-op intercept so the user's next message is read
    // as the new key name. Same shape as the existing /vault set value
    // capture (gateway.ts uses pendingVaultOps for this).
    pendingVaultOps.set(pending.chat_id, {
      kind: 'rename-vault-save',
      stageId,
      startedAt: Date.now(),
    } as PendingVaultOp)
    // #1150 audit P0: pre-fix the [Save once][Discard][Rename] keyboard
    // stayed live after the rename tap so the operator could re-tap
    // Save with the old key name mid-rename — a Save tap fires the
    // write immediately, racing the rename intercept. Strip the
    // keyboard atomically with a status line that names the rename
    // mode + the proposed new-key prompt. No synthInbound — the
    // agent's `vault_request_save` tool already returned "waiting
    // for operator," and the eventual save success/failure flows
    // its own wake-up below.
    const sourceMsg = ctx.callbackQuery?.message
    const baseText = sourceMsg && 'text' in sourceMsg && sourceMsg.text
      ? escapeHtmlForTg(sourceMsg.text)
      : ''
    const statusLine =
      `\n\n✏️ **Rename mode** — send the new key name as your next message. ` +
      `The current proposed key is \`${pending.key}\`.`
    await finalizeCallback(ctx, {
      ackText: 'Send the new key name as your next message.',
      newText: baseText ? `${baseText}${statusLine}` : statusLine,
    })
    return
  }

  if (action === 'save') {
    // Acknowledge the tap immediately so Telegram doesn't show a
    // stale "spinning" state on the button while we run the write.
    await ctx.answerCallbackQuery({ text: '⏳ Saving…' }).catch(() => {})

    // #1115 follow-up: the save-approve flow now mirrors the access-
    // approve flow under telegram-id mode — broker `put` accepts
    // `attest_via_posture: true` (server.ts:1448-1500), so the
    // gateway can attest the write without a cached passphrase.
    // Closes the UX gap where tapping Save surfaced a misleading
    // "🔒 Vault is locked" message even when the broker had been
    // auto-unlocked at boot.
    //
    // Branch: under telegram-id mode use the posture-attested put;
    // under passphrase mode keep the existing cached-passphrase +
    // shell-to-CLI path (operator must `/vault unlock` once per
    // chat session to populate `vaultPassphraseCache`).
    let write: { ok: boolean; output: string }
    if (VAULT_APPROVAL_AUTH_MODE === 'telegram-id') {
      // Posture-attested broker put. No passphrase needed. The broker
      // verifies (a) telegram-id mode, (b) per-agent peer, (c) broker
      // unlocked — see server.ts:1448-1500.
      write = await defaultVaultWritePosture(pending.key, pending.value)
    } else {
      // Passphrase mode — fetch the cached passphrase for this chat.
      // If the gateway hasn't seen the user unlock the vault yet, we
      // can't attest the write — surface the unlock prompt.
      const cached = vaultPassphraseCache.get(pending.chat_id)
      if (!cached || cached.expiresAt <= Date.now()) {
        if (pending.card_message_id != null) {
          await ctx.api
            .editMessageText(
              pending.chat_id,
              pending.card_message_id,
              richMessage(`🔒 **Passphrase not cached for this chat.** Run \`/vault unlock\` (or any /vault command) to cache it, then tap Save again on the next card.`),
              { reply_markup: { inline_keyboard: [] } },
            )
            .catch(() => {})
        }
        pendingVaultRequestSaves.delete(stageId)
        return
      }
      // defaultVaultWrite spawns `switchroom vault set <key>` with the
      // passphrase env set; the CLI forwards the passphrase to the
      // broker put as operator-attestation (#969 P1a), which authorizes
      // new-key creation.
      write = defaultVaultWrite(pending.key, pending.value, cached.passphrase)
    }

    if (!write.ok) {
      // Route through the structured-error renderer from #969 P0b so
      // failures show the actionable host hint instead of a raw blob.
      const parsed = parseVaultCliError(write.output)
      const rendered = renderVaultCliError(parsed, { verb: 'save', key: pending.key })
      const body = rendered.suppressRaw
        ? rendered.html
        : `⚠️ vault write failed:\n\`\`\`\n${write.output}\n\`\`\``
      if (pending.card_message_id != null) {
        await ctx.api
          .editMessageText(
            pending.chat_id,
            pending.card_message_id,
            richMessage(`${body}\n\n_Tap a fresh card after fixing the underlying issue._`),
            { reply_markup: { inline_keyboard: [] } },
          )
          .catch(() => {})
      }
      // Leave the staged secret in memory until TTL — operator might
      // retry by re-invoking the same MCP tool, but the value will be
      // re-staged with a new ID. Drop the current stage.
      pendingVaultRequestSaves.delete(stageId)
      // Wake the waiting agent with the failure (symmetric with the
      // success/discard paths) so it doesn't assume vault:<key> exists.
      const failReason =
        (write.output || 'vault write error').split('\n')[0]!.slice(0, 200)
      const failInbound = buildVaultSaveFailedInbound({
        ctx: {
          agent: pending.agent,
          key: pending.key,
          chat_id: pending.chat_id,
          ...(pending.threadId != null ? { threadId: pending.threadId } : {}),
        },
        stageId,
        operatorId: senderId,
        reason: failReason,
      })
      const fDelivered = deliverResumeSyntheticOrBuffer(pending.agent, failInbound)
      process.stderr.write(
        `telegram gateway: vault_save_failed injection agent=${pending.agent} ` +
        `key=${pending.key} stage=${stageId} delivered=${fDelivered}\n`,
      )
      return
    }

    // Success — mask the value in the card for visual confirmation.
    pendingVaultRequestSaves.delete(stageId)
    if (pending.card_message_id != null) {
      await ctx.api
        .editMessageText(
          pending.chat_id,
          pending.card_message_id,
          richMessage(`✅ saved as \`vault:${escapeHtmlForTg(pending.key)}\` (masked: \`${escapeHtmlForTg(maskToken(pending.value))}\`)\n_The agent can now reference this as \`vault:${escapeHtmlForTg(pending.key)}\`._`),
          { reply_markup: { inline_keyboard: [] } },
        )
        .catch(() => {})
    }
    // Wake the agent that called vault_request_save so it resumes the
    // task that was blocked on this credential (symmetric with the
    // vra: approve path; buffered if the bridge is mid-reconnect).
    const okInbound = buildVaultSaveCompletedInbound({
      ctx: {
        agent: pending.agent,
        key: pending.key,
        chat_id: pending.chat_id,
        ...(pending.threadId != null ? { threadId: pending.threadId } : {}),
      },
      stageId,
      operatorId: senderId,
    })
    const okDelivered = deliverResumeSyntheticOrBuffer(pending.agent, okInbound)
    process.stderr.write(
      `telegram gateway: vault_save_completed injection agent=${pending.agent} ` +
      `key=${pending.key} stage=${stageId} delivered=${okDelivered}\n`,
    )
    return
  }

  await ctx.answerCallbackQuery({ text: 'Unknown action' }).catch(() => {})
}

async function handleVaultDeferCallback(ctx: Context, data: string): Promise<void> {
  const senderId = String(ctx.from?.id ?? '')
  const access = loadAccess()
  if (!access.allowFrom.includes(senderId)) {
    await ctx.answerCallbackQuery({ text: 'Not authorized.' }).catch(() => {})
    return
  }
  // vd:<action>:<deferKey>. deferKey itself contains a colon (chat:msgId)
  // so we slice rather than split — only the first two segments are
  // structural; the rest is the deferKey verbatim.
  const rest = data.slice('vd:'.length)
  const colon = rest.indexOf(':')
  if (colon < 0) {
    await ctx.answerCallbackQuery({ text: 'Malformed callback.' }).catch(() => {})
    return
  }
  const action = rest.slice(0, colon)
  const deferKey = rest.slice(colon + 1)
  const deferred = deferredSecrets.get(deferKey)
  if (!deferred) {
    await ctx.answerCallbackQuery({ text: 'This card expired. Re-send the secret.' }).catch(() => {})
    await ctx.editMessageReplyMarkup({ reply_markup: { inline_keyboard: [] } }).catch(() => {})
    return
  }

  const cardChatId = String(ctx.chat?.id ?? '')
  const cardMessageId = ctx.callbackQuery?.message?.message_id

  if (action === 'cancel') {
    // Kernel-side dual-dispatch (MIGRATION.md §1): record the deny decision
    // BEFORE the legacy handler clears state, so the audit log captures it
    // even if the editMessageText below races with another tap. Best-effort
    // — broker unreachable falls back to legacy-only.
    await recordDeferredSecretKernelDecision(
      deferred.kernel_request_id,
      'deny',
      ctx.from?.id ?? 0,
      access.allowFrom,
    )
    deferredSecrets.delete(deferKey)
    await ctx.answerCallbackQuery({ text: 'Discarded.' }).catch(() => {})
    if (cardMessageId != null) {
      await ctx
        .editMessageText('🗑 Discarded — secret was not saved.', {
          reply_markup: { inline_keyboard: [] },
        })
        .catch(() => {})
    }
    return
  }

  if (action === 'unlock') {
    // Kernel-side dual-dispatch (MIGRATION.md §1): record the allow_once
    // decision when the user taps unlock. The actual passphrase capture +
    // vault write still happens via the legacy path below — the kernel
    // decision is for audit/state, not secret material (per RFC B). We
    // record at tap-time rather than after passphrase entry so a kernel
    // record exists even if the user abandons the passphrase prompt.
    await recordDeferredSecretKernelDecision(
      deferred.kernel_request_id,
      'allow_once',
      ctx.from?.id ?? 0,
      access.allowFrom,
    )
    // #1115 follow-up: telegram-id mode silent-defer-save was withdrawn
    // (same reason as the save-callback above — the in-memory
    // passphrase short-circuit became a bypass surface). The
    // deferred-secret save falls through to the cached-passphrase
    // path under all postures. Routing executeDeferredSecretSave
    // through broker-IPC attest_via_posture is a tracked follow-up.

    // If a passphrase is already cached we can skip straight to the write.
    // Covers the case where the user had unlocked separately between
    // detection and tap.
    const cached = vaultPassphraseCache.get(cardChatId)
    if (cached && cached.expiresAt > Date.now()) {
      await ctx.answerCallbackQuery({ text: 'Saving…' }).catch(() => {})
      await executeDeferredSecretSave(ctx, deferKey, cached.passphrase, cardMessageId)
      return
    }

    if (cardMessageId == null) {
      await ctx.answerCallbackQuery({ text: 'Missing card context.' }).catch(() => {})
      return
    }
    pendingVaultOps.set(cardChatId, {
      kind: 'passphrase-for-deferred',
      deferKey,
      cardChatId,
      cardMessageId,
      startedAt: Date.now(),
    })
    await ctx.answerCallbackQuery({ text: 'Send your passphrase…' }).catch(() => {})
    await ctx
      .editMessageText(
        richMessage('🔐 Send your vault passphrase as your next message — we\'ll save the held secret automatically and delete the passphrase message.'),
        { reply_markup: { inline_keyboard: [] } },
      )
      .catch(() => {})
    return
  }

  await ctx.answerCallbackQuery({ text: 'Unknown action.' }).catch(() => {})
}

// ─── Grant wizard helpers (Issue #227) ──────────────────────────────────────
// TODO: these helpers duplicate server.ts — extract to a shared module in a
// future refactor once the two entrypoints are proven stable in production.

/** Parse a duration string like "30d", "7h", "365d" into seconds. */
function parseGrantDuration(s: string): number | null {
  const m = /^(\d+)([dh])$/i.exec(s.trim())
  if (!m) return null
  const n = parseInt(m[1]!, 10)
  if (n <= 0) return null
  return m[2]!.toLowerCase() === 'd' ? n * 86400 : n * 3600
}

/** Format seconds as a human-readable expiry label. */
function formatGrantExpiry(ttlSeconds: number | null, now: Date = new Date()): string {
  if (ttlSeconds === null) return 'Never'
  const exp = new Date(now.getTime() + ttlSeconds * 1000)
  return exp.toISOString().slice(0, 10)
}

/** Build the Step 1 keyboard: agent selection. */
function buildGrantAgentKeyboard(agents: string[]): InlineKeyboard {
  const kb = new InlineKeyboard()
  // Max 3 per row to keep buttons readable on mobile
  for (let i = 0; i < agents.length; i++) {
    if (i > 0 && i % 3 === 0) kb.row()
    kb.text(agents[i]!, `vg:agent:${agents[i]!}`)
  }
  kb.row().text('Cancel', 'vg:cancel')
  return kb
}

/** Build the Step 2 keyboard: key multi-select toggle. */
function buildGrantKeysKeyboard(keys: string[], selected: Set<string>): InlineKeyboard {
  const kb = new InlineKeyboard()
  for (const k of keys) {
    const check = selected.has(k) ? '☑' : '☐'
    kb.row().text(`${check} ${k}`, `vg:key:${k}`)
  }
  kb.row()
    .text('Continue', 'vg:keys-continue')
    .text('Cancel', 'vg:cancel')
  return kb
}

/** Build the Step 3 keyboard: duration selection. */
function buildGrantDurationKeyboard(): InlineKeyboard {
  return new InlineKeyboard()
    .text('30 days', 'vg:dur:30d')
    .text('90 days', 'vg:dur:90d')
    .text('1 year', 'vg:dur:1y')
    .row()
    .text('Custom…', 'vg:dur:custom')
    .text('No expiry', 'vg:dur:never')
    .row()
    .text('Back', 'vg:back:duration')
    .text('Cancel', 'vg:cancel')
}

/** Build the Confirm keyboard. */
function buildGrantConfirmKeyboard(): InlineKeyboard {
  return new InlineKeyboard()
    .text('Generate', 'vg:generate')
    .text('Cancel', 'vg:cancel')
}

/** Start the grant wizard (step 1: pick agent). */
async function startGrantWizardStep1(ctx: Context, chatId: string): Promise<void> {
  type AgentListResp = { agents: Array<{ name: string }> }
  const data = switchroomExecJson<AgentListResp>(['agent', 'list'])
  const agents = data?.agents?.map(a => a.name).filter(Boolean) ?? []
  if (agents.length === 0) {
    await switchroomReply(ctx, '⚠️ No agents found in switchroom.yaml.', { html: true })
    return
  }
  const kb = buildGrantAgentKeyboard(agents)
  const sent = await switchroomReply(ctx, '**Grant capability token — Step 1/3**\n\nWhich agent?', { html: true, reply_markup: kb })
  const wizardMsgId = (sent as unknown as { message_id?: number })?.message_id
  pendingVaultOps.set(chatId, {
    kind: 'grant-wizard',
    step: 'agent',
    wizardMsgId,
    startedAt: Date.now(),
  })
}

/** Advance grant wizard to step 2 (pick keys). */
async function grantWizardStep2(ctx: Context, chatId: string, agent: string, wizardMsgId: number | undefined): Promise<void> {
  const keys = await listViaBroker()
  if (!keys) {
    await switchroomReply(ctx, '🔴 Broker is not running (or unreachable). Cannot list vault keys.', { html: true })
    pendingVaultOps.delete(chatId)
    return
  }
  if (keys.length === 0) {
    await switchroomReply(ctx, '⚠️ No vault keys found. Add secrets first with \`/vault set\`.', { html: true })
    pendingVaultOps.delete(chatId)
    return
  }
  const selected = new Set<string>()
  const kb = buildGrantKeysKeyboard(keys, selected)
  const text = `**Grant capability token — Step 2/3**\n\nWhich keys for \`${agent}\`?\n_Tap to toggle; tap Continue when done._`
  if (wizardMsgId != null) {
    // allow-raw-bot-api: vault grant wizard step 2/3; already .catch-swallows, tap-driven UI re-renders on retry
    await ctx.api.editMessageText(chatId, wizardMsgId, richMessage(text), { reply_markup: kb }).catch(() => {})
  } else {
    const sent = await switchroomReply(ctx, text, { html: true, reply_markup: kb })
    wizardMsgId = (sent as unknown as { message_id?: number })?.message_id
  }
  pendingVaultOps.set(chatId, {
    kind: 'grant-wizard',
    step: 'keys',
    agent,
    selectedKeys: [],
    availableKeys: keys,
    wizardMsgId,
    startedAt: Date.now(),
  })
}

/** Advance grant wizard to step 3 (pick duration). */
async function grantWizardStep3(ctx: Context, chatId: string, state: Extract<PendingVaultOp, { kind: 'grant-wizard' }>): Promise<void> {
  const kb = buildGrantDurationKeyboard()
  const keyList = state.selectedKeys!.map(k => `• \`${k}\``).join('\n')
  const text = `**Grant capability token — Step 3/3**\n\nKeys for \`${state.agent!}\`:\n${keyList}\n\nHow long should this grant be valid?`
  const msgId = state.wizardMsgId
  if (msgId != null) {
    // allow-raw-bot-api: vault grant wizard step 3/3 (TTL select); already .catch-swallows, tap-driven UI re-renders on retry
    await ctx.api.editMessageText(chatId, msgId, richMessage(text), { reply_markup: kb }).catch(() => {})
  } else {
    const sent = await switchroomReply(ctx, text, { html: true, reply_markup: kb })
    state.wizardMsgId = (sent as unknown as { message_id?: number })?.message_id
  }
  pendingVaultOps.set(chatId, { ...state, step: 'duration' })
}

/** Advance grant wizard to confirmation step. */
async function grantWizardConfirm(ctx: Context, chatId: string, state: Extract<PendingVaultOp, { kind: 'grant-wizard' }>): Promise<void> {
  const kb = buildGrantConfirmKeyboard()
  const expiresLabel = formatGrantExpiry(state.ttlSeconds!)
  const keyList = state.selectedKeys!.map(k => `• \`${k}\``).join('\n')
  const text = [
    '**Confirm grant**',
    '',
    `Agent: \`${state.agent!}\``,
    `Keys:\n${keyList}`,
    `Expires: **${escapeHtmlForTg(expiresLabel)}**`,
    '',
    'Tap **Generate** to mint the token.',
  ].join('\n')
  const msgId = state.wizardMsgId
  if (msgId != null) {
    // allow-raw-bot-api: vault grant wizard confirm step; already .catch-swallows, tap-driven UI re-renders on retry
    await ctx.api.editMessageText(chatId, msgId, richMessage(text), { reply_markup: kb }).catch(() => {})
  } else {
    const sent = await switchroomReply(ctx, text, { html: true, reply_markup: kb })
    state.wizardMsgId = (sent as unknown as { message_id?: number })?.message_id
  }
  // Mint kernel decision row at the confirm step (MIGRATION.md §2,
  // audit-only Phase 1). We do it here rather than at executeGrantWizard
  // so a kernel row exists even if the user taps Cancel from the confirm
  // card — the deny verdict on cancel is then recorded against the same
  // request_id. If the kernel/broker is unreachable, request_id stays
  // undefined and the wizard runs legacy-only (no behaviour change).
  const kernelRequestId = await mintGrantWizardKernelRequest(
    state.agent!,
    loadAccess().allowFrom,
    state.selectedKeys!,
    state.ttlSeconds ?? null,
  )
  pendingVaultOps.set(chatId, {
    ...state,
    step: 'confirm',
    expiresLabel,
    kernel_request_id: kernelRequestId ?? state.kernel_request_id,
  })
}

/** Execute the grant: call broker mint_grant, write token, reply. */
async function executeGrantWizard(ctx: Context, chatId: string, state: Extract<PendingVaultOp, { kind: 'grant-wizard' }>): Promise<void> {
  pendingVaultOps.delete(chatId)
  // Kernel-side dual-dispatch (MIGRATION.md §2, audit-only Phase 1):
  // record the allow_once decision when the user taps Generate. The
  // legacy `mintGrantViaBroker` below still drives the actual grant
  // mint + token write — the kernel row is informational, not
  // enforcing, in Phase 1 (issue #833 will flip to enforcing).
  // We record at tap-time rather than after mint_grant succeeds so a
  // kernel row exists even if the legacy mint fails (audit captures
  // intent regardless of downstream outcome).
  await recordGrantWizardKernelDecision(
    state.kernel_request_id,
    'allow_once',
    ctx.from?.id ?? 0,
    loadAccess().allowFrom,
  )
  // Defence-in-depth: state.agent flows from callback_data into a path
  // join below. A crafted vg:agent:../../etc payload would produce a
  // path traversal. Validate against the same regex the rest of the
  // file uses; on failure, drop silently — the wizard message has
  // already been finalized.
  try { assertSafeAgentName(state.agent!) } catch { return }
  const result = await mintGrantViaBroker({
    agent: state.agent!,
    keys: state.selectedKeys!,
    ttl_seconds: state.ttlSeconds ?? null,
    description: state.description,
  })
  if (result.kind === 'unreachable') {
    await switchroomReply(ctx, `🔴 Broker unreachable: ${escapeHtmlForTg(result.msg)}`, { html: true })
    return
  }
  if (result.kind === 'error') {
    await switchroomReply(ctx, `**mint_grant failed:** ${escapeHtmlForTg(result.msg)}`, { html: true })
    return
  }
  // Write token to the agent's .vault-token file
  const { token, id } = result
  const tokenPath = join(homedir(), '.switchroom', 'agents', state.agent!, '.vault-token')
  try {
    mkdirSync(join(homedir(), '.switchroom', 'agents', state.agent!), { recursive: true })
    writeFileSync(tokenPath, token, { mode: 0o600 })
  } catch (err) {
    await switchroomReply(ctx, `**Grant created but token write failed:** ${escapeHtmlForTg(String(err))}`, { html: true })
    return
  }
  // Collapse wizard message to just the outcome.
  // #1150 audit: P0 fix — pre-fix this `editMessageText` call omitted
  // `reply_markup: { inline_keyboard: [] }` so the wizard's [Generate]
  // / [Cancel] buttons stayed tappable on the success card. Operator
  // could re-tap [Generate] and mint a second redundant grant.
  // Strip the keyboard atomically with the success text via the
  // finalizeCallback helper.
  const msgId = state.wizardMsgId
  const successText = `✅ Grant \`${id}\` created. Written to \`~/.switchroom/agents/${escapeHtmlForTg(state.agent!)}/.vault-token\``
  if (msgId != null) {
    await finalizeCallback(ctx, {
      ackText: '✅ Grant created',
      newText: successText,
      // No synthInbound — operator-only flow.
    })
  } else {
    // Fallback when wizard message id was lost (rare; e.g. operator
    // deleted the card). Send a fresh reply with the success text;
    // no keyboard to strip in this branch.
    await switchroomReply(ctx, successText, { html: true })
  }
}

/**
 * Issue #228: handle vault grant management callbacks.
 *
 *   `vg:revoke:<grantId>`  — fetch grant details and show confirmation card.
 *   `vg:confirm:<grantId>` — call broker revoke_grant, reply with success.
 *   `vg:cancel:<grantId>`  — dismiss (clear keyboard, no broker call).
 *
 * Issue #227: also handles /vault grant wizard callbacks.
 *
 *   `vg:cancel`            — cancel wizard at any step.
 *   `vg:agent:<name>`      — step 1: select agent.
 *   `vg:key:<name>`        — step 2: toggle key selection.
 *   `vg:keys-continue`     — step 2 → 3.
 *   `vg:dur:<value>`       — step 3: duration selection.
 *   `vg:back:duration`     — step 3 → back to step 2.
 *   `vg:generate`          — confirm and mint token.
 */
async function handleVaultGrantCallback(ctx: Context, data: string): Promise<void> {
  const senderId = String(ctx.from?.id ?? '')
  const access = loadAccess()
  if (!access.allowFrom.includes(senderId)) {
    await ctx.answerCallbackQuery({ text: 'Not authorized.' }).catch(() => {})
    return
  }

  const revokeMatch = /^vg:revoke:(.+)$/.exec(data)
  if (revokeMatch) {
    const grantId = revokeMatch[1]!
    const result = await listGrantsViaBroker(undefined)
    if (result.kind !== 'ok') {
      await ctx.answerCallbackQuery({ text: 'Broker unreachable.' }).catch(() => {})
      return
    }
    const grant = result.grants.find(g => g.id === grantId)
    if (!grant) {
      await ctx.answerCallbackQuery({ text: 'Grant not found (already revoked?).' }).catch(() => {})
      await ctx.editMessageReplyMarkup({ reply_markup: { inline_keyboard: [] } }).catch(() => {})
      return
    }
    const cardText =
      `🗑 Revoke \`${grantId}\`?\n` +
      `Agent: **${escapeHtmlForTg(grant.agent_slug)}**\n` +
      `Keys: \`${escapeHtmlForTg(grant.key_allow.join(', '))}\``
    const confirmKeyboard = new InlineKeyboard()
      .text('✅ Confirm Revoke', `vg:confirm:${grantId}`)
      .text('❌ Cancel', `vg:cancel:${grantId}`)
    await ctx.answerCallbackQuery().catch(() => {})
    await ctx.editMessageText(richMessage(cardText), {
      reply_markup: confirmKeyboard,
    }).catch(async () => {
      const chatId = String(ctx.chat?.id ?? ctx.from?.id ?? '')
      const threadId = ctx.callbackQuery?.message?.message_thread_id
      if (chatId) {
        // #1075: thread-id-bearing — swallow on THREAD_NOT_FOUND.
        await swallowingApiCall(
          () =>
            bot.api.sendRichMessage(chatId, richMessage(cardText), {
              reply_markup: confirmKeyboard,
              ...(threadId != null ? { message_thread_id: threadId } : {}),
            }),
          {
            chat_id: chatId,
            verb: 'vault-revoke-confirm-fallback',
            ...(threadId != null ? { threadId } : {}),
          },
        )
      }
    })
    return
  }

  const confirmMatch = /^vg:confirm:(.+)$/.exec(data)
  if (confirmMatch) {
    const grantId = confirmMatch[1]!
    const revokeResult = await revokeGrantViaBroker(grantId)
    if (revokeResult.kind === 'unreachable') {
      await ctx.answerCallbackQuery({ text: 'Broker unreachable.' }).catch(() => {})
      return
    }
    if (revokeResult.kind === 'error') {
      await ctx.answerCallbackQuery({ text: `Revoke failed: ${revokeResult.msg}` }).catch(() => {})
      return
    }
    await ctx.answerCallbackQuery({ text: '✅ Revoked' }).catch(() => {})
    await ctx.editMessageText(
      richMessage(`✅ Grant \`${grantId}\` revoked. Token file removed.`),
      { reply_markup: { inline_keyboard: [] } },
    ).catch(() => {})
    return
  }

  const cancelMatch = /^vg:cancel:(.+)$/.exec(data)
  if (cancelMatch) {
    await ctx.answerCallbackQuery({ text: 'Cancelled.' }).catch(() => {})
    await ctx.editMessageReplyMarkup({ reply_markup: { inline_keyboard: [] } }).catch(() => {})
    return
  }

  // #227 grant wizard callbacks (vg:cancel bare, vg:agent:*, vg:key:*, vg:keys-continue,
  // vg:dur:*, vg:back:*, vg:generate). These come after the management callbacks above
  // because management uses vg:cancel:<id> (with trailing id) while the wizard uses
  // bare vg:cancel — the cancelMatch above only matches the id-suffixed form.
  //
  // Note: pre-#265 fix this function did `await ctx.answerCallbackQuery().catch(() => {})`
  // unconditionally up front. That meant the `vg:keys-continue` branch's
  // toast call (`Select at least one key.`) hit a Telegram error
  // ("query is too old or query ID is invalid") because the query was
  // already answered, and the toast never reached the user. Each branch
  // now owns its own ack.
  const chatId = String(ctx.chat?.id ?? ctx.from?.id ?? '')
  const ackSilently = () => ctx.answerCallbackQuery().catch(() => {})

  // Cancel at any wizard step
  if (data === 'vg:cancel') {
    // Kernel-side dual-dispatch (MIGRATION.md §2, audit-only Phase 1):
    // if the user got as far as the confirm step, a kernel request_id
    // will be on the wizard state — record the deny decision so the
    // audit log captures the abandonment. No-op if the user cancelled
    // before the confirm step (or if the kernel was unreachable).
    const cancelState = pendingVaultOps.get(chatId)
    if (cancelState && cancelState.kind === 'grant-wizard') {
      await recordGrantWizardKernelDecision(
        cancelState.kernel_request_id,
        'deny',
        ctx.from?.id ?? 0,
        loadAccess().allowFrom,
      )
    }
    pendingVaultOps.delete(chatId)
    const msg = ctx.callbackQuery?.message
    if (msg && 'text' in msg) {
      await ctx.editMessageText('❌ Grant wizard cancelled.').catch(() => {})
    }
    await ackSilently()
    return
  }

  const state = pendingVaultOps.get(chatId)
  if (!state || state.kind !== 'grant-wizard') {
    await ctx.editMessageText('⚠️ Wizard session expired. Run /vault grant to start again.').catch(() => {})
    await ackSilently()
    return
  }

  // vg:agent:<name> — step 1 selection
  if (data.startsWith('vg:agent:')) {
    const agent = data.slice('vg:agent:'.length)
    const msgId = (ctx.callbackQuery?.message as { message_id?: number })?.message_id ?? state.wizardMsgId
    await grantWizardStep2(ctx, chatId, agent, msgId)
    await ackSilently()
    return
  }

  // vg:key:<name> — step 2 toggle
  if (data.startsWith('vg:key:')) {
    const key = data.slice('vg:key:'.length)
    if (state.step !== 'keys') { await ackSilently(); return }
    const selectedSet = new Set(state.selectedKeys ?? [])
    if (selectedSet.has(key)) {
      selectedSet.delete(key)
    } else {
      selectedSet.add(key)
    }
    const updatedState = { ...state, selectedKeys: [...selectedSet] }
    pendingVaultOps.set(chatId, updatedState)
    const kb = buildGrantKeysKeyboard(state.availableKeys ?? [], selectedSet)
    await ctx.editMessageReplyMarkup({ reply_markup: kb }).catch(() => {})
    await ackSilently()
    return
  }

  // vg:keys-continue — step 2 → 3
  if (data === 'vg:keys-continue') {
    if (state.step !== 'keys') { await ackSilently(); return }
    if (!state.selectedKeys || state.selectedKeys.length === 0) {
      // Toast-only ack: this is the branch the unconditional pre-ack
      // used to silently swallow. See #265.
      await ctx.answerCallbackQuery({ text: 'Select at least one key.' }).catch(() => {})
      return
    }
    await grantWizardStep3(ctx, chatId, state)
    await ackSilently()
    return
  }

  // vg:dur:<value> — step 3 duration selection
  if (data.startsWith('vg:dur:')) {
    if (state.step !== 'duration') { await ackSilently(); return }
    const dur = data.slice('vg:dur:'.length)
    if (dur === 'custom') {
      // Ask for text reply with n d|h format
      pendingVaultOps.set(chatId, { ...state, awaitingCustomDuration: true })
      const msg = ctx.callbackQuery?.message
      if (msg && 'text' in msg && msg.text) {
        // Escape source text before re-rendering with HTML parse mode.
        // `msg.text` returns entities-stripped plain UTF-8; a raw
        // `<`/`>`/`&` in the wizard's prior-step body (e.g. a future
        // key or label) would crash the HTML re-parse and the bare
        // `.catch(() => {})` would swallow the failure silently — same
        // hazard PR #1158 caught on the operator-event card.
        await ctx.editMessageText(
          richMessage(escapeHtmlForTg(msg.text) + '\n\n_Send a duration like \`30d\` or \`12h\`:_'),
          { reply_markup: buildGrantDurationKeyboard() },
        ).catch(() => {})
      }
      await ackSilently()
      return
    }
    let ttlSeconds: number | null
    if (dur === 'never') {
      ttlSeconds = null
    } else if (dur === '1y') {
      ttlSeconds = 365 * 86400
    } else {
      ttlSeconds = parseGrantDuration(dur)
      if (ttlSeconds === null) { await ackSilently(); return }
    }
    const newState = { ...state, ttlSeconds, awaitingCustomDuration: false }
    await grantWizardConfirm(ctx, chatId, newState)
    await ackSilently()
    return
  }

  // vg:back:duration — go back to step 2 (keys selection) from step 3
  if (data === 'vg:back:duration') {
    if (state.step !== 'duration') { await ackSilently(); return }
    const msgId = state.wizardMsgId
    await grantWizardStep2(ctx, chatId, state.agent!, msgId)
    await ackSilently()
    return
  }

  // vg:generate — final step
  if (data === 'vg:generate') {
    if (state.step !== 'confirm') { await ackSilently(); return }
    await executeGrantWizard(ctx, chatId, state)
    await ackSilently()
    return
  }

  // Unrecognised vg: sub-action
  await ackSilently()
}

/**
 * Issue #44: write a deferred secret to the vault using the now-cached
 * passphrase. Confirms with a masked ref + slug; matches the "captured
 * N secret" UX of the cached-passphrase happy path so the user
 * experience is identical regardless of which path they came in on.
 *
 * Called from two places:
 *   - The `passphrase-for-deferred` branch of the text-handler
 *     pendingVaultOps intercept, after the passphrase is verified.
 *   - The `vd:unlock` callback handler when a passphrase happens to
 *     already be cached (rare but possible).
 *
 * If write fails, the deferred entry is preserved so the user can retry.
 */
async function executeDeferredSecretSave(
  ctx: Context,
  deferKey: string,
  passphrase: string,
  cardMessageId: number | undefined,
): Promise<void> {
  const deferred = deferredSecrets.get(deferKey)
  if (!deferred) {
    if (cardMessageId != null) {
      await ctx.api
        .editMessageText(
          deferKey.split(':')[0]!,
          cardMessageId,
          '⚠️ This card expired before unlock — please re-send the secret.',
          { reply_markup: { inline_keyboard: [] } },
        )
        .catch(() => {})
    }
    return
  }

  // De-duplicate suggested_slug against existing vault keys by appending
  // _2 / _3 / … if needed. Same logic as the cached-passphrase happy
  // path uses (gateway.ts ~L2402 stash command).
  const slugBase = deferred.suggested_slug || 'secret'
  const listed = defaultVaultList(passphrase)
  const existing = new Set(listed.ok ? listed.keys : [])
  let slug = slugBase
  let n = 2
  while (existing.has(slug)) slug = `${slugBase}_${n++}`

  const write = defaultVaultWrite(slug, deferred.text, passphrase)
  if (!write.ok) {
    // Classify the failure via the structured stderr markers emitted by
    // `switchroom vault` (issue #969 P0a). If it's a recognised marker,
    // render a clean actionable message instead of dumping the raw
    // "Vault file not found …" / "VAULT-NEEDS-APPROVAL …" blob the CLI
    // emits — that was the misleading-error half of #968.
    //
    // Keep the deferred entry so the user can retry by tapping again
    // once the underlying condition is fixed (broker started, host
    // approval granted, etc.).
    const parsed = parseVaultCliError(write.output)
    const rendered = renderVaultCliError(parsed, { verb: "save", key: slug })
    const body = rendered.suppressRaw
      ? rendered.html
      : `⚠️ vault write failed:\n\`\`\`\n${write.output}\n\`\`\``
    if (cardMessageId != null) {
      await ctx.api
        .editMessageText(
          deferred.chat_id,
          cardMessageId,
          richMessage(`${body}\n\nRe-tap to retry.`),
          {
            reply_markup: buildDeferredSecretKeyboard(deferKey).inline_keyboard.length > 0
              ? buildDeferredSecretKeyboard(deferKey)
              : undefined,
          },
        )
        .catch(() => {})
    }
    return
  }

  deferredSecrets.delete(deferKey)
  const masked = maskToken(deferred.text)
  if (cardMessageId != null) {
    await ctx.api
      .editMessageText(
        deferred.chat_id,
        cardMessageId,
        richMessage(`✅ stored as \`vault:${slug}\` (masked: \`${masked}\`)\n\nReply \`rename NEW_NAME\` to relabel.`),
        { reply_markup: { inline_keyboard: [] } },
      )
      .catch(() => {})
  }
  // Stage for follow-up rename, mirroring the cached-passphrase path.
  secretStaging.set({
    chat_id: deferred.chat_id,
    message_id: deferred.original_message_id,
    detection: {
      rule_id: 'deferred',
      matched_text: deferred.text,
      start: 0,
      end: deferred.text.length,
      confidence: 'high' as const,
      suppressed: false,
      suggested_slug: slug,
    },
    staged_at: Date.now(),
  })
}

async function handleOperatorEventCallback(ctx: Context, data: string): Promise<void> {
  const senderId = String(ctx.from?.id ?? '')
  const access = loadAccess()
  if (!access.allowFrom.includes(senderId)) {
    await ctx.answerCallbackQuery({ text: 'Not authorized.' }).catch(() => {})
    return
  }

  // Parse op:<action>:<encoded-agent>
  const parts = data.slice(3).split(':', 2)  // drop "op:", then split action:agent
  if (parts.length !== 2) {
    await ctx.answerCallbackQuery({ text: 'Malformed operator-event callback.' }).catch(() => {})
    return
  }
  const [action, encodedAgent] = parts
  let agent: string
  try {
    agent = decodeURIComponent(encodedAgent)
  } catch {
    await ctx.answerCallbackQuery({ text: 'Bad agent name encoding.' }).catch(() => {})
    return
  }
  if (!/^[a-z0-9][a-z0-9_-]{0,50}$/.test(agent)) {
    await ctx.answerCallbackQuery({ text: 'Invalid agent name.' }).catch(() => {})
    return
  }

  // #1150 audit P1: extract the source card text once so every branch
  // below can append a status line via finalizeCallback. Pre-fix `dismiss`
  // and `restart` stripped the keyboard but kept the original card body
  // verbatim — operator scrolling back couldn't see what they'd decided.
  // `reauth` didn't strip the keyboard at all → re-tappable mid-flow.
  //
  // HTML-escape the extracted text before concatenation. Telegram returns
  // `msg.text` as plain UTF-8 with entities stripped — any raw `<`, `>`,
  // or `&` characters in the original `detail` (operator-events.ts
  // `unknown-4xx`/`unknown-5xx` cards routinely carry API error bodies
  // with `<`/`>` in them) would be re-parsed as HTML tags when the
  // finalizeCallback edit fires with `parseMode: 'HTML'`. Telegram
  // rejects the edit, finalizeCallback's catch swallows it, the
  // keyboard never strips, and the operator re-taps → exact bug this
  // PR is meant to fix re-introduced. Escape once here so every branch
  // gets a safe-to-reparse value. We lose the original bold/italic
  // styling on the source body — acceptable, that styling was already
  // gone the moment `msg.text` was read instead of `msg.entities`.
  // (PR #1158 round 2 — review item F.)
  const sourceMsgText = (() => {
    const msg = ctx.callbackQuery?.message
    if (!msg || !('text' in msg) || !msg.text) return ''
    return escapeHtmlForTg(msg.text)
  })()

  switch (action) {
    case 'dismiss': {
      // #1150 audit P1: was strip-only. Now appends a status line so
      // scrollback shows the dismissal.
      const status = `\n\n✗ _Dismissed by operator._`
      await finalizeCallback(ctx, {
        ackText: 'Dismissed',
        newText: sourceMsgText ? `${sourceMsgText}${status}` : status,
        // No synthInbound — dismiss is operator-only, no model in loop.
      })
      return
    }
    case 'restart': {
      const ok = triggerSelfRestart(agent, 'inline-button-restart')
      if (ok) {
        // #1150 audit P1: was reply + editMessageReplyMarkup (two
        // separate edits). Atomic via finalizeCallback now — the
        // status line is the announcement, no separate reply needed.
        const status = `\n\n🔄 _**${escapeHtmlForTg(agent)}** restart requested by operator._`
        await finalizeCallback(ctx, {
          ackText: `Restarting ${agent}…`,
          newText: sourceMsgText ? `${sourceMsgText}${status}` : status,
        })
      } else {
        // Failure-path: leave the keyboard tappable so the operator
        // can retry once they've followed the manual instructions
        // below. ack toast still fires.
        await ctx.answerCallbackQuery({ text: `Restart failed for ${agent}` }).catch(() => {})
        const isDocker = process.env.SWITCHROOM_RUNTIME === 'docker'
        const detail = isDocker
          ? `cross-agent restart is not supported under docker. ` +
            `Restart from the host: \`docker compose -p switchroom restart agent-${agent}\`.`
          : 'restart trigger failed'
        await ctx.replyWithRichMessage(richMessage(`**Restart failed for ${agent}:** ${detail}`))
      }
      return
    }
    case 'reauth': {
      // #1150 audit P1: pre-fix the operator-event card's [Reauth] button
      // stayed tappable after the reauth flow started → operator could
      // re-tap and spawn a second concurrent flow that fights the first
      // for the login URL state. Strip the keyboard and append a status
      // line; the new reauth-flow's own messages appear below the
      // collapsed card.
      const status = `\n\n🔐 _Reauth started for **${escapeHtmlForTg(agent)}** — follow the login URL below._`
      await finalizeCallback(ctx, {
        ackText: `Starting reauth for ${agent}…`,
        newText: sourceMsgText ? `${sourceMsgText}${status}` : status,
        synthInbound: async () => {
          await runSwitchroomAuthCommand(ctx, ['auth', 'reauth', agent], `auth reauth ${agent}`)
          // PR3 supergroup-mode: key by (chat, thread) so an OAuth code
          // pasted into a different topic isn't mistakenly intercepted
          // as this flow's reauth code.
          const reauthThreadId = ctx.callbackQuery?.message?.message_thread_id
          pendingReauthFlows.set(
            chatKey(String(ctx.chat!.id), reauthThreadId ?? null) as string,
            { agent, startedAt: Date.now() },
          )
        },
      })
      return
    }
    case 'logs': {
      await ctx.answerCallbackQuery({ text: 'Fetching logs…' }).catch(() => {})
      // Pick the right log source for the runtime. Under docker, the
      // gateway is INSIDE the agent container — calling `docker logs`
      // requires the host's docker socket which is deliberately not
      // mounted into agent containers. Under systemd, journalctl
      // works as before. v0.7.2 fixed `case 'restart'` but left this
      // path systemd-only.
      const isDocker = process.env.SWITCHROOM_RUNTIME === 'docker'
      if (isDocker) {
        await ctx.replyWithRichMessage(richMessage(
          `_Inline log fetch is not available under docker mode (no docker.sock in agent containers). ` +
            `Run from the host: \`docker logs --since 30m --tail 30 switchroom-${agent}\`_`,
        ))
        return
      }
      try {
        const out = execFileSync(
          'journalctl',
          ['--user', '-u', `switchroom-${agent}`, '-n', '30', '--no-pager', '--output=short-monotonic'],
          { encoding: 'utf-8', timeout: 10000, stdio: ['ignore', 'pipe', 'pipe'] },
        ) as string
        const trimmed = out.trim().slice(-3500)
        await ctx.replyWithRichMessage(richMessage(
          trimmed
            ? `\`\`\`\n${trimmed.replace(/```/g, '`​``')}\n\`\`\``
            : `_No logs for ${agent}._`,
        ))
      } catch (err) {
        await ctx.replyWithRichMessage(richMessage(
          `**logs failed:** ${escapeHtmlForTg((err as Error).message)}`,
        ))
      }
      return
    }
    default: {
      await ctx.answerCallbackQuery({ text: `Unknown action: ${action}` }).catch(() => {})
      return
    }
  }
}

// RFC H §7.3: the dashboard callback dispatcher is gone — there are
// no auth: callback buttons in the new chat surface. We keep a no-op
// stub so any stale pinned message that fires an `auth:*` tap is
// silently dismissed instead of crashing the gateway.
async function handleAuthDashboardCallback(ctx: Context): Promise<void> {
  const data = ctx.callbackQuery?.data ?? ''
  const currentAgent = getMyAgentName()

  // auth:use:<label> — fleet-wide swap via broker.setActive (same path
  // /auth use takes from chat). Admin-gated via the broker's own
  // per-agent admin flag.
  if (data.startsWith('auth:use:')) {
    const label = data.slice('auth:use:'.length)
    if (!label) {
      try { await ctx.answerCallbackQuery({ text: 'Missing account label.', show_alert: false }) } catch { /* */ }
      return
    }
    try {
      const client = await getAuthBrokerClient(currentAgent)
      if (!client) {
        try { await ctx.answerCallbackQuery({ text: 'Broker unreachable.', show_alert: true }) } catch { /* */ }
        return
      }
      const result = await client.setActive(label)
      try {
        await ctx.answerCallbackQuery({
          text: `Switched fleet → ${result.active} (${result.fanned.length} agents)`,
          show_alert: false,
        })
      } catch { /* toast may fail on stale tap */ }
      // Edit the source message to reflect the new active. Leaving
      // the old keyboard intact would tempt a double-tap; we replace
      // the text + drop the keyboard so the user has to /auth again
      // to see fresh state.
      const msg = ctx.callbackQuery?.message
      if (msg) {
        // Wrap in swallowingApiCall per #1075 — stale callback-source
        // messages (deleted topic, expired) shouldn't crash the swap.
        await swallowingApiCall(
          () =>
            bot.api.editMessageText(
              msg.chat.id,
              msg.message_id,
              richMessage(
                `**Active account →** \`${result.active}\`\n` +
                `_Re-mirrored credentials for ${result.fanned.length} agent${result.fanned.length === 1 ? '' : 's'}._\n\n` +
                `_Tap /auth to see updated quota for the new active account._`,
              ),
              {},
            ),
          { chat_id: String(msg.chat.id), verb: 'auth:use:edit' },
        )
      }
    } catch (err) {
      const msg = (err as Error)?.message ?? String(err)
      try {
        await ctx.answerCallbackQuery({
          text: `Switch failed: ${msg.slice(0, 180)}`,
          show_alert: true,
        })
      } catch { /* */ }
    }
    return
  }

  // auth:refresh — re-render the /auth snapshot in-place with a fresh
  // live probe. Replaces the message body; keyboard stays.
  if (data === 'auth:refresh') {
    // Freshness throttle: each refresh fan-fires N live api.anthropic.com
    // probes (one per account, force=true bypasses the 5-min cache).
    // Without this, a user double-tapping the ↻ button burns through
    // their account's RPM budget on duplicate work. Cap at one per
    // AUTH_REFRESH_THROTTLE_MS per (chat, message) pair.
    const refreshMsg = ctx.callbackQuery?.message
    if (refreshMsg) {
      const key = `${refreshMsg.chat.id}:${refreshMsg.message_id}`
      const lastAtMs = lastAuthRefreshAtMs.get(key) ?? 0
      const sinceLastMs = Date.now() - lastAtMs
      if (sinceLastMs < AUTH_REFRESH_THROTTLE_MS) {
        const waitS = Math.ceil((AUTH_REFRESH_THROTTLE_MS - sinceLastMs) / 1000)
        try {
          await ctx.answerCallbackQuery({
            text: `Just refreshed — try again in ${waitS}s`,
            show_alert: false,
          })
        } catch { /* */ }
        return
      }
      lastAuthRefreshAtMs.set(key, Date.now())
    }
    try {
      const client = await getAuthBrokerClient(currentAgent)
      if (!client) {
        try { await ctx.answerCallbackQuery({ text: 'Broker unreachable.', show_alert: true }) } catch { /* */ }
        return
      }
      const state = await client.listState()
      // Broker-routed probe (#1336) — see gateway.ts:8910 for diagnosis.
      const probeResp = state.accounts.length > 0
        ? await client.probeQuota(state.accounts.map((a) => a.label)).catch(() => ({ results: [] }))
        : { results: [] }
      const quotas = state.accounts.map((a) => {
        const hit = probeResp.results.find((r) => r.label === a.label)
        return hit?.result ?? { ok: false as const, reason: 'broker returned no result for account' }
      })
      const tz = process.env.SWITCHROOM_TIMEZONE ?? process.env.TZ ?? 'UTC'
      const { renderAuthSnapshotFormat2, buildSnapshotsFromState, buildSnapshotKeyboard } = await import(
        '../auth-snapshot-format.js'
      )
      const snapshots = buildSnapshotsFromState(state, quotas)
      const text = renderAuthSnapshotFormat2(snapshots, {
        tz,
        now: new Date(),
        liveProbedAtMs: Date.now(),
      })
      const kbRows = buildSnapshotKeyboard(snapshots)
      const inline_keyboard = kbRows.map((row) =>
        row.map((b) => {
          if (b.callbackData) return { text: b.text, callback_data: b.callbackData }
          if (b.insertText) return { text: b.text, switch_inline_query_current_chat: b.insertText }
          return { text: b.text, callback_data: 'auth:noop' }
        }),
      )
      const msg = ctx.callbackQuery?.message
      if (msg) {
        await swallowingApiCall(
          () =>
            bot.api.editMessageText(msg.chat.id, msg.message_id, richMessage(text), {
              reply_markup: { inline_keyboard },
            }),
          { chat_id: String(msg.chat.id), verb: 'auth:refresh:edit' },
        )
      }
      try { await ctx.answerCallbackQuery({ text: 'Refreshed.', show_alert: false }) } catch { /* */ }
    } catch (err) {
      const msg = (err as Error)?.message ?? String(err)
      try {
        await ctx.answerCallbackQuery({
          text: `Refresh failed: ${msg.slice(0, 180)}`,
          show_alert: true,
        })
      } catch { /* */ }
    }
    return
  }

  // Unknown auth:* — likely from a too-old message. Dismiss with a
  // hint pointing at the canonical re-render verb.
  try {
    await ctx.answerCallbackQuery({
      text: 'Unknown auth button. Send /auth for current state.',
      show_alert: false,
    })
  } catch { /* */ }
}

// /reauth was removed in v0.6.13 — the `/auth` dashboard's
// `🔄 Reauth default` button fires the same flow (the `case 'reauth':`
// callback dispatch calls `runSwitchroomAuthCommand` and seeds
// `pendingReauthFlows`). The OAuth code paste-back is caught by the
// generic message intercept that watches `pendingReauthFlows` —
// pasting the code into chat now Just Works without a typed entry
// point. Removed surfaces in this PR:
//   - bot.command('reauth', ...)              → use /auth → 🔄 Reauth
//   - /reauth <code|url>  paste-back          → paste into chat
//   - /reauth <other-agent> targeting         → use that agent's /auth

bot.command('vault', async ctx => {
  if (!isAuthorizedSender(ctx)) return
  const chatId = String(ctx.chat!.id)
  const args = (typeof ctx.match === "string" ? ctx.match : "").trim().split(/\s+/).filter(Boolean)
  const sub = args[0]?.toLowerCase()
  const key = args[1]
  if (!sub || sub === 'help') {
    await switchroomReply(ctx, [
      '**Vault commands**',
      '/vault list — list all secret keys',
      '/vault get <key> — read a secret value',
      '/vault set <key> — set a secret',
      '/vault delete <key> — remove a secret',
      '/vault status — show broker state',
      '/vault unlock — unlock the broker (prompts for passphrase)',
      '/vault lock — lock the broker',
      '/vault grant — mint a capability token (inline wizard)',
      '/vault grants [agent] — list active capability grants (tap to revoke)',
      '/vault audit <agent> — unified view of an agent\'s vault access',
      '',
      'Your passphrase is cached in memory for 30 min after first use.',
    ].join('\n'), { html: true })
    return
  }

  // Issue #969 P2c: /vault audit <agent> — unified view of an agent's
  // vault access (grants + cron-declared schedule.secrets[]). Single
  // mental model for operators auditing the agent's credential surface.
  if (sub === 'audit') {
    const targetAgent = args[1]
    if (!targetAgent) {
      await switchroomReply(ctx, 'Usage: /vault audit <agent>', { html: true })
      return
    }
    // Sanity-check the agent name shape — same charset constraint as
    // assertSafeAgentName, applied here so we don't blindly shell-out
    // or read filesystem paths derived from user input.
    if (!/^[a-z][a-z0-9-]{0,62}$/i.test(targetAgent)) {
      await switchroomReply(ctx, '⚠️ Invalid agent name shape.', { html: true })
      return
    }

    // 1. Fetch grants from broker, filtered to this agent.
    const grantsResult = await listGrantsViaBroker(targetAgent)
    let readGrants: Array<{ id: string; keys: string[]; expiresAt: number | null }> = []
    let writeGrants: Array<{ id: string; keys: string[]; expiresAt: number | null }> = []
    let grantsError: string | null = null
    if (grantsResult.kind === 'unreachable') {
      grantsError = 'broker unreachable'
    } else if (grantsResult.kind === 'error') {
      grantsError = grantsResult.msg
    } else {
      for (const g of grantsResult.grants) {
        if (g.key_allow.length > 0) {
          readGrants.push({ id: g.id, keys: g.key_allow, expiresAt: g.expires_at })
        }
        if (g.write_allow && g.write_allow.length > 0) {
          writeGrants.push({ id: g.id, keys: g.write_allow, expiresAt: g.expires_at })
        }
      }
    }

    // 2. Load schedule[i].secrets[] from local config for this agent.
    let cronEntries: Array<{ index: number; secrets: string[]; cron?: string }> = []
    let configError: string | null = null
    try {
      const cfg = loadSwitchroomConfig()
      const agentCfg = cfg.agents?.[targetAgent]
      if (!agentCfg) {
        configError = `agent '${targetAgent}' not found in switchroom.yaml`
      } else {
        const schedule = (agentCfg as { schedule?: Array<{ secrets?: string[]; cron?: string }> }).schedule
        if (Array.isArray(schedule)) {
          schedule.forEach((entry, i) => {
            if (entry?.secrets && Array.isArray(entry.secrets) && entry.secrets.length > 0) {
              cronEntries.push({
                index: i,
                secrets: entry.secrets,
                cron: typeof entry.cron === 'string' ? entry.cron : undefined,
              })
            }
          })
        }
      }
    } catch (err) {
      configError = (err instanceof Error ? err.message : String(err))
    }

    // 3. Compose the rendered audit view.
    const lines: string[] = [`**🔐 ${escapeHtmlForTg(targetAgent)} — vault access**`, '']

    if (grantsError) {
      lines.push(`_Grants: ⚠️ ${escapeHtmlForTg(grantsError)}_`)
      lines.push('')
    } else {
      lines.push('**Read grants:**')
      if (readGrants.length === 0) {
        lines.push('  _none_')
      } else {
        for (const g of readGrants) {
          const expiry = g.expiresAt
            ? new Date(g.expiresAt * 1000).toISOString().slice(0, 10)
            : 'no expiry'
          const keysJoined = g.keys.join(', ')
          lines.push(`  \`${g.id}\` · ${escapeHtmlForTg(keysJoined)} · expires ${expiry}`)
        }
      }
      lines.push('')
      lines.push('**Write grants:**')
      if (writeGrants.length === 0) {
        lines.push('  _none_')
      } else {
        for (const g of writeGrants) {
          const expiry = g.expiresAt
            ? new Date(g.expiresAt * 1000).toISOString().slice(0, 10)
            : 'no expiry'
          const keysJoined = g.keys.join(', ')
          lines.push(`  \`${g.id}\` · ${escapeHtmlForTg(keysJoined)} · expires ${expiry}`)
        }
      }
      lines.push('')
    }

    lines.push('**Cron-declared secrets:**')
    if (configError) {
      lines.push(`  _⚠️ ${escapeHtmlForTg(configError)}_`)
    } else if (cronEntries.length === 0) {
      lines.push('  _none_')
    } else {
      for (const entry of cronEntries) {
        const cronLabel = entry.cron ? ` (\`${entry.cron}\`)` : ''
        const keysJoined = entry.secrets.join(', ')
        lines.push(`  schedule[${entry.index}]${cronLabel}: ${escapeHtmlForTg(keysJoined)}`)
      }
    }
    lines.push('')

    // Issue #969 P2b — recent denials section + one-tap "always allow"
    // button per unique denied key. Reads the broker's vault-audit.log
    // and surfaces the latest unique keys the agent was denied access
    // to. Tap a button → mint a 30-day read-grant for that key
    // (extends the existing grant flow rather than reconciling YAML).
    const denials = readRecentDenialsForAgent(targetAgent, 7 * 24 * 60 * 60 * 1000, 5)
    const denialKeyboard = new InlineKeyboard()
    if (denials.length > 0) {
      lines.push('**Recent denials (last 7d):**')
      for (const d of denials) {
        const when = new Date(d.lastSeenMs).toISOString().slice(0, 16).replace('T', ' ')
        lines.push(
          `  \`${d.key}\` · ${d.count}× · last ${when}`,
        )
        // callback_data must stay ≤ 64 bytes. Format:
        //   vrd:<agent>:<key>
        // Agent + key combined are bounded by the slug regex (200 chars
        // for key, ~64 for agent) but realistic combinations stay short.
        // Truncate the label so the button text fits Telegram's 64-byte
        // limit while still being readable.
        const cb = `vrd:${targetAgent}:${d.key}`
        if (cb.length <= 64) {
          const label = d.key.length > 30 ? `🔓 Allow ${d.key.slice(0, 27)}…` : `🔓 Allow ${d.key}`
          denialKeyboard.text(label, cb).row()
        }
      }
      lines.push('')
    }

    lines.push(
      `_Summary: ${readGrants.length} read grant${readGrants.length === 1 ? '' : 's'}, ` +
      `${writeGrants.length} write grant${writeGrants.length === 1 ? '' : 's'}, ` +
      `${cronEntries.length} cron entr${cronEntries.length === 1 ? 'y' : 'ies'}, ` +
      `${denials.length} recent denial${denials.length === 1 ? '' : 's'}._`,
    )

    const chatIdAudit = String(ctx.chat!.id)
    const threadIdAudit = resolveThreadId(chatIdAudit, ctx.message?.message_thread_id)
    await ctx.replyWithRichMessage(richMessage(lines.join('\n')), {
      ...(denials.length > 0 ? { reply_markup: denialKeyboard } : {}),
      ...(threadIdAudit != null ? { message_thread_id: threadIdAudit } : {}),
    })
    return
  }

  // Issue #228: /vault grants [agent] — list active grants grouped by agent
  if (sub === 'grants') {
    const agentFilter = args[1]  // optional agent name filter
    const result = await listGrantsViaBroker(agentFilter)
    if (result.kind === 'unreachable') {
      await switchroomReply(ctx, '🔴 Broker is not running (or unreachable).', { html: true })
      return
    }
    if (result.kind === 'error') {
      await switchroomReply(ctx, `🔴 list_grants failed: ${escapeHtmlForTg(result.msg)}`, { html: true })
      return
    }
    const { grants } = result
    if (grants.length === 0) {
      const filterNote = agentFilter ? ` for \`${agentFilter}\`` : ''
      await switchroomReply(ctx, `📜 No active grants${filterNote}.`, { html: true })
      return
    }
    // Group grants by agent_slug
    const byAgent = new Map<string, typeof grants>()
    for (const g of grants) {
      const list = byAgent.get(g.agent_slug) ?? []
      list.push(g)
      byAgent.set(g.agent_slug, list)
    }
    // Build message text (grouped) + inline keyboard (one [Revoke] per grant per row)
    const lines: string[] = ['**📜 Active grants**', '']
    const keyboard = new InlineKeyboard()
    for (const [agentName, agentGrants] of byAgent) {
      lines.push(`**${escapeHtmlForTg(agentName)}:**`)
      for (const g of agentGrants) {
        const keys = g.key_allow.join(', ')
        const expiry = g.expires_at
          ? new Date(g.expires_at * 1000).toISOString().slice(0, 10)
          : 'no expiry'
        lines.push(`• \`${g.id}\` — ${escapeHtmlForTg(keys)}, expires ${expiry}`)
        // callback_data: vg:revoke:<id> — max 64 bytes; grant IDs are "vg_" + 6 chars = 9 chars total → well within limit
        keyboard.text(`🗑 Revoke ${g.id}`, `vg:revoke:${g.id}`).row()
      }
      lines.push('')
    }
    const chatId2 = String(ctx.chat!.id)
    const threadId2 = resolveThreadId(chatId2, ctx.message?.message_thread_id)
    await ctx.replyWithRichMessage(richMessage(lines.join('\n')), {
      reply_markup: keyboard,
      ...(threadId2 != null ? { message_thread_id: threadId2 } : {}),
    })
    return
  }

  // Issue #158: broker lifecycle ops (no vault passphrase needed)
  if (sub === 'status') {
    const status = await statusViaBroker()
    if (!status) {
      await switchroomReply(ctx, '🔴 Broker is not running (or unreachable).', { html: true })
      return
    }
    const lockIcon = status.unlocked ? '🔓' : '🔒'
    const lockLabel = status.unlocked ? 'Unlocked' : 'Locked'
    const uptimeSec = Math.round(status.uptimeSec)
    const h = Math.floor(uptimeSec / 3600)
    const m = Math.floor((uptimeSec % 3600) / 60)
    const s = uptimeSec % 60
    const uptime = h > 0 ? `${h}h ${m}m` : m > 0 ? `${m}m ${s}s` : `${s}s`
    await switchroomReply(ctx, `${lockIcon} ${lockLabel} · ${status.keyCount} key${status.keyCount === 1 ? '' : 's'} · uptime ${uptime}`, { html: true })
    return
  }

  if (sub === 'lock') {
    const ok = await lockViaBroker()
    if (ok) {
      await switchroomReply(ctx, '🔒 Vault broker locked.', { html: true })
    } else {
      await switchroomReply(ctx, '🔴 Could not lock broker — is it running?', { html: true })
    }
    return
  }

  if (sub === 'unlock') {
    // Prompt for passphrase via the existing pending-op intercept, but never
    // cache it — it goes straight to the broker unlock socket.
    pendingVaultOps.set(chatId, { kind: 'unlock', startedAt: Date.now() })
    await switchroomReply(ctx, '🔐 Send your vault passphrase to unlock the broker (message will be deleted, passphrase never cached):', { html: true })
    return
  }

  // Issue #227: /vault grant — inline-keyboard wizard to mint capability tokens
  if (sub === 'grant') {
    await startGrantWizardStep1(ctx, chatId)
    return
  }

  if (!['list', 'get', 'set', 'delete', 'remove'].includes(sub)) {
    await switchroomReply(ctx, `Unknown vault subcommand: \`${sub}\`. Try /vault help`, { html: true })
    return
  }
  if ((sub === 'get' || sub === 'delete' || sub === 'remove') && !key) { await switchroomReply(ctx, `Usage: /vault ${sub} <key>`, { html: true }); return }
  if (sub === 'set' && !key) { await switchroomReply(ctx, 'Usage: /vault set <key>', { html: true }); return }

  const cached = vaultPassphraseCache.get(chatId)
  const passphrase = cached && cached.expiresAt > Date.now() ? cached.passphrase : undefined
  if (!passphrase) {
    const opSub = (sub === 'remove' ? 'delete' : sub) as 'list' | 'get' | 'delete' | 'set'
    pendingVaultOps.set(chatId, { kind: 'passphrase', op: opSub, key, startedAt: Date.now() })
    await switchroomReply(ctx, '🔐 Send your vault passphrase:', { html: true })
    return
  }
  await executeVaultOp(ctx, chatId, (sub === 'remove' ? 'delete' : sub) as 'list' | 'get' | 'set' | 'delete', key, passphrase, undefined)
})

