bot.command('issues', async ctx => {
  if (!isAuthorizedSender(ctx)) return
  const arg = (typeof ctx.match === "string" ? ctx.match : "").trim()
  // /issues resolve <fp> | /issues clear | /issues — these subcommands
  // shell out to the issues CLI verb (#426). The verb itself enforces
  // the dedup / fingerprint logic; we just relay output.
  if (!arg || arg === 'list') {
    await runSwitchroomCommand(ctx, ['issues', 'list'], 'issues list')
    return
  }
  const parts = arg.split(/\s+/)
  if (parts[0] === 'resolve' && parts.length >= 2) {
    await runSwitchroomCommand(
      ctx,
      ['issues', 'resolve', parts[1]],
      `issues resolve ${parts[1]}`,
    )
    return
  }
  if (parts[0] === 'clear') {
    // "Clear all" = list current, resolve each. The CLI's `prune` is
    // for retention; clearing live issues is a UI concern. Implement
    // here by walking the list and resolving each. Best-effort.
    //
    // #443: require an explicit `--confirm` flag. A fat-finger
    // `/issues clear` used to mass-resolve every unresolved entry in
    // one shot — destructive verbs deserve a guard. Bare `/issues
    // clear` now counts and prints the prompt; `--confirm` actually
    // executes.
    try {
      const stateDir = process.env.TELEGRAM_STATE_DIR
      if (!stateDir) {
        await switchroomReply(ctx, 'clear: no TELEGRAM_STATE_DIR; cannot operate.', { html: true })
        return
      }
      const confirmed = parts.slice(1).includes('--confirm')
      if (!confirmed) {
        const events = listIssues(stateDir)
        const n = events.length
        if (n === 0) {
          await switchroomReply(ctx, 'No unresolved issues to clear.', { html: true })
          return
        }
        const noun = n === 1 ? 'issue' : 'issues'
        await switchroomReply(
          ctx,
          [
            `This will resolve **${n} ${noun}**. To confirm, run:`,
            '',
            '\`/issues clear --confirm\`',
          ].join('\n'),
          { html: true },
        )
        return
      }
      const events = listIssues(stateDir)
      let n = 0
      for (const e of events) {
        n += resolveIssue(stateDir, e.fingerprint)
      }
      await switchroomReply(ctx, `Resolved ${n} issue${n === 1 ? '' : 's'}.`, { html: true })
      return
    } catch (err) {
      await switchroomReply(ctx, `clear failed: ${escapeHtmlForTg((err as Error).message)}`, { html: true })
      return
    }
  }
  await switchroomReply(
    ctx,
    'Usage: \`/issues\` | \`/issues resolve <fingerprint>\` | \`/issues clear [--confirm]\`',
    { html: true },
  )
})

bot.command('usage', async ctx => {
  if (!isAuthorizedSender(ctx)) return
  const demo = hasDemoFlag(getCommandArgs(ctx))
  // Format 2 path: enumerate every account in the broker's known set,
  // probe live quota in parallel, render the health-grouped snapshot.
  // Falls back to the legacy single-agent shape when the broker is
  // unreachable, since /usage was historically callable against any
  // agent regardless of fleet state.
  const currentAgent = getMyAgentName()
  try {
    const client = await getAuthBrokerClient(currentAgent)
    if (client) {
      const state = await client.listState()
      if (state.accounts.length > 0) {
        // Broker-routed probe (#1336) — see gateway.ts:8910 for diagnosis.
        // #2495 Change 2 — the broker applies a probe-on-open TTL + single-
        // flight; a TTL-hit or failed-probe fallback is tagged served:"cache",
        // which we surface as a "⚠ cached Nm ago" footer instead of a false
        // live stamp.
        const probeResp = await client.probeQuota(state.accounts.map((a) => a.label)).catch(() => ({ results: [] }))
        let staleCachedAtMs: number | undefined
        const quotas = state.accounts.map((a) => {
          const hit = probeResp.results.find((r) => r.label === a.label)
          if (hit?.served === 'cache' && hit.capturedAt != null) {
            staleCachedAtMs = staleCachedAtMs == null ? hit.capturedAt : Math.min(staleCachedAtMs, hit.capturedAt)
          }
          return hit?.result ?? { ok: false as const, reason: 'broker returned no result for account' }
        })
        const { renderAuthSnapshotFormat2, buildSnapshotsFromState, buildSnapshotKeyboard } = await import(
          '../auth-snapshot-format.js'
        )
        const tz = process.env.SWITCHROOM_TIMEZONE ?? process.env.TZ ?? 'UTC'
        const snapshots = buildSnapshotsFromState(state, quotas)
        const text = renderAuthSnapshotFormat2(snapshots, {
          tz,
          now: new Date(),
          demo,
          ...(staleCachedAtMs != null ? { staleCachedAtMs } : { liveProbedAtMs: Date.now() }),
        })
        // Preserve the Switch/Refresh/usage/Add inline keyboard on the
        // rich-message render — the table card carries the same actions the
        // /auth snapshot does. switchroomReply routes through the rich path
        // (replyWithRichMessage), which accepts reply_markup. Build a grammy
        // InlineKeyboard so the markup type matches switchroomReply's contract.
        const kbRows = buildSnapshotKeyboard(snapshots, { now: new Date() })
        const keyboard = new InlineKeyboard()
        kbRows.forEach((row, ri) => {
          if (ri > 0) keyboard.row()
          for (const b of row) {
            if (b.callbackData) keyboard.text(b.text, b.callbackData)
            else if (b.insertText) keyboard.switchInlineCurrent(b.text, b.insertText)
            else keyboard.text(b.text, 'auth:noop')
          }
        })
        await switchroomReply(ctx, text, { html: true, reply_markup: keyboard })
        return
      }
    }
  } catch (err) {
    process.stderr.write(
      `telegram gateway: /usage Format 2 path failed agent=${currentAgent}: ${(err as Error)?.message ?? err}\n`,
    )
    // fall through to legacy single-agent path
  }

  // Legacy single-agent path — kept as a graceful fallback when the
  // broker is unreachable (post-RFC-H rewire boot timing, broken
  // socket bind, etc.). Same shape /usage shipped with originally.
  const agentDir = resolveAgentDirFromEnv()
  if (!agentDir) {
    await switchroomReply(ctx, '**/usage:** cannot resolve agent dir.', { html: true })
    return
  }
  const result = await fetchQuota({ claudeConfigDir: join(agentDir, '.claude') })
  if (!result.ok) {
    await switchroomReply(ctx, `**/usage:** ${escapeHtmlForTg(result.reason)}`, { html: true })
    return
  }
  await switchroomReply(ctx, formatQuotaBlock(result.data), { html: true })
})

// Two-button scope picker shown to admin agents (when hostd is
// reachable) so the operator can run doctor for the WHOLE FLEET
// (host-side via hostd — has the docker socket) or just THIS agent
// (in-container, degraded). callback_data is tiny (`dr:fleet` /
// `dr:self`) — well within Telegram's 64-byte limit.
function buildDoctorScopeKeyboard(): InlineKeyboard {
  return new InlineKeyboard()
    .text('🩺 Whole fleet', 'dr:fleet')
    .text('🩺 This agent', 'dr:self')
}

// Shared report prettifier: ANSI-strip + status-glyph swap + pre block.
// Identical rendering for the in-container and the hostd fleet report.
function formatDoctorReport(raw: string): string {
  const trimmed = stripAnsi(raw).trim()
  if (!trimmed) return 'doctor: no output'
  const pretty = trimmed
    .replace(/^( *)✓ /gm, '$1🟢 ')
    .replace(/^( *)✗ /gm, '$1🔴 ')
    .replace(/^( *)! /gm, '$1🟡 ')
  return preBlock(formatSwitchroomOutput(pretty))
}

// In-container `switchroom doctor` — this agent's own (degraded: no
// docker socket) view. The original /doctor behaviour, unchanged.
async function renderSelfDoctor(ctx: Context): Promise<void> {
  let output: string
  try { output = switchroomExecCombined(['doctor'], 30000) }
  catch (err: unknown) { output = (err as any).stdout ?? (err as any).message ?? 'doctor failed' }
  await switchroomReply(ctx, formatDoctorReport(output), { html: true })
}

// Whole-fleet `switchroom doctor` via hostd: it runs host-side where
// the docker socket exists, so it sees every container + singleton
// instead of the degraded in-container reading. Read-only verb; the
// daemon independently enforces the admin gate (path-as-identity), so
// this is the audited boundary even though the gateway only offers
// the button to admin agents.
async function renderFleetDoctor(ctx: Context): Promise<void> {
  const resp = await tryHostdDispatch(getMyAgentName(), {
    v: 1,
    op: 'doctor',
    request_id: hostdRequestId('gw-doctor'),
  })
  if (resp === 'not-configured') {
    await switchroomReply(ctx, '🩺 Whole-fleet doctor needs hostd, which isn’t configured here — showing this agent instead.', { html: true })
    await renderSelfDoctor(ctx)
    return
  }
  if (resp.result === 'denied') {
    await switchroomReply(ctx, `🩺 **Whole-fleet doctor denied by hostd:**\n${preBlock(formatSwitchroomOutput(resp.error ?? 'admin required'))}`, { html: true })
    return
  }
  // `completed` (including `switchroom doctor` exit 1 = "found
  // problems", which the handler classifies as completed) or `error`:
  // the report on stdout (or the error text) is exactly what the
  // operator wants surfaced.
  const body = resp.stdout_tail?.trim() || resp.error || '(no output from hostd doctor)'
  await switchroomReply(ctx, formatDoctorReport(body), { html: true })
}

