// ─── Inline-button handler (permissions) ──────────────────────────────────
// Handles `perm:(allow|deny|always|asn|asb|back):<id>` — permission request buttons
bot.on('callback_query:data', async ctx => {
  const data = ctx.callbackQuery.data

  // Auth dashboard buttons (`auth:<verb>:<agent>[:<slot>]`). Route
  // through a dedicated handler that maps each action onto the
  // existing CLI invocations plus dashboard refresh.
  if (data.startsWith('auth:')) {
    await handleAuthDashboardCallback(ctx)
    return
  }

  // `mdl:*` — model-menu taps (/model dashboard). `mdl:s:<tag>`
  // selects a model by label-tag via a fresh picker discovery (never
  // a stale index); `mdl:r` re-renders. Strict allowFrom gate like
  // every other mutating callback family — a model switch changes the
  // fleet's quota burn profile.
  if (data.startsWith(EFFORT_CALLBACK_PREFIX)) {
    const access = loadAccess()
    const senderId = String(ctx.from?.id ?? '')
    if (!access.allowFrom.includes(senderId)) {
      await ctx.answerCallbackQuery({ text: 'Not authorized.' })
      return
    }
    // No picker-driving (the inline `/effort <level>` form sets it
    // directly via the inject primitive), so no mid-turn guard is needed
    // here — just ack and apply.
    await ctx.answerCallbackQuery({ text: 'Setting effort…' }).catch(() => {})
    try {
      const outcome = await handleEffortMenuCallback(data, buildEffortDeps())
      await ctx
        .editMessageText(richMessage(outcome.reply.text), {
          reply_markup: effortMenuReplyMarkup(outcome.reply) ?? { inline_keyboard: [] },
        })
        .catch(() => {})
    } catch (err) {
      process.stderr.write(
        `telegram gateway: effort-menu callback failed: ${(err as Error)?.message ?? String(err)}\n`,
      )
    }
    return
  }

  if (data.startsWith(MODEL_CALLBACK_PREFIX)) {
    const access = loadAccess()
    const senderId = String(ctx.from?.id ?? '')
    if (!access.allowFrom.includes(senderId)) {
      await ctx.answerCallbackQuery({ text: 'Not authorized.' })
      return
    }
    // Kill-switch covers the callback family too — stale menus keep
    // their buttons after the flag flips, and the flag exists exactly
    // for "picker-driving is misbehaving" (#2263 review blocker 2).
    if (process.env.SWITCHROOM_MODEL_MENU === '0') {
      await ctx.answerCallbackQuery({ text: 'Model menu is disabled (SWITCHROOM_MODEL_MENU=0).' }).catch(() => {})
      await ctx
        .editMessageText(richMessage('Model menu is disabled on this agent. Use \`/model <name>\`.'), {
          reply_markup: { inline_keyboard: [] },
        })
        .catch(() => {})
      return
    }
    const cbChatId = String(ctx.chat?.id ?? '')
    const cbThreadId = resolveThreadId(cbChatId, ctx.callbackQuery?.message?.message_thread_id)
    const modelDeps = buildModelDeps({ chatId: cbChatId, threadId: cbThreadId })
    // Mid-turn refusal is INSTANT (a sync isBusy() check, no picker drive),
    // so handle it before the "Working…" ack: toast WHY and leave the menu
    // message untouched (buttons intact) so the operator taps again when
    // idle. Editing the menu into a button-less "try again" line was the
    // "nothing happened" report — the menu looked dead.
    if (modelDeps.isBusy()) {
      await ctx
        .answerCallbackQuery({ text: '⏳ Agent is mid-turn — tap again when it’s idle', show_alert: false })
        .catch(() => {})
      return
    }
    // Ack IMMEDIATELY — the select path drives the picker (multi-second);
    // leaving the tap spinning invites a double-tap, which queues a second
    // drive behind the pane lock. A callback can only be answered once, so
    // the rich result (what was set / why it failed) is conveyed by the
    // message edit — which now ALWAYS keeps the menu buttons.
    // Header rows are section labels — informational, no model switch.
    if (data === MODEL_CALLBACK_HEADER) {
      await ctx.answerCallbackQuery({ text: 'Tap a model in this section to switch' }).catch(() => {})
      return
    }
    // Page navigation (External ▸ / ◂ Back) just re-renders the menu with the
    // other keyboard page — it never drives the picker, so ack "Loading…"
    // rather than the switch-oriented "Switching…".
    const isPageNav = data === MODEL_CALLBACK_PAGE_EXTERNAL || data === MODEL_CALLBACK_PAGE_MAIN
    await ctx.answerCallbackQuery({ text: isPageNav ? 'Loading…' : 'Switching…' }).catch(() => {})
    // sr-* inject waits for claude to respond (can take 10-30s). Edit the
    // menu immediately to show a "working on it" state so the operator isn't
    // left looking at a stale menu with no feedback. The final edit (✅/❌)
    // replaces this once the inject returns.
    // NOTE: this await yields the event loop, so a new inbound turn could
    // start between here and handleModelMenuCallback's inner isBusy() check.
    // We track whether we applied the interim edit so we can skip the
    // toastOnly short-circuit if we did — a toastOnly return after the interim
    // edit would leave the menu stuck button-less.
    let didInterimSrEdit = false
    if (data.startsWith(MODEL_CALLBACK_SR)) {
      const srLabel = escapeHtmlForTg(srFriendlyLabel(data.slice(MODEL_CALLBACK_SR.length)))
      await ctx
        .editMessageText(richMessage(`⏳ Switching session to **${srLabel}**…`), { reply_markup: { inline_keyboard: [] } })
        .catch(() => {})
      didInterimSrEdit = true
    }
    try {
      const prevSessionModel = activeSessionModelOverride
      const outcome = await handleModelMenuCallback(data, modelDeps)
      // Record a successful session switch so /status reflects what's
      // actually running. In-memory only → clears when the gateway (and thus
      // claude's session) restarts, exactly matching the session-only scope.
      if (outcome.selectedModel) {
        activeSessionModelOverride = outcome.selectedModel
      }
      // toastOnly: leave the menu untouched — but only if we haven't already
      // cleared its buttons with the interim sr-* edit. If we have, fall
      // through to the final edit so the message is recovered (busyReply or
      // the full menu) rather than left permanently button-less.
      if (outcome.toastOnly && !didInterimSrEdit) return

      // sr-* → Claude transition via the model menu: trigger a graceful restart.
      // Switching FROM an sr-* (LiteLLM/OpenRouter) model BACK to a Claude model
      // via the picker requires a session restart — the picker-select only changes
      // the session model label, but the sr-* LiteLLM routing context persists
      // until the session is torn down. Same mechanism as the /restart command.
      if (outcome.selectedModel && isSrToClaudeTransition(prevSessionModel, outcome.selectedModel)) {
        const agentName = getMyAgentName()
        // Replace the menu with a restart notice (no buttons — session is ending).
        await ctx
          .editMessageText(
            richMessage(`🔄 Switching from **${escapeHtmlForTg(prevSessionModel!)}** back to Claude — restarting session cleanly. Claude will be ready in ~30s.`),
            { reply_markup: { inline_keyboard: [] } },
          )
          .catch(() => {})
        // Write the restart marker so the post-restart boot card edits into this chat.
        writeRestartMarker({ chat_id: cbChatId, thread_id: cbThreadId ?? null, ack_message_id: null, ts: Date.now() })
        stampUserRestartReason('user: sr-to-claude model switch (menu)')
        if (turnInFlightForGate()) {
          // Defer restart until the in-flight turn completes (same gate as /restart).
          pendingRestarts.set(agentName, Date.now())
        } else {
          void sweepBeforeSelfRestart().finally(() =>
            triggerSelfRestart(agentName, 'sr-to-claude-model-switch', 1500),
          )
        }
        return
      }

      await ctx
        .editMessageText(richMessage(outcome.reply.text), {
          reply_markup: modelMenuReplyMarkup(outcome.reply) ?? { inline_keyboard: [] },
        })
        .catch(() => {})
    } catch (err) {
      process.stderr.write(
        `telegram gateway: model-menu callback failed: ${(err as Error)?.message ?? String(err)}\n`,
      )
    }
    return
  }

  // `cn:cancel:<key>` — cancel a pending Microsoft connect flow (the
  // Cancel button on the /connect card). RFC #1873 Phase 2.
  if (data.startsWith('cn:')) {
    const access = loadAccess()
    const senderId = String(ctx.from?.id ?? '')
    if (!access.allowFrom.includes(senderId)) {
      await ctx.answerCallbackQuery({ text: 'Not authorized.' })
      return
    }
    const rest = data.slice('cn:'.length)
    const sep = rest.indexOf(':')
    const action = sep >= 0 ? rest.slice(0, sep) : rest
    const flowKey = sep >= 0 ? rest.slice(sep + 1) : ''
    if (action === 'cancel') {
      const pending = pendingMicrosoftConnectFlows.get(flowKey)
      if (pending) {
        pending.cancelled = true
        pendingMicrosoftConnectFlows.delete(flowKey)
      }
      await ctx.answerCallbackQuery({ text: 'Connect cancelled.' })
      await ctx
        .editMessageText('Microsoft connect cancelled.', {
          reply_markup: { inline_keyboard: [] },
        })
        .catch(() => {})
    } else {
      await ctx.answerCallbackQuery()
    }
    return
  }

  // RFC B §6.1: apv:<request_id>:<choice>[:<param>] — approval kernel taps.
  // Routed through the generic kernel handler so any surface that uses
  // buildApprovalCard inherits consume → record → confirmation UX without
  // each surface re-implementing it.
  //
  // SECURITY (sec WS7-F1, #1394): this is the human-in-the-loop gate for
  // EVERY dangerous tool call + Drive write. handleApprovalCallback records
  // whoever tapped as the approver (`granted_by_user_id = ctx.from.id`) and
  // the approval-kernel performs NO server-side approver validation, so an
  // unauthorized tap is laundered into a real grant. The card is delivered
  // to the agent's chat(s) — for a forum/group agent that is every member.
  // Refuse callbacks from anyone outside `access.allowFrom`, BEFORE the
  // approval_consume nonce burn. Strict `access.allowFrom` — identical to
  // the drvpick:/op:/vd:/vg:/vra:/vrs:/vrd: families; the absence of this
  // check (not a deliberate exemption) was the vulnerability.
  if (data.startsWith('apv:')) {
    const access = loadAccess()
    const senderId = String(ctx.from?.id ?? '')
    if (!access.allowFrom.includes(senderId)) {
      await ctx.answerCallbackQuery({ text: 'Not authorized.' })
      return
    }
    const { handleApprovalCallback } = await import('./approval-callback.js')
    await handleApprovalCallback(ctx, data)
    return
  }

  // #1623: cfg:<requestId>:<approve|deny> — hostd config-edit
  // approval card. Resolves the pending approval (gateway-side
  // in-memory map), sends `config_approval_resolved` back to hostd
  // over the original IPC connection, and edits the card to the
  // interim "Applying…" / "Denied" state. Same operator-allowlist
  // gate as every other callback family.
  if (data.startsWith('cfg:')) {
    const access = loadAccess()
    const senderId = String(ctx.from?.id ?? '')
    if (!access.allowFrom.includes(senderId)) {
      await ctx.answerCallbackQuery({ text: 'Not authorized.' })
      return
    }
    const { parseConfigApprovalCallback, resolvePendingConfigApproval } =
      await import('./config-approval-handler.js')
    const parsed = parseConfigApprovalCallback(data)
    if (parsed === null) {
      await ctx.answerCallbackQuery({ text: 'Malformed callback.' })
      return
    }
    const resolved = await resolvePendingConfigApproval(
      parsed.requestId,
      parsed.choice,
      {
        editCard: async (args) => {
          try {
            await robustApiCall(() =>
              bot.api.editMessageText(args.chatId, args.messageId, richMessage(args.text), {
                // Resolved on tap — strip the keyboard so it can't be re-tapped.
                ...(args.stripKeyboard ? { reply_markup: { inline_keyboard: [] } } : {}),
              }),
            )
          } catch {
            /* best effort */
          }
        },
        log: (m) =>
          process.stderr.write(`telegram gateway: config-approval cb — ${m}\n`),
      },
      // Verify the per-card epoch from the callback_data against the live
      // pending entry — a stale tap (mismatched epoch) is rejected.
      parsed.epoch,
    )
    await ctx.answerCallbackQuery({
      text: resolved
        ? parsed.choice === 'approve'
          ? 'Approving…'
          : 'Denied'
        : 'Already resolved.',
    })
    return
  }

  // RFC E §4.1: drvpick:<verb>:<agent>[:<...>] — folder-picker card taps.
  // open / enter / back / refresh re-render the card in place;
  // grant writes an allow_always kernel decision at
  // doc:gdrive:folder/<id>/** and edits the card to a confirmation.
  //
  // Auth gate: the picker grant is an OPERATOR action — same strict
  // `access.allowFrom` check as every other callback family (`op:`/
  // `vd:`/`vg:`/`apv:` since sec WS7-F1, …). Refuse callbacks from
  // anyone outside `access.allowFrom`. Without this, a group member
  // who isn't in
  // the operator allowlist could still tap [✅ Allow "<folder>"] on
  // a card that landed in the group and write an `allow_always`
  // decision attributed to themselves.
  if (data.startsWith('drvpick:')) {
    const access = loadAccess()
    const senderId = String(ctx.from?.id ?? '')
    if (!access.allowFrom.includes(senderId)) {
      await ctx.answerCallbackQuery({ text: 'Not authorized.' })
      return
    }
    await handleFolderPickerCallback(ctx, data, buildFolderPickerDeps())
    return
  }

  // op:<action>:<encoded-agent> callbacks from operator-events.ts
  // renderOperatorEvent(). Agent name is URL-encoded at emit (issue #24).
  // Actions: dismiss, restart, reauth, logs.
  if (data.startsWith('op:')) {
    await handleOperatorEventCallback(ctx, data)
    return
  }

  // vd:<action>:<deferKey> callbacks from the deferred-secret card.
  // Actions: unlock (prompt for passphrase + auto-write), cancel.
  // Issue #44.
  if (data.startsWith('vd:')) {
    await handleVaultDeferCallback(ctx, data)
    return
  }

  // dr:<scope> — /doctor scope picker (only shown to admin agents
  // with hostd reachable). `dr:fleet` → host-side hostd `doctor`
  // (full fleet); `dr:self` → in-container doctor. Read-only, no
  // approval card. Same sender-auth as the /doctor command itself —
  // every callback family must re-auth (the absence of this check
  // was a past vulnerability class; see apv:/drvpick: notes above).
  if (data.startsWith('dr:')) {
    if (!isAuthorizedSender(ctx)) {
      await ctx.answerCallbackQuery({ text: 'Not authorized.' }).catch(() => {})
      return
    }
    const scope = data.slice(3)
    await ctx.answerCallbackQuery({
      text: scope === 'fleet' ? '🩺 Running fleet doctor…' : '🩺 Running doctor…',
    }).catch(() => {})
    try {
      if (scope === 'fleet') await renderFleetDoctor(ctx)
      else await renderSelfDoctor(ctx)
    } catch (err: unknown) {
      await switchroomReply(ctx, `**doctor failed:**\n${preBlock(formatSwitchroomOutput((err as any).message ?? 'unknown error'))}`, { html: true })
    }
    return
  }

  // Issue #228: vault grant management callbacks.
  // vg:revoke:<id> — show confirmation card
  // vg:confirm:<id> — execute revoke
  // vg:cancel:<id> — dismiss
  if (data.startsWith('vg:')) {
    await handleVaultGrantCallback(ctx, data)
    return
  }

  // Issue #969 P1a: agent-initiated vault-save approval card.
  // vrs:save:<stageId>     — write the staged value, edit card to success
  // vrs:discard:<stageId>  — drop the staged value, edit card to discarded
  // vrs:rename:<stageId>   — prompt for a new key name, then resume
  if (data.startsWith('vrs:')) {
    await handleVaultRequestSaveCallback(ctx, data)
    return
  }

  // Issue #1012: agent-initiated vault ACL request approval card.
  // vra:approve:<stageId> — mint scoped grant via broker, write token
  // vra:deny:<stageId>    — refuse, edit card to denied
  if (data.startsWith('vra:')) {
    await handleVaultRequestAccessCallback(ctx, data)
    return
  }

  // #2045: agent-requested-secret card.
  //   vsp:provide:<stageId> — arm capture; operator's next message is the value
  //   vsp:decline:<stageId> — drop the request, notify the agent
  if (data.startsWith('vsp:')) {
    await handleSecretRequestCallback(ctx, data)
    return
  }

  // #2670: one-tap skill-improvement proposal card.
  //   skprop:approve:<id> — apply the stored draft via the personal-skill
  //                         write pipeline (inject a turn; agent writes it)
  //   skprop:deny:<id>    — dismiss + record a rejection fingerprint so it
  //                         isn't re-proposed
  if (data.startsWith('skprop:')) {
    await handleSkillProposalCallback(ctx, data)
    return
  }

  // Issue #969 P2b: vault recent-denial one-tap approval.
  //   vrd:<agent>:<key> — mint a 30-day read-grant for the agent + key
  // Posted by /vault audit <agent> in the "Recent denials" section.
  if (data.startsWith('vrd:')) {
    await handleVaultRecentDenialCallback(ctx, data)
    return
  }

  // ask_user callback (#574). aq:<idx>:<askId>. Same authorization
  // gate as permission buttons — only allowFrom users can answer.
  // Tapped option resolves the originating ask_user tool call's
  // deferred promise; the agent receives { kind: 'answered',
  // choice, idx } as the tool result and continues.
  const askMatch = decodeAskCallback(data)
  if (askMatch != null) {
    const accessCheck = loadAccess()
    const senderId = String(ctx.from.id)
    if (!accessCheck.allowFrom.includes(senderId)) {
      await ctx.answerCallbackQuery({ text: 'Not authorized.' }).catch(() => {})
      return
    }
    const entry = pendingAskUser.get(askMatch.askId)
    if (entry == null) {
      // Stale tap — TTL fired, prompt was cancelled, or chat closed
      // before the user got back to it. Acknowledge politely so the
      // user doesn't see the spinner stick.
      await ctx.answerCallbackQuery({ text: 'This question expired.' }).catch(() => {})
      return
    }
    if (askMatch.idx >= entry.options.length) {
      // Encoded an out-of-bounds index — should be impossible from
      // our own encoding, but defend against a hostile callback.
      await ctx.answerCallbackQuery({ text: 'Invalid option.' }).catch(() => {})
      return
    }
    const choice = entry.options[askMatch.idx]
    clearTimeout(entry.timer)
    pendingAskUser.delete(askMatch.askId)
    entry.resolve({ kind: 'answered', choice, idx: askMatch.idx })

    // Edit the question in place to remove the buttons + show the
    // chosen option as a checkmarked line. Makes the chat surface
    // self-documenting — no orphaned-buttons graveyard.
    //
    // Escape `sourceMsg.text` before re-rendering with HTML parse
    // mode. `msg.text` returns entities-stripped plain UTF-8; an
    // agent-supplied `ask_user` question containing raw `<`/`>`/`&`
    // (common in code-related questions like "Run `<command>`?")
    // would crash the HTML re-parse, the try/catch would swallow,
    // and the button keyboard would stay tappable — the exact bug
    // PR #1158 caught on the operator-event card.
    const sourceMsg = ctx.callbackQuery?.message
    if (sourceMsg && 'text' in sourceMsg && sourceMsg.text != null) {
      try {
        await ctx.editMessageText(
          richMessage(`${escapeHtmlForTg(sourceMsg.text)}\n\n✅ **${escapeHtmlForTg(choice)}**`),
        )
      } catch {
        /* edit-failed is fine — the answer-callback below still acks */
      }
    }
    await ctx.answerCallbackQuery({ text: '✅ ' + choice.slice(0, 60) }).catch(() => {})
    return
  }

  // on-demand voice: '🔊 Listen' buttons carry a reserved `voice:<token>`
  // callback_data. Handle INTERNALLY here — synthesize the cached reply text
  // and send it as a native voice note. This MUST run before the agent:
  // routing below so a tap never reaches the agent as an inbound message.
  if (isVoiceOnDemandCallback(data)) {
    const access = loadAccess()
    const senderId = String(ctx.from.id)
    if (!access.allowFrom.includes(senderId)) {
      await ctx.answerCallbackQuery({ text: 'Not authorized.' }).catch(() => {})
      return
    }
    const token = parseVoiceOnDemandToken(data)
    const entry = token != null ? voiceOnDemandCache.get(token) : null
    if (entry == null) {
      await ctx
        .answerCallbackQuery({ text: 'Voice expired — send again to hear it.' })
        .catch(() => {})
      return
    }
    const cbChatId = String(ctx.chat?.id ?? ctx.from.id)
    const cbMessageId = ctx.callbackQuery?.message?.message_id
    const cbThreadId = (() => {
      const msg = ctx.callbackQuery?.message
      if (msg && 'is_topic_message' in msg && msg.is_topic_message && 'message_thread_id' in msg) {
        const tid = (msg as { message_thread_id?: number }).message_thread_id
        return typeof tid === 'number' ? tid : undefined
      }
      return undefined
    })()
    // #2763 attach-on-tap: prefer the eagerly pre-synthesized file (written
    // by the pre-synth queue at reply time). If it's on disk, attach it
    // immediately — no GPU wait. Missing/unreadable file (expired + swept,
    // crash, pre-feature entry, kill-switched gateway) falls back
    // transparently to the lazy synth path below.
    let audio: Uint8Array | null = null
    if (entry.filePath != null) {
      try {
        audio = readFileSync(entry.filePath)
      } catch {
        audio = null // swept/missing — lazy fallback
      }
    }
    if (audio != null) {
      await ctx.answerCallbackQuery({ text: '🔊' }).catch(() => {})
    } else {
      await ctx.answerCallbackQuery({ text: '🔊 Synthesizing…' }).catch(() => {})
      // Local sidecar (kokoro) synthesis — same helper the immediate voice-out
      // path uses. On-demand is a local-engine feature; the cache is only
      // populated when resolveVoiceOutPlan gated the local verdict.
      const sidecarToken = await materializeSidecarToken()
      if (!sidecarToken) {
        await ctx
          .answerCallbackQuery({ text: 'Voice sidecar unavailable — try again later.' })
          .catch(() => {})
        return
      }
      const result = await synthesizeViaSidecar({
        token: sidecarToken,
        // #2760 Phase 1: same deterministic normalization as the immediate
        // voice-out path — the Listen lazy path builds its own /tts body from
        // the persisted cache, so it must normalize independently (cache
        // entries may predate the flag flip).
        text: normalizeForTts(entry.text),
        voice: entry.voice,
        speed: entry.speed,
      })
      if (!result.ok) {
        process.stderr.write(
          `telegram gateway: voice-out on-demand: synthesis failed reason=${result.reason}\n`,
        )
        await ctx
          .answerCallbackQuery({ text: `Voice failed: ${result.reason}` })
          .catch(() => {})
        return
      }
      audio = result.audio
    }
    // Rebind as const so the closure below narrows to non-null (TS doesn't
    // narrow a captured `let` inside an arrow function).
    const audioOut: Uint8Array = audio
    try {
      // Native voice note (NOT a document), quote-replying the button's
      // message.
      await robustApiCall(
        () =>
          bot.api.sendVoice(
            cbChatId,
            // allow-raw-bot-api: single native voice-note send for an on-demand Listen tap.
            new InputFile(Buffer.from(audioOut)),
            {
              ...(cbMessageId != null ? { reply_parameters: { message_id: cbMessageId } } : {}),
              ...(cbThreadId != null ? { message_thread_id: cbThreadId } : {}),
            } as never,
          ),
        {
          chat_id: cbChatId,
          verb: 'voice-ondemand.sendVoice',
          ...(cbThreadId != null ? { threadId: cbThreadId } : {}),
        },
      )
      // Single-use on SUCCESS: strip the '🔊 Listen' keyboard so the button
      // can't be re-tapped now that the audio has been delivered. Mirrors the
      // agent-button single_use strip (keyboardIsSingleUse) house style.
      // Best-effort + non-fatal — a failed strip only leaves a replayable
      // button, never drops the delivered audio. Only reached on a successful
      // sendVoice; expiry / synth-failure / sidecar-unavailable all return
      // earlier WITHOUT stripping, so the user can retry those.
      if (cbMessageId != null) {
        await robustApiCall(
          () =>
            bot.api.editMessageReplyMarkup(cbChatId, cbMessageId, {
              reply_markup: { inline_keyboard: [] },
            }),
          {
            chat_id: cbChatId,
            verb: 'voice-ondemand.strip-listen-keyboard',
            ...(cbThreadId != null ? { threadId: cbThreadId } : {}),
          },
        ).catch(() => {})
      }
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err)
      process.stderr.write(
        `telegram gateway: voice-out on-demand: sendVoice failed (non-fatal): ${msg}\n`,
      )
    }
    return
  }

  // #271: agent-emitted inline_keyboard callbacks. Namespaced with
  // an `agent:` prefix in inline-keyboard-callbacks.ts so they can
  // round-trip without colliding with infrastructure prefixes above.
  // Strip the prefix and forward the raw payload to the connected
  // bridge as an InboundMessage with meta.button_callback_data set.
  // The agent treats it like any other inbound channel event — same
  // queue, same steer/queue classification rules.
  const agentCb = parseAgentCallback(data)
  if (agentCb != null) {
    // Authorization gate — same allowlist as inbound text messages.
    // Without this any random Telegram user who could see a button
    // could trigger an action on the agent's behalf.
    const access = loadAccess()
    const senderId = String(ctx.from.id)
    if (!access.allowFrom.includes(senderId)) {
      await ctx.answerCallbackQuery({ text: 'Not authorized.' }).catch(() => {})
      return
    }
    const cbChatId = String(ctx.chat?.id ?? ctx.from.id)
    const cbMessageId = ctx.callbackQuery?.message?.message_id
    // #710: look up agent-supplied per-button meta (ack_text / single_use)
    // stashed at send time. Empty map after a gateway restart — defaults
    // still give the user-visible toast + keyboard removal.
    const metaForMessage = cbMessageId != null
      ? agentButtonMeta.get(`${cbChatId}:${cbMessageId}`)
      : undefined
    const tapMeta = metaForMessage?.get(agentCb.raw)
    const ackText = (typeof tapMeta?.ack_text === 'string' && tapMeta.ack_text.length > 0)
      ? tapMeta.ack_text
      : '✓ received'
    // Ack the spinner FIRST with a visible toast so the user knows the
    // tap registered (#710 — empty ack showed nothing, users re-tapped).
    await ctx.answerCallbackQuery({ text: ackText }).catch(() => {})
    const buttonText = (() => {
      // Best-effort: pull the tapped button's label from the source
      // message's keyboard so the agent gets a human-readable echo.
      const msg = ctx.callbackQuery?.message
      const kb = (msg && 'reply_markup' in msg ? msg.reply_markup : undefined) as
        | { inline_keyboard?: Array<Array<{ text?: string; callback_data?: string }>> }
        | undefined
      if (!kb?.inline_keyboard) return undefined
      for (const row of kb.inline_keyboard) {
        for (const btn of row) {
          if (btn.callback_data === data && typeof btn.text === 'string') return btn.text
        }
      }
      return undefined
    })()
    const cbThreadId = (() => {
      const msg = ctx.callbackQuery?.message
      if (msg && 'is_topic_message' in msg && msg.is_topic_message && 'message_thread_id' in msg) {
        const tid = (msg as { message_thread_id?: number }).message_thread_id
        return typeof tid === 'number' ? tid : undefined
      }
      return undefined
    })()
    const inboundText = buttonText
      ? `[user tapped button: ${JSON.stringify(buttonText)} → ${agentCb.raw}]`
      : `[user tapped button: ${agentCb.raw}]`
    const inboundMsg: InboundMessage = {
      type: 'inbound',
      chatId: cbChatId,
      ...(cbThreadId != null ? { threadId: cbThreadId } : {}),
      messageId: cbMessageId ?? 0,
      user: ctx.from.username ?? String(ctx.from.id),
      userId: ctx.from.id,
      ts: Math.floor(Date.now() / 1000),
      text: inboundText,
      meta: {
        chat_id: cbChatId,
        ...(cbMessageId != null ? { message_id: String(cbMessageId) } : {}),
        user: ctx.from.username ?? String(ctx.from.id),
        user_id: String(ctx.from.id),
        ts: new Date().toISOString(),
        ...(cbThreadId != null ? { message_thread_id: String(cbThreadId) } : {}),
        button_callback: 'true',
        button_callback_data: agentCb.raw,
        ...(buttonText != null ? { button_text: buttonText } : {}),
      },
    }
    process.stderr.write(
      `telegram gateway: button_callback chatId=${cbChatId} user=${ctx.from.id} data=${JSON.stringify(agentCb.raw)} btnText=${JSON.stringify(buttonText ?? null)}\n`,
    )
    // Registered-keyed delivery + buffer-on-miss (same fix as the
    // normal-inbound path above): broadcast()/clientCount() lost the
    // tap whenever the bridge was mid-reconnect (clientCount() counts
    // unregistered sockets, so the notice was suppressed AND nothing
    // was actually queued). sendToAgent → pendingInboundBuffer (drained
    // by onClientRegistered) makes the "queued" promise real.
    const selfAgentBtn = process.env.SWITCHROOM_AGENT_NAME ?? ''
    const btnDelivered = ipcServer.sendToAgent(selfAgentBtn, inboundMsg)
    if (btnDelivered) markClaudeBusyForInbound(inboundMsg)
    if (!btnDelivered) {
      pendingInboundBuffer.push(selfAgentBtn, inboundMsg)
      // No registered bridge — the agent's mid-restart. Tell the user
      // so they don't think the button silently swallowed their tap;
      // the tap is genuinely buffered now and replays on reconnect.
      // #1075: thread-id-bearing — swallow on THREAD_NOT_FOUND.
      void swallowingApiCall(
        () =>
          bot.api.sendMessage(
            cbChatId,
            '⏳ Agent is restarting — your button tap is queued and will be processed when it comes back.',
            cbThreadId != null ? { message_thread_id: cbThreadId } : {},
          ),
        {
          chat_id: cbChatId,
          verb: 'button-tap-restarting-notice',
          ...(cbThreadId != null ? { threadId: cbThreadId } : {}),
        },
      )
    }
    // #710: strip the keyboard after tap so the buttons can't be
    // double-fired. Default policy is single-use — preserve the
    // keyboard only if at least one button on the message explicitly
    // opts out via `single_use: false`. With no stashed meta (e.g.
    // gateway restarted between send and tap) the default fires too,
    // which is the desired UX.
    const stripKeyboard = metaForMessage == null || keyboardIsSingleUse(metaForMessage)
    if (stripKeyboard && cbMessageId != null) {
      await ctx.editMessageReplyMarkup({
        reply_markup: { inline_keyboard: [] },
      }).catch(() => {})
      if (metaForMessage != null) {
        agentButtonMeta.delete(`${cbChatId}:${cbMessageId}`)
      }
    }
    return
  }

  // Permission request buttons.
  const m = /^perm:(allow|deny|always|asn|asb|back):([a-km-z]{5})$/.exec(data)
  if (!m) { await ctx.answerCallbackQuery().catch(() => {}); return }
  const access = loadAccess()
  const senderId = String(ctx.from.id)
  if (!access.allowFrom.includes(senderId)) { await ctx.answerCallbackQuery({ text: 'Not authorized.' }).catch(() => {}); return }
  const [, behavior, request_id] = m

  // "🔁 Always…" / "← Back" — toggle between the default action row and
  // the scope sub-menu. Neither dispatches a verdict; the scope is only
  // committed when the operator taps a scope button (asn / asb).
  if (behavior === 'always' || behavior === 'back') {
    const details = pendingPermissions.get(request_id)
    if (!details) { await ctx.answerCallbackQuery({ text: 'Details no longer available.' }).catch(() => {}); return }
    let keyboard: InlineKeyboard
    if (behavior === 'back') {
      keyboard = buildPermissionActionRow(request_id, true)
    } else {
      const choices = resolveScopedAllowChoices(details.tool_name, details.input_preview)
      if (choices == null) {
        await ctx.answerCallbackQuery({ text: 'No always-allow rule for this tool.' }).catch(() => {})
        return
      }
      // Scope row: ← Back · [this thing] · [any thing] ⚠️ — the ⚠️
      // rides on the broad option only. Scope stays hidden until now.
      keyboard = new InlineKeyboard().text('← Back', `perm:back:${request_id}`)
      if (choices.specific) keyboard.text(choices.specific.buttonLabel, `perm:asn:${request_id}`)
      keyboard.text(`${choices.broad.buttonLabel} ⚠️`, `perm:asb:${request_id}`)
    }
    await ctx.editMessageReplyMarkup({ reply_markup: keyboard }).catch(() => {})
    await ctx.answerCallbackQuery().catch(() => {})
    return
  }

  if (behavior === 'asn' || behavior === 'asb') {
    // "🔁 Always allow" (#1977) — persist the resolved rule into the
    // agent's tools.allow in the DURABLE host config. The old path
    // shelled `switchroom agent grant` which wrote
    // /state/config/switchroom.yaml — but that path is bind-mounted
    // READ-ONLY into agent containers, so the write silently no-op'd.
    // Durable host-config writes only land via the host-side hostd
    // daemon's `config_propose_edit` flow. We:
    //   1. dispatch the in-flight Allow verdict IMMEDIATELY (turn must
    //      not block on the host round-trip);
    //   2. if hostd is not-configured → fall back to the legacy
    //      `agent grant` + verify path (honest messaging only);
    //   3. otherwise synthesize a unified diff adding the rule to the
    //      agent's tools.allow and send it to hostd, awaiting the
    //      apply+reconcile result.
    const details = pendingPermissions.get(request_id)
    if (!details) { await ctx.answerCallbackQuery({ text: 'Details no longer available.' }).catch(() => {}); return }
    const choices = resolveScopedAllowChoices(details.tool_name, details.input_preview)
    if (choices == null) {
      await ctx.answerCallbackQuery({ text: 'Cannot synthesize an always-allow rule for this tool.' }).catch(() => {})
      return
    }
    // asn → the narrow/specific scope (falls back to broad when the tool
    // has no sub-scope); asb → the broad, whole-category scope.
    const chosen = behavior === 'asn' ? (choices.specific ?? choices.broad) : choices.broad
    const grantPhrase = describeGrant(details.tool_name, details.input_preview, chosen)
    const agentName = process.env.SWITCHROOM_AGENT_NAME
    if (!agentName) {
      await ctx.answerCallbackQuery({ text: 'Always-allow needs SWITCHROOM_AGENT_NAME — gateway is misconfigured.' }).catch(() => {})
      return
    }

    pendingPermissions.delete(request_id)
    permCardStore.remove(request_id)

    // (2) Dispatch the in-flight permission verdict IMMEDIATELY — before
    // any host round-trip — so the turn never blocks on persistence.
    // We carry the chosen `rule` so the bridge caches it for the rest
    // of the session and auto-allows matching tool calls from sub-agents
    // (Task tool) + the parent without re-popping the prompt (#1138).
    // The rule is safe to cache regardless of whether the *durable*
    // write later succeeds — it's the operator's explicit intent.
    dispatchPermissionVerdict({
      type: 'permission',
      requestId: request_id,
      behavior: 'allow',
      rule: chosen.rule,
    })
    // The turn resumes now (independent of the host persistence round-trip
    // below). Un-park 🙏 → working immediately so the operator sees the
    // agent continue while hostd writes the durable rule.
    resumeReactionAfterVerdict()
    postPermissionResumeMessage({
      behavior: 'allow',
      action: naturalAction(details.tool_name, details.input_preview),
    })

    // (3) Ack the tap IMMEDIATELY with an honest interim status. The
    // durable persist below goes through hostd `config_propose_edit`
    // (validate→approve→apply→reconcile), which can take 5-10 minutes on
    // a busy host — the old code awaited only 60s and then reported
    // "did NOT save" even when the edit later landed. Instead: ack now,
    // run the persistence in a background continuation with a 12-min
    // dispatch window, then edit the card with the REAL outcome.
    // HTML-escape baseText — `ctx.callbackQuery.message.text` returns
    // entities-stripped plain UTF-8, so raw `<`/`>`/`&` in the
    // expanded permission card's `description` or `input_preview`
    // (claude-generated tool descriptions routinely carry these)
    // would break the HTML re-parse. PR #1158 review caught the same
    // issue on the operator-event card.
    const sourceMsg = ctx.callbackQuery?.message
    const baseText = sourceMsg && 'text' in sourceMsg && sourceMsg.text
      ? escapeHtmlForTg(sourceMsg.text)
      : ''
    const interimLabel =
      `⏳ **Rule applied for this session** — ${escapeHtmlForTg(agentName)} can ${escapeHtmlForTg(grantPhrase)} ` +
      `without asking for now; saving durably in background…`
    // #1150 audit: route through finalizeCallback so the keyboard
    // strips alongside the status-line edit. The in-flight verdict was
    // ALREADY dispatched above (independently of this host round-trip)
    // so the turn never blocked — finalizeCallback here only edits the
    // card; no synthInbound (would double-fire the verdict).
    await finalizeCallback(ctx, {
      ackText: 'Rule applied for this session; saving durably in background…'.slice(0, 200),
      newText: baseText ? `${baseText}\n\n${interimLabel}` : interimLabel,
    })

    // Background continuation: decide the persistence path.
    // tryHostdDispatch returns "not-configured" when host_control is
    // disabled or the per-agent socket is absent → legacy fallback.
    // The whole body is wrapped in try/catch: a throw inside a void
    // IIFE (scheduleGrantRestart's sync fs writes, richMessage, etc.)
    // would surface as an unhandledRejection — which this gateway
    // routes through shutdown(). Pre-background, those throws were
    // contained by grammY's handler wrapper; keep that containment.
    // Known accepted gap: if the gateway restarts mid-persist, the
    // interim "saving durably in background…" card stays stale.
    void (async () => {
    try {
    let durable = false
    let legacy = false
    let failReason = ''
    let editLockHint = false

    const configEditDisabled = (msg: string): boolean =>
      msg.includes('E_CONFIG_EDIT_DISABLED')

    const unifiedDiff = (() => {
      try {
        const cfgPath = process.env.SWITCHROOM_CONFIG ?? SWITCHROOM_CONFIG ?? findSwitchroomConfigFile()
        const raw = readFileSync(cfgPath, 'utf8')
        return synthesizeAllowRuleDiff({ agentName, rule: chosen.rule, configText: raw })
      } catch (err) {
        process.stderr.write(`telegram gateway: always-allow diff synth failed: ${(err as Error).message}\n`)
        return null
      }
    })()

    const correlationKey = `${agentName}::${chosen.rule}`
    try {
      if (unifiedDiff == null) {
        // Could not locate the agent block / read config → fall back to
        // the legacy grant path; its own verify will produce honest
        // messaging.
        legacy = true
      } else {
        // Pre-register the single-tap correlation so hostd's callback
        // (request_config_approval) auto-approves WITHOUT a second card.
        pendingAlwaysAllowCorrelations.set(correlationKey, { agentName, rule: chosen.rule, unifiedDiff, createdAt: Date.now() })
        const req: HostdRequest = {
          v: 1,
          op: 'config_propose_edit',
          request_id: hostdRequestId('gw-always-allow'),
          args: {
            unified_diff: unifiedDiff,
            reason: `Operator 'always allow': ${agentName} can ${grantPhrase}`,
            target_path: '/state/config/switchroom.yaml',
          },
        }
        // config_propose_edit blocks on validate→approve→apply→reconcile,
        // which can legitimately take 5-10 minutes — allow 12 min. Safe
        // to wait this long because we're in a background continuation:
        // the tap was already acked and the verdict already dispatched.
        const resp = await tryHostdDispatch(agentName, req, 720_000)
        if (resp === 'not-configured') {
          warnLegacySpawnIfHostdDisabled('always-allow')
          legacy = true
        } else if (resp.result === 'completed') {
          durable = true
          process.stderr.write(
            `telegram gateway: always-allow durable via hostd rule="${chosen.rule}" agent=${agentName} (request_id=${request_id})\n`,
          )
        } else {
          failReason = resp.error ?? `hostd ${resp.result}`
          if (configEditDisabled(failReason)) editLockHint = true
          process.stderr.write(
            `telegram gateway: always-allow hostd FAILED: ${failReason} (request_id=${request_id})\n`,
          )
        }
      }

      if (legacy) {
        // Legacy not-configured fallback — keep TODAY's behaviour:
        // shell `agent grant` (writes the host yaml only when the
        // gateway has a writable path) + verify the rule actually
        // landed. Honest messaging: "saved (legacy path)" on verify,
        // else the "did NOT save" warning.
        try {
          switchroomExec(['agent', 'grant', agentName, chosen.rule, '--no-restart'])
          try {
            const cfg = loadSwitchroomConfig()
            const rawAgent = cfg.agents?.[agentName]
            if (rawAgent) {
              const resolved = resolveAgentConfig(cfg.defaults, cfg.profiles, rawAgent)
              const allowList: string[] = (resolved as { tools?: { allow?: string[] } }).tools?.allow ?? []
              if (isRulePersisted(allowList, chosen.rule)) {
                durable = true // legacy path verified — durable on this host shape
                process.stderr.write(
                  `telegram gateway: always-allow added rule="${chosen.rule}" agent=${agentName} via legacy grant (request_id=${request_id})\n`,
                )
              } else {
                failReason = `rule "${chosen.rule}" not found in resolved tools.allow after write — config location may have drifted`
                process.stderr.write(
                  `telegram gateway: always-allow VERIFY FAILED: ${failReason} (request_id=${request_id})\n`,
                )
              }
            } else {
              failReason = `agent "${agentName}" not found in config after write`
              process.stderr.write(
                `telegram gateway: always-allow VERIFY FAILED: ${failReason} (request_id=${request_id})\n`,
              )
            }
          } catch (verifyErr) {
            failReason = `config re-read failed: ${(verifyErr as Error).message}`
            process.stderr.write(
              `telegram gateway: always-allow VERIFY FAILED: ${failReason} (request_id=${request_id})\n`,
            )
          }
        } catch (err) {
          failReason = (err as Error).message
          process.stderr.write(`telegram gateway: always-allow grant failed: ${failReason}\n`)
        }
      }
    } finally {
      // Single-shot correlation — drop it whether or not it was
      // consumed by hostd's callback, so it can never be replayed.
      pendingAlwaysAllowCorrelations.delete(correlationKey)
    }

    const ok = durable
    const legacyNote = legacy && durable
    // Make the durable grant LIVE: config_propose_edit's apply already
    // regenerated the scaffold (settings.json with the new tools.allow), so a
    // marker-safe, turn-deferred self-restart loads it — no more "restart by
    // hand" hint that the operator ignores (leaving the grant inert until the
    // next bounce). Only on the hostd-durable path (scaffold currency assured);
    // legacy path keeps the manual hint. Self-agent only; kill-switch
    // SWITCHROOM_AUTORESTART_ON_GRANT=0.
    const restartScheduled =
      ok && !legacy &&
      scheduleGrantRestart(
        agentName,
        ctx.chat?.id,
        (ctx.callbackQuery?.message as { message_thread_id?: number } | undefined)?.message_thread_id,
        `always-allow: ${grantPhrase}`,
      ) !== "disabled"
    const liveSuffix = restartScheduled ? " — applying now (restarting to take effect)" : ""
    const editLabel = ok
      ? (legacyNote
          ? `✅ **${escapeHtmlForTg(agentName)} can now ${escapeHtmlForTg(grantPhrase)}** without asking (legacy path); restart agent for full effect`
          : restartScheduled
            ? `✅ **${escapeHtmlForTg(agentName)} can now ${escapeHtmlForTg(grantPhrase)}** without asking — applying now (restarting to take effect).`
            : `✅ **${escapeHtmlForTg(agentName)} can now ${escapeHtmlForTg(grantPhrase)}** without asking; restart agent for full effect`)
      : (editLockHint
          ? `⚠️ **Allowed for now — "always" did NOT save.** Config edits are locked; enable \`hostd.config_edit_enabled\`.`
          : `⚠️ **Allowed for now — "always" did NOT save.** It will ask again after restart. Check gateway log.`)
    // Edit the card with the REAL outcome. The keyboard was already
    // stripped by the interim finalizeCallback ack above, and the
    // callback query was already answered — this is a plain edit
    // replacing the "saving durably in background…" interim line.
    await ctx.editMessageText(
      richMessage(baseText ? `${baseText}\n\n${editLabel}` : editLabel),
      {
        reply_markup: { inline_keyboard: [] },
        link_preview_options: { is_disabled: true },
      },
    ).catch((err: unknown) => {
      process.stderr.write(
        `telegram gateway: always-allow outcome card edit failed: ${(err as Error).message} (request_id=${request_id})\n`,
      )
    })
    } catch (err) {
      // Never let the background persist take the gateway down — an
      // unhandledRejection here becomes shutdown(). Log and move on;
      // the in-session rule was already applied at tap time.
      process.stderr.write(
        `telegram gateway: always-allow background persist threw: ${(err as Error).message} (request_id=${request_id})\n`,
      )
    }
    })()
    return
  }

  // Forward permission decision to connected bridges. Capture the pending
  // details BEFORE deleting the entry — the resume message names the resumed
  // work, and "Allow" on a narrow non-destructive scope auto-grants a 30-min
  // window (resolveTimeBox) so the same action stops re-asking. This IS the
  // default behavior of Allow (no separate button); broad / MCP / destructive
  // scopes (resolveTimeBox → null) and the disabled tier (ttl<=0) stay truly
  // once. The verdict is still dispatched WITHOUT a `rule` (below), so the
  // bridge never caches it untimed — the window lives only in scopedGrants.
  // Stale-id tap (#2469 follow-up): the pendingStateReaper auto-DENIES a
  // permission whose TTL expired and DELETES its pending entry — but a late
  // operator tap on the (now keyboard-stripped, but possibly still-cached)
  // card would otherwise dispatch a verdict for an already-resolved/dead
  // request_id, which Claude Code silently ignores. Net: operator THINKS
  // they approved, but the work was auto-denied and never continues. Be
  // honest: tell the operator the request already resolved and do NOT
  // dispatch a verdict for the dead id (no buffering, no resume message).
  // LIVE ids fall through to the normal dispatch path below, preserving the
  // dispatchPermissionVerdict buffering/offline-redelivery contract.
  if (!pendingPermissions.has(request_id)) {
    await ctx.answerCallbackQuery({ text: STALE_TAP_NOTICE }).catch(() => {})
    return
  }
  // Operator tapped a verdict ⇒ they are present; reset no-repeat suppression
  // so a later identical ask is shown fresh rather than silently short-circuited.
  clearPermissionTimeoutSuppression('operator answered a permission card')
  const pd = pendingPermissions.get(request_id)
  const resumeAction = pd ? naturalAction(pd.tool_name, pd.input_preview) : ''
  const scopedTtl = scopedApprovalTtlMs()
  const timeBox = (behavior === 'allow' && scopedTtl > 0 && pd)
    ? resolveTimeBox(pd.tool_name, pd.input_preview, resolveScopedAllowChoices(pd.tool_name, pd.input_preview))
    : null
  const grantAgent = selfAgentName()
  pendingPermissions.delete(request_id)
  permCardStore.remove(request_id)
  if (timeBox && grantAgent) {
    recordScopedGrant(scopedGrants, grantAgent, timeBox.rule, Date.now(), scopedTtl)
    process.stderr.write(
      `telegram gateway: scoped-approval granted via Allow rule="${timeBox.rule}" ` +
      `agent=${grantAgent} ttl_ms=${scopedTtl} (request_id=${request_id})\n`,
    )
  }
  const scopedMins = Math.max(1, Math.round(scopedTtl / 60_000))
  // The card collapses to a plain verdict label. The distinct agent-voiced
  // "got it, continuing: …" message (posted on resume below) now carries
  // the "is it working or did my tap do nothing?" signal the old
  // `▶️ resuming…` card footnote used to — and names the work, which the
  // footnote never did. Keeps the card terse and the resume legible.
  // Honest-card: only claim the window when one was actually recorded
  // (timeBox eligible AND we had an agent name to key it under) — never
  // promise "won't ask again for 30 min" if nothing was stored.
  const windowGranted = timeBox != null && grantAgent !== ''
  const ackText = behavior === 'deny'
    ? '❌ Denied'
    : (windowGranted ? `✅ Allowed (${scopedMins} min)` : '✅ Allowed once')
  const htmlLabel = behavior === 'deny'
    ? '❌ **Denied**'
    : (windowGranted
        ? `✅ **Allowed — won't ask again about ${escapeHtmlForTg(timeBox!.breadth)} for ${scopedMins} min**`
        : '✅ **Allowed once**')
  // HTML-escape the source text — same hazard as the scope-commit and
  // recent-denial paths above. The permission card body
  // (formatPermissionCardBody) appends claude-supplied `description`
  // and `input_preview` strings that frequently contain raw
  // `<`/`>`/`&` (shell commands, JSON nested in JSON, etc). Mixing
  // a plain-text edit with `parseMode: 'HTML'` is the safe direction:
  // escaped baseText round-trips visually as plain text; the appended
  // status line carries our chosen styling cleanly.
  const msg = ctx.callbackQuery?.message
  const baseText = msg && 'text' in msg && msg.text
    ? escapeHtmlForTg(msg.text)
    : ''
  // NO SPLIT (#card-ux): the agent-voiced "got it, continuing: <action>"
  // continuation folds into THIS card edit — below the verdict label — instead
  // of spawning a separate message. formatPermissionResumeMessage returns the
  // same GFM markdown the standalone message used, so the wording is
  // unchanged; it just rides in the card the operator already tapped. The
  // separate message went to EVERY resolvePermissionCardTargets() surface; the
  // in-place edit deliberately touches only the tapped card (a single, legible
  // card, no fan-out). The turn-resume trigger (dispatchPermissionVerdict) is
  // untouched below — only the USER-VISIBLE second message collapses. Honours
  // the SWITCHROOM_RESUME_MSG=0 kill-switch (suppresses the continuation line,
  // as it suppressed the separate message before).
  const resumeLine = process.env.SWITCHROOM_RESUME_MSG === '0'
    ? ''
    : formatPermissionResumeMessage({
        agentName: process.env.SWITCHROOM_AGENT_NAME ?? null,
        behavior: behavior as 'allow' | 'deny',
        action: resumeAction,
      })
  const labelWithResume = resumeLine ? `${htmlLabel}\n\n${resumeLine}` : htmlLabel
  // #1150 audit: P0 fix — was `editMessageText` WITHOUT reply_markup
  // strip, leaving the [Allow][Deny][Always] keyboard live after the
  // decision. Operator could re-tap and flip Deny → Allow after the
  // permission was already broadcast. Routing through finalizeCallback
  // strips the keyboard atomically with the status-line edit.
  await finalizeCallback(ctx, {
    ackText: ackText.slice(0, 200),
    newText: baseText ? `${baseText}\n\n${labelWithResume}` : labelWithResume,
    synthInbound: () => {
      // No `rule` → the bridge does NOT cache this (truly once on the bridge);
      // any 30-min stickiness lives only in scopedGrants (recorded above).
      dispatchPermissionVerdict({
        type: 'permission',
        requestId: request_id,
        behavior: behavior as 'allow' | 'deny',
      })
      // Un-park the status reaction: 🙏 → working, re-arming the stall
      // watchdog that setAwaiting() suspended.
      resumeReactionAfterVerdict()
      // card-folded-resume: the visible "continuing…" line is folded into the
      // card edit above (labelWithResume), so we deliberately do NOT
      // postPermissionResumeMessage here — that would re-introduce the split
      // second message this fix (card-ux fix 3) removes. The turn still resumes
      // via dispatchPermissionVerdict + resumeReactionAfterVerdict above.
    },
  })
})

// ─── Inbound message handlers ─────────────────────────────────────────────
bot.on('message:text', async ctx => {
  await handleInboundCoalesced(ctx, ctx.message.text, undefined)
})

bot.on('message:photo', async ctx => {
  const caption = ctx.message.caption ?? '(photo)'
  await handleInboundCoalesced(ctx, caption, async () => {
    const photos = ctx.message.photo
    const best = photos[photos.length - 1]
    try {
      const file = await ctx.api.getFile(best.file_id)
      if (!file.file_path) return undefined
      // Build download URL — token is embedded in the URL but never exposed
      // in error messages or logs (caught and sanitized below).
      //
      // Bounded fetch: a stalled Telegram CDN connection without a
      // timeout would hang the entire inbound handler, blocking the
      // user's photo from ever being acked or seen by the agent.
      // 15s is generous for normal photos (typical 100ms-2s) and
      // tight enough to surface a real outage.
      const downloadUrl = `https://api.telegram.org/file/bot${TOKEN}/${file.file_path}`
      const res = await fetch(downloadUrl, { signal: AbortSignal.timeout(15_000) })
      if (!res.ok) {
        process.stderr.write(`telegram gateway: photo download failed: HTTP ${res.status}\n`)
        return undefined
      }
      const buf = Buffer.from(await res.arrayBuffer())
      const dlPath = buildAttachmentPath({
        inboxDir: INBOX_DIR,
        telegramFilePath: file.file_path,
        fileUniqueId: best.file_unique_id,
        now: Date.now(),
      })
      mkdirSync(INBOX_DIR, { recursive: true, mode: 0o700 })
      assertInsideInbox(INBOX_DIR, dlPath)
      writeFileSync(dlPath, buf, { mode: 0o600 })
      return dlPath
    } catch (err) {
      // Sanitize error to avoid leaking bot token in logs
      const msg = err instanceof Error ? err.message : 'unknown error'
      process.stderr.write(`telegram gateway: photo download failed: ${msg.replace(TOKEN!, '<REDACTED>')}\n`)
      return undefined
    }
  })
})

bot.on('message:document', async ctx => {
  const doc = ctx.message.document
  const name = safeName(doc.file_name)
  await handleInboundCoalesced(ctx, ctx.message.caption ?? `(document: ${name ?? 'file'})`, undefined, { kind: 'document', file_id: doc.file_id, size: doc.file_size, mime: doc.mime_type, name })
})

bot.on('message:voice', async ctx => {
  const voice = ctx.message.voice
  // #578 spike: when voice_in is enabled in access.json, download
  // the audio and transcribe via Whisper before surfacing to the
  // agent. The transcript becomes the inbound text; the agent reads
  // it like a typed message. Failure paths gracefully fall back to
  // the legacy "(voice message)" envelope so the agent still gets
  // SOMETHING — better than silent drops.
  const access = loadAccess()
  const voiceIn = access.voice_in
  // Engine selection (PR-B2): the persisted host verdict decides HOW we
  // transcribe. `local` → the in-fleet GPU sidecar (no third-party key,
  // vision #3 + #4); anything else → the OpenAI cloud provider. The local
  // path needs no `provider === 'openai'` gate — it has no API key — so we
  // route to the sidecar whenever voice_in is enabled AND the host verdict
  // is `local`. The cloud path keeps its existing openai gate.
  // Source precedence: the compose-injected SWITCHROOM_VOICE_ENGINE env
  // (set per-agent by compose-gen from the host verdict — PR-B3) wins,
  // then the persisted host-capabilities file, then a fail-safe `cloud`.
  // The env is load-bearing in-fleet: the in-container `~/.switchroom`
  // is a read-only constructed view that does NOT carry the host's
  // host-capabilities.json, so without the env the file lookup always
  // misses and every agent silently falls back to `cloud`. Narrow the
  // env value to the VoiceEngine union so a bogus value can't leak
  // through — anything but 'local'/'cloud' is ignored and we fall back.
  const envVoiceEngine = process.env.SWITCHROOM_VOICE_ENGINE
  const voiceEngine: VoiceEngine =
    envVoiceEngine === 'local' || envVoiceEngine === 'cloud'
      ? envVoiceEngine
      : loadHostCapabilities()?.voice.engine ?? 'cloud'
  const localEnabled = voiceIn?.enabled === true && voiceEngine === 'local'
  const cloudEnabled =
    voiceIn?.enabled === true && voiceEngine !== 'local' && voiceIn?.provider === 'openai'
  if (localEnabled || cloudEnabled) {
    const transcript = localEnabled
      ? await maybeTranscribeVoiceLocal(
          voice.file_id,
          voice.mime_type,
          voiceIn?.language,
        )
      : await maybeTranscribeVoice(
          voice.file_id,
          voice.mime_type,
          voiceIn?.language,
          voiceIn?.api_key,
        )
    if (transcript != null) {
      const text = ctx.message.caption
        ? `${ctx.message.caption}\n\n[voice transcript] ${transcript}`
        : `[voice transcript] ${transcript}`
      await handleInboundCoalesced(ctx, text, undefined, {
        kind: 'voice',
        file_id: voice.file_id,
        size: voice.file_size,
        mime: voice.mime_type,
      })
      return
    }
    // Fall through to the legacy path on transcription failure.
  }
  await handleInboundCoalesced(ctx, ctx.message.caption ?? '(voice message)', undefined, { kind: 'voice', file_id: voice.file_id, size: voice.file_size, mime: voice.mime_type })
})

/**
 * Download a voice attachment from Telegram and transcribe it via
 * the configured Whisper provider. Returns the transcript text on
 * success, or null on any failure (caller falls back). All errors
 * are logged to stderr but never thrown — voice-in is a UX
 * enhancement, not a critical path.
 */
/**
 * Filename hint for the multipart body. Telegram voice is OGG/Opus; agents
 * may also attach mp3/m4a/wav which arrive as message:audio. Match the mime
 * so the decoder (Whisper / faster-whisper) gets a usable extension.
 */
function voiceFilenameExt(mimeType: string | undefined): string {
  return mimeType?.includes('mp3') ? 'mp3'
    : mimeType?.includes('m4a') ? 'm4a'
    : mimeType?.includes('wav') ? 'wav'
    : 'ogg'
}

/**
 * Download a Telegram voice attachment into memory. Shared by the cloud
 * (Whisper) and local (sidecar) transcription paths. Returns the bytes on
 * success, or null on any failure (caller falls back). Never throws.
 */
async function downloadVoiceBytes(fileId: string): Promise<Uint8Array | null> {
  try {
    const file = await bot.api.getFile(fileId)
    if (!file.file_path) {
      process.stderr.write(`telegram gateway: voice-in: getFile returned no file_path\n`)
      return null
    }
    const url = `https://api.telegram.org/file/bot${TOKEN}/${file.file_path}`
    const res = await fetch(url, { signal: AbortSignal.timeout(30_000) })
    if (!res.ok) {
      process.stderr.write(`telegram gateway: voice-in: telegram download HTTP ${res.status}\n`)
      return null
    }
    return new Uint8Array(await res.arrayBuffer())
  } catch (err) {
    // Sanitize: never let the bot token leak into log lines via the
    // download URL — strip anything that looks like a token.
    const msg = (err as Error).message.replace(/bot[\w:-]+/g, 'bot[redacted]')
    process.stderr.write(`telegram gateway: voice-in: download failed: ${msg}\n`)
    return null
  }
}

/**
 * Transcribe a Telegram voice note via the LOCAL GPU STT sidecar (PR-B2).
 * Used when the host voice verdict is `local`. Resolves the shared-secret
 * token from the vault (voice/sidecar-token), downloads the audio, and
 * POSTs it to the sidecar at loopback (the gateway is network_mode: host).
 * Returns the transcript on success, null on any failure (caller falls
 * back to the legacy "(voice message)" envelope). Never throws.
 */
async function maybeTranscribeVoiceLocal(
  fileId: string,
  mimeType: string | undefined,
  language: string | undefined,
): Promise<string | null> {
  const token = await materializeSidecarToken()
  if (!token) {
    // materializeSidecarToken already logged the specific reason.
    return null
  }

  const audioBytes = await downloadVoiceBytes(fileId)
  if (!audioBytes) return null

  const result = await transcribeViaSidecar({
    token,
    audio: audioBytes,
    filename: `voice.${voiceFilenameExt(mimeType)}`,
    language,
  })

  if (!result.ok) {
    process.stderr.write(
      `telegram gateway: voice-in: local sidecar transcription failed reason=${result.reason}` +
      (result.detail ? ` detail=${JSON.stringify(result.detail).slice(0, 100)}` : '') +
      '\n',
    )
    return null
  }

  process.stderr.write(
    `telegram gateway: voice-in: local sidecar transcribed ${audioBytes.length} bytes in ${result.durationMs}ms ` +
    `lang=${result.language ?? '?'} audio_s=${result.audioSeconds ?? '?'} chars=${result.text.length}\n`,
  )
  return result.text
}

async function maybeTranscribeVoice(
  fileId: string,
  mimeType: string | undefined,
  language: string | undefined,
  apiKeyRef: string | undefined,
): Promise<string | null> {
  // Resolve the STT key through the vault broker at use-time (PR-A:
  // voice STT vault-unify). The configured `voice_in.api_key` is a
  // `vault:<key>` reference (default `vault:openai/api-key`); the
  // resolved value is held in memory only — never written to disk or
  // surfaced into the agent prompt. On any failure we return null and
  // the caller falls back to the legacy "(voice message)" envelope.
  const apiKey = await materializeVoiceKey({ apiKeyRef })
  if (!apiKey) {
    // materializeVoiceKey already logged the specific reason.
    return null
  }

  const audioBytes = await downloadVoiceBytes(fileId)
  if (!audioBytes) return null

  const result = await transcribeViaWhisper({
    apiKey,
    audio: audioBytes,
    filename: `voice.${voiceFilenameExt(mimeType)}`,
    language,
  })

  if (!result.ok) {
    process.stderr.write(
      `telegram gateway: voice-in: transcription failed reason=${result.reason}` +
      (result.detail ? ` detail=${JSON.stringify(result.detail).slice(0, 100)}` : '') +
      '\n',
    )
    return null
  }

  process.stderr.write(
    `telegram gateway: voice-in: transcribed ${audioBytes.length} bytes in ${result.durationMs}ms ` +
    `lang=${result.language ?? '?'} audio_s=${result.audioSeconds ?? '?'} chars=${result.text.length}\n`,
  )
  return result.text
}

