bot.on('message:passport_data', async ctx => {
  // Telegram Passport is a regulated identity-document flow. Forwarding
  // the encrypted credentials to an LLM-driven agent would be reckless;
  // we explicitly refuse to handle it and tell the user so they can
  // route via the proper channel. Logged at SECURITY level so operators
  // can see if a passport_data inbound ever lands here (an outlier worth
  // investigating).
  await handleRefusal(
    ctx,
    'passport_data',
    "Sorry, I don't handle Telegram Passport data. Please share identity documents through a supported channel — your agent does not process encrypted Passport payloads.",
  )
})

// ─── Checklist service message handlers ──────────────────────────────────
// Telegram emits `checklist_tasks_done` and `checklist_tasks_added` service
// messages when users tick or add tasks in a native checklist. These arrive
// as part of the `message` update type, so no extra `allowed_updates` config
// is required — bots already receive them.
//
// We route them to the agent as a new channel event with
// kind="checklist_task_changed" so the agent can react to user actions on
// a checklist it sent.

type ChecklistTaskUpdate = {
  message_checklist?: {
    title?: string
    tasks?: Array<{ id?: number; text?: string; is_completed?: boolean }>
  }
  checklist_tasks_done?: Array<{ id?: number; user?: { id?: number; username?: string }; done?: boolean }>
  checklist_tasks_added?: Array<{ id?: number; text?: string; user?: { id?: number; username?: string } }>
}

function handleChecklistUpdate(
  ctx: Context,
  kind: 'checklist_tasks_done' | 'checklist_tasks_added',
): void {
  try {
    const msg = ctx.message as (typeof ctx.message & ChecklistTaskUpdate) | undefined
    if (!msg) return

    const chat = ctx.chat
    if (!chat) return

    const chat_id = String(chat.id)
    const access = loadAccess()

    // Only notify if this chat is allowlisted — same guard as inbound user messages.
    // Closes #472 finding #13. Pre-fix the `&& access.allowFrom.length > 0`
    // tail made this fail-OPEN when the allowlist was empty: every chat's
    // checklist tasks would forward to the agent. Sibling guards (the
    // inbound-message gate at line ~588 and the operator-event broadcast
    // at line ~1221) are both fail-closed for empty allowlists. The
    // empty-allowlist case is the most likely state for a misconfiguration
    // (e.g. /unpair just ran), so fail-OPEN is the worst default.
    if (!access.allowFrom.includes(chat_id)) return

    const message_id = String(msg.message_id)
    const ts = msg.date ?? Math.floor(Date.now() / 1000)

    // Extract task updates depending on service message type
    const tasksDone = msg.checklist_tasks_done ?? []
    const tasksAdded = msg.checklist_tasks_added ?? []
    const allTasks = kind === 'checklist_tasks_done' ? tasksDone : tasksAdded

    // Build per-task channel events and broadcast each to connected bridges.
    for (const task of allTasks) {
      const taskId = task.id != null ? String(task.id) : '?'
      const user = (task.user as { username?: string; id?: number } | undefined)
      const userName = user?.username ?? (user?.id != null ? String(user.id) : 'unknown')
      const state = kind === 'checklist_tasks_done'
        ? ((task as { done?: boolean }).done === false ? 'undone' : 'done')
        : 'added'

      const inboundMsg: InboundMessage = {
        type: 'inbound',
        chatId: chat_id,
        messageId: Number(message_id),
        user: userName,
        userId: user?.id ?? 0,
        ts,
        text: `(checklist task ${state}: id=${taskId})`,
        meta: {
          chat_id,
          message_id,
          kind: 'checklist_task_changed',
          task_id: taskId,
          state,
          user: userName,
          user_id: user?.id != null ? String(user.id) : '0',
          ts: new Date(ts * 1000).toISOString(),
        },
      }
      // allow-broadcast: informational checklist task notification, not turn-driving
      ipcServer.broadcast(inboundMsg)
      process.stderr.write(
        `telegram gateway: checklist ${kind}: chat_id=${chat_id} message_id=${message_id} task_id=${taskId} state=${state} user=${userName}\n`,
      )
    }
  } catch (err) {
    process.stderr.write(`telegram gateway: checklist handler error (${kind}): ${err}\n`)
  }
}

bot.on('message:checklist_tasks_done' as Parameters<typeof bot.on>[0], (ctx) => {
  handleChecklistUpdate(ctx as unknown as Context, 'checklist_tasks_done')
})

bot.on('message:checklist_tasks_added' as Parameters<typeof bot.on>[0], (ctx) => {
  handleChecklistUpdate(ctx as unknown as Context, 'checklist_tasks_added')
})

// Suppress the "pinned a message" service message Telegram inserts when OUR
// silent status-pin fires. The pin call passes `disable_notification: true`,
// which kills the PUSH notification but NOT the in-chat service message — so
// delete that service message as it lands, but ONLY for pins we own (tracked
// in `statusPinState`). Manual/operator pins are never silent and are never
// touched. Only silent status pins reach here as an OUR-pin match, so the
// ownership check is the guard.
//
// Race tolerance: the service update can arrive before `reconcileStatusPin`
// has stored the new PinState (the pin API call resolves, Telegram emits the
// service message, and only then does the reconcile write the Map). A single
// short retry covers that window; if it's still not one of ours, we leave the
// service message alone.
bot.on('message:pinned_message', async ctx => {
  const pinnedId = ctx.msg.pinned_message?.message_id
  if (pinnedId == null) return
  const chatId = String(ctx.chat.id)
  const serviceMsgId = ctx.msg.message_id

  // Chat-scoped ownership (see pinnedMessageIsOurs): the match requires BOTH
  // the messageId AND that the tracked entry lives in THIS chat, so a pin id
  // colliding across chats can't delete a foreign (e.g. operator-manual) pin
  // notice. statusPinChatIds is the companion pinKey→chatId map written on
  // every desired-pinned reconcile.
  const trackedPins = (): TrackedStatusPin[] => {
    const out: TrackedStatusPin[] = []
    for (const [pinKey, state] of statusPinState) {
      const c = statusPinChatIds.get(pinKey)
      if (c != null) out.push({ chatId: c, messageId: state.messageId })
    }
    return out
  }
  const isOurs = () => pinnedMessageIsOurs(trackedPins(), chatId, pinnedId)

  if (!isOurs()) {
    // Tolerate the reconcile-store race: wait briefly, then re-check once.
    await new Promise(resolve => setTimeout(resolve, 250))
    if (!isOurs()) return
  }

  try {
    await robustApiCall(
      () => lockedBot.api.deleteMessage(chatId, serviceMsgId),
      { chat_id: chatId, verb: 'status-pin.delete-service-message' },
    )
  } catch (err) {
    // Best-effort: a failure to delete the service message is cosmetic only —
    // the "pinned a message" line just stays. The most likely cause in a
    // supergroup/forum is the bot lacking can_delete_messages admin right, so
    // surface a concise one-liner (robustApiCall rethrows this case without
    // logging a reason) rather than swallowing silently — an operator sees WHY.
    const msg = err instanceof Error ? err.message : String(err)
    process.stderr.write(
      `telegram gateway: status-pin: could not delete pin service message ` +
        `(chat=${chatId} msg=${serviceMsgId}) — likely missing can_delete_messages ` +
        `admin right in this chat: ${msg}\n`,
    )
  }
})

// ─── Reaction-trigger runtime state (#1074) ──────────────────────────────
//
// Bot-message reactions in the configured allowlist trigger a synthetic
// inbound turn (`<channel source="reaction">`) — mirrors the cron-fold-in
// dispatch path. Three pieces of mutable state, all module-local:
//
//   - `reactionsCfg` — cascade-resolved config slice with built-in
//     defaults; lazy-initialized on first reaction event.
//   - `reactionHourCap` — in-memory rolling-1-hour counter per chat.
//   - `reactionDebounce` — per-chat debounce buffer that batches rapid
//     reactions into a single delivered synthetic.
//
// The persistence path (`recordReaction`) is independent — reactions
// are persisted regardless of trigger outcome. This is the v1 contract
// pinned by the existing UAT (`reactions-dm.test.ts`) and by tests
// that rely on `get_recent_messages` surfacing user_reaction.
let reactionsCfg: ReactionsResolvedConfig | null = null
let reactionHourCap: HourCap | null = null
let reactionDebounce: DebounceBuffer | null = null
// Bot's own Telegram user_id; populated at startup from getMe(). Kept
// for parity with botUsername; not currently used for authorship
// detection on reactions (history.role is the primary signal).
let botUserId = 0

function getReactionsConfig(): ReactionsResolvedConfig {
  if (reactionsCfg) return reactionsCfg
  let raw: unknown = undefined
  try {
    const cfg = loadSwitchroomConfig()
    const agentName = process.env.SWITCHROOM_AGENT_NAME
    if (agentName) {
      const rawAgent = cfg.agents?.[agentName]
      if (rawAgent) {
        const resolved = resolveAgentConfig(cfg.defaults, cfg.profiles, rawAgent)
        raw = (resolved as { reactions?: unknown }).reactions
      }
    }
  } catch (err) {
    process.stderr.write(
      `telegram gateway: reactions: config load failed, falling back to defaults: ${(err as Error).message}\n`,
    )
  }
  reactionsCfg = resolveReactionsConfig(
    raw as Parameters<typeof resolveReactionsConfig>[0] ?? null,
  )
  return reactionsCfg
}

function getReactionHourCap(): HourCap {
  if (!reactionHourCap) {
    reactionHourCap = new HourCap(getReactionsConfig().perHourCap)
  }
  return reactionHourCap
}

function getReactionDebounce(): DebounceBuffer {
  if (!reactionDebounce) {
    reactionDebounce = new DebounceBuffer(
      getReactionsConfig().debounceMs,
      flushReactionBatch,
    )
  }
  return reactionDebounce
}

// ─── reaction_dispatch (#2291) ─────────────────────────────────────────────
// Event-driven dispatch of ANY qualifying message_reaction as an inbound
// `<channel event="reaction">` turn. Default OFF; independent of the
// bot-authored `reactions` feedback path above.
let reactionDispatchCfg: ReactionDispatchResolvedConfig | null = null

function getReactionDispatchConfig(): ReactionDispatchResolvedConfig {
  if (reactionDispatchCfg) return reactionDispatchCfg
  let raw: unknown = undefined
  try {
    const cfg = loadSwitchroomConfig()
    const agentName = process.env.SWITCHROOM_AGENT_NAME
    if (agentName) {
      const rawAgent = cfg.agents?.[agentName]
      if (rawAgent) {
        const resolved = resolveAgentConfig(cfg.defaults, cfg.profiles, rawAgent)
        raw = (resolved as { reaction_dispatch?: unknown }).reaction_dispatch
      }
    }
  } catch (err) {
    process.stderr.write(
      `telegram gateway: reaction_dispatch: config load failed, defaulting OFF: ${(err as Error).message}\n`,
    )
  }
  reactionDispatchCfg = resolveReactionDispatchConfig(
    raw as Parameters<typeof resolveReactionDispatchConfig>[0] ?? null,
  )
  return reactionDispatchCfg
}

/**
 * Event-driven reaction → inbound turn (#2291). Called from the
 * message_reaction handler for add/change events. Filters by the
 * `reaction_dispatch` emoji allowlist (default empty ⇒ no-op), looks up
 * the reacted message's text from the SQLite history buffer (graceful on
 * miss), and injects an inbound shaped like a button-callback event via
 * the same ipcServer.sendToAgent path cron uses. Removals never reach
 * here (the caller filters them).
 */
function maybeDispatchReaction(args: {
  chatId: string
  messageId: number
  emoji: string | null
  action: 'add' | 'change'
  user: string
  userId: number
  threadId?: number
}): void {
  const cfg = getReactionDispatchConfig()
  const decision = evaluateReactionDispatch(cfg, { emoji: args.emoji, action: args.action })
  if (!decision.ok) {
    if (decision.reason === 'emoji_not_in_allowlist' && cfg.enabled) {
      process.stderr.write(
        `telegram gateway: reaction_dispatch.reject reason=allowlist_miss emoji=${args.emoji} chat=${args.chatId}\n`,
      )
    }
    return
  }

  const agentName = process.env.SWITCHROOM_AGENT_NAME
  if (!agentName) {
    process.stderr.write(
      `telegram gateway: reaction_dispatch: skipped — SWITCHROOM_AGENT_NAME unset\n`,
    )
    return
  }

  // History lookup is best-effort; a miss yields an empty body. The
  // envelope still carries emoji / message_id / chat_id / user.
  let reactedText = ''
  if (HISTORY_ENABLED) {
    try {
      const row = lookupMessageRoleAndText(args.chatId, args.messageId)
      reactedText = row?.text ?? ''
    } catch (err) {
      process.stderr.write(
        `telegram gateway: reaction_dispatch: history lookup failed: ${err}\n`,
      )
    }
  }

  const { text, meta } = buildReactionDispatchInbound({
    emoji: args.emoji!,
    chatId: args.chatId,
    messageId: args.messageId,
    user: args.user,
    userId: args.userId,
    reactedText,
    ...(typeof args.threadId === 'number' ? { threadId: args.threadId } : {}),
  })

  const ts = Date.now()
  const inbound: InboundMessage = {
    type: 'inbound',
    chatId: args.chatId,
    ...(typeof args.threadId === 'number' ? { threadId: args.threadId } : {}),
    messageId: ts,
    user: args.user,
    userId: args.userId,
    ts,
    text,
    meta,
  }
  const delivered = ipcServer.sendToAgent(agentName, inbound)
  if (delivered) markClaudeBusyForInbound(inbound)
  process.stderr.write(
    `telegram gateway: reaction_dispatch agent=${agentName} chat=${args.chatId} ` +
    `emoji=${args.emoji} message_id=${args.messageId} delivered=${delivered}\n`,
  )
  if (!delivered) {
    pendingInboundBuffer.push(agentName, inbound)
  }
}

/**
 * Dispatch a debounce-flushed batch as a synthetic InboundMessage via
 * the same `ipcServer.sendToAgent` path the cron-fold-in uses.
 * Discriminated by `meta.source="reaction"`. Carries the bot-side
 * message preview (capped at PREVIEW_MAX_CHARS in
 * `reaction-trigger.ts`) — never the bot token, never vault material.
 */
function flushReactionBatch(batch: ReactionBatch): void {
  const agentName = process.env.SWITCHROOM_AGENT_NAME
  if (!agentName) {
    process.stderr.write(
      `telegram gateway: reactions: dispatch skipped — SWITCHROOM_AGENT_NAME unset\n`,
    )
    return
  }
  // Use the latest reaction's metadata for the wire envelope; the
  // batched listing lives inside `text` + `meta.count`.
  const head = batch.reactions[batch.reactions.length - 1]!
  const text = buildReactionInboundText(batch)
  const meta = buildReactionInboundMeta(batch)
  const ts = Date.now()
  const inbound: InboundMessage = {
    type: 'inbound',
    chatId: String(batch.chatId),
    ...(head.threadId !== undefined ? { threadId: head.threadId } : {}),
    // Synthetic id — same convention cron uses. The bridge only uses
    // messageId for telegram_reply context; reaction-synthesized turns
    // are not quote-replies, so any monotonic value works.
    messageId: ts,
    user: head.user,
    userId: head.userId,
    ts,
    text,
    meta,
  }
  const delivered = ipcServer.sendToAgent(agentName, inbound)
  if (delivered) markClaudeBusyForInbound(inbound)
  process.stderr.write(
    `telegram gateway: reactions.dispatch agent=${agentName} chat=${batch.chatId} ` +
    `count=${batch.reactions.length} batched=${batch.batched} delivered=${delivered}\n`,
  )
  // #1150: buffer-on-failure for reaction-triggered wake-ups too.
  if (!delivered) {
    pendingInboundBuffer.push(agentName, inbound)
  }
}

// ─── Inbound message_reaction handler ────────────────────────────────────
// Telegram delivers MessageReactionUpdated events when a user adds, changes,
// or removes an emoji reaction from a bot message. We persist the current
// reaction to the SQLite history row so get_recent_messages can surface it,
// AND (since #1074) optionally forward qualifying reactions to the agent
// as synthetic inbound turns.
//
// Only emoji reactions are handled for v1 — custom emoji are silently skipped.
// Requires "message_reaction" in allowed_updates (see run() call below).
bot.on('message_reaction' as Parameters<typeof bot.on>[0], (ctx) => {
  // Capture outer-scope handle so the async helper has stable shape.
  void handleMessageReaction(ctx as unknown as Context)
})

async function handleMessageReaction(ctx: Context): Promise<void> {
  try {
    // The payload is typed loosely via grammy's Context; cast to the
    // Bot API shape we need (MessageReactionUpdated).
    const update = (ctx as unknown as {
      update: {
        message_reaction?: {
          chat: { id: number }
          message_id: number
          message_thread_id?: number
          user?: { id: number; first_name?: string; username?: string }
          old_reaction: Array<{ type: string; emoji?: string }>
          new_reaction: Array<{ type: string; emoji?: string }>
        }
      }
    }).update.message_reaction
    if (!update) return

    const chat_id = String(update.chat.id)
    const message_id = update.message_id
    const oldReaction = update.old_reaction ?? []
    const newReaction = update.new_reaction ?? []

    // Both empty — defensive no-op.
    if (oldReaction.length === 0 && newReaction.length === 0) return

    // Determine action and emoji for logging / storage.
    let action: 'add' | 'remove' | 'change'
    let emoji: string | null

    if (oldReaction.length === 0 && newReaction.length > 0) {
      action = 'add'
      const first = newReaction.find(r => r.type === 'emoji')
      if (!first) return // custom emoji only — skip
      emoji = first.emoji ?? null
    } else if (oldReaction.length > 0 && newReaction.length === 0) {
      action = 'remove'
      emoji = null
    } else {
      action = 'change'
      const first = newReaction.find(r => r.type === 'emoji')
      if (!first) return // custom emoji only — skip
      emoji = first.emoji ?? null
    }

    if (HISTORY_ENABLED) {
      try {
        recordReaction({ chat_id, message_id, emoji })
      } catch (err) {
        process.stderr.write(`telegram gateway: history recordReaction failed: ${err}\n`)
      }
    }

    process.stderr.write(
      `telegram gateway: reaction: chatId=${chat_id} messageId=${message_id} emoji=${emoji ?? '(none)'} action=${action}\n`,
    )

    // ─── Trigger predicate (#1074) ───────────────────────────────────────
    //
    // Only `add` / `change` carry a NEW emoji; `remove` is log-only.
    // From here on we ignore failures rather than reject (the persist
    // path above is the v1 contract; trigger is best-effort).
    if (action === 'remove' || emoji === null) return
    const reacter = update.user
    if (!reacter) return // anonymous group-channel reactions — not user-attributable

    const reacterName = reacter.first_name ?? reacter.username ?? String(reacter.id)

    // ─── reaction_dispatch (#2291) ───────────────────────────────────────
    // Event-driven dispatch of ANY qualifying reaction as a button-style
    // inbound turn. Independent of (and runs before) the bot-authored
    // `reactions` feedback path below; both may fire for one reaction.
    maybeDispatchReaction({
      chatId: chat_id,
      messageId: message_id,
      emoji,
      action,
      user: reacterName,
      userId: reacter.id,
      ...(typeof update.message_thread_id === 'number'
        ? { threadId: update.message_thread_id }
        : {}),
    })

    if (!HISTORY_ENABLED) return // need history to identify bot-authored target

    const cfg = getReactionsConfig()
    if (!cfg.enabled) return

    // Resolve target authorship + preview text from local history.
    // If the row is missing (reacted-to message predates retention,
    // history disabled mid-run, or was reaped), we cannot tell and
    // therefore must NOT trigger (fail-closed on authorship).
    const row = lookupMessageRoleAndText(chat_id, message_id)
    const botAuthored = row?.role === 'assistant'
    const preview = truncatePreview(row?.text ?? '')

    const decision = evaluateTriggerCandidate(cfg, {
      chatId: update.chat.id,
      messageId: message_id,
      emoji,
      action,
      botAuthored,
    })
    if (!decision.ok) {
      // Only log the bot-authored allowlist-miss case; other rejections
      // (disabled / not-bot-authored / no-emoji) are not interesting
      // events and would spam stderr in groups where the bot has
      // never spoken.
      if (decision.reason === 'emoji_not_in_allowlist' && botAuthored) {
        process.stderr.write(
          `telegram gateway: reactions.reject reason=allowlist_miss emoji=${emoji} chat=${chat_id}\n`,
        )
      }
      return
    }

    // ─── Group admin check (fail-closed on lookup failure) ──────────────
    if (cfg.groupAdminOnly && isGroupChat(update.chat.id)) {
      let isAdmin = false
      try {
        const member = await robustApiCall(
          () => bot.api.getChatMember(update.chat.id, reacter.id),
          { chat_id, verb: 'getChatMember' },
        )
        const status = (member as { status?: string } | undefined)?.status
        isAdmin = status === 'creator' || status === 'administrator'
      } catch (err) {
        process.stderr.write(
          `telegram gateway: reactions.admin_lookup_failed chat=${chat_id} ` +
          `user=${reacter.id} err=${(err as Error).message}\n`,
        )
        isAdmin = false
      }
      if (!isAdmin) {
        process.stderr.write(
          `telegram gateway: reactions.reject reason=group_non_admin chat=${chat_id} user=${reacter.id}\n`,
        )
        return
      }
    }

    // ─── Hour cap ───────────────────────────────────────────────────────
    if (!getReactionHourCap().tryConsume(chat_id)) {
      process.stderr.write(
        `telegram gateway: reactions.reject reason=hour_cap_exhausted chat=${chat_id} cap=${cfg.perHourCap}\n`,
      )
      return
    }

    // ─── Enqueue into the per-chat debounce buffer ──────────────────────
    const pending: PendingReaction = {
      targetMessageId: message_id,
      emoji,
      action,
      ts: Date.now(),
      preview,
      userId: reacter.id,
      user: reacterName,
      ...(typeof update.message_thread_id === 'number'
        ? { threadId: update.message_thread_id }
        : {}),
    }
    getReactionDebounce().enqueue(update.chat.id, pending)
  } catch (err) {
    process.stderr.write(`telegram gateway: message_reaction handler error: ${err}\n`)
  }
}

// ─── Error handler ────────────────────────────────────────────────────────
bot.catch(err => {
  process.stderr.write(`telegram gateway: handler error (polling continues): ${err.error}\n`)
})

// ─── Shutdown ─────────────────────────────────────────────────────────────
//
// 35-second drain budget. The 2026-04-23 incident showed that a 3-second
// hard exit was NOT enough — the kernel hadn't FIN'd the long-poll TCP
// socket before the new gateway process started, so Telegram returned
// 409 Conflict to both pollers for 13+ retries (10–12s backoffs each).
// systemd's TimeoutStopSec is set to 45s in generateGatewayUnit so we
// have headroom.
const SHUTDOWN_DRAIN_BUDGET_MS = 35_000
// #689: time budget for the SIGTERM-time progress-card flush. Sits inside
// the broader drain budget — if Telegram's API can't ack edits + unpins
// within this window we log and exit anyway rather than block shutdown.
const SHUTDOWN_PROGRESS_FLUSH_BUDGET_MS = 1_500

/** Best-effort in-flight counter for the drain loop. Sums the maps that
 * track outstanding side-effects: permission prompts the user hasn't
 * answered, vault operations mid-passphrase-entry, coalesce timers
 * still buffering an outbound, and reauth flows. The IPC server is
 * stopped explicitly via close() so its inflight isn't counted here. */
function countInFlight(): number {
  return (
    pendingPermissions.size +
    pendingVaultOps.size +
    inboundCoalescer.size() +
    pendingReauthFlows.size
  )
}

let shuttingDown = false
async function shutdown(signal: string): Promise<void> {
  if (shuttingDown) return
  shuttingDown = true
  const agentName = process.env.SWITCHROOM_AGENT_NAME ?? '-'
  process.stderr.write('telegram gateway: shutting down\n')

  // Write the clean-shutdown sentinel BEFORE any drain work begins so
  // even if the drain hangs and the +5s force-exit kills us, the marker
  // is already on disk for the next boot to find. This is what tells
  // the next gateway "this restart was planned (systemd/CLI/Coolify),
  // don't post the 'recovered from unexpected restart' banner". Distinct
  // from restart-pending.json, which is the user-initiated /restart
  // marker (chat_id + ack_message_id, posts a quote-reply ack).
  //
  // ONLY write the marker for genuine OS-signal shutdowns. uncaughtException
  // and unhandledRejection ALSO route through shutdown() to release the
  // startup mutex (PR #53 nit fix), but those are real crashes — writing
  // the marker on a crash would suppress its own recovery banner at the
  // next boot, defeating the entire feature.
  //
  // Preserve any reason an initiator stamped microseconds before SIGTERM.
  // CLI/watchdog/user-slash paths call writeRestartReasonMarker(…reason)
  // right before issuing `systemctl restart`; without this readback the
  // shutdown handler would clobber their reason with a signal-only
  // marker, and the next greeting card would render no Restarted row.
  // Falls back to `"systemctl: external restart"` when no initiator
  // stamped a reason (bare `systemctl restart switchroom-<name>-gateway`
  // from an admin terminal) so the greeting always surfaces WHY we
  // bounced. See resolveShutdownMarker() for the full decision table.
  const isOsSignal = signal === 'SIGTERM' || signal === 'SIGINT'
  if (isOsSignal) {
    try {
      const prior = readCleanShutdownMarker(GATEWAY_CLEAN_SHUTDOWN_MARKER_PATH)
      const next = resolveShutdownMarker(prior, signal, Date.now())
      writeCleanShutdownMarker(GATEWAY_CLEAN_SHUTDOWN_MARKER_PATH, next)
      process.stderr.write(`telegram gateway: shutdown.clean_marker_written signal=${signal} reason=${JSON.stringify(next.reason ?? '')} preserved=${prior?.reason === next.reason && prior != null} path=${GATEWAY_CLEAN_SHUTDOWN_MARKER_PATH}\n`)
    } catch (err) {
      process.stderr.write(`telegram gateway: shutdown.clean_marker_write_failed err=${(err as Error).message}\n`)
    }
  } else {
    process.stderr.write(`telegram gateway: shutdown.clean_marker_skipped signal=${signal} (crash path — banner will fire on next boot)\n`)
  }

  // Stage 3c: stamp any in-flight turn as endedVia='sigterm' (or 'restart'
  // for the schedule_restart-initiated case where pendingRestarts is set).
  // Best-effort — SIGKILL / OOM skip this path entirely and the next-boot
  // reaper catches them as endedVia='restart'.
  // #1067: snapshot at entry. The shutdown handler is async; reading
  // currentTurn fresh after each await would tangle with a late event.
  const shutdownTurn = currentTurn
  if (turnsDb != null && shutdownTurn?.registryKey != null) {
    const wasScheduledRestart = pendingRestarts.size > 0
    const endedVia = wasScheduledRestart ? 'restart' : 'sigterm'
    try {
      recordTurnEnd(turnsDb, {
        turnKey: shutdownTurn.registryKey,
        endedVia,
        lastAssistantMsgId: shutdownTurn.lastAssistantMsgId,
        lastAssistantDone: shutdownTurn.lastAssistantDone,
        // Phase 1 of #332: record how many tools fired before the kill.
        // No assistant_reply_preview here — the reply was never committed.
        toolCallCount: shutdownTurn.toolCallCount,
      })
      process.stderr.write(`telegram gateway: shutdown.turn_stamped turnKey=${shutdownTurn.registryKey} endedVia=${endedVia}\n`)
    } catch (err) {
      process.stderr.write(`telegram gateway: shutdown.turn_stamp_failed turnKey=${shutdownTurn.registryKey} err=${(err as Error).message}\n`)
    }
    shutdownTurn.registryKey = null
  }

  // #689: flush every pinned progress card with a "Restart interrupted"
  // banner before drain begins. Bounded by SHUTDOWN_PROGRESS_FLUSH_BUDGET_MS
  // so a wedged Telegram API can't block shutdown. Reads the same reason
  // we just stamped into clean-shutdown.json so the banner mirrors the
  // marker.
  // #1122 PR3/PR4: flushProgressCardsForShutdown is permanently null
  // after the progress card was deleted. Dead block removed.

  // Stop the long-poll health check before draining so it doesn't trigger
  // a stall-recovery restart while we're already in shutdown.
  pollHealthCheck?.stop()

  // Clean up all timers and pending state.
  // Snapshot timer handles before clearing so a late-firing timer can't
  // invalidate the iterator by deleting its own entry during cleanup.
  subagentWatcher?.stop()
  subagentWatcher = null

  // Worker-activity feed runs an internal heartbeat interval; stop it so no
  // re-render fires during drain (mirrors subagentWatcher above).
  workerActivityFeed?.stop()
  workerActivityFeed = null

  // Issues watcher polls issues.jsonl on a setInterval (default 2s) and
  // edits the issues card on every tick. Without an explicit stop() the
  // poll keeps firing for the lifetime of the process and accumulates
  // editMessageText calls during shutdown drain — log noise plus a
  // genuine resource leak if the gateway runs long after the bridge
  // disconnected. Mirrors the subagentWatcher pattern above.
  activeIssuesWatcher?.stop()
  activeIssuesWatcher = null

  for (const iv of [...typingIntervals.values()]) clearInterval(iv)
  typingIntervals.clear()
  turnTypingLoop.stopAll()
  for (const t of [...earlyLivenessOpenTimers.values()]) clearTimeout(t)
  earlyLivenessOpenTimers.clear()
  for (const t of [...typingRetryTimers.values()]) clearTimeout(t)
  typingRetryTimers.clear()

  // NOTE on coalesce timers: in the legacy implementation we clearTimeout()'d
  // each pending timer here but kept the buffer entries so the drain could
  // still see them in countInFlight(). The new InboundCoalescer doesn't
  // expose individual timer handles — instead `reset()` does both at once
  // (cancel timers + drop entries). For the drain pattern, we rely on
  // post-drain `inboundCoalescer.reset()` below to do the cleanup, and let
  // any timer-driven flushes during drain still call into handleInbound
  // (which itself short-circuits when shuttingDown is true).

  clearInterval(pendingStateReaper)
  vaultPassphraseCache.clear()

  // #1067: orphaned-reply timeout now lives on the per-turn atom.
  if (currentTurn?.orphanedReplyTimeoutId != null) {
    clearTimeout(currentTurn.orphanedReplyTimeoutId)
    currentTurn.orphanedReplyTimeoutId = null
  }

  // Pre-allocated draft shutdown cleanup removed in #553 PR 5 — the
  // gateway no longer pre-allocates drafts on inbound, so there is
  // nothing to clear at SIGTERM time.

  // allow-broadcast: informational shutdown notify — bridges mark themselves disconnected
  ipcServer.broadcast({ type: 'status', status: 'gateway_shutting_down' })

  // Hard force-exit safety net at budget + 5s. systemd's TimeoutStopSec
  // is 45s; if we're not done by 40s something is genuinely wedged and
  // we'd rather exit than block the unit.
  // NOTE: this path intentionally skips releaseStartupLock — it only fires
  // when drain genuinely hung, and the next boot's stale-PID auto-recovery
  // (acquireStartupLock) reclaims the lock cleanly.
  const forceExitTimer = setTimeout(() => {
    process.stderr.write('telegram gateway: shutdown.force_exit budget_exceeded\n')
    process.exit(0)
  }, SHUTDOWN_DRAIN_BUDGET_MS + 5_000)
  forceExitTimer.unref()

  // Drain: stop polling, then await in-flight to settle. The drain
  // module logs shutdown.drain_start and shutdown.drain_complete so
  // operators can see exactly how long the long-poll took to die — the
  // KEY signal for diagnosing the next 409-conflict report.
  await drainShutdown({
    signal,
    stopPolling: async () => {
      if (runnerHandle != null) {
        await runnerHandle.stop()
      } else {
        await bot.stop()
      }
    },
    inFlight: countInFlight,
    budgetMs: SHUTDOWN_DRAIN_BUDGET_MS,
    agentName,
  })

  // Now finish the cleanup the drain didn't touch.
  inboundCoalescer.reset()
  pendingReauthFlows.clear()
  pendingVaultOps.clear()
  pendingPermissions.clear()
  permissionTimeoutSignatures.clear()

  try {
    await ipcServer.close()
  } catch (err) {
    process.stderr.write(`telegram gateway: ipc close error: ${err}\n`)
  }

  // Release the startup mutex / clear PID file. Logs shutdown.lock_released.
  // Session marker is intentionally left on disk — it's read by the
  // NEXT gateway process's banner-gate.
  await releaseStartupLock({
    path: GATEWAY_PID_PATH,
    pid: process.pid,
    agentName,
  })
  // Belt-and-braces: legacy clearPidFile is a no-op if the file is
  // already gone (which it should be after releaseStartupLock).
  clearPidFile(GATEWAY_PID_PATH)

  process.exit(0)
}
process.on('SIGTERM', () => void shutdown('SIGTERM'))
process.on('SIGINT', () => void shutdown('SIGINT'))

// ─── Stale reaction sweep (gateway crash recovery) ────────────────────────
{
  const startupAgentDir = resolveAgentDirFromEnv()
  if (startupAgentDir != null) {
    void sweepActiveReactions(
      startupAgentDir,
      (chatId, messageId) => lockedBot.api.setMessageReaction(chatId, messageId, [{ type: 'emoji', emoji: '👍' as ReactionTypeEmoji['emoji'] }]),
      { log: (msg) => process.stderr.write(`telegram gateway: startup reaction sweep — ${msg}\n`) },
    )
  }
}


// ─── Progress card driver (removed #1122 PR3) ─────────────────────────────
// The pinned progress card was deleted in favour of conversational
// pacing + the silence-poke safety net. The module-level helper vars
// (`unpinProgressCardForChat`, `getPinnedProgressCardMessageId`,
// `completeProgressCardTurn`, `flushProgressCardsForShutdown`,
// `progressDriver`) stay declared and `null`, so the remaining
// optional-chained call sites scattered through this file remain
// valid TypeScript and no-op at runtime.
//
// Cleanup pass (truthful-telemetry PR): the actively-misleading dead sites
// have been purged — the `status-query` telemetry now reads the live surfaces
// instead of the null-driver `peek()`; the sub-agent `onStall`/`onUnstall`/
// `onStallTerminal` gateway wirings (which falsely implied a stall renders a
// visual badge) are removed; the dead sub-agent card-injection block in
// `progress_update` is gone; and `progressCardActive` reads the literal false
// instead of `progressDriver != null`. The remaining `progressDriver?.X` /
// `unpinProgressCardForChat?.(...)` / `completeProgressCardTurn?.(...)` sites
// are interface-bound no-ops (deps handed to stream-reply-handler /
// disconnect-flush, or constant-folding guards inside the turn-flush backstop
// hot path); removing them means changing those modules' public shapes and is
// deferred so this PR stays scoped to truthful telemetry + comment fixes.


// ─── Startup ──────────────────────────────────────────────────────────────

// Top-level error handlers route through shutdown() so the startup lock is
// released cleanly. Without this, a top-level throw would leave the lock
// held until the next boot's stale-PID auto-recovery — workable, but noisy.
// The `shuttingDown` guard inside shutdown() prevents double-invocation if
// SIGTERM races with one of these handlers.
//
// `unhandledRejection` is discriminated through `classifyRejection` so that
// benign Telegram 400s ("message is not modified", "message to edit not
// found") are logged but NOT crashed-on. These leaked through restart loops
// for klanker (#99) and lawgpt's mid-day crash family — see the unit tests
// in `tests/unhandled-rejection-policy.test.ts`.
process.on('unhandledRejection', err => {
  const action = classifyRejection(err)
  process.stderr.write(
    `telegram gateway: unhandled rejection (${action}): ${err}\n`,
  )
  if (action === 'shutdown') {
    void shutdown('unhandledRejection')
  }
})
process.on('uncaughtException', err => {
  process.stderr.write(`telegram gateway: uncaught exception: ${err}\n`)
  void shutdown('uncaughtException')
})

let runnerHandle: RunnerHandle | null = null

// Long-poll health-check handle (issue #56). Created once per process, started
// after the runner comes up, stopped on clean shutdown. On a confirmed stall
// the gateway EXITS non-zero and the supervisor restarts it with a fresh runner
// (see recoverFromPollStall + the 2026-06-18 incident note there). It does NOT
// try to stop()+re-run the runner in place — grammy's stop() blocks on a non-
// abortable getUpdates retry backoff during a network outage, which hung the
// whole fleet deaf.
//
// Interval and threshold are configurable via env for ops/testing flexibility:
//   SWITCHROOM_POLL_HEALTH_INTERVAL_MS — default 60s (fast self-heal after a flap)
//   SWITCHROOM_POLL_HEALTH_THRESHOLD   — default 3 (a single blip must not trip it)
const POLL_HEALTH_INTERVAL_MS = Number(
  process.env.SWITCHROOM_POLL_HEALTH_INTERVAL_MS ?? 60_000,
)
const POLL_HEALTH_THRESHOLD = Number(
  process.env.SWITCHROOM_POLL_HEALTH_THRESHOLD ?? 3,
)

let pollHealthCheck: PollHealthCheckHandle | null = null
if (POLL_HEALTH_INTERVAL_MS > 0) {
  pollHealthCheck = createPollHealthCheck({
    ping: async () => {
      await bot.api.getMe()
      // Secondary: if getMe passes but getUpdates hasn't responded in
      // `threshold × interval` ms, the grammy runner loop is frozen without
      // the network being down. Throw so the failure counter increments and
      // stall recovery fires after `failureThreshold` consecutive misses.
      // (2026-06-30 incident: one getUpdates TimeoutError → runner silently
      // froze; getMe stayed green; fleet deaf for 2 h until manual restart.)
      const staleMs = Date.now() - lastGetUpdatesHeartbeatMs
      const staleThresholdMs = POLL_HEALTH_INTERVAL_MS * POLL_HEALTH_THRESHOLD
      if (staleMs > staleThresholdMs) {
        throw new Error(
          `getUpdates heartbeat stale: last seen ${Math.round(staleMs / 1000)}s ago ` +
          `(threshold ${Math.round(staleThresholdMs / 1000)}s) — runner loop frozen`,
        )
      }
    },
    onStall: async () => {
      // Exit non-zero → _switchroom_supervise restarts the gateway sidecar
      // with a fresh runner. Never awaits runnerHandle.stop() (it hangs on a
      // wedged source). recoverFromPollStall exits 1, never 78.
      recoverFromPollStall({ agentName: process.env.SWITCHROOM_AGENT_NAME ?? '-' })
    },
    intervalMs: POLL_HEALTH_INTERVAL_MS,
    failureThreshold: POLL_HEALTH_THRESHOLD,
    log: (msg) => process.stderr.write(msg.endsWith('\n') ? msg : msg + '\n'),
  })
}

// One-shot startup guard. The outer for-loop below re-enters its try block
// on 409 Conflict retries — those are transient polling conflicts, not
// process restarts. Anything that should fire exactly once per gateway
// process (restart-marker send, crash-recovery banner, boot-time pin sweep,
// auto-fallback setInterval, bot-command registration) must be gated by
// this flag. Otherwise every 409 retry re-runs them, producing the
// spurious "⚡ Recovered from unexpected restart" banners observed on
// 2026-04-22 (user received 4+ banners in 2 minutes while PID was constant
// and systemd logged zero lifecycle events — the only signal was the
// grammY 409 retry loop).
let didOneTimeSetup = false

void (async () => {
  // Load vault-grant approval posture once at startup. Side-effect: when
  // posture is `telegram-id`, this reads the machine-bound auto-unlock
  // blob and holds the plaintext passphrase in memory for silent
  // fallback when the operator taps Approve. Default-passphrase mode is
  // a no-op.
  try {
    initVaultApprovalPosture()
  } catch (err) {
    // Config-class refusal-to-boot: the operator declared
    // `vault.broker.approvalAuth: telegram-id` in switchroom.yaml but
    // the machine-bound auto-unlock blob is missing / unreadable /
    // empty. Pre-fix (#1115 follow-up, 2026-05-13) this throw bubbled
    // up as an unhandled rejection — the supervisor treated it as a
    // tight crash loop and posted an "agent-crashed" event on every
    // restart until the 10-in-60s cap kicked in. The right outcome is
    // EX_CONFIG (78) on the first failure so the supervisor
    // quarantines (see _switchroom_supervise's exit-78 short-circuit
    // in profiles/_base/start.sh.hbs) and the operator sees ONE
    // clean error in the log + the quarantine marker.
    const msg = err instanceof Error ? err.message : String(err)
    process.stderr.write(
      `telegram gateway: vault-posture-init-config-error — refusing to boot. ${msg}\n`,
    )
    try {
      writeQuarantineMarker(STATE_DIR, 'startup.config_error', msg)
    } catch (qerr) {
      process.stderr.write(
        `telegram gateway: failed to write quarantine marker: ${(qerr as Error).message}\n`,
      )
    }
    process.exit(78)
  }

  for (let attempt = 1; ; attempt++) {
    try {
      // ── Startup network-retry fence ───────────────────────────────────────
      // On boot the network stack may not be truly usable yet even after
      // network-online.target fires (observed 2026-04-29: all 5 gateways
      // started at ~21:26:26 and couldn't reach api.telegram.org for ~27 min).
      // Grammy throws HttpError for both deleteWebhook and getMe in that case.
      // `gatewayStartupRetry` absorbs those with exponential backoff (1s→64s,
      // 8 total attempts, ~2 min budget). On exhaustion it calls process.exit(1)
      // so systemd's Restart=always can restart the unit from a clean state.
      // Non-network errors (bad token, 403, etc.) are rethrown immediately so
      // the catch block below can handle them as before.
      const me = await gatewayStartupRetry(async () => {
        // Clear any orphan long-poll from a previous gateway process before we
        // start our own. See clearStaleTelegramPollingState docstring for the
        // production incident that motivates this. Safe to re-run on retries.
        await clearStaleTelegramPollingState(bot.api)
        return bot.api.getMe()
      }, {
        // #1076: a revoked/wrong-typed bot token returns 401 Unauthorized.
        // The pre-fix path rethrew non-network errors → the surrounding
        // catch exited 1 → `_switchroom_supervise` respawned → repeat. Ten
        // restarts in <60 s tripped the supervisor cap and the gateway
        // went silently dead. New path: classify 401, write a high-
        // severity issue (no token material, even truncated — threat
        // model assumes the token is the misused secret), write the
        // quarantine marker so the host CLI can refuse the next start,
        // exit 78 (sysexits EX_CONFIG) so `_switchroom_supervise`
        // stops respawning (start.sh.hbs treats 78 as "config error,
        // don't restart").
        onUnauthorized: (err) => {
          const agentName = process.env.SWITCHROOM_AGENT_NAME ?? '-'
          process.stderr.write(
            `telegram gateway: startup.unauthorized — Telegram API rejected the bot token (401). ` +
              `Marking agent quarantined; ` +
              `operator action: rotate the token, then \`switchroom agent unquarantine ${agentName}\`. ` +
              `err.name=${(err as Error)?.name ?? '?'}\n`,
          )
          // Issue sink — surfaces in `switchroom issues list` and
          // `switchroom doctor`. The detail field deliberately omits the
          // error message ("Unauthorized" is fine in principle but we
          // keep the surface tight against future Grammy versions that
          // might include header/body excerpts).
          try {
            switchroomExec([
              'issues', 'record',
              '--severity', 'critical',
              '--source', 'gateway.startup',
              '--code', 'gateway.startup.unauthorized',
              '--summary', 'bot token rejected by Telegram (401) at startup',
              '--detail', 'Telegram API returned 401 Unauthorized for the gateway startup probe. The bot token is revoked, rotated, or wrong-typed. Run `switchroom agent unquarantine ' + agentName + '` after rotating the token.',
              '--quiet',
            ])
          } catch (issueErr) {
            process.stderr.write(
              `telegram gateway: startup.unauthorized: failed to write issue sink: ${(issueErr as Error).message}\n`,
            )
          }
          // Quarantine marker — read by `switchroom apply` /
          // `switchroom agent restart` to refuse a doomed restart, and
          // by `switchroom doctor` to surface the state. Lives at
          // <TELEGRAM_STATE_DIR>/quarantine.json (the same dir the
          // gateway already minted at boot).
          try {
            writeQuarantineMarker(
              STATE_DIR,
              'startup.unauthorized',
              'Telegram API returned 401 Unauthorized for getMe at gateway startup.',
            )
          } catch (markerErr) {
            process.stderr.write(
              `telegram gateway: startup.unauthorized: failed to write quarantine marker: ${(markerErr as Error).message}\n`,
            )
          }
          // 78 = sysexits EX_CONFIG. start.sh.hbs's _switchroom_supervise
          // honours this as "config error, do not restart". A bare
          // exit 1 would put us right back in the respawn loop this fix
          // exists to prevent.
          process.exit(78)
        },
      })
      // Backport of upstream `7e401ed` (claude-plugins-official #1397):
      // reset the backoff counter on successful poll-loop start so a
      // transient mid-session 409 doesn't compound with prior attempts
      // and push the next retry past 15s. Note: the rest of #1397
      // (retry on non-409 transient errors) is supplanted in the
      // gateway by the deliberate process.exit(1) below — systemd's
      // Restart=always recovers from non-409 failures with a clean
      // reboot, which has been the chosen strategy since the 2026-04-29
      // "live-but-silent gateway" incident.
      attempt = 0
      botUsername = me.username
      botUserId = me.id
      process.stderr.write(`telegram gateway: polling as @${me.username}\n`)
      if (TOPIC_ID != null) process.stderr.write(`telegram gateway: topic filter active — thread_id=${TOPIC_ID}\n`)

      if (!didOneTimeSetup) {
        didOneTimeSetup = true
        void registerSwitchroomBotCommands().catch(() => {})

        // #613 fix: pre-warm the chatAvailableReactions cache for every
        // chat in access.allowFrom. Without this, the FIRST inbound
        // message to a restricted-reactions supergroup after a gateway
        // restart still hits the original #542 bug (controller created
        // with `null` filter → intermediate emojis 400 → only 👍 lands).
        // The lazy-probe path (gateway.ts:~4681) populates the cache
        // for subsequent messages but can't help the first one.
        //
        // Fire-and-forget per chat. Failures (rate limit, no permission,
        // network) leave the cache unset so the lazy path retries on
        // first message — preserves today's behaviour as a safety net.
        try {
          const accessAtBoot = loadAccess()
          for (const chatId of accessAtBoot.allowFrom) {
            probeAvailableReactions(chatId)
          }
          if (accessAtBoot.allowFrom.length > 0) {
            process.stderr.write(
              `telegram gateway: probed available_reactions for ${accessAtBoot.allowFrom.length} configured chat(s)\n`,
            )
          }
        } catch (err) {
          process.stderr.write(
            `telegram gateway: boot-probe of available_reactions failed (continuing): ${(err as Error).message}\n`,
          )
        }

        // RFC H removes the per-account-quota-cache boot-warm: the
        // auth-broker owns quota state now; the gateway reads it via
        // `list-state` on demand and renders directly. No in-process
        // cache to warm.

        // #412 boot-cleanup: clear any pre-existing turn-active marker.
        // By definition no turn can be in flight when the gateway just
        // started — any leftover marker is from a turn that never
        // completed (gateway killed mid-turn, restart while waiting on
        // a tool, etc). Without this, the watchdog reads the orphan
        // mtime, sees age >= TURN_HANG_SECS, and restarts the agent —
        // which kills the gateway mid-cleanup, leaving the marker
        // again. Result: a 2-min flap loop.
        //
        // Safe vs the long-running background sub-agent case: this
        // only runs at boot. A parent that's mid-flight with a
        // background worker writes a fresh marker on its next
        // tool_use (e.g. dispatching the worker), so the marker
        // tracks the live turn from there.
        try { removeTurnActiveMarker(STATE_DIR) } catch { /* best-effort */ }

        // Strip stale permission cards from prior gateway session. Any entry
        // still in the store was never resolved (gateway died before the
        // operator tapped or the reaper ran). The operator might have seen
        // those cards and tapped them — if so, they got STALE_TAP_NOTICE
        // ("already resolved") which is misleading. Edit the messages to
        // remove the keyboard and show a clear "restarted" notice instead.
        void (async () => {
          const stale = permCardStore.loadAll()
          if (stale.length === 0) return
          process.stderr.write(
            `telegram gateway: boot-sweep: stripping ${stale.length} stale permission card(s) from prior gateway session\n`,
          )
          for (const card of stale) {
            const toolLabel = card.toolName ?? 'unknown tool'
            const notice = `🔒 **${toolLabel}**\n\n⚠️ *Gateway restarted — this request is no longer active. Ask your agent to try again if needed.*`
            try {
              // allow-raw-bot-api: targeted by message_id; no thread needed; fire-and-forget boot sweep
              await bot.api.editMessageText(
                card.chatId,
                card.messageId,
                richMessage(notice),
                { reply_markup: { inline_keyboard: [] } },
              )
            } catch (err) {
              // Card may already be deleted, edited, or in an inaccessible chat — benign
              process.stderr.write(
                `telegram gateway: boot-sweep: stale-card strip failed ` +
                `${card.chatId}:${card.messageId}: ${(err as Error).message}\n`,
              )
            }
          }
          permCardStore.clear()
        })()

        // Boot-time pin sweep
        try {
          const bootAccess = loadAccess()
          const chatSet = new Set<string>(bootAccess.allowFrom)
          for (const gid of Object.keys(bootAccess.groups)) chatSet.add(gid)
          // Filter out user DM IDs (positive integers) — the Bot API returns
          // `400 chat not found` for users who have never messaged the bot.
          // Only sweep group/supergroup IDs (negative integers) at boot.
          const sweepableIds: string[] = []
          const skippedIds: string[] = []
          for (const id of chatSet) {
            if (shouldSweepChatAtBoot(id)) {
              sweepableIds.push(id)
            } else {
              skippedIds.push(id)
            }
          }
          for (const id of skippedIds) {
            process.stderr.write(`telegram gateway: startup: skipped chat ${id} (not yet reachable)\n`)
          }
          // #1122 PR3: bot-authored progress-card pin sweep at boot
          // removed with the card. The boot-probe failure notifier
          // that used to ride along is gone too; reachability checks
          // for chats now happen lazily when an inbound message lands.
          void sweepableIds
        } catch {}

        // Boot card — always post on every gateway start with the restart reason.
        // Gated on session marker so a grammY poll-restart (same process, no
        // actual restart) does NOT re-post.  See session-marker.ts for the
        // 2026-04-22 incident that introduced this gate.
        try {
          const nowMs = Date.now()
          const marker = readRestartMarker()
          const cleanMarker = readCleanShutdownMarker(GATEWAY_CLEAN_SHUTDOWN_MARKER_PATH)
          const currentSession: SessionMarker = { pid: process.pid, startedAtMs: GATEWAY_STARTED_AT_MS }
          const storedSession = readSessionMarker(GATEWAY_SESSION_MARKER_PATH)
          const isRealRestart = shouldFireRestartBanner({ stored: storedSession, current: currentSession })

          if (cleanMarker) {
            const ageSec = Math.max(0, Math.round((nowMs - cleanMarker.ts) / 1000))
            const reasonTag = cleanMarker.reason ? ` reason=${JSON.stringify(cleanMarker.reason)}` : ''
            const cleanFresh = shouldSuppressRecoveryBanner(cleanMarker, nowMs, CLEAN_SHUTDOWN_MAX_AGE_MS)
            // The 60s `cleanFresh` window is the tight default. The
            // separate `determineRestartReason()` call below applies an
            // extended 5-min window for `operator:`-prefixed markers
            // (#1142 — fleet recreate can exceed 60s before the last
            // container's gateway boots). Mirror that here so the
            // diagnostic log line doesn't contradict the actual
            // decision: an "operator:" marker that's >60s old but
            // inside the extended window logs as `_fresh_extended`,
            // not `_stale`. The decision/log mismatch was flagged in
            // PR #1142 review.
            const isOperatorMarker = typeof cleanMarker.reason === 'string'
              && cleanMarker.reason.startsWith('operator:')
            if (cleanFresh) {
              process.stderr.write(`telegram gateway: boot.clean_shutdown_detected age=${ageSec}s signal=${cleanMarker.signal}${reasonTag}\n`)
            } else if (isOperatorMarker && nowMs - cleanMarker.ts < 5 * 60_000) {
              process.stderr.write(`telegram gateway: boot.clean_shutdown_marker_fresh_extended age=${ageSec}s signal=${cleanMarker.signal}${reasonTag} window=5min\n`)
            } else {
              process.stderr.write(`telegram gateway: boot.clean_shutdown_marker_stale age=${ageSec}s signal=${cleanMarker.signal}${reasonTag}\n`)
            }
            // 2026-05-25 — clear the marker after this boot has read it.
            // Pre-fix the comment here claimed the file was "self-
            // overwriting, age-gated, harmless to leave on disk" — that's
            // true ONLY for the cycle where every shutdown writes a fresh
            // marker. The unhandledRejection / uncaughtException paths
            // explicitly SKIP writing (gateway.ts:15107 — the "crash path")
            // so a marker from an earlier graceful shutdown sits on disk
            // for hours, then on the next boot looks stale-by-age and
            // fires a misleading agent-crashed banner with detail
            // `clean-shutdown marker stale age=39976s` (clerk 2026-05-25
            // 01:11). Clearing now means the marker only ever describes
            // the IMMEDIATELY PRECEDING shutdown, not "some shutdown in
            // the past". After this clear: a subsequent crash with no
            // marker write = no marker file = correctly classified
            // 'crash' via the sessionMarker fallback (boot-reason.ts:84);
            // a graceful shutdown writes a fresh marker that the next
            // boot reads + clears. The historical session-greeting.sh
            // ownership the old comment referred to is gone since #142
            // but the GC step was never re-homed — this is it.
            clearCleanShutdownMarker(GATEWAY_CLEAN_SHUTDOWN_MARKER_PATH)
          }

          if (marker) {
            const ageMs = nowMs - marker.ts
            const ageSec = Math.max(1, Math.round(ageMs / 1000))
            process.stderr.write(`telegram gateway: boot: restart-marker present, chat_id=${marker.chat_id} age=${ageSec}s within5min=${ageMs < 5 * 60_000}\n`)
            clearRestartMarker()
          }

          if (!isRealRestart) {
            process.stderr.write(`telegram gateway: boot: suppressed boot card — session marker matches current process (pid=${process.pid} startedAt=${GATEWAY_STARTED_AT_MS})\n`)
          } else {
            const markerAgeMs = marker ? nowMs - marker.ts : undefined
            const reason = determineRestartReason({ marker, cleanMarker, sessionMarker: storedSession, now: nowMs })
            const target = resolveBootChatId(marker, markerAgeMs)

            // Issue #92: when reason='crash' AND no chat is resolvable,
            // the gateway used to silently skip — the only signal a user
            // got was their next message landing on a fresh process. Now
            // we always surface unplanned crashes via the operator-events
            // pipeline, which broadcasts to access.allowFrom (same path
            // permission requests use). The pipeline's per-agent per-kind
            // cooldown protects against crash loops spamming the chat.
            if (reason === 'crash') {
              const cleanMarkerStale = cleanMarker
                ? !shouldSuppressRecoveryBanner(cleanMarker, nowMs, CLEAN_SHUTDOWN_MAX_AGE_MS)
                : false
              const supervisor = process.env.SWITCHROOM_RUNTIME === 'docker'
                ? 'docker compose'
                : 'systemd'
              const detailParts: string[] = [`gateway crashed and was auto-restarted by ${supervisor}`]
              if (cleanMarker?.signal) detailParts.push(`prior signal=${cleanMarker.signal}`)
              if (cleanMarkerStale) detailParts.push('clean-shutdown marker stale')
              emitGatewayOperatorEvent({
                kind: 'agent-crashed',
                agent: process.env.SWITCHROOM_AGENT_NAME ?? '-',
                detail: detailParts.join(' — '),
                suggestedActions: [],
                firstSeenAt: new Date(),
              })
            }

            if (target) {
              const { chatId, threadId, ackMsgId } = target
              // First-write-wins dedupe: if bridge-reconnect already
              // claimed (its IPC client connected before this IIFE
              // reached the emit), defer to it. Symmetric with the
              // bridge-reconnect side's check above. See finn 2026-05-02
              // duplicate (msgId 673 + 674) — fix removes the boot=primary
              // assumption that special-cased boot to never skip.
              const bootDedupe = shouldSkipDuplicateBootCard({ activeBootCard, bootCardPending }, 'boot')
              if (bootDedupe.skip) {
                process.stderr.write(`telegram gateway: boot: skipping boot card (${bootDedupe.reason})\n`)
              } else {
                process.stderr.write(`telegram gateway: boot: posting boot card reason=${reason} chat_id=${chatId} thread_id=${threadId ?? '-'} ackReply=${ackMsgId ?? '-'} boot_card=${BOOT_CARD_ENABLED}\n`)
                ensureIssuesCard(chatId, threadId)
                if (BOOT_CARD_ENABLED) {
                  const agentDir = resolveAgentDirFromEnv()
                  const agentSlug = process.env.SWITCHROOM_AGENT_NAME ?? '-'
                  const agentDisplayName = resolvePersonaName(agentSlug)
                  const botApiForCard: import('./boot-card.js').BotApiForBootCard = wrapBootCardApi(threadId)
                  // Claim emission ownership synchronously BEFORE the await so
                  // the bridge-reconnect dedupe (which can run during this
                  // sendMessage round-trip) sees an in-flight emit. See #489.
                  bootCardPending = true
                  try {
                    // PR C: mirror the bridge-reconnect path — surface
                    // a recent terminal update_apply outcome with claim
                    // dedupe so it doesn't render twice if bridge
                    // re-connects within the lookback window.
                    const updateOutcomeLine = (() => {
                      try { return maybeRenderUpdateAnnouncement() ?? undefined } catch { return undefined }
                    })()
                    const resolvedAgentDirForBootCard = agentDir ?? join(homedir(), '.switchroom', 'agents', agentSlug)
                    const handle = await startBootCard(chatId, threadId, botApiForCard, {
                      agentName: agentDisplayName,
                      agentSlug,
                      version: formatBootVersion(),
                      agentDir: resolvedAgentDirForBootCard,
                      gatewayInfo: { pid: process.pid, startedAtMs: GATEWAY_STARTED_AT_MS },
                      restartReason: reason,
                      restartAgeMs: markerAgeMs,
                      restartReasonDetail: cleanMarker?.reason,
                      loadAccounts: () => loadAccountsForBootCard(agentSlug),
                      probeQuotaViaBroker: (t) => probeQuotaForBootCard(agentSlug, t),
                      tmuxSupervisor: process.env.SWITCHROOM_TMUX_SUPERVISOR === '1',
                      dockerMode: process.env.SWITCHROOM_RUNTIME === 'docker',
                      configSnapshotPath: join(resolvedAgentDirForBootCard, '.config-snapshot.json'),
                      bootCardStatePath: join(resolvedAgentDirForBootCard, '.boot-card-msgid.json'),
                      ...(updateOutcomeLine ? { updateOutcomeLine } : {}),
                    }, ackMsgId)
                    activeBootCard = handle
                  } catch (err) {
                    process.stderr.write(`telegram gateway: boot: boot card error: ${err}\n`)
                  } finally {
                    bootCardPending = false
                  }
                } else {
                  const ageSec = markerAgeMs != null ? Math.max(1, Math.round(markerAgeMs / 1000)) : 0
                  postLegacyBanner(chatId, threadId, ackMsgId, ageSec, 'boot')
                }
              }
            } else {
              process.stderr.write(`telegram gateway: boot: no known chat for boot card (reason=${reason}) — skipping\n`)
            }
          }

          // Always update the session marker so subsequent boots see "stored === current".
          try {
            writeSessionMarker(GATEWAY_SESSION_MARKER_PATH, currentSession)
          } catch (err) {
            process.stderr.write(`telegram gateway: writeSessionMarker failed: ${err}\n`)
          }
        } catch {}

        // Credit-exhaustion watcher (#348). Reads `<agentDir>/.claude/.claude.json`
        // for `cachedExtraUsageDisabledReason`. Fires a Telegram notification
        // on transition into / out of fatal billing states (out_of_credits,
        // org_level_disabled, credits_exhausted, extra_usage_disabled).
        // Pre-#348, cron tasks against an exhausted account silently failed
        // because stdout was discarded — direct violation of P1 JTBD (silent
        // failure is the worst case).
        //
        // Cadence: 15 min by default; tuned to be cheaper than the API
        // quota poll because this is a local file read (no network).
        // SWITCHROOM_CREDIT_WATCH_POLL_MS=0 disables.
        const CREDIT_WATCH_POLL_MS = Number(process.env.SWITCHROOM_CREDIT_WATCH_POLL_MS ?? 15 * 60_000)
        if (CREDIT_WATCH_POLL_MS > 0) {
          // Run an immediate check at boot so a recent fatal transition
          // doesn't have to wait 15 min to surface.
          void runCreditWatch().catch((err) => {
            process.stderr.write(`telegram gateway: credit-watch initial run failed: ${err}\n`)
          })
          setInterval(() => {
            void runCreditWatch().catch((err) => {
              process.stderr.write(`telegram gateway: credit-watch scheduled run failed: ${err}\n`)
            })
          }, CREDIT_WATCH_POLL_MS).unref()
        }

        // Proactive quota threshold-tier push (#E4). Reads broker cached
        // quota for all accounts in the pool, classifies health via
        // classifyHealth, and fires one Telegram message per
        // healthy ↔ throttling transition (edge-triggered). Does NOT
        // cover healthy → blocked or blocked → healthy — credits-watch
        // handles those fatal-billing transitions above.
        //
        // Cadence: 15 min by default (same as credit-watch). Each poll
        // calls broker listState (local IPC, cheap) + probeQuota only
        // when a state-change is detected (to get fresh numbers for
        // the notification body). SWITCHROOM_QUOTA_WATCH_POLL_MS=0 disables.
        const QUOTA_WATCH_POLL_MS = Number(process.env.SWITCHROOM_QUOTA_WATCH_POLL_MS ?? 15 * 60_000)
        if (QUOTA_WATCH_POLL_MS > 0) {
          // Delay the initial run by 30 s to let the broker connection
          // settle after boot (avoids a probe race with the boot-card
          // quota probe that fires in the first few seconds).
          setTimeout(() => {
            // bootTick: recovery edges observed on the FIRST post-boot tick
            // reconcile silently — a fleet bounce synchronizes all agents'
            // first ticks, and a just-booted gateway can't tell "just
            // recovered" from "recovered while we were down" (the
            // 2026-06-09 26-message flood). Warnings still notify.
            void runQuotaWatch({ bootTick: true }).catch((err) => {
              process.stderr.write(`telegram gateway: quota-watch initial run failed: ${err}\n`)
            })
          }, 30_000)
          setInterval(() => {
            void runQuotaWatch().catch((err) => {
              process.stderr.write(`telegram gateway: quota-watch scheduled run failed: ${err}\n`)
            })
          }, QUOTA_WATCH_POLL_MS).unref()
        }

        // Proactive Linear-auth watch (FIX 3): catch a dead/missing/near-expiry
        // Linear bundle BEFORE the agent needs Linear, instead of only on a live
        // 401. Boot run (delayed so the broker connection settles) + interval.
        // SWITCHROOM_LINEAR_AUTH_WATCH_POLL_MS=0 disables it.
        const LINEAR_AUTH_WATCH_POLL_MS = Number(process.env.SWITCHROOM_LINEAR_AUTH_WATCH_POLL_MS ?? 6 * 60 * 60_000)
        if (LINEAR_AUTH_WATCH_POLL_MS > 0) {
          setTimeout(() => {
            void runLinearAuthWatch().catch((err) => {
              process.stderr.write(`telegram gateway: linear-auth-watch initial run failed: ${err}\n`)
            })
          }, 35_000)
          setInterval(() => {
            void runLinearAuthWatch().catch((err) => {
              process.stderr.write(`telegram gateway: linear-auth-watch scheduled run failed: ${err}\n`)
            })
          }, LINEAR_AUTH_WATCH_POLL_MS).unref()
        }

        // Restart-watchdog: poll systemd's NRestarts for the agent unit.
        // When the count ticks up without a corresponding restart-pending
        // marker (= user-initiated /restart), emit an operator event.
        // Closes #30 task 4 and the 2026-04-21 lessons-learned loop where
        // IPC flaps falsely triggered the gateway's recovery banner.
        // SWITCHROOM_RESTART_WATCHDOG_POLL_MS=0 disables it.
        //
        // Disabled under SWITCHROOM_RUNTIME=docker — the watchdog reads
        // systemd's NRestarts counter, which doesn't exist for docker
        // containers. Reading docker's restart count would require
        // mounting docker.sock into the agent container (a security
        // regression we explicitly avoid). Container restart visibility
        // comes from the boot card + gateway boot logs in docker mode.
        const RESTART_WATCHDOG_POLL_MS = Number(
          process.env.SWITCHROOM_RESTART_WATCHDOG_POLL_MS ?? 30_000,
        )
        const watchdogAgentName = process.env.SWITCHROOM_AGENT_NAME
        const watchdogDockerMode = process.env.SWITCHROOM_RUNTIME === 'docker'
        if (watchdogDockerMode) {
          process.stderr.write(
            `telegram gateway: restart-watchdog disabled (SWITCHROOM_RUNTIME=docker; systemd NRestarts unavailable)\n`,
          )
        } else if (RESTART_WATCHDOG_POLL_MS > 0 && watchdogAgentName) {
          startRestartWatchdog({
            agentName: watchdogAgentName,
            pollIntervalMs: RESTART_WATCHDOG_POLL_MS,
            execShow: (unit) =>
              execFileSync(
                'systemctl',
                ['--user', 'show', unit, '-p', 'NRestarts,ActiveEnterTimestampMonotonic'],
                { encoding: 'utf-8', timeout: 5000, stdio: ['ignore', 'pipe', 'pipe'] },
              ) as string,
            isPlannedRestartFresh: () => isPlannedRestartFresh(),
            emit: (detail) => {
              emitGatewayOperatorEvent({
                kind: 'agent-restarted-unexpectedly',
                agent: watchdogAgentName,
                detail,
                suggestedActions: [],
                firstSeenAt: new Date(),
              })
            },
            log: (msg) =>
              process.stderr.write(msg.endsWith('\n') ? `telegram gateway: ${msg}` : `telegram gateway: ${msg}\n`),
          })
        }

        // Background sub-agent visibility watcher. Watches the subagents/
        // directory under each session dir for new agent-<id>.jsonl files
        // and surfaces live activity to Telegram via a pinned card +
        // inline notifications. Only started when a valid agentDir is known
        // (gate on streamMode=checklist for progress-card parity).
        if (streamMode === 'checklist') {
          const watcherAgentDir = resolveAgentDirFromEnv()
          if (watcherAgentDir != null) {
            // #PR2 — live worker-activity feed. A *background* sub-agent
            // decouples from the parent turn, so when the turn ends nothing
            // surfaces its ongoing jsonl activity and a long worker reads as
            // silence. This feed posts ONE regular chat message per worker
            // and edits it in place as work happens (current tool + elapsed),
            // finalizing on completion — the same "live, growing message"
            // shape the main agent's answer uses, NOT card chrome (the pinned
            // card was deleted in #1126). On by default (set
            // SWITCHROOM_WORKER_ACTIVITY_FEED=0 to disable); when ON it also
            // supersedes the coarse 5-min bucket relay below to avoid
            // double-surfacing the same progress beat.
            const workerFeedEnabled = isWorkerActivityFeedEnabled(process.env.SWITCHROOM_WORKER_ACTIVITY_FEED)
            // Model A — foreground sub-agent nesting in the parent's live
            // activity draft. ON by default; this edits the SAME activity-
            // summary message the tool_label feed already owns (not the
            // compose draft, so no answer-stream contention). The kill-switch
            // disables only the nesting; the parent's own feed is unaffected.
            const foregroundNestingEnabled = process.env.SWITCHROOM_FOREGROUND_SUBAGENT_NESTING !== '0'
            // Orphaned-foreground status (2026-06-09): a FOREGROUND sub-agent
            // with no live parent turn to nest into (dispatched outside a turn,
            // or the turn ended while it kept running — extended autonomous
            // work) is surfaced via the worker feed instead of vanishing.
            const orphanStatusEnabled = isOrphanSubagentStatusEnabled(process.env.SWITCHROOM_ORPHAN_SUBAGENT_STATUS)
            workerActivityFeed?.stop()
            workerActivityFeed = createWorkerActivityFeed({
              // #2669: worker-feed body is raw GFM markdown — send via rich.
              bot: {
                sendMessage: async (cid, text, sendOpts) => {
                  const sent = await robustApiCall(
                    () =>
                      // allow-raw-bot-api: sendRichMessage routed through robustApiCall (not in the THREAD_NOT_FOUND blast pattern)
                      lockedBot.api.sendRichMessage(
                        cid,
                        richMessage(text),
                        sendOpts as Parameters<typeof lockedBot.api.sendRichMessage>[2],
                      ),
                    { chat_id: cid, verb: 'worker-feed' },
                  )
                  return sent as { message_id: number }
                },
                editMessageText: (cid, mid, text, editOpts) =>
                  robustApiCall(
                    () =>
                      lockedBot.api.editMessageText(
                        cid,
                        mid,
                        richMessage(text),
                        editOpts as Parameters<typeof lockedBot.api.editMessageText>[3],
                      ),
                    { chat_id: cid, verb: 'worker-feed' },
                  ),
              },
              log: (msg) => process.stderr.write(`telegram gateway: ${msg}\n`),
            })
            subagentWatcher = startSubagentWatcher({
              agentDir: watcherAgentDir,
              // Issue #1116 (Bug A): restrict project-dir enumeration to
              // the slug Claude Code mints for this agent's cwd (which
              // start.sh sets to agentDir before launching claude — see
              // profiles/_base/start.sh.hbs `cd "{{agentDir}}"`). Foreign-
              // slug shadow dirs left over from a prior CLAUDE_PROJECT_DIR
              // accident no longer pollute the watcher with phantom
              // registrations + ENOENT log spam + false stalls.
              agentCwd: watcherAgentDir,
              // Bug 0 fix: previously omitted, leaving the watcher unable to
              // write liveness/stall/turn_end updates to the registry DB.
              // Liveness writes are now persisted across the gateway lifetime.
              db: turnsDb,
              // Issue #501: parent state dir so foreground sub-agent activity
              // refreshes the parent's `turn-active.json` mtime. Without this
              // a foreground sub-agent silent for >TURN_HANG_SECS (default
              // 300s) lets the parent's marker age out and the watchdog
              // restarts the parent — even though real work is happening
              // inside the sub-agent. Belt-and-braces with PR #557's
              // multi-signal progress gate.
              parentStateDir: STATE_DIR,
              // No user-facing notification callback: the card-era
              // "✓ Worker done" message was retired with the progress
              // card (#1122). Sub-agent completion reaches the user as
              // the model's own beat-4 handback reply; the watcher's
              // role here is registry liveness + the `onFinish` cue.
              log: (msg) => process.stderr.write(`telegram gateway: ${msg}\n`),
              // #1122/#1126 cleanup: the `onStall` / `onUnstall` /
              // `onStallTerminal` callbacks used to route into
              // `progressDriver.onSubAgentStall` / `onSubAgentUnstall` /
              // `ingest(sub_agent_turn_end)` so the pinned card could render a
              // ⚠️ badge and release its deferred-completion gate. That card
              // was deleted and `progressDriver` is permanently null, so those
              // wirings were dead no-ops that falsely implied a stall renders a
              // visual badge (it doesn't). They are removed here.
              //
              // The load-bearing completion path is NOT here: subagent-watcher's
              // silent-stall terminal synthesis writes the terminal registry-DB
              // row itself (`recordSubagentEnd`) and fires `maybySendStateTransition`
              // → `onFinish` (the handback) independently of `onStallTerminal`.
              // Re-painting a live background worker on stall/unstall is PR 2's
              // job (via the `🛠 Worker` activity feed, not a retired card).
              // conversational-pacing beat 4 — the handback. A foreground
              // sub-agent hands its result straight back as the Task tool
              // result, inside the parent's own turn; the model sees it
              // in-context. A *background* sub-agent does not — it
              // finishes decoupled from any turn boundary, with the parent
              // typically idle and no turn to receive the result. Without
              // a nudge the user never hears back until they send the next
              // message themselves. So: when a background sub-agent
              // terminates, wake the agent with a `subagent_handback`
              // inbound carrying the worker's result text, and let it
              // synthesise a user-facing handback in its own voice.
              //
              // Gated to background completions: foreground sub-agents
              // need nothing here, and 'orphan' is a stale historical-at-
              // boot row, not a fresh completion the user is waiting on.
              onFinish: ({ agentId, outcome, description, resultText, toolCount, durationMs }) => {
                // Reaction promotion: if the parent turn already ended
                // with this (or another) worker still running, its 👍 was
                // deferred (held on ✍️/⚡). Now that a worker finished,
                // promote to 👍 iff none remain running. Independent of the
                // handback gating below, so it must run before any early
                // return. Cheap no-op when nothing is deferred.
                deferredDoneReactions.promote()
                // IO: resolve the fleet chat id and the background flag.
                // The DECISION (gating + inbound build) is delegated to
                // the pure `decideSubagentHandback` so it is unit-tested
                // independent of the gateway — see
                // `subagent-handback-decision.test.ts`.
                let fleetChatId = ''
                try {
                  const fleets = progressDriver?.peekAllFleets() ?? []
                  for (const f of fleets) {
                    if (f.fleet.has(agentId)) {
                      fleetChatId = f.chatId ?? ''
                      break
                    }
                  }
                } catch {
                  // peek failures are non-fatal — fall through to the
                  // owner-chat fallback inside decideSubagentHandback.
                }
                // Background flag + feed header description, both derived from
                // the registry row via the pure resolveWorkerFeedDispatch
                // (worker-feed-dispatch.ts, pinned by its test). Best-effort:
                // a DB hiccup keeps the watcher's generic label rather than
                // throwing out of the terminal handler.
                let dispatch: WorkerFeedDispatch = resolveWorkerFeedDispatch(null, description)
                if (turnsDb != null) {
                  try {
                    dispatch = resolveWorkerFeedDispatch(getSubagentByJsonlId(turnsDb, agentId), description)
                  } catch { /* best-effort */ }
                }
                const isBackground = dispatch.isBackground
                // NESTED (depth-2+) worker terminal: its live status surfaced
                // via the worker feed (see onProgress), so finalize that card
                // cleanly — never leave it frozen mid-"→ step". But NO user
                // handback: its result returns to its DISPATCHING WORKER as
                // the Task tool result (the depth-1 worker folds it into its
                // own handback); injecting a second gateway handback would
                // double-report the same work.
                if (dispatch.isNested) {
                  if (workerFeedEnabled) {
                    void workerActivityFeed?.finish(agentId, {
                      description: dispatch.feedDescription,
                      lastTool: null,
                      toolCount,
                      latestSummary: resultText,
                      elapsedMs: durationMs,
                      state: outcome === 'failed' ? 'failed' : 'done',
                    })
                    reconcileWorkerPin(agentId, null, false)
                  }
                  return
                }
                if (!isBackground) {
                  // Model A — a foreground sub-agent finished. Collapse its
                  // nested child block from the parent's activity draft; the
                  // parent resumes and its result returns inline as the Task
                  // tool result, so there's no handback to deliver. Reaction
                  // promotion already ran above.
                  const turn = currentTurn
                  // has()-then-delete (not delete-up-front): the handoff-clear
                  // branch must render the finished sub-agent's steps as done
                  // WHILE its narrative is still in the map, then remove it.
                  if (turn != null && turn.foregroundSubAgents.has(agentId)) {
                    const action = foregroundFinishAction({
                      removed: true,
                      replyCalled: turn.replyCalled,
                      // size AFTER this agent's impending removal
                      remainingForeground: turn.foregroundSubAgents.size - 1,
                    })
                    if (action === 'handoff-clear') {
                      // Post-ack: the last foreground sub-agent finished and
                      // the parent will now produce its answer inline. Hand
                      // the re-opened feed off to the answer, mirroring the
                      // first-reply clear (turn_end is the safety net). Capture
                      // the finalized render (child steps done ✓) BEFORE the
                      // delete, then pass it so the persisted record doesn't
                      // freeze on a stale "→ in-progress" line (the emptied-feed
                      // skip — see clearActivitySummary's finalHtmlOverride doc).
                      const finalHtml = composeTurnActivity(turn, true)
                      turn.foregroundSubAgents.delete(agentId)
                      clearActivitySummary(turn, finalHtml)
                    } else if (action === 'recompose') {
                      // Collapse the finished sub-agent's block: delete first,
                      // then render WITHOUT it (live feed keeps its → step).
                      turn.foregroundSubAgents.delete(agentId)
                      const rendered = composeTurnActivity(turn)
                      if (rendered != null) {
                        turn.activityPendingRender = rendered
                        // PR-4a: routed through the emission-authority façade
                        // (no-op delegate). Producer made explicit ('tool' — the
                        // drain default this foreground sub-agent render used).
                        const ea = emissionAuthorityFor(turn)
                        // PR-4d: route through the centralized card-drain gate.
                        cardDrainGate(turn, ea, () => {
                        if (ea.mayDrain(turn)) {
                          ea.openOrEditCard('tool', () => {
                            turn.activityInFlight = drainActivitySummary(turn, 'tool')
                          })
                        }
                        })
                      }
                    }
                    return
                  }
                  // Not nested → an orphaned foreground sub-agent that was
                  // surfaced via the worker feed (no live turn to nest into):
                  // finalize its message (no-op if none was posted). A
                  // foreground result returns inline as the Task tool result, so
                  // there is no handback to deliver — return after.
                  if (
                    resolveSubagentStatusSurface({
                      isBackground: false,
                      liveTurnPresent: false,
                      workerFeedEnabled,
                      orphanStatusEnabled,
                    }) === 'worker-feed'
                  ) {
                    void workerActivityFeed?.finish(agentId, {
                      description: dispatch.feedDescription,
                      lastTool: null,
                      toolCount,
                      latestSummary: resultText,
                      elapsedMs: durationMs,
                      state: outcome === 'failed' ? 'failed' : 'done',
                    })
                    // Status-pin: worker done — drop its pin.
                    reconcileWorkerPin(agentId, null, false)
                  }
                  return
                }
                // #PR2 live worker-feed: force the terminal recap edit on
                // the worker's live message. No-op when no message was ever
                // posted (trivial workers stay silent; handback covers them).
                // 'orphan' is a stale boot row, not a fresh completion — map
                // it to 'done' so an already-posted message still finalizes.
                if (workerFeedEnabled) {
                  void workerActivityFeed?.finish(agentId, {
                    description: dispatch.feedDescription,
                    lastTool: null,
                    toolCount,
                    latestSummary: resultText,
                    elapsedMs: durationMs,
                    state: outcome === 'failed' ? 'failed' : 'done',
                  })
                  // Status-pin: worker done — drop its pin.
                  reconcileWorkerPin(agentId, null, false)
                }

                const handbackOrigin = resolveSubagentOriginChat(agentId)
                const decision = decideSubagentHandback({
                  handbackEnvValue: process.env.SWITCHROOM_SUBAGENT_HANDBACK,
                  outcome,
                  isBackground,
                  // Route the handback (the worker's result → a synthesized
                  // turn) back to the conversation the Task was dispatched
                  // from, so the result lands where the user asked — not the
                  // agent's DM. Falls back to fleetChatId/ownerChatId.
                  fleetChatId: handbackOrigin?.chatId || fleetChatId,
                  // Supergroup topic the Task was dispatched from. Plumbed
                  // through so the handback turn (and the model's in-voice
                  // "here's what the worker found" reply) land in the
                  // originating topic — not the chat's last-seen topic.
                  // Applied only when the origin chat resolved (DM fallback
                  // is topic-less).
                  ...(handbackOrigin?.threadId != null
                    ? { originThreadId: handbackOrigin.threadId }
                    : {}),
                  // Owner-chat fallback: if the parent-turn chat can't be
                  // resolved, route to the owner chat.
                  ownerChatId: loadAccess().allowFrom[0] ?? '',
                  taskDescription: description,
                  resultText,
                  // Plumb the JSONL agent id so the spool can mint a
                  // deterministic dedup key — closes the #1719
                  // re-fire-on-restart class.
                  jsonlAgentId: agentId,
                })
                if (!decision.deliver) {
                  if (decision.reason === 'no-chat') {
                    process.stderr.write(
                      `telegram gateway: subagent-handback ${agentId} — no chat to deliver to; skipped\n`,
                    )
                  }
                  return
                }

                // #1720: when the handback is queued, sweep any still-
                // live progress envelopes for the SAME sub-agent out of
                // the spool. Without this a progress envelope queued
                // moments before the worker finished could land on top
                // of the handback turn, producing a duplicated /
                // contradictory "still running" line. Prefix match on
                // `s:progress:<jsonl_agent_id>:` — see `inbound-spool.ts`
                // spoolId branch.
                try {
                  const progressPrefix = `s:progress:${agentId}:`
                  const dropped = inboundSpool?.dropMatching((id) => id.startsWith(progressPrefix)) ?? 0
                  if (dropped > 0) {
                    process.stderr.write(
                      `telegram gateway: subagent-handback ${agentId} swept ${dropped} live progress envelope(s) from spool\n`,
                    )
                  }
                } catch (err) {
                  process.stderr.write(
                    `telegram gateway: subagent-handback ${agentId} progress-sweep error: ${(err as Error).message}\n`,
                  )
                }

                // Deliver via pendingInboundBuffer + the idle-drain tick.
                // The drain only releases at an idle prompt (no active
                // turn), so the handback always lands as a clean fresh
                // turn and never races a turn-in-flight composer (#1556).
                pendingInboundBuffer.push(process.env.SWITCHROOM_AGENT_NAME ?? '', decision.inbound)
                process.stderr.write(
                  `telegram gateway: subagent-handback queued agent=${agentId} outcome=${outcome} chat=${decision.chatId} resultChars=${resultText.length}\n`,
                )
              },
              // conversational-pacing beat 3 — mid-flight progress for
              // background workers (#1720). Fires on every
              // `sub_agent_text` event; the pure `decideSubagentProgress`
              // gates on (a) background flag, (b) bucket-not-yet-fired
              // (deterministic `floor(elapsed / interval)`), (c) chat
              // resolves. Envelope spoolId is
              // `s:progress:<jsonl_agent_id>:<bucketIdx>` so a re-fire
              // within the same bucket — or across a gateway restart —
              // collapses to one live entry. TTL on `meta.expiresAt`
              // suppresses stale-after-restart delivery (a 4-h-old
              // "still working (5m)" would be a lie). Sweep on handback
              // lives in the `onFinish` block just above.
              onProgress: ({ agentId, description, latestSummary, elapsedMs, prevBucketIdx, setBucketIdx, lastTool, toolCount, progressLine }) => {
                let fleetChatId = ''
                try {
                  const fleets = progressDriver?.peekAllFleets() ?? []
                  for (const f of fleets) {
                    if (f.fleet.has(agentId)) {
                      fleetChatId = f.chatId ?? ''
                      break
                    }
                  }
                } catch { /* peek failures non-fatal */ }
                // The watcher's `description` is its 'sub-agent' default (it
                // never reassigns it from the worker jsonl). The dispatch-time
                // task description lives in the registry row — resolveWorkerFeedDispatch
                // prefers it so the header reads "🛠 Worker · <real task>" not
                // "· sub-agent" (worker-feed-dispatch.ts, pinned by its test).
                let dispatch: WorkerFeedDispatch = resolveWorkerFeedDispatch(null, description)
                if (turnsDb != null) {
                  try {
                    dispatch = resolveWorkerFeedDispatch(getSubagentByJsonlId(turnsDb, agentId), description)
                  } catch { /* best-effort */ }
                }
                // A NESTED (depth-2+) worker surfaces via the worker feed
                // regardless of its own background flag: its "parent" is a
                // worker, not the gateway's live turn, so nesting it into
                // `currentTurn` would attribute it to an unrelated turn.
                const isBackground = dispatch.isBackground || dispatch.isNested
                // The live step line for THIS tick: the friendly tool label on
                // tool ticks, else the narrative. Previously the worker feed
                // was fed ONLY `latestSummary` (prose), so a tools-only worker
                // — the common case — had a card that heartbeat-edited but
                // never grew past "starting…" (the frozen-card symptom). The
                // foreground nest path below already used this precedence.
                const stepLine = (progressLine != null && progressLine.length > 0) ? progressLine : latestSummary
                if (!isBackground) {
                  // Model A — a foreground sub-agent runs inside the parent's
                  // turn, so its live narrative nests under the parent's
                  // activity draft rather than a separate worker message. Pure
                  // jsonl-tail → render (no model call), inside the
                  // subscription-honest boundary.
                  //
                  // But a foreground sub-agent with NO live turn to nest into
                  // (dispatched outside a turn, or the turn ended while it kept
                  // running — extended autonomous work) has nowhere to nest, and
                  // pre-fix it silently returned here → invisible. Route through
                  // the proven decision: an orphaned foreground sub-agent goes to
                  // the worker feed (owner-DM fallback), not into the void.
                  const surface = resolveSubagentStatusSurface({
                    isBackground: false,
                    // A ROW-LESS worker must not nest into the live turn: with
                    // no registry row we cannot know it belongs to this turn
                    // (it is most often a nested dispatch whose row hasn't
                    // linked yet), and polluting the parent's card misroutes
                    // it. Route it via the orphan worker-feed path instead —
                    // once the row links (watcher retry, ≤ a poll tick) the
                    // classification self-corrects.
                    liveTurnPresent: currentTurn != null && dispatch.hasRow,
                    workerFeedEnabled,
                    orphanStatusEnabled,
                  })
                  if (surface === 'worker-feed') {
                    const origin = resolveSubagentOriginChat(agentId)
                    const wkChat = origin?.chatId || fleetChatId || (loadAccess().allowFrom[0] ?? '')
                    void workerActivityFeed?.update(
                      agentId,
                      wkChat,
                      {
                        description: dispatch.feedDescription,
                        lastTool,
                        toolCount,
                        latestSummary: stepLine,
                        elapsedMs,
                        state: 'running',
                      },
                      origin?.threadId,
                    )?.then(() => reconcileWorkerPin(agentId, wkChat, true))
                    return
                  }
                  if (surface !== 'nest') return // 'skip' — orphan-status off
                  const turn = currentTurn
                  if (turn == null) return // defensive: 'nest' implies a live turn
                  // Render regardless of `replyCalled` — a foreground Task
                  // blocks the parent, so any reply seen while it runs is an
                  // interim ack, never the final answer. Gating on replyCalled
                  // (pre-#2032) made ack-first turns show zero live foreground
                  // activity. Kill-switch lives in the predicate.
                  if (!shouldRenderForegroundProgress({
                    nestingEnabled: foregroundNestingEnabled,
                    replyCalled: turn.replyCalled,
                  })) return
                  // Prefer the tick's own display line: `progressLine` (a
                  // friendly tool-step label) on tool ticks, else the
                  // worker's narrative (`latestSummary`) on text ticks. This
                  // lets a foreground sub-agent that runs tools without
                  // emitting prose still nest its steps under the parent
                  // feed (the foreground blindspot) — mirroring the
                  // main-turn activity feed, which surfaces both tool labels
                  // and prose.
                  // Route through the SHARED clipNarrative so multi-line
                  // narration first-line-collapses identically to the main
                  // tier (the main path at showNarrativeStep already does
                  // this). Previously this inlined `.trim().slice(0, 120)`
                  // omitted the first-line collapse, so a multi-line
                  // narrative rendered DIFFERENTLY here than on the main feed.
                  const child = clipNarrative(progressLine ?? latestSummary)
                  if (child.length === 0) return
                  let narrative = turn.foregroundSubAgents.get(agentId)
                  if (narrative == null) {
                    narrative = []
                    turn.foregroundSubAgents.set(agentId, narrative)
                  }
                  // Dedup within the whole rolling window (mirrors the worker
                  // feed's accumulateNarrative): the watcher re-emits the same
                  // narrative across ticks, and a preamble + its tool label can
                  // repeat non-adjacently (A,B,A) — both must collapse to one
                  // ordered step.
                  if (!narrative.includes(child)) {
                    narrative.push(child)
                    if (narrative.length > FOREGROUND_SUBAGENT_ACCUM_MAX) {
                      narrative.splice(0, narrative.length - FOREGROUND_SUBAGENT_ACCUM_MAX)
                    }
                  }
                  const rendered = composeTurnActivity(turn)
                  if (rendered != null) {
                    turn.activityPendingRender = rendered
                    // PR-4a: routed through the emission-authority façade (no-op
                    // delegate). Producer made explicit ('tool' — the drain
                    // default this foreground sub-agent render used).
                    const ea = emissionAuthorityFor(turn)
                    // PR-4d: route through the centralized card-drain gate.
                    cardDrainGate(turn, ea, () => {
                    if (ea.mayDrain(turn)) {
                      ea.openOrEditCard('tool', () => {
                        turn.activityInFlight = drainActivitySummary(turn, 'tool')
                      })
                    }
                    })
                    // A foreground sub-agent's nested activity IS user-visible
                    // production — count it so the silence-poke clock resets,
                    // exactly like the parent activity-render path (10665). Without
                    // this, a long tools-only foreground sub-agent (no prose) lets
                    // the 300s framework fallback (and the #2527 mid-turn floor)
                    // measure silence against a turn that is visibly working,
                    // risking a premature tear-down / unwanted liveness beat.
                    // PR-4e — keyed liveness under the flag (a foreground
                    // sub-agent's nested render for topic A is A's production).
                    // Flag-OFF keeps the literal `currentTurn === turn`; flag-ON
                    // resolves A by its own key.
                    if (
                      SILENCE_LIVENESS_PRODUCTION &&
                      (EMISSION_AUTHORITY_ENABLED ? turnLiveForItsTopic(turn) : currentTurn === turn)
                    ) {
                      silencePoke.noteProduction(statusKey(turn.sessionChatId, turn.sessionThreadId), Date.now())
                    }
                  }
                  return
                }

                // Fix 2 (post-answer background-agent liveness): when the
                // watcher surfaces a new step for a background worker, update
                // the current turn's `subagentActivityAt` timestamp IF the turn
                // has already delivered its substantive answer. This signal is
                // written HERE — NOT in the tool_label path — so the drop-guard
                // (`shouldReopenFeedAfterAck` / finalAnswerSubstantive) cannot
                // gate it. `feedHeartbeatTick`'s post-answer branch reads
                // `subagentActivityAt` (not `lastToolLabelAt`, which is frozen
                // after the answer) to decide whether to open a liveness card.
                // Only stamp when the turn is alive AND post-answer: pre-answer
                // activity is already surfaced by the normal tool-label feed.
                //
                // SCOPE — this is the IN-TURN-WINDOW surface only. The
                // `feedHeartbeatTick` post-answer card is driven off `currentTurn`,
                // which `endCurrentTurnAtomic` nulls at `turn_end`. A genuinely
                // DECOUPLED background worker keeps running PAST the parent
                // turn's teardown, so `currentTurn` is null when its later
                // onProgress ticks arrive → this stamp is inert and the
                // heartbeat is silent for that worker. That is BY DESIGN, not a
                // gap: a decoupled worker's ongoing activity is surfaced by the
                // dedicated, currentTurn-independent `workerActivityFeed` (the
                // edit-in-place worker message, driven below at `workerFeedEnabled`
                // and bounded by its own non-running/`finish` teardown). So the
                // currentTurn card covers the brief post-answer/pre-teardown
                // window; the worker feed covers everything after teardown. Both
                // are proven in telegram-activity-visibility-integration.test.ts.
                const stampTurn = currentTurn
                if (stampTurn != null && stampTurn.finalAnswerEverDelivered) {
                  stampTurn.subagentActivityAt = Date.now()
                }

                // #PR2 live worker-feed: when ON, the worker's live chat
                // message owns the progress beat. Push a running cue and
                // return BEFORE the legacy bucket relay so the same activity
                // isn't double-surfaced (in-message edit + injected
                // "still working" inbound turn). Route to the conversation
                // the Task was dispatched from (group / forum topic) via the
                // parent turn; fall back to the owner DM when that can't be
                // resolved (the pinned-card fleet that used to carry the chat
                // is gone — see resolveSubagentOriginChat).
                if (workerFeedEnabled) {
                  const origin = resolveSubagentOriginChat(agentId)
                  const wkChat = origin?.chatId || fleetChatId || (loadAccess().allowFrom[0] ?? '')
                  void workerActivityFeed?.update(
                    agentId,
                    wkChat,
                    {
                      description: dispatch.feedDescription,
                      lastTool,
                      toolCount,
                      // The tick's step line (tool label on tool ticks, prose
                      // on text ticks) — NOT bare latestSummary, which starved
                      // tools-only workers of steps (frozen "starting…").
                      latestSummary: stepLine,
                      elapsedMs,
                      state: 'running',
                    },
                    origin?.threadId,
                  )?.then(() => reconcileWorkerPin(agentId, wkChat, true))
                  return
                }

                const progressOrigin = resolveSubagentOriginChat(agentId)
                const decision = decideSubagentProgress({
                  disableEnvValue: process.env.SWITCHROOM_DISABLE_SUBAGENT_PROGRESS,
                  isBackground,
                  // Prefer the conversation the Task was dispatched from over
                  // the owner DM (see resolveSubagentOriginChat).
                  fleetChatId: progressOrigin?.chatId || fleetChatId,
                  // Carry the dispatching topic so the progress wake lands in
                  // it (applied only when the origin chat resolved).
                  ...(progressOrigin?.threadId != null
                    ? { originThreadId: progressOrigin.threadId }
                    : {}),
                  ownerChatId: loadAccess().allowFrom[0] ?? '',
                  subagentJsonlId: agentId,
                  taskDescription: description,
                  latestSummary,
                  elapsedMs,
                  progressIntervalMs: DEFAULT_PROGRESS_INTERVAL_MS,
                  lastBucketIdx: prevBucketIdx,
                })
                if (!decision.deliver) return

                setBucketIdx(decision.bucketIdx)
                pendingInboundBuffer.push(process.env.SWITCHROOM_AGENT_NAME ?? '', decision.inbound)
                // #1725 follow-up: yield the cross-turn ambient ticker
                // for this chat. With the progress envelope queued, the
                // model is about to compose an explicit in-voice
                // progress line — letting the "— still working (Nm)"
                // edit fire in parallel would double-surface the
                // signal. Key the clear on the topic the envelope lands
                // in (origin thread) so the right lane is yielded in a
                // supergroup; chat-level for DM-shaped agents.
                pendingProgress.clearPending(
                  statusKey(decision.chatId, progressOrigin?.threadId),
                  'progress',
                )
                process.stderr.write(
                  `telegram gateway: subagent-progress queued agent=${agentId} bucket=${decision.bucketIdx} elapsed_ms=${elapsedMs} chat=${decision.chatId}\n`,
                )
              },
            })
            process.stderr.write('telegram gateway: subagent-watcher active\n')
          }
        }
      }

      // Lane state (post flash-decouple): VISIBLE only when the visible flag is
      // Lane state from the single-source-of-truth resolver: 'visible' (preview
      // Lane state: 'visible' (opt-in preview) or 'dormant' (default: reply
      // tool is the only message). The draft transport is permanently retired.
      process.stderr.write(`telegram gateway: answer-stream lane=${ANSWER_LANE.state} visible=${ANSWER_STREAM_VISIBLE_ENABLED} grammy=${GRAMMY_VERSION}\n`)
      process.stderr.write(`telegram gateway: starting bot polling pid=${process.pid} agent=${process.env.SWITCHROOM_AGENT_NAME ?? '-'} stateDir=${STATE_DIR} historyEnabled=${HISTORY_ENABLED} streamMode=${process.env.SWITCHROOM_TG_STREAM_MODE ?? 'checklist'}\n`)
      runnerHandle = run(bot, {
        runner: {
          fetch: {
            // message_reaction and message_reaction_count are opt-in —
            // Telegram only delivers them when explicitly requested.
            // message_reaction_count (anonymous group reaction tallies) is
            // listed here for completeness but we don't handle it (out of scope).
            allowed_updates: [
              'message', 'edited_message', 'channel_post', 'edited_channel_post',
              'callback_query', 'inline_query', 'chosen_inline_result',
              'shipping_query', 'pre_checkout_query', 'poll', 'poll_answer',
              'my_chat_member', 'chat_member', 'chat_join_request',
              'message_reaction', 'message_reaction_count',
            ],
          },
        },
      })
      // Start the long-poll health-check now that the runner is up.
      // Stop first in case we're re-entering the loop after a stall recovery.
      pollHealthCheck?.stop()
      pollHealthCheck?.start()
      await runnerHandle.task()
      // task() resolves only on clean shutdown (shutdown-drain stops the
      // runner) — exit the startup IIFE. Stall recovery no longer routes here:
      // onStall exits the process and the supervisor restarts the gateway
      // (see recoverFromPollStall). The 409 path below re-runs in place.
      return
    } catch (err) {
      if (err instanceof GrammyError && err.error_code === 409) {
        const delay = Math.min(1000 * attempt, 15000)
        const agentName = process.env.SWITCHROOM_AGENT_NAME ?? '-'
        // Two log lines so journalctl has both the WHY (detected) and
        // the WHEN (scheduled). The architectural fix (startup mutex
        // + 35s SIGTERM drain) should eliminate the OLD-process race
        // entirely — if these still appear together with the OLD pid
        // alive, the mutex isn't being honoured and we need to look
        // harder. Keep both lines so the next incident has signal.
        process.stderr.write(
          `telegram gateway: poll.409.detected attempt=${attempt} retry_in_ms=${delay} agent=${agentName}\n`,
        )
        process.stderr.write(
          `telegram gateway: poll.retry_scheduled reason=409 attempt=${attempt} delay_ms=${delay} agent=${agentName}\n`,
        )
        // Legacy line preserved so older grep patterns keep working.
        process.stderr.write(`telegram gateway: 409 Conflict, retrying in ${delay / 1000}s\n`)
        await new Promise(r => setTimeout(r, delay))
        continue
      }
      if (err instanceof Error && err.message === 'Aborted delay') return
      process.stderr.write(`telegram gateway: polling failed: ${err}\n`)
      // Exit non-zero so systemd's Restart=always re-runs the unit instead of
      // leaving a live-but-silent process that never polls. Previously this path
      // just `return`ed — that IS the bug from 2026-04-29 where all 5 gateways
      // stayed alive but deaf after a boot-time network failure.
      // Note: network errors at startup are handled earlier by gatewayStartupRetry
      // (with bounded retries before the exit); reaching here means either a
      // non-network fatal error, or an unexpected mid-session failure. Either
      // way, exiting is safer than silently staying alive with polling stopped.
      process.exit(1)
    }
  }
})()
